const SHELL_EXEC_TRUNCATE_BYTES: usize = 131_072; // 128 KB

fn mcp_schema_codex_context() -> bool {
    let client = std::env::var("AGENT_BRIDGE_CLIENT").ok();
    let toolset = std::env::var("AGENT_BRIDGE_TOOLSET").ok();
    let codex_host = std::env::var("AGENT_BRIDGE_CODEX_HOST").ok();

    client
        .as_deref()
        .map(normalize_tool_policy_value)
        .is_some_and(|v| v.starts_with("codex"))
        || toolset
            .as_deref()
            .map(normalize_tool_policy_value)
            .is_some_and(|v| v.starts_with("codex"))
        || codex_host.as_deref().is_some_and(|v| !v.trim().is_empty())
}

fn append_codex_native_hint(base: &str, codex_note: &str, codex_context: bool) -> String {
    if codex_context {
        format!("{base} Codex note: {codex_note}")
    } else {
        base.to_string()
    }
}

fn mcp_schema_description(base: &str, codex_note: &str) -> String {
    append_codex_native_hint(base, codex_note, mcp_schema_codex_context())
}

fn compact_mcp_output_default() -> bool {
    let policy = ToolPolicy::from_env();
    compact_mcp_output_default_for_policy(policy)
}

fn compact_mcp_output_default_for_policy(policy: ToolPolicy) -> bool {
    matches!(
        policy.set,
        ToolSet::CodexEssential
            | ToolSet::CodexEssentialMobileProjection
            | ToolSet::CodexLean
            | ToolSet::CodexA2ui
            | ToolSet::ChatGptRead
            | ToolSet::ChatGptCollab
    ) || matches!(policy.profile(), ToolProfile::Compact)
}

const FORUM_READ_DEFAULT_LIMIT: u32 = 50;
const FORUM_READ_COMPACT_DEFAULT_LIMIT: u32 = 8;

pub(crate) fn truncate_chars(s: &str, max_chars: usize) -> (String, bool, usize) {
    let total = s.chars().count();
    if max_chars == 0 || total <= max_chars {
        (s.to_string(), false, total)
    } else {
        let mut out: String = s.chars().take(max_chars).collect();
        out.push('…');
        (out, true, total)
    }
}

pub(crate) fn project_forum_posts(
    posts: &[ForumPostRecord],
    body_max_chars: usize,
    include_refs: bool,
) -> (Vec<Value>, usize) {
    let mut truncated = 0usize;
    let out = posts
        .iter()
        .map(|post| {
            let (body, body_truncated, body_total_chars) =
                truncate_chars(&post.body, body_max_chars);
            if body_truncated {
                truncated += 1;
            }
            let mut obj = Map::new();
            obj.insert("id".to_string(), json!(post.id));
            obj.insert("thread_id".to_string(), json!(post.thread_id));
            obj.insert("author".to_string(), json!(post.author));
            obj.insert("kind".to_string(), json!(post.kind));
            obj.insert("body".to_string(), json!(body));
            if body_truncated {
                obj.insert("body_truncated".to_string(), json!(true));
                obj.insert("body_total_chars".to_string(), json!(body_total_chars));
            }
            if include_refs {
                obj.insert("refs".to_string(), post.refs.clone());
            } else if !post.refs.is_null() {
                obj.insert("refs_omitted".to_string(), json!(true));
            }
            obj.insert("created_at".to_string(), json!(post.created_at));
            Value::Object(obj)
        })
        .collect();
    (out, truncated)
}

fn capabilities_summary(capabilities: &Value) -> Value {
    let Some(obj) = capabilities.as_object() else {
        return json!({"type": capabilities_type_label(capabilities)});
    };
    let mut keys: Vec<&str> = obj.keys().map(|s| s.as_str()).collect();
    keys.sort_unstable();
    let mut out = Map::new();
    out.insert("keys".to_string(), json!(keys));
    if let Some(avatar) = obj.get("avatar_state").and_then(|v| v.as_object()) {
        let mut compact = Map::new();
        for key in [
            "mode",
            "activity_state",
            "focus",
            "next_action",
            "risk_level",
            "updated_at",
            "source",
        ] {
            if let Some(v) = avatar.get(key) {
                compact.insert(key.to_string(), v.clone());
            }
        }
        if let Some(policy) = avatar.get("voice_policy").and_then(|v| v.as_object()) {
            if let Some(default_silent) = policy.get("default_silent") {
                compact.insert("voice_default_silent".to_string(), default_silent.clone());
            }
        }
        if !compact.is_empty() {
            out.insert("avatar_state".to_string(), Value::Object(compact));
        }
    }
    if let Some(pet) = obj.get("pet_state").and_then(|v| v.as_object()) {
        let mut compact = Map::new();
        for key in [
            "mode",
            "activity_state",
            "focus",
            "next_action",
            "risk_level",
        ] {
            if let Some(v) = pet.get(key) {
                compact.insert(key.to_string(), v.clone());
            }
        }
        if !compact.is_empty() {
            out.insert("pet_state".to_string(), Value::Object(compact));
        }
    }
    Value::Object(out)
}

fn capabilities_type_label(v: &Value) -> &'static str {
    match v {
        Value::Null => "null",
        Value::Bool(_) => "bool",
        Value::Number(_) => "number",
        Value::String(_) => "string",
        Value::Array(_) => "array",
        Value::Object(_) => "object",
    }
}

fn project_agent_presence_rows(
    rows: &[AgentPresenceRecord],
    include_capabilities: bool,
    include_skills: bool,
) -> (Vec<Value>, usize, usize) {
    let mut capabilities_omitted = 0usize;
    let mut skills_omitted = 0usize;
    let out = rows
        .iter()
        .map(|row| {
            let mut obj = Map::new();
            obj.insert("session_id".to_string(), json!(row.session_id));
            obj.insert("name".to_string(), json!(row.name));
            if let Some(v) = &row.description {
                obj.insert("description".to_string(), json!(v));
            }
            if let Some(v) = &row.version {
                obj.insert("version".to_string(), json!(v));
            }
            if let Some(v) = &row.url {
                obj.insert("url".to_string(), json!(v));
            }
            if include_capabilities {
                if let Some(v) = &row.capabilities {
                    obj.insert("capabilities".to_string(), v.clone());
                }
            } else if let Some(v) = &row.capabilities {
                capabilities_omitted += 1;
                obj.insert("capabilities_omitted".to_string(), json!(true));
                obj.insert("capabilities_summary".to_string(), capabilities_summary(v));
            }
            if include_skills {
                if let Some(v) = &row.skills {
                    obj.insert("skills".to_string(), v.clone());
                }
            } else if row.skills.is_some() {
                skills_omitted += 1;
                obj.insert("skills_omitted".to_string(), json!(true));
            }
            obj.insert("node".to_string(), json!(row.node));
            obj.insert("project".to_string(), json!(row.project));
            obj.insert("role".to_string(), json!(row.role));
            if let Some(v) = &row.tag {
                obj.insert("tag".to_string(), json!(v));
            }
            if let Some(v) = &row.cwd {
                obj.insert("cwd".to_string(), json!(v));
            }
            if let Some(v) = row.pid {
                obj.insert("pid".to_string(), json!(v));
            }
            obj.insert("started_at".to_string(), json!(row.started_at));
            obj.insert(
                "last_heartbeat_at".to_string(),
                json!(row.last_heartbeat_at),
            );
            Value::Object(obj)
        })
        .collect();
    (out, capabilities_omitted, skills_omitted)
}

pub struct ShellExecTool {
    hub: Hub,
}

impl ShellExecTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for ShellExecTool {
    fn name(&self) -> &'static str {
        "shell_exec"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: mcp_schema_description(
                "Run a shell command synchronously; returns exit code, stdout, \
                 stderr, wall-clock duration. Unlike terminal_send_keys this captures \
                 output directly; no PTY needed. stdout/stderr truncated at 128 KB. \
                 Default timeout 30 s, max 300 s.",
                "Prefer Codex native shell/exec tools for ordinary local commands; use \
                 this Agent-Bridge tool only when you need MCP-level execution, dispatch \
                 telemetry, or Agent-Bridge security/env limits.",
            ),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "cmd": {
                        "type": "string",
                        "description": "Shell command to run (executed via sh -c)."
                    },
                    "cwd": {
                        "type": "string",
                        "description": "Working directory. Defaults to the agent-bridge process cwd."
                    },
                    "timeout_ms": {
                        "type": "integer",
                        "minimum": 1000,
                        "maximum": 300000,
                        "default": 30000,
                        "description": "Milliseconds before the process is killed."
                    },
                    "env": {
                        "type": "object",
                        "description": "Extra environment variables to inject (string keys + values).",
                        "additionalProperties": { "type": "string" }
                    }
                },
                "required": ["cmd"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        if let Err(e) = self.hub.security.check(Cap::ShellExec) {
            return Ok(ToolResult::error(e));
        }
        let cmd = match args.get("cmd").and_then(|v| v.as_str()) {
            Some(s) if !s.is_empty() => s.to_string(),
            _ => return Ok(ToolResult::error("missing or empty 'cmd'")),
        };
        let timeout_max = self.hub.security.shell_exec_timeout_max_ms;
        let timeout_ms = args
            .get("timeout_ms")
            .and_then(|v| v.as_u64())
            .unwrap_or(30_000)
            .clamp(1_000, timeout_max);

        let mut child = {
            let mut builder = killable_command("sh");
            builder.arg("-c").arg(&cmd);
            builder.stdout(std::process::Stdio::piped());
            builder.stderr(std::process::Stdio::piped());
            if let Some(cwd) = args.get("cwd").and_then(|v| v.as_str()) {
                builder.current_dir(cwd);
            }
            if let Some(env_map) = args.get("env").and_then(|v| v.as_object()) {
                for (k, v) in env_map {
                    if let Some(val) = v.as_str() {
                        builder.env(k, val);
                    }
                }
            }
            match builder.spawn() {
                Ok(c) => c,
                Err(e) => return Ok(ToolResult::error(format!("spawn failed: {e}"))),
            }
        };

        let started = Instant::now();
        let deadline = Duration::from_millis(timeout_ms);

        // Drain stdout + stderr in background tasks so the process doesn't block on full pipes.
        use tokio::io::AsyncReadExt as _;
        let mut stdout_pipe = child.stdout.take().expect("stdout piped");
        let mut stderr_pipe = child.stderr.take().expect("stderr piped");
        let stdout_task = tokio::spawn(async move {
            let mut buf = Vec::new();
            let _ = stdout_pipe.read_to_end(&mut buf).await;
            buf
        });
        let stderr_task = tokio::spawn(async move {
            let mut buf = Vec::new();
            let _ = stderr_pipe.read_to_end(&mut buf).await;
            buf
        });

        let timed_out = tokio::time::timeout(deadline, child.wait()).await;
        let duration_ms = started.elapsed().as_millis() as u64;

        let exit_code = match timed_out {
            Err(_) => {
                child.start_kill().ok();
                stdout_task.abort();
                stderr_task.abort();
                return Ok(ToolResult::json_text(&json!({
                    "exit_code": -1,
                    "stdout": "",
                    "stderr": format!("killed after {timeout_ms} ms timeout"),
                    "duration_ms": duration_ms,
                    "truncated": false
                })));
            }
            Ok(Err(e)) => return Ok(ToolResult::error(format!("wait failed: {e}"))),
            Ok(Ok(status)) => status.code().unwrap_or(-1),
        };

        let stdout_bytes = stdout_task.await.unwrap_or_default();
        let stderr_bytes = stderr_task.await.unwrap_or_default();
        let (stdout_str, stdout_truncated) = lossy_truncate(&stdout_bytes);
        let (stderr_str, stderr_truncated) = lossy_truncate(&stderr_bytes);

        Ok(ToolResult::json_text(&json!({
            "exit_code": exit_code,
            "stdout": stdout_str,
            "stderr": stderr_str,
            "duration_ms": duration_ms,
            "truncated": stdout_truncated || stderr_truncated
        })))
    }
}

fn lossy_truncate(bytes: &[u8]) -> (String, bool) {
    if bytes.len() <= SHELL_EXEC_TRUNCATE_BYTES {
        (String::from_utf8_lossy(bytes).into_owned(), false)
    } else {
        let s = String::from_utf8_lossy(&bytes[..SHELL_EXEC_TRUNCATE_BYTES]).into_owned();
        (
            format!(
                "{s}\n[... truncated at {} KB]",
                SHELL_EXEC_TRUNCATE_BYTES / 1024
            ),
            true,
        )
    }
}

