const DESKTOP_SNAPSHOT_SEMANTIC_SCHEMA: &str = "agent_bridge.semantic_bus.desktop_snapshot.v0";
const DESKTOP_SNAPSHOT_SOURCE_SCHEMA: &str = "desktop_snapshot/v0.5";

pub struct DesktopSnapshotTool {
    _hub: Hub,
}

impl DesktopSnapshotTool {
    pub fn new(hub: Hub) -> Self {
        Self { _hub: hub }
    }
}

#[async_trait]
impl McpTool for DesktopSnapshotTool {
    fn name(&self) -> &'static str {
        "desktop_snapshot"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Read-only Linux desktop structure snapshot. Wraps \
                 scripts/desktop_snapshot.py and returns sway outputs/windows plus optional \
                 AT-SPI semantics. It does not click, type, move windows, or expose \
                 --activate-a11y; screenshots are opt-in to avoid surprise file writes."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "cwd": {
                        "type": "string",
                        "description": "Workspace/repo root used to resolve scripts/desktop_snapshot.py. Defaults to the MCP process cwd, then the build-time repo root."
                    },
                    "script_path": {
                        "type": "string",
                        "description": "Optional explicit desktop_snapshot.py path. Use mainly for tests or alternate checkouts."
                    },
                    "include_screenshot": {
                        "type": "boolean",
                        "default": false,
                        "description": "When true, allow grim to write per-output PNG files. Default false keeps the MCP call non-mutating except process execution."
                    },
                    "screenshot_dir": {
                        "type": "string",
                        "description": "Directory for PNG screenshots when include_screenshot=true."
                    },
                    "include_atspi": {
                        "type": "boolean",
                        "default": true,
                        "description": "Collect AT-SPI semantic elements when available. This does not enable global a11y."
                    },
                    "max_elements": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 1000,
                        "default": 120,
                        "description": "Cap AT-SPI elements per app."
                    },
                    "atspi_budget": {
                        "type": "number",
                        "minimum": 0.25,
                        "maximum": 10.0,
                        "default": 2.0,
                        "description": "Per-app AT-SPI traversal budget in seconds."
                    },
                    "timeout_ms": {
                        "type": "integer",
                        "minimum": 1000,
                        "maximum": 60000,
                        "default": 15000,
                        "description": "Milliseconds before the snapshot process is killed."
                    },
                    "semantic_bus": {
                        "type": "boolean",
                        "default": false,
                        "description": "When true, wrap the read-only desktop_snapshot/v0.5 payload as agent_bridge.semantic_bus.desktop_snapshot.v0. Default false preserves the existing payload exactly apart from mcp_wrapper."
                    },
                    "semantic_include_raw": {
                        "type": "boolean",
                        "default": false,
                        "description": "Only with semantic_bus=true: include the original desktop_snapshot payload as raw_snapshot. Default false keeps the semantic envelope compact."
                    },
                    "semantic_max_age_ms": {
                        "type": "integer", "minimum": 100, "maximum": 300000, "default": 5000,
                        "description": "Only with semantic_bus=true: freshness budget attached to this observation. Consumers should re-observe after this many milliseconds."
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let timeout_ms = args
            .get("timeout_ms")
            .and_then(|v| v.as_u64())
            .unwrap_or(15_000)
            .clamp(1_000, 60_000);
        let include_screenshot = args
            .get("include_screenshot")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let include_atspi = args
            .get("include_atspi")
            .and_then(|v| v.as_bool())
            .unwrap_or(true);
        let max_elements = args
            .get("max_elements")
            .and_then(|v| v.as_u64())
            .unwrap_or(120)
            .clamp(1, 1000);
        let atspi_budget = args
            .get("atspi_budget")
            .and_then(|v| v.as_f64())
            .unwrap_or(2.0)
            .clamp(0.25, 10.0);
        let semantic_bus = args
            .get("semantic_bus")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let semantic_include_raw = args
            .get("semantic_include_raw")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let semantic_max_age_ms = args
            .get("semantic_max_age_ms")
            .and_then(Value::as_u64)
            .unwrap_or(5_000)
            .clamp(100, 300_000);

        let cwd = args.get("cwd").and_then(|v| v.as_str()).map(PathBuf::from);
        let script = desktop_snapshot_script_path(&args, cwd.as_ref());
        if !script.exists() {
            return Ok(desktop_snapshot_error(json!({
                "code": "script_missing",
                "message": format!("desktop_snapshot.py not found at {}", script.display()),
                "hint": "pass script_path or run from the Agent-Bridge repo root"
            })));
        }

        let mut cmd = killable_command(
            std::env::var("PYTHON")
                .ok()
                .filter(|s| !s.trim().is_empty())
                .unwrap_or_else(|| "python3".to_string()),
        );
        cmd.arg(&script).arg("--compact");
        if !include_screenshot {
            cmd.arg("--no-screenshot");
        } else if let Some(dir) = args.get("screenshot_dir").and_then(|v| v.as_str()) {
            cmd.arg("--screenshot-dir").arg(dir);
        }
        if !include_atspi {
            cmd.arg("--no-atspi");
        }
        cmd.arg("--max-elements").arg(max_elements.to_string());
        cmd.arg("--atspi-budget").arg(atspi_budget.to_string());
        cmd.stdout(std::process::Stdio::piped());
        cmd.stderr(std::process::Stdio::piped());
        if let Some(cwd) = cwd {
            cmd.current_dir(cwd);
        }

        let started = Instant::now();
        let output =
            match tokio::time::timeout(Duration::from_millis(timeout_ms), cmd.output()).await {
                Err(_) => {
                    return Ok(desktop_snapshot_error(json!({
                        "code": "timeout",
                        "message": format!("desktop_snapshot exceeded {timeout_ms} ms"),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Err(e)) => {
                    return Ok(desktop_snapshot_error(json!({
                        "code": "spawn_failed",
                        "message": e.to_string(),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Ok(output)) => output,
            };
        let duration_ms = started.elapsed().as_millis() as u64;
        let (stdout, stdout_truncated) = lossy_truncate(&output.stdout);
        let (stderr, stderr_truncated) = lossy_truncate(&output.stderr);

        if !output.status.success() {
            return Ok(desktop_snapshot_error(json!({
                "code": "script_failed",
                "exit_code": output.status.code().unwrap_or(-1),
                "stderr": stderr,
                "stdout": stdout,
                "duration_ms": duration_ms,
                "truncated": stdout_truncated || stderr_truncated
            })));
        }

        match serde_json::from_str::<Value>(&stdout) {
            Ok(mut payload) => {
                if let Some(obj) = payload.as_object_mut() {
                    obj.insert(
                        "mcp_wrapper".to_string(),
                        json!({
                            "tool": self.name(),
                            "read_only": true,
                            "include_screenshot": include_screenshot,
                            "include_atspi": include_atspi,
                            "duration_ms": duration_ms,
                            "stderr": stderr,
                            "stderr_truncated": stderr_truncated
                        }),
                    );
                }
                if semantic_bus {
                    let semantic_payload = desktop_snapshot_semantic_bus_payload(
                        &payload,
                        semantic_include_raw,
                        semantic_max_age_ms,
                    );
                    Ok(ToolResult::json_text(&semantic_payload))
                } else {
                    Ok(ToolResult::json_text(&payload))
                }
            }
            Err(e) => Ok(desktop_snapshot_error(json!({
                "code": "invalid_json",
                "message": e.to_string(),
                "stdout": stdout,
                "stderr": stderr,
                "duration_ms": duration_ms,
                "truncated": stdout_truncated || stderr_truncated
            }))),
        }
    }
}

fn desktop_snapshot_semantic_bus_payload(
    snapshot: &Value,
    include_raw: bool,
    max_age_ms: u64,
) -> Value {
    let source_schema = snapshot
        .get("schema")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let captured_at = snapshot.get("captured_at").cloned().unwrap_or(Value::Null);
    let captured_label = desktop_snapshot_value_label(&captured_at, "unknown");
    let captured_unix_seconds = captured_at.as_u64();
    let returned_unix_ms = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis() as u64;
    let captured_unix_ms = captured_unix_seconds.and_then(|seconds| seconds.checked_mul(1_000));
    let age_ms = captured_unix_ms
        .filter(|captured| *captured <= returned_unix_ms)
        .map(|captured| returned_unix_ms - captured);
    let fresh_at_return = age_ms.is_some_and(|age| age <= max_age_ms);
    let source_content_sha256 = desktop_snapshot_source_content_sha256(snapshot);
    let observation_id = format!("obs-desktop-linux-{}", &source_content_sha256[..16]);
    let session_object_id = format!("desktop:linux:session:{captured_label}");
    let event_id = format!("evt-desktop-snapshot-{captured_label}");
    let verified = source_schema == DESKTOP_SNAPSHOT_SOURCE_SCHEMA;
    let reason = if verified {
        Value::Null
    } else {
        json!("unexpected_source_schema")
    };

    let windows = snapshot
        .get("windows")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let mut semantic_objects = Vec::new();
    let mut affordances = Vec::new();
    let mut window_ids_by_pid: HashMap<String, String> = HashMap::new();

    semantic_objects.push(json!({
        "schema": "agent_bridge.semantic_bus.object.v0",
        "object_id": session_object_id,
        "object_type": "desktop.session",
        "source_adapter": "linux.sway.session",
        "label": "Linux desktop session",
        "state": {
            "session": snapshot.get("session").cloned().unwrap_or_else(|| json!({})),
            "window_count": snapshot.get("window_count").cloned().unwrap_or(Value::Null),
            "screenshots": snapshot.get("screenshots").cloned().unwrap_or(Value::Null),
        },
        "relations": [],
        "confidence": if verified { 0.95 } else { 0.25 },
        "observed_at": captured_at,
        "provenance": {
            "tool": "desktop_snapshot",
            "schema": source_schema,
        }
    }));

    for (idx, window) in windows.iter().enumerate() {
        if window.get("error").is_some() {
            continue;
        }
        let object_id = desktop_snapshot_window_object_id(window, idx);
        if let Some(pid) = window.get("pid").and_then(Value::as_i64) {
            window_ids_by_pid.insert(pid.to_string(), object_id.clone());
        }
        let title = desktop_snapshot_str(window, "name").unwrap_or("window");
        semantic_objects.push(json!({
            "schema": "agent_bridge.semantic_bus.object.v0",
            "object_id": object_id,
            "object_type": "desktop.window",
            "source_adapter": "linux.sway.tree",
            "label": title,
            "state": {
                "id": window.get("id").cloned().unwrap_or(Value::Null),
                "app_id": window.get("app_id").cloned().unwrap_or(Value::Null),
                "x11_class": window.get("x11_class").cloned().unwrap_or(Value::Null),
                "pid": window.get("pid").cloned().unwrap_or(Value::Null),
                "title": window.get("name").cloned().unwrap_or(Value::Null),
                "focused": window.get("focused").cloned().unwrap_or(Value::Null),
                "visible": window.get("visible").cloned().unwrap_or(Value::Null),
                "grounding": window.get("grounding").cloned().unwrap_or(Value::Null),
                "rect": window.get("rect").cloned().unwrap_or(Value::Null),
                "output": window.get("output").cloned().unwrap_or(Value::Null),
            },
            "relations": [
                { "type": "member_of", "target": session_object_id }
            ],
            "confidence": 0.9,
            "observed_at": captured_at,
            "provenance": {
                "tool": "desktop_snapshot",
                "schema": source_schema,
                "source_path": "windows"
            }
        }));
        affordances.push(json!({
            "affordance_id": format!("{object_id}:verify-window"),
            "object_id": object_id,
            "action_type": "desktop.verify",
            "args_schema": {
                "expect": "window_appeared",
                "win_app_id": window.get("app_id").cloned().unwrap_or(Value::Null),
                "win_title": window.get("name").cloned().unwrap_or(Value::Null),
                "win_pid": window.get("pid").cloned().unwrap_or(Value::Null),
            },
            "risk_level": "low",
            "requires_gate": false,
            "expected_effect": "re-observes matching window state without mutating the desktop"
        }));
    }

    if let Some(apps) = snapshot
        .get("atspi")
        .and_then(|v| v.get("apps"))
        .and_then(Value::as_array)
    {
        for app in apps {
            let pid_label = app
                .get("pid")
                .and_then(Value::as_i64)
                .map(|pid| pid.to_string())
                .unwrap_or_else(|| "unknown".to_string());
            let parent_window = window_ids_by_pid.get(&pid_label).cloned();
            if let Some(elements) = app.get("elements").and_then(Value::as_array) {
                for (idx, element) in elements.iter().enumerate() {
                    let role = desktop_snapshot_str(element, "role").unwrap_or("element");
                    let name = desktop_snapshot_str(element, "name").unwrap_or("");
                    let element_slug = desktop_snapshot_slug(&format!("{role}-{name}-{idx}"));
                    let object_id = format!("desktop:linux:atspi:{pid_label}:{}", element_slug);
                    let mut relations = vec![json!({
                        "type": "member_of",
                        "target": session_object_id
                    })];
                    if let Some(parent) = &parent_window {
                        relations.push(json!({
                            "type": "contained_by",
                            "target": parent
                        }));
                    }
                    semantic_objects.push(json!({
                        "schema": "agent_bridge.semantic_bus.object.v0",
                        "object_id": object_id,
                        "object_type": format!("desktop.accessible.{}", desktop_snapshot_slug(role)),
                        "source_adapter": "linux.atspi",
                        "label": if name.is_empty() { role } else { name },
                        "state": {
                            "app": app.get("name").cloned().unwrap_or(Value::Null),
                            "pid": app.get("pid").cloned().unwrap_or(Value::Null),
                            "role": role,
                            "name": element.get("name").cloned().unwrap_or(Value::Null),
                            "bounds": element.get("bounds").cloned().unwrap_or(Value::Null),
                            "states": element.get("states").cloned().unwrap_or(Value::Null),
                        },
                        "relations": relations,
                        "confidence": 0.88,
                        "observed_at": captured_at,
                        "provenance": {
                            "tool": "desktop_snapshot",
                            "schema": source_schema,
                            "source_path": "atspi.apps[].elements[]"
                        }
                    }));
                    affordances.push(json!({
                        "affordance_id": format!("{object_id}:verify-element"),
                        "object_id": object_id,
                        "action_type": "desktop.verify",
                        "args_schema": {
                            "app": app.get("name").cloned().unwrap_or(Value::Null),
                            "role": role,
                            "name": element.get("name").cloned().unwrap_or(Value::Null),
                            "expect": "state_is"
                        },
                        "risk_level": "low",
                        "requires_gate": false,
                        "expected_effect": "re-observes matching AT-SPI element state"
                    }));
                    if desktop_snapshot_role_is_actionable(role) {
                        affordances.push(json!({
                            "affordance_id": format!("{object_id}:invoke"),
                            "object_id": object_id,
                            "action_type": "desktop.invoke",
                            "args_schema": {
                                "app": app.get("name").cloned().unwrap_or(Value::Null),
                                "role": role,
                                "name": element.get("name").cloned().unwrap_or(Value::Null),
                                "observation_ref": {
                                    "observation_id": observation_id,
                                    "content_sha256": source_content_sha256,
                                    "captured_at_unix_ms": captured_unix_ms,
                                    "max_age_ms": max_age_ms
                                }
                            },
                            "risk_level": "medium",
                            "requires_gate": true,
                            "expected_effect": "semantic AT-SPI invoke; exposed here only as gated affordance metadata"
                        }));
                    }
                }
            }
        }
    }

    let object_count = semantic_objects.len();
    let affordance_count = affordances.len();
    let window_count = windows.iter().filter(|w| w.get("error").is_none()).count();
    let atspi_object_count = semantic_objects
        .iter()
        .filter(|o| {
            o.get("source_adapter")
                .and_then(Value::as_str)
                .is_some_and(|s| s == "linux.atspi")
        })
        .count();

    let mut payload = json!({
        "schema": DESKTOP_SNAPSHOT_SEMANTIC_SCHEMA,
        "source_schema": source_schema,
        "source_adapter": "linux.desktop_snapshot",
        "captured_at": captured_at,
        "observation": {
            "schema": "agent_bridge.observation.v0",
            "observation_id": observation_id,
            "revision": captured_unix_seconds,
            "revision_semantics": "source_capture_unix_seconds; ordering hint only; ties are possible",
            "content_hash": {
                "algorithm": "sha256",
                "scope": "source_snapshot_without_mcp_wrapper",
                "value": source_content_sha256
            },
            "freshness": {
                "max_age_ms": max_age_ms,
                "age_ms_at_return": age_ms,
                "fresh_at_return": fresh_at_return,
                "returned_at_unix_ms": returned_unix_ms
            },
            "coordinate_provenance": {
                "windows_rect": {
                    "source_path": "windows[].rect",
                    "coordinate_space": "sway.logical.desktop",
                    "origin": "global_desktop_top_left",
                    "transform": "identity",
                    "output_binding": "windows[].output"
                },
                "atspi_bounds": {
                    "source_path": "atspi.apps[].elements[].bounds",
                    "coordinate_space": "atspi.screen",
                    "origin": "global_screen_top_left",
                    "transform": "none",
                    "mapping_to_sway": "unverified"
                }
            }
        },
        "read_only": true,
        "raw_available": true,
        "raw_included": include_raw,
        "semantic_objects": semantic_objects,
        "affordances": affordances,
        "events": [
            {
                "event_id": event_id,
                "event_type": "desktop.snapshot.observed",
                "subject_id": session_object_id,
                "source": "desktop_snapshot",
                "actor": "agent",
                "payload_json": {
                    "object_count": object_count,
                    "affordance_count": affordance_count,
                    "window_count": window_count,
                    "atspi_object_count": atspi_object_count,
                    "screenshot_required": false
                },
                "source_event_ids": []
            }
        ],
        "verification": {
            "verdict": if verified { "verified" } else { "not_verified" },
            "reason": reason,
            "method": "desktop_snapshot.semantic_normalizer",
            "evidence": {
                "source_schema": source_schema,
                "object_count": object_count,
                "window_count": window_count,
                "atspi_object_count": atspi_object_count,
                "raw_included": include_raw
            },
            "verified_to": if verified { json!("semantic_objects") } else { Value::Null },
            "recover": if verified { "proceed" } else { "replan" },
            "raw_available": true
        },
        "presentation": {
            "presentation_id": format!("present-desktop-snapshot-{captured_label}"),
            "source_event_ids": [event_id],
            "human_summary": format!(
                "Normalized desktop_snapshot into {object_count} semantic objects and {affordance_count} affordances."
            ),
            "machine_payload": {
                "object_count": object_count,
                "affordance_count": affordance_count,
                "window_count": window_count,
                "atspi_object_count": atspi_object_count
            },
            "ingestion": {
                "allowed": false,
                "reason": "runtime_snapshot_not_durable_memory"
            },
            "artifact": Value::Null
        }
    });
    if include_raw {
        if let Some(obj) = payload.as_object_mut() {
            obj.insert("raw_snapshot".to_string(), snapshot.clone());
        }
    }
    payload
}

fn desktop_snapshot_source_content_sha256(snapshot: &Value) -> String {
    let mut source = snapshot.clone();
    if let Some(object) = source.as_object_mut() {
        object.remove("mcp_wrapper");
    }
    let encoded = serde_json::to_vec(&source).expect("serde_json::Value is serializable");
    let mut hasher = Sha256::new();
    hasher.update(encoded);
    format!("{:x}", hasher.finalize())
}

fn desktop_snapshot_str<'a>(value: &'a Value, key: &str) -> Option<&'a str> {
    value
        .get(key)
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|s| !s.is_empty())
}

fn desktop_snapshot_value_label(value: &Value, fallback: &str) -> String {
    match value {
        Value::String(s) => desktop_snapshot_slug(s),
        Value::Number(n) => n.to_string(),
        _ => fallback.to_string(),
    }
}

fn desktop_snapshot_window_object_id(window: &Value, idx: usize) -> String {
    if let Some(id) = window.get("id").and_then(Value::as_i64) {
        return format!("desktop:linux:sway:window:{id}");
    }
    if let Some(pid) = window.get("pid").and_then(Value::as_i64) {
        return format!("desktop:linux:sway:window-pid:{pid}");
    }
    format!("desktop:linux:sway:window-index:{idx}")
}

fn desktop_snapshot_slug(raw: &str) -> String {
    let mut out = String::new();
    let mut last_dash = false;
    for ch in raw.chars() {
        if ch.is_ascii_alphanumeric() {
            out.push(ch.to_ascii_lowercase());
            last_dash = false;
        } else if !last_dash && !out.is_empty() {
            out.push('-');
            last_dash = true;
        }
    }
    while out.ends_with('-') {
        out.pop();
    }
    if out.is_empty() {
        "unknown".to_string()
    } else {
        out
    }
}

fn desktop_snapshot_role_is_actionable(role: &str) -> bool {
    let r = role.to_ascii_lowercase();
    r.contains("button")
        || r.contains("menu item")
        || r.contains("check box")
        || r.contains("radio button")
        || r.contains("combo box")
        || r.contains("slider")
        || r.contains("spin button")
        || r == "link"
}

/// Stable installed fallback for script-backed MCP tools.
///
/// Release binaries are built in disposable git worktrees.  Their compile-time
/// CARGO_MANIFEST_DIR therefore stops existing after a successful deploy.  The
/// deploy helper installs the matching scripts under this user-owned directory,
/// keeping no-cwd MCP calls independent of source/build worktree lifetime.
fn installed_runtime_script_path(file_name: &str) -> Option<PathBuf> {
    let root = std::env::var("AGENT_BRIDGE_RUNTIME_ASSET_DIR")
        .ok()
        .filter(|value| !value.trim().is_empty())
        .map(PathBuf::from)
        .or_else(|| {
            std::env::var("HOME")
                .ok()
                .filter(|value| !value.trim().is_empty())
                .map(|home| PathBuf::from(home).join(".local/lib/agent-bridge/scripts"))
        })?;
    let path = root.join(file_name);
    path.exists().then_some(path)
}

fn desktop_snapshot_script_path(args: &Value, cwd: Option<&PathBuf>) -> PathBuf {
    if let Some(path) = args.get("script_path").and_then(|v| v.as_str()) {
        return PathBuf::from(path);
    }
    if let Ok(path) = std::env::var("AGENT_BRIDGE_DESKTOP_SNAPSHOT_SCRIPT") {
        if !path.trim().is_empty() {
            return PathBuf::from(path);
        }
    }
    if let Some(cwd) = cwd {
        let path = cwd.join("scripts/desktop_snapshot.py");
        if path.exists() {
            return path;
        }
    }
    if let Ok(cwd) = std::env::current_dir() {
        let path = cwd.join("scripts/desktop_snapshot.py");
        if path.exists() {
            return path;
        }
    }
    if let Some(path) = installed_runtime_script_path("desktop_snapshot.py") {
        return path;
    }
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../scripts/desktop_snapshot.py")
}

fn desktop_snapshot_error(error: Value) -> ToolResult {
    let mut result = ToolResult::json_text(&json!({
        "schema": "desktop_snapshot_mcp_error.v0",
        "status": "error",
        "error": error,
    }));
    result.is_error = true;
    result
}

// ===========================================================================
//                            desktop_verify
// ===========================================================================
// Read-only postflight verifier — the "verify"+"recover" leg of the Linux Computer
// Use loop (thread 79). After a desktop_invoke / desktop_action, this re-observes the
// bus (AT-SPI registry + sway tree) and checks ONE expectation, POLLING until it holds
// or times out, returning a `recover` hint (proceed|retry|replan|escalate) that maps
// 1:1 to the caller's next move. It never clicks/types/moves anything, so observing the
// REAL desktop is safe + ungated (like desktop_snapshot); --cage-pid / --swaysock only
// SCOPE what counts as present.

const DESKTOP_VERIFY_SEMANTIC_SCHEMA: &str = "agent_bridge.semantic_bus.desktop_verify.v0";
const DESKTOP_VERIFY_SOURCE_SCHEMA: &str = "desktop_verify/v0";

pub struct DesktopVerifyTool {
    _hub: Hub,
}

impl DesktopVerifyTool {
    pub fn new(hub: Hub) -> Self {
        Self { _hub: hub }
    }
}

#[async_trait]
impl McpTool for DesktopVerifyTool {
    fn name(&self) -> &'static str {
        "desktop_verify"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Read-only postflight verifier for the desktop act loop. After a \
                 desktop_invoke/desktop_action, re-observes the bus (AT-SPI + sway tree) and \
                 checks ONE expectation, polling until it holds or `poll_timeout_secs` elapses \
                 (GUIs animate — a single check races the toolkit). Reuses the SAME selector you \
                 acted on. Returns verdict (verified|unmet|error) and a `recover` hint \
                 (proceed|retry|replan|escalate) that maps 1:1 to your next move; an optional \
                 before-fingerprint splits a miss into unchanged (retry) vs diverged (replan). \
                 Never clicks/types/moves — observing the real desktop is safe; cage_pid/swaysock \
                 only scope what counts as present."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "cwd": { "type": "string", "description": "Repo root to resolve scripts/desktop_verify.py." },
                    "script_path": { "type": "string", "description": "Explicit desktop_verify.py path (tests/alternate checkouts)." },
                    "expect": {
                        "type": "string",
                        "enum": ["element_gone", "element_appeared", "state_is", "state_not", "window_gone", "window_appeared", "focus_is"],
                        "description": "The postcondition to check. element_*/state_* use the AT-SPI selector (app/role/name); window_*/focus_is use the window selector (win_*)."
                    },
                    "app": { "type": "string", "description": "AT-SPI application name substring (element_*/state_*)." },
                    "role": { "type": "string", "description": "AT-SPI role substring, e.g. button." },
                    "name": { "type": "string", "description": "AT-SPI accessible name substring, e.g. OK." },
                    "nth": { "type": "integer", "default": 0 },
                    "cage_pid": { "type": "integer", "description": "Scope AT-SPI matches to this process subtree (isolated verify)." },
                    "state": { "type": "string", "description": "For state_is/state_not: checked|expanded|selected|showing|visible|focused|sensitive|enabled|pressed|active." },
                    "win_app_id": { "type": "string", "description": "sway app_id substring (window_*/focus_is)." },
                    "win_pid": { "type": "integer", "description": "Window PID (exact)." },
                    "win_title": { "type": "string", "description": "Window title substring." },
                    "swaysock": { "type": "string", "description": "Nested sway IPC socket for window checks (isolated verify)." },
                    "poll_timeout_secs": {
                        "type": "number", "minimum": 0.0, "maximum": 30.0, "default": 4.0,
                        "description": "Poll until the expectation holds or this many seconds elapse."
                    },
                    "poll_interval_secs": { "type": "number", "minimum": 0.05, "maximum": 5.0, "default": 0.3 },
                    "settle_secs": {
                        "type": "number", "minimum": 0.0, "maximum": 5.0, "default": 0.0,
                        "description": "Initial delay before the first check (let the GUI start reacting)."
                    },
                    "before_present": {
                        "type": "string", "enum": ["true", "false"],
                        "description": "Was the AT-SPI target present BEFORE the act? Splits a miss into unchanged vs diverged."
                    },
                    "before_focus": { "type": "string", "description": "Focused 'app_id|title' BEFORE the act (for focus_is)." },
                    "semantic_bus": {
                        "type": "boolean",
                        "default": false,
                        "description": "When true, wrap the read-only desktop_verify/v0 payload as agent_bridge.semantic_bus.desktop_verify.v0. Default false preserves the existing payload exactly apart from mcp_wrapper."
                    },
                    "semantic_include_raw": {
                        "type": "boolean",
                        "default": false,
                        "description": "Only with semantic_bus=true: include the original desktop_verify payload as raw_verify. Default false keeps the semantic envelope compact."
                    },
                    "timeout_ms": {
                        "type": "integer", "minimum": 2000, "maximum": 60000, "default": 12000,
                        "description": "Milliseconds before the verify process is killed (kept above poll_timeout_secs)."
                    }
                },
                "required": ["expect"]
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let expect = match required_str_arg(&args, "expect") {
            Ok(v) => v,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        let poll_timeout_secs = args
            .get("poll_timeout_secs")
            .and_then(|v| v.as_f64())
            .unwrap_or(4.0)
            .clamp(0.0, 30.0);
        // keep the process-kill timeout safely above the in-script poll window
        let min_proc_ms = (poll_timeout_secs * 1000.0) as u64 + 3000;
        let timeout_ms = args
            .get("timeout_ms")
            .and_then(|v| v.as_u64())
            .unwrap_or(12_000)
            .clamp(2_000, 60_000)
            .max(min_proc_ms);
        let semantic_bus = args
            .get("semantic_bus")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let semantic_include_raw = args
            .get("semantic_include_raw")
            .and_then(Value::as_bool)
            .unwrap_or(false);

        let cwd = args.get("cwd").and_then(|v| v.as_str()).map(PathBuf::from);
        let script = desktop_verify_script_path(&args, cwd.as_ref());
        if !script.exists() {
            return Ok(desktop_verify_error(json!({
                "code": "script_missing",
                "message": format!("desktop_verify.py not found at {}", script.display()),
                "hint": "pass script_path or run from the Agent-Bridge repo root"
            })));
        }

        let mut cmd = killable_command(
            std::env::var("PYTHON")
                .ok()
                .filter(|s| !s.trim().is_empty())
                .unwrap_or_else(|| "python3".to_string()),
        );
        cmd.arg(&script)
            .arg("--compact")
            .arg("--expect")
            .arg(expect)
            .arg("--timeout")
            .arg(poll_timeout_secs.to_string());
        push_optional_str_arg(&mut cmd, &args, "app", "--app");
        push_optional_str_arg(&mut cmd, &args, "role", "--role");
        push_optional_str_arg(&mut cmd, &args, "name", "--name");
        push_optional_value_arg(&mut cmd, &args, "nth", "--nth");
        push_optional_value_arg(&mut cmd, &args, "cage_pid", "--cage-pid");
        push_optional_str_arg(&mut cmd, &args, "state", "--state");
        push_optional_str_arg(&mut cmd, &args, "win_app_id", "--win-app-id");
        push_optional_value_arg(&mut cmd, &args, "win_pid", "--win-pid");
        push_optional_str_arg(&mut cmd, &args, "win_title", "--win-title");
        push_optional_str_arg(&mut cmd, &args, "swaysock", "--swaysock");
        push_optional_str_arg(&mut cmd, &args, "before_present", "--before-present");
        push_optional_str_arg(&mut cmd, &args, "before_focus", "--before-focus");
        if let Some(pi) = args.get("poll_interval_secs").and_then(|v| v.as_f64()) {
            cmd.arg("--poll-interval")
                .arg(pi.clamp(0.05, 5.0).to_string());
        }
        if let Some(s) = args.get("settle_secs").and_then(|v| v.as_f64()) {
            if s > 0.0 {
                cmd.arg("--settle").arg(s.clamp(0.0, 5.0).to_string());
            }
        }
        cmd.stdout(std::process::Stdio::piped());
        cmd.stderr(std::process::Stdio::piped());
        if let Some(cwd) = cwd {
            cmd.current_dir(cwd);
        }

        let started = Instant::now();
        let output =
            match tokio::time::timeout(Duration::from_millis(timeout_ms), cmd.output()).await {
                Err(_) => {
                    return Ok(desktop_verify_error(json!({
                        "code": "timeout",
                        "message": format!("desktop_verify exceeded {timeout_ms} ms"),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Err(e)) => {
                    return Ok(desktop_verify_error(json!({
                        "code": "spawn_failed",
                        "message": e.to_string(),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Ok(output)) => output,
            };
        let duration_ms = started.elapsed().as_millis() as u64;
        let (stdout, stdout_truncated) = lossy_truncate(&output.stdout);
        let (stderr, stderr_truncated) = lossy_truncate(&output.stderr);
        // NOTE: the script exits 2 for unmet and 3 for error by design, so a non-zero
        // status is NOT a wrapper failure — parse stdout regardless and only fall back
        // to an error envelope when the JSON itself is unreadable.
        match serde_json::from_str::<Value>(&stdout) {
            Ok(mut payload) => {
                if let Some(obj) = payload.as_object_mut() {
                    obj.insert(
                        "mcp_wrapper".to_string(),
                        json!({
                            "tool": self.name(),
                            "read_only": true,
                            "exit_code": output.status.code().unwrap_or(-1),
                            "duration_ms": duration_ms,
                            "stderr": stderr,
                            "stderr_truncated": stderr_truncated
                        }),
                    );
                }
                if semantic_bus {
                    payload = desktop_verify_semantic_bus_payload(&payload, semantic_include_raw);
                }
                Ok(ToolResult::json_text(&payload))
            }
            Err(e) => Ok(desktop_verify_error(json!({
                "code": "invalid_json",
                "message": e.to_string(),
                "exit_code": output.status.code().unwrap_or(-1),
                "stdout": stdout,
                "stderr": stderr,
                "duration_ms": duration_ms,
                "truncated": stdout_truncated || stderr_truncated
            }))),
        }
    }
}

fn desktop_verify_semantic_bus_payload(verify: &Value, include_raw: bool) -> Value {
    let source_schema = verify
        .get("schema")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let ts = verify.get("ts").cloned().unwrap_or(Value::Null);
    let ts_label = desktop_snapshot_value_label(&ts, "unknown");
    let expect = verify
        .get("expect")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let source_verdict = verify
        .get("verdict")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let source_recover = verify
        .get("recover")
        .and_then(Value::as_str)
        .unwrap_or_else(|| match source_verdict {
            "verified" => "proceed",
            "error" => "escalate",
            "unmet" => "retry",
            _ => "replan",
        });
    let selector = verify.get("selector").cloned().unwrap_or_else(|| json!({}));
    let scope = verify.get("scope").cloned().unwrap_or_else(|| json!({}));
    let observed = verify.get("observed").cloned().unwrap_or_else(|| json!({}));
    let target_family = desktop_verify_target_family(expect);
    let target_summary = desktop_verify_selector_summary(&selector);
    let target_seed = format!("{expect}-{target_summary}");
    let target_object_id = format!(
        "desktop:linux:verify:{target_family}:{}",
        desktop_snapshot_slug(&target_seed)
    );
    let event_id = format!(
        "evt-desktop-verify-{ts_label}-{}",
        desktop_snapshot_slug(expect)
    );
    let schema_ok = source_schema == DESKTOP_VERIFY_SOURCE_SCHEMA;
    let semantic_verdict = if !schema_ok {
        "not_verified"
    } else {
        match source_verdict {
            "verified" => "verified",
            "error" => "error",
            _ => "not_verified",
        }
    };
    let semantic_recover = if schema_ok { source_recover } else { "replan" };
    let reason = if !schema_ok {
        json!("unexpected_source_schema")
    } else if source_verdict == "verified" {
        Value::Null
    } else if source_verdict == "error" {
        verify
            .get("error")
            .cloned()
            .filter(|v| !v.is_null())
            .unwrap_or_else(|| json!("desktop_verify_error"))
    } else if source_verdict == "unmet" {
        json!("postcondition_unmet")
    } else {
        json!("unknown_source_verdict")
    };
    let observed_count = observed.get("count").cloned().unwrap_or(Value::Null);
    let mut verify_args = selector.as_object().cloned().unwrap_or_default();
    verify_args.insert("expect".to_string(), json!(expect));

    let mut payload = json!({
        "schema": DESKTOP_VERIFY_SEMANTIC_SCHEMA,
        "source_schema": source_schema,
        "source_adapter": "linux.desktop_verify",
        "observed_at": ts,
        "read_only": true,
        "raw_available": true,
        "raw_included": include_raw,
        "semantic_objects": [
            {
                "schema": "agent_bridge.semantic_bus.object.v0",
                "object_id": target_object_id,
                "object_type": format!("desktop.verify.target.{target_family}"),
                "source_adapter": "linux.desktop_verify",
                "label": format!("desktop_verify {expect} {target_summary}"),
                "state": {
                    "expect": expect,
                    "selector": selector,
                    "scope": scope,
                    "source_verdict": source_verdict,
                    "recover": source_recover,
                    "change": verify.get("change").cloned().unwrap_or(Value::Null),
                    "held_after_ms": verify.get("held_after_ms").cloned().unwrap_or(Value::Null),
                    "polls": verify.get("polls").cloned().unwrap_or(Value::Null),
                    "observed": observed,
                    "error": verify.get("error").cloned().unwrap_or(Value::Null)
                },
                "relations": [],
                "confidence": if schema_ok { 0.9 } else { 0.25 },
                "observed_at": ts,
                "provenance": {
                    "tool": "desktop_verify",
                    "schema": source_schema
                }
            }
        ],
        "affordances": [
            {
                "affordance_id": format!("{target_object_id}:reverify"),
                "object_id": target_object_id,
                "action_type": "desktop.verify",
                "args_schema": Value::Object(verify_args),
                "risk_level": "low",
                "requires_gate": false,
                "expected_effect": "re-observes the same postcondition without mutating the desktop"
            }
        ],
        "events": [
            {
                "event_id": event_id,
                "event_type": "desktop.verify.completed",
                "subject_id": target_object_id,
                "source": "desktop_verify",
                "actor": "agent",
                "payload_json": {
                    "expect": expect,
                    "source_verdict": source_verdict,
                    "recover": source_recover,
                    "change": verify.get("change").cloned().unwrap_or(Value::Null),
                    "observed_count": observed_count,
                    "held_after_ms": verify.get("held_after_ms").cloned().unwrap_or(Value::Null),
                    "polls": verify.get("polls").cloned().unwrap_or(Value::Null)
                },
                "source_event_ids": []
            }
        ],
        "verification": {
            "verdict": semantic_verdict,
            "source_verdict": source_verdict,
            "reason": reason,
            "method": "desktop_verify.semantic_normalizer",
            "evidence": {
                "source_schema": source_schema,
                "expect": expect,
                "selector": verify.get("selector").cloned().unwrap_or_else(|| json!({})),
                "scope": verify.get("scope").cloned().unwrap_or_else(|| json!({})),
                "observed_count": observed.get("count").cloned().unwrap_or(Value::Null),
                "raw_included": include_raw
            },
            "verified_to": if semantic_verdict == "verified" { json!("postcondition") } else { Value::Null },
            "recover": semantic_recover,
            "raw_available": true
        },
        "presentation": {
            "presentation_id": format!("present-desktop-verify-{ts_label}"),
            "source_event_ids": [event_id],
            "human_summary": format!(
                "desktop_verify {expect} returned {source_verdict}; recover={semantic_recover}."
            ),
            "machine_payload": {
                "expect": expect,
                "source_verdict": source_verdict,
                "recover": semantic_recover,
                "observed_count": observed.get("count").cloned().unwrap_or(Value::Null)
            },
            "ingestion": {
                "allowed": false,
                "reason": "runtime_verify_not_durable_memory"
            },
            "artifact": Value::Null
        }
    });
    if include_raw {
        if let Some(obj) = payload.as_object_mut() {
            obj.insert("raw_verify".to_string(), verify.clone());
        }
    }
    payload
}

fn desktop_verify_target_family(expect: &str) -> &'static str {
    match expect {
        "window_gone" | "window_appeared" | "focus_is" => "window",
        "element_gone" | "element_appeared" | "state_is" | "state_not" => "accessible",
        _ => "target",
    }
}

fn desktop_verify_selector_summary(selector: &Value) -> String {
    let mut parts = Vec::new();
    for key in [
        "app",
        "role",
        "name",
        "state",
        "win_app_id",
        "win_title",
        "win_pid",
    ] {
        if let Some(value) = selector.get(key) {
            match value {
                Value::String(s) if !s.trim().is_empty() => {
                    parts.push(format!("{key}:{}", s.trim()));
                }
                Value::Number(n) => parts.push(format!("{key}:{n}")),
                Value::Bool(b) => parts.push(format!("{key}:{b}")),
                _ => {}
            }
        }
    }
    if parts.is_empty() {
        "unspecified-target".to_string()
    } else {
        parts.join(" ")
    }
}

fn desktop_verify_script_path(args: &Value, cwd: Option<&PathBuf>) -> PathBuf {
    if let Some(path) = args.get("script_path").and_then(|v| v.as_str()) {
        return PathBuf::from(path);
    }
    if let Ok(path) = std::env::var("AGENT_BRIDGE_DESKTOP_VERIFY_SCRIPT") {
        if !path.trim().is_empty() {
            return PathBuf::from(path);
        }
    }
    if let Some(cwd) = cwd {
        let path = cwd.join("scripts/desktop_verify.py");
        if path.exists() {
            return path;
        }
    }
    if let Ok(cwd) = std::env::current_dir() {
        let path = cwd.join("scripts/desktop_verify.py");
        if path.exists() {
            return path;
        }
    }
    if let Some(path) = installed_runtime_script_path("desktop_verify.py") {
        return path;
    }
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../scripts/desktop_verify.py")
}

fn desktop_verify_error(error: Value) -> ToolResult {
    let mut result = ToolResult::json_text(&json!({
        "schema": "desktop_verify_mcp_error.v0",
        "status": "error",
        "error": error,
    }));
    result.is_error = true;
    result
}

// ===========================================================================
//                              macos_ax_probe
// ===========================================================================

const MACOS_AX_PROBE_SEMANTIC_SCHEMA: &str = "agent_bridge.semantic_bus.macos_ax_probe.v0";
const MACOS_AX_PROBE_SOURCE_SCHEMA: &str = "macos_ax_probe/v0";

pub struct MacosAxProbeTool {
    _hub: Hub,
}

impl MacosAxProbeTool {
    pub fn new(hub: Hub) -> Self {
        Self { _hub: hub }
    }
}

fn macos_ax_probe_process_timeout_ms(
    args: &Value,
    include_windows: bool,
    jxa_timeout_secs: f64,
) -> u64 {
    let requested_ms = args
        .get("timeout_ms")
        .and_then(Value::as_u64)
        .unwrap_or(8_000)
        .clamp(1_000, 30_000);
    if !include_windows {
        return requested_ms;
    }

    // Leave the Python process enough time to exhaust its own bounded JXA
    // read and report the result instead of preempting it at the outer layer.
    let minimum_ms = (jxa_timeout_secs * 1000.0).ceil() as u64 + 3_000;
    requested_ms.max(minimum_ms).min(30_000)
}

#[async_trait]
impl McpTool for MacosAxProbeTool {
    fn name(&self) -> &'static str {
        "macos_ax_probe"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Read-only macOS Accessibility feasibility probe. Reports platform \
                 support, AX trust state, frontmost app metadata, and a bounded window summary \
                 only when Accessibility is already trusted. It does not request AX permission; \
                 before System Events it runs a best-effort no-ask Apple Events preflight and \
                 fails closed unless explicitly allowed. It never clicks, types, focuses apps, \
                 or mutates window state."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "cwd": {
                        "type": "string",
                        "description": "Workspace/repo root used to resolve scripts/macos_ax_probe.py. Defaults to the MCP process cwd, then the build-time repo root."
                    },
                    "script_path": {
                        "type": "string",
                        "description": "Optional explicit macos_ax_probe.py path. Use mainly for tests or alternate checkouts."
                    },
                    "include_windows": {
                        "type": "boolean",
                        "default": true,
                        "description": "When true, read a bounded frontmost app/window summary through System Events only if AX is already trusted."
                    },
                    "max_windows": {
                        "type": "integer",
                        "minimum": 0,
                        "maximum": 50,
                        "default": 8,
                        "description": "Maximum frontmost-app windows to return."
                    },
                    "jxa_timeout_secs": {
                        "type": "number",
                        "minimum": 0.25,
                        "maximum": 10.0,
                        "default": 4.0,
                        "description": "Timeout for the bounded System Events/JXA read."
                    },
                    "semantic_bus": {
                        "type": "boolean",
                        "default": false,
                        "description": "When true, wrap the macos_ax_probe/v0 payload as agent_bridge.semantic_bus.macos_ax_probe.v0. Default false preserves the probe payload exactly apart from mcp_wrapper."
                    },
                    "semantic_include_raw": {
                        "type": "boolean",
                        "default": false,
                        "description": "Only with semantic_bus=true: include the original macos_ax_probe payload as raw_probe. Default false keeps the semantic envelope compact."
                    },
                    "timeout_ms": {
                        "type": "integer",
                        "minimum": 1000,
                        "maximum": 30000,
                        "default": 8000,
                        "description": "Requested milliseconds before the probe process is killed. For window reads, the effective outer timeout is raised when necessary to cover jxa_timeout_secs plus three seconds of process/preflight overhead."
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let include_windows = args
            .get("include_windows")
            .and_then(Value::as_bool)
            .unwrap_or(true);
        let max_windows = args
            .get("max_windows")
            .and_then(Value::as_u64)
            .unwrap_or(8)
            .min(50);
        let jxa_timeout_secs = args
            .get("jxa_timeout_secs")
            .and_then(Value::as_f64)
            .unwrap_or(4.0)
            .clamp(0.25, 10.0);
        let timeout_ms =
            macos_ax_probe_process_timeout_ms(&args, include_windows, jxa_timeout_secs);
        let semantic_bus = args
            .get("semantic_bus")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let semantic_include_raw = args
            .get("semantic_include_raw")
            .and_then(Value::as_bool)
            .unwrap_or(false);

        let cwd = args.get("cwd").and_then(Value::as_str).map(PathBuf::from);
        let script = macos_ax_probe_script_path(&args, cwd.as_ref());
        if !script.exists() {
            return Ok(macos_ax_probe_error(json!({
                "code": "script_missing",
                "message": format!("macos_ax_probe.py not found at {}", script.display()),
                "hint": "pass script_path or run from the Agent-Bridge repo root"
            })));
        }

        let mut cmd = killable_command(
            std::env::var("PYTHON")
                .ok()
                .filter(|s| !s.trim().is_empty())
                .unwrap_or_else(|| "python3".to_string()),
        );
        cmd.arg(&script)
            .arg("--compact")
            .arg("--max-windows")
            .arg(max_windows.to_string())
            .arg("--jxa-timeout-secs")
            .arg(jxa_timeout_secs.to_string());
        if !include_windows {
            cmd.arg("--no-windows");
        }
        cmd.stdout(std::process::Stdio::piped());
        cmd.stderr(std::process::Stdio::piped());
        if let Some(cwd) = cwd {
            cmd.current_dir(cwd);
        }

        let started = Instant::now();
        let output =
            match tokio::time::timeout(Duration::from_millis(timeout_ms), cmd.output()).await {
                Err(_) => {
                    return Ok(macos_ax_probe_error(json!({
                        "code": "timeout",
                        "message": format!("macos_ax_probe exceeded {timeout_ms} ms"),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Err(e)) => {
                    return Ok(macos_ax_probe_error(json!({
                        "code": "spawn_failed",
                        "message": e.to_string(),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Ok(output)) => output,
            };
        let duration_ms = started.elapsed().as_millis() as u64;
        let (stdout, stdout_truncated) = lossy_truncate(&output.stdout);
        let (stderr, stderr_truncated) = lossy_truncate(&output.stderr);

        if !output.status.success() {
            return Ok(macos_ax_probe_error(json!({
                "code": "script_failed",
                "exit_code": output.status.code().unwrap_or(-1),
                "stdout": stdout,
                "stderr": stderr,
                "duration_ms": duration_ms,
                "truncated": stdout_truncated || stderr_truncated
            })));
        }

        match serde_json::from_str::<Value>(&stdout) {
            Ok(mut payload) => {
                if let Some(obj) = payload.as_object_mut() {
                    obj.insert(
                        "mcp_wrapper".to_string(),
                        json!({
                            "tool": self.name(),
                            "read_only": true,
                            "include_windows": include_windows,
                            "max_windows": max_windows,
                            "duration_ms": duration_ms,
                            "exit_code": output.status.code().unwrap_or(-1),
                            "stderr": stderr,
                            "stderr_truncated": stderr_truncated
                        }),
                    );
                }
                if semantic_bus {
                    payload = macos_ax_probe_semantic_bus_payload(&payload, semantic_include_raw);
                }
                Ok(ToolResult::json_text(&payload))
            }
            Err(e) => Ok(macos_ax_probe_error(json!({
                "code": "invalid_json",
                "message": e.to_string(),
                "stdout": stdout,
                "stderr": stderr,
                "duration_ms": duration_ms,
                "truncated": stdout_truncated || stderr_truncated
            }))),
        }
    }
}

fn macos_ax_probe_semantic_bus_payload(probe: &Value, include_raw: bool) -> Value {
    let source_schema = probe
        .get("schema")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let captured_at = probe.get("captured_at").cloned().unwrap_or(Value::Null);
    let captured_label = desktop_snapshot_value_label(&captured_at, "unknown");
    let status = probe
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let schema_ok = source_schema == MACOS_AX_PROBE_SOURCE_SCHEMA;
    let platform_ok = probe.pointer("/platform/system").and_then(Value::as_str)
        == Some("Darwin");
    let include_windows = probe
        .pointer("/limits/include_windows")
        .and_then(Value::as_bool);
    let wrapper_include_windows = probe
        .pointer("/mcp_wrapper/include_windows")
        .and_then(Value::as_bool);
    let wrapper_max_windows = probe
        .pointer("/mcp_wrapper/max_windows")
        .and_then(Value::as_u64);
    let limit_max_windows = probe
        .pointer("/limits/max_windows")
        .and_then(Value::as_u64);
    let request_binding_ok = include_windows.is_some()
        && wrapper_include_windows == include_windows
        && wrapper_max_windows.is_some()
        && wrapper_max_windows == limit_max_windows;
    let permission_ok = probe.pointer("/permission/ax_trusted").and_then(Value::as_bool)
        == Some(true)
        && probe.pointer("/permission/prompted").and_then(Value::as_bool) == Some(false)
        && probe.pointer("/permission/method").and_then(Value::as_str)
            == Some("AXIsProcessTrusted");
    let errors_empty = probe
        .get("errors")
        .and_then(Value::as_array)
        .is_some_and(Vec::is_empty);
    let window_count = probe.get("window_count").and_then(Value::as_u64);
    let source_window_count = probe.get("source_window_count").and_then(Value::as_u64);
    let windows = probe.get("windows").and_then(Value::as_array);
    let windows_len = windows.map(|windows| windows.len() as u64);
    let windows_valid = windows.is_some_and(|windows| windows.iter().all(Value::is_object));
    let incomplete_reasons_empty = probe
        .get("incomplete_reasons")
        .and_then(Value::as_array)
        .is_some_and(Vec::is_empty);
    let window_evidence_complete = probe.get("read_only").and_then(Value::as_bool) == Some(true)
        && probe.get("windows_read_ok").and_then(Value::as_bool)
        == Some(true)
        && macos_ax_app_identity_valid(probe)
        && windows_valid
        && probe.get("counts_consistent").and_then(Value::as_bool) == Some(true)
        && probe.get("coverage_complete").and_then(Value::as_bool) == Some(true)
        && incomplete_reasons_empty
        && probe.pointer("/limits/truncated").and_then(Value::as_bool) == Some(false)
        && window_count.is_some()
        && window_count == source_window_count
        && window_count == windows_len
        && window_count.zip(limit_max_windows).is_some_and(|(count, limit)| {
            limit <= 50 && count <= limit
        });
    let no_window_evidence_complete = probe.get("read_only").and_then(Value::as_bool)
        == Some(true)
        && windows.is_some_and(Vec::is_empty)
        && window_count == Some(0)
        && probe.get("source_window_count") == Some(&Value::Null)
        && probe.get("windows_read_ok") == Some(&Value::Null)
        && probe.get("frontmost_app") == Some(&Value::Null)
        && probe.get("app_identity_valid").and_then(Value::as_bool) == Some(false)
        && probe.get("counts_consistent").and_then(Value::as_bool) == Some(false)
        && probe.get("coverage_complete").and_then(Value::as_bool) == Some(true)
        && incomplete_reasons_empty
        && probe.pointer("/limits/truncated").and_then(Value::as_bool) == Some(false)
        && limit_max_windows.is_some_and(|limit| limit <= 50);
    let evidence_admissible = platform_ok
        && request_binding_ok
        && permission_ok
        && errors_empty
        && match include_windows {
            Some(true) => window_evidence_complete,
            Some(false) => no_window_evidence_complete,
            None => false,
        };
    let semantic_verdict = if !schema_ok {
        "not_verified"
    } else if status == "ready" && evidence_admissible {
        "verified"
    } else if status == "unsupported_platform" {
        "blocked"
    } else {
        "not_verified"
    };
    let recover = if schema_ok && status == "ready" && evidence_admissible {
        "proceed"
    } else {
        "replan"
    };
    let reason = if !schema_ok {
        json!("unexpected_source_schema")
    } else if status == "unsupported_platform" {
        json!("unsupported_platform")
    } else if status == "degraded" {
        json!("limited_accessibility_or_window_read")
    } else if status == "ready" && !evidence_admissible {
        json!("incomplete_probe_evidence")
    } else if status != "ready" {
        json!("probe_not_ready")
    } else {
        Value::Null
    };
    let session_object_id = format!("desktop:macos:session:{captured_label}");
    let event_id = format!("evt-macos-ax-probe-{captured_label}");

    let mut semantic_objects = vec![json!({
        "schema": "agent_bridge.semantic_bus.object.v0",
        "object_id": session_object_id,
        "object_type": "desktop.session",
        "source_adapter": "macos.ax_probe",
        "label": "macOS desktop session",
        "state": {
            "platform": probe.get("platform").cloned().unwrap_or_else(|| json!({})),
            "status": status,
            "permission": probe.get("permission").cloned().unwrap_or_else(|| json!({})),
            "frontmost_app": probe.get("frontmost_app").cloned().unwrap_or(Value::Null),
            "window_count": probe.get("window_count").cloned().unwrap_or(Value::Null),
            "source_window_count": probe.get("source_window_count").cloned().unwrap_or(Value::Null),
            "limits": probe.get("limits").cloned().unwrap_or_else(|| json!({})),
        },
        "relations": [],
        "confidence": if schema_ok { 0.85 } else { 0.2 },
        "observed_at": captured_at,
        "provenance": {
            "tool": "macos_ax_probe",
            "schema": source_schema
        }
    })];
    let mut affordances = Vec::new();

    if let Some(app) = probe.get("frontmost_app").filter(|v| v.is_object()) {
        let app_id = macos_ax_app_object_id(app);
        semantic_objects.push(json!({
            "schema": "agent_bridge.semantic_bus.object.v0",
            "object_id": app_id,
            "object_type": "desktop.application",
            "source_adapter": "macos.system_events",
            "label": app.get("name").and_then(Value::as_str).unwrap_or("frontmost app"),
            "state": {
                "name": app.get("name").cloned().unwrap_or(Value::Null),
                "pid": app.get("pid").cloned().unwrap_or(Value::Null),
                "bundle_id": app.get("bundle_id").cloned().unwrap_or(Value::Null),
                "role": app.get("role").cloned().unwrap_or(Value::Null),
                "frontmost": true
            },
            "relations": [
                { "type": "member_of", "target": session_object_id }
            ],
            "confidence": 0.86,
            "observed_at": captured_at,
            "provenance": {
                "tool": "macos_ax_probe",
                "schema": source_schema,
                "source_path": "frontmost_app"
            }
        }));
    }

    if let Some(windows) = probe.get("windows").and_then(Value::as_array) {
        for (idx, window) in windows.iter().enumerate() {
            let object_id = macos_ax_window_object_id(probe, window, idx);
            semantic_objects.push(json!({
                "schema": "agent_bridge.semantic_bus.object.v0",
                "object_id": object_id,
                "object_type": "desktop.window",
                "source_adapter": "macos.ax.window",
                "label": window.get("title").and_then(Value::as_str).unwrap_or("macOS window"),
                "state": {
                    "index": window.get("index").cloned().unwrap_or(Value::Null),
                    "ax_identifier": window.get("ax_identifier").cloned().unwrap_or(Value::Null),
                    "identity": window.get("identity").cloned().unwrap_or(Value::Null),
                    "title": window.get("title").cloned().unwrap_or(Value::Null),
                    "role": window.get("role").cloned().unwrap_or(Value::Null),
                    "subrole": window.get("subrole").cloned().unwrap_or(Value::Null),
                    "focused": window.get("focused").cloned().unwrap_or(Value::Null),
                    "position": window.get("position").cloned().unwrap_or(Value::Null),
                    "size": window.get("size").cloned().unwrap_or(Value::Null),
                    "rect": window.get("rect").cloned().unwrap_or(Value::Null),
                    "app": probe.get("frontmost_app").cloned().unwrap_or(Value::Null),
                    "platform": probe.get("platform").cloned().unwrap_or_else(|| json!({})),
                },
                "relations": [
                    { "type": "member_of", "target": session_object_id }
                ],
                "confidence": 0.82,
                "observed_at": captured_at,
                "provenance": {
                    "tool": "macos_ax_probe",
                    "schema": source_schema,
                    "source_path": "windows"
                }
            }));
            affordances.push(json!({
                "affordance_id": format!("{object_id}:reobserve"),
                "object_id": object_id,
                "action_type": "macos_ax_probe.reobserve",
                "args_schema": {
                    "include_windows": true,
                    "max_windows": probe
                        .get("limits")
                        .and_then(|v| v.get("max_windows"))
                        .cloned()
                        .unwrap_or_else(|| json!(8))
                },
                "risk_level": "low",
                "requires_gate": false,
                "expected_effect": "re-runs the read-only macOS AX probe without mutating app or window state"
            }));
        }
    }

    let object_count = semantic_objects.len();
    let window_count = probe.get("window_count").cloned().unwrap_or(Value::Null);
    let mut payload = json!({
        "schema": MACOS_AX_PROBE_SEMANTIC_SCHEMA,
        "source_schema": source_schema,
        "source_adapter": "macos.ax_probe",
        "captured_at": captured_at,
        "read_only": true,
        "raw_available": true,
        "raw_included": include_raw,
        "semantic_objects": semantic_objects,
        "affordances": affordances,
        "events": [
            {
                "event_id": event_id,
                "event_type": "desktop.snapshot.observed",
                "subject_id": session_object_id,
                "source": "macos_ax_probe",
                "actor": "agent",
                "payload_json": {
                    "status": status,
                    "object_count": object_count,
                    "window_count": window_count,
                    "ax_trusted": probe
                        .get("permission")
                        .and_then(|v| v.get("ax_trusted"))
                        .cloned()
                        .unwrap_or(Value::Null),
                    "prompted": probe
                        .get("permission")
                        .and_then(|v| v.get("prompted"))
                        .cloned()
                        .unwrap_or(Value::Null)
                },
                "source_event_ids": []
            }
        ],
        "verification": {
            "verdict": semantic_verdict,
            "reason": reason,
            "method": "macos_ax_probe.semantic_normalizer",
            "evidence": {
                "source_schema": source_schema,
                "status": status,
                "platform_ok": platform_ok,
                "request_binding_ok": request_binding_ok,
                "permission": probe.get("permission").cloned().unwrap_or_else(|| json!({})),
                "window_count": window_count,
                "source_window_count": probe.get("source_window_count").cloned().unwrap_or(Value::Null),
                "windows_read_ok": probe.get("windows_read_ok").cloned().unwrap_or(Value::Null),
                "app_identity_valid": probe.get("app_identity_valid").cloned().unwrap_or(Value::Null),
                "counts_consistent": probe.get("counts_consistent").cloned().unwrap_or(Value::Null),
                "coverage_complete": probe.get("coverage_complete").cloned().unwrap_or(Value::Null),
                "incomplete_reasons": probe.get("incomplete_reasons").cloned().unwrap_or(Value::Null),
                "limits": probe.get("limits").cloned().unwrap_or_else(|| json!({})),
                "errors": probe.get("errors").cloned().unwrap_or_else(|| json!([])),
                "raw_included": include_raw
            },
            "verified_to": if semantic_verdict == "verified" { json!("semantic_objects") } else { Value::Null },
            "recover": recover,
            "raw_available": true
        },
        "presentation": {
            "presentation_id": format!("present-macos-ax-probe-{captured_label}"),
            "source_event_ids": [event_id],
            "human_summary": format!(
                "macos_ax_probe returned {status}; normalized {object_count} semantic objects."
            ),
            "machine_payload": {
                "status": status,
                "object_count": object_count,
                "window_count": probe.get("window_count").cloned().unwrap_or(Value::Null),
                "source_window_count": probe.get("source_window_count").cloned().unwrap_or(Value::Null)
            },
            "ingestion": {
                "allowed": false,
                "reason": "runtime_probe_not_durable_memory"
            },
            "artifact": Value::Null
        }
    });
    if include_raw {
        if let Some(obj) = payload.as_object_mut() {
            obj.insert("raw_probe".to_string(), probe.clone());
        }
    }
    payload
}

fn macos_ax_app_object_id(app: &Value) -> String {
    if let Some(pid) = app.get("pid").and_then(Value::as_i64) {
        return format!("desktop:macos:app:{pid}");
    }
    if let Some(bundle) = app.get("bundle_id").and_then(Value::as_str) {
        return format!("desktop:macos:app:{}", desktop_snapshot_slug(bundle));
    }
    format!(
        "desktop:macos:app:{}",
        desktop_snapshot_slug(app.get("name").and_then(Value::as_str).unwrap_or("unknown"))
    )
}

fn macos_ax_window_object_id(probe: &Value, window: &Value, idx: usize) -> String {
    let pid = probe
        .get("frontmost_app")
        .and_then(|v| v.get("pid"))
        .and_then(Value::as_i64)
        .map(|p| p.to_string())
        .unwrap_or_else(|| "unknown".to_string());
    if window
        .get("identity")
        .and_then(|v| v.get("stable_across_samples"))
        .and_then(Value::as_bool)
        .unwrap_or(false)
    {
        if let Some(identifier) = window
            .get("identity")
            .and_then(|v| v.get("value"))
            .and_then(Value::as_str)
            .filter(|value| !value.trim().is_empty())
        {
            return format!(
                "desktop:macos:window:{pid}:ax:{}",
                desktop_snapshot_slug(identifier)
            );
        }
    }
    let source_index = window
        .get("index")
        .and_then(Value::as_i64)
        .map(|i| i.to_string())
        .unwrap_or_else(|| idx.to_string());
    format!("desktop:macos:window:{pid}:{source_index}")
}

fn macos_ax_probe_script_path(args: &Value, cwd: Option<&PathBuf>) -> PathBuf {
    if let Some(path) = args.get("script_path").and_then(Value::as_str) {
        return PathBuf::from(path);
    }
    if let Ok(path) = std::env::var("AGENT_BRIDGE_MACOS_AX_PROBE_SCRIPT") {
        if !path.trim().is_empty() {
            return PathBuf::from(path);
        }
    }
    if let Some(cwd) = cwd {
        let path = cwd.join("scripts/macos_ax_probe.py");
        if path.exists() {
            return path;
        }
    }
    if let Ok(cwd) = std::env::current_dir() {
        let path = cwd.join("scripts/macos_ax_probe.py");
        if path.exists() {
            return path;
        }
    }
    if let Some(path) = installed_runtime_script_path("macos_ax_probe.py") {
        return path;
    }
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../scripts/macos_ax_probe.py")
}

fn macos_ax_probe_error(error: Value) -> ToolResult {
    let mut result = ToolResult::json_text(&json!({
        "schema": "macos_ax_probe_mcp_error.v0",
        "status": "error",
        "error": error,
    }));
    result.is_error = true;
    result
}

// ===========================================================================
//                              macos_ax_watch
// ===========================================================================

pub struct MacosAxWatchTool {
    _hub: Hub,
}

impl MacosAxWatchTool {
    pub fn new(hub: Hub) -> Self {
        Self { _hub: hub }
    }
}

#[async_trait]
impl McpTool for MacosAxWatchTool {
    fn name(&self) -> &'static str {
        "macos_ax_watch"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Bounded, read-only macOS AX short-term event stream plus current desktop semantic state. It returns order-independent scope/state SHA-256 fingerprints and a short-lived state token; pass an earlier exact token back to distinguish unchanged/proceed from drifted, scope-changed, or indeterminate/replan. Window lifecycle events still require the same process and a sample-unique stable AXIdentifier. Sample-local windows contribute only semantic state, never object-continuity claims. Incomplete, truncated, stale, or malformed evidence fails closed. It never activates apps, focuses windows, clicks, types, or writes durable memory.".into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "cwd": {"type": "string", "description": "Workspace/repo root used to resolve scripts/macos_ax_watch.py."},
                    "script_path": {"type": "string", "description": "Optional explicit macos_ax_watch.py path for tests or alternate checkouts."},
                    "samples": {"type": "integer", "minimum": 2, "maximum": 6, "default": 3},
                    "interval_secs": {"type": "number", "minimum": 0.05, "maximum": 2.0, "default": 0.3},
                    "max_windows": {"type": "integer", "minimum": 0, "maximum": 50, "default": 8},
                    "max_events": {"type": "integer", "minimum": 1, "maximum": 100, "default": 32},
                    "jxa_timeout_secs": {"type": "number", "minimum": 0.25, "maximum": 5.0, "default": 4.0},
                    "include_samples": {"type": "boolean", "default": false, "description": "Include bounded raw samples. Default false returns only compact sample summaries."},
                    "before_state_token": {
                        "type": "object",
                        "description": "Optional exact current_state.token from an earlier complete macos_ax_watch result. The token is read-only comparison evidence, not authorization.",
                        "properties": {
                            "schema": {"type": "string", "const": "agent_bridge.desktop_state_token.v0"},
                            "captured_at_unix_ms": {"type": "integer", "minimum": 1},
                            "max_age_ms": {"type": "integer", "minimum": 1000, "maximum": 300000},
                            "coverage_complete": {"type": "boolean", "const": true},
                            "scope_projection": {"type": "string", "const": "agent_bridge.desktop_scope_projection.v1"},
                            "state_projection": {"type": "string", "const": "agent_bridge.desktop_state_projection.v1"},
                            "scope_sha256": {"type": "string", "pattern": "^sha256:[0-9a-f]{64}$", "minLength": 71, "maxLength": 71},
                            "state_sha256": {"type": "string", "pattern": "^sha256:[0-9a-f]{64}$", "minLength": 71, "maxLength": 71}
                        },
                        "required": [
                            "schema", "captured_at_unix_ms", "max_age_ms",
                            "coverage_complete", "scope_projection", "state_projection",
                            "scope_sha256", "state_sha256"
                        ],
                        "additionalProperties": false
                    },
                    "max_token_age_ms": {"type": "integer", "minimum": 1000, "maximum": 300000, "default": 30000, "description": "Maximum accepted age for before_state_token; the stricter of this and the token's own max_age_ms wins."},
                    "timeout_ms": {"type": "integer", "minimum": 3000, "maximum": 60000, "default": 20000}
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let samples = args.get("samples").and_then(Value::as_u64).unwrap_or(3).clamp(2, 6);
        let interval_secs = args.get("interval_secs").and_then(Value::as_f64).unwrap_or(0.3).clamp(0.05, 2.0);
        let max_windows = args.get("max_windows").and_then(Value::as_u64).unwrap_or(8).min(50);
        let max_events = args.get("max_events").and_then(Value::as_u64).unwrap_or(32).clamp(1, 100);
        let jxa_timeout_secs = args.get("jxa_timeout_secs").and_then(Value::as_f64).unwrap_or(4.0).clamp(0.25, 5.0);
        let include_samples = args.get("include_samples").and_then(Value::as_bool).unwrap_or(false);
        // Forward even a malformed non-object value so the script can return
        // indeterminate/replan instead of silently treating it as no baseline.
        let before_state_token = args.get("before_state_token");
        let max_token_age_ms = args.get("max_token_age_ms").and_then(Value::as_u64).unwrap_or(30_000).clamp(1_000, 300_000);
        let minimum_timeout = ((samples as f64 * jxa_timeout_secs
            + (samples.saturating_sub(1)) as f64 * interval_secs
            + 3.0)
            * 1000.0) as u64;
        let timeout_ms = args.get("timeout_ms").and_then(Value::as_u64).unwrap_or(20_000).clamp(3_000, 60_000).max(minimum_timeout).min(60_000);
        let cwd = args.get("cwd").and_then(Value::as_str).map(PathBuf::from);
        let script = macos_ax_watch_script_path(&args, cwd.as_ref());
        if !script.exists() {
            return Ok(macos_ax_watch_error(json!({
                "code": "script_missing",
                "message": format!("macos_ax_watch.py not found at {}", script.display())
            })));
        }

        let mut cmd = killable_command(
            std::env::var("PYTHON").ok().filter(|s| !s.trim().is_empty()).unwrap_or_else(|| "python3".to_string()),
        );
        cmd.arg(&script)
            .arg("--compact")
            .arg("--samples").arg(samples.to_string())
            .arg("--interval").arg(interval_secs.to_string())
            .arg("--max-windows").arg(max_windows.to_string())
            .arg("--max-events").arg(max_events.to_string())
            .arg("--jxa-timeout-secs").arg(jxa_timeout_secs.to_string())
            .arg("--max-token-age-ms").arg(max_token_age_ms.to_string());
        if include_samples {
            cmd.arg("--include-samples");
        }
        if let Some(token) = before_state_token {
            cmd.arg("--before-token-json").arg(token.to_string());
        }
        cmd.stdout(std::process::Stdio::piped());
        cmd.stderr(std::process::Stdio::piped());
        if let Some(cwd) = cwd {
            cmd.current_dir(cwd);
        }
        let started = Instant::now();
        let output = match tokio::time::timeout(Duration::from_millis(timeout_ms), cmd.output()).await {
            Err(_) => return Ok(macos_ax_watch_error(json!({"code": "timeout", "duration_ms": started.elapsed().as_millis() as u64}))),
            Ok(Err(e)) => return Ok(macos_ax_watch_error(json!({"code": "spawn_failed", "message": e.to_string()}))),
            Ok(Ok(output)) => output,
        };
        let duration_ms = started.elapsed().as_millis() as u64;
        let (stdout, stdout_truncated) = lossy_truncate(&output.stdout);
        let (stderr, stderr_truncated) = lossy_truncate(&output.stderr);
        match serde_json::from_str::<Value>(&stdout) {
            Ok(mut payload) => {
                if let Some(obj) = payload.as_object_mut() {
                    obj.insert("mcp_wrapper".into(), json!({
                        "tool": self.name(), "read_only": true, "duration_ms": duration_ms,
                        "exit_code": output.status.code().unwrap_or(-1), "stderr": stderr,
                        "truncated": stdout_truncated || stderr_truncated,
                        "before_state_token_supplied": before_state_token.is_some(),
                        "max_token_age_ms": max_token_age_ms
                    }));
                }
                Ok(ToolResult::json_text(&payload))
            }
            Err(e) => Ok(macos_ax_watch_error(json!({"code": "invalid_json", "message": e.to_string(), "stdout": stdout, "stderr": stderr}))),
        }
    }
}

fn macos_ax_watch_script_path(args: &Value, cwd: Option<&PathBuf>) -> PathBuf {
    if let Some(path) = args.get("script_path").and_then(Value::as_str) {
        return PathBuf::from(path);
    }
    if let Ok(path) = std::env::var("AGENT_BRIDGE_MACOS_AX_WATCH_SCRIPT") {
        if !path.trim().is_empty() {
            return PathBuf::from(path);
        }
    }
    if let Some(cwd) = cwd {
        let path = cwd.join("scripts/macos_ax_watch.py");
        if path.exists() { return path; }
    }
    if let Ok(cwd) = std::env::current_dir() {
        let path = cwd.join("scripts/macos_ax_watch.py");
        if path.exists() { return path; }
    }
    if let Some(path) = installed_runtime_script_path("macos_ax_watch.py") {
        return path;
    }
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../scripts/macos_ax_watch.py")
}

fn macos_ax_watch_error(error: Value) -> ToolResult {
    let mut result = ToolResult::json_text(&json!({
        "schema": "macos_ax_watch_mcp_error.v0", "status": "error", "read_only": true, "error": error
    }));
    result.is_error = true;
    result
}

// ===========================================================================
//                       macos_ax_action_admission
// ===========================================================================

fn macos_ax_action_risk(operation: &str) -> Option<(&'static str, u8)> {
    match operation {
        "activate_app" | "focus_window" | "move_window" | "resize_window" | "scroll"
        | "select_element" => Some(("embodied_navigation", 1)),
        "type_text" | "press_button" | "trash_item" => Some(("reversible_content", 2)),
        "submit_form" | "send_message" | "permanent_delete" | "purchase" => {
            Some(("consequential_external", 3))
        }
        "permission_change" | "credential_entry" => Some(("protected_boundary", 4)),
        _ => None,
    }
}

fn macos_ax_requested_effect_risk(effect: Option<&str>) -> Option<(&'static str, u8)> {
    match effect {
        None => None,
        Some("local_navigation") => Some(("embodied_navigation", 1)),
        Some("local_content") => Some(("reversible_content", 2)),
        Some("external_commit") => Some(("consequential_external", 3)),
        Some("protected_boundary") => Some(("protected_boundary", 4)),
        Some(_) => None,
    }
}

fn macos_ax_trimmed_string(value: Option<&Value>) -> Option<&str> {
    value
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
}

fn macos_ax_target_binding_mode(target: &Value) -> Option<&'static str> {
    let target = target.as_object()?;
    let bundle_id = macos_ax_trimmed_string(target.get("bundle_id"))?;
    let pid = target.get("pid").and_then(Value::as_u64)?;
    if bundle_id.is_empty() || pid == 0 {
        return None;
    }
    let ax_identifier = macos_ax_trimmed_string(target.get("ax_identifier"));
    let window_index = target.get("window_index").and_then(Value::as_u64);
    match (ax_identifier, window_index) {
        (Some(_), None) => Some("stable_ax_identifier"),
        (None, Some(_))
            if target.get("expected_title").and_then(Value::as_str).is_some()
                && macos_ax_trimmed_string(target.get("expected_role")).is_some() =>
        {
            Some("sample_index_with_constraints")
        }
        _ => None,
    }
}

fn macos_ax_json_sha256(value: &Value) -> String {
    let encoded = serde_json::to_vec(value).expect("serde_json::Value is serializable");
    let mut hasher = Sha256::new();
    hasher.update(encoded);
    format!("sha256:{:x}", hasher.finalize())
}

fn macos_ax_probe_receipt_binding(
    receipt: &Value,
    target: &Value,
    max_observation_age_ms: u64,
) -> (bool, bool, bool, Option<u64>, String) {
    let receipt_sha256 = macos_ax_json_sha256(receipt);
    let Some(target_mode) = macos_ax_target_binding_mode(target) else {
        return (false, false, false, None, receipt_sha256);
    };
    let schema_ok = receipt.get("schema").and_then(Value::as_str) == Some("macos_ax_probe/v0")
        && receipt.get("read_only").and_then(Value::as_bool) == Some(true)
        && receipt.pointer("/platform/system").and_then(Value::as_str) == Some("Darwin");
    let windows = receipt.get("windows").and_then(Value::as_array);
    let returned_count = windows.map(|windows| windows.len() as u64);
    let window_count = receipt.get("window_count").and_then(Value::as_u64);
    let source_window_count = receipt
        .get("source_window_count")
        .and_then(Value::as_u64);
    let max_windows = receipt.pointer("/limits/max_windows").and_then(Value::as_u64);
    let counts_recomputed = returned_count.is_some()
        && window_count == returned_count
        && source_window_count == returned_count
        && max_windows.is_some_and(|limit| limit <= 50)
        && returned_count
            .zip(max_windows)
            .is_some_and(|(count, limit)| count <= limit);
    let coverage_ok = receipt.get("status").and_then(Value::as_str) == Some("ready")
        && receipt.get("coverage_complete").and_then(Value::as_bool) == Some(true)
        && receipt.get("windows_read_ok").and_then(Value::as_bool) == Some(true)
        && receipt.get("counts_consistent").and_then(Value::as_bool) == Some(true)
        && counts_recomputed
        && receipt
            .get("errors")
            .and_then(Value::as_array)
            .is_some_and(Vec::is_empty)
        && receipt
            .get("incomplete_reasons")
            .and_then(Value::as_array)
            .is_some_and(Vec::is_empty)
        && receipt
            .pointer("/limits/include_windows")
            .and_then(Value::as_bool)
            == Some(true)
        && receipt
            .pointer("/limits/truncated")
            .and_then(Value::as_bool)
            == Some(false)
        && receipt
            .pointer("/permission/ax_trusted")
            .and_then(Value::as_bool)
            == Some(true)
        && receipt
            .pointer("/permission/method")
            .and_then(Value::as_str)
            == Some("AXIsProcessTrusted")
        && receipt
            .pointer("/permission/prompted")
            .and_then(Value::as_bool)
            == Some(false);
    let target_bundle_id = macos_ax_trimmed_string(target.get("bundle_id"));
    let target_pid = target.get("pid").and_then(Value::as_u64);
    let app_scope_ok = receipt.get("app_identity_valid").and_then(Value::as_bool) == Some(true)
        && receipt.get("frontmost_app").is_some_and(|app| {
            macos_ax_trimmed_string(app.get("bundle_id")) == target_bundle_id
                && app.get("pid").and_then(Value::as_u64) == target_pid
                && target_pid.is_some_and(|pid| pid > 0)
                && (macos_ax_trimmed_string(app.get("name")).is_some()
                    || macos_ax_trimmed_string(app.get("bundle_id")).is_some())
        });
    let matching_windows = windows
        .map(|windows| {
            windows
                .iter()
                .filter(|window| match target_mode {
                    "stable_ax_identifier" => {
                        let expected = macos_ax_trimmed_string(target.get("ax_identifier"));
                        macos_ax_trimmed_string(window.get("ax_identifier")) == expected
                            && window
                                .pointer("/identity/kind")
                                .and_then(Value::as_str)
                                == Some("ax_identifier")
                            && macos_ax_trimmed_string(window.pointer("/identity/value"))
                                == expected
                            && window
                                .pointer("/identity/stable_across_samples")
                                .and_then(Value::as_bool)
                                == Some(true)
                    }
                    "sample_index_with_constraints" => {
                        window.get("index").and_then(Value::as_u64)
                            == target.get("window_index").and_then(Value::as_u64)
                            && window.get("title").and_then(Value::as_str)
                                == target.get("expected_title").and_then(Value::as_str)
                            && macos_ax_trimmed_string(window.get("role"))
                                == macos_ax_trimmed_string(target.get("expected_role"))
                    }
                    _ => false,
                })
                .count()
        })
        .unwrap_or(0);
    let target_bound = matching_windows == 1;
    let captured_at = receipt.get("captured_at").and_then(Value::as_i64);
    let now = dispatch_now_secs();
    let age_ms = captured_at.and_then(|captured_at| {
        if captured_at <= 0 || captured_at > now.saturating_add(2) {
            None
        } else {
            u64::try_from(now.saturating_sub(captured_at))
                .ok()
                .map(|age| age.saturating_mul(1_000))
        }
    });
    let surface_fresh = age_ms.is_some_and(|age| age <= max_observation_age_ms);
    (
        schema_ok && coverage_ok && app_scope_ok,
        target_bound,
        surface_fresh,
        age_ms,
        receipt_sha256,
    )
}

pub struct MacosAxActionAdmissionTool;

impl MacosAxActionAdmissionTool {
    pub fn new() -> Self {
        Self
    }
}

#[async_trait]
impl McpTool for MacosAxActionAdmissionTool {
    fn name(&self) -> &'static str {
        "macos_ax_action_admission"
    }

    fn annotations(&self) -> Option<ToolAnnotations> {
        Some(ToolAnnotations::read_only())
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Preview-only macOS AX action admission. It honors owner-standing body authority without per-action prompts, but computes freshness and exact target binding from a complete macos_ax_probe receipt instead of trusting caller booleans. It never executes AX actions, requests permissions, captures pixels, or changes application state.".into(),
            input_schema: json!({
                "type": "object",
                "required": ["operation", "authority_scope", "target", "surface_receipt", "task_intent_bound"],
                "properties": {
                    "operation": {
                        "type": "string",
                        "enum": [
                            "activate_app", "focus_window", "move_window", "resize_window",
                            "scroll", "select_element", "type_text", "press_button",
                            "trash_item", "submit_form", "send_message", "permanent_delete",
                            "purchase", "permission_change", "credential_entry"
                        ]
                    },
                    "authority_scope": {
                        "type": "string",
                        "enum": ["owner_standing", "task_specific", "none"]
                    },
                    "target": {
                        "type": "object",
                        "required": ["bundle_id", "pid"],
                        "oneOf": [
                            { "required": ["ax_identifier"], "not": { "required": ["window_index"] } },
                            { "required": ["window_index", "expected_title", "expected_role"], "not": { "required": ["ax_identifier"] } }
                        ],
                        "properties": {
                            "bundle_id": { "type": "string", "minLength": 1 },
                            "pid": { "type": "integer", "minimum": 1 },
                            "ax_identifier": { "type": "string", "minLength": 1 },
                            "window_index": { "type": "integer", "minimum": 0 },
                            "expected_title": { "type": "string" },
                            "expected_role": { "type": "string", "minLength": 1 }
                        },
                        "additionalProperties": false
                    },
                    "surface_receipt": {
                        "type": "object",
                        "description": "Exact complete macos_ax_probe/v0 receipt that observed the target. Freshness and binding are recomputed locally."
                    },
                    "max_observation_age_ms": {
                        "type": "integer",
                        "minimum": 100,
                        "maximum": 30000,
                        "default": 5000
                    },
                    "task_intent_bound": { "type": "boolean" },
                    "requested_effect": {
                        "type": "string",
                        "enum": ["local_navigation", "local_content", "external_commit", "protected_boundary"]
                    }
                },
                "additionalProperties": false
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let operation = args.get("operation").and_then(Value::as_str).unwrap_or("");
        let Some((mut risk_class, mut risk_rank)) = macos_ax_action_risk(operation) else {
            return Ok(ToolResult::error("unsupported macOS AX operation"));
        };
        let requested_effect = match args.get("requested_effect") {
            None => None,
            Some(value) => match value.as_str() {
                Some(effect) if macos_ax_requested_effect_risk(Some(effect)).is_some() => {
                    Some(effect)
                }
                _ => return Ok(ToolResult::error("unsupported requested_effect")),
            },
        };
        if let Some((effect_class, effect_rank)) = macos_ax_requested_effect_risk(requested_effect) {
            if effect_rank > risk_rank {
                risk_class = effect_class;
                risk_rank = effect_rank;
            }
        }
        let authority_scope = args
            .get("authority_scope")
            .and_then(Value::as_str)
            .unwrap_or("none");
        let authority_scope_valid = matches!(
            authority_scope,
            "owner_standing" | "task_specific" | "none"
        );
        let target = args.get("target").cloned().unwrap_or(Value::Null);
        let target_exact = macos_ax_target_binding_mode(&target).is_some();
        let max_observation_age_ms = args
            .get("max_observation_age_ms")
            .and_then(Value::as_u64)
            .unwrap_or(5_000)
            .clamp(100, 30_000);
        let receipt = args.get("surface_receipt").cloned().unwrap_or(Value::Null);
        let (receipt_complete, target_bound, surface_fresh, age_ms, receipt_sha256) =
            macos_ax_probe_receipt_binding(&receipt, &target, max_observation_age_ms);
        let task_intent_bound = args
            .get("task_intent_bound")
            .and_then(Value::as_bool)
            .unwrap_or(false);

        let (decision, reason_codes): (&str, Vec<&str>) = if !authority_scope_valid {
            ("deny", vec!["unsupported_authority_scope"])
        } else if !target_exact {
            ("deny", vec!["target_not_exactly_specified"])
        } else if !receipt_complete {
            ("reobserve", vec!["semantic_surface_receipt_incomplete"])
        } else if !target_bound {
            ("reobserve", vec!["target_not_bound_by_surface_receipt"])
        } else if !surface_fresh {
            ("reobserve", vec!["semantic_surface_stale"])
        } else if authority_scope == "none" {
            ("needs_task_authority", vec!["no_owner_authority"])
        } else if risk_rank == 4 {
            ("requires_user_presence", vec!["os_protected_boundary"])
        } else if risk_rank == 3 && authority_scope != "task_specific" {
            (
                "needs_task_authority",
                vec!["consequential_effect_requires_task_specific_scope"],
            )
        } else if risk_rank >= 2 && !task_intent_bound {
            ("needs_task_intent", vec!["content_effect_not_bound_to_task"])
        } else {
            ("admit", vec!["authority_and_semantic_preconditions_satisfied"])
        };

        Ok(ToolResult::json_text(&json!({
            "schema": "macos_ax_action_admission/v1",
            "status": "preview_only",
            "execution": { "performed": false, "executor_present": false },
            "operation": operation,
            "risk": { "class": risk_class, "rank": risk_rank },
            "decision": decision,
            "reason_codes": reason_codes,
            "authority": {
                "scope": authority_scope,
                "per_action_prompt_default": false,
                "standing_authority_honored": authority_scope == "owner_standing"
            },
            "preconditions": {
                "target_exact": target_exact,
                "receipt_complete": receipt_complete,
                "target_bound": target_bound,
                "surface_fresh": surface_fresh,
                "surface_age_ms": age_ms,
                "surface_receipt_sha256": receipt_sha256,
                "task_intent_bound": task_intent_bound
            },
            "receipt_requirements": {
                "before": ["bundle_id", "pid", "unique_window_identity", "surface_receipt_sha256"],
                "after": ["exact_target_focused", "new_world_revision", "observed_postcondition"],
                "restore_foreground_when_incidental": true
            },
            "visual_evidence": { "included": false, "reason": "semantic_first_default" }
        })))
    }
}

