pub struct SemanticBusPeerConformanceTool {
    _hub: Hub,
}

impl SemanticBusPeerConformanceTool {
    pub fn new(hub: Hub) -> Self {
        Self { _hub: hub }
    }
}

#[async_trait]
impl McpTool for SemanticBusPeerConformanceTool {
    fn name(&self) -> &'static str {
        "semantic_bus_peer_conformance"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Read-only Semantic System Bus peer conformance query. \
                 It fetches one or more daemon-http /semantic-bus/runtime-conformance \
                 exports and returns a compact multi-node summary; it never restarts \
                 services, captures screenshots, injects input, mutates Palace, or \
                 writes memory graph edges."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "endpoints": {
                        "type": "array",
                        "items": { "type": "string" },
                        "minItems": 1,
                        "maxItems": 16,
                        "description": "Base daemon-http URLs such as http://127.0.0.1:7878, or full /semantic-bus/runtime-conformance URLs."
                    },
                    "endpoint": {
                        "type": "string",
                        "description": "Compatibility shortcut for a single endpoint when endpoints is omitted."
                    },
                    "include_runtime_health": {
                        "type": "boolean",
                        "default": true,
                        "description": "Ask each peer endpoint to include its local runtime health summary."
                    },
                    "timeout_ms": {
                        "type": "integer",
                        "minimum": 500,
                        "maximum": 10000,
                        "default": 2500,
                        "description": "Per-peer HTTP timeout."
                    },
                    "include_raw": {
                        "type": "boolean",
                        "default": false,
                        "description": "Include each peer's raw conformance payload. Default false keeps the summary compact."
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        Ok(ToolResult::json_text(
            &semantic_bus_peer_conformance_payload(&args).await,
        ))
    }
}

async fn semantic_bus_peer_conformance_payload(args: &Value) -> Value {
    let endpoints = semantic_bus_peer_conformance_endpoints(args);
    let include_runtime_health = args
        .get("include_runtime_health")
        .and_then(Value::as_bool)
        .unwrap_or(true);
    let include_raw = args
        .get("include_raw")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let timeout_ms = args
        .get("timeout_ms")
        .and_then(Value::as_u64)
        .unwrap_or(2_500)
        .clamp(500, 10_000);
    let now_secs = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();

    if endpoints.is_empty() {
        return semantic_bus_peer_conformance_report(
            now_secs,
            timeout_ms,
            include_runtime_health,
            Vec::new(),
        );
    }

    let client = match reqwest::Client::builder()
        .timeout(Duration::from_millis(timeout_ms))
        .user_agent("agent-bridge-semantic-bus-peer-conformance/0")
        .build()
    {
        Ok(client) => client,
        Err(e) => {
            let peers = endpoints
                .iter()
                .enumerate()
                .map(|(idx, endpoint)| {
                    semantic_bus_peer_conformance_error_row(
                        idx,
                        endpoint,
                        None,
                        "client_init_error",
                        &e.to_string(),
                    )
                })
                .collect();
            return semantic_bus_peer_conformance_report(
                now_secs,
                timeout_ms,
                include_runtime_health,
                peers,
            );
        }
    };

    let mut peers = Vec::with_capacity(endpoints.len());
    for (idx, endpoint) in endpoints.iter().enumerate() {
        peers.push(
            semantic_bus_peer_conformance_fetch(
                &client,
                idx,
                endpoint,
                include_runtime_health,
                timeout_ms,
                include_raw,
            )
            .await,
        );
    }
    semantic_bus_peer_conformance_report(now_secs, timeout_ms, include_runtime_health, peers)
}

fn semantic_bus_peer_conformance_endpoints(args: &Value) -> Vec<String> {
    let mut endpoints = Vec::new();
    if let Some(items) = args.get("endpoints").and_then(Value::as_array) {
        endpoints.extend(
            items
                .iter()
                .filter_map(Value::as_str)
                .map(str::trim)
                .filter(|s| !s.is_empty())
                .map(str::to_string),
        );
    } else if let Some(endpoint) = args
        .get("endpoint")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|s| !s.is_empty())
    {
        endpoints.push(endpoint.to_string());
    }
    endpoints.truncate(16);
    endpoints
}

async fn semantic_bus_peer_conformance_fetch(
    client: &reqwest::Client,
    idx: usize,
    endpoint: &str,
    include_runtime_health: bool,
    timeout_ms: u64,
    include_raw: bool,
) -> Value {
    let url = match semantic_bus_peer_conformance_url(endpoint, include_runtime_health, timeout_ms)
    {
        Ok(url) => url,
        Err(e) => {
            return semantic_bus_peer_conformance_error_row(idx, endpoint, None, "invalid_url", &e)
        }
    };
    let started = Instant::now();
    let response = client
        .get(&url)
        .header("Accept", "application/json")
        .send()
        .await;
    match response {
        Ok(resp) => {
            let http_status = resp.status().as_u16();
            let http_ok = resp.status().is_success();
            let content_type = resp
                .headers()
                .get("content-type")
                .and_then(|v| v.to_str().ok())
                .map(str::to_string);
            match resp.text().await {
                Ok(body) => {
                    if !http_ok {
                        return semantic_bus_peer_conformance_http_error_row(
                            idx,
                            endpoint,
                            &url,
                            "http_error",
                            http_status,
                            semantic_bus_runtime_elapsed_ms(started),
                            content_type,
                            body,
                        );
                    }
                    match serde_json::from_str::<Value>(&body) {
                        Ok(payload) => semantic_bus_peer_conformance_payload_row(
                            idx,
                            endpoint,
                            &url,
                            http_status,
                            semantic_bus_runtime_elapsed_ms(started),
                            content_type,
                            payload,
                            include_raw,
                        ),
                        Err(e) => semantic_bus_peer_conformance_http_error_row(
                            idx,
                            endpoint,
                            &url,
                            "invalid_json",
                            http_status,
                            semantic_bus_runtime_elapsed_ms(started),
                            content_type,
                            format!("response was not valid JSON: {e}"),
                        ),
                    }
                }
                Err(e) => semantic_bus_peer_conformance_http_error_row(
                    idx,
                    endpoint,
                    &url,
                    "body_error",
                    http_status,
                    semantic_bus_runtime_elapsed_ms(started),
                    content_type,
                    e.to_string(),
                ),
            }
        }
        Err(e) => semantic_bus_peer_conformance_error_row(
            idx,
            endpoint,
            Some(url),
            "unreachable",
            &e.to_string(),
        ),
    }
}

fn semantic_bus_peer_conformance_url(
    endpoint: &str,
    include_runtime_health: bool,
    timeout_ms: u64,
) -> std::result::Result<String, String> {
    let trimmed = endpoint.trim();
    let url = if trimmed.contains("/semantic-bus/runtime-conformance") {
        trimmed.to_string()
    } else {
        semantic_bus_runtime_join_url(trimmed, "/semantic-bus/runtime-conformance")?
    };
    let mut parsed =
        reqwest::Url::parse(&url).map_err(|e| format!("parse conformance URL {url}: {e}"))?;
    if !matches!(parsed.scheme(), "http" | "https") {
        return Err(format!("unsupported URL scheme: {}", parsed.scheme()));
    }
    {
        let mut qp = parsed.query_pairs_mut();
        qp.append_pair(
            "include_runtime_health",
            if include_runtime_health {
                "true"
            } else {
                "false"
            },
        );
        qp.append_pair("timeout_ms", &timeout_ms.to_string());
    }
    Ok(parsed.to_string())
}

fn semantic_bus_peer_conformance_payload_row(
    idx: usize,
    endpoint: &str,
    url: &str,
    http_status: u16,
    elapsed_ms: u64,
    content_type: Option<String>,
    payload: Value,
    include_raw: bool,
) -> Value {
    let schema = payload
        .get("schema")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let schema_ok = schema == SEMANTIC_BUS_RUNTIME_CONFORMANCE_SCHEMA;
    let verification = payload.get("verification").cloned().unwrap_or(Value::Null);
    let verdict = verification
        .get("verdict")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let summary = payload.get("summary").cloned().unwrap_or_else(|| json!({}));
    let runtime_health_summary = payload
        .get("runtime_health_summary")
        .cloned()
        .unwrap_or(Value::Null);
    let runtime_health_status = summary
        .get("runtime_health_status")
        .and_then(Value::as_str)
        .or_else(|| runtime_health_summary.get("status").and_then(Value::as_str))
        .unwrap_or("unknown");
    let runtime_health_verified = summary
        .get("runtime_health_verified")
        .and_then(Value::as_bool)
        .unwrap_or_else(|| {
            runtime_health_summary
                .get("verification")
                .and_then(|v| v.get("verdict"))
                .and_then(Value::as_str)
                == Some("verified")
        });
    let windows_slot = semantic_bus_peer_conformance_windows_slot(&payload);

    let mut row = json!({
        "peer_index": idx,
        "peer_id": semantic_bus_peer_conformance_peer_id(endpoint, url, idx),
        "endpoint": endpoint,
        "url": url,
        "ok": schema_ok,
        "status": if schema_ok { "ok" } else { "schema_mismatch" },
        "http_status": http_status,
        "elapsed_ms": elapsed_ms,
        "content_type": content_type,
        "schema": schema,
        "current_platform": payload.get("current_platform").cloned().unwrap_or(Value::Null),
        "verdict": verdict,
        "runtime_health_status": runtime_health_status,
        "runtime_health_verified": runtime_health_verified,
        "adapter_count": summary.get("adapter_count").cloned().unwrap_or(Value::Null),
        "live_ready_count": summary.get("live_ready_count").cloned().unwrap_or(Value::Null),
        "gap_count": summary.get("gap_count").cloned().unwrap_or(Value::Null),
        "windows_uia_runtime_slot": windows_slot,
        "verification": verification
    });
    if include_raw {
        if let Some(obj) = row.as_object_mut() {
            obj.insert("raw".to_string(), payload);
        }
    }
    row
}

fn semantic_bus_peer_conformance_windows_slot(payload: &Value) -> Value {
    let slot = payload
        .get("windows_uia_runtime_slot")
        .cloned()
        .unwrap_or(Value::Null);
    json!({
        "adapter_id": slot.get("adapter_id").cloned().unwrap_or(json!("windows_uia_runtime_adapter")),
        "platform": slot.get("platform").cloned().unwrap_or(Value::Null),
        "evidence_level": slot.get("evidence_level").cloned().unwrap_or(Value::Null),
        "live_status": slot.get("live_status").cloned().unwrap_or(json!("unknown")),
        "tool": slot.get("tool").cloned().unwrap_or(Value::Null)
    })
}

fn semantic_bus_peer_conformance_peer_id(endpoint: &str, url: &str, idx: usize) -> String {
    semantic_bus_runtime_url_authority(endpoint)
        .or_else(|| semantic_bus_runtime_url_authority(url))
        .map(|authority| format!("peer:{authority}"))
        .unwrap_or_else(|| format!("peer:{idx}"))
}

fn semantic_bus_peer_conformance_http_error_row(
    idx: usize,
    endpoint: &str,
    url: &str,
    status: &str,
    http_status: u16,
    elapsed_ms: u64,
    content_type: Option<String>,
    error_or_body: String,
) -> Value {
    json!({
        "peer_index": idx,
        "peer_id": semantic_bus_peer_conformance_peer_id(endpoint, url, idx),
        "endpoint": endpoint,
        "url": url,
        "ok": false,
        "status": status,
        "http_status": http_status,
        "elapsed_ms": elapsed_ms,
        "content_type": content_type,
        "error": error_or_body.chars().take(512).collect::<String>(),
        "recover": "retry"
    })
}

fn semantic_bus_peer_conformance_error_row(
    idx: usize,
    endpoint: &str,
    url: Option<String>,
    status: &str,
    error: &str,
) -> Value {
    let url_ref = url.as_deref().unwrap_or(endpoint);
    json!({
        "peer_index": idx,
        "peer_id": semantic_bus_peer_conformance_peer_id(endpoint, url_ref, idx),
        "endpoint": endpoint,
        "url": url,
        "ok": false,
        "status": status,
        "error": error,
        "recover": if status == "invalid_url" { "replan" } else { "retry" }
    })
}

fn semantic_bus_peer_conformance_report(
    now_secs: u64,
    timeout_ms: u64,
    include_runtime_health: bool,
    peers: Vec<Value>,
) -> Value {
    let peer_count = peers.len() as u64;
    let ok_count = peers
        .iter()
        .filter(|row| row.get("ok").and_then(Value::as_bool) == Some(true))
        .count() as u64;
    let verified_count = peers
        .iter()
        .filter(|row| {
            row.get("ok").and_then(Value::as_bool) == Some(true)
                && row.get("verdict").and_then(Value::as_str) == Some("verified")
        })
        .count() as u64;
    let degraded_count = peers
        .iter()
        .filter(|row| {
            row.get("ok").and_then(Value::as_bool) == Some(true)
                && row.get("verdict").and_then(Value::as_str) == Some("degraded")
        })
        .count() as u64;
    let not_checked_count = peers
        .iter()
        .filter(|row| {
            row.get("ok").and_then(Value::as_bool) == Some(true)
                && row.get("verdict").and_then(Value::as_str) == Some("not_checked")
        })
        .count() as u64;
    let error_count = peer_count.saturating_sub(ok_count);
    let windows_runtime_ready_count = peers
        .iter()
        .filter(|row| {
            row.get("windows_uia_runtime_slot")
                .and_then(|slot| slot.get("live_status"))
                .and_then(Value::as_str)
                == Some("ready")
        })
        .count() as u64;
    let verdict = if peer_count == 0 {
        "blocked"
    } else if error_count == 0 && verified_count == peer_count {
        "verified"
    } else if ok_count > 0 {
        "degraded"
    } else {
        "not_verified"
    };

    json!({
        "schema": SEMANTIC_BUS_PEER_CONFORMANCE_SCHEMA,
        "generated_at_unix": now_secs,
        "read_only": true,
        "live_checks_executed": peer_count > 0,
        "timeout_ms": timeout_ms,
        "request": {
            "include_runtime_health": include_runtime_health,
            "endpoint_count": peer_count
        },
        "summary": {
            "peer_count": peer_count,
            "ok_count": ok_count,
            "verified_count": verified_count,
            "degraded_count": degraded_count,
            "not_checked_count": not_checked_count,
            "error_count": error_count,
            "windows_runtime_ready_count": windows_runtime_ready_count
        },
        "peers": peers,
        "verification": {
            "verdict": verdict,
            "reason": if peer_count == 0 {
                "no peer endpoints were supplied"
            } else if error_count == 0 && verified_count == peer_count {
                "all queried peers returned verified runtime conformance"
            } else if ok_count > 0 {
                "at least one peer returned a conformance snapshot, but not every peer is verified"
            } else {
                "no peer returned a valid runtime conformance snapshot"
            },
            "recover": if verdict == "verified" {
                "proceed"
            } else if ok_count > 0 {
                "retry"
            } else {
                "replan"
            }
        },
        "next_recommended_slice": {
            "id": if windows_runtime_ready_count > 0 {
                "ssb-16-cross-node-windows-uia-validation"
            } else {
                "ssb-16-windows-uia-runtime-host"
            },
            "reason": if windows_runtime_ready_count > 0 {
                "at least one peer reports a ready Windows UIA runtime slot; validate semantic snapshot/verify evidence next"
            } else {
                "peer query is live, but Windows UIA remains unavailable until a Windows host exports runtime evidence"
            }
        }
    })
}

// ===========================================================================
//                            vision_grounding_ocr
// ===========================================================================

pub struct VisionGroundingOcrTool {
    _hub: Hub,
}

impl VisionGroundingOcrTool {
    pub fn new(hub: Hub) -> Self {
        Self { _hub: hub }
    }
}

#[async_trait]
impl McpTool for VisionGroundingOcrTool {
    fn name(&self) -> &'static str {
        "vision_grounding_ocr"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Run the non-mutating OCR vision grounding reference runner. \
                 It reads an existing image plus desktop_snapshot metadata and returns \
                 `vision_grounding_result.v0` candidates; it never clicks, types, takes \
                 screenshots, or controls the desktop."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "cwd": {
                        "type": "string",
                        "description": "Workspace/repo root used to resolve scripts/vision_grounding_ocr.py. Defaults to the MCP process cwd, then the build-time repo root."
                    },
                    "script_path": {
                        "type": "string",
                        "description": "Optional explicit vision_grounding_ocr.py path. Use mainly for tests or alternate checkouts."
                    },
                    "image": {
                        "type": "string",
                        "description": "Existing PNG/JPEG image path to OCR. The tool does not capture screenshots."
                    },
                    "engine": {
                        "type": "string",
                        "enum": ["tesseract", "fixture-tsv", "none"],
                        "default": "tesseract"
                    },
                    "fixture_tsv": {
                        "type": "string",
                        "description": "TSV fixture path when engine=fixture-tsv."
                    },
                    "request_id": { "type": "string" },
                    "snapshot_id": {
                        "type": "string",
                        "description": "desktop_snapshot snapshot id associated with this image."
                    },
                    "snapshot_hash": {
                        "type": "string",
                        "description": "Hash of the source desktop_snapshot payload."
                    },
                    "snapshot_schema": {
                        "type": "string",
                        "default": "desktop_snapshot/v0.5"
                    },
                    "snapshot_captured_at": { "type": "string" },
                    "image_hash": { "type": "string" },
                    "image_kind": {
                        "type": "string",
                        "enum": ["desktop", "output", "window"],
                        "default": "window"
                    },
                    "coordinate_space": {
                        "type": "string",
                        "enum": ["desktop", "output", "window"],
                        "default": "window"
                    },
                    "output": { "type": "string" },
                    "crop_rect": {
                        "type": "string",
                        "description": "Optional x,y,width,height crop rect."
                    },
                    "crop_image": {
                        "type": "boolean",
                        "default": false,
                        "description": "Actually crop the OCR input to crop_rect before OCR (not just translate coords). Fixes small-UI-text misses on full-frame images (#1803). Output coords are mapped back to coordinate_space."
                    },
                    "upscale": {
                        "type": "number",
                        "minimum": 1.0,
                        "maximum": 8.0,
                        "default": 1.0,
                        "description": "LANCZOS upscale factor for the OCR input so sub-~30px UI glyphs clear tesseract's resolution floor; output coords are divided back by this factor. Pair with crop_rect + crop_image on a small region (e.g. a button bbox from desktop_snapshot)."
                    },
                    "psm": {
                        "type": "integer",
                        "minimum": 0,
                        "maximum": 13,
                        "description": "tesseract page segmentation mode (7=single text line, 8=single word — good for a cropped button/label)."
                    },
                    "window_id": { "type": "integer" },
                    "pid": { "type": "integer" },
                    "app_id": { "type": "string" },
                    "title_hash": { "type": "string" },
                    "window_rect": {
                        "type": "string",
                        "description": "Optional x,y,width,height target window rect."
                    },
                    "task": { "type": "string", "default": "find text" },
                    "hint_text": { "type": "string" },
                    "hint_role": { "type": "string", "default": "unknown" },
                    "language": { "type": "string", "default": "auto" },
                    "engine_timeout_secs": {
                        "type": "number",
                        "minimum": 0.5,
                        "maximum": 60.0,
                        "default": 8.0,
                        "description": "Timeout forwarded to the OCR engine."
                    },
                    "timeout_ms": {
                        "type": "integer",
                        "minimum": 1000,
                        "maximum": 90000,
                        "default": 20000,
                        "description": "Milliseconds before the wrapper process is killed."
                    }
                },
                "required": ["image", "snapshot_id", "snapshot_hash"]
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let image = match required_str_arg(&args, "image") {
            Ok(v) => v,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        let snapshot_id = match required_str_arg(&args, "snapshot_id") {
            Ok(v) => v,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        let snapshot_hash = match required_str_arg(&args, "snapshot_hash") {
            Ok(v) => v,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        let engine = args
            .get("engine")
            .and_then(|v| v.as_str())
            .unwrap_or("tesseract");
        if !matches!(engine, "tesseract" | "fixture-tsv" | "none") {
            return Ok(ToolResult::error(
                "engine must be tesseract, fixture-tsv, or none",
            ));
        }
        let timeout_ms = args
            .get("timeout_ms")
            .and_then(|v| v.as_u64())
            .unwrap_or(20_000)
            .clamp(1_000, 90_000);
        let engine_timeout_secs = args
            .get("engine_timeout_secs")
            .and_then(|v| v.as_f64())
            .unwrap_or(8.0)
            .clamp(0.5, 60.0);

        let cwd = args.get("cwd").and_then(|v| v.as_str()).map(PathBuf::from);
        let script = vision_grounding_ocr_script_path(&args, cwd.as_ref());
        if !script.exists() {
            return Ok(vision_grounding_ocr_error(json!({
                "code": "script_missing",
                "message": format!("vision_grounding_ocr.py not found at {}", script.display()),
                "hint": "pass script_path or run from the Agent-Bridge repo root"
            })));
        }

        let mut cmd = killable_command(
            std::env::var("PYTHON")
                .ok()
                .filter(|s| !s.trim().is_empty())
                .unwrap_or_else(|| "python3".to_string()),
        );
        cmd.arg(&script)
            .arg("--compact")
            .arg("--image")
            .arg(image)
            .arg("--engine")
            .arg(engine)
            .arg("--snapshot-id")
            .arg(snapshot_id)
            .arg("--snapshot-hash")
            .arg(snapshot_hash)
            .arg("--timeout")
            .arg(engine_timeout_secs.to_string());

        push_optional_str_arg(&mut cmd, &args, "fixture_tsv", "--fixture-tsv");
        push_optional_str_arg(&mut cmd, &args, "request_id", "--request-id");
        push_optional_str_arg(&mut cmd, &args, "snapshot_schema", "--snapshot-schema");
        push_optional_str_arg(
            &mut cmd,
            &args,
            "snapshot_captured_at",
            "--snapshot-captured-at",
        );
        push_optional_str_arg(&mut cmd, &args, "image_hash", "--image-hash");
        push_optional_str_arg(&mut cmd, &args, "image_kind", "--image-kind");
        push_optional_str_arg(&mut cmd, &args, "coordinate_space", "--coordinate-space");
        push_optional_str_arg(&mut cmd, &args, "output", "--output");
        push_optional_str_arg(&mut cmd, &args, "crop_rect", "--crop-rect");
        if args
            .get("crop_image")
            .and_then(|v| v.as_bool())
            .unwrap_or(false)
        {
            cmd.arg("--crop-image");
        }
        // upscale is a float; push_optional_value_arg only handles ints/strings.
        if let Some(u) = args.get("upscale").and_then(|v| v.as_f64()) {
            if (u - 1.0).abs() > 1e-9 {
                cmd.arg("--upscale").arg(u.to_string());
            }
        }
        push_optional_value_arg(&mut cmd, &args, "psm", "--psm");
        push_optional_value_arg(&mut cmd, &args, "window_id", "--window-id");
        push_optional_value_arg(&mut cmd, &args, "pid", "--pid");
        push_optional_str_arg(&mut cmd, &args, "app_id", "--app-id");
        push_optional_str_arg(&mut cmd, &args, "title_hash", "--title-hash");
        push_optional_str_arg(&mut cmd, &args, "window_rect", "--window-rect");
        push_optional_str_arg(&mut cmd, &args, "task", "--task");
        push_optional_str_arg(&mut cmd, &args, "hint_text", "--hint-text");
        push_optional_str_arg(&mut cmd, &args, "hint_role", "--hint-role");
        push_optional_str_arg(&mut cmd, &args, "language", "--language");

        cmd.stdout(std::process::Stdio::piped());
        cmd.stderr(std::process::Stdio::piped());
        if let Some(cwd) = cwd {
            cmd.current_dir(cwd);
        }

        let started = Instant::now();
        let output =
            match tokio::time::timeout(Duration::from_millis(timeout_ms), cmd.output()).await {
                Err(_) => {
                    return Ok(vision_grounding_ocr_error(json!({
                        "code": "timeout",
                        "message": format!("vision_grounding_ocr exceeded {timeout_ms} ms"),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Err(e)) => {
                    return Ok(vision_grounding_ocr_error(json!({
                        "code": "spawn_failed",
                        "message": e.to_string(),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Ok(output)) => output,
            };
        let duration_ms = started.elapsed().as_millis() as u64;
        let (stdout, stdout_truncated) = lossy_truncate(&output.stdout);
        let (stderr, stderr_truncated) = lossy_truncate(&output.stderr);

        if !output.status.success() {
            return Ok(vision_grounding_ocr_error(json!({
                "code": "script_failed",
                "exit_code": output.status.code().unwrap_or(-1),
                "stdout": stdout,
                "stderr": stderr,
                "duration_ms": duration_ms,
                "truncated": stdout_truncated || stderr_truncated
            })));
        }

        match serde_json::from_str::<Value>(&stdout) {
            Ok(mut payload) => {
                if let Some(obj) = payload.as_object_mut() {
                    obj.insert(
                        "mcp_wrapper".to_string(),
                        json!({
                            "tool": self.name(),
                            "read_only": true,
                            "engine": engine,
                            "duration_ms": duration_ms,
                            "stderr": stderr,
                            "stderr_truncated": stderr_truncated
                        }),
                    );
                }
                Ok(ToolResult::json_text(&payload))
            }
            Err(e) => Ok(vision_grounding_ocr_error(json!({
                "code": "invalid_json",
                "message": e.to_string(),
                "stdout": stdout,
                "stderr": stderr,
                "duration_ms": duration_ms,
                "truncated": stdout_truncated || stderr_truncated
            }))),
        }
    }
}

fn required_str_arg(args: &Value, key: &str) -> std::result::Result<String, String> {
    match args.get(key).and_then(|v| v.as_str()) {
        Some(v) if !v.trim().is_empty() => Ok(v.to_string()),
        _ => Err(format!("missing or empty '{key}'")),
    }
}

fn push_optional_str_arg(cmd: &mut TokioCommand, args: &Value, key: &str, flag: &str) {
    if let Some(value) = args.get(key).and_then(|v| v.as_str()) {
        if !value.trim().is_empty() {
            cmd.arg(flag).arg(value);
        }
    }
}

fn push_optional_value_arg(cmd: &mut TokioCommand, args: &Value, key: &str, flag: &str) {
    if let Some(value) = args.get(key) {
        if let Some(n) = value.as_i64() {
            cmd.arg(flag).arg(n.to_string());
        } else if let Some(s) = value.as_str() {
            if !s.trim().is_empty() {
                cmd.arg(flag).arg(s);
            }
        }
    }
}

fn vision_grounding_ocr_script_path(args: &Value, cwd: Option<&PathBuf>) -> PathBuf {
    if let Some(path) = args.get("script_path").and_then(|v| v.as_str()) {
        return PathBuf::from(path);
    }
    if let Ok(path) = std::env::var("AGENT_BRIDGE_VISION_GROUNDING_OCR_SCRIPT") {
        if !path.trim().is_empty() {
            return PathBuf::from(path);
        }
    }
    if let Some(cwd) = cwd {
        let path = cwd.join("scripts/vision_grounding_ocr.py");
        if path.exists() {
            return path;
        }
    }
    if let Ok(cwd) = std::env::current_dir() {
        let path = cwd.join("scripts/vision_grounding_ocr.py");
        if path.exists() {
            return path;
        }
    }
    if let Some(path) = installed_runtime_script_path("vision_grounding_ocr.py") {
        return path;
    }
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../scripts/vision_grounding_ocr.py")
}

fn vision_grounding_ocr_error(error: Value) -> ToolResult {
    let mut result = ToolResult::json_text(&json!({
        "schema": "vision_grounding_ocr_mcp_error.v0",
        "status": "error",
        "error": error,
    }));
    result.is_error = true;
    result
}

// ===========================================================================
//                              desktop_action
// ===========================================================================

pub struct DesktopActionTool {
    hub: Hub,
}

impl DesktopActionTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for DesktopActionTool {
    fn name(&self) -> &'static str {
        "desktop_action"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Gated Linux desktop input injection (ISOLATED-ONLY MVP). Wraps \
                 scripts/desktop_action.py. Safe by construction: this MCP surface NEVER \
                 touches the real host desktop. An action runs only as (a) dry_run=true \
                 (logs intent + audits, injects nothing), or (b) isolated — a nested \
                 compositor addressed by a non-host `display` plus its `swaysock`, where \
                 absolute moveto/click go through the sway-IPC backend (which itself \
                 refuses physical-output sockets). Host injection stays closed by default; \
                 set confirm_host:true to instead stage a single-use, TTL-bounded pending \
                 token (executed only by a subsequent human-approved desktop_confirm) — host \
                 injection never happens inline. Every call is audited to desktop_action_audit.jsonl."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "action": {
                        "type": "string",
                        "enum": ["type", "key", "move", "moveto", "click", "scroll"],
                        "description": "type/key need `text`; moveto needs x,y; move needs dx,dy; scroll needs dy[,dx]; click takes optional `button`."
                    },
                    "text": { "type": "string", "description": "For type (literal text) or key (keysym, e.g. Return, ctrl+c)." },
                    "x": { "type": "integer", "description": "Absolute X for moveto (nested compositor coords)." },
                    "y": { "type": "integer", "description": "Absolute Y for moveto." },
                    "dx": { "type": "integer", "description": "Relative X for move, or horizontal scroll." },
                    "dy": { "type": "integer", "description": "Relative Y for move, or vertical scroll." },
                    "button": { "type": "string", "enum": ["left", "right", "middle"], "default": "left", "description": "Mouse button for click." },
                    "display": { "type": "string", "description": "Target WAYLAND_DISPLAY. Must be a nested (non-host) display for any real injection." },
                    "swaysock": { "type": "string", "description": "Nested sway IPC socket; required (with a non-host display) for any non-dry-run injection. Enables the isolated sway-IPC absolute backend." },
                    "dry_run": { "type": "boolean", "default": false, "description": "When true, log intent + audit but inject nothing. Allowed against any target." },
                    "confirm_host": { "type": "boolean", "default": false, "description": "Host target only: do not inject; stage a single-use pending token + on-screen notify for a two-phase human-approved confirm (then call desktop_confirm). Default false keeps host injection closed." },
                    "use_grant": { "type": "boolean", "default": false, "description": "Host target only: inject directly IF a human-minted capability grant (scripts/desktop_grant.py) covers this action. Default false; no covering grant => denied. Trades per-action confirm for a bounded (ttl/max-uses/scope), revocable window (path C)." },
                    "cwd": { "type": "string", "description": "Repo root to resolve scripts/desktop_action.py." },
                    "script_path": { "type": "string", "description": "Explicit desktop_action.py path (tests / alternate checkouts)." },
                    "timeout_ms": { "type": "integer", "minimum": 1000, "maximum": 30000, "default": 10000, "description": "Milliseconds before the action process is killed." }
                    ,"embodiment_intent_id": { "type": "string", "minLength": 1, "maxLength": 128, "description": "Optional explicit embodiment intent reference. Records receipt linkage only; it grants no execution authority." }
                },
                "required": ["action"]
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let action = match args.get("action").and_then(|v| v.as_str()) {
            Some(a) if ["type", "key", "move", "moveto", "click", "scroll"].contains(&a) => {
                a.to_string()
            }
            Some(a) => {
                return Ok(desktop_action_error(json!({
                    "code": "bad_action",
                    "message": format!("unknown action {a}")
                })));
            }
            None => {
                return Ok(desktop_action_error(json!({
                    "code": "missing_action",
                    "message": "`action` is required"
                })));
            }
        };
        let timeout_ms = args
            .get("timeout_ms")
            .and_then(|v| v.as_u64())
            .unwrap_or(10_000)
            .clamp(1_000, 30_000);
        let dry_run = args
            .get("dry_run")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let display = args.get("display").and_then(|v| v.as_str());
        let swaysock = args.get("swaysock").and_then(|v| v.as_str());
        let embodiment_intent_id = args
            .get("embodiment_intent_id")
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|id| !id.is_empty())
            .map(str::to_string);

        // SAFETY (isolated-only MVP): this surface never touches the host desktop.
        // Allowed iff dry_run, or isolated = a non-host display WITH its swaysock.
        let host_display = std::env::var("AB_HOST_WAYLAND_DISPLAY")
            .ok()
            .filter(|s| !s.trim().is_empty())
            .unwrap_or_else(|| "wayland-1".to_string());
        let confirm_host = args
            .get("confirm_host")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let use_grant = args
            .get("use_grant")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let is_isolated = swaysock.map(|s| !s.is_empty()).unwrap_or(false)
            && display
                .map(|d| !d.is_empty() && d != host_display)
                .unwrap_or(false);
        // A host action is refused by default. Two opt-in host paths: confirm_host stages a
        // single-use pending token for a human-approved desktop_confirm (path A); use_grant
        // injects directly IF a human-minted capability grant covers it (path C). Neither
        // ever passes --confirm; host injection is never silent/inline.
        let host_target = !dry_run && !is_isolated;
        if host_target && !confirm_host && !use_grant {
            // Anti-laundering: a host action that the MCP refuses to inject did
            // NOT take effect — stamp it not_verified so it can never read as a
            // silent success on the event spine.
            record_desktop_action_event(
                &self.hub,
                &action,
                "refused",
                false,
                "host_mutation_not_exposed",
                json!({ "mode": "refused", "host_target": true, "embodiment_intent_id": embodiment_intent_id }),
            )
            .await;
            return Ok(desktop_action_error(json!({
                "code": "host_mutation_not_exposed",
                "message": "this MCP injects only dry_run or isolated (non-host display + swaysock) \
                            actions; for a host action set confirm_host:true (two-phase confirm) or \
                            use_grant:true (a human-minted capability grant must cover it)",
                "hint": "set dry_run:true, provide a nested `display` (!= host) and its `swaysock`, \
                         set confirm_host:true, or set use_grant:true with a desktop_grant.py grant"
            })));
        }

        let need_text = matches!(action.as_str(), "type" | "key");
        let text = args.get("text").and_then(|v| v.as_str());
        if need_text && text.map(|t| t.is_empty()).unwrap_or(true) {
            return Ok(desktop_action_error(json!({
                "code": "missing_text",
                "message": format!("action {action} requires a non-empty `text`")
            })));
        }

        let cwd = args.get("cwd").and_then(|v| v.as_str()).map(PathBuf::from);
        let script = desktop_action_script_path(&args, cwd.as_ref());
        if !script.exists() {
            return Ok(desktop_action_error(json!({
                "code": "script_missing",
                "message": format!("desktop_action.py not found at {}", script.display()),
                "hint": "pass script_path or run from the Agent-Bridge repo root"
            })));
        }

        let mut cmd = killable_command(
            std::env::var("PYTHON")
                .ok()
                .filter(|s| !s.trim().is_empty())
                .unwrap_or_else(|| "python3".to_string()),
        );
        cmd.arg(&script).arg(&action);
        match action.as_str() {
            "type" | "key" => {
                cmd.arg(text.unwrap_or(""));
            }
            "moveto" => {
                let x = args.get("x").and_then(|v| v.as_i64()).unwrap_or(0);
                let y = args.get("y").and_then(|v| v.as_i64()).unwrap_or(0);
                cmd.arg(x.to_string()).arg(y.to_string());
            }
            "move" => {
                let dx = args.get("dx").and_then(|v| v.as_i64()).unwrap_or(0);
                let dy = args.get("dy").and_then(|v| v.as_i64()).unwrap_or(0);
                cmd.arg(dx.to_string()).arg(dy.to_string());
            }
            "scroll" => {
                let dy = args.get("dy").and_then(|v| v.as_i64()).unwrap_or(0);
                let dx = args.get("dx").and_then(|v| v.as_i64()).unwrap_or(0);
                cmd.arg(dy.to_string()).arg(dx.to_string());
            }
            "click" => {
                if let Some(btn) = args.get("button").and_then(|v| v.as_str()) {
                    cmd.arg(btn);
                }
            }
            _ => {}
        }
        if let Some(d) = display {
            cmd.arg("--display").arg(d);
        }
        if let Some(s) = swaysock {
            cmd.arg("--swaysock").arg(s);
        }
        if dry_run {
            cmd.arg("--dry-run");
        }
        if host_target && use_grant {
            // Path C: inject directly IF a human-minted capability grant covers it.
            cmd.arg("--use-grant");
        } else if host_target && confirm_host {
            // Path A phase 1: stage a pending token, inject NOTHING; execution waits for a
            // human-approved desktop_confirm(token).
            cmd.arg("--request-host-confirm");
        }
        // NOTE: --confirm / --i-understand-this-touches-the-real-desktop are NEVER passed by
        // this MCP surface. Host injection is reachable only via a human-approved confirm
        // token (path A) or a human-minted grant (path C), never silent/inline.
        cmd.stdout(std::process::Stdio::piped());
        cmd.stderr(std::process::Stdio::piped());
        if let Some(cwd) = cwd {
            cmd.current_dir(cwd);
        }

        let started = Instant::now();
        let output =
            match tokio::time::timeout(Duration::from_millis(timeout_ms), cmd.output()).await {
                Err(_) => {
                    return Ok(desktop_action_error(json!({
                        "code": "timeout",
                        "message": format!("desktop_action exceeded {timeout_ms} ms"),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Err(e)) => {
                    return Ok(desktop_action_error(json!({
                        "code": "spawn_failed",
                        "message": e.to_string(),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Ok(output)) => output,
            };
        let duration_ms = started.elapsed().as_millis() as u64;
        let (stdout, stdout_truncated) = lossy_truncate(&output.stdout);
        let (stderr, stderr_truncated) = lossy_truncate(&output.stderr);

        let mode = if dry_run {
            "dry-run"
        } else if !host_target {
            "isolated"
        } else if use_grant {
            "host-grant"
        } else {
            "pending-host-confirm"
        };
        let ok = output.status.success();
        // Capture the error text for the event before `stderr` is moved into the
        // mcp_wrapper payload below.
        let event_err = if ok { String::new() } else { stderr.clone() };

        // desktop_action.py prints a JSON record; nonzero exit = blocked/error.
        match serde_json::from_str::<Value>(&stdout) {
            Ok(mut payload) => {
                if let Some(obj) = payload.as_object_mut() {
                    obj.insert(
                        "mcp_wrapper".to_string(),
                        json!({
                            "tool": self.name(),
                            "read_only": false,
                            "mode": mode,
                            "host_protected": true,
                            "duration_ms": duration_ms,
                            "exit_code": output.status.code().unwrap_or(-1),
                            "stderr": stderr,
                            "stderr_truncated": stderr_truncated
                        }),
                    );
                    let effect_verification = crate::semantic_event::classify_action(
                        mode,
                        ok,
                        &event_err,
                    );
                    let verification_reason = if effect_verification.status
                        == crate::semantic_event::VerdictStatus::Unknown
                    {
                        if matches!(mode, "dry-run" | "pending-host-confirm") {
                            "desktop action was not injected by design; no effect readback"
                        } else {
                            "desktop action was dispatched; resulting UI state was not read back"
                        }
                    } else if event_err.is_empty() {
                        "desktop action was not completed; effect was not verified"
                    } else {
                        "desktop action failed or was blocked; effect was not verified"
                    };
                    obj.insert(
                        "effect_verification".to_string(),
                        crate::semantic_event::effect_verification(
                            effect_verification.status,
                            verification_reason,
                        ),
                    );
                }
                // SSB Phase-1 typed event spine: stamp the verify-first verdict
                // for this injection AT ACTION TIME (Unknown on success — no
                // readback; NotVerified on a failed/blocked injection).
                record_desktop_action_event(
                    &self.hub,
                    &action,
                    mode,
                    ok,
                    &event_err,
                    json!({ "mode": mode, "dry_run": dry_run, "exit_code": output.status.code().unwrap_or(-1), "embodiment_intent_id": embodiment_intent_id }),
                )
                .await;
                let mut result = ToolResult::json_text(&payload);
                if !ok {
                    result.is_error = true;
                }
                Ok(result)
            }
            Err(e) => Ok(desktop_action_error(json!({
                "code": "invalid_json",
                "message": e.to_string(),
                "stdout": stdout,
                "stderr": stderr,
                "exit_code": output.status.code().unwrap_or(-1),
                "duration_ms": duration_ms,
                "truncated": stdout_truncated || stderr_truncated
            }))),
        }
    }
}

fn desktop_action_script_path(args: &Value, cwd: Option<&PathBuf>) -> PathBuf {
    if let Some(path) = args.get("script_path").and_then(|v| v.as_str()) {
        return PathBuf::from(path);
    }
    if let Ok(path) = std::env::var("AGENT_BRIDGE_DESKTOP_ACTION_SCRIPT") {
        if !path.trim().is_empty() {
            return PathBuf::from(path);
        }
    }
    if let Some(cwd) = cwd {
        let path = cwd.join("scripts/desktop_action.py");
        if path.exists() {
            return path;
        }
    }
    if let Ok(cwd) = std::env::current_dir() {
        let path = cwd.join("scripts/desktop_action.py");
        if path.exists() {
            return path;
        }
    }
    if let Some(path) = installed_runtime_script_path("desktop_action.py") {
        return path;
    }
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../scripts/desktop_action.py")
}

fn desktop_action_error(error: Value) -> ToolResult {
    let mut result = ToolResult::json_text(&json!({
        "schema": "desktop_action_mcp_error.v0",
        "status": "error",
        "error": error,
    }));
    result.is_error = true;
    result
}

/// SSB Phase-1 typed event spine: emit a verify-first semantic event for a
/// `desktop_action` outcome AT ACTION TIME. Best-effort — a telemetry write must
/// never fail the action. The verdict records whether input was actually injected
/// without readback (Unknown), refused/failed (NotVerified — the anti-laundering
/// signal), or intentionally not injected in dry-run/pending modes (Unknown).
async fn record_desktop_action_event(
    hub: &Hub,
    action: &str,
    mode: &str,
    ok: bool,
    err_msg: &str,
    facts: Value,
) {
    if let Some(store) = &hub.store {
        let verdict = crate::semantic_event::classify_action(mode, ok, err_msg);
        // SSB unified contract: same Object/Affordance vocabulary as browser_click.
        // Risk tracks how close the mode gets to real host mutation.
        let risk_level = match mode {
            "dry-run" => "low",
            "isolated" => "medium",
            _ => "high", // host-grant / pending-host-confirm / refused
        };
        let object = crate::semantic_event::SemanticObject {
            object_type: "desktop_input_surface".to_string(),
            source_adapter: "desktop".to_string(),
            label: None,
            object_id: None,
        };
        let affordance = crate::semantic_event::Affordance {
            action_type: action.to_string(),
            risk_level: risk_level.to_string(),
            requires_gate: true,
            expected_effect: Some(format!("inject {action} into the {mode} target")),
        };
        let ev = crate::semantic_event::SemanticEvent {
            ts: dispatch_now_secs(),
            actor: "mcp".to_string(),
            source: "desktop".to_string(),
            action: action.to_string(),
            target: None,
            object,
            affordance,
            verdict,
            facts,
        };
        if let Err(e) = store.record_semantic_event(ev.to_record()).await {
            tracing::debug!(error = %e, "record_semantic_event (desktop_action) failed");
        }
    }
}

// ===========================================================================
//   Linux Computer Use — L2 semantic AT-SPI invoke (desktop_invoke)
// ===========================================================================

pub struct DesktopInvokeTool {
    _hub: Hub,
}

impl DesktopInvokeTool {
    pub fn new(hub: Hub) -> Self {
        Self { _hub: hub }
    }
}

#[async_trait]
impl McpTool for DesktopInvokeTool {
    fn name(&self) -> &'static str {
        "desktop_invoke"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Gated Linux desktop SEMANTIC input via AT-SPI (ISOLATED-ONLY MVP). \
                 Wraps scripts/desktop_invoke.py. Finds an accessible by app/role/name and \
                 calls its AT-SPI action (e.g. a button's \"click\") — no screenshot, no OCR, \
                 no coordinates; the L2 dual of desktop_snapshot's bus-first read. Safe by \
                 construction: AT-SPI is a session-global bus, so isolation is by PROCESS — an \
                 invoke runs only as (a) dry_run=true (locates + audits, invokes nothing), or \
                 (b) isolated — `cage_pid` set to a nested compositor whose process subtree owns \
                 the target accessible. Host-app invoke stays closed by default; set \
                 confirm_host:true to instead mint a single-use, TTL-bounded pending token \
                 (executed only by a subsequent human-approved desktop_confirm) — host mutation \
                 never happens inline. Every call is audited to desktop_invoke_audit.jsonl."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "app": { "type": "string", "description": "Application name substring (e.g. 'firefox')." },
                    "role": { "type": "string", "description": "AT-SPI role-name substring (e.g. 'button', 'menu item'). Note GTK buttons report 'button', not 'push button'." },
                    "name": { "type": "string", "description": "Accessible name/label substring (e.g. 'Save')." },
                    "nth": { "type": "integer", "minimum": 0, "default": 0, "description": "Which match if several (0-based)." },
                    "action": { "type": "string", "description": "AT-SPI action name to invoke; default auto-picks click/press/activate/first." },
                    "cage_pid": { "type": "integer", "description": "Nested compositor PID; the target accessible's app PID must be its descendant for an isolated (non-dry-run) invoke." },
                    "wait": { "type": "number", "minimum": 0, "maximum": 30, "default": 4.0, "description": "Seconds to poll for the accessible to appear (a11y subtree can lag app registration)." },
                    "dry_run": { "type": "boolean", "default": false, "description": "When true, locate + log intent but invoke nothing. Allowed against any target." },
                    "confirm_host": { "type": "boolean", "default": false, "description": "Host target only: do not invoke; mint a single-use pending token + on-screen notify for a two-phase human-approved confirm (then call desktop_confirm). Default false keeps host invoke closed." },
                    "use_grant": { "type": "boolean", "default": false, "description": "Host target only: invoke directly IF a human-minted capability grant (scripts/desktop_grant.py) covers this app/action. Default false; no covering grant => denied. Trades per-action confirm for a bounded (ttl/max-uses/scope), revocable window (path C)." },
                    "cwd": { "type": "string", "description": "Repo root to resolve scripts/desktop_invoke.py." },
                    "script_path": { "type": "string", "description": "Explicit desktop_invoke.py path (tests / alternate checkouts)." },
                    "timeout_ms": { "type": "integer", "minimum": 1000, "maximum": 30000, "default": 10000, "description": "Milliseconds before the invoke process is killed." }
                    ,"observation_ref": {
                        "type": "object",
                        "description": "Required for every non-dry-run invoke. Copy from desktop_snapshot semantic output; stale or malformed observations are rejected before dispatch.",
                        "properties": {
                            "observation_id": { "type": "string", "minLength": 1 },
                            "content_sha256": { "type": "string", "pattern": "^[0-9a-f]{64}$" },
                            "captured_at_unix_ms": { "type": "integer", "minimum": 1 },
                            "max_age_ms": { "type": "integer", "minimum": 100, "maximum": 300000 }
                        },
                        "required": ["observation_id", "content_sha256", "captured_at_unix_ms", "max_age_ms"]
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let app = args.get("app").and_then(|v| v.as_str());
        let role = args.get("role").and_then(|v| v.as_str());
        let name = args.get("name").and_then(|v| v.as_str());
        if app.map(|s| s.is_empty()).unwrap_or(true)
            && role.map(|s| s.is_empty()).unwrap_or(true)
            && name.map(|s| s.is_empty()).unwrap_or(true)
        {
            return Ok(desktop_invoke_error(json!({
                "code": "missing_selector",
                "message": "at least one of `app`, `role`, or `name` is required"
            })));
        }
        let timeout_ms = args
            .get("timeout_ms")
            .and_then(|v| v.as_u64())
            .unwrap_or(10_000)
            .clamp(1_000, 30_000);
        let dry_run = args
            .get("dry_run")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let cage_pid = args
            .get("cage_pid")
            .and_then(|v| v.as_i64())
            .filter(|p| *p > 0);

        // SAFETY: inline invoke is allowed iff dry_run or isolated (cage_pid). A host
        // target is refused by default; with confirm_host the call does NOT invoke — it
        // mints a single-use pending token for a separate human-approved desktop_confirm
        // (two-phase host-confirm path A). Host mutation never happens inline here.
        let confirm_host = args
            .get("confirm_host")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let use_grant = args
            .get("use_grant")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let is_isolated = cage_pid.is_some();
        // Host invoke is refused by default. Two opt-in host paths: confirm_host stages a
        // single-use pending token for a human-approved desktop_confirm (path A); use_grant
        // invokes directly IF a human-minted capability grant covers it (path C). Neither
        // passes --confirm; host mutation is never silent/inline.
        let host_target = !dry_run && !is_isolated;
        if host_target && !confirm_host && !use_grant {
            return Ok(desktop_invoke_error(json!({
                "code": "host_invoke_not_exposed",
                "message": "this MCP invokes only dry_run or isolated (cage_pid) targets; \
                            for a host target set confirm_host:true (two-phase confirm) or \
                            use_grant:true (a human-minted capability grant must cover it)",
                "hint": "set dry_run:true, provide `cage_pid`, set confirm_host:true, or set use_grant:true with a desktop_grant.py grant"
            })));
        }
        let observation_ref = match desktop_invoke_observation_ref(&args, dry_run) {
            Ok(reference) => reference,
            Err(error) => return Ok(desktop_invoke_error(error)),
        };

        let cwd = args.get("cwd").and_then(|v| v.as_str()).map(PathBuf::from);
        let script = desktop_invoke_script_path(&args, cwd.as_ref());
        if !script.exists() {
            return Ok(desktop_invoke_error(json!({
                "code": "script_missing",
                "message": format!("desktop_invoke.py not found at {}", script.display()),
                "hint": "pass script_path or run from the Agent-Bridge repo root"
            })));
        }

        let mut cmd = killable_command(
            std::env::var("PYTHON")
                .ok()
                .filter(|s| !s.trim().is_empty())
                .unwrap_or_else(|| "python3".to_string()),
        );
        cmd.arg(&script);
        if let Some(v) = app {
            if !v.is_empty() {
                cmd.arg("--app").arg(v);
            }
        }
        if let Some(v) = role {
            if !v.is_empty() {
                cmd.arg("--role").arg(v);
            }
        }
        if let Some(v) = name {
            if !v.is_empty() {
                cmd.arg("--name").arg(v);
            }
        }
        if let Some(n) = args.get("nth").and_then(|v| v.as_i64()) {
            cmd.arg("--nth").arg(n.to_string());
        }
        if let Some(a) = args.get("action").and_then(|v| v.as_str()) {
            if !a.is_empty() {
                cmd.arg("--action").arg(a);
            }
        }
        if let Some(w) = args.get("wait").and_then(|v| v.as_f64()) {
            cmd.arg("--wait").arg(format!("{w}"));
        }
        if let Some(p) = cage_pid {
            cmd.arg("--cage-pid").arg(p.to_string());
        }
        if dry_run {
            cmd.arg("--dry-run");
        }
        if host_target && use_grant {
            // Path C: invoke directly IF a human-minted capability grant covers it.
            cmd.arg("--use-grant");
        } else if host_target && confirm_host {
            // Path A phase 1: mint a pending token, invoke NOTHING; execution waits for a
            // human-approved desktop_confirm(token).
            cmd.arg("--request-host-confirm");
        }
        // NOTE: --confirm / --i-understand-this-touches-the-real-desktop are NEVER passed by
        // this MCP surface. Host mutation is reachable only via a human-approved confirm
        // token (path A) or a human-minted grant (path C), never silent/inline.
        cmd.stdout(std::process::Stdio::piped());
        cmd.stderr(std::process::Stdio::piped());
        if let Some(cwd) = cwd {
            cmd.current_dir(cwd);
        }

        let started = Instant::now();
        let output =
            match tokio::time::timeout(Duration::from_millis(timeout_ms), cmd.output()).await {
                Err(_) => {
                    return Ok(desktop_invoke_error(json!({
                        "code": "timeout",
                        "message": format!("desktop_invoke exceeded {timeout_ms} ms"),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Err(e)) => {
                    return Ok(desktop_invoke_error(json!({
                        "code": "spawn_failed",
                        "message": e.to_string(),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Ok(output)) => output,
            };
        let duration_ms = started.elapsed().as_millis() as u64;
        let (stdout, stdout_truncated) = lossy_truncate(&output.stdout);
        let (stderr, stderr_truncated) = lossy_truncate(&output.stderr);

        match serde_json::from_str::<Value>(&stdout) {
            Ok(mut payload) => {
                if let Some(obj) = payload.as_object_mut() {
                    let dispatch_status = if !output.status.success() {
                        "failed"
                    } else if dry_run {
                        "not_dispatched_dry_run"
                    } else if host_target && confirm_host && !use_grant {
                        "pending_human_confirmation"
                    } else {
                        "dispatched"
                    };
                    let mode = if dry_run {
                        "dry-run"
                    } else if !host_target {
                        "isolated"
                    } else if use_grant {
                        "host-grant"
                    } else {
                        "pending-host-confirm"
                    };
                    let verdict = crate::semantic_event::classify_action(
                        mode,
                        output.status.success(),
                        &stderr,
                    );
                    let verification_reason = if verdict.status
                        == crate::semantic_event::VerdictStatus::Unknown
                    {
                        if matches!(mode, "dry-run" | "pending-host-confirm") {
                            "desktop invoke was not injected by design; no effect readback"
                        } else {
                            "desktop invoke was dispatched; resulting UI state was not read back"
                        }
                    } else {
                        "desktop invoke failed or was blocked; effect was not verified"
                    };
                    let effect_verification = crate::semantic_event::effect_verification(
                        verdict.status,
                        verification_reason,
                    );
                    obj.insert(
                        "mcp_wrapper".to_string(),
                        json!({
                            "tool": self.name(),
                            "read_only": false,
                            "mode": mode,
                            "host_protected": true,
                            "duration_ms": duration_ms,
                            "exit_code": output.status.code().unwrap_or(-1),
                            "stderr": stderr,
                            "stderr_truncated": stderr_truncated
                        }),
                    );
                    obj.insert(
                        "action_outcome".to_string(),
                        json!({
                            "dispatch_status": dispatch_status,
                            "effect_verification": "unknown",
                            "effect_verification_detail": effect_verification.clone(),
                            "effect_verified": false,
                            "requires_postcondition_observation": output.status.success() && !dry_run,
                            "observation_ref": observation_ref
                        }),
                    );
                    obj.insert("effect_verification".to_string(), effect_verification);
                }
                let mut result = ToolResult::json_text(&payload);
                if !output.status.success() {
                    result.is_error = true;
                }
                Ok(result)
            }
            Err(e) => Ok(desktop_invoke_error(json!({
                "code": "invalid_json",
                "message": e.to_string(),
                "stdout": stdout,
                "stderr": stderr,
                "exit_code": output.status.code().unwrap_or(-1),
                "duration_ms": duration_ms,
                "truncated": stdout_truncated || stderr_truncated
            }))),
        }
    }
}

fn desktop_invoke_observation_ref(args: &Value, dry_run: bool) -> std::result::Result<Value, Value> {
    if dry_run && args.get("observation_ref").is_none() {
        return Ok(Value::Null);
    }
    let reference = args.get("observation_ref").ok_or_else(|| json!({
        "code": "observation_ref_required",
        "message": "non-dry-run desktop_invoke requires observation_ref from a recent semantic desktop_snapshot"
    }))?;
    let object = reference.as_object().ok_or_else(|| json!({
        "code": "invalid_observation_ref", "message": "observation_ref must be an object"
    }))?;
    let id_ok = object.get("observation_id").and_then(Value::as_str).is_some_and(|v| !v.trim().is_empty());
    let hash_ok = object.get("content_sha256").and_then(Value::as_str).is_some_and(|v| {
        v.len() == 64 && v.bytes().all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase())
    });
    let captured_at = object.get("captured_at_unix_ms").and_then(Value::as_u64);
    let max_age_ms = object.get("max_age_ms").and_then(Value::as_u64).filter(|v| (100..=300_000).contains(v));
    if !id_ok || !hash_ok || captured_at.is_none() || max_age_ms.is_none() {
        return Err(json!({
            "code": "invalid_observation_ref",
            "message": "observation_ref requires non-empty observation_id, lowercase SHA-256, captured_at_unix_ms, and max_age_ms in 100..=300000"
        }));
    }
    let now_ms = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_millis() as u64;
    let captured_at = captured_at.unwrap_or_default();
    if captured_at > now_ms {
        return Err(json!({ "code": "observation_from_future", "message": "observation capture time is later than action validation time" }));
    }
    let age_ms = now_ms - captured_at;
    if age_ms > max_age_ms.unwrap_or_default() {
        return Err(json!({
            "code": "stale_observation",
            "message": "observation exceeded its freshness budget",
            "age_ms": age_ms,
            "max_age_ms": max_age_ms
        }));
    }
    Ok(reference.clone())
}

fn desktop_invoke_script_path(args: &Value, cwd: Option<&PathBuf>) -> PathBuf {
    if let Some(path) = args.get("script_path").and_then(|v| v.as_str()) {
        return PathBuf::from(path);
    }
    if let Ok(path) = std::env::var("AGENT_BRIDGE_DESKTOP_INVOKE_SCRIPT") {
        if !path.trim().is_empty() {
            return PathBuf::from(path);
        }
    }
    if let Some(cwd) = cwd {
        let path = cwd.join("scripts/desktop_invoke.py");
        if path.exists() {
            return path;
        }
    }
    // Runtime calls without an explicit cwd must use the deployed asset.  The MCP
    // server can be launched from a dirty/stale checkout whose scripts no longer
    // match the deployed binary; treating that incidental current directory as
    // authoritative bypasses deployment and can revive fixed desktop behavior.
    if let Some(path) = installed_runtime_script_path("desktop_invoke.py") {
        return path;
    }
    if let Ok(cwd) = std::env::current_dir() {
        let path = cwd.join("scripts/desktop_invoke.py");
        if path.exists() {
            return path;
        }
    }
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../scripts/desktop_invoke.py")
}

/// Resolve scripts/desktop_steer.py — the blessed phase-2 executor for `kind=steer`
/// pendings (cross-process tmux injection). Mirrors desktop_{action,invoke}_script_path:
/// explicit `script_path` arg > AGENT_BRIDGE_DESKTOP_STEER_SCRIPT env > cwd/scripts >
/// current_dir/scripts > stable installed runtime assets > compile-time repo fallback.
fn desktop_steer_script_path(args: &Value, cwd: Option<&PathBuf>) -> PathBuf {
    if let Some(path) = args.get("script_path").and_then(|v| v.as_str()) {
        return PathBuf::from(path);
    }
    if let Ok(path) = std::env::var("AGENT_BRIDGE_DESKTOP_STEER_SCRIPT") {
        if !path.trim().is_empty() {
            return PathBuf::from(path);
        }
    }
    if let Some(cwd) = cwd {
        let path = cwd.join("scripts/desktop_steer.py");
        if path.exists() {
            return path;
        }
    }
    if let Ok(cwd) = std::env::current_dir() {
        let path = cwd.join("scripts/desktop_steer.py");
        if path.exists() {
            return path;
        }
    }
    if let Some(path) = installed_runtime_script_path("desktop_steer.py") {
        return path;
    }
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../scripts/desktop_steer.py")
}

fn desktop_invoke_error(error: Value) -> ToolResult {
    let mut result = ToolResult::json_text(&json!({
        "schema": "desktop_invoke_mcp_error.v0",
        "status": "error",
        "error": error,
    }));
    result.is_error = true;
    result
}

// ===========================================================================
//  Linux Computer Use — bounded semantic task transaction
// ===========================================================================
// One practical Codex-facing call for the full snapshot -> invoke -> verify loop.
// The low-level tools remain independently testable and available in profile=all,
// but this transaction is the compact act surface. It deliberately supports no
// host-confirm or capability-grant arguments: inline mutation is possible only in
// a caller-supplied process cage. A host target is reachable only as dry-run.

const DESKTOP_SEMANTIC_TASK_SCHEMA: &str = "agent_bridge.desktop_semantic_task.v0";
const DESKTOP_SEMANTIC_TASK_EXPECTS: &[&str] = &[
    "element_gone",
    "element_appeared",
    "state_is",
    "state_not",
    "window_gone",
    "window_appeared",
    "focus_is",
];
const DESKTOP_SEMANTIC_TASK_STATES: &[&str] = &[
    "checked",
    "expanded",
    "selected",
    "showing",
    "visible",
    "focused",
    "sensitive",
    "enabled",
    "pressed",
    "active",
];

pub struct DesktopSemanticTaskTool {
    hub: Hub,
}

impl DesktopSemanticTaskTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for DesktopSemanticTaskTool {
    fn name(&self) -> &'static str {
        "desktop_semantic_task"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Bounded Linux desktop semantic task transaction. Runs one compact, \
                 auditable snapshot -> AT-SPI invoke -> postcondition verify loop and returns \
                 a single recover decision (proceed|retry|replan|escalate). The snapshot and \
                 verify legs are read-only. The invoke leg is allowed only with dry_run=true \
                 or a positive cage_pid whose process subtree owns the target; host mutation, \
                 coordinate input, host-confirm tokens, and capability grants are not exposed. \
                 `expect` is required so an action cannot report success without checking its \
                 intended effect."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "app": { "type": "string", "description": "AT-SPI application name substring." },
                    "role": { "type": "string", "description": "AT-SPI role substring, e.g. button." },
                    "name": { "type": "string", "description": "Accessible name/label substring." },
                    "nth": { "type": "integer", "minimum": 0, "default": 0 },
                    "action": { "type": "string", "description": "AT-SPI action; default auto-picks click/press/activate/first." },
                    "dry_run": { "type": "boolean", "default": false, "description": "Locate, audit, and verify without invoking. Allowed against any target." },
                    "cage_pid": { "type": "integer", "minimum": 1, "description": "Nested compositor PID. Required for a real invoke; the target app PID must be its descendant." },
                    "wait": { "type": "number", "minimum": 0.0, "maximum": 30.0, "default": 4.0 },
                    "expect": {
                        "type": "string",
                        "enum": ["element_gone", "element_appeared", "state_is", "state_not", "window_gone", "window_appeared", "focus_is"],
                        "description": "Required postcondition. Element/state checks reuse app/role/name; window/focus checks use win_* selectors."
                    },
                    "state": {
                        "type": "string",
                        "enum": ["checked", "expanded", "selected", "showing", "visible", "focused", "sensitive", "enabled", "pressed", "active"],
                        "description": "Required by state_is/state_not."
                    },
                    "win_app_id": { "type": "string" },
                    "win_pid": { "type": "integer" },
                    "win_title": { "type": "string" },
                    "swaysock": { "type": "string", "description": "Nested sway IPC socket for window/focus verification." },
                    "poll_timeout_secs": { "type": "number", "minimum": 0.0, "maximum": 30.0, "default": 4.0 },
                    "poll_interval_secs": { "type": "number", "minimum": 0.05, "maximum": 5.0, "default": 0.3 },
                    "settle_secs": { "type": "number", "minimum": 0.0, "maximum": 5.0, "default": 0.0 },
                    "cwd": { "type": "string", "description": "Repo root used to resolve all three backend scripts." },
                    "snapshot_script_path": { "type": "string", "description": "Explicit desktop_snapshot.py path (tests/alternate checkouts)." },
                    "invoke_script_path": { "type": "string", "description": "Explicit desktop_invoke.py path (tests/alternate checkouts)." },
                    "verify_script_path": { "type": "string", "description": "Explicit desktop_verify.py path (tests/alternate checkouts)." },
                    "snapshot_timeout_ms": { "type": "integer", "minimum": 1000, "maximum": 60000, "default": 12000 },
                    "invoke_timeout_ms": { "type": "integer", "minimum": 1000, "maximum": 30000, "default": 10000 },
                    "verify_timeout_ms": { "type": "integer", "minimum": 2000, "maximum": 60000, "default": 12000 }
                },
                "required": ["expect"]
            }),
        }
    }

    async fn execute(&self, args: Value, ctx: &ToolContext) -> Result<ToolResult> {
        let selector = desktop_semantic_task_selector(&args);
        if ["app", "role", "name"].iter().all(|key| {
            args.get(*key)
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .is_none()
        }) {
            return Ok(desktop_semantic_task_error(
                "replan",
                json!({
                    "code": "missing_selector",
                    "message": "at least one of `app`, `role`, or `name` is required"
                }),
            ));
        }

        let expect = match required_str_arg(&args, "expect") {
            Ok(value) => value,
            Err(message) => {
                return Ok(desktop_semantic_task_error(
                    "replan",
                    json!({"code": "missing_expectation", "message": message}),
                ))
            }
        };
        if !DESKTOP_SEMANTIC_TASK_EXPECTS.contains(&expect.as_str()) {
            return Ok(desktop_semantic_task_error(
                "replan",
                json!({
                    "code": "invalid_expectation",
                    "message": format!("unsupported postcondition `{expect}`")
                }),
            ));
        }
        if let Some(nth) = args.get("nth") {
            if nth.as_i64().map(|value| value < 0).unwrap_or(true) {
                return Ok(desktop_semantic_task_error(
                    "replan",
                    json!({
                        "code": "invalid_nth",
                        "message": "`nth` must be a non-negative integer"
                    }),
                ));
            }
        }
        if matches!(expect.as_str(), "state_is" | "state_not") {
            let state = args
                .get("state")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty());
            let Some(state) = state else {
                return Ok(desktop_semantic_task_error(
                    "replan",
                    json!({
                        "code": "missing_state",
                        "message": format!("`state` is required for expect={expect}")
                    }),
                ));
            };
            if !DESKTOP_SEMANTIC_TASK_STATES.contains(&state) {
                return Ok(desktop_semantic_task_error(
                    "replan",
                    json!({
                        "code": "invalid_state",
                        "message": format!("unsupported AT-SPI state `{state}`")
                    }),
                ));
            }
        }
        let window_expect = matches!(
            expect.as_str(),
            "window_gone" | "window_appeared" | "focus_is"
        );
        let has_window_string = ["win_app_id", "win_title"].iter().any(|key| {
            args.get(*key)
                .and_then(Value::as_str)
                .map(str::trim)
                .is_some_and(|value| !value.is_empty())
        });
        let has_window_pid = args
            .get("win_pid")
            .and_then(Value::as_i64)
            .is_some_and(|pid| pid > 0);
        if window_expect && !has_window_string && !has_window_pid {
            return Ok(desktop_semantic_task_error(
                "replan",
                json!({
                    "code": "missing_window_selector",
                    "message": format!("one of win_app_id/win_pid/win_title is required for expect={expect}")
                }),
            ));
        }

        let dry_run = args
            .get("dry_run")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let cage_pid = args
            .get("cage_pid")
            .and_then(Value::as_i64)
            .filter(|pid| *pid > 0);
        if !dry_run && cage_pid.is_none() {
            return Ok(desktop_semantic_task_error(
                "replan",
                json!({
                    "code": "host_task_not_exposed",
                    "message": "a real semantic task requires a positive cage_pid; host mutation is not exposed by this transaction",
                    "hint": "set dry_run:true or provide the nested compositor cage_pid"
                }),
            ));
        }

        // Preflight is deliberately bounded and read-only. The full raw snapshot can be
        // large, so the transaction retains only coverage and selector-match evidence.
        let mut snapshot_args = json!({
            "include_screenshot": false,
            "include_atspi": true,
            "max_elements": 80,
            "atspi_budget": 0.5,
            "semantic_bus": true,
            "semantic_include_raw": true,
            "semantic_max_age_ms": 15000,
            "timeout_ms": args.get("snapshot_timeout_ms").cloned().unwrap_or_else(|| json!(12000))
        });
        desktop_semantic_task_copy(&args, &mut snapshot_args, "cwd", "cwd");
        desktop_semantic_task_copy(
            &args,
            &mut snapshot_args,
            "snapshot_script_path",
            "script_path",
        );
        let snapshot_result = DesktopSnapshotTool::new(self.hub.clone())
            .execute(snapshot_args, ctx)
            .await?;
        let snapshot_payload = desktop_semantic_task_result_payload(&snapshot_result);
        let preflight = desktop_semantic_task_preflight_summary(
            snapshot_payload.as_ref(),
            snapshot_result.is_error,
            &args,
        );
        let observation_ref = snapshot_payload
            .as_ref()
            .and_then(desktop_semantic_task_observation_ref);
        if !dry_run && observation_ref.is_none() {
            let mut result = ToolResult::json_text(&json!({
                "schema": DESKTOP_SEMANTIC_TASK_SCHEMA,
                "status": "preflight_failed",
                "verdict": "error",
                "recover": "retry",
                "safety": desktop_semantic_task_safety(dry_run, cage_pid),
                "selector": selector,
                "expect": expect,
                "preflight": preflight,
                "action": Value::Null,
                "verification": Value::Null,
                "error": {
                    "code": "fresh_observation_unavailable",
                    "message": "a real invoke requires a verified, fresh semantic desktop observation"
                }
            }));
            result.is_error = true;
            return Ok(result);
        }

        let mut invoke_args = json!({
            "dry_run": dry_run,
            "timeout_ms": args.get("invoke_timeout_ms").cloned().unwrap_or_else(|| json!(10000))
        });
        for key in ["app", "role", "name", "nth", "action", "wait", "cwd"] {
            desktop_semantic_task_copy(&args, &mut invoke_args, key, key);
        }
        if let Some(pid) = cage_pid {
            invoke_args["cage_pid"] = json!(pid);
        }
        if let Some(reference) = observation_ref {
            invoke_args["observation_ref"] = reference;
        }
        desktop_semantic_task_copy(
            &args,
            &mut invoke_args,
            "invoke_script_path",
            "script_path",
        );
        let invoke_result = DesktopInvokeTool::new(self.hub.clone())
            .execute(invoke_args, ctx)
            .await?;
        let invoke_payload = desktop_semantic_task_result_payload(&invoke_result);
        if invoke_result.is_error || invoke_payload.is_none() {
            let recover = desktop_semantic_task_invoke_recover(invoke_payload.as_ref());
            let mut result = ToolResult::json_text(&json!({
                "schema": DESKTOP_SEMANTIC_TASK_SCHEMA,
                "status": "action_failed",
                "verdict": "error",
                "recover": recover,
                "safety": desktop_semantic_task_safety(dry_run, cage_pid),
                "selector": selector,
                "expect": expect,
                "preflight": preflight,
                "action": desktop_semantic_task_action_summary(invoke_payload.as_ref()),
                "verification": Value::Null
            }));
            result.is_error = true;
            return Ok(result);
        }

        let invoke_payload = invoke_payload.expect("checked above");
        let mut verify_args = json!({
            "expect": expect,
            "timeout_ms": args.get("verify_timeout_ms").cloned().unwrap_or_else(|| json!(12000))
        });
        for key in [
            "app",
            "role",
            "name",
            "nth",
            "state",
            "win_app_id",
            "win_pid",
            "win_title",
            "swaysock",
            "poll_timeout_secs",
            "poll_interval_secs",
            "settle_secs",
            "cwd",
        ] {
            desktop_semantic_task_copy(&args, &mut verify_args, key, key);
        }
        if let Some(pid) = cage_pid {
            verify_args["cage_pid"] = json!(pid);
        }
        desktop_semantic_task_copy(
            &args,
            &mut verify_args,
            "verify_script_path",
            "script_path",
        );
        if let Some(present) = invoke_payload
            .get("before")
            .and_then(|value| value.get("target_present"))
            .and_then(Value::as_bool)
        {
            verify_args["before_present"] = json!(if present { "true" } else { "false" });
        }
        if let Some(focus) = invoke_payload
            .get("before")
            .and_then(|value| value.get("focus"))
            .and_then(Value::as_str)
            .filter(|value| !value.is_empty())
        {
            verify_args["before_focus"] = json!(focus);
        }

        let verify_result = DesktopVerifyTool::new(self.hub.clone())
            .execute(verify_args, ctx)
            .await?;
        let verify_payload = desktop_semantic_task_result_payload(&verify_result);
        let verdict = verify_payload
            .as_ref()
            .and_then(|payload| payload.get("verdict"))
            .and_then(Value::as_str)
            .unwrap_or("error");
        let recover = verify_payload
            .as_ref()
            .and_then(|payload| payload.get("recover"))
            .and_then(Value::as_str)
            .filter(|value| matches!(*value, "proceed" | "retry" | "replan" | "escalate"))
            .unwrap_or(if verdict == "verified" { "proceed" } else { "escalate" });
        let status = match verdict {
            "verified" => "verified",
            "unmet" => "unmet",
            _ => "error",
        };
        let mut result = ToolResult::json_text(&json!({
            "schema": DESKTOP_SEMANTIC_TASK_SCHEMA,
            "status": status,
            "verdict": verdict,
            "recover": recover,
            "safety": desktop_semantic_task_safety(dry_run, cage_pid),
            "selector": selector,
            "expect": expect,
            "preflight": preflight,
            "action": desktop_semantic_task_action_summary(Some(&invoke_payload)),
            "verification": desktop_semantic_task_verification_summary(verify_payload.as_ref())
        }));
        result.is_error = verify_result.is_error || verdict == "error";
        Ok(result)
    }
}

fn desktop_semantic_task_selector(args: &Value) -> Value {
    json!({
        "app": args.get("app").cloned().unwrap_or(Value::Null),
        "role": args.get("role").cloned().unwrap_or(Value::Null),
        "name": args.get("name").cloned().unwrap_or(Value::Null),
        "nth": args.get("nth").cloned().unwrap_or_else(|| json!(0))
    })
}

fn desktop_semantic_task_copy(source: &Value, target: &mut Value, from: &str, to: &str) {
    if let Some(value) = source.get(from).filter(|value| !value.is_null()) {
        target[to] = value.clone();
    }
}

fn desktop_semantic_task_result_payload(result: &ToolResult) -> Option<Value> {
    result.structured_content.clone().or_else(|| {
        result.content.iter().find_map(|block| match block {
            ContentBlock::Text { text } => serde_json::from_str(text).ok(),
            _ => None,
        })
    })
}

fn desktop_semantic_task_safety(dry_run: bool, cage_pid: Option<i64>) -> Value {
    json!({
        "mode": if dry_run { "dry-run" } else { "isolated" },
        "cage_pid": cage_pid,
        "host_mutation_exposed": false,
        "coordinate_input_exposed": false,
        "postcondition_required": true
    })
}

fn desktop_semantic_task_preflight_summary(
    payload: Option<&Value>,
    is_error: bool,
    args: &Value,
) -> Value {
    let Some(payload) = payload else {
        return json!({
            "status": "degraded",
            "read_only": true,
            "reason": "snapshot_payload_missing"
        });
    };
    if is_error {
        return json!({
            "status": "degraded",
            "read_only": true,
            "schema": payload.get("schema").cloned().unwrap_or(Value::Null),
            "error": payload.get("error").cloned().unwrap_or(Value::Null)
        });
    }

    let raw_snapshot = payload.get("raw_snapshot").unwrap_or(payload);
    let app_match = args
        .get("app")
        .and_then(Value::as_str)
        .map(str::to_lowercase);
    let role_match = args
        .get("role")
        .and_then(Value::as_str)
        .map(str::to_lowercase);
    let name_match = args
        .get("name")
        .and_then(Value::as_str)
        .map(str::to_lowercase);
    let apps = raw_snapshot
        .get("atspi")
        .and_then(|value| value.get("apps"))
        .and_then(Value::as_array);
    let mut target_matches = 0_u64;
    let mut timed_out_apps = 0_u64;
    if let Some(apps) = apps {
        for app in apps {
            if app.get("timed_out").and_then(Value::as_bool).unwrap_or(false) {
                timed_out_apps += 1;
            }
            let app_name = app
                .get("name")
                .and_then(Value::as_str)
                .unwrap_or("")
                .to_lowercase();
            if app_match
                .as_ref()
                .map(|want| !app_name.contains(want))
                .unwrap_or(false)
            {
                continue;
            }
            if let Some(elements) = app.get("elements").and_then(Value::as_array) {
                for element in elements {
                    let role = element
                        .get("role")
                        .and_then(Value::as_str)
                        .unwrap_or("")
                        .to_lowercase();
                    let name = element
                        .get("name")
                        .and_then(Value::as_str)
                        .unwrap_or("")
                        .to_lowercase();
                    let role_ok = role_match
                        .as_ref()
                        .map(|want| role.contains(want))
                        .unwrap_or(true);
                    let name_ok = name_match
                        .as_ref()
                        .map(|want| name.contains(want))
                        .unwrap_or(true);
                    if role_ok && name_ok {
                        target_matches += 1;
                    }
                }
            }
        }
    }
    let fresh_at_return = payload
        .get("observation")
        .and_then(|value| value.get("freshness"))
        .and_then(|value| value.get("fresh_at_return"))
        .and_then(Value::as_bool);
    let semantic_verified = payload
        .get("verification")
        .and_then(|value| value.get("verdict"))
        .and_then(Value::as_str)
        .is_some_and(|verdict| verdict == "verified");
    json!({
        "status": if semantic_verified && fresh_at_return != Some(false) { "observed" } else { "degraded" },
        "read_only": true,
        "schema": payload.get("schema").cloned().unwrap_or(Value::Null),
        "source_schema": payload.get("source_schema").cloned().unwrap_or_else(|| raw_snapshot.get("schema").cloned().unwrap_or(Value::Null)),
        "window_count": raw_snapshot.get("window_count").cloned().unwrap_or(Value::Null),
        "atspi_available": raw_snapshot.get("atspi").and_then(|value| value.get("available")).cloned().unwrap_or(Value::Null),
        "atspi_app_count": apps.map(|apps| apps.len()).unwrap_or(0),
        "target_matches_in_bounded_snapshot": target_matches,
        "timed_out_apps": timed_out_apps,
        "coverage_complete": timed_out_apps == 0,
        "observation": {
            "observation_id": payload.get("observation").and_then(|value| value.get("observation_id")).cloned().unwrap_or(Value::Null),
            "fresh_at_return": fresh_at_return,
            "age_ms_at_return": payload.get("observation").and_then(|value| value.get("freshness")).and_then(|value| value.get("age_ms_at_return")).cloned().unwrap_or(Value::Null),
            "max_age_ms": payload.get("observation").and_then(|value| value.get("freshness")).and_then(|value| value.get("max_age_ms")).cloned().unwrap_or(Value::Null)
        }
    })
}

fn desktop_semantic_task_observation_ref(payload: &Value) -> Option<Value> {
    if payload.get("schema").and_then(Value::as_str) != Some(DESKTOP_SNAPSHOT_SEMANTIC_SCHEMA)
        || payload
            .get("verification")
            .and_then(|value| value.get("verdict"))
            .and_then(Value::as_str)
            != Some("verified")
        || payload
            .get("observation")
            .and_then(|value| value.get("freshness"))
            .and_then(|value| value.get("fresh_at_return"))
            .and_then(Value::as_bool)
            != Some(true)
    {
        return None;
    }
    let observation = payload.get("observation")?;
    let captured_at_unix_ms = payload.get("captured_at")?.as_u64()?.checked_mul(1_000)?;
    Some(json!({
        "observation_id": observation.get("observation_id")?.as_str()?,
        "content_sha256": observation.get("content_hash")?.get("value")?.as_str()?,
        "captured_at_unix_ms": captured_at_unix_ms,
        "max_age_ms": observation.get("freshness")?.get("max_age_ms")?.as_u64()?
    }))
}

fn desktop_semantic_task_action_summary(payload: Option<&Value>) -> Value {
    let Some(payload) = payload else {
        return json!({"status": "missing"});
    };
    let effect_verification = payload
        .get("effect_verification")
        .cloned()
        .or_else(|| {
            payload
                .get("action_outcome")
                .and_then(|value| value.get("effect_verification_detail"))
                .cloned()
        })
        .unwrap_or_else(|| {
            json!({
                "status": "unknown",
                "reason": "effect verification detail was not provided by the action surface"
            })
        });
    let action_outcome = payload.get("action_outcome");
    json!({
        "schema": payload.get("schema").cloned().unwrap_or(Value::Null),
        "allowed": payload.get("allowed").cloned().unwrap_or(Value::Null),
        "rc": payload.get("rc").cloned().unwrap_or(Value::Null),
        "found": payload.get("found").cloned().unwrap_or(Value::Null),
        "before": payload.get("before").cloned().unwrap_or(Value::Null),
        "detail": payload.get("detail").cloned().unwrap_or(Value::Null),
        "error": payload.get("error").cloned().unwrap_or(Value::Null),
        "search": payload.get("search").cloned().unwrap_or(Value::Null),
        "dispatch": action_outcome.and_then(|value| value.get("dispatch_status")).cloned().unwrap_or(Value::Null),
        "effect_verification": effect_verification,
        "effect_verified": action_outcome.and_then(|value| value.get("effect_verified")).cloned().unwrap_or(Value::Null),
        "requires_postcondition_observation": action_outcome.and_then(|value| value.get("requires_postcondition_observation")).cloned().unwrap_or(Value::Null),
        "wrapper": payload.get("mcp_wrapper").cloned().unwrap_or(Value::Null)
    })
}

fn desktop_semantic_task_verification_summary(payload: Option<&Value>) -> Value {
    let Some(payload) = payload else {
        return json!({"verdict": "error", "recover": "escalate", "error": "verify_payload_missing"});
    };
    let observed = payload.get("observed");
    json!({
        "schema": payload.get("schema").cloned().unwrap_or(Value::Null),
        "verdict": payload.get("verdict").cloned().unwrap_or_else(|| json!("error")),
        "recover": payload.get("recover").cloned().unwrap_or_else(|| json!("escalate")),
        "change": payload.get("change").cloned().unwrap_or(Value::Null),
        "held_after_ms": payload.get("held_after_ms").cloned().unwrap_or(Value::Null),
        "polls": payload.get("polls").cloned().unwrap_or(Value::Null),
        "observed_count": observed.and_then(|value| value.get("count")).cloned().unwrap_or(Value::Null),
        "search": observed.and_then(|value| value.get("search")).cloned().unwrap_or(Value::Null),
        "focused": observed.and_then(|value| value.get("focused")).cloned().unwrap_or(Value::Null),
        "error": payload.get("error").cloned().unwrap_or(Value::Null),
        "wrapper": payload.get("mcp_wrapper").cloned().unwrap_or(Value::Null)
    })
}

fn desktop_semantic_task_invoke_recover(payload: Option<&Value>) -> &'static str {
    let code = payload
        .and_then(|value| value.get("error"))
        .and_then(|value| value.get("code"))
        .and_then(Value::as_str)
        .unwrap_or("");
    let message = payload
        .and_then(|value| value.get("error"))
        .and_then(Value::as_str)
        .unwrap_or("")
        .to_lowercase();
    match code {
        "missing_selector" | "host_invoke_not_exposed" | "script_missing" | "search_incomplete" => "replan",
        "target_not_found" => "retry",
        "timeout" | "spawn_failed" => "retry",
        _ if message.contains("no matching accessible") => "retry",
        _ => "escalate",
    }
}

fn desktop_semantic_task_error(recover: &str, error: Value) -> ToolResult {
    let mut result = ToolResult::json_text(&json!({
        "schema": DESKTOP_SEMANTIC_TASK_SCHEMA,
        "status": "error",
        "verdict": "error",
        "recover": recover,
        "error": error,
        "safety": {
            "host_mutation_exposed": false,
            "coordinate_input_exposed": false,
            "postcondition_required": true
        }
    }));
    result.is_error = true;
    result
}

// ===========================================================================
//  Application control — protocol/API first, independently verified
// ===========================================================================

pub struct AppControlTool {
    _hub: Hub,
}

const APP_CONTROL_WRAPPER_CONTRACT_SCHEMA: &str =
    "agent_bridge.app_control.wrapper_contract.v1";

// Keep the durable app-control contracts discoverable in the release binary.
// The deploy gate intentionally checks the binary, not only the external
// Python asset; these `#[used]` sentinels make that trust boundary explicit
// without changing any runtime behavior.
#[used]
#[no_mangle]
pub static APP_CONTROL_OPERATION_PREFLIGHT_SENTINEL: [u8; 48] =
    *b"agent_bridge.app_control.operation_preflight.v0\0";
#[used]
#[no_mangle]
pub static APP_CONTROL_TRACK_SETTLEMENT_SENTINEL: [u8; 45] =
    *b"agent_bridge.app_control.track_settlement.v0\0";
#[used]
#[no_mangle]
pub static APP_CONTROL_WRAPPER_CONTRACT_SENTINEL: [u8; 45] =
    *b"agent_bridge.app_control.wrapper_contract.v1\0";

impl AppControlTool {
    pub fn new(hub: Hub) -> Self {
        Self { _hub: hub }
    }

    /// Inspect the installed durable-next journal without exposing a new MCP
    /// action or treating the snapshot as dispatch authority.
    pub(super) async fn preflight_durable_next(
        &self,
        operation_id: &str,
        player_selector: Option<&str>,
        operation_ttl_secs: u64,
        timeout_ms: u64,
    ) -> ToolResult {
        let script = app_control_durable_script_path();
        if !script.exists() {
            return app_control_error(
                "replan",
                json!({
                    "code": "script_missing",
                    "message": format!("app_control.py not found at {}", script.display())
                }),
            );
        }
        let mut cmd = killable_command(
            std::env::var("PYTHON")
                .ok()
                .filter(|value| !value.trim().is_empty())
                .unwrap_or_else(|| "python3".into()),
        );
        cmd.arg(&script)
            .arg("--domain")
            .arg("media")
            .arg("--action")
            .arg("next")
            .arg("--operation-id")
            .arg(operation_id)
            .arg("--operation-ttl-secs")
            .arg(operation_ttl_secs.to_string())
            .arg("--operation-preflight")
            .arg("--wrapper-contract-version")
            .arg(APP_CONTROL_WRAPPER_CONTRACT_SCHEMA);
        if let Some(player) = player_selector {
            cmd.arg("--player").arg(player);
        }
        cmd.stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped());

        let started = Instant::now();
        let output = match tokio::time::timeout(
            Duration::from_millis(timeout_ms.clamp(1_000, 30_000)),
            cmd.output(),
        )
        .await
        {
            Err(_) => {
                return app_control_error(
                    "retry",
                    json!({"code": "preflight_timeout", "duration_ms": started.elapsed().as_millis()}),
                )
            }
            Ok(Err(error)) => {
                return app_control_error(
                    "retry",
                    json!({"code": "preflight_spawn_failed", "message": error.to_string()}),
                )
            }
            Ok(Ok(output)) => output,
        };
        let duration_ms = started.elapsed().as_millis() as u64;
        let (stdout, stdout_truncated) = lossy_truncate(&output.stdout);
        let (stderr, stderr_truncated) = lossy_truncate(&output.stderr);
        let mut payload = match serde_json::from_str::<Value>(&stdout) {
            Ok(payload) => payload,
            Err(error) => {
                return app_control_error(
                    "replan",
                    json!({
                        "code": "preflight_invalid_json",
                        "message": error.to_string(),
                        "exit_code": output.status.code().unwrap_or(-1),
                        "stdout": stdout,
                        "stderr": stderr
                    }),
                )
            }
        };
        let exit_code = output.status.code().unwrap_or(-1);
        let source_contract_ok = app_control_preflight_source_contract_valid(
            &payload,
            operation_id,
            player_selector,
            operation_ttl_secs,
            exit_code,
        );
        if let Some(object) = payload.as_object_mut() {
            object.insert(
                "mcp_wrapper".into(),
                json!({
                    "tool": "app_control",
                    "mode": "durable_operation_preflight",
                    "duration_ms": duration_ms,
                    "exit_code": exit_code,
                    "stderr": stderr,
                    "truncated": stdout_truncated || stderr_truncated,
                    "source_contract_ok": source_contract_ok,
                    "operation_id_bound": true
                }),
            );
        }
        if !source_contract_ok {
            return app_control_error(
                "replan",
                json!({
                    "code": "preflight_source_contract_mismatch",
                    "exit_code": exit_code,
                    "source": payload
                }),
            );
        }
        let verified = payload.get("verdict").and_then(Value::as_str) == Some("verified");
        let mut result = ToolResult::json_text(&payload);
        result.is_error = !verified;
        result
    }
}

#[async_trait]
impl McpTool for AppControlTool {
    fn name(&self) -> &'static str {
        "app_control"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Bounded application capability discovery and control transaction. \
                The initial media adapter prefers the standard MPRIS application protocol, \
                reads state before dispatch, executes one allowlisted action without shell \
                interpolation, and independently re-reads MPRIS state to verify the effect. \
                AT-SPI, vision, and coordinate input are reported as explicit fallbacks but \
                are never selected silently. Use action=discover or dry_run=true for read-only use."
                .into(),
            input_schema: json!({
                "type": "object",
                "additionalProperties": false,
                "properties": {
                    "domain": {"type": "string", "enum": ["media"], "default": "media"},
                    "action": {
                        "type": "string",
                        "enum": ["discover", "next", "previous", "play", "pause", "play_pause", "stop", "volume_get", "volume_up", "volume_down", "volume_set", "state_get", "position_get", "playlist_list", "playlist_current", "playlist_activate"]
                    },
                    "player": {
                        "type": "string",
                        "description": "Optional exact or unique-substring MPRIS player selector. With multiple players and no selector, only one uniquely Playing instance is selected; ambiguity fails closed."
                    },
                    "volume": {
                        "type": "number", "minimum": 0.0, "maximum": 1.0,
                        "description": "Target player volume in the normalized MPRIS range 0.0–1.0; required by volume_set."
                    },
                    "playlist_id": {
                        "type": "string",
                        "description": "Exact MPRIS playlist object path returned by playlist_list; required by playlist_activate."
                    },
                    "operation_id": {
                        "type": "string",
                        "minLength": 1,
                        "maxLength": 128,
                        "pattern": "^[A-Za-z0-9._:-]+$",
                        "description": "Optional durable at-most-once identity for action=next. The installed backend journals the exact request before dispatch; replay or restart recovery never dispatches next a second time. First slice only: incompatible with dry_run, cwd, or script_path."
                    },
                    "operation_ttl_secs": {
                        "type": "integer",
                        "minimum": 60,
                        "maximum": 86400,
                        "default": 3600,
                        "description": "TTL for a durable operation_id. Expired operations fail closed and require a new identity; ignored requests are rejected rather than silently changing the journal contract."
                    },
                    "workspace_root": {
                        "type": "string",
                        "description": "Canonical absolute workspace directory to bind into a durable next operation as a SHA-256 digest. Required for newly recoverable embodied episodes; the raw path is not journaled."
                    },
                    "recovery_preflight": {
                        "type": "boolean", "default": false,
                        "description": "Read-only exact recovery admission. Requires action=next, operation_id, expected_record_sha256, player, operation_ttl_secs, workspace_root, and intent_confirmed=true; never observes media or dispatches."
                    },
                    "expected_record_sha256": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
                    "intent_confirmed": {"type": "boolean", "default": false},
                    "minimum_recovery_secs": {"type": "number", "minimum": 0.0, "maximum": 86400.0, "default": 5.0},
                    "recovery_authorization_review": {"type": "boolean", "default": false},
                    "recovery_authorization_request": {"type": "boolean", "default": false},
                    "recovery_authorization_status": {
                        "type": "boolean", "default": false,
                        "description": "Read-only readiness probe for the external Ed25519 signer contract. Requires action=discover and never reads a private key."
                    },
                    "recovery_authorization_receipt": {"type": "string", "maxLength": 8192},
                    "recovery_authorization_consume": {"type": "boolean", "default": false},
                    "dry_run": {
                        "type": "boolean", "default": false,
                        "description": "Discover the route and read current state without dispatching the action."
                    },
                    "verify_timeout_secs": {
                        "type": "number", "minimum": 0.1, "maximum": 10.0, "default": 2.0
                    },
                    "cwd": {"type": "string", "description": "Repo root used to resolve scripts/app_control.py."},
                    "script_path": {"type": "string", "description": "Explicit backend script path for tests or alternate checkouts."},
                    "timeout_ms": {"type": "integer", "minimum": 1000, "maximum": 30000, "default": 15000}
                },
                "required": ["action"]
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        const ARGUMENTS: &[&str] = &[
            "domain",
            "action",
            "player",
            "volume",
            "playlist_id",
            "operation_id",
            "operation_ttl_secs",
            "workspace_root",
            "recovery_preflight",
            "expected_record_sha256",
            "intent_confirmed",
            "minimum_recovery_secs",
            "recovery_authorization_review",
            "recovery_authorization_request",
            "recovery_authorization_status",
            "recovery_authorization_receipt",
            "recovery_authorization_consume",
            "dry_run",
            "verify_timeout_secs",
            "cwd",
            "script_path",
            "timeout_ms",
        ];
        if let Some(arguments) = args.as_object() {
            if let Some(unknown) = arguments
                .keys()
                .find(|key| !ARGUMENTS.contains(&key.as_str()))
            {
                return Ok(app_control_error(
                    "replan",
                    json!({"code": "unknown_argument", "argument": unknown}),
                ));
            }
        }
        let action = match required_str_arg(&args, "action") {
            Ok(value) => value,
            Err(message) => {
                return Ok(app_control_error(
                    "replan",
                    json!({"code": "missing_action", "message": message}),
                ))
            }
        };
        const ACTIONS: &[&str] = &[
            "discover",
            "next",
            "previous",
            "play",
            "pause",
            "play_pause",
            "stop",
            "volume_get",
            "volume_up",
            "volume_down",
            "volume_set",
            "state_get",
            "position_get",
            "playlist_list",
            "playlist_current",
            "playlist_activate",
        ];
        if !ACTIONS.contains(&action.as_str()) {
            return Ok(app_control_error("replan", json!({
                "code": "unsupported_action", "action": action
            })));
        }
        let domain = match args.get("domain") {
            None => "media",
            Some(Value::String(value)) if !value.trim().is_empty() => value.as_str(),
            Some(_) => {
                return Ok(app_control_error(
                    "replan",
                    json!({"code": "invalid_domain"}),
                ))
            }
        };
        if domain != "media" {
            return Ok(app_control_error("replan", json!({
                "code": "unsupported_domain", "domain": domain
            })));
        }
        let dry_run = match args.get("dry_run") {
            None => false,
            Some(Value::Bool(value)) => *value,
            Some(_) => {
                return Ok(app_control_error(
                    "replan",
                    json!({"code": "invalid_dry_run"}),
                ))
            }
        };
        let operation_id = match args.get("operation_id") {
            None => None,
            Some(Value::String(value)) => {
                let value = value.trim();
                if value.is_empty()
                    || args.get("operation_id").and_then(Value::as_str) != Some(value)
                    || value.chars().count() > 128
                    || !value
                        .bytes()
                        .all(|byte| byte.is_ascii_alphanumeric() || b"._:-".contains(&byte))
                {
                    return Ok(app_control_error(
                        "replan",
                        json!({"code": "invalid_operation_id"}),
                    ));
                }
                Some(value.to_string())
            }
            Some(_) => {
                return Ok(app_control_error(
                    "replan",
                    json!({"code": "invalid_operation_id"}),
                ))
            }
        };
        let operation_ttl_secs = match args.get("operation_ttl_secs") {
            None => 3_600_u64,
            Some(value) => match value.as_u64() {
                Some(value) if (60..=86_400).contains(&value) => value,
                _ => {
                    return Ok(app_control_error(
                        "replan",
                        json!({"code": "invalid_operation_ttl_secs"}),
                    ))
                }
            },
        };
        if operation_id.is_none() && args.get("operation_ttl_secs").is_some() {
            return Ok(app_control_error(
                "replan",
                json!({
                    "code": "operation_id_required",
                    "message": "operation_ttl_secs requires operation_id"
                }),
            ));
        }
        let workspace_sha256 = match args.get("workspace_root") {
            None => None,
            Some(Value::String(value)) => {
                let supplied = PathBuf::from(value);
                let canonical = match supplied.canonicalize() {
                    Ok(path) if supplied.is_absolute() && path == supplied && path.is_dir() => path,
                    _ => return Ok(app_control_error("replan", json!({
                        "code": "invalid_workspace_root",
                        "message": "workspace_root must be an existing canonical absolute directory"
                    }))),
                };
                if operation_id.is_none() {
                    return Ok(app_control_error("replan", json!({
                        "code": "operation_id_required",
                        "message": "workspace_root is only accepted for a durable operation_id"
                    })));
                }
                Some(format!("{:x}", Sha256::digest(canonical.as_os_str().as_encoded_bytes())))
            }
            Some(_) => return Ok(app_control_error("replan", json!({"code": "invalid_workspace_root"}))),
        };
        let player_selector = match args.get("player") {
            None => None,
            Some(Value::String(value)) => {
                let value = value.trim();
                if value.is_empty() {
                    return Ok(app_control_error("replan", json!({"code": "invalid_player"})));
                }
                Some(value)
            }
            Some(_) => return Ok(app_control_error("replan", json!({"code": "invalid_player"}))),
        };
        let recovery_preflight = args.get("recovery_preflight").and_then(Value::as_bool).unwrap_or(false);
        let authorization_status = args.get("recovery_authorization_status").and_then(Value::as_bool).unwrap_or(false);
        if authorization_status {
            if recovery_preflight || action != "discover" || args.as_object().map(|object| object.keys().any(|key|
                !matches!(key.as_str(), "action" | "domain" | "recovery_authorization_status"))).unwrap_or(false)
            {
                return Ok(app_control_error("replan", json!({"code": "recovery_authorization_status_requires_discover_only"})));
            }
            let script = app_control_recovery_signer_status_script_path();
            if !script.is_file() {
                return Ok(app_control_error("replan", json!({"code": "recovery_authorization_status_script_missing"})));
            }
            let mut cmd = killable_command(std::env::var("PYTHON").ok()
                .filter(|value| !value.trim().is_empty()).unwrap_or_else(|| "python3".into()));
            cmd.arg(script).stdout(std::process::Stdio::piped()).stderr(std::process::Stdio::null());
            let output = match tokio::time::timeout(Duration::from_millis(2_000), cmd.output()).await {
                Ok(Ok(output)) => output,
                _ => return Ok(app_control_error("retry", json!({"code": "recovery_authorization_status_unavailable"}))),
            };
            let payload: Value = match serde_json::from_slice(&output.stdout) {
                Ok(value) => value,
                Err(_) => return Ok(app_control_error("replan", json!({"code": "recovery_authorization_status_invalid_json"}))),
            };
            let safe = payload.get("schema").and_then(Value::as_str)
                == Some("agent_bridge.app_control.recovery_authorization_signer_status.v0")
                && payload.get("verdict").and_then(Value::as_str) == Some("verified")
                && payload.get("read_only").and_then(Value::as_bool) == Some(true)
                && payload.get("private_key_observed").and_then(Value::as_bool) == Some(false)
                && payload.get("action_invoked").and_then(Value::as_bool) == Some(false)
                && payload.get("automatic_recovery_authorized").and_then(Value::as_bool) == Some(false)
                && matches!(payload.get("admission").and_then(Value::as_str), Some("configured" | "source_unavailable"));
            if !safe { return Ok(app_control_error("replan", json!({"code": "recovery_authorization_status_contract_mismatch"}))); }
            let mut result = ToolResult::json_text(&payload);
            result.is_error = payload.get("admission").and_then(Value::as_str) != Some("configured");
            return Ok(result);
        }
        if !recovery_preflight && ["expected_record_sha256", "intent_confirmed", "minimum_recovery_secs",
            "recovery_authorization_review", "recovery_authorization_receipt", "recovery_authorization_consume"]
            .iter().any(|key| args.get(*key).is_some())
        {
            return Ok(app_control_error("replan", json!({"code": "recovery_preflight_required"})));
        }
        if !recovery_preflight && args.get("recovery_authorization_request").is_some() {
            return Ok(app_control_error("replan", json!({"code": "recovery_preflight_required"})));
        }
        if recovery_preflight {
            let authorization_review = args.get("recovery_authorization_review").and_then(Value::as_bool).unwrap_or(false);
            let authorization_request = args.get("recovery_authorization_request").and_then(Value::as_bool).unwrap_or(false);
            let authorization_consume = args.get("recovery_authorization_consume").and_then(Value::as_bool).unwrap_or(false);
            let authorization_receipt = args.get("recovery_authorization_receipt").and_then(Value::as_str);
            if authorization_consume && !authorization_review {
                return Ok(app_control_error("replan", json!({"code": "recovery_authorization_review_required"})));
            }
            if authorization_request && authorization_review {
                return Ok(app_control_error("replan", json!({"code": "recovery_authorization_mode_conflict"})));
            }
            if authorization_review && authorization_receipt.map(str::is_empty).unwrap_or(true) {
                return Ok(app_control_error("replan", json!({"code": "recovery_authorization_receipt_required"})));
            }
            if !authorization_review && authorization_receipt.is_some() {
                return Ok(app_control_error("replan", json!({"code": "recovery_authorization_review_required"})));
            }
            let expected_record_sha256 = args.get("expected_record_sha256").and_then(Value::as_str)
                .filter(|value| value.len() == 64 && value.bytes().all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte)));
            let intent_confirmed = args.get("intent_confirmed").and_then(Value::as_bool) == Some(true);
            let minimum = args.get("minimum_recovery_secs").and_then(Value::as_f64).unwrap_or(5.0);
            let workspace_root = args.get("workspace_root").and_then(Value::as_str);
            let Some(operation_id) = operation_id.as_deref() else {
                return Ok(app_control_error("replan", json!({"code": "recovery_preflight_requires_operation_id"})));
            };
            let Some(player_selector) = player_selector else {
                return Ok(app_control_error("replan", json!({"code": "recovery_preflight_requires_player"})));
            };
            if action != "next" || expected_record_sha256.is_none() || !intent_confirmed
                || workspace_root.is_none() || workspace_sha256.is_none() || !(0.0..=86_400.0).contains(&minimum)
            {
                return Ok(app_control_error("replan", json!({"code": "recovery_preflight_requires_explicit_context"})));
            }
            let journal = match std::env::var("AB_APP_CONTROL_OPERATION_DIR") {
                Ok(value) if Path::new(&value).is_absolute() => value,
                _ => return Ok(app_control_error("replan", json!({"code": "operation_journal_unavailable"}))),
            };
            let script = app_control_recovery_candidates_script_path();
            if !script.is_file() {
                return Ok(app_control_error("replan", json!({"code": "recovery_preflight_script_missing"})));
            }
            let mut cmd = killable_command(std::env::var("PYTHON").ok()
                .filter(|value| !value.trim().is_empty()).unwrap_or_else(|| "python3".into()));
            cmd.arg(script).arg("--journal").arg(journal)
                .arg("--minimum-recovery-secs").arg(minimum.to_string())
                .arg("--operation-id").arg(operation_id)
                .arg("--expected-record-sha256").arg(expected_record_sha256.unwrap())
                .arg("--intent-confirmed").arg("--intent-player").arg(player_selector)
                .arg("--intent-ttl-secs").arg(operation_ttl_secs.to_string())
                .arg("--workspace-root").arg(workspace_root.unwrap())
                .stdout(std::process::Stdio::piped()).stderr(std::process::Stdio::piped());
            let output = match tokio::time::timeout(Duration::from_millis(2_000), cmd.output()).await {
                Ok(Ok(output)) => output,
                _ => return Ok(app_control_error("retry", json!({"code": "recovery_preflight_unavailable"}))),
            };
            let mut payload: Value = match serde_json::from_slice(&output.stdout) {
                Ok(value) => value,
                Err(_) => return Ok(app_control_error("replan", json!({"code": "recovery_preflight_invalid_json"}))),
            };
            let safe = payload.get("schema").and_then(Value::as_str) == Some("agent_bridge.app_control.recovery_intent_preflight.v0")
                && payload.get("verdict").and_then(Value::as_str) == Some("verified")
                && payload.get("read_only").and_then(Value::as_bool) == Some(true)
                && payload.get("media_observed").and_then(Value::as_bool) == Some(false)
                && payload.get("action_invoked").and_then(Value::as_bool) == Some(false)
                && payload.get("automatic_recovery_authorized").and_then(Value::as_bool) == Some(false)
                && payload.get("selection_requested").and_then(Value::as_bool) == Some(true)
                && payload.pointer("/intent_binding/confirmed").and_then(Value::as_bool) == Some(true)
                && payload.pointer("/intent_binding/authenticated").and_then(Value::as_bool) == Some(false)
                && payload.pointer("/intent_binding/action").and_then(Value::as_str) == Some("next")
                && payload.pointer("/intent_binding/player_selector").and_then(Value::as_str) == Some(player_selector)
                && payload.pointer("/intent_binding/operation_ttl_secs").and_then(Value::as_u64) == Some(operation_ttl_secs)
                && matches!(payload.get("admission").and_then(Value::as_str), Some("eligible" | "conflict" | "expired" | "insufficient_context" | "selection_conflict"));
            let eligible_contract = payload.get("admission").and_then(Value::as_str) != Some("eligible") || (
                payload.get("recover").and_then(Value::as_str) == Some("proceed")
                && payload.get("candidate_count").and_then(Value::as_u64) == Some(1)
                && payload.pointer("/candidates/0/operation_id").and_then(Value::as_str) == Some(operation_id)
                && payload.pointer("/candidates/0/record_sha256").and_then(Value::as_str) == expected_record_sha256
                && payload.pointer("/candidates/0/request/action").and_then(Value::as_str) == Some("next")
                && payload.pointer("/candidates/0/request/player_selector").and_then(Value::as_str) == Some(player_selector)
                && payload.pointer("/candidates/0/request/operation_ttl_secs").and_then(Value::as_u64) == Some(operation_ttl_secs)
                && payload.pointer("/workspace_binding/declared_sha256").and_then(Value::as_str) == workspace_sha256.as_deref()
                && payload.pointer("/workspace_binding/recorded_sha256").and_then(Value::as_str) == workspace_sha256.as_deref()
                && payload.pointer("/workspace_binding/matches").and_then(Value::as_bool) == Some(true)
            );
            let blocked_contract = payload.get("admission").and_then(Value::as_str) == Some("eligible")
                || payload.get("recover").and_then(Value::as_str) == Some("replan");
            if !safe || !eligible_contract || !blocked_contract {
                return Ok(app_control_error("replan", json!({"code": "recovery_preflight_source_contract_mismatch"})));
            }
            if authorization_request && payload.get("admission").and_then(Value::as_str) == Some("eligible") {
                let Some(session_id) = _ctx.session_id.as_ref() else {
                    return Ok(app_control_error("replan", json!({"code": "authorization_source_unavailable"})));
                };
                let request_script = app_control_recovery_authorization_request_script_path();
                let session_sha256 = format!("{:x}", Sha256::digest(session_id.as_str().as_bytes()));
                let request_sha256 = payload.pointer("/candidates/0/request_digest").and_then(Value::as_str).unwrap();
                let mut request_cmd = killable_command(std::env::var("PYTHON").ok()
                    .filter(|value| !value.trim().is_empty()).unwrap_or_else(|| "python3".into()));
                request_cmd.arg(request_script).arg("--operation-id").arg(operation_id)
                    .arg("--record-sha256").arg(expected_record_sha256.unwrap())
                    .arg("--request-sha256").arg(request_sha256)
                    .arg("--workspace-sha256").arg(workspace_sha256.as_deref().unwrap())
                    .arg("--session-sha256").arg(session_sha256)
                    .stdout(std::process::Stdio::piped()).stderr(std::process::Stdio::null());
                let request_output = match tokio::time::timeout(Duration::from_millis(2_000), request_cmd.output()).await {
                    Ok(Ok(output)) => output,
                    _ => return Ok(app_control_error("retry", json!({"code": "recovery_authorization_request_unavailable"}))),
                };
                let request_payload: Value = match serde_json::from_slice(&request_output.stdout) {
                    Ok(value) => value,
                    Err(_) => return Ok(app_control_error("replan", json!({"code": "recovery_authorization_request_invalid_json"}))),
                };
                let request_safe = request_payload.get("schema").and_then(Value::as_str)
                    == Some("agent_bridge.app_control.recovery_authorization_broker_request.v0")
                    && request_payload.get("verdict").and_then(Value::as_str) == Some("verified")
                    && request_payload.get("read_only").and_then(Value::as_bool) == Some(true)
                    && request_payload.get("authorization_granted").and_then(Value::as_bool) == Some(false)
                    && request_payload.get("action_invoked").and_then(Value::as_bool) == Some(false)
                    && request_payload.get("automatic_recovery_authorized").and_then(Value::as_bool) == Some(false);
                if !request_safe { return Ok(app_control_error("replan", json!({"code": "recovery_authorization_request_contract_mismatch"}))); }
                return Ok(ToolResult::json_text(&request_payload));
            }
            if authorization_review && payload.get("admission").and_then(Value::as_str) == Some("eligible") {
                let Some(session_id) = _ctx.session_id.as_ref() else {
                    return Ok(ToolResult::json_text(&json!({"schema": "agent_bridge.app_control.recovery_authorization.v0",
                        "status": "verified", "verdict": "verified", "recover": "replan",
                        "admission": "source_unavailable", "read_only": true, "receipt_consumed": false,
                        "media_observed": false, "action_invoked": false, "automatic_recovery_authorized": false,
                        "error": {"code": "authorization_source_unavailable"}})));
                };
                let auth_script = app_control_recovery_authorization_script_path();
                if !auth_script.is_file() {
                    return Ok(app_control_error("replan", json!({"code": "recovery_authorization_script_missing"})));
                }
                let session_sha256 = format!("{:x}", Sha256::digest(session_id.as_str().as_bytes()));
                let request_sha256 = payload.pointer("/candidates/0/request_digest").and_then(Value::as_str).unwrap();
                let mut auth_cmd = killable_command(std::env::var("PYTHON").ok()
                    .filter(|value| !value.trim().is_empty()).unwrap_or_else(|| "python3".into()));
                auth_cmd.arg(auth_script).arg("--receipt").arg(authorization_receipt.unwrap())
                    .arg("--operation-id").arg(operation_id).arg("--record-sha256").arg(expected_record_sha256.unwrap())
                    .arg("--request-sha256").arg(request_sha256).arg("--workspace-sha256").arg(workspace_sha256.as_deref().unwrap())
                    .arg("--session-sha256").arg(session_sha256)
                    .stdout(std::process::Stdio::piped()).stderr(std::process::Stdio::null());
                if authorization_consume { auth_cmd.arg("--consume"); }
                let auth_output = match tokio::time::timeout(Duration::from_millis(2_000), auth_cmd.output()).await {
                    Ok(Ok(output)) => output,
                    _ => return Ok(app_control_error("retry", json!({"code": "recovery_authorization_unavailable"}))),
                };
                let mut auth_payload: Value = match serde_json::from_slice(&auth_output.stdout) {
                    Ok(value) => value,
                    Err(_) => return Ok(app_control_error("replan", json!({"code": "recovery_authorization_invalid_json"}))),
                };
                let admission = auth_payload.get("admission").and_then(Value::as_str).map(str::to_owned);
                let auth_safe = auth_payload.get("schema").and_then(Value::as_str) == Some("agent_bridge.app_control.recovery_authorization.v0")
                    && auth_payload.get("verdict").and_then(Value::as_str) == Some("verified")
                    && auth_payload.get("media_observed").and_then(Value::as_bool) == Some(false)
                    && auth_payload.get("action_invoked").and_then(Value::as_bool) == Some(false)
                    && auth_payload.get("automatic_recovery_authorized").and_then(Value::as_bool) == Some(false)
                    && matches!(admission.as_deref(), Some("authorized" | "expired" | "binding_conflict" | "already_consumed" | "source_unavailable"));
                if !auth_safe {
                    return Ok(app_control_error("replan", json!({"code": "recovery_authorization_source_contract_mismatch"})));
                }
                if let Some(object) = auth_payload.as_object_mut() {
                    object.insert("mcp_wrapper".into(), json!({"tool": "app_control", "mode": "recovery_authorization_review",
                        "source_contract_ok": true, "exact_preflight_admission": "eligible"}));
                }
                let mut result = ToolResult::json_text(&auth_payload);
                result.is_error = admission.as_deref() != Some("authorized");
                return Ok(result);
            }
            if let Some(object) = payload.as_object_mut() {
                object.insert("mcp_wrapper".into(), json!({"tool": "app_control", "mode": "recovery_intent_preflight", "source_contract_ok": true}));
            }
            let mut result = ToolResult::json_text(&payload);
            result.is_error = payload.get("admission").and_then(Value::as_str) != Some("eligible");
            return Ok(result);
        }
        if operation_id.is_some() {
            if action != "next" {
                return Ok(app_control_error(
                    "replan",
                    json!({
                        "code": "durable_action_not_supported",
                        "message": "the v0 durable operation slice supports action=next only"
                    }),
                ));
            }
            if dry_run {
                return Ok(app_control_error(
                    "replan",
                    json!({
                        "code": "durable_dry_run_not_supported",
                        "message": "omit operation_id for a read-only dry run"
                    }),
                ));
            }
            if args.get("cwd").is_some() || args.get("script_path").is_some() {
                return Ok(app_control_error(
                    "replan",
                    json!({
                        "code": "durable_operation_requires_installed_backend",
                        "message": "durable operations cannot use caller-selected backend paths"
                    }),
                ));
            }
        }
        let verify_timeout = match args.get("verify_timeout_secs") {
            None => 2.0,
            Some(value) => match value.as_f64() {
                Some(value) if (0.1..=10.0).contains(&value) => value,
                _ => {
                    return Ok(app_control_error(
                        "replan",
                        json!({"code": "invalid_verify_timeout_secs"}),
                    ))
                }
            },
        };
        let requested_timeout_ms = match args.get("timeout_ms") {
            None => None,
            Some(value) => match value.as_u64() {
                Some(value) if (1_000..=30_000).contains(&value) => Some(value),
                _ => {
                    return Ok(app_control_error(
                        "replan",
                        json!({"code": "invalid_timeout_ms"}),
                    ))
                }
            },
        };
        let timeout_ms = app_control_process_timeout_ms(
            requested_timeout_ms,
            verify_timeout,
            operation_id.is_some(),
        );
        let requested_volume = match args.get("volume") {
            None => None,
            Some(value) => match value.as_f64() {
                Some(value) if (0.0..=1.0).contains(&value) => Some(value),
                _ => {
                    return Ok(app_control_error(
                        "replan",
                        json!({"code": "invalid_volume", "message": "volume must be numeric in [0.0, 1.0]"}),
                    ))
                }
            },
        };
        if action == "volume_set" && requested_volume.is_none() {
            return Ok(app_control_error(
                "replan",
                json!({"code": "invalid_volume", "message": "volume_set requires volume in [0.0, 1.0]"}),
            ));
        }
        let requested_playlist_id = match args.get("playlist_id") {
            None => None,
            Some(Value::String(value))
                if !value.is_empty() && value.trim() == value.as_str() =>
            {
                Some(value.as_str())
            }
            Some(_) => {
                return Ok(app_control_error(
                    "replan",
                    json!({"code": "invalid_playlist_id"}),
                ))
            }
        };
        let cwd = match args.get("cwd") {
            None => None,
            Some(Value::String(value)) => Some(PathBuf::from(value)),
            Some(_) => {
                return Ok(app_control_error(
                    "replan",
                    json!({"code": "invalid_cwd"}),
                ))
            }
        };
        if args
            .get("script_path")
            .is_some_and(|value| !value.is_string())
        {
            return Ok(app_control_error(
                "replan",
                json!({"code": "invalid_script_path"}),
            ));
        }
        let script = if operation_id.is_some() {
            app_control_durable_script_path()
        } else {
            app_control_script_path(&args, cwd.as_ref())
        };
        if !script.exists() {
            return Ok(app_control_error("replan", json!({
                "code": "script_missing", "message": format!("app_control.py not found at {}", script.display())
            })));
        }

        let mut cmd = killable_command(
            std::env::var("PYTHON")
                .ok()
                .filter(|value| !value.trim().is_empty())
                .unwrap_or_else(|| "python3".into()),
        );
        cmd.arg(&script)
            .arg("--domain")
            .arg("media")
            .arg("--action")
            .arg(&action)
            .arg("--verify-timeout")
            .arg(verify_timeout.to_string());
        if !dry_run
            && matches!(
                action.as_str(),
                "next"
                    | "previous"
                    | "play"
                    | "pause"
                    | "play_pause"
                    | "stop"
                    | "volume_up"
                    | "volume_down"
                    | "volume_set"
                    | "playlist_activate"
            )
        {
            cmd.arg("--wrapper-contract-version")
                .arg(APP_CONTROL_WRAPPER_CONTRACT_SCHEMA);
        }
        if let Some(volume) = requested_volume {
            cmd.arg("--volume").arg(volume.to_string());
        }
        if let Some(playlist_id) = requested_playlist_id {
            cmd.arg("--playlist-id").arg(playlist_id);
        }
        if let Some(player) = player_selector {
            cmd.arg("--player").arg(player);
        }
        if let Some(operation_id) = operation_id.as_deref() {
            cmd.arg("--operation-id")
                .arg(operation_id)
                .arg("--operation-ttl-secs")
                .arg(operation_ttl_secs.to_string());
            if let Some(workspace_sha256) = workspace_sha256.as_deref() {
                cmd.arg("--workspace-sha256").arg(workspace_sha256);
            }
        }
        if dry_run {
            cmd.arg("--dry-run");
        }
        cmd.stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped());
        if let Some(cwd) = cwd {
            cmd.current_dir(cwd);
        }

        let started = Instant::now();
        let output = match tokio::time::timeout(Duration::from_millis(timeout_ms), cmd.output()).await
        {
            Err(_) => {
                return Ok(app_control_error(
                    "retry",
                    json!({"code": "timeout", "duration_ms": started.elapsed().as_millis()}),
                ))
            }
            Ok(Err(error)) => {
                return Ok(app_control_error(
                    "retry",
                    json!({"code": "spawn_failed", "message": error.to_string()}),
                ))
            }
            Ok(Ok(output)) => output,
        };
        let duration_ms = started.elapsed().as_millis() as u64;
        let (stdout, stdout_truncated) = lossy_truncate(&output.stdout);
        let (stderr, stderr_truncated) = lossy_truncate(&output.stderr);
        let mut payload = match serde_json::from_str::<Value>(&stdout) {
            Ok(payload) => payload,
            Err(error) => return Ok(app_control_error("retry", json!({
                "code": "invalid_json", "message": error.to_string(), "exit_code": output.status.code().unwrap_or(-1),
                "stdout": stdout, "stderr": stderr
            }))),
        };
        let exit_code = output.status.code().unwrap_or(-1);
        let source_contract_ok = app_control_source_contract_valid(
            &payload,
            domain,
            &action,
            dry_run,
            operation_id.as_deref(),
            player_selector,
            requested_volume,
            requested_playlist_id,
            operation_ttl_secs,
            exit_code,
        );
        if let Some(object) = payload.as_object_mut() {
            object.insert("mcp_wrapper".into(), json!({
                "tool": self.name(), "duration_ms": duration_ms,
                "exit_code": exit_code, "stderr": stderr,
                "truncated": stdout_truncated || stderr_truncated,
                "source_contract_ok": source_contract_ok,
                "operation_id_bound": operation_id.is_some()
            }));
        }
        if !source_contract_ok {
            return Ok(app_control_error("replan", json!({
                "code": "source_contract_mismatch",
                "exit_code": exit_code,
                "source": payload
            })));
        }
        let verified = payload.get("verdict").and_then(Value::as_str) == Some("verified");
        let mut result = ToolResult::json_text(&payload);
        result.is_error = !verified;
        Ok(result)
    }
}

fn app_control_preflight_source_contract_valid(
    payload: &Value,
    operation_id: &str,
    player_selector: Option<&str>,
    operation_ttl_secs: u64,
    exit_code: i32,
) -> bool {
    let verdict = payload.get("verdict").and_then(Value::as_str);
    let status = payload.get("status").and_then(Value::as_str);
    let preflight = match payload.get("preflight").and_then(Value::as_object) {
        Some(value) => value,
        None => return false,
    };
    let expected_request = json!({
        "schema": "agent_bridge.app_control.v0",
        "action": "next",
        "player_selector": player_selector,
        "operation_ttl_secs": operation_ttl_secs
    });
    let expected_digest =
        app_control_operation_request_digest("next", player_selector, operation_ttl_secs);
    let outcome = preflight.get("outcome").and_then(Value::as_str);
    let candidate = preflight.get("candidate").and_then(Value::as_bool);
    let blocked = preflight.get("blocked").and_then(Value::as_bool);
    let candidate_state = matches!(
        status,
        Some(
            "fresh_candidate"
                | "retryable_candidate"
                | "terminal_replay_candidate"
                | "recovery_observation_candidate"
        )
    );
    let blocked_state = matches!(
        status,
        Some(
            "operation_expired"
                | "idempotency_conflict"
                | "terminal_operation_not_verified"
                | "operation_record_invalid"
                | "operation_journal_unavailable"
                | "operation_lock_busy"
        )
    );
    if payload.get("schema").and_then(Value::as_str) != Some("agent_bridge.app_control.v0")
        || payload.get("domain").and_then(Value::as_str) != Some("media")
        || payload.get("action").and_then(Value::as_str) != Some("next")
        || payload.get("read_only").and_then(Value::as_bool) != Some(true)
        || payload.get("preflight_only").and_then(Value::as_bool) != Some(true)
        || preflight.get("schema").and_then(Value::as_str)
            != Some("agent_bridge.app_control.operation_preflight.v0")
        || preflight.get("state").and_then(Value::as_str) != status
        || preflight.get("operation_id").and_then(Value::as_str) != Some(operation_id)
        || preflight.get("request") != Some(&expected_request)
        || preflight.get("request_digest").and_then(Value::as_str)
            != Some(expected_digest.as_str())
        || preflight.get("advisory").and_then(Value::as_bool) != Some(true)
        || preflight.get("must_revalidate").and_then(Value::as_bool) != Some(true)
        || preflight.get("dispatch_authorized").and_then(Value::as_bool) != Some(false)
        || preflight.get("reservation_created").and_then(Value::as_bool) != Some(false)
        || preflight.get("operation_record_mutated").and_then(Value::as_bool) != Some(false)
        || preflight.get("player_observed").and_then(Value::as_bool) != Some(false)
        || preflight.get("effect_verified").and_then(Value::as_bool) != Some(false)
        || preflight.get("automatic_new_id_allowed").and_then(Value::as_bool) != Some(false)
        || !preflight
            .get("observed_at_unix_seconds")
            .and_then(Value::as_f64)
            .is_some_and(|value| value.is_finite() && value > 0.0)
        || payload
            .pointer("/claim_boundary/authorizes_dispatch")
            .and_then(Value::as_bool)
            != Some(false)
        || payload
            .pointer("/claim_boundary/reserves_operation_id")
            .and_then(Value::as_bool)
            != Some(false)
        || payload
            .pointer("/claim_boundary/lock_held_at_return")
            .and_then(Value::as_bool)
            != Some(false)
        || payload
            .pointer("/claim_boundary/state_unchanged_until_action")
            .and_then(Value::as_bool)
            != Some(false)
        || payload
            .pointer("/claim_boundary/player_observed")
            .and_then(Value::as_bool)
            != Some(false)
        || payload
            .pointer("/claim_boundary/effect_verified")
            .and_then(Value::as_bool)
            != Some(false)
        || payload
            .pointer("/claim_boundary/current_track_verified")
            .and_then(Value::as_bool)
            != Some(false)
        || preflight
            .get("recommended_next")
            .and_then(Value::as_str)
            .is_none_or(str::is_empty)
        || !preflight
            .get("record_present")
            .is_some_and(|value| value.is_boolean() || value.is_null())
        || !preflight
            .get("lock_present")
            .is_some_and(|value| value.is_boolean() || value.is_null())
    {
        return false;
    }
    if let Some(digest) = preflight.get("record_sha256").and_then(Value::as_str) {
        if digest.len() != 64
            || !digest
                .bytes()
                .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
        {
            return false;
        }
    } else if !preflight
        .get("record_sha256")
        .is_some_and(Value::is_null)
    {
        return false;
    }
    let result_shape_ok = match verdict {
        Some("verified") => {
            exit_code == 0
                && candidate_state
                && outcome == Some("eligible")
                && candidate == Some(true)
                && blocked == Some(false)
                && payload.get("recover").and_then(Value::as_str) == Some("proceed")
                && payload.get("error").is_some_and(Value::is_null)
                && preflight.get("same_id_retry_allowed").and_then(Value::as_bool)
                    == Some(true)
                && preflight
                    .get("operation_id_disposition")
                    .and_then(Value::as_str)
                    == Some("reusable_same_request")
        }
        Some("error") => {
            exit_code == 2
                && blocked_state
                && matches!(outcome, Some("blocked" | "indeterminate"))
                && candidate == Some(false)
                && blocked == Some(true)
                && matches!(
                    payload.get("recover").and_then(Value::as_str),
                    Some("retry" | "replan")
                )
                && payload.pointer("/error/code").and_then(Value::as_str) == status
        }
        _ => false,
    };
    if !result_shape_ok {
        return false;
    }
    match status {
        Some("fresh_candidate") => {
            preflight.get("record_present").and_then(Value::as_bool) == Some(false)
                && preflight.get("observed_phase").is_some_and(Value::is_null)
                && preflight.get("dispatch_count").and_then(Value::as_u64) == Some(0)
                && preflight.get("expires_at").is_some_and(Value::is_null)
                && preflight.get("remaining_secs").is_some_and(Value::is_null)
                && preflight.get("terminal_verdict").is_some_and(Value::is_null)
                && preflight.get("record_sha256").is_some_and(Value::is_null)
                && preflight.get("lock_present").and_then(Value::as_bool).is_some()
        }
        Some("retryable_candidate") => {
            app_control_preflight_existing_candidate_valid(preflight, "retryable", 0)
                && preflight.get("terminal_verdict").is_some_and(Value::is_null)
        }
        Some("terminal_replay_candidate") => {
            app_control_preflight_existing_candidate_valid(preflight, "terminal", 1)
                && preflight.get("terminal_verdict").and_then(Value::as_str)
                    == Some("verified")
        }
        Some("recovery_observation_candidate") => {
            app_control_preflight_existing_candidate_valid(preflight, "dispatch_started", 1)
                && preflight.get("terminal_verdict").is_some_and(Value::is_null)
        }
        Some("operation_lock_busy") => {
            outcome == Some("indeterminate")
                && payload.get("recover").and_then(Value::as_str) == Some("retry")
                && preflight.get("record_present").is_some_and(Value::is_null)
                && preflight.get("lock_present").and_then(Value::as_bool) == Some(true)
                && preflight.get("observed_phase").is_some_and(Value::is_null)
                && preflight.get("dispatch_count").is_some_and(Value::is_null)
                && preflight.get("record_sha256").is_some_and(Value::is_null)
                && preflight
                    .get("operation_id_disposition")
                    .and_then(Value::as_str)
                    == Some("indeterminate_do_not_replace_automatically")
                && preflight.get("same_id_retry_allowed").and_then(Value::as_bool)
                    == Some(true)
        }
        Some("operation_expired") => {
            app_control_preflight_existing_record_evidence_valid(preflight)
                && preflight.get("operation_id_disposition").and_then(Value::as_str)
                    == Some("expired")
                && preflight.get("same_id_retry_allowed").and_then(Value::as_bool)
                    == Some(false)
        }
        Some("idempotency_conflict") => {
            app_control_preflight_existing_record_evidence_valid(preflight)
                && preflight.get("operation_id_disposition").and_then(Value::as_str)
                    == Some("conflicts_with_request")
                && preflight.get("same_id_retry_allowed").and_then(Value::as_bool)
                    == Some(false)
        }
        Some("terminal_operation_not_verified") => {
            app_control_preflight_existing_record_evidence_valid(preflight)
                && preflight.get("operation_id_disposition").and_then(Value::as_str)
                    == Some("terminal_failure")
                && preflight.get("same_id_retry_allowed").and_then(Value::as_bool)
                    == Some(false)
        }
        Some("operation_record_invalid" | "operation_journal_unavailable") => {
            preflight.get("operation_id_disposition").and_then(Value::as_str)
                == Some("invalid_or_unavailable")
                && preflight.get("same_id_retry_allowed").and_then(Value::as_bool)
                    == Some(false)
        }
        _ => false,
    }
}

fn app_control_preflight_existing_record_evidence_valid(
    preflight: &serde_json::Map<String, Value>,
) -> bool {
    preflight.get("record_present").and_then(Value::as_bool) == Some(true)
        && preflight.get("lock_present").and_then(Value::as_bool) == Some(true)
        && preflight
            .get("record_sha256")
            .and_then(Value::as_str)
            .is_some_and(|digest| {
                digest.len() == 64
                    && digest
                        .bytes()
                        .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
            })
}

fn app_control_preflight_existing_candidate_valid(
    preflight: &serde_json::Map<String, Value>,
    expected_phase: &str,
    expected_dispatch_count: u64,
) -> bool {
    preflight.get("record_present").and_then(Value::as_bool) == Some(true)
        && preflight.get("lock_present").and_then(Value::as_bool) == Some(true)
        && preflight.get("observed_phase").and_then(Value::as_str) == Some(expected_phase)
        && preflight.get("dispatch_count").and_then(Value::as_u64)
            == Some(expected_dispatch_count)
        && preflight
            .get("expires_at")
            .and_then(Value::as_f64)
            .is_some_and(|value| value.is_finite() && value > 0.0)
        && preflight
            .get("remaining_secs")
            .and_then(Value::as_f64)
            .is_some_and(|value| value.is_finite() && value > 0.0)
        && preflight
            .get("record_sha256")
            .and_then(Value::as_str)
            .is_some()
}

fn app_control_settled_track_evidence_valid(
    verification: &serde_json::Map<String, Value>,
    after_track_id: &str,
) -> bool {
    let Some(settlement) = verification.get("settlement").and_then(Value::as_object) else {
        return false;
    };
    let Some(observed_count) = settlement
        .get("observed_consecutive_observations")
        .and_then(Value::as_u64)
    else {
        return false;
    };
    let Some(observed_stable_ms) = settlement.get("observed_stable_ms").and_then(Value::as_u64)
    else {
        return false;
    };
    let Some(polls) = verification.get("polls").and_then(Value::as_u64) else {
        return false;
    };

    settlement.get("schema").and_then(Value::as_str)
        == Some("agent_bridge.app_control.track_settlement.v0")
        && settlement.get("candidate_track_id").and_then(Value::as_str) == Some(after_track_id)
        && settlement
            .get("required_consecutive_observations")
            .and_then(Value::as_u64)
            == Some(3)
        && observed_count >= 3
        && settlement.get("required_stable_ms").and_then(Value::as_u64) == Some(500)
        && observed_stable_ms >= 500
        && settlement.get("settled").and_then(Value::as_bool) == Some(true)
        && polls >= observed_count
}

fn app_control_pending_track_evidence_valid(
    payload: &Value,
    transaction: &serde_json::Map<String, Value>,
    player_selector: Option<&str>,
) -> bool {
    if payload.get("status").and_then(Value::as_str) != Some("indeterminate")
        || payload.get("verdict").and_then(Value::as_str) != Some("error")
        || payload.get("recover").and_then(Value::as_str) != Some("retry")
        || payload.get("read_only").and_then(Value::as_bool) != Some(false)
        || transaction.get("phase").and_then(Value::as_str) != Some("dispatch_started")
        || transaction.get("dispatch_count").and_then(Value::as_u64) != Some(1)
        || transaction.get("idempotent_replay").and_then(Value::as_bool) != Some(false)
        || payload.pointer("/error/code").and_then(Value::as_str)
            != Some("operation_effect_not_settled")
        || !payload
            .pointer("/error/message")
            .and_then(Value::as_str)
            .is_some_and(|message| !message.is_empty())
    {
        return false;
    }

    let Some(player) = payload
        .get("player")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
    else {
        return false;
    };
    let Some(before_track_id) = payload
        .pointer("/before/track_id")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
    else {
        return false;
    };
    if payload.pointer("/selection/selected_player").and_then(Value::as_str) != Some(player)
        || !app_control_selector_echo_valid(payload, player_selector)
        || payload.pointer("/before/player").and_then(Value::as_str) != Some(player)
        || payload.pointer("/after/player").and_then(Value::as_str) != Some(player)
    {
        return false;
    }

    let Some(verification) = payload.get("verification").and_then(Value::as_object) else {
        return false;
    };
    let Some(reason) = verification.get("reason").and_then(Value::as_str) else {
        return false;
    };
    let Some(polls) = verification.get("polls").and_then(Value::as_u64) else {
        return false;
    };
    if polls == 0
        || verification.get("status").and_then(Value::as_str) != Some("indeterminate")
        || verification.get("predicate").and_then(Value::as_str)
            != Some("track_identity_change_not_settled")
        || payload.pointer("/error/reason").and_then(Value::as_str) != Some(reason)
    {
        return false;
    }
    let observation_error_valid = match reason {
        "observation_failed" => verification
            .get("observation_error")
            .is_some_and(Value::is_object),
        "track_id_unchanged" | "current_track_id_missing" | "track_settlement_pending" => {
            verification
                .get("observation_error")
                .is_some_and(Value::is_null)
        }
        _ => false,
    };
    if !observation_error_valid {
        return false;
    }

    let Some(settlement) = verification.get("settlement").and_then(Value::as_object) else {
        return false;
    };
    let Some(observed_count) = settlement
        .get("observed_consecutive_observations")
        .and_then(Value::as_u64)
    else {
        return false;
    };
    let Some(observed_stable_ms) = settlement.get("observed_stable_ms").and_then(Value::as_u64)
    else {
        return false;
    };
    if settlement.get("schema").and_then(Value::as_str)
        != Some("agent_bridge.app_control.track_settlement.v0")
        || settlement
            .get("required_consecutive_observations")
            .and_then(Value::as_u64)
            != Some(3)
        || settlement.get("required_stable_ms").and_then(Value::as_u64) != Some(500)
        || settlement.get("settled").and_then(Value::as_bool) != Some(false)
        || polls < observed_count
    {
        return false;
    }
    let candidate_valid = match reason {
        "track_settlement_pending" => settlement
            .get("candidate_track_id")
            .and_then(Value::as_str)
            .filter(|candidate| !candidate.is_empty() && *candidate != before_track_id)
            .is_some_and(|candidate| {
                observed_count >= 1
                    && payload.pointer("/after/track_id").and_then(Value::as_str)
                        == Some(candidate)
            }),
        "track_id_unchanged" => {
            settlement
                .get("candidate_track_id")
                .is_some_and(Value::is_null)
                && observed_count == 0
                && observed_stable_ms == 0
                && payload.pointer("/after/track_id").and_then(Value::as_str)
                    == Some(before_track_id)
        }
        "current_track_id_missing" => {
            settlement
                .get("candidate_track_id")
                .is_some_and(Value::is_null)
                && observed_count == 0
                && observed_stable_ms == 0
                && payload.pointer("/after/track_id").is_some_and(Value::is_null)
        }
        "observation_failed" => {
            settlement
                .get("candidate_track_id")
                .is_some_and(Value::is_null)
                && observed_count == 0
                && observed_stable_ms == 0
        }
        _ => false,
    };
    if !candidate_valid {
        return false;
    }

    let recovered = transaction
        .get("recovered_after_interruption")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    if recovered {
        payload.get("dispatch").is_none()
            && payload.get("causal_attribution").and_then(Value::as_str)
                == Some("unknown_after_restart")
            && verification
                .get("causal_attribution")
                .and_then(Value::as_str)
                == Some("unknown_after_restart")
    } else {
        payload
            .get("dispatch")
            .and_then(Value::as_object)
            .is_some_and(|dispatch| {
                dispatch.get("status").and_then(Value::as_str) == Some("dispatched")
                    && dispatch.get("rc").and_then(Value::as_i64) == Some(0)
                    && dispatch.get("argv")
                        == Some(&json!(["playerctl", "-p", player, "next"]))
            })
            && payload.get("causal_attribution").is_none()
            && verification.get("causal_attribution").is_none()
    }
}

fn app_control_expired_dispatch_started_valid(
    payload: &Value,
    transaction: &serde_json::Map<String, Value>,
) -> bool {
    payload.get("status").and_then(Value::as_str) == Some("error")
        && payload.get("verdict").and_then(Value::as_str) == Some("error")
        && payload.get("recover").and_then(Value::as_str) == Some("replan")
        && payload.pointer("/error/code").and_then(Value::as_str) == Some("operation_expired")
        && payload
            .pointer("/error/message")
            .and_then(Value::as_str)
            .is_some_and(|message| !message.is_empty())
        && payload.pointer("/error/reason").is_none()
        && transaction.get("phase").and_then(Value::as_str) == Some("dispatch_started")
        && transaction.get("dispatch_count").and_then(Value::as_u64) == Some(1)
        && transaction.get("idempotent_replay").and_then(Value::as_bool) == Some(false)
        && transaction
            .get("expires_at")
            .and_then(Value::as_f64)
            .is_some_and(|value| value.is_finite() && value > 0.0)
        && payload.get("read_only").is_none()
        && payload.get("player").is_none()
        && payload.get("selection").is_none()
        && payload.get("before").is_none()
        && payload.get("after").is_none()
        && payload.get("dispatch").is_none()
        && payload.get("verification").is_none()
        && payload.get("causal_attribution").is_none()
}

fn app_control_source_contract_valid(
    payload: &Value,
    domain: &str,
    action: &str,
    dry_run: bool,
    operation_id: Option<&str>,
    player_selector: Option<&str>,
    requested_volume: Option<f64>,
    requested_playlist_id: Option<&str>,
    operation_ttl_secs: u64,
    exit_code: i32,
) -> bool {
    let verdict = payload.get("verdict").and_then(Value::as_str);
    let base_ok = payload.get("schema").and_then(Value::as_str)
        == Some("agent_bridge.app_control.v0")
        && payload.get("domain").and_then(Value::as_str) == Some(domain)
        && payload.get("action").and_then(Value::as_str) == Some(action)
        && matches!(verdict, Some("verified" | "unmet" | "error"))
        && match verdict {
            Some("verified") => exit_code == 0,
            Some("unmet" | "error") => exit_code == 2,
            _ => false,
        };
    if !base_ok {
        return false;
    }
    if verdict != Some("verified") {
        if !matches!(
            payload.get("recover").and_then(Value::as_str),
            Some("retry" | "replan")
        ) {
            return false;
        }
    } else if payload.get("recover").and_then(Value::as_str) != Some("proceed") {
        return false;
    }
    let Some(operation_id) = operation_id else {
        return verdict != Some("verified")
            || app_control_verified_claim_valid(
                payload,
                action,
                dry_run,
                player_selector,
                requested_volume,
                requested_playlist_id,
            );
    };
    if dry_run || action != "next" {
        return false;
    }
    let transaction = match payload.get("transaction") {
        Some(Value::Object(transaction)) => transaction,
        _ => return false,
    };
    let expected_request_digest =
        app_control_operation_request_digest(action, player_selector, operation_ttl_secs);
    if transaction.get("schema").and_then(Value::as_str)
        != Some("agent_bridge.app_control.operation.v0")
        || transaction.get("operation_id").and_then(Value::as_str) != Some(operation_id)
        || transaction.get("request_digest").and_then(Value::as_str)
            != Some(expected_request_digest.as_str())
        || transaction.get("external_execution_repeated").and_then(Value::as_bool) != Some(false)
    {
        return false;
    }
    let Some(dispatch_count) = transaction.get("dispatch_count").and_then(Value::as_u64) else {
        return false;
    };
    if dispatch_count > 1
        || transaction
            .get("idempotent_replay")
            .and_then(Value::as_bool)
            .is_none()
        || transaction
            .get("recovered_after_interruption")
            .and_then(Value::as_bool)
            .is_none()
    {
        return false;
    }
    if verdict != Some("verified") {
        let recover = payload.get("recover").and_then(Value::as_str);
        let phase = transaction.get("phase").and_then(Value::as_str);
        let error_code = payload.pointer("/error/code").and_then(Value::as_str);
        if error_code == Some("operation_effect_not_settled") {
            return app_control_pending_track_evidence_valid(
                payload,
                transaction,
                player_selector,
            );
        }
        if phase == Some("dispatch_started") {
            return error_code == Some("operation_expired")
                && app_control_expired_dispatch_started_valid(payload, transaction);
        }
        return matches!(recover, Some("retry" | "replan"))
            && matches!(
                phase,
                Some(
                    "rejected"
                        | "lock_busy"
                        | "journal_error"
                        | "retryable"
                        | "terminal"
                        | "indeterminate"
                        | "journal_write_failed"
                )
            );
    }
    if payload.get("status").and_then(Value::as_str) != Some("verified")
        || payload.get("error").is_some()
        || transaction.get("phase").and_then(Value::as_str) != Some("verified")
        || dispatch_count != 1
    {
        return false;
    }
    if payload.get("read_only").and_then(Value::as_bool) != Some(false)
        || payload
            .get("verification")
            .and_then(|value| value.get("status"))
            .and_then(Value::as_str)
            != Some("verified")
    {
        return false;
    }
    let Some(verification) = payload.get("verification").and_then(Value::as_object) else {
        return false;
    };
    if !verification.get("reason").is_some_and(Value::is_null)
        || !verification
            .get("observation_error")
            .is_some_and(Value::is_null)
    {
        return false;
    }
    let predicate = verification.get("predicate").and_then(Value::as_str);
    if !matches!(
        predicate,
        Some("track_identity_changed_settled" | "track_identity_changed_after_restart_settled")
    ) {
        return false;
    }
    let recovered = transaction["recovered_after_interruption"]
        .as_bool()
        .unwrap_or(false);
    let Some(player) = payload
        .get("player")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
    else {
        return false;
    };
    if payload.pointer("/selection/selected_player").and_then(Value::as_str) != Some(player)
        || !app_control_selector_echo_valid(payload, player_selector)
        || payload.pointer("/before/player").and_then(Value::as_str) != Some(player)
        || payload.pointer("/after/player").and_then(Value::as_str) != Some(player)
    {
        return false;
    }
    let before_track_id = payload
        .pointer("/before/track_id")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty());
    let after_track_id = payload
        .pointer("/after/track_id")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty());
    if before_track_id.is_none()
        || after_track_id.is_none()
        || before_track_id == after_track_id
    {
        return false;
    }
    if !app_control_settled_track_evidence_valid(
        verification,
        after_track_id.expect("non-empty after track id checked above"),
    ) {
        return false;
    }
    let fresh_dispatch = payload
        .get("dispatch")
        .and_then(Value::as_object)
        .is_some_and(|dispatch| {
            dispatch.get("status").and_then(Value::as_str) == Some("dispatched")
                && dispatch.get("rc").and_then(Value::as_i64) == Some(0)
                && dispatch.get("argv") == Some(&json!(["playerctl", "-p", player, "next"]))
    });
    match predicate {
        Some("track_identity_changed_settled") => {
            !recovered
                && fresh_dispatch
                && payload.get("causal_attribution").is_none()
                && verification.get("causal_attribution").is_none()
        }
        Some("track_identity_changed_after_restart_settled") => {
            recovered
                && payload.get("dispatch").is_none()
                && payload.get("causal_attribution").and_then(Value::as_str)
                    == Some("unknown_after_restart")
                && payload
                    .pointer("/verification/causal_attribution")
                    .and_then(Value::as_str)
                    == Some("unknown_after_restart")
        }
        _ => false,
    }
}

fn app_control_verified_claim_valid(
    payload: &Value,
    action: &str,
    dry_run: bool,
    player_selector: Option<&str>,
    requested_volume: Option<f64>,
    requested_playlist_id: Option<&str>,
) -> bool {
    if action == "discover" {
        return payload.get("read_only").and_then(Value::as_bool) == Some(true)
            && payload
                .pointer("/capabilities/available")
                .and_then(Value::as_bool)
                == Some(true)
            && payload
                .pointer("/capabilities/players")
                .is_some_and(Value::is_array);
    }

    let Some(player) = payload
        .get("player")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
    else {
        return false;
    };
    if payload.pointer("/selection/selected_player").and_then(Value::as_str) != Some(player)
        || !app_control_selector_echo_valid(payload, player_selector)
    {
        return false;
    }

    let read_only_predicate = match action {
        "volume_get" => Some("volume_observed"),
        "state_get" => Some("player_state_observed"),
        "position_get" => Some("media_position_observed"),
        "playlist_list" => Some("playlist_catalog_observed"),
        "playlist_current" => Some("active_playlist_observed"),
        _ => None,
    };
    let verification_status = payload
        .pointer("/verification/status")
        .and_then(Value::as_str);
    let predicate = payload
        .pointer("/verification/predicate")
        .and_then(Value::as_str);
    if let Some(expected) = read_only_predicate {
        if payload.get("read_only").and_then(Value::as_bool) != Some(true)
            || verification_status != Some("verified")
            || predicate != Some(expected)
        {
            return false;
        }
        return match action {
            "volume_get" => {
                payload.pointer("/before/player").and_then(Value::as_str) == Some(player)
                    && payload.pointer("/before/volume").and_then(Value::as_f64).is_some()
            }
            "state_get" => {
                payload.pointer("/before/player").and_then(Value::as_str) == Some(player)
                    && payload
                        .pointer("/before/playback_status")
                        .and_then(Value::as_str)
                        .is_some_and(|value| !value.is_empty())
            }
            "position_get" => {
                payload.pointer("/before/player").and_then(Value::as_str) == Some(player)
                    && payload.pointer("/before/position_available").and_then(Value::as_bool)
                    == Some(true)
                    && payload.pointer("/before/position_seconds").and_then(Value::as_f64).is_some()
                    && payload.pointer("/before/duration_seconds").and_then(Value::as_f64).is_some()
            }
            "playlist_list" => payload
                .get("playlists")
                .and_then(Value::as_array)
                .is_some_and(|items| {
                    items.iter().all(|item| {
                        item.get("id")
                            .and_then(Value::as_str)
                            .is_some_and(|value| !value.is_empty())
                            && item.get("name").and_then(Value::as_str).is_some()
                    })
                }),
            "playlist_current" => payload
                .get("active_playlist")
                .and_then(Value::as_object)
                .is_some_and(|active| match active.get("active").and_then(Value::as_bool) {
                    Some(true) => active
                        .get("id")
                        .and_then(Value::as_str)
                        .is_some_and(|value| !value.is_empty()),
                    Some(false) => active.get("id").is_none_or(Value::is_null),
                    None => false,
                }),
            _ => false,
        };
    }

    if dry_run {
        if payload.get("read_only").and_then(Value::as_bool) != Some(true)
            || payload.pointer("/dispatch/status").and_then(Value::as_str)
                != Some("not_dispatched_dry_run")
            || verification_status != Some("not_run")
        {
            return false;
        }
        let dispatch_argv = payload.pointer("/dispatch/argv");
        let before_player_matches =
            payload.pointer("/before/player").and_then(Value::as_str) == Some(player);
        return match action {
            "next" | "previous" | "play" | "pause" | "stop" => {
                before_player_matches
                    && dispatch_argv == Some(&json!(["playerctl", "-p", player, action]))
            }
            "play_pause" => {
                before_player_matches
                    && dispatch_argv
                        == Some(&json!(["playerctl", "-p", player, "play-pause"]))
            }
            "volume_up" | "volume_down" => {
                before_player_matches
                    && payload
                        .pointer("/before/volume")
                        .and_then(Value::as_f64)
                        .is_some_and(|before| {
                            let planned = if action == "volume_up" {
                                before + 0.05
                            } else {
                                before - 0.05
                            }
                            .clamp(0.0, 1.0);
                            dispatch_argv
                                == Some(&json!([
                                    "playerctl",
                                    "-p",
                                    player,
                                    "volume",
                                    format!("{planned:.3}")
                                ]))
                        })
            }
            "volume_set" => {
                before_player_matches
                    && requested_volume.is_some_and(|target| {
                        dispatch_argv
                            == Some(&json!([
                                "playerctl",
                                "-p",
                                player,
                                "volume",
                                format!("{target:.3}")
                            ]))
                    })
            }
            "playlist_activate" => requested_playlist_id.is_some_and(|playlist_id| {
                payload.get("playlist_id").and_then(Value::as_str) == Some(playlist_id)
                    && payload
                        .get("playlists")
                        .and_then(Value::as_array)
                        .is_some_and(|playlists| {
                            playlists.iter().any(|playlist| {
                                playlist.get("id").and_then(Value::as_str) == Some(playlist_id)
                            })
                        })
                    && dispatch_argv
                        == Some(&app_control_playlist_activate_argv(player, playlist_id))
            }),
            _ => false,
        };
    }

    let expected_predicate = match action {
        "next" | "previous" => "track_identity_changed",
        "play" => "playback_status_is_playing",
        "pause" => "playback_status_is_paused",
        "play_pause" => "playback_status_changed",
        "stop" => "playback_status_is_stopped",
        "volume_up" | "volume_down" => "volume_changed_in_requested_direction",
        "volume_set" => "volume_is_requested",
        "playlist_activate" => "playlist_active_id_matches_target",
        _ => return false,
    };
    if payload.get("read_only").and_then(Value::as_bool) != Some(false)
        || payload.pointer("/dispatch/status").and_then(Value::as_str) != Some("dispatched")
        || payload.pointer("/dispatch/rc").and_then(Value::as_i64) != Some(0)
        || verification_status != Some("verified")
        || predicate != Some(expected_predicate)
        || payload.pointer("/before/player").and_then(Value::as_str) != Some(player)
        || payload.pointer("/after/player").and_then(Value::as_str) != Some(player)
    {
        return false;
    }
    let dispatch_argv = payload.pointer("/dispatch/argv");
    let before = payload.get("before").and_then(Value::as_object);
    let after = payload.get("after").and_then(Value::as_object);
    match action {
        "next" | "previous" => {
            let (Some(before), Some(after)) = (before, after) else {
                return false;
            };
            let before_track_id = before
                .get("track_id")
                .and_then(Value::as_str)
                .filter(|value| !value.is_empty());
            let after_track_id = after
                .get("track_id")
                .and_then(Value::as_str)
                .filter(|value| !value.is_empty());
            dispatch_argv == Some(&json!(["playerctl", "-p", player, action]))
                && before_track_id.is_some()
                && after_track_id.is_some()
                && before_track_id != after_track_id
        }
        "play" | "pause" | "stop" => {
            let command = action;
            let expected_status = match action {
                "play" => "Playing",
                "pause" => "Paused",
                "stop" => "Stopped",
                _ => unreachable!(),
            };
            dispatch_argv == Some(&json!(["playerctl", "-p", player, command]))
                && payload
                    .pointer("/after/playback_status")
                    .and_then(Value::as_str)
                    == Some(expected_status)
        }
        "play_pause" => {
            let before_status = payload
                .pointer("/before/playback_status")
                .and_then(Value::as_str);
            let after_status = payload
                .pointer("/after/playback_status")
                .and_then(Value::as_str);
            dispatch_argv == Some(&json!(["playerctl", "-p", player, "play-pause"]))
                && before_status.is_some_and(app_control_playback_status_valid)
                && after_status.is_some_and(app_control_playback_status_valid)
                && before_status != after_status
        }
        "volume_up" | "volume_down" | "volume_set" => {
            let argv = dispatch_argv.and_then(Value::as_array);
            let Some(argv) = argv else {
                return false;
            };
            if argv.len() != 5
                || argv[0] != "playerctl"
                || argv[1] != "-p"
                || argv[2] != player
                || argv[3] != "volume"
            {
                return false;
            }
            let Some(commanded) = argv[4].as_str().and_then(|value| value.parse::<f64>().ok())
            else {
                return false;
            };
            let before_volume = payload.pointer("/before/volume").and_then(Value::as_f64);
            let after_volume = payload.pointer("/after/volume").and_then(Value::as_f64);
            let (Some(before_volume), Some(after_volume)) = (before_volume, after_volume) else {
                return false;
            };
            match action {
                "volume_set" => requested_volume.is_some_and(|target| {
                    (commanded - target).abs() <= 0.001
                        && payload.pointer("/before/requested_volume").and_then(Value::as_f64)
                            == Some(target)
                        && (after_volume - target).abs() <= 0.01
                }),
                "volume_up" => {
                    let target = (before_volume + 0.05).clamp(0.0, 1.0);
                    (commanded - target).abs() <= 0.001
                        && after_volume > before_volume + 0.001
                }
                "volume_down" => {
                    let target = (before_volume - 0.05).clamp(0.0, 1.0);
                    (commanded - target).abs() <= 0.001
                        && after_volume < before_volume - 0.001
                }
                _ => false,
            }
        }
        "playlist_activate" => requested_playlist_id.is_some_and(|playlist_id| {
            dispatch_argv == Some(&app_control_playlist_activate_argv(player, playlist_id))
                && payload.get("playlist_id").and_then(Value::as_str) == Some(playlist_id)
                && payload.pointer("/active_playlist/active").and_then(Value::as_bool)
                    == Some(true)
                && payload.pointer("/active_playlist/id").and_then(Value::as_str)
                    == Some(playlist_id)
                && payload
                    .pointer("/after/playback_status")
                    .and_then(Value::as_str)
                    .is_some_and(app_control_playback_status_valid)
                && payload
                    .pointer("/playback_preservation/status")
                    .and_then(Value::as_str)
                    == Some("verified")
        }),
        _ => false,
    }
}

fn app_control_selector_echo_valid(payload: &Value, player_selector: Option<&str>) -> bool {
    match player_selector {
        Some(selector) => {
            payload.pointer("/selection/selector").and_then(Value::as_str) == Some(selector)
        }
        None => payload
            .pointer("/selection/selector")
            .is_some_and(Value::is_null),
    }
}

fn app_control_playback_status_valid(status: &str) -> bool {
    matches!(status, "Playing" | "Paused" | "Stopped")
}

fn app_control_playlist_activate_argv(player: &str, playlist_id: &str) -> Value {
    json!([
        "gdbus",
        "call",
        "--session",
        "--dest",
        format!("org.mpris.MediaPlayer2.{player}"),
        "--object-path",
        "/org/mpris/MediaPlayer2",
        "--method",
        "org.mpris.MediaPlayer2.Playlists.ActivatePlaylist",
        playlist_id
    ])
}

fn app_control_operation_request_digest(
    action: &str,
    player_selector: Option<&str>,
    operation_ttl_secs: u64,
) -> String {
    let canonical_request = BTreeMap::from([
        ("action", json!(action)),
        ("operation_ttl_secs", json!(operation_ttl_secs)),
        ("player_selector", json!(player_selector)),
        ("schema", json!("agent_bridge.app_control.v0")),
    ]);
    let canonical = serde_json::to_vec(&canonical_request)
        .expect("app_control operation request is serializable");
    format!("{:x}", Sha256::digest(canonical))
}

fn app_control_process_timeout_ms(
    requested_timeout_ms: Option<u64>,
    verify_timeout_secs: f64,
    durable: bool,
) -> u64 {
    let requested = requested_timeout_ms.unwrap_or(15_000).clamp(1_000, 30_000);
    if !durable {
        return requested;
    }
    let minimum = (verify_timeout_secs * 1_000.0).ceil() as u64 + 3_000;
    requested.max(minimum).min(30_000)
}

fn app_control_durable_script_path() -> PathBuf {
    installed_runtime_script_path("app_control.py").unwrap_or_else(|| {
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../scripts/app_control.py")
    })
}

fn app_control_script_path(args: &Value, cwd: Option<&PathBuf>) -> PathBuf {
    if let Some(path) = args.get("script_path").and_then(Value::as_str) {
        return PathBuf::from(path);
    }
    if let Ok(path) = std::env::var("AGENT_BRIDGE_APP_CONTROL_SCRIPT") {
        if !path.trim().is_empty() {
            return PathBuf::from(path);
        }
    }
    if let Some(cwd) = cwd {
        let path = cwd.join("scripts/app_control.py");
        if path.exists() {
            return path;
        }
    }
    if let Ok(cwd) = std::env::current_dir() {
        let path = cwd.join("scripts/app_control.py");
        if path.exists() {
            return path;
        }
    }
    if let Some(path) = installed_runtime_script_path("app_control.py") {
        return path;
    }
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../scripts/app_control.py")
}

fn app_control_error(recover: &str, error: Value) -> ToolResult {
    let mut result = ToolResult::json_text(&json!({
        "schema": "agent_bridge.app_control.v0", "status": "error", "verdict": "error",
        "recover": recover, "error": error
    }));
    result.is_error = true;
    result
}

/// Read a pending host-confirm record's `kind` ("invoke" | "action" | "steer") WITHOUT
/// consuming it, so desktop_confirm can dispatch to the right backend script. Token must be
/// hex (path safety); returns None if malformed, missing, or unreadable (caller defaults to
/// the invoke backend, which then reports "no such pending token").
fn desktop_pending_kind(token: &str) -> Option<String> {
    if token.is_empty() || !token.chars().all(|c| c.is_ascii_hexdigit()) {
        return None;
    }
    let cache = std::env::var("XDG_CACHE_HOME")
        .ok()
        .filter(|s| !s.trim().is_empty())
        .unwrap_or_else(|| {
            format!(
                "{}/.cache",
                std::env::var("HOME").unwrap_or_else(|_| ".".to_string())
            )
        });
    let path = format!("{cache}/agent-bridge/desktop_pending/{token}.json");
    let txt = std::fs::read_to_string(path).ok()?;
    let v: Value = serde_json::from_str(&txt).ok()?;
    v.get("kind").and_then(|k| k.as_str()).map(str::to_string)
}

/// Phase 2 of the host-confirm path: execute a host action a human approved.
///
/// `desktop_invoke`/`desktop_action` with `confirm_host:true` mint a single-use,
/// TTL-bounded pending token (and an on-screen notify); they act on NOTHING. This tool
/// takes that token and executes the pending host action — the only way host mutation
/// reaches the real desktop through MCP. It dispatches by the record's kind (invoke ->
/// desktop_invoke.py, action -> desktop_action.py, steer -> desktop_steer.py cross-process
/// tmux injection); the backend validates the token (exists, unconsumed, unexpired) and
/// marks it consumed before acting, so it runs once.
pub struct DesktopConfirmTool {
    _hub: Hub,
}

impl DesktopConfirmTool {
    pub fn new(hub: Hub) -> Self {
        Self { _hub: hub }
    }
}

#[async_trait]
impl McpTool for DesktopConfirmTool {
    fn name(&self) -> &'static str {
        "desktop_confirm"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Execute a host desktop action previously staged by \
                 desktop_invoke(confirm_host:true). Pass the single-use `token` it minted; \
                 the backend re-resolves the stored selector and invokes it once (the token \
                 is validated + consumed first). This is the ONLY path by which an MCP-driven \
                 invoke touches the REAL desktop, and only after a human approved the pending \
                 summary. Audited to desktop_invoke_audit.jsonl (phase=confirm)."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "token": { "type": "string", "description": "The single-use token minted by desktop_invoke or desktop_action with confirm_host:true. desktop_confirm dispatches to the right backend by the token's kind." },
                    "wait": { "type": "number", "minimum": 0, "maximum": 30, "default": 4.0, "description": "Seconds to poll for the accessible to reappear before invoking." },
                    "cwd": { "type": "string", "description": "Repo root to resolve scripts/desktop_invoke.py." },
                    "script_path": { "type": "string", "description": "Explicit desktop_invoke.py path (tests / alternate checkouts)." },
                    "timeout_ms": { "type": "integer", "minimum": 1000, "maximum": 30000, "default": 10000, "description": "Milliseconds before the confirm process is killed." }
                },
                "required": ["token"]
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let token = args.get("token").and_then(|v| v.as_str()).unwrap_or("");
        if token.is_empty() {
            return Ok(desktop_invoke_error(json!({
                "code": "missing_token",
                "message": "`token` is required (minted by desktop_invoke/desktop_action with confirm_host:true)"
            })));
        }
        let timeout_ms = args
            .get("timeout_ms")
            .and_then(|v| v.as_u64())
            .unwrap_or(10_000)
            .clamp(1_000, 30_000);

        let cwd = args.get("cwd").and_then(|v| v.as_str()).map(PathBuf::from);
        // Dispatch to the right backend by the pending record's kind: "action" ->
        // desktop_action.py (coordinate click), "steer" -> desktop_steer.py (cross-process
        // tmux injection), otherwise desktop_invoke.py (AT-SPI doAction). All three share the
        // single-use --confirm-token contract (validate + consume before acting).
        let script = match desktop_pending_kind(token).as_deref() {
            Some("action") => desktop_action_script_path(&args, cwd.as_ref()),
            Some("steer") => desktop_steer_script_path(&args, cwd.as_ref()),
            _ => desktop_invoke_script_path(&args, cwd.as_ref()),
        };
        if !script.exists() {
            return Ok(desktop_invoke_error(json!({
                "code": "script_missing",
                "message": format!("backend confirm script not found at {}", script.display()),
                "hint": "pass script_path or run from the Agent-Bridge repo root"
            })));
        }

        let mut cmd = killable_command(
            std::env::var("PYTHON")
                .ok()
                .filter(|s| !s.trim().is_empty())
                .unwrap_or_else(|| "python3".to_string()),
        );
        cmd.arg(&script).arg("--confirm-token").arg(token);
        if let Some(w) = args.get("wait").and_then(|v| v.as_f64()) {
            cmd.arg("--wait").arg(format!("{w}"));
        }
        cmd.stdout(std::process::Stdio::piped());
        cmd.stderr(std::process::Stdio::piped());
        if let Some(cwd) = cwd {
            cmd.current_dir(cwd);
        }

        let started = Instant::now();
        let output =
            match tokio::time::timeout(Duration::from_millis(timeout_ms), cmd.output()).await {
                Err(_) => {
                    return Ok(desktop_invoke_error(json!({
                        "code": "timeout",
                        "message": format!("desktop_confirm exceeded {timeout_ms} ms"),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Err(e)) => {
                    return Ok(desktop_invoke_error(json!({
                        "code": "spawn_failed",
                        "message": e.to_string(),
                        "duration_ms": started.elapsed().as_millis() as u64
                    })));
                }
                Ok(Ok(output)) => output,
            };
        let duration_ms = started.elapsed().as_millis() as u64;
        let (stdout, stdout_truncated) = lossy_truncate(&output.stdout);
        let (stderr, stderr_truncated) = lossy_truncate(&output.stderr);

        match serde_json::from_str::<Value>(&stdout) {
            Ok(mut payload) => {
                if let Some(obj) = payload.as_object_mut() {
                    obj.insert(
                        "mcp_wrapper".to_string(),
                        json!({
                            "tool": self.name(),
                            "read_only": false,
                            "mode": "host-confirm-phase2",
                            "host_protected": true,
                            "duration_ms": duration_ms,
                            "exit_code": output.status.code().unwrap_or(-1),
                            "stderr": stderr,
                            "stderr_truncated": stderr_truncated
                        }),
                    );
                }
                let mut result = ToolResult::json_text(&payload);
                if !output.status.success() {
                    result.is_error = true;
                }
                Ok(result)
            }
            Err(e) => Ok(desktop_invoke_error(json!({
                "code": "invalid_json",
                "message": e.to_string(),
                "stdout": stdout,
                "stderr": stderr,
                "exit_code": output.status.code().unwrap_or(-1),
                "duration_ms": duration_ms,
                "truncated": stdout_truncated || stderr_truncated
            }))),
        }
    }
}

// mobile / Android ADB tools — extracted to mcp_tools/mobile.rs (2026-07 split step 2).
mod mobile;
pub use mobile::*;
// ===========================================================================
//                              browser tools
// ===========================================================================

pub struct BrowserNavigateTool {
    hub: Hub,
}
impl BrowserNavigateTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for BrowserNavigateTool {
    fn name(&self) -> &'static str {
        "browser_navigate"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Open a URL in the agent-bridge browser and return a page id you can \
                 pass to other browser_* tools. The browser is launched lazily on first \
                 call (headed by default; set AGENT_BRIDGE_HEADLESS=1 for headless)."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": { "url": { "type": "string", "description": "Absolute URL." }, "embodiment_intent_id": { "type": "string", "minLength": 1, "maxLength": 128, "description": "Optional explicit embodiment intent reference. Records receipt linkage only; it grants no execution authority." }, "embodiment_lease_id": { "type": "string", "minLength": 1, "maxLength": 128, "description": "Required current body write lease from embodiment_lease(acquire)." } },
                "required": ["url", "embodiment_lease_id"]
            }),
        }
    }
    async fn execute(&self, args: Value, ctx: &ToolContext) -> Result<ToolResult> {
        if let Err(e) = self.hub.security.check(Cap::Browser) {
            return Ok(ToolResult::error(e));
        }
        let _body_action_guard = self.hub.embodiment_lease_action_lock.lock().await;
        let lease_id = match require_body_write_lease(&self.hub, &args, ctx).await {
            Ok(lease_id) => lease_id,
            Err(error) => return Ok(ToolResult::error(error)),
        };
        let b = match &self.hub.browser {
            Some(b) => b.clone(),
            None => return Ok(ToolResult::error("no browser backend configured")),
        };
        let url = match args.get("url").and_then(|v| v.as_str()) {
            Some(u) => u,
            None => return Ok(ToolResult::error("missing 'url'")),
        };
        let embodiment_intent_id = args
            .get("embodiment_intent_id")
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|id| !id.is_empty());
        let body_shadow = BodyWriteShadowSpan::start("browser_navigate", None);
        let result = b.navigate(url).await;
        let body_shadow = body_shadow.finish(&self.hub).await;
        match result {
            Ok(pid) => {
                record_embodiment_receipt(
                    &self.hub,
                    "browser",
                    "navigate",
                    embodiment_intent_id,
                    Some(pid.to_string()),
                    true,
                    json!({
                        "url_recorded": false,
                        "embodiment_lease_id": lease_id,
                        "body_shadow": body_shadow,
                    }),
                )
                .await;
                Ok(ToolResult::text(format!("page: {pid}")))
            }
            Err(e) => {
                record_embodiment_receipt(
                    &self.hub,
                    "browser",
                    "navigate",
                    embodiment_intent_id,
                    None,
                    false,
                    json!({
                        "error": e.to_string(),
                        "url_recorded": false,
                        "embodiment_lease_id": lease_id,
                        "body_shadow": body_shadow,
                    }),
                )
                .await;
                Ok(ToolResult::error(format!("browser: {e}")))
            }
        }
    }
}

const BODY_WRITE_SHADOW_SCHEMA_V0: &str = "agent_bridge.body_write_shadow.v0";

struct BodyWriteShadowSpan {
    preflight: Value,
    span_id: Option<String>,
    start_error: Option<String>,
}

impl BodyWriteShadowSpan {
    fn start(task_kind: &str, task_ref: Option<String>) -> Self {
        let span_id = format!("body-write-{}", uuid::Uuid::new_v4());
        match crate::body_telemetry::start_task_resource_span(
            span_id.clone(),
            task_kind.to_string(),
            task_ref,
        ) {
            Ok(span) => Self {
                preflight: crate::body_telemetry::shadow_reflex_advice_from_status(&span.before),
                span_id: Some(span_id),
                start_error: None,
            },
            Err(error) => Self {
                preflight: crate::body_telemetry::body_reflex_advice_snapshot(),
                span_id: None,
                start_error: Some(error),
            },
        }
    }

    async fn finish(self, hub: &Hub) -> Value {
        let task_span = match self.span_id {
            Some(span_id) => {
                let checkpoint_captured =
                    crate::body_telemetry::checkpoint_task_resource_span(&span_id).is_ok();
                match crate::body_telemetry::finish_task_resource_span(&span_id) {
                    Ok(span) => {
                        let event_recorded = match &hub.store {
                            Some(store) => record_body_task_span_event(store, &span).await,
                            None => false,
                        };
                        json!({
                            "span_id": span.span_id,
                            "state": span.state,
                            "checkpoint_phase": "post_dispatch",
                            "checkpoint_captured": checkpoint_captured,
                            "event_recorded": event_recorded,
                            "receipt": span.receipt(),
                        })
                    }
                    Err(error) => json!({
                        "span_id": span_id,
                        "state": "abandoned",
                        "checkpoint_phase": "post_dispatch",
                        "checkpoint_captured": checkpoint_captured,
                        "event_recorded": false,
                        "error": error,
                    }),
                }
            }
            None => json!({
                "state": "not_started",
                "event_recorded": false,
                "reason": self.start_error,
            }),
        };

        json!({
            "schema_version": BODY_WRITE_SHADOW_SCHEMA_V0,
            "mode": "shadow_only",
            "body_id": LOCAL_BODY_ID,
            "blocked": false,
            "changes_execution_authority": false,
            "preflight": {
                "pressure": self.preflight.get("pressure").cloned().unwrap_or(Value::String("unknown".into())),
                "recommendation": self.preflight.get("recommendation").cloned().unwrap_or(Value::String("observe_only".into())),
                "reason": self.preflight.get("reason").cloned().unwrap_or(Value::String("body advice unavailable".into())),
            },
            "task_span": task_span,
        })
    }
}

async fn record_embodiment_receipt(
    hub: &Hub,
    source: &str,
    action: &str,
    intent_id: Option<&str>,
    target: Option<String>,
    ok: bool,
    facts: Value,
) {
    let Some(store) = &hub.store else {
        return;
    };
    let verdict = if ok {
        crate::semantic_event::VerdictStatus::Unknown
    } else {
        crate::semantic_event::VerdictStatus::NotVerified
    };
    let (target, method, evidence, facts, expected_effect) = match intent_id {
        Some(intent_id) => (
            target,
            "intent_linked_receipt",
            json!({"intent_id": intent_id}),
            json!({"embodiment_intent_id": intent_id, "receipt": facts}),
            "record intent-linked action receipt",
        ),
        None => (
            None,
            "action_coverage_receipt",
            json!({"intent_linked": false}),
            json!({
                "embodiment_intent_id": null,
                "receipt": {
                    "schema": "agent_bridge.embodiment_action_coverage.v0",
                    "coverage_only": true,
                    "intent_linked": false,
                    "body_id": LOCAL_BODY_ID,
                    "execution_succeeded": ok,
                }
            }),
            "record privacy-minimal action coverage receipt",
        ),
    };
    let event = crate::semantic_event::SemanticEvent {
        ts: dispatch_now_secs(),
        actor: "mcp".into(),
        source: source.into(),
        action: action.into(),
        target,
        object: crate::semantic_event::SemanticObject {
            object_type: format!("{source}_surface"),
            source_adapter: source.into(),
            label: None,
            object_id: None,
        },
        affordance: crate::semantic_event::Affordance {
            action_type: action.into(),
            risk_level: "medium".into(),
            requires_gate: true,
            expected_effect: Some(expected_effect.into()),
        },
        verdict: crate::semantic_event::Verdict {
            status: verdict,
            method: method.into(),
            evidence,
        },
        facts,
    };
    if let Err(error) = store.record_semantic_event(event.to_record()).await {
        tracing::debug!(%error, "record embodiment action receipt failed");
    }
}

/// Output / expression lane — E1 `present()` static-artifact sink.
/// Renders a structured result into a self-verified standalone HTML artifact
/// carrying both a human render and a machine-facing `#ab-payload`
/// (dual-encoding) + provenance. See `crate::present`.
pub struct PresentTool {
    hub: Hub,
}
impl PresentTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for PresentTool {
    fn name(&self) -> &'static str {
        "present"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Output-expression lane E1: render a structured result into a \
                 self-verified standalone HTML artifact that carries BOTH a human-facing \
                 render AND a machine-facing structured payload (dual-encoding) + provenance. \
                 Linear terminal text is lossy for non-linear results (tables, graphs, diagrams); \
                 `present` writes an artifact to ~/.cache/agent-bridge/presentations/<id>.html, \
                 self-verifies it by loading it in the browser, and returns the path + verify \
                 status. Pass `payload` (the structured JSON the artifact visualizes) so other \
                 agents read structure instead of OCR-ing pixels. Degrades to \
                 verify_status=no_browser when no browser is available."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "kind": {
                        "type": "string",
                        "enum": ["table", "markdown_table", "html", "svg", "mermaid"],
                        "description": "Artifact kind. table=structured rows (from payload); markdown_table=a markdown pipe table in artifact; html/svg=raw markup in artifact; mermaid=diagram source in artifact. NOTE: html/svg are inlined WITHOUT sanitization and, when verify runs, are loaded in a real browser (their scripts execute) — use html/svg only with trusted/self-authored content, not untrusted input."
                    },
                    "artifact": {
                        "type": "string",
                        "description": "Source content for html/svg/mermaid/markdown_table. For kind=table, optional (data comes from payload, or a JSON array string here)."
                    },
                    "payload": {
                        "type": ["object", "array"],
                        "description": "Structured JSON the artifact visualizes. Embedded as #ab-payload (dual-encoding). For kind=table, an array of objects/arrays renders the table. Pass a JSON object/array (NOT a stringified blob — declaring the type stops clients double-encoding; a stringified value is still defensively decoded, see #1786). Strongly encouraged."
                    },
                    "title": { "type": "string", "description": "Document title." },
                    "intent": {
                        "type": "string",
                        "description": "Optional: what this render is the outcome of (the intent half of the action→outcome record). Recorded in the `<id>.outcome.json` sidecar and surfaced by present_outcomes; does not affect the artifact."
                    },
                    "channel": {
                        "type": "string",
                        "enum": ["file"],
                        "default": "file",
                        "description": "Sink. Only 'file' implemented in v0 (browser_tab/notify/avatar are future rungs)."
                    },
                    "provenance": {
                        "type": "object",
                        "description": "Where the data came from: {source_tool, source_event_ids, cwd, ...}. generated_by/session_id/ts are auto-added."
                    },
                    "verify": {
                        "type": "boolean",
                        "default": true,
                        "description": "Self-verify by loading the artifact in the browser and checking the #ab-render region rendered visible content (verify_status: rendered_ok|blank|no_browser|error|skipped). Requires the Browser capability + a configured backend; otherwise returns no_browser (see verify_detail). Result also includes artifact_path, screenshot_path (when captured), dual_encoding, and provenance."
                    },
                    "interactive": {
                        "type": "boolean",
                        "default": false,
                        "description": "E2 output-expression rung: when true AND kind=table with an array-of-objects payload, the artifact gains client-side filter + per-column sort controls over the embedded #ab-payload (no author code — a fixed server runtime; #ab-payload stays the single-encoded machine structure). Otherwise a no-op (interactive_status=not_applicable). When verify runs, a second headless probe drives a control and returns interactive_status: verified|dead|not_applicable|skipped|no_browser|error (dead = a control that does not actually change the view). Default false → E1 output is byte-identical."
                    }
                },
                "required": ["kind"]
            }),
        }
    }
    async fn execute(&self, args: Value, ctx: &ToolContext) -> Result<ToolResult> {
        let kind_str = match required_str_arg(&args, "kind") {
            Ok(v) => v,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        let kind = match crate::present::PresentKind::parse(&kind_str) {
            Some(k) => k,
            None => {
                return Ok(ToolResult::error(format!(
                    "unknown kind '{kind_str}': use table|markdown_table|html|svg|mermaid"
                )))
            }
        };
        let artifact = args
            .get("artifact")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string();
        // Explicit `null` means "no payload" (not an embedded JSON null) so
        // dual_encoding is not falsely reported true. normalize_payload undoes
        // a client that JSON-stringified the structured arg (forum #1786) so
        // #ab-payload embeds the structure single-encoded, not a quoted blob.
        let payload = args
            .get("payload")
            .filter(|v| !v.is_null())
            .map(crate::present::normalize_payload);
        let title = args.get("title").and_then(|v| v.as_str());
        // Slice A: optional caller-supplied "what was this the outcome of" — the
        // intent half of the (intent → action → verified-outcome) record.
        let intent = args.get("intent").and_then(|v| v.as_str());
        let channel = args
            .get("channel")
            .and_then(|v| v.as_str())
            .unwrap_or("file")
            .to_string();
        // v0 implements only the `file` sink; reject others so the echoed
        // channel always matches what actually happened.
        if channel != "file" {
            return Ok(ToolResult::error(format!(
                "unsupported channel '{channel}': v0 implements only 'file'"
            )));
        }
        let verify = args.get("verify").and_then(|v| v.as_bool()).unwrap_or(true);
        // E2: interactivity is opt-in; `enhanced` is true only when the kind+payload
        // can actually be driven (keyed table), so the tool never claims interactivity
        // it didn't add.
        let interactive_req = args
            .get("interactive")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let enhanced =
            interactive_req && crate::present::is_enhanceable(kind, &artifact, payload.as_ref());

        // Provenance: caller-supplied + auto fields (generated_by/session_id/ts).
        // A non-object provenance is wrapped as {given: <value>} so the auto
        // integrity fields are never silently dropped.
        let mut provenance = match args.get("provenance").cloned() {
            Some(v) if v.is_object() => v,
            Some(v) => json!({ "given": v }),
            None => json!({}),
        };
        if let Some(obj) = provenance.as_object_mut() {
            obj.entry("generated_by")
                .or_insert_with(|| json!(crate::present::PRESENT_SCHEMA));
            if let Some(sid) = &ctx.session_id {
                obj.entry("session_id")
                    .or_insert_with(|| json!(sid.to_string()));
            }
            obj.insert("ts".into(), json!(crate::present::now_unix()));
            // record the kind so present_list can reconstruct the index from
            // the self-describing artifact (dual-encoding consumer side).
            obj.insert("kind".into(), json!(kind.as_str()));
        }

        let html = if interactive_req {
            crate::present::build_html_interactive(
                kind,
                &artifact,
                title,
                payload.as_ref(),
                Some(&provenance),
            )
        } else {
            crate::present::build_html(kind, &artifact, title, payload.as_ref(), Some(&provenance))
        };
        // Enhanced markdown_table embeds a synthesized #ab-payload even though the
        // caller passed none, so dual_encoding tracks the artifact, not just the arg.
        let dual_encoding = payload.is_some() || enhanced;
        // Content-addressed id: hash the SOURCE (kind+title+artifact+payload+enhanced),
        // NOT the rendered HTML — the HTML embeds a per-call provenance ts, so
        // hashing it would defeat dedupe. `enhanced` (not interactive_req) keys the
        // id so an interactive-but-non-enhanceable call dedupes with its E1 twin.
        let canonical = format!(
            "{}\u{0}{}\u{0}{}\u{0}{}\u{0}{}",
            kind.as_str(),
            title.unwrap_or(""),
            artifact,
            payload.as_ref().map(|p| p.to_string()).unwrap_or_default(),
            enhanced
        );
        let id = crate::present::derive_id(&canonical);
        let dir = crate::present::presentations_dir();
        let path = dir.join(format!("{id}.html"));
        if let Err(e) = crate::present::write_artifact_atomic(&path, &html) {
            return Ok(ToolResult::error(format!("present: write failed: {e}")));
        }

        // Self-verify: load the artifact in the browser and check it rendered.
        let mut verify_status = crate::present::VerifyStatus::Skipped;
        let mut verify_detail: Option<String> = None;
        let mut screenshot_path: Option<String> = None;
        // E2 interactivity status (orthogonal to verify_status). None unless
        // requested; not_applicable when not enhanceable; the enhanced+verify case
        // defaults to no_browser and is overwritten iff the drive probe runs.
        let mut interactive_status: Option<crate::present::InteractStatus> = if !interactive_req {
            None
        } else if !enhanced {
            Some(crate::present::InteractStatus::NotApplicable)
        } else if !verify {
            Some(crate::present::InteractStatus::Skipped)
        } else {
            Some(crate::present::InteractStatus::NoBrowser)
        };
        let mut interactive_detail: Option<String> = None;
        if verify && channel == "file" {
            if let Err(e) = self.hub.security.check(Cap::Browser) {
                verify_status = crate::present::VerifyStatus::NoBrowser;
                verify_detail = Some(format!("capability: {e}"));
            } else if let Some(b) = self.hub.browser.clone() {
                let file_url = format!("file://{}", path.display());
                match b.navigate(&file_url).await {
                    Ok(page) => {
                        match b.eval(&page, crate::present::VERIFY_METRICS_JS).await {
                            Ok(mv) => {
                                let metrics = crate::present::parse_metrics(&mv);
                                verify_status = crate::present::classify_render(&metrics);
                            }
                            Err(e) => {
                                verify_status = crate::present::VerifyStatus::Error;
                                verify_detail = Some(format!("eval: {e}"));
                            }
                        }
                        if let Ok(bytes) = b.screenshot(&page).await {
                            let png = dir.join(format!("{id}.png"));
                            if std::fs::write(&png, bytes.as_ref()).is_ok() {
                                screenshot_path = Some(png.display().to_string());
                            }
                        }
                        // E2: after the static-render check, drive a control on the
                        // SAME loaded page and classify whether the interactivity is
                        // real. Only when enhanced AND the initial render passed
                        // (no point proving interactivity on a blank artifact).
                        if enhanced {
                            if verify_status == crate::present::VerifyStatus::RenderedOk {
                                match b.eval(&page, crate::present::INTERACT_DRIVE_JS).await {
                                    Ok(sv) => {
                                        let sig = crate::present::parse_interact_signature(&sv);
                                        interactive_detail = Some(format!(
                                            "filtered_changed={} restored={} sorted_changed={} rows0={}{}",
                                            sig.filtered_changed,
                                            sig.restored,
                                            sig.sorted_changed,
                                            sig.rowcount0,
                                            sig.reason
                                                .as_deref()
                                                .map(|r| format!(" reason={r}"))
                                                .unwrap_or_default()
                                        ));
                                        interactive_status =
                                            Some(crate::present::classify_interactivity(&sig));
                                    }
                                    Err(e) => {
                                        interactive_status =
                                            Some(crate::present::InteractStatus::Error);
                                        interactive_detail = Some(format!("interact eval: {e}"));
                                    }
                                }
                            } else {
                                // initial render didn't pass → interactivity unprovable;
                                // a blank render is a real fault for an interactive artifact.
                                interactive_status = Some(match verify_status {
                                    crate::present::VerifyStatus::Blank => {
                                        crate::present::InteractStatus::Dead
                                    }
                                    _ => crate::present::InteractStatus::Skipped,
                                });
                            }
                        }
                    }
                    Err(e) => {
                        // Some(browser) != launchable Chrome — navigate failure
                        // (missing binary / launch error) degrades, not fails.
                        verify_status = crate::present::VerifyStatus::NoBrowser;
                        verify_detail = Some(format!("navigate: {e}"));
                    }
                }
            } else {
                verify_status = crate::present::VerifyStatus::NoBrowser;
                verify_detail = Some("no browser backend configured".to_string());
            }
        }

        // Slice A: persist a falsifier-gated action→outcome record sidecar
        // (`<id>.outcome.json`, next to the artifact + its `<id>.png`) so the
        // lane's verified results become a queryable training-signal stream
        // (`present_outcomes`), not a one-shot tool result. Best-effort: a sidecar
        // write failure never fails the present() call. The gate that decides
        // eligibility lives in present_outcomes (read side), so this record stays
        // a faithful log of what actually happened (verified or not).
        let verify_method = if !verify {
            "none"
        } else if verify_status.as_str() == "no_browser" {
            "no_browser"
        } else {
            "browser_eval"
        };
        // Provenance: the present_replay chain_head over the lane's artifacts NOW
        // (including the one just written) — the chain state this outcome
        // contributes to. A future opt-in memory ingest can back-link the verified
        // outcome to the chain that produced it. Local SHA-256 chain only (the same
        // idiom present_replay reports); does NOT touch event_spine. Best-effort —
        // a listing failure leaves it empty rather than failing the render.
        let chain_head = {
            let artifacts = crate::present::list_artifacts(&dir, 500, None);
            crate::present::present_replay_snapshot(
                &artifacts,
                0usize,
                0u64,
                crate::present::now_unix(),
            )
            .get("chain_head")
            .and_then(|v| v.as_str())
            .map(|s| s.to_string())
            .unwrap_or_default()
        };
        let outcome_record = json!({
            "artifact_id": id,
            "intent": intent,
            "action_tool": "present",
            "kind": kind.as_str(),
            "verify_status": verify_status.as_str(),
            "embody_status": crate::present::EmbodyStatus::NotApplicable.as_str(),
            "interactive_status": interactive_status.map(|s| s.as_str()),
            "verify_method": verify_method,
            "dual_encoding": dual_encoding,
            "chain_head": chain_head,
            "session_id": ctx.session_id.as_ref().map(|s| s.to_string()),
            "ts": crate::present::now_unix(),
        });
        let _ = crate::present::write_outcome_sidecar(&dir, &id, &outcome_record);

        let result = json!({
            "schema": crate::present::PRESENT_SCHEMA,
            "id": id,
            "kind": kind.as_str(),
            "channel": channel,
            "artifact_path": path.display().to_string(),
            "screenshot_path": screenshot_path,
            "verify_status": verify_status.as_str(),
            "verify_detail": verify_detail,
            "interactive_status": interactive_status.map(|s| s.as_str()),
            "interactive_detail": interactive_detail,
            "dual_encoding": dual_encoding,
            "bytes": html.len(),
            "provenance": provenance,
        });
        Ok(ToolResult::json_text(&result))
    }
}

/// GSL-1A: narrow Codex-facing projection of grounded observations.
///
/// This wrapper deliberately exposes only the structured-table subset of
/// `present`: callers cannot supply markup, disable verification, enable
/// interactivity, or choose another sink.  It gives eager/lean clients a useful
/// projection organ without admitting the broader Niche presentation surface.
pub struct GroundedSurfacePresentTool {
    present: PresentTool,
}

impl GroundedSurfacePresentTool {
    pub fn new(hub: Hub) -> Self {
        Self {
            present: PresentTool::new(hub),
        }
    }
}

fn bounded_optional_str(
    args: &Value,
    field: &str,
    max_chars: usize,
) -> std::result::Result<Option<String>, String> {
    let Some(value) = args.get(field) else {
        return Ok(None);
    };
    let Some(value) = value.as_str() else {
        return Err(format!("'{field}' must be a string"));
    };
    let value = value.trim();
    if value.is_empty() {
        return Err(format!("'{field}' must not be empty"));
    }
    if value.chars().count() > max_chars {
        return Err(format!("'{field}' exceeds {max_chars} characters"));
    }
    Ok(Some(value.to_string()))
}

fn validate_grounded_observations(args: &Value) -> std::result::Result<Vec<Value>, String> {
    let Some(root) = args.as_object() else {
        return Err("grounded surface input must be an object".to_string());
    };
    let allowed = ["title", "intent", "cwd", "observations"];
    if let Some(field) = root.keys().find(|field| !allowed.contains(&field.as_str())) {
        return Err(format!("unsupported grounded surface field '{field}'"));
    }
    let observations = args
        .get("observations")
        .and_then(Value::as_array)
        .ok_or_else(|| "'observations' must be an array".to_string())?;
    if observations.is_empty() || observations.len() > 64 {
        return Err("'observations' must contain between 1 and 64 rows".to_string());
    }

    for (index, observation) in observations.iter().enumerate() {
        let Some(row) = observation.as_object() else {
            return Err(format!("observations[{index}] must be an object"));
        };
        for field in ["source", "status", "freshness"] {
            let Some(value) = row.get(field).and_then(Value::as_str) else {
                return Err(format!("observations[{index}].{field} must be a string"));
            };
            if value.trim().is_empty() || value.chars().count() > 128 {
                return Err(format!(
                    "observations[{index}].{field} must contain 1 to 128 characters"
                ));
            }
        }
        let freshness = row["freshness"].as_str().unwrap_or_default();
        if !matches!(freshness, "fresh" | "stale" | "unavailable" | "unknown") {
            return Err(format!(
                "observations[{index}].freshness must be fresh|stale|unavailable|unknown"
            ));
        }
        if row
            .get("observed_at_unix_ms")
            .and_then(Value::as_u64)
            .is_none()
        {
            return Err(format!(
                "observations[{index}].observed_at_unix_ms must be a non-negative integer"
            ));
        }
    }

    let encoded = serde_json::to_vec(observations)
        .map_err(|error| format!("observations are not serializable: {error}"))?;
    if encoded.len() > 128 * 1024 {
        return Err("'observations' exceeds the 128 KiB encoded limit".to_string());
    }
    Ok(observations.clone())
}

#[async_trait]
impl McpTool for GroundedSurfacePresentTool {
    fn name(&self) -> &'static str {
        "grounded_surface_present"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "GSL-1A bounded projection: render 1-64 provenance-bearing observation rows as a self-verified local table. The wrapper fixes kind=table, channel=file, verify=true, and interactive=false; it never accepts HTML/SVG/script input, controls a device, or claims that a human saw the result. Missing sensors must be represented explicitly with freshness=unavailable.".into(),
            input_schema: json!({
                "type": "object",
                "additionalProperties": false,
                "required": ["observations"],
                "properties": {
                    "title": {
                        "type": "string",
                        "maxLength": 160,
                        "default": "Agent-Bridge grounded surface"
                    },
                    "intent": {
                        "type": "string",
                        "maxLength": 500,
                        "description": "Why this grounded state card was requested."
                    },
                    "cwd": {
                        "type": "string",
                        "maxLength": 4096,
                        "description": "Optional workspace provenance; it is displayed as metadata, never executed."
                    },
                    "observations": {
                        "type": "array",
                        "minItems": 1,
                        "maxItems": 64,
                        "items": {
                            "type": "object",
                            "additionalProperties": true,
                            "required": ["source", "status", "observed_at_unix_ms", "freshness"],
                            "properties": {
                                "source": {"type": "string", "maxLength": 128},
                                "status": {"type": "string", "maxLength": 128},
                                "observed_at_unix_ms": {"type": "integer", "minimum": 0},
                                "freshness": {
                                    "type": "string",
                                    "enum": ["fresh", "stale", "unavailable", "unknown"]
                                },
                                "evidence_ref": {"type": "string"},
                                "detail": {}
                            }
                        }
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, ctx: &ToolContext) -> Result<ToolResult> {
        let observations = match validate_grounded_observations(&args) {
            Ok(rows) => rows,
            Err(error) => return Ok(ToolResult::error(error)),
        };
        let title = match bounded_optional_str(&args, "title", 160) {
            Ok(value) => value.unwrap_or_else(|| "Agent-Bridge grounded surface".to_string()),
            Err(error) => return Ok(ToolResult::error(error)),
        };
        let intent = match bounded_optional_str(&args, "intent", 500) {
            Ok(value) => value,
            Err(error) => return Ok(ToolResult::error(error)),
        };
        let cwd = match bounded_optional_str(&args, "cwd", 4096) {
            Ok(value) => value,
            Err(error) => return Ok(ToolResult::error(error)),
        };
        let provenance = json!({
            "source_tool": self.name(),
            "cwd": cwd,
            "observation_count": observations.len(),
            "truth_boundary": {
                "verification_target": "local_browser_render",
                "human_seen_claimed": false,
                "device_display_claimed": false,
                "external_world_effect_claimed": false
            }
        });
        self.present
            .execute(
                json!({
                    "kind": "table",
                    "payload": observations,
                    "title": title,
                    "intent": intent,
                    "channel": "file",
                    "provenance": provenance,
                    "verify": true,
                    "interactive": false
                }),
                ctx,
            )
            .await
    }
}

/// Output / expression lane — list persisted `present()` artifacts by reading
/// their self-describing HTML (embedded provenance + payload). Read-only.
pub struct PresentListTool {
    _hub: Hub,
}
impl PresentListTool {
    pub fn new(hub: Hub) -> Self {
        Self { _hub: hub }
    }
}
#[async_trait]
impl McpTool for PresentListTool {
    fn name(&self) -> &'static str {
        "present_list"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "List artifacts previously written by `present` (read-only). Scans \
                 ~/.cache/agent-bridge/presentations and reconstructs each entry from the \
                 artifact's embedded provenance + payload (id, kind, ts, generated_by, \
                 session_id, dual_encoding, has_screenshot, bytes), most-recent first."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "limit": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 500,
                        "default": 50,
                        "description": "Max artifacts to return (most-recent first)."
                    },
                    "kind": {
                        "type": "string",
                        "enum": ["table", "markdown_table", "html", "svg", "mermaid"],
                        "description": "Optional kind filter."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let limit = args
            .get("limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(50)
            .clamp(1, 500) as usize;
        let kind = args.get("kind").and_then(|v| v.as_str());
        let dir = crate::present::presentations_dir();
        let infos = crate::present::list_artifacts(&dir, limit, kind);
        let artifacts: Vec<Value> = infos
            .iter()
            .map(|a| {
                json!({
                    "id": a.id,
                    "artifact_path": a.artifact_path,
                    "kind": a.kind,
                    "ts": a.ts,
                    "generated_by": a.generated_by,
                    "session_id": a.session_id,
                    "dual_encoding": a.dual_encoding,
                    "has_screenshot": a.has_screenshot,
                    "bytes": a.bytes,
                })
            })
            .collect();
        Ok(ToolResult::json_text(&json!({
            "schema": "present_list/v0",
            "dir": dir.display().to_string(),
            "count": artifacts.len(),
            "artifacts": artifacts,
        })))
    }
}

/// Output-expression lane slice 2: read-only replay/audit projection over the
/// artifacts `present` has persisted. Complements `present_list` (flat index)
/// with an ordered hash chain + drift + dual-encoding audit. See
/// `crate::present::present_replay_snapshot`.
pub struct PresentReplayTool {
    hub: Hub,
}
impl PresentReplayTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for PresentReplayTool {
    fn name(&self) -> &'static str {
        "present_replay"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Output-expression lane slice 2: READ-ONLY replay/audit projection over \
                 persisted present() artifacts. Does NOT create a new source of truth — it orders \
                 the self-describing on-disk artifacts (~/.cache/agent-bridge/presentations) \
                 oldest→newest, derives an event_spine-style SHA-256 hash chain over their \
                 identity (chain_head makes loss/tamper detectable), cross-checks the artifact \
                 count against the `present` calls already recorded in mcp_tool_calls (drift), and \
                 tallies how many carry a machine-readable #ab-payload (dual_encoding). Use to \
                 audit/replay what present() has emitted without re-reading every artifact."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "window_secs": {
                        "type": "integer",
                        "minimum": 60,
                        "maximum": 31536000,
                        "default": 86400,
                        "description": "Look-back window for both present calls and artifacts (by provenance ts)."
                    },
                    "limit": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 500,
                        "default": 200,
                        "description": "Max artifacts scanned (most-recent-first) and present-call rows fetched."
                    },
                    "kind": {
                        "type": "string",
                        "description": "Optional kind filter (table|markdown_table|html|svg|mermaid)."
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let window_secs = args
            .get("window_secs")
            .and_then(|v| v.as_i64())
            .unwrap_or(86_400)
            .clamp(60, 31_536_000);
        let limit = args
            .get("limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(200)
            .clamp(1, 500) as usize;
        let kind_filter = args.get("kind").and_then(|v| v.as_str());

        let now = dispatch_now_secs();
        let cutoff = now.saturating_sub(window_secs);

        // Count present() calls already recorded in mcp_tool_calls within the
        // window (bounded by `limit` fetched rows — drift is best-effort, not exact
        // for very high-volume windows).
        let calls = match store.recent_mcp_tool_calls(window_secs, limit as u32).await {
            Ok(rows) => rows,
            Err(e) => return Ok(ToolResult::error(format!("recent_mcp_tool_calls: {e}"))),
        };
        let present_calls_logged = calls.iter().filter(|c| c.tool_name == "present").count();

        // On-disk artifacts (self-describing index), filtered to the window by
        // provenance ts (artifacts lacking a ts are kept for visibility).
        let dir = crate::present::presentations_dir();
        let artifacts: Vec<_> = crate::present::list_artifacts(&dir, limit, kind_filter)
            .into_iter()
            .filter(|a| a.ts.map_or(true, |t| t as i64 >= cutoff))
            .collect();

        let snapshot = crate::present::present_replay_snapshot(
            &artifacts,
            present_calls_logged,
            window_secs as u64,
            now.max(0) as u64,
        );
        Ok(ToolResult::json_text(&snapshot))
    }
}

/// Build the read-only `present_replay` snapshot the E3 dashboard mirrors. Shared
/// by `present_dashboard` for both the embedded render AND the verify-time
/// recompute (so the embodiment check compares the surface against a freshly
/// derived current `chain_head`, not an echo of the value it embedded). The
/// stable dashboard file is excluded by [`crate::present::list_artifacts`], so it
/// never perturbs the chain it reflects.
async fn dashboard_replay_snapshot(
    store: &Arc<dyn StateStore>,
    window_secs: i64,
    limit: usize,
    kind_filter: Option<&str>,
) -> std::result::Result<Value, String> {
    let calls = store
        .recent_mcp_tool_calls(window_secs, limit as u32)
        .await
        .map_err(|e| format!("recent_mcp_tool_calls: {e}"))?;
    let present_calls_logged = calls.iter().filter(|c| c.tool_name == "present").count();
    let now = dispatch_now_secs();
    let cutoff = now.saturating_sub(window_secs);
    let dir = crate::present::presentations_dir();
    let artifacts: Vec<_> = crate::present::list_artifacts(&dir, limit, kind_filter)
        .into_iter()
        .filter(|a| a.ts.map_or(true, |t| t as i64 >= cutoff))
        .collect();
    Ok(crate::present::present_replay_snapshot(
        &artifacts,
        present_calls_logged,
        window_secs as u64,
        now.max(0) as u64,
    ))
}

/// First 12 chars of a chain head, for compact `embody_detail` diagnostics.
fn short_head(h: &str) -> String {
    h.chars().take(12).collect()
}

