// ===========================================================================
//                 agent_send_input (interactive PTY follow-up turns)
// ===========================================================================

pub struct AgentSendInputTool {
    hub: Hub,
}
impl AgentSendInputTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for AgentSendInputTool {
    fn name(&self) -> &'static str {
        "agent_send_input"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Deliver one follow-up turn of input to a live interactive agent \
                 session this bridge started via agent_spawn(interactive=true). The session \
                 row's runtime_id selects the runtime, so the input always reaches the \
                 session you opened and never the daemon default by accident. One-shot or \
                 finished sessions reject this call."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "id": {
                        "type": "string",
                        "description": "Session id returned by agent_spawn."
                    },
                    "text": {
                        "type": "string",
                        "description": "One turn of input. The runtime submits it once; pass an empty string only when you intentionally want to press Enter."
                    }
                },
                "required": ["id", "text"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        if let Err(e) = self.hub.security.check(Cap::AgentSpawn) {
            return Ok(ToolResult::error(e));
        }
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let id = match args.get("id").and_then(|v| v.as_str()) {
            Some(s) => SessionId::from_raw(s.to_string()),
            None => return Ok(ToolResult::error("missing 'id'")),
        };
        let text = match args.get("text").and_then(|v| v.as_str()) {
            Some(s) => s.to_string(),
            None => return Ok(ToolResult::error("missing 'text'")),
        };
        let session = match store.load_session(&id).await? {
            Some(s) => s,
            None => {
                return Ok(ToolResult::error(format!("unknown agent session {id}")));
            }
        };
        if session.ended_at.is_some() {
            return Ok(ToolResult::error(format!(
                "agent session {id} already finished; spawn a new interactive session"
            )));
        }
        let agent = match resolve_agent_for_session(&self.hub, &session) {
            Ok(a) => a,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        match agent.send_input(&id, &text).await {
            Ok(()) => Ok(ToolResult::json_text(&json!({
                "status": "sent",
                "id": id.as_str(),
                "runtime_id": session.runtime_id,
                "cwd": session.cwd,
            }))),
            Err(e) => Ok(ToolResult::error(format!("agent_send_input: {e}"))),
        }
    }
}

// ===========================================================================
//                          agent_kill (v0.3)
// ===========================================================================

pub struct AgentKillTool {
    hub: Hub,
}
impl AgentKillTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for AgentKillTool {
    fn name(&self) -> &'static str {
        "agent_kill"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Gracefully stop a running agent session this bridge started — sends \
                 SIGTERM to that session's own process. Use when a sub-agent you launched \
                 stalled, went off-task, or its result is no longer needed. The background \
                 wait task finalises the session with the signal exit code; \
                 agent_session_get(id) still shows captured output."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "id": { "type": "string", "description": "Session id from agent_spawn." }
                },
                "required": ["id"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let id = match args.get("id").and_then(|v| v.as_str()) {
            Some(s) => SessionId::from_raw(s.to_string()),
            None => return Ok(ToolResult::error("missing 'id'")),
        };
        // Route to the runtime that OWNS this session (by its recorded
        // `runtime_id`), NOT the configured primary. The primary is frequently a
        // different runtime (e.g. claude-code) than the session's (e.g. gemini),
        // and each runtime tracks its own live interactive PTY sessions in a
        // process-local map — killing via the primary misses the handle, returns
        // a spurious "no live child", and leaks the child process tree. Mirrors
        // the resolution agent_send_input / agent_session_output already use.
        let session = match store.load_session(&id).await? {
            Some(s) => s,
            None => return Ok(ToolResult::error(format!("unknown agent session {id}"))),
        };
        let agent = match resolve_agent_for_session(&self.hub, &session) {
            Ok(a) => a,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        match agent.kill(&id).await {
            Ok(()) => Ok(ToolResult::text(format!("SIGTERM sent to session {id}"))),
            Err(e) => Ok(ToolResult::error(format!("kill: {e}"))),
        }
    }
}

// ===========================================================================
//                       agent session inspection (v0.2)
// ===========================================================================

pub struct AgentSessionListTool {
    hub: Hub,
}
impl AgentSessionListTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for AgentSessionListTool {
    fn name(&self) -> &'static str {
        "agent_session_list"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "List recent agent sessions (default 20, max 1000). Row: id, \
                 runtime, cwd, started_at, ended_at, exit_code. Filters: runtime_id, \
                 cwd_prefix, state, exit_code (negative=signal). Running rows carry \
                 liveness. Use agent_session_get(id) for full output."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "limit":      { "type": "integer", "minimum": 1, "maximum": 1000, "default": 20 },
                    "runtime_id": { "type": "string",  "description": "e.g. 'claude-code'" },
                    "cwd_prefix": { "type": "string",  "description": "Prefix-match the working dir." },
                    "state":      { "type": "string",  "enum": ["running","finished"] },
                    "exit_code":  { "type": "integer", "description": "Exact exit code (negative = signal)." }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let limit = args
            .get("limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(20)
            .min(1000) as u32;
        let filter = SessionFilter {
            runtime_id: args
                .get("runtime_id")
                .and_then(|v| v.as_str())
                .map(|s| s.to_string()),
            cwd_prefix: args
                .get("cwd_prefix")
                .and_then(|v| v.as_str())
                .map(|s| s.to_string()),
            exited_only: args
                .get("state")
                .and_then(|v| v.as_str())
                .and_then(|s| match s {
                    "finished" => Some(true),
                    "running" => Some(false),
                    _ => None,
                }),
            exit_code: args
                .get("exit_code")
                .and_then(|v| v.as_i64())
                .map(|n| n as i32),
        };
        let rows = store.list_sessions(&filter, limit).await?;
        // Strip stdout/stderr to keep the listing compact.
        let summary: Vec<Value> = rows
            .into_iter()
            .map(|s| {
                let running = s.ended_at.is_none();
                let mut row = json!({
                    "id":          s.id.as_str(),
                    "runtime_id":  s.runtime_id,
                    "cwd":         s.cwd,
                    "started_at":  s.started_at,
                    "ended_at":    s.ended_at,
                    "exit_code":   s.exit_code,
                    "running":     running,
                    "stdout_len":  s.stdout.as_ref().map(|x| x.len()).unwrap_or(0),
                    "stderr_len":  s.stderr.as_ref().map(|x| x.len()).unwrap_or(0),
                });
                if running {
                    let (pid, liveness) = agent_session_liveness(&self.hub, &s);
                    if let Some(p) = pid {
                        row["pid"] = json!(p);
                    }
                    row["liveness"] = json!(liveness);
                }
                row
            })
            .collect();
        Ok(ToolResult::json_text(&Value::Array(summary)))
    }
}

pub struct AgentSessionReconcileTool {
    hub: Hub,
}
impl AgentSessionReconcileTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for AgentSessionReconcileTool {
    fn name(&self) -> &'static str {
        "agent_session_reconcile"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Find stale running local agent sessions whose owning MCP process has \
                 likely disappeared, and optionally finalise proven-dead rows. Defaults to \
                 dry-run. Rows with liveness=untracked are reported but not finalised by \
                 default because another live MCP process may own their in-memory PTY session."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "dry_run": {
                        "type": "boolean",
                        "default": true,
                        "description": "When true, report candidates without mutating sessions."
                    },
                    "apply_confirmation": {
                        "type": "string",
                        "description": "Required exact value 'finalise_stale_sessions' when dry_run=false, after reviewing dry-run candidates."
                    },
                    "finalise_untracked": {
                        "type": "boolean",
                        "default": false,
                        "description": "Also finalise liveness=untracked rows. Dangerous while multiple MCP processes may be active; requires apply_untracked_confirmation when dry_run=false."
                    },
                    "apply_untracked_confirmation": {
                        "type": "string",
                        "description": "Required exact value 'finalise_untracked_sessions' when dry_run=false and finalise_untracked=true."
                    },
                    "stale_after_secs": {
                        "type": "integer",
                        "minimum": 60,
                        "maximum": 604800,
                        "default": 300,
                        "description": "Only reconcile running sessions older than this age."
                    },
                    "limit": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 1000,
                        "default": 100
                    },
                    "runtime_id": {
                        "type": "string",
                        "description": "Optional runtime filter, e.g. kilo or codex."
                    },
                    "cwd_prefix": {
                        "type": "string",
                        "description": "Optional cwd prefix filter."
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let dry_run = args
            .get("dry_run")
            .and_then(|v| v.as_bool())
            .unwrap_or(true);
        if !dry_run
            && args.get("apply_confirmation").and_then(|v| v.as_str())
                != Some("finalise_stale_sessions")
        {
            return Ok(ToolResult::error(
                "dry_run=false requires apply_confirmation=\"finalise_stale_sessions\" \
                 after reviewing dry-run candidates",
            ));
        }
        let finalise_untracked = args
            .get("finalise_untracked")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        if !dry_run
            && finalise_untracked
            && args
                .get("apply_untracked_confirmation")
                .and_then(|v| v.as_str())
                != Some("finalise_untracked_sessions")
        {
            return Ok(ToolResult::error(
                "dry_run=false with finalise_untracked=true requires \
                 apply_untracked_confirmation=\"finalise_untracked_sessions\"",
            ));
        }
        let stale_after_secs = args
            .get("stale_after_secs")
            .and_then(|v| v.as_i64())
            .unwrap_or(300)
            .clamp(60, 604_800);
        let limit = args
            .get("limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(100)
            .min(1000) as u32;
        let filter = SessionFilter {
            runtime_id: args
                .get("runtime_id")
                .and_then(|v| v.as_str())
                .map(|s| s.to_string()),
            cwd_prefix: args
                .get("cwd_prefix")
                .and_then(|v| v.as_str())
                .map(|s| s.to_string()),
            exited_only: Some(false),
            exit_code: None,
        };
        let rows = store.list_sessions(&filter, limit).await?;
        let now = dispatch_now_secs();
        let mut candidates = Vec::new();
        let mut deferred_untracked = Vec::new();
        let mut finalised_count = 0usize;
        let mut skipped_recent = 0usize;
        let mut skipped_unsupported_runtime = 0usize;
        let mut skipped_alive = 0usize;
        let mut skipped_untracked = 0usize;
        let mut skipped_reaper_owned = 0usize;
        let mut errors = Vec::new();

        for session in rows {
            let age_secs = now.saturating_sub(session.started_at);
            if age_secs < stale_after_secs {
                skipped_recent += 1;
                continue;
            }
            // v41: rows carrying a proven process identity belong to the
            // orphan reaper — it can actually KILL the process group, while
            // finalising here would hide the row from every future reaper
            // pass with the process still alive (review finding, 2026-07-03).
            if session.proc_pid.is_some() && session.proc_start_ticks.is_some() {
                skipped_reaper_owned += 1;
                continue;
            }
            if !is_local_process_agent_runtime(&session.runtime_id) {
                skipped_unsupported_runtime += 1;
                continue;
            }
            let (pid, liveness) = agent_session_liveness(&self.hub, &session);
            if liveness == "alive" {
                skipped_alive += 1;
                continue;
            }
            let candidate = json!({
                "id": session.id.as_str(),
                "runtime_id": session.runtime_id.as_str(),
                "cwd": session.cwd.as_str(),
                "started_at": session.started_at,
                "age_secs": age_secs,
                "pid": pid,
                "liveness": liveness,
                "exit_code_if_applied": -15,
            });
            if liveness == "untracked" && !finalise_untracked {
                skipped_untracked += 1;
                let mut deferred = candidate;
                deferred["deferred_reason"] =
                    json!("untracked_liveness_requires_finalise_untracked_confirmation");
                deferred_untracked.push(deferred);
                continue;
            }
            let reason = format!(
                "agent_session_reconcile: finalised stale running session after {age_secs}s; \
                 liveness={liveness}"
            );
            candidates.push(candidate);
            if !dry_run {
                let stderr = append_reconcile_reason(session.stderr.as_deref(), &reason);
                match store
                    .finalise_session(
                        &session.id,
                        now,
                        Some(-15),
                        session.stdout.clone(),
                        Some(stderr),
                    )
                    .await
                {
                    Ok(()) => finalised_count += 1,
                    Err(e) => errors.push(json!({
                        "id": session.id.as_str(),
                        "error": e.to_string(),
                    })),
                }
            }
        }

        Ok(ToolResult::json_text(&json!({
            "dry_run": dry_run,
            "stale_after_secs": stale_after_secs,
            "scanned_count": skipped_recent
                + skipped_unsupported_runtime
                + skipped_alive
                + skipped_untracked
                + candidates.len(),
            "candidate_count": candidates.len(),
            "deferred_untracked_count": deferred_untracked.len(),
            "finalised_count": finalised_count,
            "skipped_recent": skipped_recent,
            "skipped_unsupported_runtime": skipped_unsupported_runtime,
            "skipped_alive": skipped_alive,
            "skipped_untracked": skipped_untracked,
            "skipped_reaper_owned": skipped_reaper_owned,
            "errors": errors,
            "candidates": candidates,
            "deferred_untracked": deferred_untracked,
        })))
    }
}

fn append_reconcile_reason(existing: Option<&str>, reason: &str) -> String {
    match existing {
        Some(prev) if !prev.trim().is_empty() => format!("{prev}\n{reason}"),
        _ => reason.to_string(),
    }
}

fn is_local_process_agent_runtime(runtime_id: &str) -> bool {
    matches!(
        runtime_id,
        "claude-code" | "codex" | "kilo" | "opencode" | "gemini" | "auggie" | "acp"
    )
}

fn resolve_agent_for_session(
    hub: &Hub,
    session: &StoredSession,
) -> std::result::Result<Arc<dyn ab_agent::AgentRuntime>, String> {
    hub.agents
        .get(&session.runtime_id)
        .cloned()
        .or_else(|| {
            hub.agent
                .as_ref()
                .filter(|agent| agent.id() == session.runtime_id)
                .cloned()
        })
        .ok_or_else(|| {
            let mut available: Vec<&str> = hub.agents.keys().map(|s| s.as_str()).collect();
            available.sort();
            format!(
                "agent session {} uses runtime '{}' but this MCP process is not tracking that \
                 runtime; available: [{}]",
                session.id,
                session.runtime_id,
                available.join(", ")
            )
        })
}

fn agent_session_liveness(hub: &Hub, session: &StoredSession) -> (Option<u32>, &'static str) {
    let pid = hub
        .agents
        .get(&session.runtime_id)
        .and_then(|agent| agent.pid_for(&session.id))
        .or_else(|| {
            hub.agent
                .as_ref()
                .filter(|agent| agent.id() == session.runtime_id)
                .and_then(|agent| agent.pid_for(&session.id))
        });
    match pid {
        Some(pid) if process_pid_exists(pid) => (Some(pid), "alive"),
        Some(pid) => (Some(pid), "dead"),
        None => (None, "untracked"),
    }
}

fn process_pid_exists(pid: u32) -> bool {
    #[cfg(unix)]
    {
        if pid == 0 || pid > libc::pid_t::MAX as u32 {
            return false;
        }
        let rc = unsafe { libc::kill(pid as libc::pid_t, 0) };
        if rc == 0 {
            return true;
        }
        std::io::Error::last_os_error().raw_os_error() == Some(libc::EPERM)
    }
    #[cfg(not(unix))]
    {
        let _ = pid;
        false
    }
}

