#[derive(Clone, Debug, Default, PartialEq, Eq)]
struct MemoryContinuityMetadata {
    continuity_role: Option<String>,
    retrieval_trigger: Option<String>,
    confidence: Option<String>,
    freshness_policy: Option<String>,
    actionability: Option<String>,
    blast_radius: Option<String>,
    supersedes: Vec<String>,
    superseded_by: Option<String>,
}

impl MemoryContinuityMetadata {
    fn is_empty(&self) -> bool {
        self.continuity_role.is_none()
            && self.retrieval_trigger.is_none()
            && self.confidence.is_none()
            && self.freshness_policy.is_none()
            && self.actionability.is_none()
            && self.blast_radius.is_none()
            && self.supersedes.is_empty()
            && self.superseded_by.is_none()
    }

    fn to_json_value(&self) -> Value {
        let mut obj = Map::new();
        if let Some(value) = &self.continuity_role {
            obj.insert("continuity_role".to_string(), Value::String(value.clone()));
        }
        if let Some(value) = &self.retrieval_trigger {
            obj.insert(
                "retrieval_trigger".to_string(),
                Value::String(value.clone()),
            );
        }
        if let Some(value) = &self.confidence {
            obj.insert("confidence".to_string(), Value::String(value.clone()));
        }
        if let Some(value) = &self.freshness_policy {
            obj.insert("freshness_policy".to_string(), Value::String(value.clone()));
        }
        if let Some(value) = &self.actionability {
            obj.insert("actionability".to_string(), Value::String(value.clone()));
        }
        if let Some(value) = &self.blast_radius {
            obj.insert("blast_radius".to_string(), Value::String(value.clone()));
        }
        if !self.supersedes.is_empty() {
            obj.insert("supersedes".to_string(), json!(self.supersedes));
        }
        if let Some(value) = &self.superseded_by {
            obj.insert("superseded_by".to_string(), Value::String(value.clone()));
        }
        Value::Object(obj)
    }
}

fn memory_validate_continuity_enum(
    field: &str,
    value: &str,
    allowed: &[&str],
) -> std::result::Result<String, String> {
    let trimmed = value.trim();
    if trimmed.is_empty() {
        return Ok(String::new());
    }
    if allowed.contains(&trimmed) {
        Ok(trimmed.to_string())
    } else {
        Err(format!(
            "invalid continuity.{field}: '{trimmed}' (allowed: {})",
            allowed.join(", ")
        ))
    }
}

fn memory_continuity_string_field(obj: &Map<String, Value>, field: &str) -> Option<String> {
    obj.get(field)
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(|s| {
            s.chars()
                .take(CONTINUITY_RETRIEVAL_TRIGGER_MAX_CHARS)
                .collect()
        })
}

fn memory_continuity_enum_field(
    obj: &Map<String, Value>,
    field: &str,
    allowed: &[&str],
) -> std::result::Result<Option<String>, String> {
    match obj.get(field).and_then(Value::as_str) {
        Some(value) => {
            let mut parsed = memory_validate_continuity_enum(field, value, allowed)?;
            if field == "continuity_role" && parsed == "decision" {
                parsed = "state".to_string();
            }
            Ok((!parsed.is_empty()).then_some(parsed))
        }
        None => Ok(None),
    }
}

fn memory_continuity_metadata_from_args(
    args: &Value,
) -> std::result::Result<Option<MemoryContinuityMetadata>, String> {
    let Some(raw) = args.get("continuity") else {
        return Ok(None);
    };
    let Some(obj) = raw.as_object() else {
        return Err("continuity must be an object".to_string());
    };

    let supersedes = obj
        .get("supersedes")
        .and_then(Value::as_array)
        .map(|items| {
            items
                .iter()
                .filter_map(Value::as_str)
                .map(str::trim)
                .filter(|s| !s.is_empty())
                .map(str::to_string)
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    let metadata = MemoryContinuityMetadata {
        continuity_role: memory_continuity_enum_field(
            obj,
            "continuity_role",
            &CONTINUITY_ROLE_INPUT_VALUES,
        )?,
        retrieval_trigger: memory_continuity_string_field(obj, "retrieval_trigger"),
        confidence: memory_continuity_enum_field(obj, "confidence", &CONTINUITY_CONFIDENCE_VALUES)?,
        freshness_policy: memory_continuity_enum_field(
            obj,
            "freshness_policy",
            &CONTINUITY_FRESHNESS_POLICY_VALUES,
        )?,
        actionability: memory_continuity_enum_field(
            obj,
            "actionability",
            &CONTINUITY_ACTIONABILITY_VALUES,
        )?,
        blast_radius: memory_continuity_enum_field(
            obj,
            "blast_radius",
            &CONTINUITY_BLAST_RADIUS_VALUES,
        )?,
        supersedes,
        superseded_by: None,
    };

    Ok((!metadata.is_empty()).then_some(metadata))
}

fn memory_push_unique_tag(tags: &mut Vec<String>, tag: String) {
    if !tags.iter().any(|existing| existing == &tag) {
        tags.push(tag);
    }
}

/// Normalize the public recall-scope convention used by memory tools.
///
/// `None`, an empty string, and `global` all mean the unscoped/global lane.
/// This is a single-user recall boundary, not a principal/tenant ACL.
fn normalized_recall_scope(scope: Option<&str>) -> Option<String> {
    scope
        .map(str::trim)
        .filter(|scope| !scope.is_empty() && !scope.eq_ignore_ascii_case("global"))
        .map(str::to_string)
}

/// Store scoped-query APIs deliberately treat an empty context as the legacy
/// all-store view. Automatic paths must never pass empty here: global memories
/// may see only global/unscoped rows, while scoped memories see their local
/// lane plus global rows.
fn recall_context_for_scope(scope: Option<&str>) -> String {
    normalized_recall_scope(scope).unwrap_or_else(|| "global".to_string())
}

/// Apply conservative governance to memories produced by an automatic text
/// transform. Curated output is an inference until a separate evidence-backed
/// process verifies it; it also inherits the caller's recall scope and keeps
/// durable lineage to memory sources where such keys exist.
fn apply_curated_memory_governance(
    memory: &mut MemoryRecord,
    target_scope: Option<&str>,
    transform: &str,
    source_session: Option<&str>,
    source_keys: &[String],
) {
    memory.scope = normalized_recall_scope(target_scope);
    if let Some(scope) = memory.scope.as_deref() {
        // Curator keys are otherwise content/position based and live in one
        // process-wide key namespace. Bind scoped products to a stable scope
        // digest so identical text in two projects cannot collide or cause one
        // project's candidate to be skipped as another project's duplicate.
        let scope_hash = stable_fnv1a_hex(scope);
        let suffix = format!("__scope_{}", &scope_hash[..12]);
        if !memory.key.ends_with(&suffix) {
            memory.key.push_str(&suffix);
        }
    }

    memory
        .tags
        .retain(|tag| !tag.starts_with(CONTINUITY_CONFIDENCE_TAG_PREFIX));
    memory_push_unique_tag(
        &mut memory.tags,
        format!("{CONTINUITY_CONFIDENCE_TAG_PREFIX}inferred"),
    );
    memory_push_unique_tag(
        &mut memory.tags,
        format!("{PROVENANCE_TRANSFORM_TAG_PREFIX}{transform}"),
    );
    memory_push_unique_tag(
        &mut memory.tags,
        format!(
            "{PROVENANCE_SOURCE_TAG_PREFIX}{}",
            if source_keys.is_empty() {
                "conversation_text"
            } else {
                "memory_records"
            }
        ),
    );
    if let Some(session_id) = source_session.map(str::trim).filter(|s| !s.is_empty()) {
        memory_push_unique_tag(
            &mut memory.tags,
            format!("{PROVENANCE_SOURCE_SESSION_TAG_PREFIX}{session_id}"),
        );
    }

    for source_key in source_keys {
        let source_key = source_key.trim();
        if !source_key.is_empty()
            && !memory
                .related_keys
                .iter()
                .any(|existing| existing == source_key)
        {
            memory.related_keys.push(source_key.to_string());
        }
    }
}

async fn persist_curated_lineage_edges(
    store: &Arc<dyn StateStore>,
    derived_key: &str,
    source_keys: &[String],
) -> (usize, Vec<String>) {
    let mut written = 0usize;
    let mut errors = Vec::new();
    for source_key in source_keys {
        if source_key == derived_key {
            continue;
        }
        match store
            .memory_link(derived_key, source_key, "derived_from", 1.0)
            .await
        {
            Ok(()) => written += 1,
            Err(error) => errors.push(format!("{derived_key} -> {source_key}: {error}")),
        }
    }
    (written, errors)
}

fn memory_apply_continuity_metadata_tags(
    tags: &mut Vec<String>,
    metadata: &MemoryContinuityMetadata,
) {
    tags.retain(|tag| {
        !CONTINUITY_TAG_PREFIXES
            .iter()
            .any(|prefix| tag.starts_with(prefix))
    });

    if let Some(value) = &metadata.continuity_role {
        memory_push_unique_tag(tags, format!("{CONTINUITY_ROLE_TAG_PREFIX}{value}"));
    }
    if let Some(value) = &metadata.retrieval_trigger {
        memory_push_unique_tag(
            tags,
            format!("{CONTINUITY_RETRIEVAL_TRIGGER_TAG_PREFIX}{value}"),
        );
    }
    if let Some(value) = &metadata.confidence {
        memory_push_unique_tag(tags, format!("{CONTINUITY_CONFIDENCE_TAG_PREFIX}{value}"));
    }
    if let Some(value) = &metadata.freshness_policy {
        memory_push_unique_tag(
            tags,
            format!("{CONTINUITY_FRESHNESS_POLICY_TAG_PREFIX}{value}"),
        );
    }
    if let Some(value) = &metadata.actionability {
        memory_push_unique_tag(
            tags,
            format!("{CONTINUITY_ACTIONABILITY_TAG_PREFIX}{value}"),
        );
    }
    if let Some(value) = &metadata.blast_radius {
        memory_push_unique_tag(tags, format!("{CONTINUITY_BLAST_RADIUS_TAG_PREFIX}{value}"));
    }
    for key in &metadata.supersedes {
        memory_push_unique_tag(tags, format!("{CONTINUITY_SUPERSEDES_TAG_PREFIX}{key}"));
    }
}

fn memory_tag_suffix(tags: &[String], prefix: &str) -> Option<String> {
    tags.iter()
        .find_map(|tag| tag.strip_prefix(prefix))
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(str::to_string)
}

fn memory_tag_suffixes(tags: &[String], prefix: &str) -> Vec<String> {
    let mut seen = BTreeSet::new();
    tags.iter()
        .filter_map(|tag| tag.strip_prefix(prefix))
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .filter_map(|s| {
            let value = s.to_string();
            seen.insert(value.clone()).then_some(value)
        })
        .collect()
}

fn memory_continuity_metadata_from_tags(
    tags: &[String],
    superseded_by: Option<&str>,
) -> Option<MemoryContinuityMetadata> {
    let metadata = MemoryContinuityMetadata {
        continuity_role: memory_tag_suffix(tags, CONTINUITY_ROLE_TAG_PREFIX),
        retrieval_trigger: memory_tag_suffix(tags, CONTINUITY_RETRIEVAL_TRIGGER_TAG_PREFIX),
        confidence: memory_tag_suffix(tags, CONTINUITY_CONFIDENCE_TAG_PREFIX),
        freshness_policy: memory_tag_suffix(tags, CONTINUITY_FRESHNESS_POLICY_TAG_PREFIX),
        actionability: memory_tag_suffix(tags, CONTINUITY_ACTIONABILITY_TAG_PREFIX),
        blast_radius: memory_tag_suffix(tags, CONTINUITY_BLAST_RADIUS_TAG_PREFIX),
        supersedes: memory_tag_suffixes(tags, CONTINUITY_SUPERSEDES_TAG_PREFIX),
        superseded_by: superseded_by
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(str::to_string),
    };
    (!metadata.is_empty()).then_some(metadata)
}

fn memory_record_value_with_continuity(rec: &MemoryRecord) -> Value {
    let mut value = serde_json::to_value(rec).unwrap_or(Value::Null);
    if let Some(obj) = value.as_object_mut() {
        let metadata =
            memory_continuity_metadata_from_tags(&rec.tags, rec.superseded_by.as_deref())
                .map(|m| m.to_json_value())
                .unwrap_or(Value::Null);
        obj.insert("continuity_metadata".to_string(), metadata);
    }
    value
}

fn memory_search_hit_value_with_continuity(hit: &MemorySearchHit) -> Value {
    let mut value = serde_json::to_value(hit).unwrap_or(Value::Null);
    if let Some(obj) = value.as_object_mut() {
        obj.insert(
            "record".to_string(),
            memory_record_value_with_continuity(&hit.record),
        );
    }
    value
}

/// S4 compact projection (gate: `s4_compact_search_projection_gate_20260709`).
/// The Cue→Tag layer of the read-cost model: enough per hit to decide WHICH
/// rows deserve a full `memory_get`, without paying the full-body page.
/// `content_chars` is the price tag for that follow-up read. Truncation is
/// char-based, never byte-based — a byte slice could split a multi-byte code
/// point (most store content is Chinese) and panic.
const MEMORY_SEARCH_COMPACT_PREVIEW_CHARS: usize = 200;

fn memory_search_hit_value_compact(hit: &MemorySearchHit) -> Value {
    let rec = &hit.record;
    let content_chars = rec.content.chars().count();
    let preview: String = rec
        .content
        .chars()
        .take(MEMORY_SEARCH_COMPACT_PREVIEW_CHARS)
        .collect();
    let mut obj = serde_json::Map::new();
    obj.insert("key".to_string(), json!(rec.key));
    obj.insert("kind".to_string(), json!(rec.kind));
    obj.insert("tags".to_string(), json!(rec.tags));
    obj.insert("importance".to_string(), json!(rec.importance));
    obj.insert("score".to_string(), json!(hit.score));
    if let Some(c) = hit.cosine {
        obj.insert("cosine".to_string(), json!(c));
    }
    obj.insert("content_preview".to_string(), json!(preview));
    obj.insert("content_chars".to_string(), json!(content_chars));
    obj.insert(
        "content_truncated".to_string(),
        json!(content_chars > MEMORY_SEARCH_COMPACT_PREVIEW_CHARS),
    );
    Value::Object(obj)
}

