impl ChatGptForumFetchTool {
    pub fn new(hub: Hub, allowed_tags: Vec<String>) -> Self {
        Self { hub, allowed_tags }
    }
}

#[async_trait]
impl McpTool for ChatGptForumFetchTool {
    fn name(&self) -> &'static str {
        "forum_fetch"
    }

    fn title(&self) -> String {
        "Fetch an approved Agent-Bridge forum thread".into()
    }

    fn annotations(&self) -> Option<ToolAnnotations> {
        Some(ToolAnnotations::read_only())
    }

    fn output_schema(&self) -> Option<Value> {
        Some(chatgpt_fetch_output_schema())
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Fetch bounded recent posts from one forum thread returned by \
                 forum_search. The thread must still match the tunnel's explicit tag allowlist. \
                 The result excludes refs and does not advance subscription cursors."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "id": {
                        "type": "string",
                        "description": "Exact forum-thread ID returned by forum_search."
                    }
                },
                "required": ["id"],
                "additionalProperties": false
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(store) => store.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let id = args
            .get("id")
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|id| !id.is_empty());
        let Some(id) = id else {
            return Ok(ToolResult::error("missing or empty 'id'"));
        };
        let Some(thread_id) = id
            .strip_prefix("forum-thread:")
            .and_then(|raw| raw.parse::<i64>().ok())
            .filter(|thread_id| *thread_id > 0)
        else {
            return Ok(ToolResult::error("invalid forum thread id"));
        };

        let Some(thread) = store.forum_thread_get(thread_id).await? else {
            return Ok(ToolResult::error(format!(
                "forum thread '{thread_id}' not found"
            )));
        };
        if !chatgpt_forum_thread_allowed(&thread, &self.allowed_tags) {
            return Ok(ToolResult::error(format!(
                "forum thread '{thread_id}' is unavailable"
            )));
        }

        let mut posts = store
            .forum_recent_posts(thread_id, CHATGPT_FORUM_FETCH_POST_LIMIT)
            .await?;
        posts.reverse();
        let omitted_posts = thread.post_count.saturating_sub(posts.len() as i64);
        let mut text = format!(
            "# {}\n\nBoard: {}\nStatus: {}\nTags: {}\n\n",
            thread.title,
            thread.board,
            thread.status,
            thread.tags.join(", ")
        );
        let mut body_truncated_posts = 0usize;
        for post in &posts {
            let (body, body_truncated, _) =
                truncate_chars(&post.body, CHATGPT_FORUM_POST_BODY_CHARS);
            body_truncated_posts += usize::from(body_truncated);
            text.push_str(&format!(
                "## Post {} | {} | {} | {}\n\n{}\n\n",
                post.id, post.kind, post.author, post.created_at, body
            ));
        }
        let (text, text_truncated, _) = truncate_chars(&text, CHATGPT_FORUM_FETCH_TEXT_CHARS);
        let content_truncated = text_truncated || omitted_posts > 0 || body_truncated_posts > 0;
        let metadata = json!({
            "source": "agent-bridge-forum",
            "board": thread.board,
            "status": thread.status,
            "tags": thread.tags.join(","),
            "post_count": thread.post_count.to_string(),
            "returned_posts": posts.len().to_string(),
            "omitted_posts": omitted_posts.to_string(),
            "body_truncated_posts": body_truncated_posts.to_string(),
            "content_truncated": content_truncated.to_string(),
            "last_post_at": thread.last_post_at.to_string()
        });
        Ok(ToolResult::structured_json(&json!({
            "id": format!("forum-thread:{thread_id}"),
            "title": thread.title,
            "text": text,
            "url": "",
            "metadata": metadata
        })))
    }
}

pub struct MemorySaveTool {
    hub: Hub,
}
impl MemorySaveTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemorySaveTool {
    fn name(&self) -> &'static str {
        "memory_save"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Persist one note to agent self-memory (cross-session). Record \
                 lessons, decisions, todos, or context the next-session-you should know. \
                 Same key overwrites: created_at preserved, updated_at bumps. related_keys: \
                 free-form list of related memory keys."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "key":          { "type": "string", "description": "Unique stable id, e.g. 'v0.5_design' or 'agent_spawn_pitfall'." },
                    "kind":         { "type": "string", "description": "lesson | decision | todo | context | session_handoff | …" },
                    "content":      { "type": "string", "description": "Markdown / free text. Capped at 256 KiB." },
                    "tags":         { "type": "array", "items": { "type": "string" }, "default": [] },
                    "related_keys": { "type": "array", "items": { "type": "string" }, "default": [] },
                    "scope":        { "type": "string", "description": "Visibility: omit/global=everywhere, project:/abs/path=cwd-scoped, domain:rust=tech-domain." },
                    "scope_identity_trace": { "type": "boolean", "default": false, "description": "If true, return a git/project-id identity trace plus no-op scope-write shadow comparison for project scopes without changing the stored scope. Honors explicit project-id scopes, AGENT_BRIDGE_PROJECT_SCOPE_ALIASES policy matches, and AGENT_BRIDGE_PROJECT_ID for dedicated processes." },
                    "importance":   { "type": "number", "minimum": 0.0, "maximum": 1.0, "description": "Override importance (0.0–1.0). Omit to auto-assign from kind: decision=0.8, lesson=0.7, todo=0.6, fact=0.5, observation=0.3." },
                    "trigger_pattern": { "type": "string", "description": "For kind=error_pattern: surfacing when session_bootstrap `error_hint` contains this substring (case-insensitive)." },
                    "continuity": {
                        "type": "object",
                        "description": "Optional continuity metadata encoded in backward-compatible memory tags and surfaced as continuity_metadata on reads.",
                        "properties": {
                            "continuity_role": { "type": "string", "enum": ["state", "constraint", "procedure", "evidence", "preference", "warning", "archive", "decision"], "description": "`decision` is accepted as an input alias and stored as `state`; use `kind: decision` for the memory's durable type." },
                            "retrieval_trigger": { "type": "string", "description": "Short condition under which this memory should be retrieved. Stored with a 160-character cap." },
                            "confidence": { "type": "string", "enum": ["verified", "observed", "inferred", "user_stated", "stale"] },
                            "freshness_policy": { "type": "string", "enum": ["never_expires", "ttl", "version_bound", "project_phase_bound"] },
                            "actionability": { "type": "string", "enum": ["background", "plan_influence", "must_block", "needs_review"] },
                            "blast_radius": { "type": "string", "enum": ["current_task", "project", "cross_project", "global"] },
                            "supersedes": { "type": "array", "items": { "type": "string" }, "default": [], "description": "Keys this memory replaces. Each existing target is RETIRED in the same save (status='superseded' + superseded_by pointer + supersedes edge), dropping it from search/list surfaces; memory_get still returns it. Self-references and unknown keys are skipped." }
                        }
                    }
                },
                "required": ["key", "kind", "content"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let key = match args.get("key").and_then(|v| v.as_str()) {
            Some(s) if !s.is_empty() => s.to_string(),
            _ => return Ok(ToolResult::error("missing or empty 'key'")),
        };
        let kind = match args.get("kind").and_then(|v| v.as_str()) {
            Some(s) if !s.is_empty() => s.to_string(),
            _ => return Ok(ToolResult::error("missing or empty 'kind'")),
        };
        let content = args
            .get("content")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string();
        let mut tags: Vec<String> = args
            .get("tags")
            .and_then(|v| v.as_array())
            .map(|a| {
                a.iter()
                    .filter_map(|x| x.as_str().map(|s| s.to_string()))
                    .collect()
            })
            .unwrap_or_default();
        let mut related_keys: Vec<String> = args
            .get("related_keys")
            .and_then(|v| v.as_array())
            .map(|a| {
                a.iter()
                    .filter_map(|x| x.as_str().map(|s| s.to_string()))
                    .collect()
            })
            .unwrap_or_default();
        let scope = args
            .get("scope")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty() && *s != "global")
            .map(|s| s.to_string());
        let scope_identity_trace_requested = args
            .get("scope_identity_trace")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let scope_identity_trace = if scope_identity_trace_requested {
            Some(memory_save_scope_identity_trace(scope.as_deref()))
        } else {
            None
        };
        // Optional importance override; 0.5 = "use kind-based default"
        let importance = args
            .get("importance")
            .and_then(|v| v.as_f64())
            .unwrap_or(0.5)
            .clamp(0.0, 1.0);

        let trigger_pattern = args
            .get("trigger_pattern")
            .and_then(|v| v.as_str())
            .map(|s| s.trim().to_string())
            .filter(|s| !s.is_empty());

        let continuity_metadata = match memory_continuity_metadata_from_args(&args) {
            Ok(value) => value,
            Err(message) => return Ok(ToolResult::error(message)),
        };
        if let Some(metadata) = &continuity_metadata {
            memory_apply_continuity_metadata_tags(&mut tags, metadata);
            for key in &metadata.supersedes {
                if !related_keys.iter().any(|existing| existing == key) {
                    related_keys.push(key.clone());
                }
            }
        }

        let mem = MemoryRecord {
            key: key.clone(),
            kind,
            content,
            tags,
            related_keys,
            scope,
            created_at: 0,
            updated_at: 0,
            last_accessed_at: 0,
            access_count: 0,
            importance,
            status: "active".to_string(),
            trigger_pattern,
            superseded_by: None,
        };
        // B3 preflight (audit-gap B3 v0) — see `b3_preflight` rustdoc + design memo.
        // Runs before the save so warnings reach the caller in the same response;
        // the save is not blocked, this is advisory. memory_correction is a
        // separate tool path so naturally untouched per Q2 self-match argument.
        let b3_disabled = std::env::var("AB_REDO_WARN_DISABLE")
            .map(|v| v == "1")
            .unwrap_or(false);
        let b3_eligible_kind = {
            use ab_store::CATALOG_KINDS_C3;
            !CATALOG_KINDS_C3.contains(&mem.kind.as_str())
        };
        let sync_advisory_enabled = memory_save_sync_advisory_enabled(&mem.content);
        let (b3_warnings, b3_hints) = if sync_advisory_enabled && !b3_disabled && b3_eligible_kind {
            b3_preflight(
                &store,
                &mem.key,
                &mem.content,
                &mem.kind,
                &recall_context_for_scope(mem.scope.as_deref()),
            )
            .await
        } else {
            (Vec::new(), Vec::new())
        };
        match store.memory_save(&mem).await {
            Ok(()) => {
                // Keep embedding cache coherent AND auto-evolve the graph:
                // 1) upsert the new record into the cache (best-effort)
                // 2) **Phase 1 P4 structural** — pick top-k cosine neighbors
                //    and write `evolved` edges. The graph densifies organically
                //    as memories are saved (deterministic half of A-MEM
                //    evolution; LLM-driven tag/X rewrite deferred to P4b).
                //
                // **Cache fallback fix**: the embedding cache is `None` until
                // `session_bootstrap` or `memory_reindex` populates it. Pre-fix
                // version silently exited if cache was empty — meaning P4
                // never fired in cold sessions. Now: prefer cache when warm,
                // fall back to scoped store cosine search when cold so
                // edges always get written. The semantic-search call costs
                // ~11ms per save (one embed + small cosine sweep), which is
                // acceptable for a background spawn.
                {
                    let cache = self.hub.memory_embed_cache.clone();
                    let store_for_evolve = store.clone();
                    let new_key_for_evolve = key.clone();
                    let new_content_for_evolve = mem.content.clone();
                    let rec = mem.clone();
                    let emb = embed_text(&rec.content);
                    let emb_for_evolve = emb.clone();
                    let new_kind_for_evolve = mem.kind.clone();
                    let new_tags_for_evolve = mem.tags.clone();
                    let recall_context_for_evolve = recall_context_for_scope(mem.scope.as_deref());
                    tokio::spawn(async move {
                        tracing::debug!(
                            target: "p4_evolve",
                            key = %new_key_for_evolve,
                            "P4 evolve spawn entry"
                        );
                        // Step 1: cosine candidates (warm cache → in-memory;
                        //   cold cache → store fallback).
                        let candidates: Vec<(MemoryRecord, f64)> = {
                            let mut guard = cache.lock().await;
                            if let Some(ref mut cached) = *guard {
                                cached.retain(|(r, _)| r.key != rec.key);
                                cached.push((rec, emb));
                                let n = pick_evolution_neighbors_in_scope(
                                    cached,
                                    &recall_context_for_evolve,
                                    &new_key_for_evolve,
                                    &emb_for_evolve,
                                    /* threshold */ 0.65,
                                    /* top_k */ 5,
                                );
                                drop(guard);
                                tracing::debug!(
                                    target: "p4_evolve",
                                    key = %new_key_for_evolve,
                                    branch = "warm",
                                    candidates = n.len(),
                                    "P4 evolve cosine candidates picked"
                                );
                                n
                            } else {
                                drop(guard);
                                // Pull by PURE COSINE over the source memory's
                                // recall lane (local + global), then
                                // threshold/exclude to match the warm
                                // pick_evolution_neighbors. Using
                                // memory_search_semantic here would truncate by the
                                // blended score first and drop high-cosine, low-
                                // importance neighbors (#54 follow-up).
                                //
                                // The scoped cosine query truncates to k BY COSINE
                                // over all visible active rows BEFORE this helper filters
                                // self/skill. The true top-5-eligible is lost only
                                // if >(k-5) INELIGIBLE rows outrank the 5th real
                                // neighbor by cosine — i.e. self(1) + skill rows,
                                // since any eligible row with cosine ≥ the 5th's is
                                // itself one of the top-4. So loss needs ≥ k-5
                                // active `kind="skill"` MEMORY rows more similar to
                                // this save than its 5th neighbor. k=200 (corpus
                                // has 0 such rows; skills live in the `skills`
                                // table) makes that unreachable while staying cheap
                                // — top_k_cosine already full-scans+cosines every
                                // active row, so a larger k only grows the returned
                                // Vec, which we immediately truncate to top_k.
                                match store_for_evolve
                                    .memory_top_k_cosine_in_scope(
                                        &new_content_for_evolve,
                                        &recall_context_for_evolve,
                                        /* k (headroom vs self+skill) */ 200,
                                    )
                                    .await
                                {
                                    Ok(hits) => {
                                        let n = evolution_neighbors_from_cosine_hits(
                                            hits,
                                            &new_key_for_evolve,
                                            /* threshold */ 0.65,
                                            /* top_k */ 5,
                                        );
                                        tracing::debug!(
                                            target: "p4_evolve",
                                            key = %new_key_for_evolve,
                                            branch = "cold",
                                            candidates = n.len(),
                                            "P4 evolve cosine candidates picked (cold)"
                                        );
                                        n
                                    }
                                    Err(e) => {
                                        tracing::warn!(
                                            target: "p4_evolve",
                                            key = %new_key_for_evolve,
                                            error = %e,
                                            "P4 evolve cold path scoped cosine query FAILED"
                                        );
                                        Vec::new()
                                    }
                                }
                            }
                        };

                        // Step 2: P4b — optional LLM filter. If ANTHROPIC_API_KEY
                        // is set, ask the LLM which candidates are conceptually
                        // linked (vs just sharing vocabulary). On any failure
                        // (no key / parse / network), pass everything through —
                        // structural P4 still works without LLM.
                        let kept_indices: Vec<usize> = if candidates.is_empty() {
                            Vec::new()
                        } else {
                            match crate::llm_client::LlmClient::from_env() {
                                Ok(client) => {
                                    let kept = llm_filter_evolution_neighbors(
                                        &client,
                                        &new_key_for_evolve,
                                        &new_kind_for_evolve,
                                        &new_tags_for_evolve,
                                        &new_content_for_evolve,
                                        &candidates,
                                    )
                                    .await;
                                    tracing::debug!(
                                        target: "p4b_evolve",
                                        key = %new_key_for_evolve,
                                        candidates = candidates.len(),
                                        kept = kept.len(),
                                        "P4b LLM filter applied"
                                    );
                                    kept
                                }
                                Err(_) => {
                                    // No API key configured — degrade to cosine-only.
                                    // Logged at debug because this is the expected
                                    // path for users who haven't set up Anthropic.
                                    tracing::debug!(
                                        target: "p4b_evolve",
                                        key = %new_key_for_evolve,
                                        "P4b LLM unavailable (no API key); using all cosine candidates"
                                    );
                                    (0..candidates.len()).collect()
                                }
                            }
                        };

                        // Step 3: write evolution edges for the kept set.
                        for idx in kept_indices {
                            let (neighbor, score) = match candidates.get(idx) {
                                Some(c) => c,
                                None => continue,
                            };
                            match store_for_evolve
                                .memory_link(&new_key_for_evolve, &neighbor.key, "evolved", *score)
                                .await
                            {
                                Ok(()) => tracing::debug!(
                                    target: "p4_evolve",
                                    from = %new_key_for_evolve,
                                    to = %neighbor.key,
                                    score = score,
                                    "P4 evolve edge written"
                                ),
                                Err(e) => tracing::warn!(
                                    target: "p4_evolve",
                                    from = %new_key_for_evolve,
                                    to = %neighbor.key,
                                    error = %e,
                                    "P4 evolve memory_link FAILED"
                                ),
                            }
                        }
                    });
                }
                let hint = if sync_advisory_enabled {
                    build_proactive_hint(
                        &store,
                        &key,
                        &mem.content,
                        &mem.tags,
                        &recall_context_for_scope(mem.scope.as_deref()),
                    )
                    .await
                } else {
                    None
                };
                let mut resp = json!({
                    "status": "saved",
                    "key": key,
                    "continuity_metadata": continuity_metadata
                        .as_ref()
                        .map(MemoryContinuityMetadata::to_json_value)
                        .unwrap_or(Value::Null),
                    "proactive_hint": hint,
                    "prior_decision_warnings": b3_warnings,
                    "prior_decision_hints": b3_hints,
                });
                if let Some(trace) = scope_identity_trace {
                    resp["scope_identity_trace"] = trace;
                }
                Ok(ToolResult::json_text(&resp))
            }
            Err(e) => Ok(ToolResult::error(format!("memory: {e}"))),
        }
    }
}

const MEMORY_SAVE_PROJECT_ID_ENV: &str = "AGENT_BRIDGE_PROJECT_ID";

fn memory_save_scope_identity_trace(scope: Option<&str>) -> Value {
    let configured_project_id = std::env::var(MEMORY_SAVE_PROJECT_ID_ENV).ok();
    let project_scope_aliases = std::env::var(PROJECT_SCOPE_ALIASES_ENV).ok();
    memory_save_scope_identity_trace_with_policy(
        scope,
        configured_project_id.as_deref(),
        project_scope_aliases.as_deref(),
    )
}

#[cfg(test)]
fn memory_save_scope_identity_trace_with_project_id(
    scope: Option<&str>,
    configured_project_id: Option<&str>,
) -> Value {
    memory_save_scope_identity_trace_with_policy(scope, configured_project_id, None)
}

fn memory_save_scope_identity_trace_with_policy(
    scope: Option<&str>,
    configured_project_id: Option<&str>,
    project_scope_aliases: Option<&str>,
) -> Value {
    let Some(scope) = scope.map(str::trim).filter(|s| !s.is_empty()) else {
        return json!({
            "status": "not_applicable",
            "reason": "no project scope supplied",
            "write_policy": "trace_only_stored_scope_unchanged",
        });
    };

    let scope_project_id = strip_scope_prefix_case_insensitive(
        scope,
        crate::project_identity::PROJECT_ID_SCOPE_PREFIX,
    );
    let legacy_project_path = strip_scope_prefix_case_insensitive(
        scope,
        crate::project_identity::LEGACY_PROJECT_SCOPE_PREFIX,
    );
    if scope_project_id.is_none() && legacy_project_path.is_none() {
        return json!({
            "status": "not_applicable",
            "requested_scope": scope,
            "reason": "non_project_scope",
            "write_policy": "trace_only_stored_scope_unchanged",
        });
    }

    let policy_project_id = project_scope_aliases
        .map(str::trim)
        .filter(|aliases| !aliases.is_empty())
        .and_then(|aliases| {
            crate::project_identity::approved_scope_alias_canonical(scope, aliases)
        });
    let configured_project_id = configured_project_id
        .map(str::trim)
        .filter(|project_id| !project_id.is_empty());
    let canonical_policy_scope =
        memory_save_scope_policy_canonical(policy_project_id.as_deref(), configured_project_id);
    let explicit_project_id = scope_project_id
        .map(|_| scope)
        .or(policy_project_id.as_deref())
        .or(configured_project_id);
    let explicit_project_id_source = if scope_project_id.is_some() {
        "scope"
    } else if policy_project_id.is_some() {
        "policy"
    } else if configured_project_id.is_some() {
        "env"
    } else {
        "none"
    };

    let cwd = legacy_project_path
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(str::to_string)
        .or_else(|| {
            std::env::current_dir()
                .ok()
                .map(|p| p.display().to_string())
        });

    let Some(cwd) = cwd else {
        return json!({
            "status": "not_applicable",
            "requested_scope": scope,
            "reason": "could not resolve cwd for project identity trace",
            "write_policy": "trace_only_stored_scope_unchanged",
        });
    };

    let cwd_path = Path::new(&cwd);
    let git_remote = memory_save_git_capture(cwd_path, &["remote", "get-url", "origin"]);
    let git_root = memory_save_git_capture(cwd_path, &["rev-parse", "--show-toplevel"]);
    let identity = crate::project_identity::resolve_project_identity(
        crate::project_identity::ProjectIdentityInput {
            cwd: &cwd,
            explicit_project_id,
            git_remote: git_remote.as_deref(),
            git_root: git_root.as_deref(),
        },
    );
    let identity_source = if explicit_project_id_source == "none" {
        identity.evidence.label()
    } else {
        explicit_project_id_source
    };
    let shadow_decision = crate::project_identity::evaluate_scope_write_shadow(
        scope,
        canonical_policy_scope.as_deref(),
        project_scope_aliases,
    );

    json!({
        "status": "ok",
        "requested_scope": scope,
        "stored_scope": scope,
        "stored_scope_changed": false,
        "write_policy": "trace_only_stored_scope_unchanged",
        "identity": identity.identity,
        "canonical_scope": identity.canonical_scope,
        "legacy_scope": identity.legacy_scope,
        "explicit_project_id_source": explicit_project_id_source,
        "evidence": identity.evidence.label(),
        "high_confidence": identity.evidence.is_high_confidence(),
        "git_remote": git_remote,
        "git_root": git_root,
        "scope_write_shadow_comparison": memory_save_scope_shadow_decision_value(
            &shadow_decision,
            identity_source,
            &identity.canonical_scope,
        ),
    })
}

fn memory_save_scope_policy_canonical(
    policy_project_id: Option<&str>,
    configured_project_id: Option<&str>,
) -> Option<String> {
    policy_project_id
        .or(configured_project_id)
        .map(str::trim)
        .filter(|project_id| !project_id.is_empty())
        .and_then(|project_id| {
            crate::project_identity::normalize_project_id(project_id)
                .map(|id| crate::project_identity::project_id_scope(&id))
        })
}

fn memory_save_scope_shadow_decision_value(
    decision: &crate::project_identity::ScopeWriteShadowDecision,
    identity_source: &str,
    resolved_identity_scope: &str,
) -> Value {
    json!({
        "status": "ok",
        "requested_scope": decision.requested_scope,
        "current_stored_scope": decision.requested_scope,
        "stored_scope_changed": false,
        "write_policy": "shadow_only_stored_scope_unchanged",
        "production_write_authorized": false,
        "identity_source": identity_source,
        "resolved_identity_scope": resolved_identity_scope,
        "canonical_policy_scope": decision.canonical_policy_scope,
        "reviewed_alias_registry_match": decision.reviewed_alias_registry_match,
        "shadow_action": decision.action.label(),
        "reason": decision.reason,
        "proposed_scope": decision.proposed_scope,
        "would_store_scope_if_enabled": decision.would_store_scope_if_enabled,
        "legacy_scope_preserved": decision.legacy_scope_preserved,
        "shadow_write_eligible": decision.shadow_write_eligible,
    })
}

fn strip_scope_prefix_case_insensitive<'a>(raw: &'a str, prefix: &str) -> Option<&'a str> {
    raw.get(..prefix.len())
        .filter(|candidate| candidate.eq_ignore_ascii_case(prefix))
        .and_then(|_| raw.get(prefix.len()..))
}

fn memory_save_git_capture(cwd: &Path, args: &[&str]) -> Option<String> {
    let out = std::process::Command::new("git")
        .current_dir(cwd)
        .args(args)
        .output()
        .ok()?;
    if !out.status.success() {
        return None;
    }
    let text = String::from_utf8_lossy(&out.stdout).trim().to_string();
    (!text.is_empty()).then_some(text)
}

/// Phase 0 telemetry helper. Build a `MemoryQueryRecord` with the common
/// fields and dispatch a fire-and-forget log write so the MCP request path
/// stays sub-ms even when the store is contended. We pass the store as `Arc`
/// because `tokio::spawn` needs an owned value.
fn log_memory_query(
    store: Arc<dyn StateStore>,
    kind: &'static str,
    query: String,
    tags_json: String,
    hit_count: u32,
    top_hit_age_secs: Option<i64>,
    top_hit_created_at: Option<i64>,
    duration: Duration,
    source: &'static str,
) {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    let rec = MemoryQueryRecord {
        kind: kind.to_string(),
        query,
        tags_json,
        hit_count,
        top_hit_age_secs,
        top_hit_created_at,
        duration_us: duration.as_micros().min(u32::MAX as u128) as u32,
        source: source.to_string(),
        at: now,
    };
    tokio::spawn(async move {
        let _ = store.record_memory_query(&rec).await;
    });
}

pub struct MemoryGetTool {
    hub: Hub,
}
impl MemoryGetTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemoryGetTool {
    fn name(&self) -> &'static str {
        "memory_get"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Fetch one memory by exact key. Side effect: bumps the row's \
                 access_count and last_accessed_at — this is what gives \
                 `memory_search` ranking and `memory_compact` something to score \
                 against. Returns null if the key is unknown."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": { "key": { "type": "string" } },
                "required": ["key"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let key = match args.get("key").and_then(|v| v.as_str()) {
            Some(s) => s.to_string(),
            None => return Ok(ToolResult::error("missing 'key'")),
        };
        let started = Instant::now();
        let row = store.memory_get(&key).await?;
        let elapsed = started.elapsed();

        // Phase 0 telemetry: log hit/miss + age. last_accessed_at was just
        // bumped by memory_get so we use created_at as the recency anchor.
        let now_secs = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_secs() as i64)
            .unwrap_or(0);
        let (hit_count, age, created) = match &row {
            Some(rec) => (1u32, Some(now_secs - rec.created_at), Some(rec.created_at)),
            None => (0u32, None, None),
        };
        log_memory_query(
            store.clone(),
            "get",
            key.clone(),
            "[]".to_string(),
            hit_count,
            age,
            created,
            elapsed,
            "mcp:memory_get",
        );

        // Outcome-collector prototype (flag-gated, default-OFF): attribute this
        // explicit get to any recent search surfacing of the same key (= "used").
        // memory_get is an explicit fetch, NOT background re-access, so this is the
        // de-contaminated positive signal. Fire-and-forget; 1800s window.
        if outcome_collector_enabled() && row.is_some() {
            let store_clone = store.clone();
            let k = key.clone();
            tokio::spawn(async move {
                let _ = store_clone.attribute_retrieval_get(&k, 1800).await;
            });
        }

        match row {
            None => Ok(ToolResult::json_text(&Value::Null)),
            Some(rec) => {
                let hint = build_proactive_hint(
                    &store,
                    &key,
                    &rec.content,
                    &rec.tags,
                    &recall_context_for_scope(rec.scope.as_deref()),
                )
                .await;
                let mut resp = memory_record_value_with_continuity(&rec);
                if let Some(obj) = resp.as_object_mut() {
                    obj.insert(
                        "proactive_hint".to_string(),
                        hint.map(Value::String).unwrap_or(Value::Null),
                    );
                }
                Ok(ToolResult::json_text(&resp))
            }
        }
    }
}

/// Item B (2026-06-26, #120): is the owner-gated semantic fallback for the
/// FTS-empty recall tail enabled? **Default-OFF** — only an explicit
/// `AGENT_BRIDGE_RECALL_SEMANTIC_FALLBACK=1`/`true` turns it on; until then the
/// default (fts) `memory_search` path is byte-identical to the prior behavior.
/// Rationale: gte-768 semantic recall is ~2x fts on the hard (no-lexical-overlap)
/// recall_eval tier, but only for queries FTS cannot serve at all — so the
/// fallback fires strictly when FTS returns zero rows AND a real (non-hash)
/// embedder is loaded. Pure (env split out) so the policy is unit-tested.
fn recall_semantic_fallback_enabled_from(env_val: Option<&str>) -> bool {
    matches!(env_val, Some(v) if v == "1" || v.eq_ignore_ascii_case("true"))
}

fn recall_semantic_fallback_enabled() -> bool {
    recall_semantic_fallback_enabled_from(
        std::env::var("AGENT_BRIDGE_RECALL_SEMANTIC_FALLBACK")
            .ok()
            .as_deref(),
    )
}

/// Outcome-collector prototype gate. **Default-OFF** — only an explicit
/// `AGENT_BRIDGE_OUTCOME_COLLECTOR=1`/`true` enables the surfaced-key logging
/// (in `memory_search`, plus the ambient session_bootstrap page writer, which
/// `ambient_surfacing_disabled` can turn off separately) and the `memory_get`
/// "used" attribution. The v39 table
/// exists after store migration, but no rows are written while the flag is off.
/// Pure (env split out) so the policy is unit-testable. See the Phase-0 study:
/// the signal is real + de-contaminated but sparse, so this only SEEDS accrual.
fn outcome_collector_enabled_from(env_val: Option<&str>) -> bool {
    matches!(env_val, Some(v) if v == "1" || v.eq_ignore_ascii_case("true"))
}

fn outcome_collector_enabled() -> bool {
    outcome_collector_enabled_from(
        std::env::var("AGENT_BRIDGE_OUTCOME_COLLECTOR")
            .ok()
            .as_deref(),
    )
}

const RETRIEVAL_TRAFFIC_CLASS_ENV: &str = "AGENT_BRIDGE_RETRIEVAL_TRAFFIC_CLASS";

/// Process-boundary provenance for retrieval telemetry. Missing, empty, and
/// invalid values fail closed to `unknown`; no request content is inspected.
fn retrieval_traffic_class_from(env_val: Option<&str>) -> &'static str {
    ab_store::normalize_retrieval_traffic_class(env_val)
}

fn retrieval_traffic_class() -> &'static str {
    retrieval_traffic_class_from(std::env::var(RETRIEVAL_TRAFFIC_CLASS_ENV).ok().as_deref())
}

/// Stage-1 ambient-surfacing kill switch: `AB_BOOTSTRAP_SURFACING_DISABLE=1`
/// stops session_bootstrap from logging its semantic page to
/// `retrieval_surfacing` (mode = [`AMBIENT_SURFACING_MODE`]) without touching
/// the search-side collector. The writer is telemetry-only, so disabling
/// loses data and changes no ranking. Pure split for unit-testability,
/// mirroring `outcome_collector_enabled_from`.
fn ambient_surfacing_disabled_from(env_val: Option<&str>) -> bool {
    matches!(env_val, Some(v) if v == "1" || v.eq_ignore_ascii_case("true"))
}

fn ambient_surfacing_disabled() -> bool {
    ambient_surfacing_disabled_from(
        std::env::var("AB_BOOTSTRAP_SURFACING_DISABLE")
            .ok()
            .as_deref(),
    )
}

/// S1 distillation-surfacing kill switch: `AB_DISTILL_SURFACING_DISABLE=1`
/// drops the "Distillation candidates" bootstrap block. Presentation-only:
/// the eval-side detector and all ranking are untouched. Same shape as the
/// stage-1 ambient switch above.
fn distill_surfacing_disabled_from(env_val: Option<&str>) -> bool {
    matches!(env_val, Some(v) if v == "1" || v.eq_ignore_ascii_case("true"))
}

fn distill_surfacing_disabled() -> bool {
    distill_surfacing_disabled_from(
        std::env::var("AB_DISTILL_SURFACING_DISABLE")
            .ok()
            .as_deref(),
    )
}

/// R3 MMR diversity kill switch (forum #147, default ON):
/// `AB_BOOTSTRAP_MMR_DISABLE=1` skips the MMR re-rank of the
/// session_bootstrap semantic page and restores plain blend-score order.
/// Presentation-only — search ranking and telemetry writers are untouched.
/// Same pure-split shape as the stage-1 ambient switch above.
fn bootstrap_mmr_disabled_from(env_val: Option<&str>) -> bool {
    matches!(env_val, Some(v) if v == "1" || v.eq_ignore_ascii_case("true"))
}

fn bootstrap_mmr_disabled() -> bool {
    bootstrap_mmr_disabled_from(std::env::var("AB_BOOTSTRAP_MMR_DISABLE").ok().as_deref())
}

/// Default relevance/diversity trade-off for the bootstrap MMR re-rank.
const BOOTSTRAP_MMR_LAMBDA_DEFAULT: f64 = 0.7;

/// Optional λ override: `AB_BOOTSTRAP_MMR_LAMBDA` ∈ [0, 1]. Unset, unparsable,
/// non-finite, or out-of-range values all fall back to the default — the env
/// var can degrade to stock behaviour but never to a nonsense λ.
fn bootstrap_mmr_lambda_from(env_val: Option<&str>) -> f64 {
    match env_val.and_then(|v| v.trim().parse::<f64>().ok()) {
        Some(l) if l.is_finite() && (0.0..=1.0).contains(&l) => l,
        _ => BOOTSTRAP_MMR_LAMBDA_DEFAULT,
    }
}

fn bootstrap_mmr_lambda() -> f64 {
    bootstrap_mmr_lambda_from(std::env::var("AB_BOOTSTRAP_MMR_LAMBDA").ok().as_deref())
}

/// Item B real-embedder gate: would a query embed produce a REAL vector (not the
/// hash fallback)? Under remote delegation the embed runs on a warm peer, so the
/// local model state is irrelevant. Otherwise the local ONNX model must have
/// actually loaded AND the active backend must not be the hash fallback — this
/// covers cold-load (model_init_done false), a hash-only build (model_init_done
/// is true unconditionally there, but the backend name is the hash backend), and
/// a permanent model-load failure. Consulted only on the rare FTS-empty branch.
fn fallback_embedder_ready() -> bool {
    if crate::remote_embed::active_remote_url().is_some() {
        return true;
    }
    ab_store::vector::model_init_done()
        && !ab_store::embedding::default_backend()
            .name()
            .to_ascii_lowercase()
            .contains("hash")
}

/// R2 fusion-shadow gate (forum #147 "shadow first"). **Default-OFF** — every
/// shadowed default-mode search pays one real extra query embed (the semantic
/// leg), so the owner flips `AGENT_BRIDGE_FUSION_SHADOW=1`/`true` on the
/// daemon only for a measurement window. Read ONCE at the `memory_search`
/// public entry; everything below it takes parameters (the R1/R3 env-sinking
/// idiom). Pure split for unit tests.
fn fusion_shadow_enabled_from(env_val: Option<&str>) -> bool {
    matches!(env_val, Some(v) if v == "1" || v.eq_ignore_ascii_case("true"))
}

fn fusion_shadow_enabled() -> bool {
    fusion_shadow_enabled_from(std::env::var("AGENT_BRIDGE_FUSION_SHADOW").ok().as_deref())
}

/// Fusion-shadow knobs pinned to the paths they mirror: semantic-leg cosine
/// floor = the mode=semantic default; RRF k = the mode=hybrid default; a few
/// example keys per side keep one shadow row one compact line.
const FUSION_SHADOW_THRESHOLD: f32 = 0.3;
const FUSION_SHADOW_RRF_K: f64 = 60.0;
const FUSION_SHADOW_EXAMPLE_KEYS: usize = 5;

/// Pure R2 shadow math: RRF-fuse the ACTUAL returned page with the semantic
/// leg — via the very `ab_store::rrf_fuse` mode=hybrid runs — then measure how
/// top-k membership and order would change. `overlap` divides the top-k
/// intersection by `max(|actual|, |fused top-k|)` (1.0 when both are empty);
/// shifts are |rank_fused − rank_actual| over keys present in BOTH pages.
/// Returns a storable sample (`at` is stamped by the store).
fn fusion_shadow_metrics(
    query: &str,
    actual: &[String],
    semantic: &[String],
    k: usize,
) -> FusionShadowSample {
    let fused_full = ab_store::rrf_fuse(&[actual, semantic], FUSION_SHADOW_RRF_K);
    let fused: Vec<&String> = fused_full.iter().take(k).map(|(key, _)| key).collect();
    let actual_set: HashSet<&String> = actual.iter().collect();
    let fused_set: HashSet<&String> = fused.iter().copied().collect();
    let inter = fused.iter().filter(|key| actual_set.contains(*key)).count();
    let denom = actual.len().max(fused.len());
    let overlap = if denom == 0 {
        1.0
    } else {
        inter as f64 / denom as f64
    };
    let gained: Vec<String> = fused
        .iter()
        .filter(|key| !actual_set.contains(*key))
        .map(|key| (*key).clone())
        .collect();
    let lost: Vec<String> = actual
        .iter()
        .filter(|key| !fused_set.contains(key))
        .cloned()
        .collect();
    let shifts: Vec<u32> = actual
        .iter()
        .enumerate()
        .filter_map(|(a_rank, key)| {
            let f_rank = fused.iter().position(|f| *f == key)?;
            Some((a_rank as i64 - f_rank as i64).unsigned_abs() as u32)
        })
        .collect();
    let mean_abs_shift = if shifts.is_empty() {
        0.0
    } else {
        shifts.iter().map(|s| *s as f64).sum::<f64>() / shifts.len() as f64
    };
    FusionShadowSample {
        at: 0,
        query: query.to_string(),
        k: k as u32,
        actual_n: actual.len() as u32,
        semantic_n: semantic.len() as u32,
        overlap,
        gained: gained.len() as u32,
        lost: lost.len() as u32,
        max_abs_shift: shifts.iter().copied().max().unwrap_or(0),
        gained_keys: gained
            .into_iter()
            .take(FUSION_SHADOW_EXAMPLE_KEYS)
            .collect(),
        lost_keys: lost.into_iter().take(FUSION_SHADOW_EXAMPLE_KEYS).collect(),
        mean_abs_shift,
        skipped: false,
        skip_reason: None,
    }
}

/// R2 shadow leg runner — spawned off the caller's path; everything in here is
/// fail-soft (warn-only) because the main query already returned. The semantic
/// leg reuses the EXISTING internal path (`memory_search_semantic`, one query
/// embed). `skip_reason` is decided by the caller from cheap sync state so a
/// skip costs no embed; a skip row is still recorded (skips count).
async fn run_fusion_shadow(
    store: Arc<dyn StateStore>,
    query: String,
    actual: Vec<String>,
    k: usize,
    sem_limit: u32,
    skip_reason: Option<&'static str>,
) {
    let sample = match skip_reason {
        Some(reason) => FusionShadowSample {
            query,
            k: k as u32,
            actual_n: actual.len() as u32,
            skipped: true,
            skip_reason: Some(reason.to_string()),
            ..Default::default()
        },
        None => {
            match store
                .memory_search_semantic(&query, sem_limit, FUSION_SHADOW_THRESHOLD)
                .await
            {
                Ok(hits) => {
                    let sem: Vec<String> = hits.iter().map(|h| h.record.key.clone()).collect();
                    fusion_shadow_metrics(&query, &actual, &sem, k)
                }
                Err(e) => {
                    tracing::warn!(target: "fusion_shadow", error = %e, "semantic leg failed (non-fatal)");
                    return;
                }
            }
        }
    };
    if let Err(e) = store.record_fusion_shadow(&sample).await {
        tracing::warn!(target: "fusion_shadow", error = %e, "record_fusion_shadow failed (non-fatal)");
    }
}

#[cfg(test)]
mod fusion_shadow_tests {
    use super::{fusion_shadow_enabled_from, fusion_shadow_metrics};

    fn keys(v: &[&str]) -> Vec<String> {
        v.iter().map(|s| s.to_string()).collect()
    }

    #[test]
    fn fusion_shadow_gate_default_off_unless_truthy() {
        assert!(!fusion_shadow_enabled_from(None));
        assert!(!fusion_shadow_enabled_from(Some("")));
        assert!(!fusion_shadow_enabled_from(Some("0")));
        assert!(!fusion_shadow_enabled_from(Some("false")));
        assert!(!fusion_shadow_enabled_from(Some("yes")));
        assert!(fusion_shadow_enabled_from(Some("1")));
        assert!(fusion_shadow_enabled_from(Some("true")));
        assert!(fusion_shadow_enabled_from(Some("TRUE")));
    }

    #[test]
    fn fusion_shadow_metrics_overlap_gained_lost_shift() {
        // actual page [a,b,c,d] (k=4) fused with semantic [c,e,a] at RRF k=60:
        //   a: 1/61 + 1/63     c: 1/63 + 1/61 (== a, key tiebreak → a first)
        //   b: 1/62            e: 1/62 (== b, tiebreak → b first)   d: 1/64
        // fused top-4 = [a, c, b, e] → keeps {a,b,c}, gains e, drops d.
        let actual = keys(&["a", "b", "c", "d"]);
        let semantic = keys(&["c", "e", "a"]);
        let m = fusion_shadow_metrics("q", &actual, &semantic, 4);
        assert_eq!((m.k, m.actual_n, m.semantic_n), (4, 4, 3));
        assert!((m.overlap - 0.75).abs() < 1e-12, "3 of 4 kept");
        assert_eq!(m.gained, 1);
        assert_eq!(m.gained_keys, keys(&["e"]));
        assert_eq!(m.lost, 1);
        assert_eq!(m.lost_keys, keys(&["d"]));
        // Shifts over both-page keys: a 0→0, b 1→2, c 2→1 → mean 2/3, max 1.
        assert!((m.mean_abs_shift - 2.0 / 3.0).abs() < 1e-12);
        assert_eq!(m.max_abs_shift, 1);
        assert!(!m.skipped);
    }

    #[test]
    fn fusion_shadow_metrics_edge_pages() {
        // Empty actual page: fusion is pure semantic — all gained, no overlap.
        let m = fusion_shadow_metrics("q", &[], &keys(&["x", "y"]), 2);
        assert_eq!(m.overlap, 0.0);
        assert_eq!((m.gained, m.lost), (2, 0));
        assert_eq!(m.mean_abs_shift, 0.0);
        assert_eq!(m.max_abs_shift, 0);
        // Both legs empty: nothing to compare — overlap reads 1.0 (no change).
        let e = fusion_shadow_metrics("q", &[], &[], 5);
        assert_eq!(e.overlap, 1.0);
        assert_eq!((e.gained, e.lost), (0, 0));
        // Identical legs: fusion is a no-op page.
        let same = keys(&["m", "n"]);
        let s = fusion_shadow_metrics("q", &same, &same, 2);
        assert_eq!(s.overlap, 1.0);
        assert_eq!((s.gained, s.lost), (0, 0));
        assert_eq!(s.max_abs_shift, 0);
    }
}

#[cfg(test)]
mod recall_semantic_fallback_tests {
    use super::{
        ambient_surfacing_disabled_from, bootstrap_mmr_disabled_from, bootstrap_mmr_lambda_from,
        correction_cosurface_enabled_from, distill_surfacing_disabled_from,
        outcome_collector_enabled_from, recall_semantic_fallback_enabled_from,
        retrieval_traffic_class_from, BOOTSTRAP_MMR_LAMBDA_DEFAULT,
    };

    #[test]
    fn bootstrap_mmr_kill_switch_default_off_unless_truthy() {
        // Default: MMR re-rank of the semantic page runs (owner-approved
        // default-on, forum #147).
        assert!(!bootstrap_mmr_disabled_from(None));
        assert!(!bootstrap_mmr_disabled_from(Some("0")));
        assert!(!bootstrap_mmr_disabled_from(Some("")));
        assert!(!bootstrap_mmr_disabled_from(Some("off")));
        // Only an explicit truthy value disables it.
        assert!(bootstrap_mmr_disabled_from(Some("1")));
        assert!(bootstrap_mmr_disabled_from(Some("true")));
        assert!(bootstrap_mmr_disabled_from(Some("TRUE")));
    }

    #[test]
    fn bootstrap_mmr_lambda_defaults_on_garbage_and_accepts_valid() {
        // Unset / unparsable / non-finite / out-of-range → default 0.7.
        assert_eq!(
            bootstrap_mmr_lambda_from(None),
            BOOTSTRAP_MMR_LAMBDA_DEFAULT
        );
        assert_eq!(
            bootstrap_mmr_lambda_from(Some("banana")),
            BOOTSTRAP_MMR_LAMBDA_DEFAULT
        );
        assert_eq!(
            bootstrap_mmr_lambda_from(Some("")),
            BOOTSTRAP_MMR_LAMBDA_DEFAULT
        );
        assert_eq!(
            bootstrap_mmr_lambda_from(Some("NaN")),
            BOOTSTRAP_MMR_LAMBDA_DEFAULT
        );
        assert_eq!(
            bootstrap_mmr_lambda_from(Some("1.5")),
            BOOTSTRAP_MMR_LAMBDA_DEFAULT
        );
        assert_eq!(
            bootstrap_mmr_lambda_from(Some("-0.2")),
            BOOTSTRAP_MMR_LAMBDA_DEFAULT
        );
        // Valid in-range values (whitespace tolerated) pass through.
        assert_eq!(bootstrap_mmr_lambda_from(Some("0.5")), 0.5);
        assert_eq!(bootstrap_mmr_lambda_from(Some(" 1.0 ")), 1.0);
        assert_eq!(bootstrap_mmr_lambda_from(Some("0")), 0.0);
    }

    #[test]
    fn distill_surfacing_kill_switch_default_off_unless_truthy() {
        assert!(!distill_surfacing_disabled_from(None));
        assert!(!distill_surfacing_disabled_from(Some("0")));
        assert!(!distill_surfacing_disabled_from(Some("")));
        assert!(!distill_surfacing_disabled_from(Some("off")));
        assert!(distill_surfacing_disabled_from(Some("1")));
        assert!(distill_surfacing_disabled_from(Some("true")));
        assert!(distill_surfacing_disabled_from(Some("TRUE")));
    }

    #[test]
    fn ambient_surfacing_kill_switch_default_off_unless_truthy() {
        // Default: the ambient writer runs (subject to the collector gate).
        assert!(!ambient_surfacing_disabled_from(None));
        assert!(!ambient_surfacing_disabled_from(Some("0")));
        assert!(!ambient_surfacing_disabled_from(Some("")));
        assert!(!ambient_surfacing_disabled_from(Some("off")));
        // Only an explicit truthy value disables it.
        assert!(ambient_surfacing_disabled_from(Some("1")));
        assert!(ambient_surfacing_disabled_from(Some("true")));
        assert!(ambient_surfacing_disabled_from(Some("TRUE")));
    }

    #[test]
    fn semantic_fallback_default_off_unless_truthy() {
        // Default-OFF: unset / "0" / arbitrary values keep the fts path byte-identical.
        assert!(!recall_semantic_fallback_enabled_from(None));
        assert!(!recall_semantic_fallback_enabled_from(Some("0")));
        assert!(!recall_semantic_fallback_enabled_from(Some("")));
        assert!(!recall_semantic_fallback_enabled_from(Some("yes")));
        // Only an explicit truthy value opts in.
        assert!(recall_semantic_fallback_enabled_from(Some("1")));
        assert!(recall_semantic_fallback_enabled_from(Some("true")));
        assert!(recall_semantic_fallback_enabled_from(Some("TRUE")));
    }

    #[test]
    fn outcome_collector_default_off_unless_truthy() {
        // Default-OFF: unset / "0" / arbitrary values write zero telemetry rows.
        assert!(!outcome_collector_enabled_from(None));
        assert!(!outcome_collector_enabled_from(Some("0")));
        assert!(!outcome_collector_enabled_from(Some("")));
        assert!(!outcome_collector_enabled_from(Some("yes")));
        // Only an explicit truthy value opts in.
        assert!(outcome_collector_enabled_from(Some("1")));
        assert!(outcome_collector_enabled_from(Some("true")));
        assert!(outcome_collector_enabled_from(Some("TRUE")));
    }

    #[test]
    fn retrieval_traffic_class_is_canonical_and_fails_closed() {
        assert_eq!(retrieval_traffic_class_from(None), "unknown");
        assert_eq!(retrieval_traffic_class_from(Some("")), "unknown");
        assert_eq!(retrieval_traffic_class_from(Some("   ")), "unknown");
        assert_eq!(retrieval_traffic_class_from(Some("production")), "unknown");
        assert_eq!(retrieval_traffic_class_from(Some("organic")), "organic");
        assert_eq!(retrieval_traffic_class_from(Some(" Organic ")), "organic");
        assert_eq!(retrieval_traffic_class_from(Some("EVAL")), "eval");
    }

    #[test]
    fn correction_cosurface_default_off_unless_truthy() {
        // Default-OFF: unset / "0" / arbitrary values keep the fts page
        // byte-identical to pure ranking.
        assert!(!correction_cosurface_enabled_from(None));
        assert!(!correction_cosurface_enabled_from(Some("0")));
        assert!(!correction_cosurface_enabled_from(Some("")));
        assert!(!correction_cosurface_enabled_from(Some("yes")));
        assert!(!correction_cosurface_enabled_from(Some("false")));
        // Only an explicit truthy value opts in to B1 co-surfacing.
        assert!(correction_cosurface_enabled_from(Some("1")));
        assert!(correction_cosurface_enabled_from(Some("true")));
        assert!(correction_cosurface_enabled_from(Some("TRUE")));
    }
}

pub struct MemorySearchTool {
    hub: Hub,
}
impl MemorySearchTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemorySearchTool {
    fn name(&self) -> &'static str {
        "memory_search"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Search memories by keyword or semantic similarity. mode='fts': \
                 FTS5 by bm25+recency+importance. mode='hybrid': FTS5 + graph neighbors \
                 via RRF fusion. mode='semantic': cosine over local embeddings — catches \
                 synonyms FTS misses. Excludes archived/superseded. Set compact:true for \
                 a key/kind/tags/importance/score/preview projection, then memory_get the \
                 few rows worth reading in full."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "query":      { "type": "string", "description": "Search query (FTS5 match syntax for fts/hybrid; natural language for semantic)." },
                    "tags_any":   { "type": "array", "items": { "type": "string" }, "default": [] },
                    "scope":      {
                        "type": "string",
                        "description": "Optional scope hint/filter, e.g. project:/abs/path or domain:rust. Pair with scope_mode to choose local-only recall vs cross-project exploration."
                    },
                    "scope_mode": {
                        "type": "string",
                        "enum": ["local_only", "local_plus_global", "exploratory"],
                        "default": "local_only",
                        "description": "When scope is set: local_only keeps only matching project/domain rows; local_plus_global also allows global/unscoped rows with a small score penalty; exploratory keeps cross-project rows as demoted analogy candidates."
                    },
                    "include_global": {
                        "type": "boolean",
                        "default": false,
                        "description": "Compatibility alias for scope_mode=local_plus_global when scope_mode is omitted."
                    },
                    "limit":      { "type": "integer", "minimum": 1, "maximum": 200, "default": 20 },
                    "mode":       {
                        "type": "string", "enum": ["fts", "hybrid", "semantic"], "default": "fts",
                        "description": "'fts' = keyword BM25; 'hybrid' = FTS5 + graph RRF fusion; 'semantic' = cosine similarity."
                    },
                    "expand_top": {
                        "type": "integer", "minimum": 1, "maximum": 20, "default": 10,
                        "description": "[hybrid only] Number of top FTS5 hits to expand via graph neighbors."
                    },
                    "rrf_k":      {
                        "type": "number", "minimum": 1.0, "maximum": 200.0, "default": 60.0,
                        "description": "[hybrid only] RRF constant k. Higher k = less rank compression."
                    },
                    "threshold":  {
                        "type": "number", "minimum": 0.0, "maximum": 1.0, "default": 0.3,
                        "description": "[semantic only] Minimum cosine similarity to include. 0.3 = broad, 0.7 = tight."
                    },
                    "exclude_kinds": {
                        "type": "array", "items": { "type": "string" }, "default": [],
                        "description": "Drop hits whose `kind` matches any of these from the OUTPUT. \
                            Useful for keeping bulky `skill` records (~88% of store) out of generic queries. \
                            Inner search auto-overfetches 5× to compensate. α coactivation still learns \
                            from the full pre-filter hit set, so cross-kind edges keep forming."
                    },
                    "compact": {
                        "type": "boolean", "default": false,
                        "description": "Return a compact projection per hit — key/kind/tags/importance/\
                            score(+cosine)/content_preview (first 200 chars) + content_chars — instead \
                            of full records (~5-8KB vs ~25KB a page). Ranking, limits and telemetry are \
                            unchanged; follow up with memory_get for the rows worth reading in full. \
                            Default false = full records, byte-identical to prior behavior."
                    }
                },
                "required": ["query"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let q = args
            .get("query")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string();
        let tags: Vec<String> = args
            .get("tags_any")
            .and_then(|v| v.as_array())
            .map(|a| {
                a.iter()
                    .filter_map(|x| x.as_str().map(|s| s.to_string()))
                    .collect()
            })
            .unwrap_or_default();
        let limit = args
            .get("limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(20)
            .min(200) as u32;
        // Clamp to the schema enum: off-enum values already fell through to
        // the fts path, but the raw string also reached the surfacing writer
        // as a telemetry label — a client passing mode="bootstrap" would have
        // its search logged under the writer-reserved ambient mode and voided
        // from every learning aggregate (review finding, 2026-07-05).
        let mode = match args.get("mode").and_then(|v| v.as_str()).unwrap_or("fts") {
            m @ ("hybrid" | "semantic") => m,
            _ => "fts",
        };
        let scope_filter = args
            .get("scope")
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(str::to_string);
        let include_global = args
            .get("include_global")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let scope_mode = memory_search_scope_mode(&args, include_global);
        let remote_session_specificity = remote_session_specificity_policy(
            remote_session_specificity_enabled(),
            mode,
            scope_filter.as_deref(),
            &q,
        );

        let mut exclude_kinds: Vec<String> = args
            .get("exclude_kinds")
            .and_then(|v| v.as_array())
            .map(|a| {
                a.iter()
                    .filter_map(|x| x.as_str().map(|s| s.to_string()))
                    .collect()
            })
            .unwrap_or_default();
        // Machine-level default exclusions, unioned with the caller's list.
        // Bookkeeping kinds parasitize their own target's queries (e.g. a
        // retrieval_feedback row quotes the query text it was stamped for,
        // so it outranks the content row on exactly that query). Default
        // unset = byte-identical behavior.
        for k in memory_search_env_exclude_kinds() {
            if !exclude_kinds.contains(&k) {
                exclude_kinds.push(k);
            }
        }
        // When output filters are active, overfetch so the post-filter result
        // can still hit `limit`. 5× covers up to ~80% saturation; cap at 200
        // (the schema's hard upper bound) to avoid pathological queries.
        // Class quota also needs a beyond-`limit` pool to promote from, but a
        // flat 200 cap would leave that pool EMPTY at limit=200 and starved
        // above 40 (review A-3) — so its branch always keeps ≥40 pool rows.
        let class_quota = memory_class_quota();
        let inner_limit =
            if exclude_kinds.is_empty() && scope_filter.is_none() && class_quota.is_empty() {
                limit
            } else if class_quota.is_empty() {
                (limit.saturating_mul(5)).min(200)
            } else {
                (limit.saturating_mul(5)).min(200.max(limit.saturating_add(40)))
            };

        let started = Instant::now();
        let mut semantic_fallback_fired = false;
        let hits = if mode == "hybrid" {
            let expand_top = args
                .get("expand_top")
                .and_then(|v| v.as_u64())
                .unwrap_or(10)
                .min(20) as u32;
            let rrf_k = args
                .get("rrf_k")
                .and_then(|v| v.as_f64())
                .unwrap_or(60.0)
                .clamp(1.0, 200.0);
            store
                .memory_search_hybrid(&q, &tags, inner_limit, rrf_k, expand_top)
                .await?
        } else if mode == "semantic" {
            let threshold = args
                .get("threshold")
                .and_then(|v| v.as_f64())
                .unwrap_or(0.3)
                .clamp(0.0, 1.0) as f32;
            let cache_guard = self.hub.memory_embed_cache.lock().await;
            // Under the lock, do ONLY the cosine sweep against the cached
            // embeddings (the one thing that genuinely needs the frozen
            // vectors), collecting above-threshold candidates. Everything else
            // — fresh metadata, blend, sort — happens after we release the lock,
            // so the one new DB await (metadata overlay) never holds the mutex.
            // (The query embed stays inside the warm branch, as before, so the
            // cold path doesn't pay a redundant embed the SQL fallback repeats.)
            let warm_candidates: Option<Vec<(MemoryRecord, f32)>> =
                cache_guard.as_ref().map(|cached| {
                    let query_vec = embed_text(&q);
                    cached
                        .iter()
                        // Racy-cleanup guard, retained for the DB-error fallback
                        // below: cache removal (delete/compact) is a fire-and-
                        // forget spawn, so a just-removed row may still sit here
                        // with a stale `status`. The live-meta overlay is
                        // stricter still (drops anything not active in the DB).
                        .filter(|(rec, _)| rec.status == "active")
                        .filter_map(|(rec, emb)| {
                            let cosine = cosine_similarity(&query_vec, emb);
                            if cosine < threshold {
                                return None;
                            }
                            Some((rec.clone(), cosine))
                        })
                        .collect()
                });
            drop(cache_guard);
            match warm_candidates {
                Some(candidates) => {
                    // Re-hydrate ranking metadata from the DB so warm ranking
                    // matches the SQL path even when importance/status/access
                    // changed after the cache was primed. The warm embed cache
                    // is a frozen snapshot; valence-importance apply, decay,
                    // reinforce, correction and archive all mutate the DB WITHOUT
                    // touching it, so its per-row importance/status went stale —
                    // making the arc6 valence boost invisible on warm daemons
                    // and leaking superseded/archived rows into results. The
                    // cache still owns the expensive embeddings; this overlay is
                    // a metadata-only scan (no blobs). Score via the SAME
                    // owner-approved weights + shared semantic_blend_score as the
                    // SQL path (also: honors every AGENT_BRIDGE_SEMANTIC_* knob).
                    let weights = semantic_rank_weights();
                    let now = now_secs();
                    let live_meta = store.memory_active_meta().await;
                    if let Err(e) = &live_meta {
                        tracing::warn!(
                            target: "memory_semantic",
                            error = %e,
                            "warm-path live metadata refresh failed; falling back \
                             to cached (possibly stale) metadata"
                        );
                    }
                    let mut hits: Vec<MemorySearchHit> = candidates
                        .into_iter()
                        .filter_map(|(mut rec, cosine)| {
                            if let Ok(meta_map) = &live_meta {
                                match meta_map.get(&rec.key) {
                                    // Fresh metadata → override the frozen
                                    // importance/recency/access with live values.
                                    Some(meta) => {
                                        rec.importance = meta.importance;
                                        rec.last_accessed_at = meta.last_accessed_at;
                                        rec.access_count = meta.access_count;
                                    }
                                    // Absent from the active-metadata map → the
                                    // row was superseded/archived/deleted after
                                    // priming. Its cached `status` still reads
                                    // "active"; drop it so warm never leaks a dead
                                    // row the SQL path (WHERE status='active')
                                    // would exclude.
                                    None => return None,
                                }
                            }
                            // else: DB fetch errored → keep the cached fields
                            // (pre-fix behavior) rather than dropping everything.
                            let score = semantic_blend_score(
                                weights,
                                cosine,
                                rec.importance,
                                rec.last_accessed_at,
                                rec.access_count,
                                &rec.kind,
                                now,
                            );
                            Some(MemorySearchHit {
                                score,
                                record: rec,
                                cosine: Some(cosine),
                            })
                        })
                        .collect();
                    sort_hits_score_desc(&mut hits);
                    hits.truncate(inner_limit as usize);
                    hits
                }
                None => {
                    store
                        .memory_search_semantic(&q, inner_limit, threshold)
                        .await?
                }
            }
        } else {
            // Default (fts) path. Item B (2026-06-26, #120): owner-gated semantic
            // fallback for the FTS-empty tail. gte-768 semantic recall is ~2x fts
            // on the hard (no-lexical-overlap) recall_eval tier — but only for the
            // paraphrase queries FTS cannot serve AT ALL, so recover via cosine
            // strictly when FTS returns zero rows AND the flag is on AND a real
            // (non-hash) embedder has loaded (cold-load hash never injects noise).
            // Default-OFF: byte-identical to pure fts until the owner flips it.
            let mut fts_hits = store.memory_search(&q, &tags, inner_limit).await?;
            // Fire only on the no-lexical-overlap tail: FTS truly empty, AND no
            // tag predicate to honor (memory_search_semantic ignores tags_any, so
            // substituting would leak tag-violating rows), AND the flag is on, AND
            // a real embedder is available (cold-load hash never injects noise).
            if fts_hits.is_empty()
                && tags.is_empty()
                && recall_semantic_fallback_enabled()
                && fallback_embedder_ready()
            {
                let threshold = args
                    .get("threshold")
                    .and_then(|v| v.as_f64())
                    .unwrap_or(0.3)
                    .clamp(0.0, 1.0) as f32;
                let fb = store
                    .memory_search_semantic(&q, inner_limit, threshold)
                    .await?;
                if !fb.is_empty() {
                    semantic_fallback_fired = true;
                    fts_hits = fb;
                }
            }
            fts_hits
        };

        // Quota-only overfetch must NOT widen what the pipeline stages below
        // see: pre-quota, an unfiltered query ran seed boost / coactivation
        // rerank / sampling over exactly `limit` rows, and inflating that pool
        // via an ambient env var would silently change ranking for every
        // query even when the quota itself no-ops (review B-1/G-4/F-3). Park
        // the overfetched tail here, keeping only quota-class rows; the quota
        // stage re-appends it after every rerank stage has run. Queries with
        // caller filters (exclude_kinds / scope) already ran pool-wide before
        // this feature and keep doing so.
        let mut hits = hits;
        let mut quota_reserve: Vec<MemorySearchHit> = Vec::new();
        if !class_quota.is_empty()
            && exclude_kinds.is_empty()
            && scope_filter.is_none()
            && hits.len() > limit as usize
        {
            quota_reserve = hits.split_off(limit as usize);
            quota_reserve.retain(|h| {
                class_quota
                    .iter()
                    .any(|(k, _)| h.record.kind.eq_ignore_ascii_case(k))
            });
        }
        // Scope mode is intentionally applied before Seed/coactivation rerank:
        // callers asking for local work should not let discarded cross-project
        // hits affect boosts, while exploratory mode keeps those hits as
        // demoted analogy candidates instead of letting them dominate top-k.
        if let Some(scope) = scope_filter.as_deref() {
            // Whether the caller *explicitly* chose a scope_mode. A deliberate
            // `scope_mode:"local_only"` is honored strictly (no silent widening);
            // only the DEFAULT (local_only via omission) gets the recall-recovery
            // fallback inside the helper.
            let scope_mode_explicit = args
                .get("scope_mode")
                .and_then(|v| v.as_str())
                .map(str::trim)
                .map(|s| !s.is_empty())
                .unwrap_or(false);
            hits = memory_search_apply_scope_mode_with_fallback(
                hits,
                scope,
                scope_mode,
                scope_mode_explicit,
            );
        }

        // Engram specificity v0 (default-OFF): a narrow, mechanically gated
        // repair for the observed remote-agent-session overgeneralization.
        // Non-steering queries cannot surface this family; strict steering
        // queries keep the semantic page but bypass the coactivation rerank
        // that moved the highest-cosine answer from rank 1 to rank 10.
        //
        // This runs before seed/coactivation so a suppressed row cannot affect
        // another candidate's score or create a misleading coactivation trace.
        if remote_session_specificity == RemoteSessionSpecificityPolicy::SuppressFamily {
            hits.retain(|hit| !is_remote_session_steering_family_key(&hit.record.key));
        }

        // Path C actuator: rerank using perception_filter hub_clusters.
        // Fail-soft (no state file / disable env / empty hub_clusters → pass-through).
        let hits = apply_seed_boost(hits);

        // Phase 1 P1 — coactivation rerank. For each hit, sum the count of
        // edges connecting it to OTHER hits in the same page. Boost score by
        // `1 + 0.2 * ln(1 + sum)`. Pure no-op when graph is empty (zero
        // edges → boost = 1.0 → score unchanged). Single SQL round-trip.
        //
        // Operator disable knob (2026-07-03, forum #102):
        // `AGENT_BRIDGE_COACTIVATION_RERANK_DISABLE=1` turns the multiplier
        // off; DEFAULT KEEPS IT ON (upstream contract and design docs
        // unchanged). Rationale for the knob: a joint offline A/B on one
        // frozen store snapshot (6 fresh-target probes + the recall_eval
        // curated corpus' 9 live cases, UNFILTERED top-limit regime only)
        // measured the boost net-negative there — fresh-target MRR
        // 0.312→0.667, curated 0.387→0.870 with it off — because veterans
        // that repeatedly co-surface accrue dense mutual edges and boost
        // each other ×1.4–1.7 past the semantically-correct hit. Honest
        // limits of that evidence: 15 queries, a Python replication (not the
        // binary), a graph grown under rerank-ON page composition, and the
        // filtered regime (exclude_kinds/scope, where the rerank runs over
        // the 5× pool and can change page MEMBERSHIP, not just order) was
        // NOT modeled — hence a per-deployment knob, not a default flip.
        // Re-evaluate after the graph regrows under the new policy. Note the
        // coactivation WRITES below always stay: they feed dream_replay
        // consolidation, memory_coactivation_top and prune/latch tooling
        // (NOT hybrid RRF — that reads memory_edges only, which coactivation
        // reaches solely via crystallization).
        let hits = if !coactivation_rerank_disabled()
            && remote_session_specificity != RemoteSessionSpecificityPolicy::StrictSteering
            && hits.len() >= 2
        {
            let keys: Vec<String> = hits.iter().map(|h| h.record.key.clone()).collect();
            match store.coactivation_among(&keys).await {
                Ok(edges) if !edges.is_empty() => {
                    let mut per_key: HashMap<String, u64> = HashMap::new();
                    for e in &edges {
                        // Each edge contributes count to BOTH endpoints since
                        // an edge means "these two co-fire". A key with N
                        // edges in this page is in a tight cluster.
                        *per_key.entry(e.key_a.clone()).or_insert(0) += e.count;
                        *per_key.entry(e.key_b.clone()).or_insert(0) += e.count;
                    }
                    let boosted: Vec<MemorySearchHit> = hits
                        .into_iter()
                        .map(|mut h| {
                            let c = per_key.get(&h.record.key).copied().unwrap_or(0);
                            let boost = 1.0 + 0.2 * (1.0 + c as f64).ln();
                            h.score *= boost;
                            h
                        })
                        .collect();
                    let mut sorted = boosted;
                    sort_hits_score_desc(&mut sorted);
                    sorted
                }
                _ => hits,
            }
        } else {
            hits
        };

        // Apply caller's exclude_kinds and re-truncate to the requested limit.
        let mut hits = hits;
        if !exclude_kinds.is_empty() {
            hits.retain(|h| !exclude_kinds.iter().any(|k| k == &h.record.kind));
        }
        // TTL suppression: drop rows whose `ttl:<N>d` window has passed, so
        // bounded-life plumbing (e.g. `*_apply` rollback-map audit rows) stops
        // flooding top-k once its rollback window is over. Rows without a ttl
        // tag are never affected (record_ttl_is_live returns true), so this is
        // byte-identical for the overwhelming majority of the store.
        {
            let now = unix_now_secs();
            hits.retain(|h| record_ttl_is_live(&h.record, now));
        }
        // B1 — correction co-surface (gated; default-OFF → byte-identical to the
        // pure ranking above). When AGENT_BRIDGE_CORRECTION_COSURFACE is enabled,
        // any result that is the target of an INBOUND active `corrects` edge gets
        // its corrector pulled in immediately after it, so a stale original never
        // surfaces without the correction that supersedes its claim. Runs BEFORE
        // the final truncate so the page stays within `limit` — a surfaced
        // correction DISPLACES the weakest tail result rather than growing the
        // page. Anchors are bounded to the prospective top-`limit`, so switch-on
        // cost is at most one `memory_neighbors` lookup per visible result, and a
        // page with no corrected original is left untouched.
        let cosurfaced_keys: HashSet<String> = if correction_cosurface_enabled() {
            cosurface_corrections(&store, &mut hits, limit as usize, &exclude_kinds).await
        } else {
            HashSet::new()
        };
        // Class-quota reservation (gated; empty spec → byte-identical). Runs
        // LAST before the truncate so the guarantee survives every earlier
        // rerank/co-surface stage. The parked reserve rejoins the pool here —
        // only rows that cleared the mode's own match bar are promotable, and
        // cosurfaced correctors are exempt from displacement so a stale
        // original never sheds its correction (review B-3).
        if !quota_reserve.is_empty() {
            hits.append(&mut quota_reserve);
        }
        apply_class_quota(&mut hits, limit as usize, &class_quota, &cosurfaced_keys);
        hits.truncate(limit as usize);

        // v21 α — Synaptic Trace. Record co-activation pairs for the FINAL
        // page as fire-and-forget background work; never block search latency.
        // ctx_centroid is None for now (mode-agnostic α); follow-up plumbs
        // hit embeddings through for richer trace.
        //
        // Sampled AFTER exclude/cosurface/quota/truncate (review G-1/C-2): the
        // surfaced log and the coactivation writes must describe the page the
        // caller actually sees. Pre-quota sampling logged displaced rows as
        // surfaced (feeding retrieval_outcome_report false decay candidates)
        // and structurally excluded quota-promoted rows from the very
        // access/coactivation accrual the reservation exists to bootstrap.
        //
        // **Phase 1 P1.5 — skill filter.** Exclude `kind=skill` records
        // from coactivation writes. Skills are *procedures*, not knowledge
        // facts; they show up in result pages by FTS overlap and would ride
        // the P1 boost loop unfairly (Phase 1 P1 demo confirmed: a Java
        // skill record rode +22% on a Path C query). Same intent as
        // memory_link_audit defaulting to `include_skills=false`. The
        // filter applies pre-record, so the graph stays clean at write
        // time rather than needing a downstream cleanup.
        let coact_keys: Vec<String> = hits
            .iter()
            .filter(|h| h.record.kind != "skill")
            .filter(|h| {
                scope_filter.as_deref().map_or(true, |scope| {
                    memory_search_scope_trace_allowed(&h.record, scope, scope_mode)
                })
            })
            .take(10)
            .map(|h| h.record.key.clone())
            .collect();
        // Outcome-collector prototype (flag-gated, default-OFF): log the surfaced
        // keys so a later EXPLICIT memory_get of one of them attributes a "used"
        // retrieval outcome. Reuses coact_keys (top-10 non-skill, scope-allowed)
        // as the surfaced set; clones it so the coactivation write below still
        // owns its copy. Fire-and-forget like coactivation — never blocks search.
        if outcome_collector_enabled() && !coact_keys.is_empty() {
            let store_clone = store.clone();
            let surfaced: Vec<(String, i64)> = coact_keys
                .iter()
                .enumerate()
                .map(|(i, k)| (k.clone(), i as i64))
                .collect();
            let q_owned = q.to_string();
            let mode_owned = mode.to_string();
            let traffic_class = retrieval_traffic_class().to_string();
            tokio::spawn(async move {
                let _ = store_clone
                    .record_retrieval_surfacing_classified(
                        &surfaced,
                        &q_owned,
                        &mode_owned,
                        &traffic_class,
                    )
                    .await;
            });
        }
        if coact_keys.len() >= 2 {
            let store_clone = store.clone();
            tokio::spawn(async move {
                let _ = store_clone.record_coactivation(&coact_keys, None).await;
            });
        }

        let elapsed = started.elapsed();

        // Phase 0 telemetry: log hit count + top-hit age (post-filter, what the
        // user actually sees). Top-hit age uses created_at as the recency anchor;
        // we deliberately don't use last_accessed_at because memory_search itself
        // bumps it on read in some backends and would self-zero this signal.
        let kind_label = if semantic_fallback_fired {
            // Honest telemetry: a default-path query that FTS could not serve and
            // the gated semantic fallback recovered — never silently labeled fts.
            "search_fts_semantic_fallback"
        } else {
            match mode {
                "hybrid" => "search_hybrid",
                "semantic" => "search_semantic",
                _ => "search_fts",
            }
        };
        let now_secs = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_secs() as i64)
            .unwrap_or(0);
        let (top_age, top_created) = hits
            .first()
            .map(|h| {
                (
                    Some(now_secs - h.record.created_at),
                    Some(h.record.created_at),
                )
            })
            .unwrap_or((None, None));
        let tags_json = serde_json::to_string(&tags).unwrap_or_else(|_| "[]".to_string());
        log_memory_query(
            store.clone(),
            kind_label,
            q.clone(),
            tags_json,
            hits.len() as u32,
            top_age,
            top_created,
            elapsed,
            "mcp:memory_search",
        );

        // R2 fusion shadow (forum #147, default-OFF): passively measure how
        // the page just assembled WOULD change if a semantic leg were RRF-fused
        // into the default (fts) ranking. Default-mode path only, spawned
        // fire-and-forget AFTER the page is final — returned bytes identical
        // flag on or off. Skips are decided here from cheap sync state and
        // still recorded (counted): a hash-fallback embedder measures noise;
        // a fallback-served page already IS the semantic leg.
        if mode == "fts" && fusion_shadow_enabled() {
            let skip_reason = if semantic_fallback_fired {
                Some("semantic_fallback_served")
            } else if !fallback_embedder_ready() {
                Some("hash_embedder")
            } else {
                None
            };
            let store_shadow = store.clone();
            let q_shadow = q.clone();
            let actual_keys: Vec<String> = hits.iter().map(|h| h.record.key.clone()).collect();
            let k_page = limit as usize;
            tokio::spawn(async move {
                run_fusion_shadow(
                    store_shadow,
                    q_shadow,
                    actual_keys,
                    k_page,
                    inner_limit,
                    skip_reason,
                )
                .await;
            });
        }

        // S4 projection dispatch. Param absent/false takes the pre-existing
        // full-record path untouched — the byte-identical default contract.
        let compact = args
            .get("compact")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let project: fn(&MemorySearchHit) -> Value = if compact {
            memory_search_hit_value_compact
        } else {
            memory_search_hit_value_with_continuity
        };
        Ok(ToolResult::json_text(&Value::Array(
            hits.iter().map(project).collect(),
        )))
    }
}

/// True when the B1 correction co-surface read-path is enabled. Default-OFF:
/// when unset / `0` / `false` the search path is byte-identical to pure ranking.
/// Mirrors the existing `AGENT_BRIDGE_*` boolean-switch idiom (e.g. main.rs).
fn correction_cosurface_enabled_from(env_val: Option<&str>) -> bool {
    matches!(env_val, Some(v) if v == "1" || v.eq_ignore_ascii_case("true"))
}

fn correction_cosurface_enabled() -> bool {
    correction_cosurface_enabled_from(
        std::env::var("AGENT_BRIDGE_CORRECTION_COSURFACE")
            .ok()
            .as_deref(),
    )
}

/// Parse the `AGENT_BRIDGE_MEMORY_CLASS_QUOTA` spec: comma-separated
/// `kind:slots` pairs (e.g. `present_outcome:2,lesson:1`). Default-OFF: when
/// unset / empty / all-malformed the search path is byte-identical to pure
/// ranking. Malformed pieces are skipped fail-soft (mirrors the
/// `AGENT_BRIDGE_SEMANTIC_W_*` override idiom); the first spec for a kind
/// wins. Kinds are lowercased here and matched case-insensitively against
/// rows (same contract as the coverage kind matcher) so a case-variant spec
/// or store row never silently voids the quota (review A-5).
fn memory_class_quota_from(env_val: Option<&str>) -> Vec<(String, usize)> {
    let Some(raw) = env_val else {
        return Vec::new();
    };
    let mut out: Vec<(String, usize)> = Vec::new();
    for part in raw.split(',') {
        let Some((kind, slots)) = part.split_once(':') else {
            continue;
        };
        let kind = kind.trim().to_ascii_lowercase();
        let Ok(slots) = slots.trim().parse::<usize>() else {
            continue;
        };
        if kind.is_empty() || slots == 0 || out.iter().any(|(k, _)| *k == kind) {
            continue;
        }
        out.push((kind, slots));
    }
    out
}

fn memory_class_quota() -> Vec<(String, usize)> {
    memory_class_quota_from(
        std::env::var("AGENT_BRIDGE_MEMORY_CLASS_QUOTA")
            .ok()
            .as_deref(),
    )
}

/// Parse `AGENT_BRIDGE_MEMORY_SEARCH_EXCLUDE_KINDS`: comma-separated kinds
/// dropped from every memory_search OUTPUT, unioned with the caller's
/// `exclude_kinds` param. Fail-soft like the class-quota parser; default
/// unset / empty = no machine-level exclusion. Values are trimmed but NOT
/// case-folded — the downstream filter is an exact match against the stored
/// kind (kinds are conventionally lowercase), same contract as the caller
/// param. The inner search already overfetches 5× whenever exclusions are
/// active, and α coactivation still learns from the pre-filter hit set.
fn memory_search_env_exclude_kinds_from(env_val: Option<&str>) -> Vec<String> {
    let Some(raw) = env_val else {
        return Vec::new();
    };
    let mut out: Vec<String> = Vec::new();
    for part in raw.split(',') {
        let k = part.trim().to_string();
        if !k.is_empty() && !out.contains(&k) {
            out.push(k);
        }
    }
    out
}

fn memory_search_env_exclude_kinds() -> Vec<String> {
    memory_search_env_exclude_kinds_from(
        std::env::var("AGENT_BRIDGE_MEMORY_SEARCH_EXCLUDE_KINDS")
            .ok()
            .as_deref(),
    )
}

const REMOTE_SESSION_SPECIFICITY_ENV: &str = "AGENT_BRIDGE_REMOTE_SESSION_SPECIFICITY_V0";
const REMOTE_SESSION_SPECIFICITY_PROJECT_ID: &str =
    "project-id:git:gitlab.com/pallasting/agent-bridge";

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum RemoteSessionSpecificityPolicy {
    Off,
    StrictSteering,
    SuppressFamily,
}

fn remote_session_specificity_enabled_from(value: Option<&str>) -> bool {
    matches!(value, Some(v) if v == "1" || v.eq_ignore_ascii_case("true"))
}

fn remote_session_specificity_enabled() -> bool {
    remote_session_specificity_enabled_from(
        std::env::var(REMOTE_SESSION_SPECIFICITY_ENV)
            .ok()
            .as_deref(),
    )
}

fn remote_session_specificity_policy(
    enabled: bool,
    mode: &str,
    requested_scope: Option<&str>,
    query: &str,
) -> RemoteSessionSpecificityPolicy {
    let aliases = std::env::var(PROJECT_SCOPE_ALIASES_ENV).ok();
    remote_session_specificity_policy_with_aliases(
        enabled,
        mode,
        requested_scope,
        query,
        aliases.as_deref(),
    )
}

fn remote_session_specificity_policy_with_aliases(
    enabled: bool,
    mode: &str,
    requested_scope: Option<&str>,
    query: &str,
    project_scope_aliases: Option<&str>,
) -> RemoteSessionSpecificityPolicy {
    if !enabled || mode != "semantic" {
        return RemoteSessionSpecificityPolicy::Off;
    }
    let Some(scope) = requested_scope else {
        return RemoteSessionSpecificityPolicy::Off;
    };
    if !project_scopes_read_time_compatible_with_aliases(
        scope,
        REMOTE_SESSION_SPECIFICITY_PROJECT_ID,
        project_scope_aliases,
    ) {
        return RemoteSessionSpecificityPolicy::Off;
    }
    if is_strict_remote_session_steering_query(query) {
        RemoteSessionSpecificityPolicy::StrictSteering
    } else {
        RemoteSessionSpecificityPolicy::SuppressFamily
    }
}

fn is_strict_remote_session_steering_query(query: &str) -> bool {
    let query = query.to_lowercase();
    let contains_any = |needles: &[&str]| needles.iter().any(|needle| query.contains(needle));
    let agent = contains_any(&[
        "agent",
        "agentbridge",
        "agent-bridge",
        "codex",
        "claude",
        "kilo",
        "aio2",
    ]);
    let remote = contains_any(&["远程", "远端", "remote", "tailnet", "aio2", "远程控制"]);
    let session = contains_any(&[
        "会话",
        "session",
        "tmux",
        "mux",
        "pane",
        "长驻",
        "long-lived",
        "long running",
        "long-running",
        "detached",
        "presence",
        "handle",
    ]);
    let steering = contains_any(&[
        "注入指令",
        "指令",
        "输入",
        "发送",
        "控制",
        "steer",
        "steering",
        "remote_steer",
        "agent_steer",
        "agent_steer_drive",
        "send-keys",
        "send keys",
        "send input",
        "drive",
    ]);
    agent && remote && session && steering
}

fn is_remote_session_steering_family_key(key: &str) -> bool {
    let key = key.to_ascii_lowercase();
    key.contains("agentbridge_remote_session_steer_gap")
        || key.contains("session_handoff_agent_spawn_remote_steer")
        || key.contains("agent_spawn_remote_ssh_and_steer")
        || key.contains("remote_session_steering")
        || key.contains("remote_steer")
        || key.contains("agent_steer")
        || key.contains("steer_presence")
        || (key.contains("mux") && key.contains("steer"))
}

/// True when the operator has disabled the P1 coactivation read-side rerank
/// (`AGENT_BRIDGE_COACTIVATION_RERANK_DISABLE=1`). Default = enabled, i.e.
/// unset keeps the long-standing behavior; the disable knob exists because a
/// per-deployment offline A/B measured the multiplier net-negative on the
/// unfiltered regime (see the gate site in MemorySearchTool::execute).
/// Mirrors the `AGENT_BRIDGE_SEED_BOOST_DISABLE` idiom.
fn coactivation_rerank_disabled_from(env_val: Option<&str>) -> bool {
    matches!(env_val, Some(v) if v == "1" || v.eq_ignore_ascii_case("true"))
}

fn coactivation_rerank_disabled() -> bool {
    coactivation_rerank_disabled_from(
        std::env::var("AGENT_BRIDGE_COACTIVATION_RERANK_DISABLE")
            .ok()
            .as_deref(),
    )
}

/// Class-quota reservation — guarantee each configured `kind` at least `slots`
/// rows on the final top-`limit` page, promoting that kind's best-scoring rows
/// from the overfetched beyond-`limit` pool.
///
/// Motivation (2026-07-03 measurement, forum #102 post #2883): entrenched
/// high-importance / high-access rows compound two flywheels — the frequency
/// term grows on every surfacing, and the coactivation rerank multiplies
/// scores only among rows already sharing a page — so a fresh thin row can
/// hold a HIGHER cosine than most of the page yet never break in (best
/// `present_outcome` row: cosine above 14 of top-20, ranked #29/737). A
/// reserved slot is the cold-start diversity valve: the row surfaces, accrues
/// access/coactivation organically, and competes on its own afterwards.
///
/// Contract: never grows the page, only promotes rows that already cleared
/// the mode's own match bar (cosine threshold / FTS / RRF), and displacement
/// never touches (a) another quota class's GUARANTEED rows — surplus rows
/// beyond a class's own `slots` are fair game (review A-4) — or (b) rows in
/// `protected` (cosurfaced correctors; evicting one would strand its stale
/// anchor on the page, review B-3). After any swap the page is re-sorted by
/// score — the stable sort keeps cosurfaced correctors adjacent to their
/// anchors (equal scores). No-op when the pool fits the page or quotas are
/// already satisfied.
fn apply_class_quota(
    hits: &mut Vec<MemorySearchHit>,
    limit: usize,
    quotas: &[(String, usize)],
    protected: &HashSet<String>,
) {
    if quotas.is_empty() || hits.len() <= limit || limit == 0 {
        return;
    }
    // Per-quota-kind page counts (quota kinds are pre-lowercased), maintained
    // across swaps so later classes see the page the earlier ones produced.
    let quota_slots = |kind_lower: &str| -> Option<usize> {
        quotas
            .iter()
            .find(|(k, _)| *k == kind_lower)
            .map(|(_, s)| *s)
    };
    let mut page_count: HashMap<String, usize> = HashMap::new();
    for h in hits[..limit].iter() {
        let kl = h.record.kind.to_ascii_lowercase();
        if quota_slots(&kl).is_some() {
            *page_count.entry(kl).or_insert(0) += 1;
        }
    }
    let mut swapped = false;
    for (kind, slots) in quotas {
        let have = page_count.get(kind).copied().unwrap_or(0);
        if have >= *slots {
            continue;
        }
        // Pool is score-ordered, so the first matches are the best candidates.
        let promote: Vec<usize> = (limit..hits.len())
            .filter(|&i| hits[i].record.kind.eq_ignore_ascii_case(kind))
            .take(*slots - have)
            .collect();
        if promote.is_empty() {
            continue;
        }
        // Victims, bottom-up: skip protected rows; a quota-kind row is
        // evictable only above its own class's guarantee. When the page
        // yields fewer victims than candidates the shortfall is dropped
        // rather than evicting a guaranteed or protected row.
        let mut victims: Vec<usize> = Vec::new();
        for i in (0..limit).rev() {
            if victims.len() == promote.len() {
                break;
            }
            if protected.contains(&hits[i].record.key) {
                continue;
            }
            let vkind = hits[i].record.kind.to_ascii_lowercase();
            match quota_slots(&vkind) {
                None => victims.push(i),
                Some(vslots) => {
                    if page_count.get(&vkind).copied().unwrap_or(0) > vslots {
                        victims.push(i);
                        *page_count.entry(vkind).or_insert(1) -= 1;
                    }
                }
            }
        }
        for (&v, &p) in victims.iter().zip(promote.iter()) {
            hits.swap(v, p);
            swapped = true;
        }
        *page_count.entry(kind.clone()).or_insert(0) += victims.len();
    }
    if swapped {
        sort_hits_score_desc(&mut hits[..limit]);
    }
}

/// Score-descending, NaN-tolerant ordering shared by every sort in the
/// memory_search pipeline (semantic blend, coactivation rerank, class quota).
/// Stable, so equal-score rows (e.g. a cosurfaced corrector carrying its
/// anchor's score) keep their relative order.
fn sort_hits_score_desc(hits: &mut [MemorySearchHit]) {
    hits.sort_by(|a, b| {
        b.score
            .partial_cmp(&a.score)
            .unwrap_or(std::cmp::Ordering::Equal)
    });
}

/// B1 — co-surface corrections next to the originals they correct.
///
/// For each result within the prospective top-`anchor_limit` that is the `to_key`
/// of an active `corrects` edge (`corrector --corrects--> result`), insert the
/// active corrector immediately after it, unless it is already on the page.
/// Topology-independent (unlike generic hybrid graph expansion, which buries the
/// single `corrects` edge under dense neighbours). The caller truncates back to
/// the page size, so a surfaced correction displaces the weakest tail result
/// rather than growing the page. Bounded: only the top-`anchor_limit` results are
/// probed (one `memory_neighbors` call each), and at most `MAX_CORRECTORS_PER_ANCHOR`
/// correctors are pulled per original (guards against a pathological fan-in of
/// `corrects` edges to one hot record). `excluded_kinds` preserves the
/// memory_search output filter contract even after gated co-surfacing. Reuses
/// existing store methods — no new SQL. Returns the keys of the correctors it
/// inserted so the class-quota stage can exempt them from displacement (an
/// evicted corrector would strand its stale anchor on the page).
async fn cosurface_corrections(
    store: &Arc<dyn StateStore>,
    hits: &mut Vec<MemorySearchHit>,
    anchor_limit: usize,
    excluded_kinds: &[String],
) -> HashSet<String> {
    let mut inserted: HashSet<String> = HashSet::new();
    if hits.is_empty() {
        return inserted;
    }
    const MAX_CORRECTORS_PER_ANCHOR: usize = 4;
    let mut present: HashSet<String> = hits.iter().map(|h| h.record.key.clone()).collect();
    let drained: Vec<MemorySearchHit> = std::mem::take(hits);
    let mut out: Vec<MemorySearchHit> = Vec::with_capacity(drained.len() + 2);
    for (i, h) in drained.into_iter().enumerate() {
        let anchor_key = h.record.key.clone();
        let anchor_score = h.score;
        out.push(h);
        // Only anchors that will survive the caller's top-`anchor_limit` truncate
        // are probed — bounds the neighbour lookups to the visible page.
        if i >= anchor_limit {
            continue;
        }
        let edges = match store.memory_neighbors(&anchor_key).await {
            Ok(e) => e,
            Err(_) => continue,
        };
        let mut added_here = 0usize;
        for e in edges {
            if added_here >= MAX_CORRECTORS_PER_ANCHOR {
                break;
            }
            // INBOUND `corrects` only: corrector --corrects--> anchor. A correction
            // anchor's OUTBOUND edge (from_key == anchor) is correctly skipped.
            if e.edge_type != "corrects" || e.to_key != anchor_key {
                continue;
            }
            if present.contains(&e.from_key) {
                continue;
            }
            if let Ok(Some(rec)) = store.memory_get(&e.from_key).await {
                if rec.status == "active" && !excluded_kinds.iter().any(|k| k == &rec.kind) {
                    present.insert(e.from_key.clone());
                    inserted.insert(e.from_key.clone());
                    out.push(MemorySearchHit {
                        score: anchor_score,
                        record: rec,
                        cosine: None,
                    });
                    added_here += 1;
                }
            }
        }
    }
    *hits = out;
    inserted
}

pub struct MemoryListTool {
    hub: Hub,
}
impl MemoryListTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemoryListTool {
    fn name(&self) -> &'static str {
        "memory_list"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "List memories, optionally filtered by `kind`, sorted by 'recent' \
                 (default, last_accessed_at desc), 'frequent' (access_count desc), or \
                 'newest' (created_at desc). Excludes archived/superseded rows. Long \
                 contents are truncated to `content_max_chars` (default 280) so an \
                 overview list never blows past the MCP token cap; use `memory_get` for \
                 full bodies, or set `content_max_chars=0` to disable truncation. Use at \
                 session start with kind='lesson' to surface what previous-you learned."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "kind":  { "type": "string", "description": "Optional kind filter." },
                    "sort":  { "type": "string", "enum": ["recent","frequent","newest"], "default": "recent" },
                    "limit": { "type": "integer", "minimum": 1, "maximum": 200, "default": 8 },
                    "content_max_chars": {
                        "type": "integer", "minimum": 0, "default": 280,
                        "description": "Per-row content truncation (chars, not bytes — CJK safe). 0 disables."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let kind = args
            .get("kind")
            .and_then(|v| v.as_str())
            .map(|s| s.to_string());
        let sort = match args
            .get("sort")
            .and_then(|v| v.as_str())
            .unwrap_or("recent")
        {
            "frequent" => MemoryListSort::Frequent,
            "newest" => MemoryListSort::Newest,
            _ => MemoryListSort::Recent,
        };
        let limit = args
            .get("limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(8)
            .min(200) as u32;
        let max_chars = args
            .get("content_max_chars")
            .and_then(|v| v.as_u64())
            .map(|n| n as usize)
            .unwrap_or(280);
        let rows = store.list_memories(kind.as_deref(), sort, limit).await?;
        let mut json_rows = Value::Array(
            rows.iter()
                .map(memory_record_value_with_continuity)
                .collect(),
        );
        if max_chars > 0 {
            if let Some(arr) = json_rows.as_array_mut() {
                for item in arr {
                    if let Some(obj) = item.as_object_mut() {
                        let owned_content = obj
                            .get("content")
                            .and_then(|v| v.as_str())
                            .map(|s| s.to_string());
                        if let Some(content) = owned_content {
                            let total = content.chars().count();
                            if total > max_chars {
                                let head: String = content.chars().take(max_chars).collect();
                                obj.insert(
                                    "content".to_string(),
                                    Value::String(format!(
                                        "{head}…(truncated; total {total} chars — use memory_get for full)"
                                    )),
                                );
                            }
                        }
                    }
                }
            }
        }
        Ok(ToolResult::json_text(&json_rows))
    }
}

pub struct MemoryDeleteTool {
    hub: Hub,
}
impl MemoryDeleteTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemoryDeleteTool {
    fn name(&self) -> &'static str {
        "memory_delete"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Delete a memory by key. Returns `{deleted: true}` if a row was removed."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": { "key": { "type": "string" } },
                "required": ["key"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let key = match args.get("key").and_then(|v| v.as_str()) {
            Some(s) => s.to_string(),
            None => return Ok(ToolResult::error("missing 'key'")),
        };
        let removed = store.memory_delete(&key).await?;
        if removed {
            let cache = self.hub.memory_embed_cache.clone();
            let del_key = key.clone();
            tokio::spawn(async move {
                let mut guard = cache.lock().await;
                if let Some(ref mut cached) = *guard {
                    cached.retain(|(r, _)| r.key != del_key);
                }
            });
        }
        Ok(ToolResult::json_text(&json!({ "deleted": removed })))
    }
}

const WORK_MEMORY_KIND: &str = "work_memory";
const WORK_MEMORY_DEFAULT_SLOT: &str = "active";
const WORK_MEMORY_MAX_CONTENT_CHARS: usize = 12_000;
const WORK_MEMORY_PRECOMPACT_CHARS: usize = 6_000;
const WORK_MEMORY_SECONDS_PER_DAY: i64 = 86_400;
/// Upper bound on work_memory rows scanned (most-recent first, across ALL
/// projects' scopes) for cross-node fan-in in the alias-aware `list`. The scan
/// is then filtered to alias-compatible scopes. NOTE: an alias-compatible
/// sibling lane older than the Nth most-recent work_memory row store-wide is
/// silently NOT surfaced — acceptable because work_memory is a recent-sorted,
/// TTL-bounded scratchpad, but raise this (or scope the broad fetch) if the
/// live work_memory population ever approaches this bound.
const WORK_MEMORY_ALIAS_FANIN_SCAN: u32 = 500;

fn unix_now_secs() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs() as i64
}

fn work_memory_declared_status(args: &Value, content: &str) -> String {
    if let Some(status) = args
        .get("status")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|status| !status.is_empty())
    {
        return status.to_string();
    }
    content
        .lines()
        .find_map(|line| {
            let (name, value) = line.split_once(':')?;
            name.trim()
                .eq_ignore_ascii_case("status")
                .then(|| value.trim().to_string())
        })
        .filter(|status| !status.is_empty())
        .unwrap_or_else(|| "active".to_string())
}

fn work_memory_status_is_terminal(status: &str) -> bool {
    let head = status
        .trim()
        .to_ascii_lowercase()
        .split_whitespace()
        .next()
        .unwrap_or_default()
        .trim_matches(|ch: char| matches!(ch, '.' | ',' | ':' | ';'))
        .to_string();
    matches!(
        head.as_str(),
        "complete" | "completed" | "resolved" | "done" | "closed" | "finished" | "superseded"
    ) || head.starts_with("completed_")
        || head.starts_with("completed-")
}

fn work_memory_expires_at(record: &MemoryRecord) -> Option<i64> {
    ab_store::memory_record_ttl_expires_at(record)
}

fn work_memory_is_live(record: &MemoryRecord, now: i64) -> bool {
    record.status == "active"
        && work_memory_expires_at(record)
            .map(|expires_at| expires_at > now)
            .unwrap_or(true)
}

/// Kind-agnostic TTL liveness for the retrieval path. Any row carrying a
/// `ttl:<N>d` tag is considered expired once `updated_at.max(created_at) + N
/// days` passes; a row WITHOUT such a tag is always live (returns true). The
/// TTL parser is shared with `work_memory_expires_at`, so work_memory keeps its
/// existing behavior; this only extends the same rule to other tagged rows
/// (today: `*_apply` rollback-map audit rows). Blast radius = ttl-tagged rows
/// only — untagged rows are byte-identical.
fn record_ttl_is_live(record: &MemoryRecord, now: i64) -> bool {
    ab_store::memory_record_ttl_is_live_at(record, now)
}

fn stable_fnv1a_hex(input: &str) -> String {
    let mut hash: u64 = 0xcbf29ce484222325;
    for b in input.as_bytes() {
        hash ^= *b as u64;
        hash = hash.wrapping_mul(0x100000001b3);
    }
    format!("{hash:016x}")
}

fn sanitize_work_memory_component(value: &str, fallback: &str, max_chars: usize) -> String {
    let mut out = String::new();
    let mut last_dash = false;
    for ch in value.trim().chars() {
        let mapped = if ch.is_ascii_alphanumeric() || ch == '_' || ch == '-' {
            Some(ch.to_ascii_lowercase())
        } else if ch.is_whitespace() || matches!(ch, '/' | ':' | '.' | '@') {
            Some('-')
        } else {
            None
        };
        if let Some(ch) = mapped {
            if ch == '-' {
                if !last_dash && !out.is_empty() {
                    out.push(ch);
                    last_dash = true;
                }
            } else {
                out.push(ch);
                last_dash = false;
            }
        }
        if out.chars().count() >= max_chars {
            break;
        }
    }
    while out.ends_with('-') {
        out.pop();
    }
    if out.is_empty() {
        fallback.to_string()
    } else {
        out
    }
}

fn work_memory_cwd(args: &Value) -> String {
    args.get("cwd")
        .and_then(|v| v.as_str())
        .filter(|s| !s.trim().is_empty())
        .map(|s| s.trim().to_string())
        .or_else(|| {
            std::env::current_dir()
                .ok()
                .map(|p| p.display().to_string())
        })
        .unwrap_or_else(|| "/".to_string())
}

fn work_memory_scope(cwd: &str) -> String {
    format!("project:{cwd}")
}

fn work_memory_key(cwd: &str, session_id: Option<&str>, slot: &str) -> String {
    let scope_hash = stable_fnv1a_hex(cwd);
    let slot = sanitize_work_memory_component(slot, WORK_MEMORY_DEFAULT_SLOT, 48);
    let owner = session_id
        .map(|s| sanitize_work_memory_component(s, "session", 48))
        .unwrap_or_else(|| "shared".to_string());
    format!("work_memory_{}_{}_{}", &scope_hash[..12], owner, slot)
}

/// Resolve the effective work-memory key: an explicit non-empty `key` arg
/// wins; otherwise fall back to the cwd/session_id/slot-derived slot key.
/// Shared by the save/get/clear arms so their addressing cannot drift.
fn work_memory_resolved_key(
    args: &Value,
    cwd: &str,
    session_id: Option<&str>,
    slot: &str,
) -> String {
    args.get("key")
        .and_then(|v| v.as_str())
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(str::to_string)
        .unwrap_or_else(|| work_memory_key(cwd, session_id, slot))
}

/// Cross-node fan-in merge for `work_memory list`.
///
/// `same_node` is the exact-scope result (today's behaviour); `broad` is all
/// work_memory rows across every scope. Returns `same_node` PLUS any `broad` row
/// whose scope is alias-compatible with `requested_scope` — using the same
/// read-time canonicalization `memory_search` uses (`AGENT_BRIDGE_PROJECT_SCOPE_ALIASES`)
/// — that is not already present, sorted most-recently-accessed first and capped
/// to `limit`. This surfaces a sibling node's lanes for the SAME project (e.g.
/// aio2's `project:/Data/...` path) which otherwise sync into state.db but stay
/// invisible to an exact-scope list. Pure (no IO) so the cross-node visibility
/// rule is unit-testable. Keys are never rewritten here, so a cross-node lane
/// surfaces as its own distinct row — read-converge, never write-overwrite.
fn merge_alias_compatible_work_memory(
    mut same_node: Vec<MemoryRecord>,
    broad: Vec<MemoryRecord>,
    requested_scope: &str,
    aliases: &str,
    limit: usize,
) -> Vec<MemoryRecord> {
    let seen: std::collections::HashSet<String> = same_node.iter().map(|r| r.key.clone()).collect();
    let mut extra: Vec<MemoryRecord> = broad
        .into_iter()
        .filter(|r| !seen.contains(&r.key))
        .filter(|r| {
            project_scopes_read_time_compatible_with_aliases(
                r.scope.as_deref().unwrap_or(""),
                requested_scope,
                Some(aliases),
            )
        })
        .collect();
    // PIN the same-node lanes (already recent-sorted and capped at `limit` by the
    // SQL): an agent must never lose sight of its OWN current lane. Fill only the
    // REMAINING budget with the most-recently-accessed cross-node lanes. A naive
    // "merge-all then truncate" would let newer sibling lanes evict the local lane
    // entirely under truncate(limit).
    extra.sort_by(|a, b| b.last_accessed_at.cmp(&a.last_accessed_at));
    let room = limit.saturating_sub(same_node.len());
    same_node.extend(extra.into_iter().take(room));
    same_node
}

/// Cross-node "peer" work_memory lanes — the wake delta. Returns lanes that are
/// alias-compatible with `requested_scope` (same logical project) but written
/// under a DIFFERENT scope (i.e. a sibling NODE's path, e.g. aio2's
/// `project:/Data/...` for a Mac session's `project:/Users/...`), with
/// `updated_at > since_ts`, most-recent first. Same-node lanes (scope ==
/// requested_scope) are excluded — those are the agent's own, surfaced by `list`.
///
/// Reliable across nodes because `updated_at` survives state.db sync unchanged
/// (sync's stabilise_sync_metadata zeroes last_accessed_at / access_count /
/// importance but NOT updated_at). Pull/turn-driven by design: it reads lanes
/// already synced into the local store, so a peer's update surfaces once sync has
/// carried it over — there is no live push (that is the sibling node's lane).
fn cross_node_peer_lanes(
    requested_scope: &str,
    broad: Vec<MemoryRecord>,
    aliases: &str,
    since_ts: i64,
    limit: usize,
) -> Vec<MemoryRecord> {
    let now = unix_now_secs();
    let mut peers: Vec<MemoryRecord> = broad
        .into_iter()
        .filter(|r| work_memory_is_live(r, now))
        .filter(|r| r.updated_at > since_ts)
        // Exclude this session's own scope AND same-node ancestor/descendant
        // scopes (e.g. the parent `project:/Users/.../Projects` of this
        // `…/Projects/agent-bridge`). A TRUE cross-node peer has a different root
        // path (aio2 `/Data/…` vs Mac `/Users/…`), not a prefix relation — those
        // survive; same-node path relatives are the agent's own neighborhood.
        .filter(|r| {
            !scope_is_path_prefix_related(r.scope.as_deref().unwrap_or(""), requested_scope)
        })
        // …but still the SAME logical project (alias-compatible).
        .filter(|r| {
            project_scopes_read_time_compatible_with_aliases(
                r.scope.as_deref().unwrap_or(""),
                requested_scope,
                Some(aliases),
            )
        })
        .collect();
    peers.sort_by(|a, b| b.updated_at.cmp(&a.updated_at));
    peers.truncate(limit);
    peers
}

/// True if `a` and `b` are the same scope or one is a path-segment prefix of the
/// other (same-node ancestor/descendant), e.g.
/// `project:/Users/x/Projects` vs `project:/Users/x/Projects/agent-bridge`.
/// Segment-aware so `…/Projects` does not match `…/Projects-foo`.
fn scope_is_path_prefix_related(a: &str, b: &str) -> bool {
    fn is_segment_prefix(short: &str, long: &str) -> bool {
        long == short
            || (long.starts_with(short) && long.as_bytes().get(short.len()) == Some(&b'/'))
    }
    is_segment_prefix(a, b) || is_segment_prefix(b, a)
}

fn json_string_array(args: &Value, key: &str) -> Vec<String> {
    args.get(key)
        .and_then(|v| v.as_array())
        .map(|a| {
            a.iter()
                .filter_map(|x| x.as_str().map(str::trim))
                .filter(|s| !s.is_empty())
                .map(str::to_string)
                .collect()
        })
        .unwrap_or_default()
}

fn tail_chars(s: &str, max_chars: usize) -> (String, bool, usize) {
    let total = s.chars().count();
    if max_chars == 0 || total <= max_chars {
        (s.to_string(), false, total)
    } else {
        let start = total.saturating_sub(max_chars);
        let tail: String = s.chars().skip(start).collect();
        (
            format!("[trimmed earlier context; total {total} chars]\n{tail}"),
            true,
            total,
        )
    }
}

fn build_work_memory_content(
    args: &Value,
    cwd: &str,
    session_id: Option<&str>,
    slot: &str,
) -> std::result::Result<(String, bool, usize), String> {
    if let Some(content) = args
        .get("content")
        .and_then(|v| v.as_str())
        .map(str::trim)
        .filter(|s| !s.is_empty())
    {
        let (content, truncated, total_chars) =
            truncate_chars(content, WORK_MEMORY_MAX_CONTENT_CHARS);
        return Ok((content, truncated, total_chars));
    }

    let title = args
        .get("title")
        .and_then(|v| v.as_str())
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .unwrap_or("Active Work Memory");
    let summary = args
        .get("summary")
        .and_then(|v| v.as_str())
        .map(str::trim)
        .filter(|s| !s.is_empty());
    let next_step = args
        .get("next_step")
        .and_then(|v| v.as_str())
        .map(str::trim)
        .filter(|s| !s.is_empty());
    let evidence = args
        .get("evidence")
        .and_then(|v| v.as_str())
        .map(str::trim)
        .filter(|s| !s.is_empty());
    let status = args
        .get("status")
        .and_then(|v| v.as_str())
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .unwrap_or("active");
    let files = json_string_array(args, "files");

    if summary.is_none() && next_step.is_none() && evidence.is_none() && files.is_empty() {
        return Err(
            "save requires either content or at least one of summary/next_step/evidence/files"
                .to_string(),
        );
    }

    let mut lines = vec![
        format!("# {title}"),
        format!("cwd: {cwd}"),
        format!("slot: {slot}"),
        format!("status: {status}"),
        format!("updated_at: {}", unix_now_secs()),
    ];
    if let Some(session_id) = session_id {
        lines.push(format!("session_id: {session_id}"));
    }
    if let Some(summary) = summary {
        lines.extend([
            "".to_string(),
            "## Summary".to_string(),
            summary.to_string(),
        ]);
    }
    if let Some(next_step) = next_step {
        lines.extend([
            "".to_string(),
            "## Next Step".to_string(),
            next_step.to_string(),
        ]);
    }
    if let Some(evidence) = evidence {
        lines.extend([
            "".to_string(),
            "## Evidence".to_string(),
            evidence.to_string(),
        ]);
    }
    if !files.is_empty() {
        lines.push(String::new());
        lines.push("## Files".to_string());
        lines.extend(files.iter().map(|f| format!("- {f}")));
    }
    let content = lines.join("\n");
    let (content, truncated, total_chars) = truncate_chars(&content, WORK_MEMORY_MAX_CONTENT_CHARS);
    Ok((content, truncated, total_chars))
}

fn build_precompact_work_memory_content(
    conversation_text: &str,
    cwd: &str,
    session_id: Option<&str>,
) -> (String, bool, usize) {
    let (excerpt, truncated, total_chars) =
        tail_chars(conversation_text, WORK_MEMORY_PRECOMPACT_CHARS);
    let mut lines = vec![
        "# PreCompact Work Memory".to_string(),
        format!("cwd: {cwd}"),
        "slot: precompact".to_string(),
        "source: session_lifecycle_step(precompact)".to_string(),
        format!("updated_at: {}", unix_now_secs()),
    ];
    if let Some(session_id) = session_id {
        lines.push(format!("session_id: {session_id}"));
    }
    lines.extend([
        String::new(),
        "## Recent Context Excerpt".to_string(),
        excerpt,
    ]);
    (lines.join("\n"), truncated, total_chars)
}

fn format_work_memory_block(
    rows: &[MemoryRecord],
    is_compact: bool,
    snippet_len: usize,
) -> Option<Vec<String>> {
    let now = unix_now_secs();
    let rows: Vec<MemoryRecord> = rows
        .iter()
        .filter(|r| work_memory_is_live(r, now))
        .take(4)
        .cloned()
        .collect();
    if rows.is_empty() {
        return None;
    }
    let mut out = vec![
        if is_compact {
            "=== Active Work Memory ===".to_string()
        } else {
            "=== Active Work Memory (short-lived scratchpad) ===".to_string()
        },
        String::new(),
    ];
    out.extend(
        rows.iter()
            .map(|row| format_work_memory_resume_row(row, snippet_len)),
    );
    out.push(String::new());
    Some(out)
}

/// Keep the automatic bootstrap scratchpad local to the exact project cwd.
/// `list_memories_in_scope` intentionally includes ancestor scopes for durable
/// memory recall, but a short-lived work lane from `/Data` or `…/Projects`
/// describes a different task surface and must not silently resume inside a
/// child repository. Cross-node alias lanes have their own explicit peer block.
fn exact_scope_work_memory_rows(rows: Vec<MemoryRecord>, cwd: &str) -> Vec<MemoryRecord> {
    let requested = work_memory_scope(cwd.trim_end_matches('/'));
    rows.into_iter()
        .filter(|row| {
            row.scope
                .as_deref()
                .map(|scope| scope.trim_end_matches('/') == requested)
                .unwrap_or(false)
        })
        .collect()
}

/// Select the bounded automatic bootstrap view without changing explicit
/// work-memory reads. Structured lanes remain independently useful, but old
/// per-session precompact snapshots describe superseded interruption points;
/// only the newest live snapshot for this exact project is resumed.
fn bootstrap_work_memory_rows(
    rows: Vec<MemoryRecord>,
    cwd: &str,
    now: i64,
) -> Vec<MemoryRecord> {
    let rows: Vec<MemoryRecord> = exact_scope_work_memory_rows(rows, cwd)
        .into_iter()
        .filter(|row| work_memory_is_live(row, now))
        .collect();
    let newest_precompact_key = rows
        .iter()
        .filter(|row| row.tags.iter().any(|tag| tag == "source:precompact"))
        .max_by_key(|row| (row.updated_at.max(row.created_at), row.key.as_str()))
        .map(|row| row.key.clone());

    rows.into_iter()
        .filter(|row| {
            !row.tags.iter().any(|tag| tag == "source:precompact")
                || newest_precompact_key.as_deref() == Some(row.key.as_str())
        })
        .collect()
}

/// Render the part of a scratchpad that is useful after interruption.
/// Generic bootstrap rows show a content prefix, but work-memory prefixes are
/// mostly metadata (`cwd`, slot, timestamp). A precompact snapshot stores its
/// newest conversation at the tail, while structured slots carry an explicit
/// Next Step or Summary section. Prefer those resume cues and keep the key as
/// the drill-down handle for the full record.
fn format_work_memory_resume_row(record: &MemoryRecord, snippet_len: usize) -> String {
    fn section<'a>(content: &'a str, heading: &str) -> Option<&'a str> {
        let body = content.split_once(heading)?.1.trim_start_matches(['\r', '\n']);
        let end = body
            .find("\n## ")
            .or_else(|| body.find("\r\n## "))
            .unwrap_or(body.len());
        let value = body[..end].trim();
        (!value.is_empty()).then_some(value)
    }

    let precompact = record.tags.iter().any(|tag| tag == "source:precompact");
    let cue = if precompact {
        tail_chars(&record.content, snippet_len).0
    } else {
        let next = section(&record.content, "## Next Step");
        let summary = section(&record.content, "## Summary");
        let combined = match (next, summary) {
            (Some(next), Some(summary)) => format!("Next: {next} | Summary: {summary}"),
            (Some(next), None) => format!("Next: {next}"),
            (None, Some(summary)) => format!("Summary: {summary}"),
            (None, None) => record.content.clone(),
        };
        truncate_chars(&combined, snippet_len).0
    };
    let cue = cue.split_whitespace().collect::<Vec<_>>().join(" ");
    let truncated = cue.chars().count() < record.content.chars().count();
    format!(
        "[work_memory] {}: {}{}",
        record.key,
        cue,
        if truncated { "…" } else { "" }
    )
}

/// Format the cross-node peer wake block for session_bootstrap. `rows` are
/// already filtered to cross-node peer lanes (see [`cross_node_peer_lanes`]) and
/// recency-sorted. Shows the sibling node's scope + lane key + a short snippet so
/// a starting session perceives what a peer node changed for this project. None
/// when there are no peer lanes (clean / single-node).
fn format_cross_node_peer_block(rows: &[MemoryRecord], is_compact: bool) -> Option<Vec<String>> {
    if rows.is_empty() {
        return None;
    }
    let mut out = vec![
        if is_compact {
            "=== Cross-node peer work memory ===".to_string()
        } else {
            "=== Cross-node peer work memory (a sibling node updated these lanes for this project) ==="
                .to_string()
        },
        String::new(),
    ];
    for r in rows.iter().take(3) {
        let scope = r.scope.as_deref().unwrap_or("?");
        let (snippet, _, _) = truncate_chars(&r.content, 90);
        let snippet = snippet.replace('\n', " ");
        out.push(format!("[{scope}] {}: {snippet}…", r.key));
    }
    out.push(String::new());
    Some(out)
}

async fn save_precompact_work_memory_snapshot(
    hub: &Hub,
    cwd: &str,
    session_id: Option<&str>,
    conversation_text: &str,
) -> Value {
    let store = match &hub.store {
        Some(s) => s.clone(),
        None => return json!({ "saved": false, "reason": "no store configured" }),
    };
    let (content, truncated, source_chars) =
        build_precompact_work_memory_content(conversation_text, cwd, session_id);
    let key = work_memory_key(cwd, session_id, "precompact");
    let scope = work_memory_scope(cwd);
    let mut tags = vec![
        "work_memory".to_string(),
        "source:precompact".to_string(),
        "ttl:14d".to_string(),
    ];
    if let Some(session_id) = session_id {
        tags.push(format!("session:{session_id}"));
    }
    let mem = MemoryRecord {
        key: key.clone(),
        kind: WORK_MEMORY_KIND.to_string(),
        content,
        tags,
        related_keys: vec![],
        scope: Some(scope.clone()),
        created_at: 0,
        updated_at: 0,
        last_accessed_at: 0,
        access_count: 0,
        importance: 0.62,
        status: "active".to_string(),
        trigger_pattern: None,
        superseded_by: None,
    };
    match store.memory_save(&mem).await {
        Ok(()) => json!({
            "saved": true,
            "key": key,
            "scope": scope,
            "source_chars": source_chars,
            "truncated": truncated,
        }),
        Err(e) => json!({ "saved": false, "error": e.to_string() }),
    }
}

/// Read-only contract compiler for reviewing a bounded agent attempt before
/// any mutating orchestration tool is called.
pub struct AgentTaskContractPreviewTool;

impl AgentTaskContractPreviewTool {
    pub fn new() -> Self {
        Self
    }
}

impl Default for AgentTaskContractPreviewTool {
    fn default() -> Self {
        Self::new()
    }
}

#[async_trait]
impl McpTool for AgentTaskContractPreviewTool {
    fn name(&self) -> &'static str {
        "agent_task_contract_preview"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Compile and validate a deterministic, read-only agent task contract preview. The tool never spawns or steers agents, never writes durable memory or work_memory, never promotes canon, and never enables runtime behavior. A blocked preview has typed violations and an empty compiled_instruction."
                .into(),
            input_schema: json!({
                "type": "object",
                "required": ["contract"],
                "properties": {
                    "contract": {
                        "type": "object",
                        "additionalProperties": false,
                        "required": [
                            "schema_version",
                            "contract_id",
                            "revision",
                            "objective",
                            "this_attempt_only",
                            "acceptance_criteria",
                            "authority_boundary",
                            "attempt_no",
                            "attempt_budget"
                        ],
                        "properties": {
                            "schema_version": {
                                "type": "string",
                                "const": "agent_bridge.agent_task_contract.v0"
                            },
                            "contract_id": { "type": "string", "minLength": 1 },
                            "revision": { "type": "integer", "minimum": 1 },
                            "objective": { "type": "string", "minLength": 1 },
                            "parent_evidence_refs": {
                                "type": "array",
                                "default": [],
                                "items": {
                                    "type": "object",
                                    "additionalProperties": false,
                                    "required": ["reference", "verdict", "authority_boundary"],
                                    "properties": {
                                        "reference": { "type": "string", "minLength": 1 },
                                        "verdict": {
                                            "type": "string",
                                            "enum": ["accepted", "accepted_with_deviation", "rejected"]
                                        },
                                        "authority_boundary": {
                                            "type": "string",
                                            "enum": ["read_only", "project_write", "external_write", "runtime_enablement"]
                                        }
                                    }
                                }
                            },
                            "this_attempt_only": {
                                "type": "array",
                                "items": { "type": "string", "minLength": 1 },
                                "minItems": 1
                            },
                            "reserved_actions": {
                                "type": "array",
                                "items": { "type": "string" },
                                "default": []
                            },
                            "continuity_locks": {
                                "type": "object",
                                "additionalProperties": { "type": "string" },
                                "default": {}
                            },
                            "allowed_changes": {
                                "type": "array",
                                "items": { "type": "string" },
                                "default": []
                            },
                            "acceptance_criteria": {
                                "type": "array",
                                "items": { "type": "string", "minLength": 1 },
                                "minItems": 1
                            },
                            "authority_boundary": {
                                "type": "string",
                                "enum": ["read_only", "project_write", "external_write", "runtime_enablement"]
                            },
                            "attempt_no": { "type": "integer", "minimum": 1 },
                            "attempt_budget": { "type": "integer", "minimum": 1 },
                            "changed_variable": { "type": ["string", "null"] },
                            "planned_state": {
                                "type": "object",
                                "additionalProperties": { "type": "string" },
                                "default": {}
                            },
                            "observed_state": {
                                "type": "object",
                                "additionalProperties": { "type": "string" },
                                "default": {}
                            }
                        }
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let Some(contract_value) = args.get("contract") else {
            return Ok(ToolResult::error("missing required object: contract"));
        };
        let contract = match serde_json::from_value::<AgentTaskContract>(contract_value.clone()) {
            Ok(contract) => contract,
            Err(error) => {
                return Ok(ToolResult::error(format!(
                    "invalid agent task contract: {error}"
                )))
            }
        };
        let preview = preview_agent_task_contract(contract);
        Ok(ToolResult::json_text(&json!(preview)))
    }
}

pub struct WorkMemoryTool {
    hub: Hub,
}
impl WorkMemoryTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for WorkMemoryTool {
    fn name(&self) -> &'static str {
        "work_memory"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Manage a short-lived project/session scratchpad outside the model \
                 context. Use it to preserve active task state across context compaction; \
                 durable lessons and decisions still belong in memory_save."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "op": {
                        "type": "string",
                        "enum": ["save", "list", "get", "clear", "peers"],
                        "default": "list",
                        "description": "save overwrites a project/session slot; list returns recent work memories (with cross-node fan-in); get reads one key (omitted key = the cwd/session_id/slot-derived slot key, same addressing as save); clear deletes one slot/key; peers returns ONLY cross-node sibling lanes (a DIFFERENT node working this same project, surfaced via scope-alias) changed since `since_ts` — the cross-node wake delta: 'what did my peers change since I last looked'."
                    },
                    "since_ts": { "type": "integer", "description": "[peers] Only return cross-node lanes with updated_at > this unix-seconds cursor. Pass back the response's next_cursor to poll incrementally. Default 0 = all peer lanes." },
                    "cwd": { "type": "string", "description": "Project path for scoping. Defaults to current working directory." },
                    "session_id": { "type": "string", "description": "Optional session namespace. Omit for a shared project slot." },
                    "slot": { "type": "string", "default": "active", "description": "Short slot name, e.g. active, release, precompact." },
                    "key": { "type": "string", "description": "Explicit key for save/get/clear. If omitted, cwd/session_id/slot derives the key (all three ops share the same slot addressing)." },
                    "title": { "type": "string" },
                    "summary": { "type": "string" },
                    "next_step": { "type": "string" },
                    "evidence": { "type": "string" },
                    "files": { "type": "array", "items": { "type": "string" }, "default": [] },
                    "content": { "type": "string", "description": "Optional full Markdown content. Capped at 12000 chars." },
                    "status": { "type": "string", "default": "active", "description": "Lifecycle marker. Terminal values (complete/completed/resolved/done/closed/finished/superseded, including completed_* variants) clear the addressed short-lived slot instead of saving another active row. WAIT/blocked values remain visible." },
                    "tags": { "type": "array", "items": { "type": "string" }, "default": [] },
                    "ttl_days": { "type": "integer", "minimum": 1, "maximum": 90, "default": 14 },
                    "limit": { "type": "integer", "minimum": 1, "maximum": 50, "default": 8 },
                    "compact": { "type": "boolean", "description": "When listing, return compact row summaries. Defaults true for Codex compact profiles." }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let op = args
            .get("op")
            .and_then(|v| v.as_str())
            .unwrap_or("list")
            .trim()
            .to_lowercase();
        let cwd = work_memory_cwd(&args);
        let session_id = args
            .get("session_id")
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty());
        let slot = args
            .get("slot")
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .unwrap_or(WORK_MEMORY_DEFAULT_SLOT);

        match op.as_str() {
            "save" => {
                let (content, truncated, total_chars) =
                    match build_work_memory_content(&args, &cwd, session_id, slot) {
                        Ok(v) => v,
                        Err(e) => return Ok(ToolResult::error(e)),
                    };
                let key = work_memory_resolved_key(&args, &cwd, session_id, slot);
                let scope = work_memory_scope(&cwd);
                let declared_status = work_memory_declared_status(&args, &content);
                if work_memory_status_is_terminal(&declared_status) {
                    let deleted = store.memory_delete(&key).await?;
                    return Ok(ToolResult::json_text(&json!({
                        "saved": false,
                        "cleared": true,
                        "deleted": deleted,
                        "key": key,
                        "scope": scope,
                        "slot": slot,
                        "declared_status": declared_status,
                        "source_chars": total_chars,
                        "truncated": truncated,
                    })));
                }
                let ttl_days = args
                    .get("ttl_days")
                    .and_then(|v| v.as_u64())
                    .unwrap_or(14)
                    .clamp(1, 90);
                let mut tags = vec![
                    "work_memory".to_string(),
                    format!(
                        "slot:{}",
                        sanitize_work_memory_component(slot, WORK_MEMORY_DEFAULT_SLOT, 48)
                    ),
                    format!("ttl:{ttl_days}d"),
                ];
                if let Some(session_id) = session_id {
                    tags.push(format!("session:{session_id}"));
                }
                tags.extend(json_string_array(&args, "tags"));
                tags.sort();
                tags.dedup();
                let mem = MemoryRecord {
                    key: key.clone(),
                    kind: WORK_MEMORY_KIND.to_string(),
                    content,
                    tags,
                    related_keys: vec![],
                    scope: Some(scope.clone()),
                    created_at: 0,
                    updated_at: 0,
                    last_accessed_at: 0,
                    access_count: 0,
                    importance: 0.65,
                    status: "active".to_string(),
                    trigger_pattern: None,
                    superseded_by: None,
                };
                store.memory_save(&mem).await?;
                Ok(ToolResult::json_text(&json!({
                    "saved": true,
                    "key": key,
                    "scope": scope,
                    "slot": slot,
                    "declared_status": declared_status,
                    "content_chars": mem.content.chars().count(),
                    "source_chars": total_chars,
                    "truncated": truncated,
                })))
            }
            "list" => {
                let limit = args
                    .get("limit")
                    .and_then(|v| v.as_u64())
                    .unwrap_or(8)
                    .clamp(1, 50) as u32;
                let compact = args
                    .get("compact")
                    .and_then(|v| v.as_bool())
                    .unwrap_or_else(compact_mcp_output_default);
                let mut rows = store
                    .list_memories_in_scope(
                        &cwd,
                        Some(WORK_MEMORY_KIND),
                        MemoryListSort::Recent,
                        limit,
                    )
                    .await?;
                let now = unix_now_secs();
                rows.retain(|row| work_memory_is_live(row, now));
                // Cross-node fan-in: work_memory list is otherwise exact-scope,
                // so lanes written under an alias-compatible scope on ANOTHER
                // node (e.g. aio2's project:/Data/... path for this same
                // project) stay invisible even though they sync into state.db.
                // When a scope-alias registry is configured, widen the READ via
                // the same canonicalization memory_search uses so cross-node
                // lanes surface in the fan-in. Key derivation is untouched, so
                // cross-node lanes remain DISTINCT rows (read-converge, never
                // write-overwrite).
                if let Some(aliases) = std::env::var(PROJECT_SCOPE_ALIASES_ENV)
                    .ok()
                    .filter(|s| !s.trim().is_empty())
                {
                    let mut broad = store
                        .list_memories(
                            Some(WORK_MEMORY_KIND),
                            MemoryListSort::Recent,
                            WORK_MEMORY_ALIAS_FANIN_SCAN,
                        )
                        .await?;
                    broad.retain(|row| work_memory_is_live(row, now));
                    rows = merge_alias_compatible_work_memory(
                        rows,
                        broad,
                        &work_memory_scope(&cwd),
                        &aliases,
                        limit as usize,
                    );
                }
                if compact {
                    let rows: Vec<Value> = rows
                        .into_iter()
                        .map(|r| {
                            let (snippet, truncated, total_chars) = truncate_chars(&r.content, 240);
                            json!({
                                "key": r.key,
                                "scope": r.scope,
                                "updated_at": r.updated_at,
                                "expires_at": work_memory_expires_at(&r),
                                "tags": r.tags,
                                "snippet": snippet,
                                "truncated": truncated,
                                "content_chars": total_chars,
                            })
                        })
                        .collect();
                    Ok(ToolResult::json_text(&json!({
                        "cwd": cwd,
                        "kind": WORK_MEMORY_KIND,
                        "rows": rows,
                    })))
                } else {
                    Ok(ToolResult::json_text(
                        &serde_json::to_value(rows).unwrap_or(Value::Null),
                    ))
                }
            }
            "get" => {
                // Symmetric with save/clear: an omitted key falls back to the
                // cwd/session_id/slot-derived slot key instead of erroring.
                let key = work_memory_resolved_key(&args, &cwd, session_id, slot);
                match store.memory_get(&key).await? {
                    // Match the list/bootstrap surface (both filter
                    // status=='active'): retired scratchpad rows are not
                    // readable, so get cannot resurrect an archived or
                    // superseded slot that list no longer shows.
                    Some(row)
                        if row.kind == WORK_MEMORY_KIND
                            && work_memory_is_live(&row, unix_now_secs()) =>
                    {
                        Ok(ToolResult::json_text(
                            &serde_json::to_value(row).unwrap_or(Value::Null),
                        ))
                    }
                    Some(row) if row.kind == WORK_MEMORY_KIND => {
                        Ok(ToolResult::error("work memory key not found"))
                    }
                    Some(_) => Ok(ToolResult::error("key exists but is not work_memory")),
                    None => Ok(ToolResult::error("work memory key not found")),
                }
            }
            "clear" => {
                let key = work_memory_resolved_key(&args, &cwd, session_id, slot);
                let deleted = store.memory_delete(&key).await?;
                Ok(ToolResult::json_text(
                    &json!({ "deleted": deleted, "key": key }),
                ))
            }
            "peers" => {
                // Cross-node wake delta: which sibling-NODE lanes for this project
                // changed since the caller's cursor. Requires the scope-alias
                // registry (no aliases = no cross-node concept = empty).
                let since_ts = args.get("since_ts").and_then(|v| v.as_i64()).unwrap_or(0);
                let limit = args
                    .get("limit")
                    .and_then(|v| v.as_u64())
                    .unwrap_or(8)
                    .clamp(1, 50) as usize;
                let peers = match std::env::var(PROJECT_SCOPE_ALIASES_ENV)
                    .ok()
                    .filter(|s| !s.trim().is_empty())
                {
                    Some(aliases) => {
                        let broad = store
                            .list_memories(
                                Some(WORK_MEMORY_KIND),
                                MemoryListSort::Recent,
                                WORK_MEMORY_ALIAS_FANIN_SCAN,
                            )
                            .await?;
                        cross_node_peer_lanes(
                            &work_memory_scope(&cwd),
                            broad,
                            &aliases,
                            since_ts,
                            limit,
                        )
                    }
                    None => Vec::new(),
                };
                // next_cursor lets the caller poll incrementally (pass back as since_ts).
                let next_cursor = peers.iter().map(|r| r.updated_at).max().unwrap_or(since_ts);
                let rows: Vec<Value> = peers
                    .iter()
                    .map(|r| {
                        let (snippet, truncated, total_chars) = truncate_chars(&r.content, 200);
                        json!({
                            "key": r.key,
                            "scope": r.scope,
                            "updated_at": r.updated_at,
                            "tags": r.tags,
                            "snippet": snippet,
                            "truncated": truncated,
                            "content_chars": total_chars,
                        })
                    })
                    .collect();
                Ok(ToolResult::json_text(&json!({
                    "cwd": cwd,
                    "kind": WORK_MEMORY_KIND,
                    "since_ts": since_ts,
                    "next_cursor": next_cursor,
                    "peer_lane_count": rows.len(),
                    "peer_lanes": rows,
                })))
            }
            other => Ok(ToolResult::error(format!(
                "unknown work_memory op: {other} (expected save|list|get|clear|peers)"
            ))),
        }
    }
}

pub struct MemoryCompactTool {
    hub: Hub,
}
impl MemoryCompactTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemoryCompactTool {
    fn name(&self) -> &'static str {
        "memory_compact"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Retire low-value memories by tombstoning them (NOT hard-delete; \
                 final removal is memory_purge_tombstones' 7d ladder, and tombstones \
                 propagate the deletion across peers via NewerWins sync). Acts only on \
                 status='active' rows, and only when BOTH match: min_uses (access_count <) \
                 AND older_than_days (last_accessed_at older than). Durable rows are \
                 protected and never retired: importance ≥ 0.6, author-linked \
                 (related_keys), or graph-connected (has edges). 1-hour grace on \
                 created_at. dry_run=true previews. Both omitted → defaults \
                 (min_uses=2, older_than_days=90)."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "min_uses":        { "type": "integer", "minimum": 0 },
                    "older_than_days": { "type": "integer", "minimum": 1 },
                    "dry_run":         { "type": "boolean", "default": false }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let min_uses = args.get("min_uses").and_then(|v| v.as_u64());
        let older_than_secs = args
            .get("older_than_days")
            .and_then(|v| v.as_i64())
            .map(|d| d * 86_400);
        let dry_run = args
            .get("dry_run")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);

        let mut policy = CompactPolicy {
            min_uses,
            older_than_secs,
            dry_run,
        };
        let applied_defaults = policy.is_unset();
        if applied_defaults {
            // v0.8: don't punish callers with a silent no-op; apply the balanced
            // default. dry_run flag is still honoured.
            let mut def = CompactPolicy::healthy_default();
            def.dry_run = dry_run;
            policy = def;
        }
        let keys = store.memory_compact(policy).await?;
        if !dry_run && !keys.is_empty() {
            let cache = self.hub.memory_embed_cache.clone();
            let removed_keys: std::collections::HashSet<String> = keys.iter().cloned().collect();
            tokio::spawn(async move {
                let mut guard = cache.lock().await;
                if let Some(ref mut cached) = *guard {
                    cached.retain(|(r, _)| !removed_keys.contains(&r.key));
                }
            });
        }
        Ok(ToolResult::json_text(&json!({
            "dry_run": dry_run,
            "applied_defaults": applied_defaults,
            "policy": {
                "min_uses": policy.min_uses,
                "older_than_secs": policy.older_than_secs,
            },
            "removed_count": keys.len(),
            "removed_keys": keys,
        })))
    }
}

// ===========================================================================
//                  memory_purge_tombstones (Phase 2.x #6)
// ===========================================================================

pub struct MemoryPurgeTombstonesTool {
    hub: Hub,
}
impl MemoryPurgeTombstonesTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemoryPurgeTombstonesTool {
    fn name(&self) -> &'static str {
        "memory_purge_tombstones"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Hard-DELETE memories that have been tombstoned for at least \
                older_than_days. Tombstone soft-delete keeps deleted rows so the \
                deletion propagates across `agent-bridge sync`; this GC pass cleans \
                them once the sync window has safely passed. Default 7 days. \
                dry_run=true previews."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "older_than_days": {
                        "type": "integer",
                        "minimum": 0,
                        "default": 7,
                        "description": "Only purge tombstones whose updated_at is strictly older than this. \
                            Default 7 — long enough to outlive a typical multi-node sync round-trip. \
                            0 means purge all tombstones regardless of age (use only on isolated nodes)."
                    },
                    "dry_run": { "type": "boolean", "default": false }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let older_than_days = args
            .get("older_than_days")
            .and_then(|v| v.as_i64())
            .unwrap_or(7)
            .max(0);
        let dry_run = args
            .get("dry_run")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let purged = store
            .memory_purge_tombstones(older_than_days, dry_run)
            .await?;
        Ok(ToolResult::json_text(&json!({
            "dry_run": dry_run,
            "older_than_days": older_than_days,
            "purged_count": purged.len(),
            "purged_keys": purged,
        })))
    }
}

// ===========================================================================
//          memory_prune_coactivation_noise (δ-3 — Butlin HOT-4 hygiene)
// ===========================================================================

pub struct MemoryPruneCoactivationNoiseTool {
    hub: Hub,
}
impl MemoryPruneCoactivationNoiseTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemoryPruneCoactivationNoiseTool {
    fn name(&self) -> &'static str {
        "memory_prune_coactivation_noise"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Drop low-weight coactivation pairs that never crystallised. \
                A pair with count <= max_count AND last_at older than older_than_days \
                is noise: it co-fired briefly once, never re-fired, and is now ageing the \
                table. Pair with dream promote (which crystallises pairs at count≥N into \
                cofires edges) — anything left below the promote threshold for a long \
                window is by definition unworthy of the synaptic graph. Returns \
                {pruned_count}. dry_run=true previews."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "max_count": {
                        "type": "integer",
                        "minimum": 0,
                        "default": 1,
                        "description": "Prune pairs whose count is ≤ this. Default 1: only \
                            single co-firings get pruned. Raise to 2 to also drop sporadic \
                            twice-fired pairs that never reached promote threshold."
                    },
                    "older_than_days": {
                        "type": "integer",
                        "minimum": 0,
                        "default": 30,
                        "description": "Only prune pairs whose last_at is at least this many \
                            days old. Default 30 — gives a pair a month to grow before GC."
                    },
                    "dry_run": { "type": "boolean", "default": false }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let max_count = args
            .get("max_count")
            .and_then(|v| v.as_i64())
            .unwrap_or(1)
            .max(0);
        let older_than_days = args
            .get("older_than_days")
            .and_then(|v| v.as_i64())
            .unwrap_or(30)
            .max(0);
        let dry_run = args
            .get("dry_run")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let pruned = store
            .memory_prune_coactivation_noise(max_count, older_than_days, dry_run)
            .await?;
        Ok(ToolResult::json_text(&json!({
            "dry_run": dry_run,
            "max_count": max_count,
            "older_than_days": older_than_days,
            "pruned_count": pruned,
        })))
    }
}

// ===========================================================================
//          memory_prune_degenerate_relates (ζ-12 — clean legacy noise hubs)
// ===========================================================================

/// ζ-12 — Drop `relates` edges where BOTH endpoints carry a tag in
/// `blacklist_tags`. Defensive cleanup for the ζ-9-revealed pattern:
/// pre-ζ-11 `memory_link_orphans` runs collapsed all auto_curated stubs
/// onto a single sibling (degree-84 noise hub on aio2). Pairs with
/// ζ-11's preventive `skip_tags` parameter — ζ-11 stops new degenerate
/// links forming, ζ-12 deletes the legacy ones already in the graph.
/// Only `relates` (softest edge type) is in scope.
pub struct MemoryPruneDegenerateRelatesTool {
    hub: Hub,
}
impl MemoryPruneDegenerateRelatesTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemoryPruneDegenerateRelatesTool {
    fn name(&self) -> &'static str {
        "memory_prune_degenerate_relates"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "ζ-12 (one-shot graph hygiene). Delete `relates` edges where BOTH \
                endpoints carry any tag in `blacklist_tags`. Defensive: only `relates` (softest \
                edge type) is in scope — causal/structural edges (caused_by, supersedes, \
                implements, ...) are preserved even when both endpoints overlap the blacklist. \
                Pair with `memory_link_orphans`' ζ-11 `skip_tags` to stop new degenerate \
                edges from forming. Returns {pruned_count}. dry_run=true previews."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "blacklist_tags": {
                        "type": "array",
                        "items": { "type": "string" },
                        "default": ["auto_curated"],
                        "description": "Edges where both endpoints carry any of these tags are \
                            pruned. Default `['auto_curated']` targets the noise-hub pattern \
                            surfaced by ζ-9: pre-ζ-11 `memory_link_orphans` runs collapsed \
                            curated_implicit_* stubs onto a single sibling."
                    },
                    "dry_run": { "type": "boolean", "default": false }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let blacklist_tags: Vec<String> = args
            .get("blacklist_tags")
            .and_then(|v| v.as_array())
            .map(|arr| {
                arr.iter()
                    .filter_map(|v| v.as_str().map(|s| s.to_string()))
                    .collect()
            })
            .unwrap_or_else(|| vec!["auto_curated".to_string()]);
        let dry_run = args
            .get("dry_run")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let pruned = store
            .memory_prune_degenerate_relates(&blacklist_tags, dry_run)
            .await?;
        Ok(ToolResult::json_text(&json!({
            "dry_run": dry_run,
            "blacklist_tags": blacklist_tags,
            "pruned_count": pruned,
        })))
    }
}

// ===========================================================================
//          memory_archive_orphan_stubs (ζ-14 — retire signal-poor stubs)
// ===========================================================================

/// ζ-14 — Flip orphan stubs carrying a blacklist tag from `status='active'`
/// to `status='archived'`. Closes the ζ-9 → ζ-11 → ζ-12 loop:
/// - ζ-11 stops new degenerate links forming
/// - ζ-12 deletes legacy degenerate edges
/// - ζ-14 actively retires the resulting orphan stubs instead of waiting
///   for passive decay
///
/// Stubs that are simultaneously (a) tagged blacklist, (b) orphan, (c)
/// older than N days are by construction signal-poor dead weight: ζ-11
/// blacklist prevents them from ever re-linking; the only sensible
/// transition is into archived.
pub struct MemoryArchiveOrphanStubsTool {
    hub: Hub,
}
impl MemoryArchiveOrphanStubsTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemoryArchiveOrphanStubsTool {
    fn name(&self) -> &'static str {
        "memory_archive_orphan_stubs"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "ζ-14 (graph-hygiene close-out). Transition orphan stubs from \
                `status='active'` to `status='archived'`. Criterion: status=active AND tags \
                overlap blacklist_tags AND no edges AND created_at <= now-older_than_days*86400. \
                Defaults are conservative: only auto_curated stubs older than 3 days, capped at \
                200 per run. Pair with memory_link_orphans skip_tags (ζ-11) and \
                memory_prune_degenerate_relates (ζ-12) for a full hygiene cycle. dry_run=true \
                previews. Returns {archived_count}."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "blacklist_tags": {
                        "type": "array",
                        "items": { "type": "string" },
                        "default": ["auto_curated"],
                        "description": "Stubs whose tags overlap this list are eligible for \
                            archive. Default `['auto_curated']` matches the ζ-11 / ζ-12 lane."
                    },
                    "older_than_days": {
                        "type": "integer",
                        "minimum": 0,
                        "default": 3,
                        "description": "Only stubs whose created_at is at least this many days \
                            old are archived. Default 3 — gives a session window to revisit \
                            recent stubs before they go cold."
                    },
                    "max_archive": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 1000,
                        "default": 200,
                        "description": "Hard cap on archives per run. Bounds accidents and \
                            keeps a single tx small."
                    },
                    "dry_run": { "type": "boolean", "default": false }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let blacklist_tags: Vec<String> = args
            .get("blacklist_tags")
            .and_then(|v| v.as_array())
            .map(|arr| {
                arr.iter()
                    .filter_map(|v| v.as_str().map(|s| s.to_string()))
                    .collect()
            })
            .unwrap_or_else(|| vec!["auto_curated".to_string()]);
        let older_than_days = args
            .get("older_than_days")
            .and_then(|v| v.as_i64())
            .unwrap_or(3)
            .max(0);
        let max_archive = args
            .get("max_archive")
            .and_then(|v| v.as_i64())
            .unwrap_or(200)
            .clamp(1, 1000);
        let dry_run = args
            .get("dry_run")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let archived = store
            .memory_archive_orphan_stubs(&blacklist_tags, older_than_days, max_archive, dry_run)
            .await?;
        Ok(ToolResult::json_text(&json!({
            "dry_run": dry_run,
            "blacklist_tags": blacklist_tags,
            "older_than_days": older_than_days,
            "max_archive": max_archive,
            "archived_count": archived,
        })))
    }
}

// ===========================================================================
//        memory_restore_archived (ζ-18 — escape hatch for ζ-14 false positives)
// ===========================================================================

/// ζ-18 — Reverse of ζ-14. Restore a single archived row back to
/// `status='active'`. Single-key, not criterion-based: operator inspects
/// a specific row and decides. A bulk restore would re-introduce the
/// noise ζ-14 just retired.
///
/// Only `status='archived'` rows are eligible. `active` / `superseded` /
/// `tombstoned` are no-ops returning `restored=false`. The
/// tombstone → active path goes through supersede chains, not here.
pub struct MemoryRestoreArchivedTool {
    hub: Hub,
}
impl MemoryRestoreArchivedTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemoryRestoreArchivedTool {
    fn name(&self) -> &'static str {
        "memory_restore_archived"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "ζ-18 (graph-hygiene escape hatch). Restore a single \
                `status='archived'` memory back to active by key. Operator-driven \
                inverse of ζ-14 memory_archive_orphan_stubs. Only matches archived \
                rows — active / superseded / tombstoned rows are no-ops. Bumps \
                updated_at on success. Returns {restored: bool}."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "key": {
                        "type": "string",
                        "description": "Memory key (UNIQUE) to restore from archived → active."
                    }
                },
                "required": ["key"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let key = match args.get("key").and_then(|v| v.as_str()) {
            Some(k) if !k.is_empty() => k.to_string(),
            _ => return Ok(ToolResult::error("key is required and must be non-empty")),
        };
        let restored = store.memory_restore_archived(&key).await?;
        Ok(ToolResult::json_text(&json!({
            "key": key,
            "restored": restored,
        })))
    }
}

// ===========================================================================
//   memory_tombstone_aged_archived (ζ-19 — archive→tombstone GC, retire end)
// ===========================================================================

/// ζ-19 — Time-based downgrade of stale `archived` rows to `tombstoned`.
/// Closes the hygiene state machine:
///
///   active → ζ-14 → archived → ζ-19 → tombstoned → purge_tombstones (7d) → DELETE
///
/// `tombstoned` (not direct DELETE) is required so the `dedupe_key` slot
/// is held until the 7-day purge window — protects against NewerWins
/// import or same-content re-save resurrecting an already-retired row.
pub struct MemoryTombstoneAgedArchivedTool {
    hub: Hub,
}
impl MemoryTombstoneAgedArchivedTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemoryTombstoneAgedArchivedTool {
    fn name(&self) -> &'static str {
        "memory_tombstone_aged_archived"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "ζ-19 (graph-hygiene retire-end GC). Downgrade stale archived rows \
                to tombstoned: criterion is status='archived' AND updated_at ≤ now-N*86400. \
                The 14-day default leaves a generous restore window for ζ-18. tombstoned \
                rows still hold their dedupe_key slot, so the existing 7-day purge_tombstones \
                cycle gives a final undo before physical DELETE. dry_run=true previews. \
                Returns {tombstoned_count}."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "older_than_days": {
                        "type": "integer",
                        "minimum": 0,
                        "default": 14,
                        "description": "Rows whose updated_at is at least this many days old \
                            are eligible. `updated_at` is the timestamp ζ-14 bumps on archive, \
                            so this measures how long the row has been sitting in archived \
                            state. Default 14 — comfortably outside ζ-18 restore window."
                    },
                    "max_count": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 5000,
                        "default": 500,
                        "description": "Hard cap on tombstones per run. Bounds runaway and \
                            keeps the transaction small."
                    },
                    "dry_run": { "type": "boolean", "default": false }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let older_than_days = args
            .get("older_than_days")
            .and_then(|v| v.as_i64())
            .unwrap_or(14)
            .max(0);
        let max_count = args
            .get("max_count")
            .and_then(|v| v.as_i64())
            .unwrap_or(500)
            .clamp(1, 5000);
        let dry_run = args
            .get("dry_run")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let tombstoned = store
            .memory_tombstone_aged_archived(older_than_days, max_count, dry_run)
            .await?;
        Ok(ToolResult::json_text(&json!({
            "dry_run": dry_run,
            "older_than_days": older_than_days,
            "max_count": max_count,
            "tombstoned_count": tombstoned,
        })))
    }
}

// ===========================================================================
//                  memory_decay_unused (Phase 2.x #8 — read-recency decay)
// ===========================================================================

pub struct MemoryDecayUnusedTool {
    hub: Hub,
}
impl MemoryDecayUnusedTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemoryDecayUnusedTool {
    fn name(&self) -> &'static str {
        "memory_decay_unused"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Read-recency importance decay: shave `step` off the importance of \
                every active memory whose last_accessed_at is older than window_days, floored \
                at `floor`. Mirrors the Palace C7/C8 staleness model — what hasn't been read \
                loses retrieval rank, even if it was recently written. Distinct from the \
                memory_compact phase that decays by updated_at (write recency). Returns \
                {candidates, decayed, skipped_at_floor}. Defaults: 30d / 0.05 / 0.1."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "window_days": {
                        "type": "number",
                        "minimum": 0,
                        "default": 30,
                        "description": "Only decay rows whose last_accessed_at is older than \
                            this many days. Default 30."
                    },
                    "step": {
                        "type": "number",
                        "minimum": 0,
                        "maximum": 1,
                        "default": 0.05,
                        "description": "How much to shave off importance per pass. Default 0.05."
                    },
                    "floor": {
                        "type": "number",
                        "minimum": 0,
                        "maximum": 1,
                        "default": 0.1,
                        "description": "Importance never drops below this. Default 0.1."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let window_days = args
            .get("window_days")
            .and_then(|v| v.as_f64())
            .unwrap_or(30.0)
            .max(0.0);
        let step = args
            .get("step")
            .and_then(|v| v.as_f64())
            .unwrap_or(0.05)
            .clamp(0.0, 1.0);
        let floor = args
            .get("floor")
            .and_then(|v| v.as_f64())
            .unwrap_or(0.1)
            .clamp(0.0, 1.0);
        let window_secs = (window_days * 86_400.0) as i64;
        let stats = store
            .memory_decay_unused_importance(window_secs, step, floor)
            .await?;
        Ok(ToolResult::json_text(&json!({
            "window_days": window_days,
            "step": step,
            "floor": floor,
            "candidates": stats.candidates,
            "decayed": stats.decayed,
            "skipped_at_floor": stats.skipped_at_floor,
        })))
    }
}

// ===========================================================================
//                       memory_reindex (re-embed after dim migration)
// ===========================================================================

pub struct MemoryReindexTool {
    hub: Hub,
}
impl MemoryReindexTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemoryReindexTool {
    fn name(&self) -> &'static str {
        "memory_reindex"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Re-compute embeddings for active memories. Two modes:\n\
                 - Default (only_stale=false): fills rows with `embedding IS NULL`.\n\
                 - only_stale=true (P9): also reindexes rows whose embedding_backend \
                   tag differs from current default — hash → ONNX upgrade path. \
                   Pre-v26 NULL-backend rows skipped in stale mode."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "batch_size": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 1000,
                        "default": 100,
                        "description": "Number of rows to re-embed per call."
                    },
                    "only_stale": {
                        "type": "boolean",
                        "default": false,
                        "description": "Also reindex rows with embedding_backend != current default."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let batch_size = args
            .get("batch_size")
            .and_then(|v| v.as_u64())
            .unwrap_or(100) as usize;
        let only_stale = args
            .get("only_stale")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);

        let updated = store
            .memory_reindex_embeddings(batch_size, only_stale)
            .await?;

        // Refresh the in-process embedding cache so the new vectors are visible.
        if updated > 0 {
            let cache = self.hub.memory_embed_cache.clone();
            let refresh_store = store.clone();
            tokio::spawn(async move {
                if let Ok(rows) = refresh_store.memory_load_embeddings().await {
                    let mut guard = cache.lock().await;
                    *guard = Some(rows);
                }
            });
        }

        Ok(ToolResult::json_text(&json!({
            "updated": updated,
            "batch_size": batch_size,
            "hint": if updated == batch_size {
                format!("Batch full — call memory_reindex again to continue ({batch_size} rows/call).")
            } else {
                format!("Done. {updated} rows re-embedded this call.")
            }
        })))
    }
}

