// ===========================================================================
//                       memory portability (v0.6)
// ===========================================================================

pub struct MemoryExportTool {
    hub: Hub,
}
impl MemoryExportTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemoryExportTool {
    fn name(&self) -> &'static str {
        "memory_export"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Export memories to a newline-delimited JSON file (one record \
                 per line — JSONL is grep-friendly and stable across versions). \
                 Optional filters narrow what's exported. When `edges_out_path` \
                 is set, a second JSONL file is written for edges. Edge \
                 membership is controlled by `loose_edges`: false (default, \
                 strict) keeps edges where **both** endpoints are in the \
                 exported set; true keeps edges where **either** endpoint is in \
                 the set. Loose is the right choice for narrow filters \
                 (e.g. kind=chat_session) whose edges typically point at \
                 nodes living under other filters; the destination side \
                 will skip + count edges referring to keys it doesn't have."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "path":     { "type": "string", "description": "Absolute output path; parent dirs auto-created." },
                    "kind":     { "type": "string", "description": "Optional kind filter." },
                    "tags_any": { "type": "array", "items": {"type": "string"}, "description": "Match if memory has at least one tag." },
                    "since_ts": { "type": "integer", "description": "Only memories with updated_at >= this unix-epoch seconds value." },
                    "edges_out_path": { "type": "string", "description": "Optional absolute path for companion edge JSONL." },
                    "loose_edges":    { "type": "boolean", "description": "Default false (strict: both endpoints in exported set). True keeps edges with at least one endpoint in the set — destination drops + counts edges referring to missing keys." }
                },
                "required": ["path"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let path = match args.get("path").and_then(|v| v.as_str()) {
            Some(s) => PathBuf::from(s),
            None => return Ok(ToolResult::error("missing 'path'")),
        };
        let filter = MemoryExportFilter {
            kind: args
                .get("kind")
                .and_then(|v| v.as_str())
                .map(|s| s.to_string()),
            tags_any: args.get("tags_any").and_then(|v| v.as_array()).map(|a| {
                a.iter()
                    .filter_map(|x| x.as_str().map(|s| s.to_string()))
                    .collect()
            }),
            since_ts: args.get("since_ts").and_then(|v| v.as_i64()),
            edges_out_path: args
                .get("edges_out_path")
                .and_then(|v| v.as_str())
                .filter(|s| !s.is_empty())
                .map(PathBuf::from),
            loose_edges: args
                .get("loose_edges")
                .and_then(|v| v.as_bool())
                .unwrap_or(false),
            stable_sync_metadata: false,
            exclude_tombstoned_older_than_secs: None,
        };
        match store.memory_export(&filter, &path).await {
            Ok(res) => Ok(ToolResult::json_text(&json!({
                "exported": res.memories_written,
                "memories_written": res.memories_written,
                "edges_written": res.edges_written,
                "path": path.display().to_string(),
            }))),
            Err(e) => Ok(ToolResult::error(format!("export: {e}"))),
        }
    }
}

pub struct MemoryImportTool {
    hub: Hub,
}
impl MemoryImportTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemoryImportTool {
    fn name(&self) -> &'static str {
        "memory_import"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Import memories from a JSONL file (the format `memory_export` \
                 produces). Optional `edges_path` is a companion JSONL of \
                 `MemoryEdgeExport` lines (same convention as `memory_export` \
                 `edges_out_path`); edges are upserted after memories. \
                 `conflict_policy` decides what happens when a key \
                 already exists locally:\n\
                   - `skip` (default): keep local row\n\
                   - `overwrite`: always replace with the imported row\n\
                   - `newer_wins`: replace only if imported.updated_at is greater\n\
                   - `version_vector_merge`: conflict-aware (Track MS) — the dominant version vector wins; a concurrent pair (neither dominates) is preserved as a non-destructive conflict copy (`<key>#conflict-…`, status='conflict') instead of dropping the loser; falls back to newer_wins when either side has no version vector yet\n\
                 Returns {inserted, updated, skipped, malformed, conflict_copies, edges_upserted, edges_malformed, edges_skipped_dangling}. \
                 `edges_skipped_dangling` counts edges that referenced a key not present locally — these are dropped rather than upserted to keep the graph free of dangling refs."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "path":            { "type": "string" },
                    "edges_path":      { "type": "string", "description": "Optional companion JSONL produced by memory_export(edges_out_path=...)." },
                    "conflict_policy": {
                        "type": "string",
                        "enum": ["skip","overwrite","newer_wins","version_vector_merge"],
                        "default": "skip"
                    }
                },
                "required": ["path"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let path = match args.get("path").and_then(|v| v.as_str()) {
            Some(s) => PathBuf::from(s),
            None => return Ok(ToolResult::error("missing 'path'")),
        };
        let policy = match args
            .get("conflict_policy")
            .and_then(|v| v.as_str())
            .unwrap_or("skip")
        {
            "overwrite" => ImportConflictPolicy::Overwrite,
            "newer_wins" => ImportConflictPolicy::NewerWins,
            "version_vector_merge" => ImportConflictPolicy::VersionVectorMerge,
            _ => ImportConflictPolicy::Skip,
        };
        let edges_path = args
            .get("edges_path")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty())
            .map(PathBuf::from);
        match store
            .memory_import(&path, policy, edges_path.as_deref())
            .await
        {
            Ok(report) => Ok(ToolResult::json_text(
                &serde_json::to_value(report).unwrap_or(Value::Null),
            )),
            Err(e) => Ok(ToolResult::error(format!("import: {e}"))),
        }
    }
}

// ===========================================================================
//                       memory graph edges (v0.6)
// ===========================================================================

pub struct MemoryLinkTool {
    hub: Hub,
}
impl MemoryLinkTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemoryLinkTool {
    fn name(&self) -> &'static str {
        "memory_link"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Create/update a directed edge between two memories. Type/weight: \
                 updates 1.5, caused_by 1.3, supersedes 1.3, implements 1.1, relates 1.0, \
                 part_of 0.8, derived_from 0.8, contradicts 0.5, invalidates 0.5. Causal \
                 ×1.2 in BFS. Pair with memory_neighbors."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "from_key":  { "type": "string", "description": "Source memory key." },
                    "to_key":    { "type": "string", "description": "Target memory key." },
                    "edge_type": {
                        "type": "string",
                        "enum": ["updates","caused_by","supersedes","implements","relates","part_of","derived_from","contradicts","invalidates"],
                        "default": "relates",
                        "description": "Relationship type. Weight is auto-assigned from type unless 'weight' is given."
                    },
                    "weight": {
                        "type": "number", "minimum": 0.0, "maximum": 2.0, "default": 1.0,
                        "description": "Override weight. Omit to use canonical weight for the edge type."
                    }
                },
                "required": ["from_key", "to_key"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let from_key = match args.get("from_key").and_then(|v| v.as_str()) {
            Some(s) if !s.is_empty() => s.to_string(),
            _ => return Ok(ToolResult::error("missing 'from_key'")),
        };
        let to_key = match args.get("to_key").and_then(|v| v.as_str()) {
            Some(s) if !s.is_empty() => s.to_string(),
            _ => return Ok(ToolResult::error("missing 'to_key'")),
        };
        let edge_type = args
            .get("edge_type")
            .and_then(|v| v.as_str())
            .unwrap_or("relates")
            .to_string();
        // 1.0 is the sentinel meaning "auto-assign from type"; any other value is explicit.
        let weight = args.get("weight").and_then(|v| v.as_f64()).unwrap_or(1.0);
        match store
            .memory_link(&from_key, &to_key, &edge_type, weight)
            .await
        {
            Ok(()) => {
                // Compute the effective weight that was stored for the response message
                let effective = if (weight - 1.0).abs() < f64::EPSILON {
                    ab_store::weight_for_edge_type(&edge_type)
                } else {
                    weight
                };
                Ok(ToolResult::text(format!(
                    "linked '{from_key}' -{edge_type}-> '{to_key}' (weight={effective:.2})"
                )))
            }
            Err(e) => Ok(ToolResult::error(format!("memory_link: {e}"))),
        }
    }
}

/// L5 P2 — first-class correction API.
///
/// "I learned X about target_key; bias future retrieval accordingly."
/// Writes a `kind=feedback` memory + a `corrects` edge to the target.
/// The feedback memory inherits the L5 P1 retrieval boost in
/// `memory_search`, so the next session searching for `target_key`'s
/// topic will surface the correction earlier than vanilla notes.
///
/// Roadmap: `docs/AGENT-BRIDGE-CAPABILITY-ROADMAP-2026-05-15.md` §2.
pub struct MemoryCorrectionTool {
    hub: Hub,
}
impl MemoryCorrectionTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

/// FNV-1a 64-bit hash, formatted as 16 hex chars. Same approach as
/// `sha256_file` above — collision risk is fine for content-addressed
/// dedupe keys (multiple corrections with the same body to the same
/// target collapse to one row; different bodies are different keys).
fn fnv1a_hex16(s: &str) -> String {
    let mut h: u64 = 14_695_981_039_346_656_037;
    for byte in s.as_bytes() {
        h ^= *byte as u64;
        h = h.wrapping_mul(1_099_511_628_211);
    }
    format!("{h:016x}")
}

/// Sanitise a target key for safe inclusion in a derived key:
/// keep [A-Za-z0-9_-:], replace others with `_`, clamp length so the
/// derived key stays under the storage cap with margin.
pub fn sanitise_target_for_key(target: &str) -> String {
    let cleaned: String = target
        .chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() || c == '_' || c == '-' || c == ':' {
                c
            } else {
                '_'
            }
        })
        .collect();
    cleaned.chars().take(96).collect()
}

#[async_trait]
impl McpTool for MemoryCorrectionTool {
    fn name(&self) -> &'static str {
        "memory_correction"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Record a behavioral correction targeting an existing memory. \
                 Writes a kind=feedback memory + a corrects edge from the new memory \
                 to target_key. The feedback memory inherits the L5 retrieval boost \
                 so future memory_search calls surface it earlier than generic notes. \
                 Idempotent: same target+body produces the same derived key, so \
                 re-recording the same correction is a no-op. target_key must already \
                 exist (errors if not)."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "target_key":       { "type": "string", "description": "Key of the memory being corrected. Must exist." },
                    "correction_body":  { "type": "string", "description": "The correction content. Free-form text." },
                    "importance":       { "type": "number", "minimum": 0.0, "maximum": 1.0, "default": 0.7, "description": "Override importance for the feedback memory (default 0.7; behavioral signal). Clamped to [0,1]." }
                },
                "required": ["target_key", "correction_body"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let target_key = match args
            .get("target_key")
            .and_then(|v| v.as_str())
            .filter(|s| !s.trim().is_empty())
        {
            Some(s) => s.trim().to_string(),
            None => return Ok(ToolResult::error("missing or empty 'target_key'")),
        };
        let correction_body = match args
            .get("correction_body")
            .and_then(|v| v.as_str())
            .filter(|s| !s.trim().is_empty())
        {
            Some(s) => s.to_string(),
            None => return Ok(ToolResult::error("missing or empty 'correction_body'")),
        };
        let importance = args
            .get("importance")
            .and_then(|v| v.as_f64())
            .unwrap_or(0.7)
            .clamp(0.0, 1.0);

        // Target must exist — corrections without anchor are noise.
        match store.memory_get(&target_key).await {
            Ok(Some(_)) => {}
            Ok(None) => {
                return Ok(ToolResult::error(format!(
                    "memory_correction: target_key '{target_key}' not found"
                )));
            }
            Err(e) => {
                return Ok(ToolResult::error(format!(
                    "memory_correction: lookup error for '{target_key}': {e}"
                )));
            }
        }

        // Derived key — content-addressed for idempotent re-correction.
        let correction_key = format!(
            "correction:{}:{}",
            sanitise_target_for_key(&target_key),
            fnv1a_hex16(&correction_body)
        );

        let mem = MemoryRecord {
            key: correction_key.clone(),
            kind: "feedback".into(),
            content: correction_body,
            tags: vec!["correction".into(), "l5".into()],
            related_keys: vec![target_key.clone()],
            scope: None,
            created_at: 0,
            updated_at: 0,
            last_accessed_at: 0,
            access_count: 0,
            importance,
            status: "active".into(),
            trigger_pattern: None,
            superseded_by: None,
        };

        if let Err(e) = store.memory_save(&mem).await {
            return Ok(ToolResult::error(format!(
                "memory_correction: save failed: {e}"
            )));
        }

        // Link new feedback memory → target. weight=1.0 is the
        // "auto-assign from type" sentinel; the store resolves it to
        // EDGE_WEIGHT_CORRECTS (1.4) via weight_for_edge_type.
        if let Err(e) = store
            .memory_link(&correction_key, &target_key, "corrects", 1.0)
            .await
        {
            return Ok(ToolResult::error(format!(
                "memory_correction: link failed (memory saved as {correction_key}): {e}"
            )));
        }

        let edge_weight = ab_store::weight_for_edge_type("corrects");
        Ok(ToolResult::json_text(&json!({
            "status": "ok",
            "correction_key": correction_key,
            "target_key": target_key,
            "edge_type": "corrects",
            "edge_weight": edge_weight,
            "importance": importance,
        })))
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum MemoryRetrievalFeedbackOutcome {
    Used,
    Ignored,
    Stale,
    Duplicate,
    Harmful,
    Missing,
    TooLarge,
}

impl MemoryRetrievalFeedbackOutcome {
    fn parse(raw: &str) -> std::result::Result<Self, String> {
        let normalized = raw.trim().to_ascii_lowercase().replace('-', "_");
        match normalized.as_str() {
            "used" => Ok(Self::Used),
            "ignored" => Ok(Self::Ignored),
            "stale" => Ok(Self::Stale),
            "duplicate" => Ok(Self::Duplicate),
            "harmful" => Ok(Self::Harmful),
            "missing" => Ok(Self::Missing),
            "too_large" => Ok(Self::TooLarge),
            _ => Err(format!(
                "invalid outcome '{raw}' (allowed: used, ignored, stale, duplicate, harmful, missing, too_large)"
            )),
        }
    }

    fn as_str(self) -> &'static str {
        match self {
            Self::Used => "used",
            Self::Ignored => "ignored",
            Self::Stale => "stale",
            Self::Duplicate => "duplicate",
            Self::Harmful => "harmful",
            Self::Missing => "missing",
            Self::TooLarge => "too_large",
        }
    }

    fn edge_type(self) -> Option<&'static str> {
        match self {
            Self::Used => Some("retrieval_used"),
            Self::Ignored => Some("retrieval_ignored"),
            Self::Stale => Some("retrieval_stale"),
            Self::Duplicate => Some("retrieval_duplicate"),
            Self::Harmful => Some("retrieval_harmful"),
            Self::Missing => None,
            Self::TooLarge => Some("retrieval_too_large"),
        }
    }

    fn edge_weight(self) -> Option<f64> {
        match self {
            Self::Used => Some(1.1),
            Self::Ignored => Some(0.6),
            Self::Stale => Some(0.5),
            Self::Duplicate => Some(0.5),
            Self::Harmful => Some(0.4),
            Self::Missing => None,
            Self::TooLarge => Some(0.6),
        }
    }

    fn default_importance(self) -> f64 {
        match self {
            Self::Harmful | Self::Missing | Self::Stale => 0.75,
            Self::Duplicate | Self::TooLarge => 0.65,
            Self::Used => 0.55,
            Self::Ignored => 0.45,
        }
    }
}

pub struct MemoryRetrievalFeedbackTool {
    hub: Hub,
}
impl MemoryRetrievalFeedbackTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

fn memory_retrieval_feedback_source(args: &Value) -> std::result::Result<String, String> {
    let source = args
        .get("source")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .unwrap_or("manual")
        .replace('-', "_");
    match source.as_str() {
        "memory_search" | "memory_get" | "session_bootstrap" | "manual" => Ok(source),
        _ => Err(format!(
            "invalid source '{source}' (allowed: memory_search, memory_get, session_bootstrap, manual)"
        )),
    }
}

fn memory_optional_string_arg(args: &Value, key: &str) -> Option<String> {
    args.get(key)
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(str::to_string)
}

fn memory_push_unique_string(values: &mut Vec<String>, value: String) {
    if !value.trim().is_empty() && !values.iter().any(|existing| existing == &value) {
        values.push(value);
    }
}

fn memory_retrieval_feedback_content(
    outcome: MemoryRetrievalFeedbackOutcome,
    source: &str,
    target_key: Option<&str>,
    query: Option<&str>,
    note: Option<&str>,
    retrieved_keys: &[String],
) -> String {
    let mut lines = vec![
        "# Memory Retrieval Feedback".to_string(),
        format!("outcome: {}", outcome.as_str()),
        format!("source: {source}"),
        format!("target_key: {}", target_key.unwrap_or("(missing)")),
        format!("query: {}", query.unwrap_or("")),
    ];
    if let Some(note) = note {
        lines.push(format!("note: {note}"));
    }
    if !retrieved_keys.is_empty() {
        lines.push(String::new());
        lines.push("## Retrieved Keys".to_string());
        for key in retrieved_keys {
            lines.push(format!("- {key}"));
        }
    }
    lines.join("\n")
}

/// Kind for the machine-written retrieval telemetry rows this tool saves
/// (`retrieval_feedback:*` keys). Split out of `feedback` (2026-07-07) so
/// telemetry never rides the behavioral-feedback surfaces — the FTS/semantic
/// kind boosts, the decay protection class, and the session-start preamble
/// all key on `feedback` and are meant for corrections / owner feedback,
/// which stay kind=feedback (`correction:*` writer untouched).
pub(crate) const RETRIEVAL_FEEDBACK_KIND: &str = "retrieval_feedback";

#[async_trait]
impl McpTool for MemoryRetrievalFeedbackTool {
    fn name(&self) -> &'static str {
        "memory_retrieval_feedback"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Record low-friction feedback about retrieved memories. \
                 Writes a kind=retrieval_feedback telemetry memory tagged with \
                 retrieval_feedback and, \
                 when memory_key exists, links feedback -> memory_key with an \
                 outcome-specific edge such as retrieval_used or retrieval_stale. \
                 outcome=missing may be recorded without a target. This does not \
                 reorder default FTS results, but graph-aware hybrid retrieval may \
                 observe the new feedback rows and edges."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "memory_key": { "type": "string", "description": "Retrieved memory being judged. Required unless outcome=missing. Must exist when provided." },
                    "outcome": {
                        "type": "string",
                        "enum": ["used", "ignored", "stale", "duplicate", "harmful", "missing", "too_large"],
                        "description": "Observed retrieval quality label. too-large is accepted as an alias for too_large."
                    },
                    "source": {
                        "type": "string",
                        "enum": ["memory_search", "memory_get", "session_bootstrap", "manual"],
                        "default": "manual",
                        "description": "Where the retrieval happened."
                    },
                    "query": { "type": "string", "description": "Optional retrieval query or task context." },
                    "note": { "type": "string", "description": "Optional compact reason for the label." },
                    "retrieved_keys": {
                        "type": "array",
                        "items": { "type": "string" },
                        "default": [],
                        "description": "Optional selected/retrieved memory keys from the same retrieval event."
                    },
                    "related_keys": {
                        "type": "array",
                        "items": { "type": "string" },
                        "default": [],
                        "description": "Optional extra context memories to relate to this feedback when they exist."
                    },
                    "importance": {
                        "type": "number", "minimum": 0.0, "maximum": 1.0,
                        "description": "Optional importance override. Defaults depend on outcome."
                    }
                },
                "required": ["outcome"]
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let outcome_raw = match args.get("outcome").and_then(Value::as_str) {
            Some(s) if !s.trim().is_empty() => s,
            _ => return Ok(ToolResult::error("missing or empty 'outcome'")),
        };
        let outcome = match MemoryRetrievalFeedbackOutcome::parse(outcome_raw) {
            Ok(outcome) => outcome,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        let source = match memory_retrieval_feedback_source(&args) {
            Ok(source) => source,
            Err(e) => return Ok(ToolResult::error(e)),
        };
        let target_key = memory_optional_string_arg(&args, "memory_key");
        if outcome != MemoryRetrievalFeedbackOutcome::Missing && target_key.is_none() {
            return Ok(ToolResult::error(
                "memory_key is required unless outcome=missing",
            ));
        }
        if let Some(target_key) = &target_key {
            match store.memory_get(target_key).await {
                Ok(Some(_)) => {}
                Ok(None) => {
                    return Ok(ToolResult::error(format!(
                        "memory_retrieval_feedback: target_key '{target_key}' not found"
                    )));
                }
                Err(e) => {
                    return Ok(ToolResult::error(format!(
                        "memory_retrieval_feedback: lookup error for '{target_key}': {e}"
                    )));
                }
            }
        }

        let query = memory_optional_string_arg(&args, "query");
        let note = memory_optional_string_arg(&args, "note");
        let retrieved_keys = memory_string_array_arg(&args, "retrieved_keys", &[]);
        let explicit_related_keys = memory_string_array_arg(&args, "related_keys", &[]);
        let mut related_keys = Vec::new();
        if let Some(target_key) = &target_key {
            memory_push_unique_string(&mut related_keys, target_key.clone());
        }
        for key in retrieved_keys.iter().chain(explicit_related_keys.iter()) {
            memory_push_unique_string(&mut related_keys, key.clone());
        }

        let target_slug = target_key
            .as_deref()
            .map(sanitise_target_for_key)
            .unwrap_or_else(|| "missing".to_string());
        let seed = format!(
            "{}\0{}\0{}\0{}\0{}\0{}\0{}",
            outcome.as_str(),
            source,
            target_key.as_deref().unwrap_or(""),
            query.as_deref().unwrap_or(""),
            note.as_deref().unwrap_or(""),
            retrieved_keys.join("\0"),
            explicit_related_keys.join("\0")
        );
        let feedback_key = format!(
            "retrieval_feedback:{target_slug}:{}:{}",
            outcome.as_str(),
            fnv1a_hex16(&seed)
        );
        let content = memory_retrieval_feedback_content(
            outcome,
            &source,
            target_key.as_deref(),
            query.as_deref(),
            note.as_deref(),
            &retrieved_keys,
        );
        let importance = args
            .get("importance")
            .and_then(Value::as_f64)
            .unwrap_or_else(|| outcome.default_importance())
            .clamp(0.0, 1.0);
        let mut tags = vec![
            "retrieval_feedback".to_string(),
            format!("retrieval_feedback:{}", outcome.as_str()),
            format!("retrieval_source:{source}"),
        ];
        if let Some(target_key) = &target_key {
            memory_push_unique_tag(
                &mut tags,
                format!("target:{}", sanitise_target_for_key(target_key)),
            );
        }

        let rec = MemoryRecord {
            key: feedback_key.clone(),
            kind: RETRIEVAL_FEEDBACK_KIND.to_string(),
            content,
            tags,
            related_keys: related_keys.clone(),
            scope: None,
            created_at: 0,
            updated_at: 0,
            last_accessed_at: 0,
            access_count: 0,
            importance,
            status: "active".to_string(),
            trigger_pattern: None,
            superseded_by: None,
        };
        if let Err(e) = store.memory_save(&rec).await {
            return Ok(ToolResult::error(format!(
                "memory_retrieval_feedback: save failed: {e}"
            )));
        }

        let mut edge = Value::Null;
        if let (Some(target_key), Some(edge_type), Some(weight)) =
            (&target_key, outcome.edge_type(), outcome.edge_weight())
        {
            if let Err(e) = store
                .memory_link(&feedback_key, target_key, edge_type, weight)
                .await
            {
                return Ok(ToolResult::error(format!(
                    "memory_retrieval_feedback: link failed (memory saved as {feedback_key}): {e}"
                )));
            }
            edge = json!({
                "from_key": feedback_key,
                "to_key": target_key,
                "edge_type": edge_type,
                "weight": weight,
            });
        }

        let mut linked_related_keys = Vec::new();
        for related_key in related_keys.iter() {
            if target_key.as_deref() == Some(related_key.as_str()) {
                continue;
            }
            match store.memory_get(related_key).await {
                Ok(Some(_)) => {
                    if let Err(e) = store
                        .memory_link(&feedback_key, related_key, "retrieval_context", 0.7)
                        .await
                    {
                        return Ok(ToolResult::error(format!(
                            "memory_retrieval_feedback: related link failed (memory saved as {feedback_key}): {e}"
                        )));
                    }
                    linked_related_keys.push(related_key.clone());
                }
                Ok(None) => {}
                Err(e) => {
                    return Ok(ToolResult::error(format!(
                        "memory_retrieval_feedback: related lookup error for '{related_key}': {e}"
                    )));
                }
            }
        }

        // Outcome-collector (flag-gated): an explicit `used` judgement is the
        // strongest positive retrieval signal there is — stamp `used_at` on
        // the judged key's recent surfacings so the reinforce/decay pass sees
        // it. Wider window than the memory_get hook (feedback often lands at
        // session end, hours after the search); ≤ APPLY_MATURATION_SECS so a
        // stamp can never chase an already-consumed row. Fail-soft: the store
        // impl warns and returns 0 on error.
        let mut used_at_stamped = 0u64;
        if outcome == MemoryRetrievalFeedbackOutcome::Used && outcome_collector_enabled() {
            if let Some(target_key) = &target_key {
                used_at_stamped = store
                    .attribute_retrieval_get(
                        target_key,
                        crate::retrieval_outcome::FEEDBACK_ATTRIBUTION_WINDOW_SECS,
                    )
                    .await
                    .unwrap_or(0);
            }
        }

        Ok(ToolResult::json_text(&json!({
            "status": "ok",
            "feedback_key": feedback_key,
            "outcome": outcome.as_str(),
            "source": source,
            "target_key": target_key,
            "edge": edge,
            "linked_related_keys": linked_related_keys,
            "importance": importance,
            "used_at_stamped": used_at_stamped,
            "hint": "telemetry recorded; default FTS order is unchanged, but graph-aware hybrid retrieval may observe the new feedback memory and edges",
        })))
    }
}

pub struct MemoryNeighborsTool {
    hub: Hub,
}
impl MemoryNeighborsTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemoryNeighborsTool {
    fn name(&self) -> &'static str {
        "memory_neighbors"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Return graph edges (optionally BFS multi-hop) from a memory key. \
                 depth=1: direct neighbors by weight. depth>1: BFS propagating \
                 energy × weight × temporal × decay. Row: from_key, to_key, edge_type, \
                 weight, energy. Causal ×1.2, conflicts ×0.85."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "key": { "type": "string", "description": "Starting memory key." },
                    "depth": {
                        "type": "integer", "minimum": 1, "maximum": 6, "default": 1,
                        "description": "BFS depth. 1=direct neighbors only, 2–6=multi-hop traversal."
                    },
                    "decay_factor": {
                        "type": "number", "minimum": 0.1, "maximum": 1.0, "default": 0.7,
                        "description": "Energy decay per hop. 0.7 means 30% energy loss per hop."
                    },
                    "min_energy": {
                        "type": "number", "minimum": 0.0, "maximum": 1.0, "default": 0.05,
                        "description": "Prune edges with propagated energy below this threshold."
                    }
                },
                "required": ["key"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let key = match args.get("key").and_then(|v| v.as_str()) {
            Some(s) => s.to_string(),
            None => return Ok(ToolResult::error("missing 'key'")),
        };
        let depth = args
            .get("depth")
            .and_then(|v| v.as_u64())
            .unwrap_or(1)
            .clamp(1, 6) as u8;
        let decay_factor = args
            .get("decay_factor")
            .and_then(|v| v.as_f64())
            .unwrap_or(0.7)
            .clamp(0.1, 1.0);
        let min_energy = args
            .get("min_energy")
            .and_then(|v| v.as_f64())
            .unwrap_or(0.05)
            .clamp(0.0, 1.0);

        if depth == 1 {
            // Fast path: simple direct neighbors (no BFS overhead)
            let edges = store.memory_neighbors(&key).await?;
            let out: Vec<serde_json::Value> = edges
                .into_iter()
                .map(|e| {
                    let energy = 1.0 * e.weight; // at depth=1, energy = starting_energy × weight
                    serde_json::json!({
                        "from_key": e.from_key,
                        "to_key": e.to_key,
                        "edge_type": e.edge_type,
                        "weight": e.weight,
                        "energy": energy
                    })
                })
                .collect();
            Ok(ToolResult::json_text(
                &serde_json::to_value(out).unwrap_or(Value::Null),
            ))
        } else {
            // BFS multi-hop path
            let pairs = store
                .memory_neighbors_bfs(&key, depth, decay_factor, min_energy)
                .await?;
            let out: Vec<serde_json::Value> = pairs
                .into_iter()
                .map(|(e, energy)| {
                    serde_json::json!({
                        "from_key": e.from_key,
                        "to_key": e.to_key,
                        "edge_type": e.edge_type,
                        "weight": e.weight,
                        "energy": (energy * 1000.0).round() / 1000.0
                    })
                })
                .collect();
            Ok(ToolResult::json_text(
                &serde_json::to_value(out).unwrap_or(Value::Null),
            ))
        }
    }
}

pub struct MemoryCoactivationTopTool {
    hub: Hub,
}
impl MemoryCoactivationTopTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemoryCoactivationTopTool {
    fn name(&self) -> &'static str {
        "memory_coactivation_top"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "v21 α — Synaptic Trace introspection. Returns the top \
                co-activation edges for a memory key, ordered by count DESC. \
                Records are populated as a side effect of memory_search calls \
                (Hebbian fire-together-wire-together). Each row: \
                {key_a, key_b, count, first_at, last_at}. The peer key in each \
                row is whichever of key_a/key_b is NOT the queried key. Empty \
                result on cold DB or if α has not started recording yet."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "key":   { "type": "string", "description": "Memory key to look up." },
                    "limit": {
                        "type": "integer", "minimum": 1, "maximum": 200, "default": 20,
                        "description": "Max edges to return (highest count first)."
                    }
                },
                "required": ["key"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let key = match args.get("key").and_then(|v| v.as_str()) {
            Some(s) => s.to_string(),
            None => return Ok(ToolResult::error("missing 'key'")),
        };
        let limit = args
            .get("limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(20)
            .clamp(1, 200) as u32;
        let edges = store.top_coactivation(&key, limit).await?;
        Ok(ToolResult::json_text(
            &serde_json::to_value(edges).unwrap_or(Value::Null),
        ))
    }
}

fn is_continuity_tag(tag: &str) -> bool {
    CONTINUITY_TAG_PREFIXES
        .iter()
        .any(|prefix| tag.starts_with(prefix))
}

fn memory_continuity_bootstrap_reason(r: &MemoryRecord) -> Option<String> {
    let metadata = memory_continuity_metadata_from_tags(&r.tags, r.superseded_by.as_deref())?;
    let why = metadata
        .actionability
        .as_deref()
        .or_else(|| match metadata.continuity_role.as_deref() {
            Some("constraint") | Some("warning") => Some("must_block"),
            Some("state") | Some("procedure") | Some("preference") => Some("plan_influence"),
            Some("evidence") | Some("archive") => Some("background"),
            _ => None,
        })
        .unwrap_or("context");
    let mut parts = vec![format!("why: {why}")];
    if let Some(role) = metadata.continuity_role.as_deref() {
        parts.push(format!("role={role}"));
    }
    if let Some(confidence) = metadata.confidence.as_deref() {
        parts.push(format!("conf={confidence}"));
    }
    if let Some(radius) = metadata.blast_radius.as_deref() {
        parts.push(format!("radius={radius}"));
    }
    if let Some(trigger) = metadata.retrieval_trigger.as_deref() {
        parts.push(format!("trigger={trigger}"));
    }
    Some(format!(" {{{}}}", parts.join(", ")))
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ContinuityBootstrapTier {
    MustBlock,
    Active,
    Evidence,
}

fn memory_continuity_bootstrap_tier(
    metadata: &MemoryContinuityMetadata,
) -> Option<ContinuityBootstrapTier> {
    match metadata.actionability.as_deref() {
        Some("must_block") => return Some(ContinuityBootstrapTier::MustBlock),
        Some("plan_influence") | Some("needs_review") => {
            return Some(ContinuityBootstrapTier::Active);
        }
        Some("background") => return Some(ContinuityBootstrapTier::Evidence),
        _ => {}
    }
    match metadata.continuity_role.as_deref() {
        Some("constraint") | Some("warning") => Some(ContinuityBootstrapTier::MustBlock),
        Some("state") | Some("procedure") | Some("preference") => {
            Some(ContinuityBootstrapTier::Active)
        }
        Some("evidence") | Some("archive") => Some(ContinuityBootstrapTier::Evidence),
        _ => None,
    }
}

/// Whether a session handoff may receive bootstrap *priority* for `cwd`.
///
/// Handoffs that fail this gate remain ordinary searchable memories; they are
/// only denied the unconditional prefix/float that can otherwise displace
/// current project state.  Priority is intentionally strict: an exact project
/// scope, actionable continuity metadata, and a verified/non-stale source are
/// required.  Auto-curated or identifier-unverified rows never qualify.
fn bootstrap_handoff_priority_eligible(row: &MemoryRecord, cwd: &str) -> bool {
    if row.kind != "session_handoff" || row.status != "active" {
        return false;
    }
    if row
        .tags
        .iter()
        .any(|tag| tag == "auto_curated" || tag == crate::curate::UNVERIFIED_IDENTIFIER_TAG)
    {
        return false;
    }

    let expected_scope = format!("project:{}", cwd.trim_end_matches('/'));
    if row.scope.as_deref().map(|s| s.trim_end_matches('/')) != Some(expected_scope.as_str()) {
        return false;
    }

    let Some(metadata) =
        memory_continuity_metadata_from_tags(&row.tags, row.superseded_by.as_deref())
    else {
        return false;
    };
    if metadata.confidence.as_deref() == Some("stale") {
        return false;
    }
    matches!(
        memory_continuity_bootstrap_tier(&metadata),
        Some(ContinuityBootstrapTier::MustBlock | ContinuityBootstrapTier::Active)
    )
}

fn prioritize_bootstrap_handoffs(rows: Vec<MemoryRecord>, cwd: &str) -> Vec<MemoryRecord> {
    let (priority, rest): (Vec<_>, Vec<_>) = rows
        .into_iter()
        .partition(|row| bootstrap_handoff_priority_eligible(row, cwd));
    priority.into_iter().chain(rest).collect()
}

#[cfg(test)]
mod bootstrap_handoff_priority_tests {
    use super::*;

    const CWD: &str = "/Data/CascadeProjects/agent-bridge";

    fn handoff(key: &str, scope: Option<&str>, tags: &[&str]) -> MemoryRecord {
        MemoryRecord {
            key: key.into(),
            kind: "session_handoff".into(),
            content: String::new(),
            tags: tags.iter().map(|tag| (*tag).into()).collect(),
            related_keys: vec![],
            scope: scope.map(str::to_string),
            created_at: 0,
            updated_at: 0,
            last_accessed_at: 0,
            access_count: 0,
            importance: 0.5,
            status: "active".into(),
            trigger_pattern: None,
            superseded_by: None,
        }
    }

    #[test]
    fn admits_exact_scope_actionable_verified_handoff() {
        let row = handoff(
            "current",
            Some("project:/Data/CascadeProjects/agent-bridge"),
            &[
                "continuity_role:state",
                "continuity_actionability:plan_influence",
                "continuity_confidence:verified",
            ],
        );
        assert!(bootstrap_handoff_priority_eligible(&row, CWD));
    }

    #[test]
    fn rejects_auto_curated_unverified_background_and_cross_scope_handoffs() {
        let cases = [
            handoff(
                "auto",
                Some("project:/Data/CascadeProjects/agent-bridge"),
                &["auto_curated", "continuity_actionability:must_block"],
            ),
            handoff(
                "unverified",
                Some("project:/Data/CascadeProjects/agent-bridge"),
                &[
                    crate::curate::UNVERIFIED_IDENTIFIER_TAG,
                    "continuity_actionability:must_block",
                ],
            ),
            handoff(
                "archive",
                Some("project:/Data/CascadeProjects/agent-bridge"),
                &[
                    "continuity_role:archive",
                    "continuity_actionability:background",
                ],
            ),
            handoff(
                "root-scope",
                Some("project:/Data/CascadeProjects"),
                &["continuity_actionability:must_block"],
            ),
            handoff("global", None, &["continuity_actionability:must_block"]),
        ];
        for row in cases {
            assert!(
                !bootstrap_handoff_priority_eligible(&row, CWD),
                "{} unexpectedly admitted",
                row.key
            );
        }
    }

    #[test]
    fn priority_partition_floats_only_admitted_handoffs() {
        let mut lesson = handoff("lesson", None, &[]);
        lesson.kind = "lesson".into();
        let rejected = handoff("rejected", None, &["auto_curated"]);
        let admitted = handoff(
            "admitted",
            Some("project:/Data/CascadeProjects/agent-bridge"),
            &["continuity_role:state", "continuity_confidence:verified"],
        );
        let out = prioritize_bootstrap_handoffs(vec![lesson, rejected, admitted], CWD);
        assert_eq!(
            out.iter().map(|row| row.key.as_str()).collect::<Vec<_>>(),
            vec!["admitted", "lesson", "rejected"]
        );
    }
}

fn format_continuity_kernel_row(r: &MemoryRecord, snippet_len: usize) -> String {
    let snippet: String = r.content.chars().take(snippet_len).collect();
    let ellipsis = if r.content.chars().count() > snippet_len {
        "..."
    } else {
        ""
    };
    let imp_marker = if r.importance >= 0.7 { "*" } else { "" };
    let reason = memory_continuity_bootstrap_reason(r).unwrap_or_default();
    format!(
        "- [{}] {}{}{}: {}{}",
        r.kind, r.key, imp_marker, reason, snippet, ellipsis
    )
}

/// Bucket + sort the kernel selection (unchanged from the original
/// `format_continuity_kernel_block` body): active rows carrying continuity
/// metadata, tiered must-block → active → evidence, importance-desc inside
/// each bucket. `None` when nothing qualifies.
#[allow(clippy::type_complexity)]
fn select_continuity_kernel_buckets(
    rows: &[MemoryRecord],
) -> Option<(Vec<&MemoryRecord>, Vec<&MemoryRecord>, Vec<&MemoryRecord>)> {
    let mut must_block: Vec<&MemoryRecord> = Vec::new();
    let mut active: Vec<&MemoryRecord> = Vec::new();
    let mut evidence: Vec<&MemoryRecord> = Vec::new();

    for row in rows.iter().filter(|r| r.status == "active") {
        let Some(metadata) =
            memory_continuity_metadata_from_tags(&row.tags, row.superseded_by.as_deref())
        else {
            continue;
        };
        match memory_continuity_bootstrap_tier(&metadata) {
            Some(ContinuityBootstrapTier::MustBlock) => must_block.push(row),
            Some(ContinuityBootstrapTier::Active) => active.push(row),
            Some(ContinuityBootstrapTier::Evidence) => evidence.push(row),
            None => {}
        }
    }

    if must_block.is_empty() && active.is_empty() && evidence.is_empty() {
        return None;
    }
    for bucket in [&mut must_block, &mut active, &mut evidence] {
        bucket.sort_by(|a, b| {
            b.importance
                .partial_cmp(&a.importance)
                .unwrap_or(std::cmp::Ordering::Equal)
        });
    }
    Some((must_block, active, evidence))
}

/// D1 index-line trigger prefix cap — keys must stay verbatim (they are the
/// drill-down handle), the trigger is only a recall cue so it truncates.
const CONTINUITY_KERNEL_INDEX_TRIGGER_CHARS: usize = 60;

/// D1 floor line: `  - [kind] key {trigger prefix}` — the minimum trace a
/// selected row may leave in bootstrap output. Carries exactly what a new
/// session needs to drill down (`memory_get key`) plus the retrieval trigger
/// as a "when would I need this" cue; trigger section omitted when absent.
fn format_continuity_kernel_index_line(r: &MemoryRecord) -> String {
    let trigger = memory_continuity_metadata_from_tags(&r.tags, r.superseded_by.as_deref())
        .and_then(|m| m.retrieval_trigger)
        .map(|t| {
            let prefix: String = t
                .chars()
                .take(CONTINUITY_KERNEL_INDEX_TRIGGER_CHARS)
                .collect();
            format!(" {{{prefix}}}")
        })
        .unwrap_or_default();
    format!("  - [{}] {}{}", r.kind, r.key, trigger)
}

/// Third-stage degradation: bare `  - [kind] key` with no trigger cue.
/// Used once trigger-bearing index lines overflow `index_budget` — bare keys
/// keep the `memory_get` drill-down handle for every selected row at a
/// fraction of the cost (CJK triggers dominate index-line token cost).
fn format_continuity_kernel_bare_index_line(r: &MemoryRecord) -> String {
    format!("  - [{}] {}", r.kind, r.key)
}

/// Budget-aware Continuity Kernel renderer (D1 fix, 2026-07-06).
///
/// The old pipeline (`format_continuity_kernel_block` → `cap_block_lines`)
/// truncated the block bottom-up at `BUDGET_CONTINUITY_KERNEL`, so most
/// selected rows vanished without even their key surfacing — a new session
/// could not `memory_get` what it never saw (live measurement: 34 rows
/// selected, ~160 text lines trimmed). This renderer self-accounts instead:
///
/// 1. Full rows render in the existing bucket order (must-block → active →
///    evidence, per-bucket caps unchanged) with running token accounting via
///    `estimate_tokens_from_text` against `full_budget`. The first row that
///    would overflow demotes ITSELF AND every later selected row — bucket
///    order is thus preserved and must-block rows keep full-text priority.
/// 2. Demoted rows (budget overflow + the rows beyond per-bucket caps, which
///    previously vanished silently) emit one index line each under a separate
///    `index_budget`. If the trigger-bearing rendering of ALL demoted rows
///    would overflow that budget, the whole section drops to bare
///    `  - [kind] key` lines (live 2026-07-06: CJK triggers cost ~2.5× the
///    ASCII corpus the budget was measured on — 25 of 40 trigger lines
///    exhausted it, dropping 14 keys). Only when even bare lines do not fit
///    does a final `[...N more selected rows omitted, use memory_search]`
///    marker appear.
///
/// Under budget the output is byte-identical to the old renderer (no index
/// section). The block no longer goes through `cap_block_lines`.
fn format_continuity_kernel_block(
    rows: &[MemoryRecord],
    is_compact: bool,
    snippet_len: usize,
    full_budget: usize,
    index_budget: usize,
) -> Option<Vec<String>> {
    let (must_block, active, evidence) = select_continuity_kernel_buckets(rows)?;

    let total = must_block.len() + active.len() + evidence.len();
    let mut out = vec![
        if is_compact {
            format!("=== Continuity Kernel ({total}) ===")
        } else {
            format!("=== Continuity Kernel ({total} selected rows, no extra retrieval) ===")
        },
        String::new(),
    ];
    let mut used: usize = out
        .iter()
        .map(|l| estimate_tokens_from_text(l) as usize)
        .sum();
    let mut demoted: Vec<&MemoryRecord> = Vec::new();
    let mut full_exhausted = false;
    for (title, bucket, cap) in [
        ("-- must-block / constraints --", &must_block, 4usize),
        ("-- active state / procedures --", &active, 4),
        ("-- evidence / background --", &evidence, 3),
    ] {
        let mut title_pending = Some(title);
        for (i, &row) in bucket.iter().enumerate() {
            if full_exhausted || i >= cap {
                demoted.push(row);
                continue;
            }
            let line = format_continuity_kernel_row(row, snippet_len);
            let title_tokens = title_pending
                .map(|t| estimate_tokens_from_text(t) as usize)
                .unwrap_or(0);
            let line_tokens = estimate_tokens_from_text(&line) as usize;
            if used
                .saturating_add(title_tokens)
                .saturating_add(line_tokens)
                > full_budget
            {
                full_exhausted = true;
                demoted.push(row);
                continue;
            }
            if let Some(title) = title_pending.take() {
                out.push(title.to_string());
            }
            used += title_tokens + line_tokens;
            out.push(line);
        }
    }

    if !demoted.is_empty() {
        let header = "-- index (full text over budget; memory_get <key> to expand) --";
        out.push(header.to_string());
        let mut index_used = estimate_tokens_from_text(header) as usize;
        // Two-pass format decision: if the trigger-bearing rendering of ALL
        // demoted rows fits, keep triggers; otherwise the WHOLE section drops
        // to bare `- [kind] key` lines — key coverage beats trigger cues, and
        // switching mid-stream would only rescue the last sliver of budget.
        let with_triggers: Vec<String> = demoted
            .iter()
            .map(|row| format_continuity_kernel_index_line(row))
            .collect();
        let triggers_total: usize = index_used
            + with_triggers
                .iter()
                .map(|l| estimate_tokens_from_text(l) as usize)
                .sum::<usize>();
        let index_lines: Vec<String> = if triggers_total <= index_budget {
            with_triggers
        } else {
            demoted
                .iter()
                .map(|row| format_continuity_kernel_bare_index_line(row))
                .collect()
        };
        for (i, line) in index_lines.iter().enumerate() {
            let line_tokens = estimate_tokens_from_text(line) as usize;
            if index_used.saturating_add(line_tokens) > index_budget {
                out.push(format!(
                    "  [...{} more selected rows omitted, use memory_search]",
                    index_lines.len() - i
                ));
                break;
            }
            index_used += line_tokens;
            out.push(line.clone());
        }
    }
    out.push(String::new());
    Some(out)
}

fn format_bootstrap_memory_rows(rows: &[MemoryRecord], snippet_len: usize) -> Vec<String> {
    rows.iter()
        .map(|r| {
            let visible_tags: Vec<&str> = r
                .tags
                .iter()
                .map(String::as_str)
                .filter(|tag| !is_continuity_tag(tag))
                .collect();
            let tags = if visible_tags.is_empty() {
                String::new()
            } else {
                format!(" [{}]", visible_tags.join(", "))
            };
            let continuity_reason = memory_continuity_bootstrap_reason(r).unwrap_or_default();
            let snippet: String = r.content.chars().take(snippet_len).collect();
            let ellipsis = if r.content.chars().count() > snippet_len {
                "…"
            } else {
                ""
            };
            let imp_marker = if r.importance >= 0.7 { "★" } else { "" };
            // #1758 hardening: rows carrying a fabricatable identifier (bare
            // git SHA / #post-id) — either flagged at curate time or detected
            // here for rows predating the tag — get a ⚠ref marker so recalled
            // identifiers read as "verify before citing", not settled fact.
            let ref_marker = if r
                .tags
                .iter()
                .any(|t| t == crate::curate::UNVERIFIED_IDENTIFIER_TAG)
                || crate::curate::contains_unverified_identifier(&snippet)
            {
                " ⚠ref"
            } else {
                ""
            };
            format!(
                "[{}] {}{}{}{}{}: {}{}",
                r.kind, r.key, imp_marker, ref_marker, tags, continuity_reason, snippet, ellipsis
            )
        })
        .collect()
}

/// **L5 P3** — composite "preamble fitness" score for feedback memories.
/// Blends static importance with a 30d half-life recency factor so the
/// session-start preamble surfaces both freshly-written corrections and
/// long-standing high-importance feedback. Pure for testability.
fn feedback_preamble_score(importance: f64, updated_at: i64, now: i64) -> f64 {
    let age_days = ((now - updated_at).max(0) as f64) / 86_400.0;
    let recency = (-age_days / 30.0).exp(); // 30d half-life
    importance + 0.3 * recency
}

/// **L5 P3** — pick the top-K feedback memories for the session-start
/// preamble. Re-ranks by [`feedback_preamble_score`] then truncates.
/// Pure (no IO); caller sources `rows` from `list_memories_in_scope`.
fn pick_top_feedback(rows: Vec<MemoryRecord>, k: usize, now: i64) -> Vec<MemoryRecord> {
    let mut scored: Vec<(f64, MemoryRecord)> = rows
        .into_iter()
        // kind=retrieval_feedback telemetry rows are deliberately outside the
        // preamble pool: only behavioral feedback (corrections, owner notes)
        // belongs in the session-start preamble.
        .filter(|r| r.status == "active" && r.kind == "feedback")
        .map(|r| {
            let score = feedback_preamble_score(r.importance, r.updated_at, now);
            (score, r)
        })
        .collect();
    scored.sort_by(|a, b| b.0.partial_cmp(&a.0).unwrap_or(std::cmp::Ordering::Equal));
    scored.into_iter().take(k).map(|(_, r)| r).collect()
}

/// **L5 P3** — format the feedback preamble block. Returns `None` when
/// `rows` is empty so the caller can skip the section header entirely
/// (no visual noise on fresh sessions). Pure for testability.
fn format_feedback_preamble_block(
    rows: &[MemoryRecord],
    is_compact: bool,
    snippet_len: usize,
) -> Option<Vec<String>> {
    if rows.is_empty() {
        return None;
    }
    let header = if is_compact {
        format!("=== Feedback preamble ({}) ===", rows.len())
    } else {
        format!(
            "=== Behavioral Feedback Preamble ({} top recent + important) ===",
            rows.len()
        )
    };
    let mut out = vec![header, String::new()];
    out.extend(format_bootstrap_memory_rows(rows, snippet_len));
    out.push(String::new());
    Some(out)
}

/// S1 distillation-candidate picker (design packet
/// `design_s1_distillation_surfacing_arc_20260707`). Propose-only: selects
/// verified, still-undistilled mechanism rows as candidates for manual
/// pub_* distillation; nothing here writes.
///
/// The verified signal spans TWO tag vocabularies — continuity tags on
/// lesson-class rows, verify facets on outcome-class rows; filtering on one
/// alone loses half the ground truth (measured 2026-07-07: recall 2/7 → 4/4).
/// `pub_provenance` = non-pub keys already cited by a pub_* row's
/// related_keys — already-distilled rows leave the queue. `distill:no` is
/// the manual dismissal tag.
///
/// `pub(crate)` since P2: the nightly draft batch (`dream_distill::run`)
/// feeds off the same picker so CLI queue and bootstrap queue can't drift.
pub(crate) fn pick_distillation_candidates(
    rows: Vec<MemoryRecord>,
    pub_provenance: &std::collections::HashSet<String>,
    k: usize,
) -> Vec<MemoryRecord> {
    let mut out: Vec<MemoryRecord> = rows
        .into_iter()
        .filter(memory_record_active)
        .filter(|r| !r.key.starts_with("pub_"))
        .filter(|r| {
            !r.tags
                .iter()
                .any(|t| t == "zone:public" || t == "distill:no")
        })
        .filter(|r| match r.kind.as_str() {
            "lesson" | "error_pattern" => {
                r.tags.iter().any(|t| t == "continuity_confidence:verified")
            }
            "present_outcome" | "outcome" => r.tags.iter().any(|t| t == "verify:verified"),
            _ => false,
        })
        .filter(|r| !pub_provenance.contains(&r.key))
        .collect();
    out.sort_by(|a, b| b.created_at.cmp(&a.created_at).then(a.key.cmp(&b.key)));
    out.truncate(k);
    out
}

/// Formats the S1 "distillation candidates" bootstrap block. Shows each
/// row's blast_radius tag: radius labels are known-miscalibrated against
/// real portability (zones MEASURE, 2026-07-06), so the distiller re-judges
/// radius at distill time. Returns `None` when empty (no hollow header).
fn format_distillation_candidates_block(
    rows: &[MemoryRecord],
    is_compact: bool,
) -> Option<Vec<String>> {
    if rows.is_empty() {
        return None;
    }
    let header = if is_compact {
        format!("=== Distill candidates ({}) ===", rows.len())
    } else {
        format!(
            "=== Distillation candidates ({} — distill to pub_* or dismiss with tag distill:no) ===",
            rows.len()
        )
    };
    let mut out = vec![header];
    for r in rows {
        let radius = r
            .tags
            .iter()
            .find_map(|t| t.strip_prefix("continuity_blast_radius:"))
            .unwrap_or("unlabeled");
        out.push(format!("- {} [{} · radius:{}]", r.key, r.kind, radius));
    }
    out.push(String::new());
    Some(out)
}

/// Formats the P2 "distill drafts pending review" bootstrap block — the
/// review surface over rows the nightly `dream distill` batch wrote. Shows
/// at most `DISTILL_DRAFTS_SHOWN` newest drafts; the queue is self-cleaning
/// (see `dream_distill::pending_distill_drafts`), so a long list means
/// review debt, not staleness. Returns `None` when empty.
fn format_distill_drafts_block(rows: &[MemoryRecord], is_compact: bool) -> Option<Vec<String>> {
    const DISTILL_DRAFTS_SHOWN: usize = 5;
    if rows.is_empty() {
        return None;
    }
    let header = if is_compact {
        format!("=== Distill drafts ({}) ===", rows.len())
    } else {
        format!(
            "=== Distill drafts pending review ({} — memory_get the draft, apply its 评审动作; queue self-clears) ===",
            rows.len()
        )
    };
    let mut out = vec![header];
    for r in rows.iter().take(DISTILL_DRAFTS_SHOWN) {
        let verdict = r
            .tags
            .iter()
            .find_map(|t| t.strip_prefix("verdict:"))
            .unwrap_or("?");
        let target = r
            .tags
            .iter()
            .find_map(|t| {
                t.strip_prefix("proposes:")
                    .or_else(|| t.strip_prefix("merge_into:"))
            })
            .map(|k| format!(" → {k}"))
            .unwrap_or_default();
        out.push(format!("- {} [{verdict}{target}]", r.key));
    }
    if rows.len() > DISTILL_DRAFTS_SHOWN {
        out.push(format!(
            "  …{} more pending (memory_list kind=distill_draft)",
            rows.len() - DISTILL_DRAFTS_SHOWN
        ));
    }
    out.push(String::new());
    Some(out)
}

/// **B1 audit-gap v0 (2026-05-19)** — project-state digest block formatter.
/// Compact "where am I right now" orientation card for session bootstrap.
/// Three buckets (caller-sourced + pre-filtered):
///   - up to 3 most important active `decision` records
///   - up to 1 most recent `session_handoff`
///   - up to 3 most recent active `project` records
///
/// Returns `None` if all three buckets are empty so the caller can skip
/// the section header entirely (no visual noise on fresh stores).
///
/// Refs:
/// - docs/DESIGN-A1-B1-B3-RECALL-TIMING-v0.md §2.3 mechanism
/// - thread 10 #218 (design) + #221/#223 (cross-check) + #249 (act unlock)
fn format_project_state_digest_block(
    decisions: &[MemoryRecord],
    handoffs: &[MemoryRecord],
    projects: &[MemoryRecord],
    is_compact: bool,
    snippet_len: usize,
) -> Option<Vec<String>> {
    if decisions.is_empty() && handoffs.is_empty() && projects.is_empty() {
        return None;
    }
    let total = decisions.len() + handoffs.len() + projects.len();
    let header = if is_compact {
        format!("=== State digest ({total}) ===")
    } else {
        format!(
            "=== Project State Digest ({total} = {}D + {}H + {}P) ===",
            decisions.len(),
            handoffs.len(),
            projects.len()
        )
    };
    let mut out = vec![header, String::new()];
    if !decisions.is_empty() {
        if !is_compact {
            out.push("-- recent important decisions --".to_string());
        }
        out.extend(format_bootstrap_memory_rows(decisions, snippet_len));
    }
    if !handoffs.is_empty() {
        if !is_compact {
            out.push("-- last handoff --".to_string());
        }
        out.extend(format_bootstrap_memory_rows(handoffs, snippet_len));
    }
    if !projects.is_empty() {
        if !is_compact {
            out.push("-- recently touched projects --".to_string());
        }
        out.extend(format_bootstrap_memory_rows(projects, snippet_len));
    }
    out.push(String::new());
    Some(out)
}

// ---------------------------------------------------------------------------
// session_bootstrap per-block token budgets (v0 — 2026-05-17).
//
// Live measurement on 2026-05-17 showed bootstrap output 16,834 chars ≈ 4,810
// tokens, dominated by `format_bootstrap_memory_rows` (top-60 memories with
// 120-char snippets ≈ 3,400 tokens) plus 6+ static blocks.
//
// Budgets below target total p95 ≈ 2,000 tokens (60% reduction). They cap
// each block independently so any single block exceeding its budget gets
// `[...trimmed N more lines for budget]` instead of starving the next block.
//
// Inspired by [rtk-ai/icm](https://github.com/rtk-ai/icm)'s 500-token wake-up
// cap; see `docs/DESIGN-context-lifecycle-edges-2026-05-17.md` §3.6.
const BUDGET_USER_PROFILE: usize = 300;
const BUDGET_AGENT_PROFILE: usize = 300;
const BUDGET_AIOT_SOUL: usize = 200;
const BUDGET_SEED: usize = 200;
const BUDGET_PERCEPTION: usize = 150;
const BUDGET_LETTER_EACH: usize = 150;
const BUDGET_FEEDBACK_PREAMBLE: usize = 300;
const BUDGET_WORK_MEMORY: usize = 260;
const BUDGET_CROSS_NODE_PEERS: usize = 160;
const BUDGET_DECISIONS_DUE: usize = 200;
const BUDGET_ERROR_PATTERNS: usize = 200;
const BUDGET_CONTINUITY_KERNEL: usize = 260;
// S1 distillation surfacing (2026-07-07): header + 3 key lines. Keys are
// ASCII but budget is token-estimated, so CJK-safe by construction.
const BUDGET_DISTILL_CANDIDATES: usize = 120;
// D1 fix (2026-07-06) — separate budget for the kernel INDEX section (the
// one-line-per-row floor for selected rows that lost full-text rendering).
// Measured with `estimate_tokens_from_text` on 34 realistic index lines
// (snake_case keys ~37 chars with date suffix, ≤60-char trigger prefix on
// 3 of 4 rows): header 20 + Σ lines 1044 = 1064 tokens (per line: min 20
// without trigger, max 34 with trigger) — the measurement lives in test
// `continuity_kernel_typical_index_corpus_fits_index_budget`. The typical
// live case demotes ~28 of 34 rows (~900 tokens), so 1100 holds the full
// 34-row measured corpus; anything beyond degrades to the
// `[...N more selected rows omitted, use memory_search]` marker. The
// initially suggested 200 was rejected by measurement — it holds only ~6
// index lines, reintroducing the trace-less-vanish bug for typical load.
const BUDGET_CONTINUITY_KERNEL_INDEX: usize = 1_100;
// P2 draft review surface (2026-07-07): header + ≤5 draft lines + overflow
// marker. Draft keys/verdict targets are ASCII; the full header carries a
// short CJK span (评审动作), so 200 holds the 5-line worst case with room.
const BUDGET_DISTILL_DRAFTS: usize = 200;
const BUDGET_BOOTSTRAP_ROWS: usize = 500;
const BUDGET_GAMMA_BFS: usize = 200;
const BUDGET_DELTA_TRANSITIONS: usize = 150;
const BUDGET_SIBLING_WARN: usize = 200;
// B1 audit-gap v0 (2026-05-19) — project-state digest. 7 rows max
// (3 decisions + 1 handoff + 3 projects) × ~120 char snippets ≈ 200 tokens.
const BUDGET_PROJECT_DIGEST: usize = 220;
const BUDGET_GIT_CURRENTNESS: usize = 120;
// SSB §3.6 (2026-06-15) — recent verify-first NotVerified events surfaced at
// cold start. Top 5 inert/failed actions × ~80 char ≈ 160 tokens; hidden when
// none, so the budget only bites on a session that actually had a no-op.
const BUDGET_INERT_ACTIONS: usize = 200;
const BUDGET_RECOVERY_CANDIDATES: usize = 180;
const APP_CONTROL_RECOVERY_CANDIDATES_SCHEMA: &str = "agent_bridge.app_control.recovery_candidates.v0";

/// Trim a block of lines so the total estimated token count ≤ `budget`.
///
/// Appends `[...trimmed N more lines for budget]` marker when truncated.
/// Keeps the first line (block header) even if the header alone exceeds
/// budget — the header is informational and the trim marker tells the
/// reader the block was cut.
///
/// Cheap path: if `chars / 3 ≤ budget` we know we're under (chars/3 is a
/// pessimistic upper bound for any reasonable text), skip the calibrated
/// estimator entirely.
fn cap_block_lines(lines: Vec<String>, budget: usize) -> Vec<String> {
    if lines.is_empty() || budget == 0 {
        return lines;
    }
    // A caller may pass a multi-line string as a SINGLE element (e.g. an
    // AGENT.md profile body or a soul/seed block). Normalize to real lines so
    // the budget loop can keep a useful PREFIX of an oversized block instead of
    // dropping the whole body atomically — which would emit a hollow header
    // (a header with no content, the "green-but-inert" presentation we forbid).
    // When the block fits, splitting then re-joining on "\n" reproduces the
    // identical text, so this is a no-op for under-budget blocks.
    let lines: Vec<String> = lines
        .into_iter()
        .flat_map(|s| {
            if s.contains('\n') {
                s.split('\n').map(str::to_string).collect::<Vec<_>>()
            } else {
                vec![s]
            }
        })
        .collect();
    // Fast path: pessimistic bound says we're under.
    let total_chars: usize = lines.iter().map(|s| s.chars().count()).sum();
    if total_chars / 3 <= budget {
        return lines;
    }
    // Slow path: use calibrated estimator.
    let joined = lines.join("\n");
    let est = estimate_tokens_from_text(&joined) as usize;
    if est <= budget {
        return lines;
    }
    // Truncate from end, keep accumulating until budget exhausted.
    let mut out: Vec<String> = Vec::with_capacity(lines.len() + 1);
    let mut running: usize = 0;
    let mut kept = 0usize;
    for (i, line) in lines.iter().enumerate() {
        let line_tokens = estimate_tokens_from_text(line) as usize;
        // Always keep the first line (header). After that, stop when we'd
        // exceed budget.
        if i > 0 && running + line_tokens > budget {
            break;
        }
        running += line_tokens;
        out.push(line.clone());
        kept = i + 1;
    }
    let trimmed = lines.len() - kept;
    if trimmed > 0 {
        out.push(format!("  [...trimmed {} more lines for budget]", trimmed));
    }
    out
}

/// SSB lifecycle producer (roadmap §2 "hooks → bus events"): emit a
/// `session_bootstrap` as a typed semantic event on the same unified
/// Object/Affordance contract as browser/desktop/mobile and the symmetric
/// `session_finalize` lifecycle producer. Bootstrap HAS readback (the count of
/// memory rows it surfaced + the assembled payload), so a bootstrap that
/// injected context is Verified; an empty-scope bootstrap injected nothing and
/// is honestly Unknown — never laundered to a green success. Best-effort; the
/// emit failure never affects the bootstrap output.
async fn record_session_bootstrap_event(
    store: &Arc<dyn StateStore>,
    injected: bool,
    memory_rows: usize,
    output_lines: usize,
) {
    let verdict = crate::semantic_event::classify_lifecycle(true, injected, "");
    let ev = crate::semantic_event::SemanticEvent {
        ts: dispatch_now_secs(),
        actor: "mcp".to_string(),
        source: "session".to_string(),
        action: "bootstrap".to_string(),
        target: None,
        object: crate::semantic_event::SemanticObject {
            object_type: "session".to_string(),
            source_adapter: "session".to_string(),
            label: None,
            object_id: None,
        },
        affordance: crate::semantic_event::Affordance {
            action_type: "bootstrap".to_string(),
            risk_level: "low".to_string(),
            requires_gate: false,
            expected_effect: Some("assemble + inject session context".to_string()),
        },
        verdict,
        facts: json!({
            "memory_rows": memory_rows,
            "output_lines": output_lines,
            "injected": injected,
        }),
    };
    if let Err(e) = store.record_semantic_event(ev.to_record()).await {
        tracing::debug!(error = %e, "record_semantic_event (session_bootstrap) failed");
    }
}

