/// Render a non-authoritative hint only. The journal has no workspace identity,
/// so a candidate is never treated as the current intent or dispatch authority.
fn format_bootstrap_recovery_candidates(payload: &Value, is_compact: bool) -> Option<Vec<String>> {
    if payload.get("schema").and_then(Value::as_str) != Some(APP_CONTROL_RECOVERY_CANDIDATES_SCHEMA)
        || payload.get("status").and_then(Value::as_str) != Some("verified")
        || payload.get("verdict").and_then(Value::as_str) != Some("verified")
        || payload.get("recover").and_then(Value::as_str) != Some("proceed")
        || payload.get("read_only").and_then(Value::as_bool) != Some(true)
        || payload.get("scan_complete").and_then(Value::as_bool) != Some(true)
        || payload.get("media_observed").and_then(Value::as_bool) != Some(false)
        || payload.get("action_invoked").and_then(Value::as_bool) != Some(false)
        || payload.get("automatic_recovery_authorized").and_then(Value::as_bool) != Some(false)
        || payload.get("admission").and_then(Value::as_str) != Some("eligible_candidate_present")
        || payload.get("selection_requested").and_then(Value::as_bool) != Some(false)
    { return None; }
    let candidates = payload.get("candidates")?.as_array()?;
    if candidates.is_empty() || candidates.len() > 64
        || payload.get("candidate_count").and_then(Value::as_u64) != Some(candidates.len() as u64)
    { return None; }
    let mut rendered = Vec::new();
    for candidate in candidates.iter().take(3) {
        let operation_id = candidate.get("operation_id")?.as_str()?;
        let record_sha256 = candidate.get("record_sha256")?.as_str()?;
        let request_digest = candidate.get("request_digest")?.as_str()?;
        let request = candidate.get("request")?.as_object()?;
        let player = request.get("player_selector")?.as_str()?;
        let ttl = request.get("operation_ttl_secs")?.as_u64()?;
        let remaining = candidate.get("remaining_secs")?.as_f64()?;
        let lowercase_hex = |value: &str, len| value.len() == len
            && value.bytes().all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase());
        if !operation_id.starts_with("ab-episode-") || operation_id.len() != 43
            || !lowercase_hex(&operation_id[11..], 32)
            || !lowercase_hex(record_sha256, 64) || !lowercase_hex(request_digest, 64)
            || request.get("schema").and_then(Value::as_str) != Some("agent_bridge.app_control.v0")
            || request.get("action").and_then(Value::as_str) != Some("next")
            || candidate.get("phase").and_then(Value::as_str) != Some("dispatch_started")
            || candidate.get("dispatch_count").and_then(Value::as_u64) != Some(1)
            || candidate.get("discovery_only").and_then(Value::as_bool) != Some(true)
            || candidate.get("revalidation_required").and_then(Value::as_bool) != Some(true)
            || candidate.get("automatic_execution_allowed").and_then(Value::as_bool) != Some(false)
            || player.is_empty() || ttl == 0 || !remaining.is_finite() || remaining <= 0.0
        { return None; }
        let player = serde_json::to_string(player).ok()?;
        rendered.push(format!("  • operation_id={operation_id} player={player} ttl={ttl}s remaining≈{}s record_sha256={record_sha256}", remaining.floor() as u64));
    }
    let mut out = vec![if is_compact {
        format!("=== Media recovery candidates ({}) — not selected ===", candidates.len())
    } else {
        format!("=== Durable Media Recovery Candidates ({}) — read-only, not selected ===", candidates.len())
    }];
    out.push("Current workspace/intent binding: unverified. Automatic execution: forbidden.".into());
    out.extend(rendered);
    if candidates.len() > 3 { out.push(format!("  … {} more candidate(s) omitted", candidates.len() - 3)); }
    out.push("Next: explicitly review one candidate, then revalidate its exact operation_id + record_sha256 before using the normal recovery path.".into());
    out.push(String::new());
    Some(out)
}

async fn bootstrap_recovery_candidates_block(is_compact: bool) -> Option<Vec<String>> {
    let journal = std::env::var("AB_APP_CONTROL_OPERATION_DIR").ok()?;
    if journal.trim().is_empty() || !Path::new(&journal).is_absolute() { return None; }
    let script = app_control_recovery_candidates_script_path();
    if !script.is_file() { return None; }
    let mut cmd = killable_command(std::env::var("PYTHON").ok()
        .filter(|value| !value.trim().is_empty()).unwrap_or_else(|| "python3".into()));
    cmd.arg(script).arg("--journal").arg(journal)
        .arg("--minimum-recovery-secs").arg("5")
        .stdout(std::process::Stdio::piped()).stderr(std::process::Stdio::null());
    let output = tokio::time::timeout(Duration::from_millis(1_500), cmd.output()).await.ok()?.ok()?;
    if !output.status.success() || output.stdout.len() > 256 * 1024 { return None; }
    format_bootstrap_recovery_candidates(&serde_json::from_slice(&output.stdout).ok()?, is_compact)
}

/// A bootstrap with an explicit task query is a recovery packet, not a general
/// cold-start dashboard. Keep the sections that answer "where am I and what
/// blocks this task?" while leaving global letters and the
/// research/curation/associative panels to static bootstraps. This applies to
/// every frontend: a full Codex/Claude rendering must not re-introduce global
/// auxiliary state that compact Warp/Cursor recovery already omits.
fn include_bootstrap_auxiliary_sections(has_query: bool) -> bool {
    !has_query
}

impl SessionBootstrapTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for SessionBootstrapTool {
    fn name(&self) -> &'static str {
        "session_bootstrap"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Build a compact memory bootstrap block. Returns top scoped \
                 memories (global + project). Current actionable exact-project \
                 session_handoff rows receive priority; auto-curated, unverified, \
                 background/archive, stale, global, and cross-project handoffs do not. query= enables \
                 semantic ranking. frontend='cursor'|'warp' uses compact format; default \
                 'claude-code' is full. For every frontend, an explicit query produces a \
                 task-recovery packet that omits global past-self letters, AiOT/Seed/perception, \
                 curation, review, and associative panels. A bootstrap without a query retains \
                 those auxiliary sections. Stable User and Agent Profile sections are unaffected. \
                 When the outcome collector \
                 (AGENT_BRIDGE_OUTCOME_COLLECTOR) is on, the semantic page is logged to \
                 retrieval_surfacing as mode=bootstrap — telemetry-only (excluded from \
                 reinforce/decay aggregates until a calibrated ambient rule exists); \
                 AB_BOOTSTRAP_SURFACING_DISABLE=1 turns just this writer off. The \
                 semantic page is MMR diversity re-ranked (default on, lambda=0.7; \
                 AB_BOOTSTRAP_MMR_DISABLE=1 restores plain score order, \
                 AB_BOOTSTRAP_MMR_LAMBDA overrides lambda). Also \
                 surfaces an S1 distillation-candidates block (propose-only; \
                 AB_DISTILL_SURFACING_DISABLE=1 drops it). Any bootstrap may also \
                 surface read-only durable-media recovery candidates when the \
                 owner-only journal is configured; these remain unselected, are not \
                 workspace/current-intent bound, never authorize execution, and require \
                 exact operation_id + record_sha256 revalidation. Query-targeted \
                 bootstraps retain this bounded safety hint while continuing to omit \
                 unrelated global auxiliary panels."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "cwd": { "type": "string", "description": "Optional project path for scope filtering. Defaults to process cwd." },
                    "limit": { "type": "integer", "minimum": 1, "maximum": 200, "default": 60 },
                    "query": {
                        "type": "string",
                        "description": "Optional natural-language description of the current task (e.g. 'fix Warp IPC socket reconnect bug'). When provided, memories are ranked by semantic similarity instead of static importance. Only current actionable exact-project session_handoff rows receive prefix priority."
                    },
                    "frontend": {
                        "type": "string",
                        "enum": ["claude-code", "cursor", "warp", "auto"],
                        "default": "auto",
                        "description": "Output format: 'cursor'/'warp' for compact, 'claude-code' for full, 'auto' detects from env."
                    },
                    "error_hint": {
                        "type": "string",
                        "description": "Optional error text (e.g. last command stderr). When set, surfaces active kind=error_pattern memories whose non-empty trigger_pattern appears as a substring in this hint (case-insensitive)."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let cwd = args
            .get("cwd")
            .and_then(|v| v.as_str())
            .map(|s| s.to_string())
            .or_else(|| {
                std::env::current_dir()
                    .ok()
                    .map(|p| p.display().to_string())
            })
            .unwrap_or_else(|| "/".to_string());
        let limit = args
            .get("limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(60)
            .min(200) as u32;

        // R3 MMR switches: read env once at entry, pass plain values down so
        // the re-rank itself stays a pure, directly testable function
        // (same handling as AGENT_BRIDGE_FTS_OR_PRIMARY in memory_search).
        let mmr_disabled = bootstrap_mmr_disabled();
        let mmr_lambda = bootstrap_mmr_lambda();

        // Detect frontend: explicit arg > env var > default (claude-code).
        // Both `cursor` and `warp` use the compact output format (Warp
        // surfaces tool output in the Block UI where vertical space is
        // at a premium, just like Cursor's inline panel).
        let frontend = args
            .get("frontend")
            .and_then(|v| v.as_str())
            .unwrap_or("auto");
        let is_compact = match frontend {
            "cursor" | "warp" => true,
            "claude-code" => false,
            _ => detect_frontend() != "claude-code" && detect_frontend() != "unknown",
        };

        let snippet_len = if is_compact { 80 } else { 120 };

        let error_hint = args
            .get("error_hint")
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty());

        let mut error_section: Vec<String> = Vec::new();
        if let Some(hint) = error_hint {
            let hint_lc = hint.to_lowercase();
            let ep_rows = store
                .list_memories_in_scope(
                    &cwd,
                    Some("error_pattern"),
                    MemoryListSort::ByImportance,
                    80,
                )
                .await?;
            let ep_rows: Vec<_> = ep_rows
                .into_iter()
                .filter(|r| r.status == "active")
                .filter(|r| {
                    r.trigger_pattern.as_ref().is_some_and(|p| {
                        let pl = p.trim().to_lowercase();
                        !pl.is_empty() && hint_lc.contains(&pl)
                    })
                })
                .collect();
            if !ep_rows.is_empty() {
                error_section.push(if is_compact {
                    "=== Error patterns (hint) ===".to_string()
                } else {
                    "=== Error patterns (matched error_hint) ===".to_string()
                });
                error_section.push(String::new());
                error_section.extend(format_bootstrap_memory_rows(&ep_rows, snippet_len));
                error_section.push(String::new());
            }
        }

        // Optional semantic query: rank by cosine similarity when provided.
        let query = args
            .get("query")
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(str::to_string);
        let include_auxiliary_sections = include_bootstrap_auxiliary_sections(query.is_some());
        // Recovery discovery is a bounded safety hint rather than a global
        // auxiliary dashboard. Keep it on task-targeted bootstraps (including
        // the default UserPromptSubmit hook path) without reintroducing the
        // letters/research/curation panels that compact recovery omits.
        let recovery_candidates_block = bootstrap_recovery_candidates_block(is_compact).await;

        let rows: Vec<MemoryRecord> = if let Some(ref q) = query {
            // Semantic path: cosine-ranked results, with only current,
            // actionable, exact-project handoffs prepended.
            let semantic_hits = store
                .memory_search_semantic_in_scope(q, &cwd, limit, 0.15)
                .await
                .unwrap_or_default();
            let mut ranked: Vec<MemorySearchHit> = semantic_hits
                .into_iter()
                .filter(|h| h.record.status == "active")
                .collect();
            // Handoffs that fail the priority gate remain eligible for normal
            // semantic ranking; they simply cannot displace current state by
            // kind alone.
            let handoff = store
                .list_memories_in_scope(&cwd, Some("session_handoff"), MemoryListSort::Recent, 8)
                .await
                .unwrap_or_default()
                .into_iter()
                .filter(|r| r.status == "active")
                .filter(|r| bootstrap_handoff_priority_eligible(r, &cwd))
                .collect::<Vec<_>>();
            let handoff_keys: std::collections::HashSet<_> =
                handoff.iter().map(|r| r.key.clone()).collect();
            ranked.retain(|h| !handoff_keys.contains(&h.record.key));
            // R3 (forum #147, default ON): MMR diversity re-rank of the
            // semantic page, applied before the final truncation so dropping
            // near-duplicates actually frees page slots for diverse rows.
            // Scope: this block only — the handoff prefix above keeps its
            // "always prepended" contract and the error_pattern section is
            // untouched. Relevance is the existing semantic blend score.
            if !mmr_disabled {
                let texts: Vec<&str> = ranked.iter().map(|h| h.record.content.as_str()).collect();
                let relevance: Vec<f64> = ranked.iter().map(|h| h.score).collect();
                let order = mmr_rerank_by_text(&texts, &relevance, mmr_lambda);
                let mut slots: Vec<Option<MemorySearchHit>> =
                    ranked.into_iter().map(Some).collect();
                ranked = order.into_iter().filter_map(|i| slots[i].take()).collect();
            }
            let mut combined = handoff;
            combined.extend(ranked.into_iter().map(|h| h.record));
            combined.truncate(limit as usize);
            combined
        } else {
            // Static path: float only handoffs that pass the same gate.
            let rows = store
                .list_memories_in_scope(&cwd, None, MemoryListSort::ByImportance, limit)
                .await?;
            let rows: Vec<_> = rows.into_iter().filter(|r| r.status == "active").collect();
            prioritize_bootstrap_handoffs(rows, &cwd)
        };

        // Outcome-collector, ambient leg (stage 1, 2026-07-05): log the
        // semantic bootstrap page to `retrieval_surfacing` under
        // AMBIENT_SURFACING_MODE so injected rows participate in used_at
        // attribution at all — hook v5.0 made this page the primary ambient
        // read path, and it was the learning loop's largest blind spot.
        // Telemetry-only: every reinforce/decay aggregate excludes this mode
        // until a calibrated bootstrap rule exists (stage 2), and the apply
        // pass retires the rows, so nothing here can move importance.
        // Conventions mirror the memory_search writer: the logged set is the
        // page the caller actually receives (post dedup/truncate — review
        // G-1/C-2), minus `kind=skill` (Phase 1 P1.5). Both this and the
        // record_session_bootstrap_event readback draw from the same `rows`
        // vec, but the readback counts skill rows and this filter drops
        // them, so the two counts diverge by exactly the on-page skill rows;
        // the per-block line budget can also trim tail lines at render,
        // which this deliberately ignores (bounded, display-only skew).
        // Static (no-query) pages are importance-sorted furniture, not
        // ranked retrieval — never logged.
        if query.is_some()
            && outcome_collector_enabled()
            && !ambient_surfacing_disabled()
            && !rows.is_empty()
        {
            let surfaced: Vec<(String, i64)> = rows
                .iter()
                .filter(|r| r.kind != "skill")
                .enumerate()
                .map(|(i, r)| (r.key.clone(), i as i64))
                .collect();
            if !surfaced.is_empty() {
                let store_clone = store.clone();
                let q_owned = query.clone().unwrap_or_default();
                let traffic_class = retrieval_traffic_class().to_string();
                tokio::spawn(async move {
                    let _ = store_clone
                        .record_retrieval_surfacing_classified(
                            &surfaced,
                            &q_owned,
                            AMBIENT_SURFACING_MODE,
                            &traffic_class,
                        )
                        .await;
                });
            }
        }

        if rows.is_empty() && error_section.is_empty() && recovery_candidates_block.is_none() {
            let lifecycle_hint = session_lifecycle_hint();
            // SSB lifecycle producer: an empty-scope bootstrap injected nothing,
            // so it is honestly Unknown (ran, no effect) — not laundered green.
            record_session_bootstrap_event(&store, false, 0, 0).await;
            return Ok(ToolResult::text(format!(
                "(no scoped memories yet)\n\n{lifecycle_hint}"
            )));
        }

        let mode_tag = if query.is_some() { " | semantic" } else { "" };
        let mut lines = if is_compact {
            vec![
                format!("=== Bootstrap (scope: {}{mode_tag}) ===", cwd),
                String::new(),
            ]
        } else {
            vec![
                format!("=== Agent-Bridge Session Bootstrap (scope: {cwd}{mode_tag}) ==="),
                "Use memory_get <key> for full content, memory_search for lookup.".to_string(),
                String::new(),
            ]
        };

        // Agent-facing orientation guard. This is read-only and deliberately
        // uses only local refs: bootstrap must never fetch, switch, reset, or
        // turn a possibly dirty feature checkout into an implicit mutation.
        if let Some(state) = session_git_currentness(std::path::Path::new(&cwd)) {
            let warnings = state["warnings"]
                .as_array()
                .map(|xs| {
                    xs.iter()
                        .filter_map(|x| x.as_str())
                        .collect::<Vec<_>>()
                        .join(", ")
                })
                .unwrap_or_default();
            let mut block = vec![
                "=== Git Currentness Warning (read-only) ===".to_string(),
                format!(
                    "branch={} head={} target={} ahead={} behind={} clean={} warnings={}",
                    state["branch"].as_str().unwrap_or("?"),
                    state["head"]
                        .as_str()
                        .unwrap_or("?")
                        .chars()
                        .take(12)
                        .collect::<String>(),
                    state["target_ref"].as_str().unwrap_or("?"),
                    state["ahead"].as_u64().unwrap_or(0),
                    state["behind"].as_u64().unwrap_or(0),
                    state["clean"].as_bool().unwrap_or(false),
                    warnings,
                ),
            ];
            if let Some(recovery) = state["recovery_worktree"].as_object() {
                block.push(format!(
                    "local_recovery_candidate={} branch={} head={} ahead={} behind=0 clean=true",
                    recovery
                        .get("path")
                        .and_then(|v| v.as_str())
                        .unwrap_or("?"),
                    recovery
                        .get("branch")
                        .and_then(|v| v.as_str())
                        .unwrap_or("?"),
                    recovery
                        .get("head")
                        .and_then(|v| v.as_str())
                        .unwrap_or("?")
                        .chars()
                        .take(12)
                        .collect::<String>(),
                    recovery
                        .get("ahead")
                        .and_then(|v| v.as_u64())
                        .unwrap_or(0),
                ));
                block.push(
                    "Consider resuming from that local integration worktree; verify intent first. No Git state was changed."
                        .to_string(),
                );
            } else {
                block.push(
                    "Verify the intended worktree/branch before continuing; no safe local integration worktree was identified and no Git state was changed."
                        .to_string(),
                );
            }
            block.push(String::new());
            lines.extend(cap_block_lines(block, BUDGET_GIT_CURRENTNESS));
        }

        // Inject USER.md profile if present.
        if let Ok(profile) = std::fs::read_to_string(user_profile_path()) {
            if !profile.trim().is_empty() {
                let block = vec![
                    "=== User Profile ===".to_string(),
                    profile.trim().to_string(),
                    "=== End User Profile ===".to_string(),
                    String::new(),
                ];
                lines.extend(cap_block_lines(block, BUDGET_USER_PROFILE));
            }
        }

        // Inject AGENT.md self-profile if present — this is the agent's own
        // values / working style / self-observations, companion to USER.md.
        // Maintained by the agent itself via session_finalize(agent_profile=...).
        if let Ok(profile) = std::fs::read_to_string(agent_profile_path()) {
            if !profile.trim().is_empty() {
                let block = vec![
                    "=== Agent Self-Profile ===".to_string(),
                    profile.trim().to_string(),
                    "=== End Agent Self-Profile ===".to_string(),
                    String::new(),
                ];
                lines.extend(cap_block_lines(block, BUDGET_AGENT_PROFILE));
            }
        }

        // Inject AiOT Soul state if available — the carrier identity
        // that AiOT's identity_anchor.py has been accumulating across
        // sessions. Read-only Phase α′ bridge; the actual EMA update
        // logic stays on AiOT side. This makes the 21-month trajectory
        // tangible at the level of working state, not just memory text.
        if include_auxiliary_sections {
            if let Some(soul_block) = format_aiot_soul_block() {
                let block = vec![
                    "=== AiOT Soul (read-only carrier identity from /Data/CascadeProjects/AiOT) ==="
                        .to_string(),
                    soul_block,
                    "=== End AiOT Soul ===".to_string(),
                    String::new(),
                ];
                lines.extend(cap_block_lines(block, BUDGET_AIOT_SOUL));
            }
        }

        // Inject Agent-Bridge Seed sidecar grid state if available — symmetric
        // to AiOT Soul. AiOT Soul = Python EMA on AiOT carrier trajectory;
        // Agent-Bridge Seed = Rust DynamicGrid self-organizing on the
        // agent-bridge memory stream. Both are read-only views of "another
        // substrate's identity" — together they triangulate self across
        // markdown / Python EMA / Rust grid. See
        // `plan_seed_integration_gaps_20260504`.
        if include_auxiliary_sections {
            if let Some(seed_block) = format_agent_bridge_seed_block() {
                let block = vec![
                    "=== Agent-Bridge Seed (self-organized network on memory stream) ==="
                        .to_string(),
                    seed_block,
                    "=== End Seed ===".to_string(),
                    String::new(),
                ];
                lines.extend(cap_block_lines(block, BUDGET_SEED));
            }
        }

        // Inject Perception Filter (path B) state if available — parallel
        // learned-encoder + thermodynamic-filter substrate. Read-only, same
        // as the 32-d Seed above. Together they cross-validate "what does the
        // current memory corpus look like to a self-organizing network?"
        // Model and dim are dynamic (env-overridable in the sidecar) — the
        // body of the block carries the ground-truth `model=... ({dim}d)`.
        if include_auxiliary_sections {
            if let Some(pf_block) = format_perception_filter_block() {
                let block = vec![
                    "=== Perception Filter (thermodynamic surprisal filter on memory stream) ==="
                        .to_string(),
                    pf_block,
                    "=== End Perception Filter ===".to_string(),
                    String::new(),
                ];
                lines.extend(cap_block_lines(block, BUDGET_PERCEPTION));
            }
        }

        // Inject up to 3 most recent letter-to-future-self entries.
        // Letters are written by the agent via session_finalize(letter=...);
        // they sit between AGENT.md (stable identity) and memory rows
        // (specific knowledge). They carry "what I was thinking last time"
        // — momentary state that AGENT.md doesn't and shouldn't capture.
        if include_auxiliary_sections {
            for path in recent_letters(3) {
                if let Ok(body) = std::fs::read_to_string(&path) {
                    let stem = path
                        .file_stem()
                        .and_then(|s| s.to_str())
                        .unwrap_or("letter");
                    let block = vec![
                        format!("=== Letter from past-self ({stem}) ==="),
                        body.trim().to_string(),
                        "=== End Letter ===".to_string(),
                        String::new(),
                    ];
                    lines.extend(cap_block_lines(block, BUDGET_LETTER_EACH));
                }
            }
        }

        // L5 P3 — feedback preamble. Surface top-K behavioral feedback
        // memories (recent + high-importance) at session start so the
        // assistant lands with corrections in awareness before any
        // search query. Companion to L5 P1 (FTS retrieval boost) and
        // L5 P2 (memory_correction MCP tool). K=5 is the v0 default;
        // tune via L5-P1 30d measurement.
        if include_auxiliary_sections {
            let now_ts = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_secs() as i64;
            let feedback_pool = store
                .list_memories_in_scope(&cwd, Some("feedback"), MemoryListSort::ByImportance, 30)
                .await
                .unwrap_or_default();
            let picked = pick_top_feedback(feedback_pool, 5, now_ts);
            if let Some(block) = format_feedback_preamble_block(&picked, is_compact, snippet_len) {
                lines.extend(cap_block_lines(block, BUDGET_FEEDBACK_PREAMBLE));
            }
        }

        // S1 distillation surfacing — propose-only queue of verified,
        // still-undistilled mechanism rows for manual pub_* distillation
        // (design_s1_distillation_surfacing_arc_20260707). Scope-less pools:
        // pub_* rows live under domain:* scopes and candidates under project
        // scopes, so the in-scope list would miss both.
        if include_auxiliary_sections && !distill_surfacing_disabled() {
            let mut pool: Vec<MemoryRecord> = Vec::new();
            for kind in ["lesson", "error_pattern", "present_outcome", "outcome"] {
                pool.extend(
                    store
                        .list_memories(Some(kind), MemoryListSort::Newest, 200)
                        .await
                        .unwrap_or_default(),
                );
            }
            let draft_rows = store
                .list_memories(
                    Some(crate::dream_distill::DRAFT_KIND),
                    MemoryListSort::Newest,
                    100,
                )
                .await
                .unwrap_or_default();
            let pub_provenance: std::collections::HashSet<String> = pool
                .iter()
                .filter(|r| r.key.starts_with("pub_"))
                .flat_map(|r| r.related_keys.iter().cloned())
                .filter(|k| !k.starts_with("pub_"))
                .collect();
            let sources_distill_no: std::collections::HashSet<String> = pool
                .iter()
                .filter(|r| r.tags.iter().any(|t| t == "distill:no"))
                .map(|r| r.key.clone())
                .collect();
            // P2: a drafted candidate's surfaced item is its DRAFT row (the
            // review block below) — exclude it here so one mechanism never
            // occupies two queue slots at once.
            let mut exclusion = pub_provenance.clone();
            exclusion.extend(crate::dream_distill::drafted_source_keys(&draft_rows));
            let picked = pick_distillation_candidates(pool, &exclusion, 3);
            if let Some(block) = format_distillation_candidates_block(&picked, is_compact) {
                lines.extend(cap_block_lines(block, BUDGET_DISTILL_CANDIDATES));
            }
            // P2 review surface — pending drafts from the nightly
            // `dream distill` batch; self-cleaning, see
            // `dream_distill::pending_distill_drafts` for exit conditions.
            let pending = crate::dream_distill::pending_distill_drafts(
                draft_rows,
                &pub_provenance,
                &sources_distill_no,
            );
            if let Some(block) = format_distill_drafts_block(&pending, is_compact) {
                lines.extend(cap_block_lines(block, BUDGET_DISTILL_DRAFTS));
            }
        }

        // Active work memory is a short-lived scratchpad for the task in
        // flight. It is intentionally separate from durable lesson/decision
        // rows so context-compaction recovery does not pollute long-term memory.
        {
            let work_rows = store
                .list_memories_in_scope(&cwd, Some(WORK_MEMORY_KIND), MemoryListSort::Recent, 8)
                .await
                .unwrap_or_default();
            let work_rows = bootstrap_work_memory_rows(work_rows, &cwd, unix_now_secs());
            if let Some(block) = format_work_memory_block(&work_rows, is_compact, 180) {
                lines.extend(cap_block_lines(block, BUDGET_WORK_MEMORY));
            }

            // Cross-node wake (auto-surface): lanes a SIBLING NODE updated for this
            // same project (e.g. an aio2 session's project:/Data/... lane aliased
            // to this Mac session's project). The work_memory block above is
            // exact-scope and same-node only; this block makes a starting session
            // PERCEIVE peer activity without an explicit `work_memory op=peers`
            // call. Pull/turn-driven: shows lanes already synced into the local
            // store. Gated on the scope-alias registry (no aliases = no cross-node).
            if let Some(aliases) = std::env::var(PROJECT_SCOPE_ALIASES_ENV)
                .ok()
                .filter(|s| !s.trim().is_empty())
            {
                let broad = store
                    .list_memories(
                        Some(WORK_MEMORY_KIND),
                        MemoryListSort::Recent,
                        WORK_MEMORY_ALIAS_FANIN_SCAN,
                    )
                    .await
                    .unwrap_or_default();
                let peers = cross_node_peer_lanes(&work_memory_scope(&cwd), broad, &aliases, 0, 3);
                if let Some(block) = format_cross_node_peer_block(&peers, is_compact) {
                    lines.extend(cap_block_lines(block, BUDGET_CROSS_NODE_PEERS));
                }
            }
        }

        if let Some(block) = recovery_candidates_block {
            lines.extend(cap_block_lines(block, BUDGET_RECOVERY_CANDIDATES));
        }

        // B1 audit-gap v0 — project-state digest. Compact "where am I right
        // now" card: top-3 important decisions + last handoff + top-3 recently-
        // touched projects. Different from "Decisions Due for Review" (which
        // is review-cycle-driven, not importance/recency-driven) and from the
        // main bootstrap rows (mixed-kind, top-60, low compression). This
        // block answers the orientation question first.
        //
        // Refs: docs/DESIGN-A1-B1-B3-RECALL-TIMING-v0.md §2.3, thread 10 #218/#249.
        {
            let decision_pool = store
                .list_memories_in_scope(&cwd, Some("decision"), MemoryListSort::ByImportance, 12)
                .await
                .unwrap_or_default();
            let decisions_picked: Vec<MemoryRecord> = decision_pool
                .into_iter()
                .filter(|r| r.status == "active" && r.importance >= 0.6)
                .take(3)
                .collect();
            let handoff_pool = store
                .list_memories_in_scope(&cwd, Some("session_handoff"), MemoryListSort::Recent, 5)
                .await
                .unwrap_or_default();
            let handoffs_picked: Vec<MemoryRecord> = handoff_pool
                .into_iter()
                .filter(|r| bootstrap_handoff_priority_eligible(r, &cwd))
                .take(1)
                .collect();
            let project_pool = store
                .list_memories_in_scope(&cwd, Some("project"), MemoryListSort::Recent, 12)
                .await
                .unwrap_or_default();
            let projects_picked: Vec<MemoryRecord> = project_pool
                .into_iter()
                .filter(|r| r.status == "active")
                .take(3)
                .collect();
            if let Some(block) = format_project_state_digest_block(
                &decisions_picked,
                &handoffs_picked,
                &projects_picked,
                is_compact,
                snippet_len,
            ) {
                lines.extend(cap_block_lines(block, BUDGET_PROJECT_DIGEST));
            }
        }

        // Inject "Decisions Due for Review" — closes the reflection loop in
        // the dual-mechanism continuity architecture. Decisions tagged with
        // `review:Nd` re-surface here once they exceed their review interval.
        // Hidden when nothing is due (avoids visual noise on fresh sessions).
        if include_auxiliary_sections {
            let now_ts = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_secs() as i64;
            let decision_pool = store
                .list_memories_in_scope(&cwd, Some("decision"), MemoryListSort::Newest, 200)
                .await
                .unwrap_or_default()
                .into_iter()
                .filter(|r| r.status == "active")
                .collect::<Vec<_>>();
            if let Some(block) = format_due_review_block(&decision_pool, now_ts) {
                let count = block.matches("\n- ").count() + 1;
                let block_lines = vec![
                    format!("=== Decisions Due for Review ({count}) ==="),
                    block,
                    "=== End Reviews ===".to_string(),
                    String::new(),
                ];
                lines.extend(cap_block_lines(block_lines, BUDGET_DECISIONS_DUE));
            }
        }

        // SSB §3.6 — surface recent verify-first NotVerified events at cold
        // start. An action that was inert / failed / refused last session (the
        // anti-laundering signal the producers emit) is shown here instead of
        // staying buried in the semantic_events log — closing the loop from
        // bus event → presentation/handoff surface. Hidden when none (clean
        // session). Best-effort; a read failure never blocks bootstrap.
        if include_auxiliary_sections {
            let now_ts = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|d| d.as_secs() as i64)
                .unwrap_or(0);
            if let Ok(evs) = store.recent_semantic_events(7 * 86400, 100).await {
                if let Some(block) = format_inert_actions_block(&evs, now_ts, 5) {
                    lines.extend(cap_block_lines(block, BUDGET_INERT_ACTIONS));
                }
            }

            // SSB "memory" arm (`… → Verification → Memory`) — distill the whole
            // retained verify-first log into failure MODES that *recur*, so a
            // systematic inert pattern surfaces as a learned lesson rather than
            // just the last few one-off failures the recency block above shows.
            // Wider window (the retained ring IS the cross-session memory
            // substrate) + a recurrence floor so one-offs never become noise.
            // Best-effort; a read failure never blocks bootstrap.
            if let Ok(evs) = store.recent_semantic_events(90 * 86400, 500).await {
                if let Some(block) = format_recurring_inert_block(&evs, now_ts, 3, 3) {
                    lines.extend(cap_block_lines(block, BUDGET_INERT_ACTIONS));
                }
            }
        }

        lines.extend(cap_block_lines(error_section, BUDGET_ERROR_PATTERNS));
        // D1: the kernel block self-accounts (full rows vs index floor) —
        // routing it through cap_block_lines again would re-truncate the
        // index lines the floor exists to protect.
        if let Some(block) = format_continuity_kernel_block(
            &rows,
            is_compact,
            snippet_len,
            BUDGET_CONTINUITY_KERNEL,
            BUDGET_CONTINUITY_KERNEL_INDEX,
        ) {
            lines.extend(block);
        }
        // Work memory already has a resume-aware block above. Exclude it from
        // the generic prefix-snippet list so bootstrap does not duplicate the
        // same lane with metadata (`cwd`, slot, timestamp) instead of its
        // actionable Summary/Next Step or precompact tail.
        let regular_rows: Vec<MemoryRecord> = rows
            .iter()
            .filter(|row| row.kind != WORK_MEMORY_KIND)
            .cloned()
            .collect();
        lines.extend(cap_block_lines(
            format_bootstrap_memory_rows(&regular_rows, snippet_len),
            BUDGET_BOOTSTRAP_ROWS,
        ));
        lines.push("=== End Bootstrap ===".to_string());
        lines.push(String::new());

        // γ' wiring (2026-05-10) — surface high-energy neighbors of recent
        // high-importance seeds via memory_neighbors_bfs. Engine (α
        // coactivation, β cofires, P4 evolved edges) is already built; this
        // injects its output into cold-start payload. See
        // `design_gamma_scope_revision_after_beta_dogfood_20260510` for why
        // γ became wiring instead of a prediction engine. Best-effort —
        // failures don't block bootstrap.
        if include_auxiliary_sections {
            if let Ok(section) =
                crate::bootstrap_bfs::compute_section(store.as_ref(), &cwd, is_compact).await
            {
                lines.extend(cap_block_lines(section, BUDGET_GAMMA_BFS));
            }
        }

        // δ-4 PP-1 lift (2026-05-11) — surface repeated next-step transitions
        // from recent memory_get events as a predicted-next signal. Bumps the
        // Butlin PP-1 indicator from medium → strong by giving cold-start a
        // temporal-asymmetric "after A, B usually follows" line. Best-effort.
        if include_auxiliary_sections {
            if let Ok(section) =
                crate::bootstrap_transitions::compute_section(store.as_ref(), is_compact).await
            {
                lines.extend(cap_block_lines(section, BUDGET_DELTA_TRANSITIONS));
            }
        }

        // ε-5 (2026-05-11) — sibling-presence warning. Two agents in the
        // same working tree + git index will sweep each other's unstaged
        // changes (top-9 Hebbian pair: `lesson_sibling_parallel_commits` ↔
        // `lesson_git_commit_by_path_overrides_apply_cached`). When another
        // agent has heartbeat in this project within the last 5 minutes,
        // emit a loud warning + the worktree-session recipe. Best-effort.
        {
            let project_slug = std::path::Path::new(&cwd)
                .file_name()
                .and_then(|n| n.to_str().map(|s| s.to_string()))
                .unwrap_or_default();
            if !project_slug.is_empty() {
                if let Ok(live) = store
                    .agent_presence_list(Some(&project_slug), None, 300, 50)
                    .await
                {
                    let my_sid = std::env::var("CLAUDE_SESSION_ID")
                        .ok()
                        .or_else(|| std::env::var("AGENT_BRIDGE_SESSION_ID").ok());
                    let peers: Vec<&ab_store::AgentPresenceRecord> = live
                        .iter()
                        .filter(|r| my_sid.as_deref().map(|m| r.session_id != m).unwrap_or(true))
                        .collect();
                    if !peers.is_empty() {
                        let now_ts = std::time::SystemTime::now()
                            .duration_since(std::time::UNIX_EPOCH)
                            .map(|d| d.as_secs() as i64)
                            .unwrap_or(0);
                        let mut block = vec![
                            if is_compact {
                                format!(
                                    "=== ⚠ Sibling agents ({}) — risk of sweep ===",
                                    peers.len()
                                )
                            } else {
                                format!(
                                    "=== ⚠ Sibling-Presence Warning ({} other agent{} in '{}') ===",
                                    peers.len(),
                                    if peers.len() == 1 { "" } else { "s" },
                                    project_slug
                                )
                            },
                            String::new(),
                        ];
                        for p in peers.iter().take(5) {
                            let age = (now_ts - p.last_heartbeat_at).max(0);
                            block.push(format!("  • {} (heartbeat {}s ago)", p.session_id, age));
                        }
                        block.push(String::new());
                        if !is_compact {
                            block.push(
                                "  Sharing a working tree + git index → `git add/commit` may sweep"
                                    .to_string(),
                            );
                            block.push(
                                "  the other agent's unstaged changes (see `lesson_sibling_parallel_commits`)."
                                    .to_string(),
                            );
                        }
                        block.push(
                            "  Isolate: `agent-bridge worktree-session new --name <slug>`"
                                .to_string(),
                        );
                        block.push(String::new());
                        lines.extend(cap_block_lines(block, BUDGET_SIBLING_WARN));
                    }
                }
            }
        }

        lines.push(session_lifecycle_hint());

        // D2.3: prime the embedding cache in the background so subsequent
        // memory_search(mode=semantic) calls skip the DB round-trip.
        {
            let prefetch_store = store.clone();
            let prefetch_cache = self.hub.memory_embed_cache.clone();
            tokio::spawn(async move {
                if let Ok(rows) = prefetch_store.memory_load_embeddings().await {
                    let mut guard = prefetch_cache.lock().await;
                    *guard = Some(rows);
                }
            });
        }

        // SSB lifecycle producer: this bootstrap assembled and injected real
        // context (memory rows + blocks), so it is Verified — readback is the
        // surfaced row count + the assembled payload size.
        record_session_bootstrap_event(&store, true, rows.len(), lines.len()).await;

        Ok(ToolResult::text(lines.join("\n")))
    }
}

/// Lifecycle reminder appended to session_bootstrap output.
fn session_lifecycle_hint() -> String {
    "=== Session Lifecycle Reminder ===\n\
     Before this session ends, call:\n\
     1. session_curate(conversation_text=<recent context summary>) — extract and save lessons; \
        prefix lines with handoff: for next-session continuity\n\
     2. session_finalize() — compact stale memories + optional export\n\
     --- Grounded-claim rule (#1758) ---\n\
     Any outward claim that cites a produced identifier (commit SHA, PR#, \
     deployed sha, post-id) MUST be emitted in a SEPARATE tool turn AFTER the \
     producing call returns its real value — never batch the producing call \
     (git commit / deploy) together with the forum_post / memory_save that \
     references it; at batch time the value does not yet exist and gets \
     confabulated. A denied or cancelled tool call did NOT run — re-verify, \
     don't assume success.\n\
     =================================="
        .to_string()
}

// ===========================================================================
//                              session_curate
// ===========================================================================

#[derive(Default)]
struct SessionCurateCandidateLedger {
    saved_count: usize,
    duplicate_count: usize,
    candidate_error_count: usize,
    auxiliary_errors: Vec<String>,
    candidate_errors: Vec<String>,
}

impl SessionCurateCandidateLedger {
    fn record_saved(&mut self) {
        self.saved_count += 1;
    }

    fn record_duplicate(&mut self) {
        self.duplicate_count += 1;
    }

    fn record_lookup_error(&mut self, message: String) {
        self.candidate_error_count += 1;
        self.candidate_errors.push(message);
    }

    fn record_save_error(&mut self, message: String) {
        self.candidate_error_count += 1;
        self.candidate_errors.push(message);
    }

    fn record_auxiliary_error(&mut self, message: String) {
        self.auxiliary_errors.push(message);
    }

    fn into_response_errors(self) -> Vec<String> {
        let mut errors = self.auxiliary_errors;
        errors.extend(self.candidate_errors);
        errors
    }
}

/// SSB lifecycle producer (roadmap §2 "hooks → bus events"): emit a
/// `session_curate` as a typed semantic event on the unified Object/Affordance
/// contract, completing the session-lifecycle trio on the bus alongside
/// session_bootstrap (start) and session_finalize (end). Curate HAS readback —
/// the count of memories actually persisted — so a run that saved ≥1 memory is
/// Verified; a dry-run or a run that saved nothing (all duplicates / no
/// candidates) made no effect and is honestly Unknown; a run where every
/// candidate save errored failed to persist and is NotVerified (anti-laundering).
/// Best-effort; the emit never affects the curate result.
async fn record_session_curate_event(
    store: &Arc<dyn StateStore>,
    dry_run: bool,
    saved_count: usize,
    skipped_dupes: usize,
    error_count: usize,
    candidate_count: usize,
) {
    let verdict = if dry_run {
        // Dry-run previews candidates but persists nothing → no effect → Unknown.
        crate::semantic_event::classify_lifecycle(true, false, "")
    } else {
        // A real run that saved nothing AND hit errors failed to persist (the
        // step's core work did not succeed) → NotVerified. Otherwise it ran:
        // saved ≥1 → Verified (readback), saved 0 with no errors → Unknown.
        let total_failure = saved_count == 0 && error_count > 0;
        crate::semantic_event::classify_lifecycle(
            !total_failure,
            saved_count > 0,
            if total_failure {
                "curate: all candidate saves failed"
            } else {
                ""
            },
        )
    };
    let ev = crate::semantic_event::SemanticEvent {
        ts: dispatch_now_secs(),
        actor: "mcp".to_string(),
        source: "session".to_string(),
        action: "curate".to_string(),
        target: None,
        object: crate::semantic_event::SemanticObject {
            object_type: "session".to_string(),
            source_adapter: "session".to_string(),
            label: None,
            object_id: None,
        },
        affordance: crate::semantic_event::Affordance {
            action_type: "curate".to_string(),
            risk_level: "low".to_string(),
            requires_gate: false,
            expected_effect: Some("extract + persist memories from conversation".to_string()),
        },
        verdict,
        facts: json!({
            "dry_run": dry_run,
            "saved_count": saved_count,
            "skipped_duplicates": skipped_dupes,
            "error_count": error_count,
            "candidate_count": candidate_count,
        }),
    };
    if let Err(e) = store.record_semantic_event(ev.to_record()).await {
        tracing::debug!(error = %e, "record_semantic_event (session_curate) failed");
    }
}

pub struct SessionCurateTool {
    hub: Hub,
}
impl SessionCurateTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

// CURATE_MARKERS, section helpers, and curate_conversation live in crate::curate.

// Extraction logic lives in crate::curate — use curate_conversation() below.

#[async_trait]
impl McpTool for SessionCurateTool {
    fn name(&self) -> &'static str {
        "session_curate"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Extract structured memories from conversation text. Two-pass: \
                 (1) explicit markers (lesson:, decision:, todo:, handoff:) and \
                 (2) lexical scoring of epistemic/normative/causal/decision signals \
                 (English + Chinese). dry_run=true previews."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "conversation_text": {
                        "type": "string",
                        "description": "Recent conversation or summary text. Lines prefixed with lesson:, decision:, todo:, handoff:, etc. are extracted as memories."
                    },
                    "session_id": {
                        "type": "string",
                        "description": "Optional session ID for key namespacing and deduplication."
                    },
                    "scope": {
                        "type": "string",
                        "description": "Recall scope inherited by every extracted memory (for example project:/repo or domain:rust). Omit or use 'global' only for an intentional global curation run. This is not a principal ACL."
                    },
                    "max_items": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 50,
                        "default": 8,
                        "description": "Max number of memories to write."
                    },
                    "dry_run": {
                        "type": "boolean",
                        "default": false,
                        "description": "If true, return what would be saved without writing."
                    },
                    "implicit_score_threshold": {
                        "type": "number",
                        "description": "Optional Pass-2 minimum aggregate signal score (default from env AGENT_BRIDGE_CURATE_SCORE_THRESHOLD or built-in default). Clamped to [0.15, 0.95]."
                    },
                    "implicit_dedup_jaccard": {
                        "type": "number",
                        "description": "Optional Pass-2 Jaccard dedup threshold (default from env AGENT_BRIDGE_CURATE_DEDUP_JACCARD or built-in default). Clamped to [0.1, 0.95]."
                    }
                },
                "required": ["conversation_text"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store_opt = self.hub.store.clone();
        c2c_live_lab_phase!("curate_entered");

        let text = match args.get("conversation_text").and_then(|v| v.as_str()) {
            Some(s) if !s.is_empty() => s.to_string(),
            _ => return Ok(ToolResult::error("missing 'conversation_text'")),
        };
        let session_id = args
            .get("session_id")
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(|s| s.to_string());
        let target_scope = normalized_recall_scope(args.get("scope").and_then(Value::as_str));
        let max_items = args
            .get("max_items")
            .and_then(|v| v.as_u64())
            .unwrap_or(8)
            .min(50) as usize;
        let dry_run = args
            .get("dry_run")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);

        let score_ov = args
            .get("implicit_score_threshold")
            .and_then(|v| v.as_f64())
            .map(|x| x as f32);
        let dedup_ov = args.get("implicit_dedup_jaccard").and_then(|v| v.as_f64());
        let curate_opts =
            crate::curate::CurateOptions::from_env_or_defaults().with_overrides(score_ov, dedup_ov);

        let mut candidates = crate::curate::curate_conversation_with_options(
            &text,
            session_id.as_deref(),
            max_items,
            curate_opts.clone(),
        );
        c2c_live_lab_phase!("candidates_ready");
        for candidate in &mut candidates {
            apply_curated_memory_governance(
                candidate,
                target_scope.as_deref(),
                "session_curate",
                session_id.as_deref(),
                &[],
            );
        }

        if dry_run || store_opt.is_none() {
            // SSB lifecycle producer: a dry-run previews but persists nothing →
            // Unknown (no effect). Only emit when a store exists; a no-store call
            // has nowhere to record (and is not a real curate).
            if let Some(store) = &store_opt {
                record_session_curate_event(store, true, 0, 0, 0, candidates.len()).await;
            }
            return Ok(ToolResult::json_text(&json!({
                "dry_run": true,
                "scope": target_scope.as_deref().unwrap_or("global"),
                "options": {
                    "implicit_score_threshold": curate_opts.implicit_score_threshold,
                    "implicit_dedup_jaccard": curate_opts.implicit_dedup_jaccard,
                },
                "candidates": candidates.iter().map(|m| json!({
                    "key": m.key,
                    "kind": m.kind,
                    "content": m.content,
                    "tags": m.tags,
                    "related_keys": m.related_keys,
                    "scope": m.scope,
                })).collect::<Vec<_>>()
            })));
        }

        let store = store_opt.unwrap();
        let mut saved: Vec<Value> = Vec::new();
        let mut outcome_ledger = SessionCurateCandidateLedger::default();

        // Staleness-gate slice ③ (forum #119 post 3072): a curate run retires
        // its OWN session's previous in-flight handoff snapshots by declaring
        // `continuity_supersedes` on the batch's new session_handoff row —
        // enforced store-side since f067ab6e. In-flight snapshots asserting
        // arc state were the dominant stale class (M2 69.2%); the CJK-weak
        // token-overlap heuristic never retired them. Scoped to runs WITH a
        // session_id (an empty sid suffix would prefix-match every session);
        // lessons/decisions are durable knowledge and are never touched.
        // Limitation: if the new handoff's key already exists verbatim, its
        // save is skipped below and no retirement happens this run.
        let mut retired_prior_handoffs: Vec<String> = Vec::new();
        if session_id.is_some() && candidates.iter().any(|m| m.kind == "session_handoff") {
            let sid_suffix = crate::curate::mk_sid_suffix(session_id.as_deref());
            let prefix = format!("curated_session_handoff{sid_suffix}_");
            let batch_keys: std::collections::HashSet<&str> =
                candidates.iter().map(|m| m.key.as_str()).collect();
            match store.memory_active_keys_with_prefix(&prefix, 32).await {
                Ok(prior) => {
                    retired_prior_handoffs = prior
                        .into_iter()
                        .filter(|k| !batch_keys.contains(k.as_str()))
                        .collect();
                    if !retired_prior_handoffs.is_empty() {
                        if let Some(h) = candidates.iter_mut().find(|m| m.kind == "session_handoff")
                        {
                            for old_key in &retired_prior_handoffs {
                                h.tags.push(format!("continuity_supersedes:{old_key}"));
                            }
                        }
                    }
                }
                Err(e) => outcome_ledger.record_auxiliary_error(format!("prior-handoff scan: {e}")),
            }
        }

        #[cfg(feature = "episode-observation-slice-c1")]
        c2c_live_lab_phase!("observation_begin_enter");
        #[cfg(feature = "episode-observation-slice-c1")]
        let mut curation_batch_observation = CurationBatchObservationRun::begin(
            self.hub.curation_batch_observer.clone(),
            !candidates.is_empty(),
        )
        .await;
        #[cfg(feature = "episode-observation-slice-c1")]
        c2c_live_lab_phase!("observation_begin_done");

        for mem in &candidates {
            c2c_live_lab_phase!("core_save_enter");
            // Skip if key already exists (dedup)
            match store.memory_get(&mem.key).await {
                Ok(Some(_)) => {
                    // Already exists — skip
                    outcome_ledger.record_duplicate();
                }
                Ok(None) => match store.memory_save(mem).await {
                    Ok(()) => {
                        saved.push(json!({ "key": mem.key, "kind": mem.kind }));
                        outcome_ledger.record_saved();
                        c2c_live_lab_phase!("core_save_done");
                        #[cfg(feature = "episode-observation-slice-c1")]
                        c2c_live_lab_phase!("observation_item_enter");
                        #[cfg(feature = "episode-observation-slice-c1")]
                        curation_batch_observation
                            .observe_memory_saved(&mem.key)
                            .await;
                        #[cfg(feature = "episode-observation-slice-c1")]
                        c2c_live_lab_phase!("observation_item_done");
                    }
                    Err(e) => outcome_ledger.record_save_error(format!("{}: {e}", mem.key)),
                },
                Err(e) => outcome_ledger.record_lookup_error(format!("{}: {e}", mem.key)),
            }
        }

        #[cfg(feature = "episode-observation-slice-c1")]
        c2c_live_lab_phase!("observation_finish_enter");
        #[cfg(feature = "episode-observation-slice-c1")]
        let _observation_completion = curation_batch_observation.finish().await;
        #[cfg(feature = "episode-observation-slice-c1")]
        c2c_live_lab_phase!("observation_finish_done");

        let session_handoff_key = candidates
            .iter()
            .find(|m| m.kind == "session_handoff")
            .map(|m| m.key.clone());

        // SSB lifecycle producer: a real curate HAS readback (the persisted
        // count), so a run that saved ≥1 memory is Verified; saved nothing with
        // no errors → Unknown; saved nothing but every save errored → NotVerified.
        debug_assert_eq!(outcome_ledger.saved_count, saved.len());
        let skipped = outcome_ledger.duplicate_count;
        let candidate_error_count = outcome_ledger.candidate_error_count;
        record_session_curate_event(
            &store,
            false,
            saved.len(),
            skipped,
            candidate_error_count,
            candidates.len(),
        )
        .await;

        // Retirement is carried by the tagged handoff row's save; if that
        // save was skipped (key already existed) or errored, nothing was
        // actually retired — don't report otherwise.
        if !retired_prior_handoffs.is_empty()
            && !saved
                .iter()
                .any(|v| v.get("kind").and_then(|k| k.as_str()) == Some("session_handoff"))
        {
            retired_prior_handoffs.clear();
        }

        let errors = outcome_ledger.into_response_errors();

        c2c_live_lab_phase!("curate_response_ready");
        Ok(ToolResult::json_text(&json!({
            "dry_run": false,
            "scope": target_scope.as_deref().unwrap_or("global"),
            "saved_count": saved.len(),
            "new_memories": saved,
            "skipped_duplicates": skipped,
            "errors": errors,
            "session_handoff_key": session_handoff_key,
            "retired_prior_handoffs": retired_prior_handoffs
        })))
    }
}

