pub struct McpCallStatsTool {
    hub: Hub,
}
impl McpCallStatsTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for McpCallStatsTool {
    fn name(&self) -> &'static str {
        "mcp_call_stats"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Aggregate MCP `tools/call` telemetry over a recent time window. \
                 Returns per-tool call_count / error_count / avg+p95+max duration_ms / \
                 avg result_size, sorted by call_count desc. Powers the observation period \
                 that drives the ab-shell decision (see memory \
                 plan_warp_observation_metrics_20260503). Telemetry is recorded by the MCP \
                 stdio dispatcher on every successful or failed call."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "window_days": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 365,
                        "default": 7,
                        "description": "Look-back window in days. Default 7."
                    },
                    "window_secs": {
                        "type": "integer",
                        "minimum": 60,
                        "maximum": 31536000,
                        "description": "Optional look-back window in seconds. Overrides window_days; useful for post-restart or A/B observation."
                    },
                    "top_n": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 200,
                        "default": 30,
                        "description": "Max number of tools in the result, sorted by call_count desc."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let (window_days, window_secs, window_source) = dispatch_window_from_args(&args);
        let top_n = args
            .get("top_n")
            .and_then(|v| v.as_u64())
            .unwrap_or(30)
            .clamp(1, 200) as u32;
        match store.mcp_tool_call_stats(window_secs, top_n).await {
            Ok(stats) => {
                let total_calls: u64 = stats.iter().map(|s| s.call_count).sum();
                let total_errors: u64 = stats.iter().map(|s| s.error_count).sum();
                Ok(ToolResult::json_text(&json!({
                    "window_days": window_days,
                    "window_secs": window_secs,
                    "window_source": window_source,
                    "tools": stats,
                    "total_calls": total_calls,
                    "total_errors": total_errors,
                })))
            }
            Err(e) => Ok(ToolResult::error(format!("store: {e}"))),
        }
    }
}

// ===========================================================================
//                       mcp_dispatch_audit — tool-surface tuning
// ===========================================================================

pub struct McpDispatchAuditTool {
    hub: Hub,
}
impl McpDispatchAuditTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for McpDispatchAuditTool {
    fn name(&self) -> &'static str {
        "mcp_dispatch_audit"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Summarize Agent-Bridge MCP tool dispatch telemetry for profile tuning. \
                 Shows hot tools, cold currently-exposed tools, failed tools, and optimization \
                 candidates over a recent window. Use this to decide which tools Codex should \
                 keep exposed, optimize, demote, or move behind skills/profile gates."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "window_days": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 365,
                        "default": 7,
                        "description": "Look-back window in days. Default 7."
                    },
                    "window_secs": {
                        "type": "integer",
                        "minimum": 60,
                        "maximum": 31536000,
                        "description": "Optional look-back window in seconds. Overrides window_days; useful for post-restart or A/B observation."
                    },
                    "top_n": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 50,
                        "default": 20,
                        "description": "Max hot/failing/optimization rows to return. Default 20."
                    },
                    "cold_limit": {
                        "type": "integer",
                        "minimum": 0,
                        "maximum": 200,
                        "default": 50,
                        "description": "Max currently-exposed zero-call tools to return. Use 0 to hide cold tools."
                    },
                    "recent_errors": {
                        "type": "integer",
                        "minimum": 0,
                        "maximum": 100,
                        "default": 10,
                        "description": "Max recent error rows to include. Use 0 to hide raw recent errors."
                    },
                    "source": {
                        "type": "string",
                        "enum": ["codex", "chatgpt", "hook", "claude", "gemini", "manual", "other", "legacy"],
                        "description": "Optional caller-source filter. Omit for all traffic."
                    },
                    "client_name": {
                        "type": "string",
                        "description": "Optional exact MCP clientInfo.name filter."
                    },
                    "profile": {
                        "type": "string",
                        "enum": ["essential", "standard", "all", "legacy"],
                        "description": "Optional AGENT_BRIDGE_TOOL_PROFILE filter."
                    },
                    "model": {
                        "type": "string",
                        "description": "Optional AGENT_BRIDGE_MODEL filter, for model-aware profile tuning."
                    },
                    "model_reasoning_effort": {
                        "type": "string",
                        "description": "Optional AGENT_BRIDGE_MODEL_REASONING_EFFORT filter."
                    },
                    "codex_host": {
                        "type": "string",
                        "enum": ["desktop", "cli", "ide", "legacy"],
                        "description": "Optional AGENT_BRIDGE_CODEX_HOST filter for Codex desktop/CLI/IDE slices."
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let (window_days, window_secs, window_source) = dispatch_window_from_args(&args);
        let top_n = args
            .get("top_n")
            .and_then(|v| v.as_u64())
            .unwrap_or(20)
            .clamp(1, 50) as usize;
        let cold_limit = args
            .get("cold_limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(50)
            .clamp(0, 200) as usize;
        let recent_errors_limit = args
            .get("recent_errors")
            .and_then(|v| v.as_u64())
            .unwrap_or(10)
            .clamp(0, 100) as u32;
        let filter = dispatch_filter_from_args(&args);
        let cold_basis = if dispatch_filter_is_empty(&filter) {
            McpToolCallFilter {
                source: Some("codex".to_string()),
                ..McpToolCallFilter::default()
            }
        } else {
            filter.clone()
        };

        let policy = ToolPolicy::from_env();
        let current_tools: Vec<String> = build_registry(self.hub.clone())
            .list()
            .into_iter()
            .map(|schema| schema.name)
            .collect();
        let current_tool_count = current_tools.len();

        // Ask for enough rows to cover the full current surface. The store clamps
        // to 200, which is enough for today's registry profiles.
        let stats_limit = current_tool_count.max(top_n).min(200) as u32;
        let stats = match store
            .mcp_tool_call_stats_filtered(window_secs, stats_limit, filter.clone())
            .await
        {
            Ok(rows) => rows,
            Err(e) => return Ok(ToolResult::error(format!("store: {e}"))),
        };
        let cold_basis_stats = match store
            .mcp_tool_call_stats_filtered(window_secs, stats_limit, cold_basis.clone())
            .await
        {
            Ok(rows) => rows,
            Err(e) => return Ok(ToolResult::error(format!("store: {e}"))),
        };
        let stats_by_tool: HashMap<String, ab_store::McpToolCallStats> = cold_basis_stats
            .iter()
            .cloned()
            .map(|s| (s.tool_name.clone(), s))
            .collect();
        let source_breakdown = match store
            .mcp_tool_source_stats_filtered(window_secs, 50, filter.clone())
            .await
        {
            Ok(rows) => rows
                .iter()
                .map(dispatch_source_stat_json)
                .collect::<Vec<_>>(),
            Err(e) => return Ok(ToolResult::error(format!("store: {e}"))),
        };
        let global_hot_codex_tools = match store
            .mcp_tool_call_stats_filtered(
                window_secs,
                top_n as u32,
                dispatch_source_only_filter("codex"),
            )
            .await
        {
            Ok(rows) => rows.iter().map(dispatch_stat_json).collect::<Vec<_>>(),
            Err(e) => return Ok(ToolResult::error(format!("store: {e}"))),
        };
        let global_hot_hook_tools = match store
            .mcp_tool_call_stats_filtered(
                window_secs,
                top_n as u32,
                dispatch_source_only_filter("hook"),
            )
            .await
        {
            Ok(rows) => rows.iter().map(dispatch_stat_json).collect::<Vec<_>>(),
            Err(e) => return Ok(ToolResult::error(format!("store: {e}"))),
        };
        let external_batch_context: HashMap<String, ab_store::McpToolCallStats> =
            if dispatch_filter_is_empty(&filter) {
                match store
                    .mcp_tool_call_stats_filtered(
                        window_secs,
                        stats_limit,
                        dispatch_source_only_filter("other"),
                    )
                    .await
                {
                    Ok(rows) => rows.into_iter().map(|s| (s.tool_name.clone(), s)).collect(),
                    Err(e) => return Ok(ToolResult::error(format!("store: {e}"))),
                }
            } else {
                HashMap::new()
            };

        let total_calls: u64 = stats.iter().map(|s| s.call_count).sum();
        let total_errors: u64 = stats.iter().map(|s| s.error_count).sum();

        let hot_tools: Vec<Value> = stats.iter().take(top_n).map(dispatch_stat_json).collect();

        let recent_error_rows = if stats.iter().any(|s| s.error_count > 0) {
            store
                .recent_mcp_tool_errors(ab_store::MCP_TOOL_ERROR_RING_CAP)
                .await
                .unwrap_or_default()
        } else {
            Vec::new()
        };
        let error_diagnostics =
            dispatch_error_diagnostics_by_tool(recent_error_rows.clone(), window_secs, &stats);

        let failing_tools: Vec<Value> = stats
            .iter()
            .filter(|s| dispatch_stat_has_actionable_errors(s, &error_diagnostics))
            .take(top_n)
            .map(|s| {
                let mut v = dispatch_stat_json(s);
                if let Some(obj) = v.as_object_mut() {
                    obj.insert(
                        "error_rate".to_string(),
                        json!(dispatch_error_rate(s.error_count, s.call_count)),
                    );
                }
                v
            })
            .collect();

        let optimization_candidates: Vec<Value> = stats
            .iter()
            .filter_map(|s| {
                let reasons = dispatch_optimization_reasons_with_source_context(
                    s,
                    &error_diagnostics,
                    &external_batch_context,
                );
                if reasons.is_empty() {
                    None
                } else {
                    Some(json!({
                        "tool_name": s.tool_name,
                        "call_count": s.call_count,
                        "error_count": s.error_count,
                        "p95_duration_ms": s.p95_duration_ms,
                        "avg_result_size": s.avg_result_size,
                        "reasons": reasons,
                    }))
                }
            })
            .take(top_n)
            .collect();

        let cold_tools: Vec<Value> = if cold_limit == 0 {
            Vec::new()
        } else {
            current_tools
                .iter()
                .filter(|name| !stats_by_tool.contains_key(*name))
                .take(cold_limit)
                .map(|name| {
                    json!({
                        "tool_name": name,
                        "codex_native_overlap": dispatch_codex_native_overlap(name),
                        "suggestion": dispatch_cold_tool_suggestion(name),
                    })
                })
                .collect()
        };

        let recent_errors = if recent_errors_limit == 0 {
            Vec::new()
        } else {
            dispatch_recent_errors_for_audit(
                recent_error_rows,
                recent_errors_limit,
                window_secs,
                &stats,
                &error_diagnostics,
            )
        };

        let profile_suggestions = dispatch_profile_suggestions_with_source_context(
            &stats,
            &cold_tools,
            &error_diagnostics,
            &external_batch_context,
        );

        Ok(ToolResult::json_text(&json!({
            "profile": policy.profile().label(),
            "toolset": policy.label(),
            "model": std::env::var("AGENT_BRIDGE_MODEL").ok(),
            "model_reasoning_effort": std::env::var("AGENT_BRIDGE_MODEL_REASONING_EFFORT").ok(),
            "codex_host": std::env::var("AGENT_BRIDGE_CODEX_HOST").ok(),
            "window_days": window_days,
            "window_secs": window_secs,
            "window_source": window_source,
            "filter": dispatch_filter_json(&filter),
            "current_exposed_tool_count": current_tool_count,
            "observed_tool_count": stats.len(),
            "total_calls": total_calls,
            "total_errors": total_errors,
            "source_breakdown": source_breakdown,
            "hot_tools": hot_tools,
            "global_hot_codex_tools": global_hot_codex_tools,
            "global_hot_hook_tools": global_hot_hook_tools,
            "failing_tools": failing_tools,
            "optimization_candidates": optimization_candidates,
            "cold_basis": dispatch_filter_json(&cold_basis),
            "cold_tools": cold_tools,
            "recent_errors": recent_errors,
            "profile_suggestions": profile_suggestions,
            "view_scope": {
                "hot_tools": "current filter",
                "failing_tools": "current filter",
                "optimization_candidates": "current filter",
                "source_breakdown": "current filter",
                "cold_tools": "cold_basis filter",
                "recent_errors": "current-filter failing tool names within the current window; mcp_tool_errors rows do not carry source/model attribution",
                "global_hot_codex_tools": "global source-only comparison: source=codex",
                "global_hot_hook_tools": "global source-only comparison: source=hook"
            },
            "limits": {
                "top_n": top_n,
                "cold_limit": cold_limit,
                "recent_errors": recent_errors_limit,
                "stats_limit": stats_limit
            },
            "note": "Telemetry covers Agent-Bridge MCP tools/call traffic only; Codex native shell/browser/GitHub tool use is outside this table. Rows recorded before telemetry attribution appear as source=legacy. The current audit call itself is recorded after this response, so it appears on the next audit."
        })))
    }
}

pub struct EventSpineSnapshotTool {
    hub: Hub,
}
impl EventSpineSnapshotTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for EventSpineSnapshotTool {
    fn name(&self) -> &'static str {
        "event_spine_snapshot"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Read-only Phase 0 event-spine projection over existing Agent-Bridge \
                 telemetry. Builds a timestamp-ordered SHA-256 hash chain from recent MCP \
                 tool-call, tool-error, and agent-session lifecycle rows without creating a \
                 new source of truth. Use this to verify whether current telemetry can support \
                 replay/explainability before adding a persisted unified event table."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "window_secs": {
                        "type": "integer",
                        "minimum": 60,
                        "maximum": 31536000,
                        "default": 86400,
                        "description": "Look-back window in seconds."
                    },
                    "limit": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 500,
                        "default": 40,
                        "description": "Maximum derived events to consider after timestamp ordering."
                    },
                    "include_events": {
                        "type": "boolean",
                        "default": false,
                        "description": "When false, omit event rows but keep counts and chain head."
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let window_secs = args
            .get("window_secs")
            .and_then(|v| v.as_i64())
            .unwrap_or(86_400)
            .clamp(60, 31_536_000);
        let limit = args
            .get("limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(40)
            .clamp(1, 500) as usize;
        let include_events = args
            .get("include_events")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let fetch_limit = limit.min(500) as u32;

        let calls = match store.recent_mcp_tool_calls(window_secs, fetch_limit).await {
            Ok(rows) => rows,
            Err(e) => return Ok(ToolResult::error(format!("recent_mcp_tool_calls: {e}"))),
        };
        let errors = match store.recent_mcp_tool_errors(fetch_limit).await {
            Ok(rows) => rows,
            Err(e) => return Ok(ToolResult::error(format!("recent_mcp_tool_errors: {e}"))),
        };
        let sessions = match store
            .list_sessions(&SessionFilter::default(), fetch_limit)
            .await
        {
            Ok(rows) => rows,
            Err(e) => return Ok(ToolResult::error(format!("list_sessions: {e}"))),
        };
        let semantic_events = match store.recent_semantic_events(window_secs, fetch_limit).await {
            Ok(rows) => rows,
            Err(e) => return Ok(ToolResult::error(format!("recent_semantic_events: {e}"))),
        };
        let snapshot = crate::event_spine::mcp_event_spine_snapshot(
            &calls,
            &errors,
            &sessions,
            &semantic_events,
            window_secs,
            limit,
            dispatch_now_secs(),
        );
        let payload = crate::event_spine::project_event_spine_snapshot(&snapshot, include_events);
        Ok(ToolResult::json_text(&payload))
    }
}

/// Default-off, read-only compatibility audit for Qwen-AgentWorld-style
/// action/observation trajectories. The tool emits digest-only manifests and
/// never treats simulator material as execution evidence.
pub struct AgentWorldTrajectoryAuditTool {
    hub: Hub,
}

impl AgentWorldTrajectoryAuditTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for AgentWorldTrajectoryAuditTool {
    fn name(&self) -> &'static str {
        "agent_world_trajectory_audit"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Audit whether current Agent-Bridge telemetry can honestly reconstruct a Qwen-AgentWorld-style action/observation trajectory. This all-profile-only P0 tool is read-only and digest-only: it never exports raw prompts, tool payloads, transcripts, or state values; never writes memory; and never permits simulated observations to claim evidence or attestation."
                .into(),
            input_schema: json!({
                "type": "object",
                "required": ["contract"],
                "properties": {
                    "contract": {
                        "type": "object",
                        "description": "AgentTaskContract v0 object accepted by agent_task_contract_preview."
                    },
                    "window_secs": {
                        "type": "integer",
                        "minimum": 60,
                        "maximum": 31536000,
                        "default": 86400
                    },
                    "limit": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 500,
                        "default": 40
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let contract_value = match args.get("contract") {
            Some(value) => value.clone(),
            None => return Ok(ToolResult::error("missing required field: contract")),
        };
        let contract = match serde_json::from_value::<AgentTaskContract>(contract_value) {
            Ok(contract) => contract,
            Err(error) => return Ok(ToolResult::error(format!("invalid contract: {error}"))),
        };
        let contract_preview = preview_agent_task_contract(contract);
        let store = match &self.hub.store {
            Some(store) => store.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let window_secs = args
            .get("window_secs")
            .and_then(Value::as_i64)
            .unwrap_or(86_400)
            .clamp(60, 31_536_000);
        let limit = args
            .get("limit")
            .and_then(Value::as_u64)
            .unwrap_or(40)
            .clamp(1, 500) as usize;
        // Fetch one sentinel row per source. Without it, a source capped at the
        // output limit could be silently mistaken for a complete snapshot.
        let fetch_limit = (limit.saturating_add(1).min(500)) as u32;

        let calls = match store.recent_mcp_tool_calls(window_secs, fetch_limit).await {
            Ok(rows) => rows,
            Err(error) => return Ok(ToolResult::error(format!("recent_mcp_tool_calls: {error}"))),
        };
        let errors = match store.recent_mcp_tool_errors(fetch_limit).await {
            Ok(rows) => rows,
            Err(error) => {
                return Ok(ToolResult::error(format!(
                    "recent_mcp_tool_errors: {error}"
                )))
            }
        };
        let sessions = match store
            .list_sessions(&SessionFilter::default(), fetch_limit)
            .await
        {
            Ok(rows) => rows,
            Err(error) => return Ok(ToolResult::error(format!("list_sessions: {error}"))),
        };
        let semantic_events = match store.recent_semantic_events(window_secs, fetch_limit).await {
            Ok(rows) => rows,
            Err(error) => {
                return Ok(ToolResult::error(format!(
                    "recent_semantic_events: {error}"
                )))
            }
        };
        let source_cap_reached = agent_world_source_cap_reached(
            [
                calls.len(),
                errors.len(),
                sessions.len(),
                semantic_events.len(),
            ],
            fetch_limit as usize,
        );
        let mut snapshot = crate::event_spine::mcp_event_spine_snapshot(
            &calls,
            &errors,
            &sessions,
            &semantic_events,
            window_secs,
            limit,
            dispatch_now_secs(),
        );
        if source_cap_reached && snapshot.truncated_count == 0 {
            snapshot.candidate_count = snapshot.candidate_count.saturating_add(1);
            snapshot.truncated_count = 1;
        }
        static COMMITMENT_KEY: std::sync::OnceLock<[u8; 16]> = std::sync::OnceLock::new();
        let commitment_key = COMMITMENT_KEY.get_or_init(|| *uuid::Uuid::new_v4().as_bytes());
        let audit = crate::agent_world_trajectory::audit_agent_world_trajectory(
            &contract_preview,
            &snapshot,
            commitment_key,
        );
        let payload = serde_json::to_value(audit)
            .unwrap_or_else(|error| json!({ "error": format!("serialize audit: {error}") }));
        Ok(ToolResult::json_text(&payload))
    }
}

fn agent_world_source_cap_reached<const N: usize>(
    source_lengths: [usize; N],
    fetch_limit: usize,
) -> bool {
    source_lengths.into_iter().any(|count| count >= fetch_limit)
}

fn agent_world_capture_enabled_from(value: Option<&str>) -> bool {
    matches!(value.map(str::trim), Some("1"))
        || value.is_some_and(|value| value.trim().eq_ignore_ascii_case("true"))
}

fn agent_world_capture_enabled() -> bool {
    agent_world_capture_enabled_from(
        std::env::var("AGENT_BRIDGE_AGENT_WORLD_CAPTURE")
            .ok()
            .as_deref(),
    )
}

fn agent_world_output_commitment(domain: &str, value: &str) -> String {
    static KEY: std::sync::OnceLock<[u8; 16]> = std::sync::OnceLock::new();
    let key = KEY.get_or_init(|| *uuid::Uuid::new_v4().as_bytes());
    let mut hasher = Sha256::new();
    ShaDigest::update(&mut hasher, domain.as_bytes());
    ShaDigest::update(&mut hasher, [0]);
    ShaDigest::update(&mut hasher, value.as_bytes());
    ShaDigest::update(&mut hasher, [0]);
    ShaDigest::update(&mut hasher, key);
    format!("{:x}", ShaDigest::finalize(hasher))
}

fn workspace_summary_observation(root: &std::path::Path) -> std::io::Result<Value> {
    let mut files = 0_u64;
    let mut directories = 0_u64;
    let mut symlinks = 0_u64;
    let mut other = 0_u64;
    for entry in std::fs::read_dir(root)? {
        let kind = entry?.file_type()?;
        if kind.is_file() {
            files += 1;
        } else if kind.is_dir() {
            directories += 1;
        } else if kind.is_symlink() {
            symlinks += 1;
        } else {
            other += 1;
        }
    }
    Ok(json!({
        "schema": "agent_bridge.workspace_summary_observation.v0",
        "files": files,
        "directories": directories,
        "symlinks": symlinks,
        "other": other
    }))
}

fn resolve_agent_world_workspace_root(
    value: &str,
) -> std::result::Result<std::path::PathBuf, String> {
    let supplied = std::path::Path::new(value);
    if !supplied.is_absolute() {
        return Err("root must be an absolute canonical path".to_string());
    }
    if std::fs::symlink_metadata(value)
        .map_err(|error| format!("inspect root: {error}"))?
        .file_type()
        .is_symlink()
    {
        return Err("symlink roots are not admissible".to_string());
    }
    let root =
        std::fs::canonicalize(value).map_err(|error| format!("canonicalize root: {error}"))?;
    if supplied != root {
        return Err(
            "root path must already be canonical and contain no symlinked ancestors".to_string(),
        );
    }
    if root == std::path::Path::new("/") {
        return Err("filesystem root is not an admissible workspace".to_string());
    }
    if std::env::var_os("HOME").is_some_and(|home| root == std::path::PathBuf::from(home)) {
        return Err("home directory is not an admissible workspace".to_string());
    }
    validate_agent_world_git_root(&root)?;
    Ok(root)
}

#[cfg(unix)]
fn agent_world_workspace_identity(root: &std::path::Path) -> std::io::Result<(u64, u64)> {
    use std::os::unix::fs::MetadataExt;
    let metadata = std::fs::metadata(root)?;
    Ok((metadata.dev(), metadata.ino()))
}

#[cfg(not(unix))]
fn agent_world_workspace_identity(root: &std::path::Path) -> std::io::Result<std::path::PathBuf> {
    std::fs::canonicalize(root)
}

fn validate_agent_world_git_root(root: &std::path::Path) -> std::result::Result<(), String> {
    let root_text = root.to_str().ok_or("root is not valid UTF-8")?;
    let output = std::process::Command::new("git")
        .args(["-C", root_text, "rev-parse", "--show-toplevel"])
        .output()
        .map_err(|error| format!("run git worktree validation: {error}"))?;
    if !output.status.success() {
        return Err("root must be an actual git worktree".to_string());
    }
    let top =
        String::from_utf8(output.stdout).map_err(|_| "git top-level is not UTF-8".to_string())?;
    let top = std::fs::canonicalize(top.trim())
        .map_err(|error| format!("canonicalize git top-level: {error}"))?;
    if top != root {
        return Err("root must equal the git worktree top-level".to_string());
    }
    Ok(())
}

/// Default-off P1 producer: Bridge executes one fixed read-only probe and
/// stores the exact structured pair in the local SQLite ring.
pub struct AgentWorldProbeCaptureTool {
    hub: Hub,
}

impl AgentWorldProbeCaptureTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for AgentWorldProbeCaptureTool {
    fn name(&self) -> &'static str {
        "agent_world_probe_capture"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Run one fixed local read-only workspace-summary probe and append its exact action/observation pair to a 200-row local-only ring. Requires AGENT_BRIDGE_AGENT_WORLD_CAPTURE=1 and per_call_opt_in=true. It cannot execute caller-supplied commands, accept caller-supplied observations, export data, or authorize runtime.".into(),
            input_schema: json!({
                "type": "object",
                "required": ["root", "per_call_opt_in"],
                "properties": {
                    "root": { "type": "string", "description": "Canonicalizable git worktree root; / and HOME are rejected." },
                    "per_call_opt_in": { "type": "boolean", "default": false }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        if !agent_world_capture_enabled() {
            return Ok(ToolResult::error(
                "agent-world capture is disabled; set AGENT_BRIDGE_AGENT_WORLD_CAPTURE=1",
            ));
        }
        if !args
            .get("per_call_opt_in")
            .and_then(Value::as_bool)
            .unwrap_or(false)
        {
            return Ok(ToolResult::error("per_call_opt_in=true is required"));
        }
        let root_value = args.get("root").and_then(Value::as_str).unwrap_or("");
        let root = match resolve_agent_world_workspace_root(root_value) {
            Ok(root) => root,
            Err(error) => return Ok(ToolResult::error(error)),
        };
        let identity_before = match agent_world_workspace_identity(&root) {
            Ok(identity) => identity,
            Err(error) => {
                return Ok(ToolResult::error(format!(
                    "inspect workspace identity: {error}"
                )))
            }
        };
        let observation = match workspace_summary_observation(&root) {
            Ok(value) => value,
            Err(error) => {
                return Ok(ToolResult::error(format!(
                    "workspace summary probe: {error}"
                )))
            }
        };
        if let Err(error) = validate_agent_world_git_root(&root) {
            return Ok(ToolResult::error(format!(
                "workspace changed during probe: {error}"
            )));
        }
        let identity_after = match agent_world_workspace_identity(&root) {
            Ok(identity) => identity,
            Err(error) => {
                return Ok(ToolResult::error(format!(
                    "reinspect workspace identity: {error}"
                )))
            }
        };
        if identity_before != identity_after {
            return Ok(ToolResult::error("workspace identity changed during probe"));
        }
        let store = self
            .hub
            .store
            .as_ref()
            .ok_or_else(|| ab_core::Error::Backend("no store configured".to_string()))?;
        let row = store
            .record_agent_world_capture(ab_store::AgentWorldWorkspaceSummaryCapture {
                capture_id: uuid::Uuid::new_v4().to_string(),
                files: observation["files"].as_u64().unwrap_or(0),
                directories: observation["directories"].as_u64().unwrap_or(0),
                symlinks: observation["symlinks"].as_u64().unwrap_or(0),
                other: observation["other"].as_u64().unwrap_or(0),
            })
            .await?;
        Ok(ToolResult::json_text(&json!({
            "schema": "agent_bridge.agent_world_probe_capture_receipt.v0",
            "status": "captured",
            "capture_id": row.capture_id,
            "at": row.at,
            "probe_kind": row.probe_kind,
            "receipt_commitment": agent_world_output_commitment("capture-row", &row.row_hash),
            "raw_content_exported": false,
            "local_only": true,
            "can_authorize_runtime": false
        })))
    }
}

pub struct AgentWorldCaptureReportTool {
    hub: Hub,
}

fn agent_world_capture_report_payload(
    rows: &[ab_store::AgentWorldCaptureRow],
    limit: usize,
) -> Value {
    let retained_slice_consistent = ab_store::verify_agent_world_capture_chain(rows);
    let samples = rows
        .iter()
        .rev()
        .take(limit)
        .rev()
        .map(|row| {
            json!({
                "capture_ref": agent_world_output_commitment("capture-id", &row.capture_id),
                "probe_kind": row.probe_kind,
            })
        })
        .collect::<Vec<_>>();
    json!({
        "schema": "agent_bridge.agent_world_capture_report.v0",
        "status": if rows.len() >= 20 && retained_slice_consistent { "acceptance_sample_ready" } else { "collecting" },
        "sample_count": rows.len(),
        "target_count": 20,
        "retained_slice_consistent": retained_slice_consistent,
        "raw_content_exported": false,
        "samples": samples
    })
}

impl AgentWorldCaptureReportTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for AgentWorldCaptureReportTool {
    fn name(&self) -> &'static str {
        "agent_world_capture_report"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Read a digest-only local AgentWorld capture coverage report. Raw actions and observations remain in the local store and are never returned.".into(),
            input_schema: json!({"type":"object","properties":{"limit":{"type":"integer","minimum":1,"maximum":200,"default":200}}}),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let limit = args
            .get("limit")
            .and_then(Value::as_u64)
            .unwrap_or(200)
            .clamp(1, 200) as u32;
        let store = self
            .hub
            .store
            .as_ref()
            .ok_or_else(|| ab_core::Error::Backend("no store configured".to_string()))?;
        if !agent_world_capture_enabled() {
            return Ok(ToolResult::error(
                "agent-world capture report is disabled with the capture feature",
            ));
        }
        let rows = store.agent_world_capture_rows(200).await?;
        Ok(ToolResult::json_text(&agent_world_capture_report_payload(
            &rows,
            limit as usize,
        )))
    }
}

pub struct ToolAtlasSnapshotTool {
    hub: Hub,
}
impl ToolAtlasSnapshotTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for ToolAtlasSnapshotTool {
    fn name(&self) -> &'static str {
        "tool_atlas_snapshot"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Read-only Tool Atlas v0 over Agent-Bridge MCP telemetry. \
                 Combines the current exposed tool registry, recent mcp_tool_calls stats, \
                 and mcp_tool_errors samples into per-tool usage, health, failure-mode, \
                 and keep/fix/watch recommendations. Use after event_spine_snapshot when \
                 deciding which tools should stay exposed, be optimized, or be repaired."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "window_secs": {
                        "type": "integer",
                        "minimum": 60,
                        "maximum": 31536000,
                        "default": 86400,
                        "description": "Look-back window in seconds."
                    },
                    "source": {
                        "type": "string",
                        "enum": ["codex", "chatgpt", "hook", "claude", "gemini", "manual", "other", "legacy"],
                        "description": "Optional caller-source filter. Omit for all traffic."
                    },
                    "client_name": {
                        "type": "string",
                        "description": "Optional exact MCP clientInfo.name filter."
                    },
                    "profile": {
                        "type": "string",
                        "enum": ["essential", "standard", "all", "legacy"],
                        "description": "Optional AGENT_BRIDGE_TOOL_PROFILE filter."
                    },
                    "model": {
                        "type": "string",
                        "description": "Optional AGENT_BRIDGE_MODEL filter."
                    },
                    "model_reasoning_effort": {
                        "type": "string",
                        "description": "Optional AGENT_BRIDGE_MODEL_REASONING_EFFORT filter."
                    },
                    "codex_host": {
                        "type": "string",
                        "enum": ["desktop", "cli", "ide", "legacy"],
                        "description": "Optional AGENT_BRIDGE_CODEX_HOST filter for Codex desktop/CLI/IDE slices."
                    },
                    "limit": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 500,
                        "default": 8,
                        "description": "Maximum number of per-tool rows to include. Defaults to 8 to keep MCP output compact; summary counts still cover all tools."
                    },
                    "include_tools": {
                        "type": "boolean",
                        "default": true,
                        "description": "When false, return only summary/filter/note and omit per-tool rows."
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let window_secs = args
            .get("window_secs")
            .and_then(|v| v.as_i64())
            .unwrap_or(86_400)
            .clamp(60, 31_536_000);
        let limit = args
            .get("limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(8)
            .clamp(1, 500) as usize;
        let include_tools = args
            .get("include_tools")
            .and_then(|v| v.as_bool())
            .unwrap_or(true);
        let filter = dispatch_filter_from_args(&args);
        let current_tools: Vec<String> = build_registry(self.hub.clone())
            .list()
            .into_iter()
            .map(|schema| schema.name)
            .collect();
        let stats_limit = current_tools.len().max(1).min(200) as u32;
        let stats = match store
            .mcp_tool_call_stats_filtered(window_secs, stats_limit, filter.clone())
            .await
        {
            Ok(rows) => rows,
            Err(e) => {
                return Ok(ToolResult::error(format!(
                    "mcp_tool_call_stats_filtered: {e}"
                )))
            }
        };
        let recent_errors = match store
            .recent_mcp_tool_errors(ab_store::MCP_TOOL_ERROR_RING_CAP)
            .await
        {
            Ok(rows) => rows,
            Err(e) => return Ok(ToolResult::error(format!("recent_mcp_tool_errors: {e}"))),
        };
        let snapshot =
            crate::tool_atlas::build_tool_atlas_snapshot(crate::tool_atlas::ToolAtlasInput {
                generated_at: dispatch_now_secs(),
                window_secs,
                current_tools,
                stats,
                recent_errors,
            });
        let mut payload = crate::tool_atlas::project_tool_atlas_snapshot(
            &snapshot,
            crate::tool_atlas::ToolAtlasViewOptions {
                include_tools,
                limit,
            },
        );
        if let Some(obj) = payload.as_object_mut() {
            obj.insert("filter".to_string(), dispatch_filter_json(&filter));
            obj.insert(
                "note".to_string(),
                json!("Read-only derived atlas. Default output is compact: use limit to include more rows, or include_tools=false for summary-only. It does not write memories, change profiles, or replace the event spine."),
            );
        }
        Ok(ToolResult::json_text(&payload))
    }
}

/// A `verified` verdict that rests on no readback evidence is green-laundering —
/// the exact failure the verify-first invariant forbids. Pure + total so the
/// integrity monitor's core check is unit-testable without a store. (The
/// structural [`crate::semantic_event::contract_violations`] validator does not
/// require the evidence field, so this is an additional, orthogonal check.)
fn is_green_laundering(verdict_status: &str, evidence: Option<&str>) -> bool {
    verdict_status == "verified" && evidence.map(|s| s.trim().is_empty()).unwrap_or(true)
}

/// Read-only Semantic System Bus INTEGRITY monitor — the release-build safety
/// net for the verify-first contract. Gate E's `to_record()` debug_assert
/// (which runs [`crate::semantic_event::contract_violations`]) is a no-op in
/// release, so a deployed build has no automatic conformance check on the events
/// producers emit. This tool scans recent `semantic_events` and re-runs the SAME
/// validator, plus a green-laundering check (a `verified` verdict resting on no
/// readback evidence — the exact thing the verify-first invariant forbids), and
/// reports the verdict distribution + producer coverage. It never writes,
/// restarts, mutates Palace, or captures screenshots.
pub struct SemanticBusIntegrityTool {
    hub: Hub,
}
impl SemanticBusIntegrityTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for SemanticBusIntegrityTool {
    fn name(&self) -> &'static str {
        "semantic_bus_integrity"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Read-only Semantic System Bus integrity monitor: scans recent \
                 semantic_events and re-runs the unified-contract validator (the same \
                 contract_violations behind Gate E, which is debug-only / a no-op in release) \
                 plus a green-laundering check (a verified verdict with no readback evidence). \
                 Reports verdict distribution, producer coverage, and any offending rows. \
                 Release-build safety net; never writes or mutates anything."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "window_secs": {
                        "type": "integer",
                        "minimum": 60,
                        "maximum": 31536000,
                        "default": 604800,
                        "description": "Look-back window in seconds (default 7 days)."
                    },
                    "limit": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 5000,
                        "default": 500,
                        "description": "Max recent events to scan."
                    },
                    "violations_only": {
                        "type": "boolean",
                        "default": false,
                        "description": "When true, omit the verdict/producer breakdown and return only offending rows."
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let window_secs = args
            .get("window_secs")
            .and_then(|v| v.as_i64())
            .unwrap_or(604_800)
            .clamp(60, 31_536_000);
        let limit = args
            .get("limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(500)
            .clamp(1, 5000) as u32;
        let violations_only = args
            .get("violations_only")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);

        let events = match store.recent_semantic_events(window_secs, limit).await {
            Ok(e) => e,
            Err(e) => return Ok(ToolResult::error(format!("recent_semantic_events: {e}"))),
        };

        let mut verdict_counts: std::collections::BTreeMap<String, u64> = Default::default();
        let mut producer_counts: std::collections::BTreeMap<String, u64> = Default::default();
        let mut offenders: Vec<Value> = Vec::new();
        let mut contract_violation_rows = 0u64;
        let mut laundering_rows = 0u64;

        for ev in &events {
            *verdict_counts.entry(ev.verdict_status.clone()).or_default() += 1;
            *producer_counts
                .entry(format!("{}/{}", ev.source, ev.action))
                .or_default() += 1;

            // Re-run the canonical structural validator (the same one Gate E uses).
            let mut row_issues = crate::semantic_event::contract_violations(ev);
            if !row_issues.is_empty() {
                contract_violation_rows += 1;
            }
            // Green-laundering: a verified verdict must rest on concrete readback
            // evidence. A verified row with empty/absent evidence is the exact
            // failure the verify-first invariant forbids — flag it even though the
            // structural validator does not require the evidence field.
            let laundered = is_green_laundering(&ev.verdict_status, ev.evidence.as_deref());
            if laundered {
                laundering_rows += 1;
                row_issues.push(
                    "verified verdict has no readback evidence (green-laundering)".to_string(),
                );
            }
            if !row_issues.is_empty() {
                offenders.push(json!({
                    "source": ev.source,
                    "action": ev.action,
                    "verdict": ev.verdict_status,
                    "method": ev.verdict_method,
                    "ts": ev.ts,
                    "issues": row_issues,
                }));
            }
        }

        let clean = offenders.is_empty();
        let mut out = json!({
            "integrity": if clean { "ok" } else { "violations" },
            "scanned": events.len(),
            "window_secs": window_secs,
            "contract_violation_rows": contract_violation_rows,
            "laundering_rows": laundering_rows,
            "offenders": offenders,
        });
        if !violations_only {
            out["verdict_distribution"] = json!(verdict_counts);
            out["producer_coverage"] = json!(producer_counts);
        }
        Ok(ToolResult::json_text(&out))
    }
}

pub struct GosLiteSnapshotTool {
    hub: Hub,
}
impl GosLiteSnapshotTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for GosLiteSnapshotTool {
    fn name(&self) -> &'static str {
        "gos_lite_snapshot"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Read-only GoS-lite belief-graph projection over the same Tool Atlas \
                 telemetry as tool_atlas_snapshot. Converts grounded failing/degraded tool facts \
                 into explicit Signal/Evidence/Hypothesis nodes and support/refines edges so an \
                 agent can reason about which tool failures are actionable. It does not call \
                 tools, write state, change profiles, or ask an LLM to fill missing evidence."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "window_secs": {
                        "type": "integer",
                        "minimum": 60,
                        "maximum": 31536000,
                        "default": 86400,
                        "description": "Look-back window in seconds."
                    },
                    "source": {
                        "type": "string",
                        "enum": ["codex", "chatgpt", "hook", "claude", "gemini", "manual", "other", "legacy"],
                        "description": "Optional caller-source filter. Omit for all traffic."
                    },
                    "client_name": {
                        "type": "string",
                        "description": "Optional exact MCP clientInfo.name filter."
                    },
                    "profile": {
                        "type": "string",
                        "enum": ["essential", "standard", "all", "legacy"],
                        "description": "Optional AGENT_BRIDGE_TOOL_PROFILE filter."
                    },
                    "model": {
                        "type": "string",
                        "description": "Optional AGENT_BRIDGE_MODEL filter."
                    },
                    "model_reasoning_effort": {
                        "type": "string",
                        "description": "Optional AGENT_BRIDGE_MODEL_REASONING_EFFORT filter."
                    },
                    "codex_host": {
                        "type": "string",
                        "enum": ["desktop", "cli", "ide", "legacy"],
                        "description": "Optional AGENT_BRIDGE_CODEX_HOST filter for Codex desktop/CLI/IDE slices."
                    },
                    "include_graph": {
                        "type": "boolean",
                        "default": true,
                        "description": "When false, omit nodes and edges while keeping counts, summary, and the human review gate."
                    },
                    "include_replay_check": {
                        "type": "boolean",
                        "default": true,
                        "description": "When true, attach a read-only Event Spine replay/falsifier report for generated hypotheses."
                    },
                    "replay_event_limit": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 500,
                        "default": 200,
                        "description": "Maximum recent Event Spine events to inspect for replay/falsifier checks."
                    },
                    "limit": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 500,
                        "default": 100,
                        "description": "Maximum graph nodes to include when include_graph=true. Edges are kept only when both endpoints are included."
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let window_secs = args
            .get("window_secs")
            .and_then(|v| v.as_i64())
            .unwrap_or(86_400)
            .clamp(60, 31_536_000);
        let limit = args
            .get("limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(100)
            .clamp(1, 500) as usize;
        let include_graph = args
            .get("include_graph")
            .and_then(|v| v.as_bool())
            .unwrap_or(true);
        let include_replay_check = args
            .get("include_replay_check")
            .and_then(|v| v.as_bool())
            .unwrap_or(true);
        let replay_event_limit = args
            .get("replay_event_limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(200)
            .clamp(1, 500) as usize;
        let filter = dispatch_filter_from_args(&args);
        let current_tools: Vec<String> = build_registry(self.hub.clone())
            .list()
            .into_iter()
            .map(|schema| schema.name)
            .collect();
        let stats_limit = current_tools.len().max(1).min(200) as u32;
        let generated_at = dispatch_now_secs();
        let stats = match store
            .mcp_tool_call_stats_filtered(window_secs, stats_limit, filter.clone())
            .await
        {
            Ok(rows) => rows,
            Err(e) => {
                return Ok(ToolResult::error(format!(
                    "mcp_tool_call_stats_filtered: {e}"
                )))
            }
        };
        let recent_errors = match store
            .recent_mcp_tool_errors(ab_store::MCP_TOOL_ERROR_RING_CAP)
            .await
        {
            Ok(rows) => rows,
            Err(e) => return Ok(ToolResult::error(format!("recent_mcp_tool_errors: {e}"))),
        };
        let atlas =
            crate::tool_atlas::build_tool_atlas_snapshot(crate::tool_atlas::ToolAtlasInput {
                generated_at,
                window_secs,
                current_tools,
                stats,
                recent_errors: recent_errors.clone(),
            });
        let snapshot = crate::gos_lite::build_gos_lite_snapshot_from_tool_atlas(&atlas);
        let mut payload = crate::gos_lite::project_gos_lite_snapshot(
            &snapshot,
            crate::gos_lite::GosLiteViewOptions {
                include_graph,
                limit,
            },
        );
        if let Some(obj) = payload.as_object_mut() {
            obj.insert("filter".to_string(), dispatch_filter_json(&filter));
            obj.insert("read_only".to_string(), json!(true));
            obj.insert("llm_calls".to_string(), json!(false));
            obj.insert("writes_state".to_string(), json!(false));
            if include_replay_check {
                let calls = match store
                    .recent_mcp_tool_calls(window_secs, replay_event_limit as u32)
                    .await
                {
                    Ok(rows) => rows,
                    Err(e) => return Ok(ToolResult::error(format!("recent_mcp_tool_calls: {e}"))),
                };
                let event_spine = crate::event_spine::mcp_event_spine_snapshot(
                    &calls,
                    &recent_errors,
                    &[],
                    &[],
                    window_secs,
                    replay_event_limit,
                    generated_at,
                );
                let replay_report =
                    crate::gos_lite::build_gos_lite_replay_report(&snapshot, &event_spine);
                obj.insert(
                    "replay_check".to_string(),
                    serde_json::to_value(replay_report).unwrap_or_else(|_| json!({})),
                );
            } else {
                obj.insert(
                    "replay_check".to_string(),
                    json!({
                        "included": false,
                        "reason": "include_replay_check=false"
                    }),
                );
            }
            obj.insert(
                "note".to_string(),
                json!("Read-only GoS-lite projection derived from the same Tool Atlas telemetry. It does not call tools, write memories, change profiles, or replace the event spine."),
            );
        }
        Ok(ToolResult::json_text(&payload))
    }
}

// ===========================================================================
//                 mcp_lifecycle_digest - borrowed-patterns status
// ===========================================================================

pub struct McpLifecycleDigestTool {
    hub: Hub,
}
impl McpLifecycleDigestTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for McpLifecycleDigestTool {
    fn name(&self) -> &'static str {
        "mcp_lifecycle_digest"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Read-only lifecycle/status digest for Agent-Bridge MCP. \
                 Separates stdio MCP/tool-profile readiness, hook/setup readiness, \
                 recent tool telemetry, and optional daemon-http/Palace runtime health. \
                 It does not start/stop MCP servers, restart services, or mutate profiles."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "repo_root": {
                        "type": "string",
                        "description": "Optional Agent-Bridge checkout root for readiness source checks."
                    },
                    "window_secs": {
                        "type": "integer",
                        "minimum": 60,
                        "maximum": 31536000,
                        "default": 86400,
                        "description": "Tool telemetry look-back window."
                    },
                    "include_local_install": {
                        "type": "boolean",
                        "default": false,
                        "description": "Ask readiness_audit to inspect installed hook scripts and setup-state."
                    },
                    "include_runtime_health": {
                        "type": "boolean",
                        "default": false,
                        "description": "Run bounded read-only daemon-http/Palace health GETs. Defaults false so a digest can stay stdio-only."
                    },
                    "daemon_http_url": {
                        "type": "string",
                        "description": "Base URL for daemon-http when include_runtime_health=true."
                    },
                    "palace_url": {
                        "type": "string",
                        "description": "Base URL for Palace when include_runtime_health=true."
                    },
                    "timeout_ms": {
                        "type": "integer",
                        "minimum": 100,
                        "maximum": 30000,
                        "default": 1000,
                        "description": "Per-request timeout for optional runtime health checks."
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let payload = mcp_lifecycle_digest_payload(&args, &self.hub).await;
        Ok(ToolResult::json_text(&payload))
    }
}

async fn mcp_lifecycle_digest_payload(args: &Value, hub: &Hub) -> Value {
    let policy = ToolPolicy::from_env();
    let window_secs = args
        .get("window_secs")
        .and_then(|v| v.as_i64())
        .unwrap_or(86_400)
        .clamp(60, 31_536_000);
    let include_local_install = args
        .get("include_local_install")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let include_runtime_health = args
        .get("include_runtime_health")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    let current_tool_count = build_registry(hub.clone()).list().len();
    // Same reality semantics as current_tool_count (host detection applied) —
    // pre-prune both used one builder and were always equal.
    let scoped_tool_count = build_registry_current_view(policy).list().len();
    let readiness_args = json!({
        "repo_root": args.get("repo_root").cloned().unwrap_or(Value::Null),
        "include_local_install": include_local_install,
    });
    let readiness = readiness_audit_payload(&readiness_args, hub);
    let telemetry = mcp_lifecycle_tool_telemetry(hub, window_secs).await;
    let runtime_health = if include_runtime_health {
        let mut runtime_args = json!({
            "timeout_ms": args.get("timeout_ms").cloned().unwrap_or(json!(1000)),
        });
        if let Some(v) = args.get("daemon_http_url").cloned() {
            runtime_args["daemon_http_url"] = v;
        }
        if let Some(v) = args.get("palace_url").cloned() {
            runtime_args["palace_url"] = v;
        }
        json!({
            "checked": true,
            "payload": semantic_bus_runtime_health_payload(&runtime_args).await,
        })
    } else {
        json!({
            "checked": false,
            "reason": "include_runtime_health=false",
            "note": "MCP stdio/readiness can be healthy even when daemon-http or Palace are not running."
        })
    };

    let readiness_status = readiness
        .get("status")
        .and_then(|v| v.as_str())
        .unwrap_or("unknown")
        .to_string();
    let readiness_warnings = readiness
        .pointer("/summary/warnings")
        .and_then(|v| v.as_u64())
        .unwrap_or(0);
    let runtime_status = runtime_health
        .pointer("/payload/status")
        .and_then(|v| v.as_str())
        .unwrap_or(if include_runtime_health {
            "unknown"
        } else {
            "not_checked"
        })
        .to_string();
    let failing_tool_count = telemetry
        .pointer("/summary/failing_tool_count")
        .and_then(|v| v.as_u64())
        .unwrap_or(0);
    let lifecycle_state = if readiness_warnings == 0 && failing_tool_count == 0 {
        if include_runtime_health && !mcp_lifecycle_runtime_status_ready(&runtime_status) {
            "stdio_ready_runtime_degraded"
        } else {
            "ready"
        }
    } else {
        "attention"
    };

    json!({
        "schema": "agent_bridge.mcp_lifecycle_digest.v0",
        "generated_at": dispatch_now_secs(),
        "read_only": true,
        "lifecycle_state": lifecycle_state,
        "summary": {
            "mcp_stdio_available": true,
            "toolset": policy.label(),
            "tool_profile": policy.profile().label(),
            "current_tool_count": current_tool_count,
            "scoped_tool_count": scoped_tool_count,
            "readiness_status": readiness_status,
            "readiness_warnings": readiness_warnings,
            "telemetry_window_secs": window_secs,
            "failing_tool_count": failing_tool_count,
            "runtime_health_checked": include_runtime_health,
            "runtime_health_status": runtime_status,
        },
        "sections": {
            "mcp_profile": {
                "toolset": policy.label(),
                "tool_profile": policy.profile().label(),
                "tool_profile_extras": policy.extras(),
                "toolset_env": std::env::var("AGENT_BRIDGE_TOOLSET").ok(),
                "tool_profile_env": std::env::var("AGENT_BRIDGE_TOOL_PROFILE").ok(),
                "client": std::env::var("AGENT_BRIDGE_CLIENT").ok(),
                "codex_host": std::env::var("AGENT_BRIDGE_CODEX_HOST").ok(),
                "model": std::env::var("AGENT_BRIDGE_MODEL").ok(),
                "model_reasoning_effort": std::env::var("AGENT_BRIDGE_MODEL_REASONING_EFFORT").ok(),
            },
            "readiness": {
                "status": readiness_status,
                "summary": readiness.get("summary").cloned().unwrap_or(Value::Null),
                "recommendations": readiness.get("recommendations").cloned().unwrap_or(json!([])),
            },
            "tool_telemetry": telemetry,
            "runtime_health": runtime_health,
        },
        "recommendations": mcp_lifecycle_recommendations(
            readiness_warnings,
            failing_tool_count,
            include_runtime_health,
            &runtime_status,
        ),
        "note": "Borrowed from Theia-style lifecycle separation: profile/readiness/telemetry/runtime health are reported as separate axes. This tool is observational only."
    })
}

fn mcp_lifecycle_runtime_status_ready(runtime_status: &str) -> bool {
    matches!(runtime_status, "ok" | "ready")
}

fn mcp_lifecycle_tool_atlas_input(
    generated_at: i64,
    window_secs: i64,
    current_tools: Vec<String>,
    stats: Vec<ab_store::McpToolCallStats>,
    recent_errors: Vec<ab_store::McpToolErrorRecord>,
) -> crate::tool_atlas::ToolAtlasInput {
    let current_tool_set: HashSet<String> = current_tools
        .iter()
        .map(|name| name.trim().to_string())
        .filter(|name| !name.is_empty())
        .collect();
    let stats: Vec<ab_store::McpToolCallStats> = stats
        .into_iter()
        .filter(|stat| current_tool_set.contains(stat.tool_name.trim()))
        .collect();
    let failing_tool_set: HashSet<String> = stats
        .iter()
        .filter(|stat| stat.error_count > 0)
        .map(|stat| stat.tool_name.trim().to_string())
        .collect();
    let recent_errors: Vec<ab_store::McpToolErrorRecord> = recent_errors
        .into_iter()
        .filter(|error| failing_tool_set.contains(error.tool_name.trim()))
        .collect();

    crate::tool_atlas::ToolAtlasInput {
        generated_at,
        window_secs,
        current_tools,
        stats,
        recent_errors,
    }
}

async fn mcp_lifecycle_tool_telemetry(hub: &Hub, window_secs: i64) -> Value {
    let Some(store) = hub.store.as_ref() else {
        return json!({
            "status": "unavailable",
            "reason": "no store configured",
            "summary": {
                "current_tool_count": build_registry(hub.clone()).list().len(),
                "observed_tool_count": 0,
                "hot_tool_count": 0,
                "failing_tool_count": 0,
                "cold_tool_count": 0
            }
        });
    };
    let current_tools: Vec<String> = build_registry(hub.clone())
        .list()
        .into_iter()
        .map(|schema| schema.name)
        .collect();
    let stats_limit = current_tools.len().max(1).min(200) as u32;
    let filter = mcp_lifecycle_telemetry_filter_from_env();
    let stats = match store
        .mcp_tool_call_stats_filtered(window_secs, stats_limit, filter.clone())
        .await
    {
        Ok(rows) => rows,
        Err(e) => {
            return json!({
                "status": "error",
                "reason": format!("mcp_tool_call_stats_filtered: {e}"),
            })
        }
    };
    let recent_errors = match store
        .recent_mcp_tool_errors(ab_store::MCP_TOOL_ERROR_RING_CAP)
        .await
    {
        Ok(rows) => rows,
        Err(e) => {
            return json!({
                "status": "error",
                "reason": format!("recent_mcp_tool_errors: {e}"),
            })
        }
    };
    let snapshot = crate::tool_atlas::build_tool_atlas_snapshot(mcp_lifecycle_tool_atlas_input(
        dispatch_now_secs(),
        window_secs,
        current_tools,
        stats,
        recent_errors,
    ));
    let mut payload = crate::tool_atlas::project_tool_atlas_snapshot(
        &snapshot,
        crate::tool_atlas::ToolAtlasViewOptions {
            include_tools: false,
            limit: 1,
        },
    );
    if let Some(obj) = payload.as_object_mut() {
        obj.insert("status".to_string(), json!("ok"));
        obj.insert("filter".to_string(), dispatch_filter_json(&filter));
        obj.insert(
            "scope_note".to_string(),
            json!("Lifecycle telemetry is scoped to the current MCP surface and attribution where available. The recent error ring has no attribution columns, so it is used only for tools with current scoped error stats."),
        );
    }
    payload
}

fn mcp_lifecycle_telemetry_filter_from_env() -> McpToolCallFilter {
    let policy = ToolPolicy::from_env();
    McpToolCallFilter {
        source: mcp_lifecycle_source_from_env(),
        client_name: std::env::var("AGENT_BRIDGE_CLIENT_NAME")
            .ok()
            .map(|s| s.trim().to_string())
            .filter(|s| !s.is_empty()),
        profile: Some(policy.profile().label().to_string()),
        model: std::env::var("AGENT_BRIDGE_MODEL")
            .ok()
            .map(|s| s.trim().to_string())
            .filter(|s| !s.is_empty()),
        model_reasoning_effort: std::env::var("AGENT_BRIDGE_MODEL_REASONING_EFFORT")
            .ok()
            .map(|s| s.trim().to_string())
            .filter(|s| !s.is_empty()),
        codex_host: std::env::var("AGENT_BRIDGE_CODEX_HOST")
            .ok()
            .map(|s| s.trim().to_string())
            .filter(|s| !s.is_empty()),
    }
}

fn mcp_lifecycle_source_from_env() -> Option<String> {
    for key in [
        "AGENT_BRIDGE_MCP_SOURCE",
        "AGENT_BRIDGE_CLIENT",
        "AGENT_BRIDGE_TOOLSET",
    ] {
        if let Ok(value) = std::env::var(key) {
            if let Some(source) = dispatch_normalize_source(&value) {
                return Some(source.to_string());
            }
        }
    }
    if let Ok(client_name) = std::env::var("AGENT_BRIDGE_CLIENT_NAME") {
        if let Some(source) = dispatch_normalize_source(&client_name) {
            return Some(source.to_string());
        }
    }
    if mcp_schema_codex_context() {
        return Some("codex".to_string());
    }
    None
}

fn dispatch_normalize_source(value: &str) -> Option<&'static str> {
    let normalized = normalize_tool_policy_value(value);
    if normalized.contains("hook")
        || normalized.contains("precompact")
        || normalized.contains("pre-compact")
        || normalized.contains("session-end")
        || normalized.contains("sessionend")
        || normalized.contains("stop")
    {
        return Some("hook");
    }
    if normalized.contains("chatgpt") || normalized == "openai-chat" {
        return Some("chatgpt");
    }
    if normalized.contains("codex") || normalized.contains("openai") {
        return Some("codex");
    }
    if normalized.contains("claude") {
        return Some("claude");
    }
    if normalized.contains("gemini") {
        return Some("gemini");
    }
    if normalized.contains("audit") || normalized.contains("smoke") || normalized.contains("test") {
        return Some("manual");
    }
    match normalized.as_str() {
        "manual" => Some("manual"),
        "legacy" => Some("legacy"),
        "other" => Some("other"),
        _ => None,
    }
}

fn mcp_lifecycle_recommendations(
    readiness_warnings: u64,
    failing_tool_count: u64,
    include_runtime_health: bool,
    runtime_status: &str,
) -> Vec<String> {
    let mut out = Vec::new();
    if readiness_warnings > 0 {
        out.push(
            "Inspect readiness_audit recommendations before changing MCP tool profiles.".into(),
        );
    }
    if failing_tool_count > 0 {
        out.push("Inspect tool_atlas_snapshot or mcp_dispatch_audit for failing MCP tools.".into());
    }
    if !include_runtime_health {
        out.push(
            "Set include_runtime_health=true when diagnosing daemon-http or Palace availability."
                .into(),
        );
    } else if !mcp_lifecycle_runtime_status_ready(runtime_status) {
        out.push("Treat daemon-http/Palace degradation as runtime health, separate from MCP stdio readiness.".into());
    }
    if out.is_empty() {
        out.push("MCP lifecycle axes look ready in this digest.".into());
    }
    out
}

fn dispatch_window_from_args(args: &Value) -> (i64, i64, &'static str) {
    let window_days = args
        .get("window_days")
        .and_then(|v| v.as_i64())
        .unwrap_or(7)
        .clamp(1, 365);
    if let Some(secs) = args.get("window_secs").and_then(|v| v.as_i64()) {
        (window_days, secs.clamp(60, 31_536_000), "window_secs")
    } else {
        (window_days, window_days * 86_400, "window_days")
    }
}

fn dispatch_now_secs() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0)
}

fn dispatch_recent_errors_for_audit(
    rows: Vec<ab_store::McpToolErrorRecord>,
    limit: u32,
    window_secs: i64,
    stats: &[ab_store::McpToolCallStats],
    diagnostics: &HashMap<String, Vec<ToolErrorDiagnosticClass>>,
) -> Vec<ab_store::McpToolErrorRecord> {
    if limit == 0 {
        return Vec::new();
    }
    let failing_tools: HashSet<&str> = stats
        .iter()
        .filter(|s| dispatch_stat_has_actionable_errors(s, diagnostics))
        .map(|s| s.tool_name.as_str())
        .collect();
    if failing_tools.is_empty() {
        return Vec::new();
    }
    let cutoff = dispatch_now_secs().saturating_sub(window_secs.max(0));
    rows.into_iter()
        .filter(|row| row.ts >= cutoff && failing_tools.contains(row.tool_name.as_str()))
        .take(limit as usize)
        .collect()
}

fn dispatch_error_diagnostics_by_tool(
    rows: Vec<ab_store::McpToolErrorRecord>,
    window_secs: i64,
    stats: &[ab_store::McpToolCallStats],
) -> HashMap<String, Vec<ToolErrorDiagnosticClass>> {
    let error_tools: HashSet<&str> = stats
        .iter()
        .filter(|s| s.error_count > 0)
        .map(|s| s.tool_name.as_str())
        .collect();
    if error_tools.is_empty() {
        return HashMap::new();
    }
    let cutoff = dispatch_now_secs().saturating_sub(window_secs.max(0));
    let mut diagnostics: HashMap<String, Vec<ToolErrorDiagnosticClass>> = HashMap::new();
    for row in rows
        .into_iter()
        .filter(|row| row.ts >= cutoff && error_tools.contains(row.tool_name.as_str()))
    {
        diagnostics
            .entry(row.tool_name.clone())
            .or_default()
            .push(classify_tool_error(&row.tool_name, &row.message));
    }
    diagnostics
}

fn dispatch_stat_has_actionable_errors(
    s: &ab_store::McpToolCallStats,
    diagnostics: &HashMap<String, Vec<ToolErrorDiagnosticClass>>,
) -> bool {
    if s.error_count == 0 {
        return false;
    }
    let Some(classes) = diagnostics.get(&s.tool_name) else {
        return true;
    };
    if classes.is_empty() {
        return true;
    }
    !classes.iter().all(|class| class.is_expected())
}

fn dispatch_filter_from_args(args: &Value) -> McpToolCallFilter {
    McpToolCallFilter {
        source: dispatch_optional_string_arg(args, "source"),
        client_name: dispatch_optional_string_arg(args, "client_name"),
        profile: dispatch_optional_string_arg(args, "profile"),
        model: dispatch_optional_string_arg(args, "model"),
        model_reasoning_effort: dispatch_optional_string_arg(args, "model_reasoning_effort"),
        codex_host: dispatch_optional_string_arg(args, "codex_host"),
    }
}

fn dispatch_optional_string_arg(args: &Value, key: &str) -> Option<String> {
    args.get(key)
        .and_then(|v| v.as_str())
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(ToString::to_string)
}

fn dispatch_filter_is_empty(filter: &McpToolCallFilter) -> bool {
    filter.source.is_none()
        && filter.client_name.is_none()
        && filter.profile.is_none()
        && filter.model.is_none()
        && filter.model_reasoning_effort.is_none()
        && filter.codex_host.is_none()
}

fn dispatch_source_only_filter(source: &str) -> McpToolCallFilter {
    McpToolCallFilter {
        source: Some(source.to_string()),
        ..McpToolCallFilter::default()
    }
}

fn dispatch_filter_json(filter: &McpToolCallFilter) -> Value {
    json!({
        "source": filter.source.as_deref(),
        "client_name": filter.client_name.as_deref(),
        "profile": filter.profile.as_deref(),
        "model": filter.model.as_deref(),
        "model_reasoning_effort": filter.model_reasoning_effort.as_deref(),
        "codex_host": filter.codex_host.as_deref(),
    })
}

fn dispatch_source_stat_json(s: &ab_store::McpToolSourceStats) -> Value {
    json!({
        "source": s.source,
        "client_name": s.client_name,
        "profile": s.profile,
        "model": s.model,
        "model_reasoning_effort": s.model_reasoning_effort,
        "codex_host": s.codex_host,
        "call_count": s.call_count,
        "error_count": s.error_count,
    })
}

fn dispatch_stat_json(s: &ab_store::McpToolCallStats) -> Value {
    let mut out = json!({
        "tool_name": s.tool_name,
        "call_count": s.call_count,
        "error_count": s.error_count,
        "avg_duration_ms": s.avg_duration_ms,
        "p95_duration_ms": s.p95_duration_ms,
        "max_duration_ms": s.max_duration_ms,
        "avg_result_size": s.avg_result_size,
    });
    if let Some(obj) = out.as_object_mut() {
        if let Some(source) = &s.source {
            obj.insert("source".to_string(), json!(source));
        }
        if let Some(client_name) = &s.client_name {
            obj.insert("client_name".to_string(), json!(client_name));
        }
        if let Some(profile) = &s.profile {
            obj.insert("profile".to_string(), json!(profile));
        }
        if let Some(model) = &s.model {
            obj.insert("model".to_string(), json!(model));
        }
        if let Some(model_reasoning_effort) = &s.model_reasoning_effort {
            obj.insert(
                "model_reasoning_effort".to_string(),
                json!(model_reasoning_effort),
            );
        }
        if let Some(codex_host) = &s.codex_host {
            obj.insert("codex_host".to_string(), json!(codex_host));
        }
    }
    out
}

fn dispatch_error_rate(errors: u64, calls: u64) -> f64 {
    if calls == 0 {
        0.0
    } else {
        errors as f64 / calls as f64
    }
}

#[cfg(test)]
fn dispatch_optimization_reasons(
    s: &ab_store::McpToolCallStats,
    diagnostics: &HashMap<String, Vec<ToolErrorDiagnosticClass>>,
) -> Vec<&'static str> {
    dispatch_optimization_reasons_with_source_context(s, diagnostics, &HashMap::new())
}

fn dispatch_optimization_reasons_with_source_context(
    s: &ab_store::McpToolCallStats,
    diagnostics: &HashMap<String, Vec<ToolErrorDiagnosticClass>>,
    external_batch_context: &HashMap<String, ab_store::McpToolCallStats>,
) -> Vec<&'static str> {
    const SAMPLE_SENSITIVE_P95_CALL_THRESHOLD: u64 = 20;

    if dispatch_expected_hook_lifecycle_latency(s) || dispatch_expected_biocortex_eval_workload(s) {
        return Vec::new();
    }

    let mut reasons = Vec::new();
    let has_actionable_errors = dispatch_stat_has_actionable_errors(s, diagnostics);
    if has_actionable_errors {
        reasons.push("has_errors");
        if !diagnostics.contains_key(&s.tool_name) {
            reasons.push("missing_error_samples");
        }
    }
    let sample_sensitive_p95 = s.call_count < SAMPLE_SENSITIVE_P95_CALL_THRESHOLD
        && !has_actionable_errors
        && s.p95_duration_ms == s.max_duration_ms;
    if s.call_count >= 3 && s.p95_duration_ms >= 1_000 && !sample_sensitive_p95 {
        reasons.push("slow_p95");
        if dispatch_external_batch_load(s)
            || dispatch_aggregate_external_batch_load(s, external_batch_context)
        {
            reasons.push("external_batch_load");
            if has_actionable_errors {
                reasons.push("external_batch_failure");
            }
        }
    }
    if s.call_count >= 3
        && s.avg_result_size >= 24_000.0
        && !dispatch_expected_detail_payload_tool(&s.tool_name)
    {
        reasons.push("large_average_result");
    }
    if has_actionable_errors
        && s.call_count >= 10
        && dispatch_error_rate(s.error_count, s.call_count) >= 0.20
    {
        reasons.push("high_error_rate");
    }
    reasons
}

fn dispatch_expected_detail_payload_tool(tool_name: &str) -> bool {
    matches!(
        tool_name,
        "event_spine_snapshot" | "forum_read" | "biocortex_replay_compare"
    )
}

fn dispatch_external_batch_load(s: &ab_store::McpToolCallStats) -> bool {
    s.call_count >= 50 && s.p95_duration_ms >= 1_000 && s.source.as_deref() == Some("other")
}

fn dispatch_aggregate_external_batch_load(
    s: &ab_store::McpToolCallStats,
    external_batch_context: &HashMap<String, ab_store::McpToolCallStats>,
) -> bool {
    if s.source.is_some() || s.call_count == 0 {
        return false;
    }
    let Some(source_stat) = external_batch_context.get(&s.tool_name) else {
        return false;
    };
    dispatch_external_batch_load(source_stat)
        && source_stat.call_count.saturating_mul(2) >= s.call_count
}

fn dispatch_expected_hook_lifecycle_latency(s: &ab_store::McpToolCallStats) -> bool {
    s.error_count == 0
        && s.p95_duration_ms >= 1_000
        && matches!(s.source.as_deref(), Some("hook") | None)
        && hook_lifecycle_tool(&s.tool_name)
}

fn dispatch_expected_biocortex_eval_workload(s: &ab_store::McpToolCallStats) -> bool {
    s.error_count == 0
        && (s.p95_duration_ms >= 1_000 || s.avg_result_size >= 24_000.0)
        && matches!(
            s.tool_name.as_str(),
            "biocortex_replay_compare" | "biocortex_retrieval_relevance_lift_eval"
        )
}

fn dispatch_codex_native_overlap(tool_name: &str) -> bool {
    tool_name == "shell_exec"
        || tool_name.starts_with("terminal_")
        || tool_name.starts_with("browser_")
        || tool_name.starts_with("github_")
        || tool_name.starts_with("gitlab_")
        || tool_name.starts_with("notion_")
        || tool_name.starts_with("cloudflare_")
        || tool_name.starts_with("brave_")
        || tool_name.starts_with("worktree_")
        || tool_name.starts_with("codebase_")
}

fn dispatch_cold_tool_suggestion(tool_name: &str) -> &'static str {
    if dispatch_codex_native_overlap(tool_name) {
        "candidate_for_profile_demotion_if_still_cold"
    } else if tool_name.starts_with("memory_")
        || tool_name.starts_with("session_")
        || tool_name == "skills_recommend"
        || tool_name == "skills_route"
        || tool_name == "skills_feedback"
        || tool_name == "tool_atlas_snapshot"
    {
        "keep_exposed_for_agent_bridge_core_value"
    } else {
        "watch_before_demoting"
    }
}

#[cfg(test)]
fn dispatch_profile_suggestions(
    stats: &[ab_store::McpToolCallStats],
    cold_tools: &[Value],
    diagnostics: &HashMap<String, Vec<ToolErrorDiagnosticClass>>,
) -> Vec<String> {
    dispatch_profile_suggestions_with_source_context(
        stats,
        cold_tools,
        diagnostics,
        &HashMap::new(),
    )
}

fn dispatch_profile_suggestions_with_source_context(
    stats: &[ab_store::McpToolCallStats],
    cold_tools: &[Value],
    diagnostics: &HashMap<String, Vec<ToolErrorDiagnosticClass>>,
    external_batch_context: &HashMap<String, ab_store::McpToolCallStats>,
) -> Vec<String> {
    let mut suggestions = Vec::new();
    if stats.is_empty() {
        suggestions.push(
            "No Agent-Bridge MCP calls were observed in the selected window; keep the current profile until hooks and skills have produced enough traffic."
                .to_string(),
        );
        return suggestions;
    }

    let hot_core = stats.iter().any(|s| {
        s.tool_name.starts_with("memory_")
            || s.tool_name.starts_with("session_")
            || s.tool_name == "skills_recommend"
            || s.tool_name == "skills_route"
            || s.tool_name == "skills_feedback"
            || s.tool_name == "tool_atlas_snapshot"
    });
    if hot_core {
        suggestions.push(
            "Memory/session/skill tools are receiving traffic; keep them in the Codex-facing profile."
                .to_string(),
        );
    }

    let hot_overlap = stats
        .iter()
        .filter(|s| s.call_count >= 3 && dispatch_codex_native_overlap(&s.tool_name))
        .count();
    if hot_overlap > 0 {
        suggestions.push(format!(
            "{hot_overlap} hot tools overlap Codex native surfaces; prefer schema-description nudges or a codex-lean A/B run before removing them from the default profile."
        ));
    }

    let cold_overlap = cold_tools
        .iter()
        .filter(|v| {
            v.get("codex_native_overlap")
                .and_then(|b| b.as_bool())
                .unwrap_or(false)
        })
        .count();
    if cold_overlap > 0 {
        suggestions.push(format!(
            "{cold_overlap} cold exposed tools overlap Codex native surfaces; if they remain cold, move them behind a broader profile or skill-triggered path."
        ));
    }

    if stats.iter().any(|s| {
        !dispatch_optimization_reasons_with_source_context(s, diagnostics, external_batch_context)
            .is_empty()
    }) {
        suggestions.push(
            "At least one observed tool has errors, slow p95 latency, or large results; inspect optimization_candidates before changing profile exposure."
                .to_string(),
        );
    }

    suggestions
}

