pub struct MemoryQueryStatsTool {
    hub: Hub,
}
impl MemoryQueryStatsTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for MemoryQueryStatsTool {
    fn name(&self) -> &'static str {
        "memory_query_stats"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Phase 0 memory telemetry readout. Aggregates `memory_query_log` \
                 over the last `window_secs` seconds: hit-rate, p50/p95 latency, average \
                 top-hit age, per-mode counts, top miss queries. Used to drive Phase 1 \
                 design decisions (decay scoring, coactivation in retrieval, dead-link \
                 detection). Default window: 7 days."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "window_secs": {
                        "type": "integer",
                        "minimum": 60,
                        "maximum": 31_536_000,
                        "default": 604_800,
                        "description": "Lookback window in seconds. Default 7 days. Capped to 1 year."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let window_secs = args
            .get("window_secs")
            .and_then(|v| v.as_i64())
            .unwrap_or(604_800)
            .clamp(60, 31_536_000);

        let stats = store.memory_query_stats(window_secs).await?;

        let by_kind_json: Vec<Value> = stats
            .by_kind
            .iter()
            .map(|(k, n)| json!({ "kind": k, "count": n }))
            .collect();
        let top_misses_json: Vec<Value> = stats
            .top_miss_queries
            .iter()
            .map(|(q, n)| json!({ "query": q, "count": n }))
            .collect();

        Ok(ToolResult::json_text(&json!({
            "window_start": stats.window_start,
            "window_end": stats.window_end,
            "window_secs": window_secs,
            "total_queries": stats.total_queries,
            "hits": stats.hits,
            "misses": stats.misses,
            "hit_rate": (stats.hit_rate * 1000.0).round() / 1000.0,
            "avg_top_hit_age_days":
                (stats.avg_top_hit_age_secs / 86_400.0 * 100.0).round() / 100.0,
            "p50_duration_us": stats.p50_duration_us,
            "p95_duration_us": stats.p95_duration_us,
            "by_kind": by_kind_json,
            "top_miss_queries": top_misses_json,
            "note": "Empty / low total_queries means the MCP layer hasn't logged enough \
                yet — exercise memory_search/get and re-run.",
        })))
    }
}

// ===========================================================================
//     retrieval_outcome_report — surfaced→used feedback readout (read-only)
// ===========================================================================

pub struct RetrievalOutcomeReportTool {
    hub: Hub,
}
impl RetrievalOutcomeReportTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for RetrievalOutcomeReportTool {
    fn name(&self) -> &'static str {
        "retrieval_outcome_report"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Read-only readout of the retrieval-feedback half of the \
                 learning loop: aggregates the `retrieval_surfacing` telemetry \
                 (surfaced→used) over the last `window_secs`. Reports overall \
                 used-rate, avg rank (overall vs when-used), per-mode counts, and \
                 the top reinforce candidates (memories whose surfacings were used) \
                 + decay candidates (surfaced ≥2× but never used). Rows exist only \
                 when the outcome collector (AGENT_BRIDGE_OUTCOME_COLLECTOR) is \
                 enabled — an empty report means the gate is off or nothing has \
                 accrued yet. Ambient bootstrap telemetry (mode=bootstrap) is \
                 excluded from used-rate/candidate aggregates (uncalibrated ambient \
                 signal); its volume stays visible in the per-mode counts. The telemetry table is FIFO ring-capped at \
                 RETRIEVAL_SURFACING_RING_CAP (50k rows ≈ 7 days of moderate use), \
                 so windows longer than the retained span under-report silently. \
                 Mutates nothing and carries no authority over ranking; \
                 it exists to calibrate a later, separately-gated reinforce/decay \
                 rule against the real distribution. Default window 7 days, top_n 15."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "window_secs": {
                        "type": "integer",
                        "minimum": 60,
                        "maximum": 31_536_000,
                        "default": 604_800,
                        "description": "Lookback window in seconds. Default 7 days. Capped to 1 year."
                    },
                    "top_n": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 200,
                        "default": 15,
                        "description": "Max reinforce/decay candidates returned each. Default 15."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let window_secs = args
            .get("window_secs")
            .and_then(|v| v.as_i64())
            .unwrap_or(604_800)
            .clamp(60, 31_536_000);
        let top_n = args
            .get("top_n")
            .and_then(|v| v.as_i64())
            .unwrap_or(15)
            .clamp(1, 200) as usize;

        let s = store.retrieval_outcome_summary(window_secs, top_n).await?;

        let used_rate = if s.total_surfacings > 0 {
            (s.used_surfacings as f64 / s.total_surfacings as f64 * 1000.0).round() / 1000.0
        } else {
            0.0
        };
        let mem_json = |m: &ab_store::RetrievalOutcomeMemory| {
            json!({
                "key": m.key,
                "surfaced_count": m.surfaced_count,
                "used_count": m.used_count,
                "used_ratio": if m.surfaced_count > 0 {
                    (m.used_count as f64 / m.surfaced_count as f64 * 1000.0).round() / 1000.0
                } else {
                    0.0
                },
                "avg_rank": (m.avg_rank * 100.0).round() / 100.0,
                "last_surfaced_at": m.last_surfaced_at,
            })
        };
        let by_mode_json: Vec<Value> = s
            .by_mode
            .iter()
            .map(|(m, n)| json!({ "mode": m, "count": n }))
            .collect();
        let reinforce_json: Vec<Value> = s.top_used.iter().map(mem_json).collect();
        let decay_json: Vec<Value> = s.top_never_used.iter().map(mem_json).collect();

        Ok(ToolResult::json_text(&json!({
            "window_start": s.window_start,
            "window_end": s.window_end,
            "window_secs": window_secs,
            "total_surfacings": s.total_surfacings,
            "used_surfacings": s.used_surfacings,
            "used_rate": used_rate,
            "distinct_memories": s.distinct_memories,
            "distinct_used_memories": s.distinct_used_memories,
            "avg_rank_overall": (s.avg_rank_overall * 100.0).round() / 100.0,
            "avg_rank_when_used": (s.avg_rank_when_used * 100.0).round() / 100.0,
            "by_mode": by_mode_json,
            "reinforce_candidates": reinforce_json,
            "decay_candidates": decay_json,
            "note": "surfaced→used telemetry (AGENT_BRIDGE_OUTCOME_COLLECTOR). Read-only; \
                empty = gate off or nothing accrued yet. reinforce_candidates = memories \
                whose surfacings were used; decay_candidates = surfaced ≥2× but never used.",
        })))
    }
}

// ===========================================================================
//    retrieval_outcome_shadow — what-if harness for a reinforce/decay rule
// ===========================================================================

/// The parameterized rule `retrieval_outcome_shadow` simulates. Nothing here
/// writes — the harness exists so the rule can be calibrated against the real
/// surfaced→used distribution BEFORE any behavior-changing apply is built
/// (which stays a separately-gated follow-up).
#[derive(Debug, Clone, Copy)]
struct RetrievalShadowParams {
    reinforce_step: f64,
    decay_step: f64,
    min_surfaced_for_decay: u64,
    floor: f64,
    ceiling: f64,
    protect_classes: bool,
}

/// One simulated outcome row (still nothing written).
#[derive(Debug, Clone)]
struct RetrievalShadowChange {
    key: String,
    surfaced_count: u64,
    used_count: u64,
    avg_rank: f64,
    importance: f64,
    would_be: f64,
    action: &'static str,
}

/// Pure rule math — delegates to [`crate::retrieval_outcome::classify_rows`],
/// the SINGLE source shared with the behavior-changing
/// `retrieval_outcome_apply` pass, so preview and apply can never disagree on
/// what the rule prescribes. Classes are disjoint by construction (used > 0
/// vs used == 0); monotone clamps mirror the memory_decay_unused floor
/// semantics. Returns (changes, at_ceiling, at_floor).
fn retrieval_shadow_apply_rule(
    rows: &[ab_store::RetrievalOutcomeShadowRow],
    p: &RetrievalShadowParams,
) -> (Vec<RetrievalShadowChange>, u64, u64, Vec<String>) {
    let classified = crate::retrieval_outcome::classify_rows(
        rows,
        &crate::retrieval_outcome::RuleParams {
            reinforce_step: p.reinforce_step,
            decay_step: p.decay_step,
            min_surfaced_for_decay: p.min_surfaced_for_decay,
            floor: p.floor,
            ceiling: p.ceiling,
            protect_classes: p.protect_classes,
        },
    );
    let changes = classified
        .changes
        .into_iter()
        .map(|c| RetrievalShadowChange {
            key: c.key,
            surfaced_count: c.surfaced_count,
            used_count: c.used_count,
            avg_rank: c.avg_rank,
            importance: c.importance,
            would_be: c.would_be,
            action: c.action,
        })
        .collect();
    (
        changes,
        classified.at_ceiling_keys.len() as u64,
        classified.at_floor_keys.len() as u64,
        classified.protected_decay_keys,
    )
}

pub struct RetrievalOutcomeShadowTool {
    hub: Hub,
}
impl RetrievalOutcomeShadowTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for RetrievalOutcomeShadowTool {
    fn name(&self) -> &'static str {
        "retrieval_outcome_shadow"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "READ-ONLY what-if harness for a retrieval-feedback \
                 reinforce/decay rule: simulates 'bump importance of memories whose \
                 surfacings were used (+reinforce_step, ceiling-capped), shave memories \
                 surfaced ≥min_surfaced_for_decay times but never used (−decay_step, \
                 floor-capped)' against the live `retrieval_surfacing` telemetry and \
                 CURRENT importances, and reports exactly what WOULD change. Writes \
                 NOTHING — the behavior-changing apply is a separately-gated follow-up; \
                 this harness exists so its parameters get calibrated against the real \
                 surfaced→used distribution instead of guessed. Same telemetry bound as \
                 retrieval_outcome_report (collector gate, FIFO ring cap). Honest-flags \
                 low_sample when the distribution is too thin to calibrate against."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "window_secs": {
                        "type": "integer",
                        "minimum": 60,
                        "maximum": 31_536_000,
                        "default": 604_800,
                        "description": "Telemetry lookback in seconds. Default 7 days."
                    },
                    "reinforce_step": {
                        "type": "number",
                        "minimum": 0.0,
                        "maximum": 1.0,
                        "default": 0.05,
                        "description": "Importance bump for memories with ≥1 used surfacing. \
                            0.0 disables this half (its rows then report no change). \
                            Default 0.05 (the memory_decay_unused op-class step)."
                    },
                    "decay_step": {
                        "type": "number",
                        "minimum": 0.0,
                        "maximum": 1.0,
                        "default": 0.05,
                        "description": "Importance shave for surfaced-never-used memories. \
                            0.0 disables this half (its rows then report no change). Default 0.05."
                    },
                    "min_surfaced_for_decay": {
                        "type": "integer",
                        "minimum": 1,
                        "default": 2,
                        "description": "Only decay memories surfaced at least this many times with \
                            zero uses (matches the report's decay-candidate rule). Default 2."
                    },
                    "floor": {
                        "type": "number",
                        "minimum": 0.0,
                        "maximum": 1.0,
                        "default": 0.1,
                        "description": "Decay never takes importance below this; rows already at/below \
                            are skipped, not lifted. Default 0.1 (memory_decay_unused floor)."
                    },
                    "ceiling": {
                        "type": "number",
                        "minimum": 0.0,
                        "maximum": 1.0,
                        "default": 0.9,
                        "description": "Reinforce never takes importance above this; rows already \
                            at/above are skipped, not pulled down. Default 0.9 (valence-rule ceiling)."
                    },
                    "protect": {
                        "type": "boolean",
                        "description": "Exempt constraint-class rows (kind=feedback, continuity \
                            must_block/constraint/warning tags) from the decay half — their ambient \
                            consumption channel never stamps used_at, so never-used telemetry on \
                            them is attribution bias. Default: on unless \
                            AB_RETRIEVAL_OUTCOME_APPLY_PROTECT_DISABLE=1."
                    },
                    "top_n": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 200,
                        "default": 15,
                        "description": "Max would-change rows listed (summary always covers ALL rows). Default 15."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let window_secs = args
            .get("window_secs")
            .and_then(|v| v.as_i64())
            .unwrap_or(604_800)
            .clamp(60, 31_536_000);
        let f = |key: &str, default: f64| {
            args.get(key)
                .and_then(|v| v.as_f64())
                .unwrap_or(default)
                .clamp(0.0, 1.0)
        };
        let params = RetrievalShadowParams {
            reinforce_step: f("reinforce_step", 0.05),
            decay_step: f("decay_step", 0.05),
            min_surfaced_for_decay: args
                .get("min_surfaced_for_decay")
                .and_then(|v| v.as_u64())
                .unwrap_or(2)
                .max(1),
            floor: f("floor", 0.1),
            ceiling: f("ceiling", 0.9),
            protect_classes: args
                .get("protect")
                .and_then(Value::as_bool)
                .unwrap_or_else(crate::retrieval_outcome::protect_classes_enabled),
        };
        let top_n = args
            .get("top_n")
            .and_then(|v| v.as_i64())
            .unwrap_or(15)
            .clamp(1, 200) as usize;

        let rows = store.retrieval_outcome_shadow_rows(window_secs).await?;
        let rows_considered = rows.len();
        let (changes, at_ceiling, at_floor, protected_keys) =
            retrieval_shadow_apply_rule(&rows, &params);

        let round3 = |x: f64| (x * 1000.0).round() / 1000.0;
        let (mut n_reinforce, mut n_decay) = (0u64, 0u64);
        let (mut delta_reinforce, mut delta_decay) = (0.0f64, 0.0f64);
        for ch in &changes {
            let d = ch.would_be - ch.importance;
            if ch.action == "reinforce" {
                n_reinforce += 1;
                delta_reinforce += d;
            } else {
                n_decay += 1;
                delta_decay += d;
            }
        }
        // Store order is used DESC, surfaced DESC, key ASC — reinforce rows
        // naturally lead. Keep it; just truncate honestly.
        let truncated = changes.len() > top_n;
        let changes_json: Vec<Value> = changes
            .iter()
            .take(top_n)
            .map(|ch| {
                json!({
                    "key": ch.key,
                    "action": ch.action,
                    "surfaced_count": ch.surfaced_count,
                    "used_count": ch.used_count,
                    "avg_rank": (ch.avg_rank * 100.0).round() / 100.0,
                    "importance": round3(ch.importance),
                    "would_be": round3(ch.would_be),
                    "delta": round3(ch.would_be - ch.importance),
                })
            })
            .collect();

        // Below ~10 distinct memories the distribution can't anchor thresholds
        // (the collector doc itself warns the signal is sparse) — flag it.
        let low_sample = rows_considered < 10;

        Ok(ToolResult::json_text(&json!({
            "schema": "agent_bridge.retrieval_outcome_shadow.v0",
            "params": {
                "window_secs": window_secs,
                "reinforce_step": params.reinforce_step,
                "decay_step": params.decay_step,
                "min_surfaced_for_decay": params.min_surfaced_for_decay,
                "floor": params.floor,
                "ceiling": params.ceiling,
                "protect_classes": params.protect_classes,
            },
            "rows_considered": rows_considered,
            "reinforce": {
                "would_change": n_reinforce,
                "already_at_ceiling": at_ceiling,
                "total_delta": round3(delta_reinforce),
            },
            "decay": {
                "would_change": n_decay,
                "already_at_floor": at_floor,
                "protected_skipped": protected_keys.len(),
                "total_delta": round3(delta_decay),
            },
            "protected_keys": protected_keys,
            "net_importance_delta": round3(delta_reinforce + delta_decay),
            "low_sample": low_sample,
            "changes": changes_json,
            "changes_truncated": truncated,
            "note": "WHAT-IF ONLY — nothing was written. low_sample=true means too few \
                distinct memories to calibrate against; let the collector accrue longer. \
                Non-active memories and one-off unused surfacings are excluded by design.",
        })))
    }
}

// ===========================================================================
//   memory_fusion_shadow_report — R2 passive RRF-fusion shadow summary
// ===========================================================================

pub struct MemoryFusionShadowReportTool {
    hub: Hub,
}
impl MemoryFusionShadowReportTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for MemoryFusionShadowReportTool {
    fn name(&self) -> &'static str {
        "memory_fusion_shadow_report"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "READ-ONLY summary of the R2 fusion-shadow telemetry (forum \
                 #147): while AGENT_BRIDGE_FUSION_SHADOW is enabled, every default \
                 (mode=fts) memory_search passively records how its returned page \
                 WOULD change if a semantic leg were RRF-fused in (k=60, the \
                 mode=hybrid math) — overlap@k, gained/lost keys, rank displacement — \
                 without altering a single returned byte. Aggregates those rows: \
                 sample/skip counts, mean overlap, gained/lost totals, top \
                 displacement examples. Evidence for the default-flip decision; \
                 authorizes nothing."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "window_secs": {
                        "type": "integer", "minimum": 60, "maximum": 31_536_000, "default": 604_800,
                        "description": "Telemetry lookback in seconds. Default 7 days."
                    },
                    "top_n": {
                        "type": "integer", "minimum": 1, "maximum": 50, "default": 5,
                        "description": "Max top-displacement example rows. Default 5."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let window_secs = args
            .get("window_secs")
            .and_then(|v| v.as_i64())
            .unwrap_or(604_800)
            .clamp(60, 31_536_000);
        let top_n = args
            .get("top_n")
            .and_then(|v| v.as_i64())
            .unwrap_or(5)
            .clamp(1, 50) as usize;

        let rows = store.fusion_shadow_rows(window_secs).await?;
        let mut skips_by_reason: std::collections::BTreeMap<String, u64> =
            std::collections::BTreeMap::new();
        for r in rows.iter().filter(|r| r.skipped) {
            *skips_by_reason
                .entry(r.skip_reason.clone().unwrap_or_else(|| "unknown".into()))
                .or_insert(0) += 1;
        }
        let mut measured: Vec<&FusionShadowSample> = rows.iter().filter(|r| !r.skipped).collect();
        let n = measured.len();
        let mean = |f: fn(&FusionShadowSample) -> f64| -> f64 {
            if n == 0 {
                0.0
            } else {
                measured.iter().map(|r| f(r)).sum::<f64>() / n as f64
            }
        };
        let avg_overlap = mean(|r| r.overlap);
        let avg_mean_abs_shift = mean(|r| r.mean_abs_shift);
        let gained_total: u64 = measured.iter().map(|r| r.gained as u64).sum();
        let lost_total: u64 = measured.iter().map(|r| r.lost as u64).sum();
        let unchanged_pages = measured
            .iter()
            .filter(|r| r.gained == 0 && r.lost == 0 && r.max_abs_shift == 0)
            .count();

        // Top displacement examples: pages fusion would perturb the most.
        measured.sort_by(|a, b| {
            (b.gained + b.lost, b.max_abs_shift)
                .cmp(&(a.gained + a.lost, a.max_abs_shift))
                .then_with(|| {
                    b.mean_abs_shift
                        .partial_cmp(&a.mean_abs_shift)
                        .unwrap_or(std::cmp::Ordering::Equal)
                })
                .then_with(|| b.at.cmp(&a.at))
        });
        let round3 = |x: f64| (x * 1000.0).round() / 1000.0;
        let examples: Vec<Value> = measured
            .iter()
            .take(top_n)
            .map(|r| {
                json!({
                    "at": r.at, "query": r.query, "k": r.k,
                    "actual_n": r.actual_n, "semantic_n": r.semantic_n,
                    "overlap": round3(r.overlap),
                    "gained": r.gained, "lost": r.lost,
                    "gained_keys": r.gained_keys, "lost_keys": r.lost_keys,
                    "mean_abs_shift": round3(r.mean_abs_shift),
                    "max_abs_shift": r.max_abs_shift,
                })
            })
            .collect();

        Ok(ToolResult::json_text(&json!({
            "schema": "agent_bridge.memory_fusion_shadow.v0",
            "read_only": true,
            "gate_env": "AGENT_BRIDGE_FUSION_SHADOW",
            "window_secs": window_secs,
            "samples": n,
            "skips": (rows.len() - n) as u64,
            "skips_by_reason": skips_by_reason,
            "avg_overlap": round3(avg_overlap),
            "gained_total": gained_total,
            "lost_total": lost_total,
            "avg_mean_abs_shift": round3(avg_mean_abs_shift),
            "unchanged_pages": unchanged_pages,
            // Below ~10 measured pages the averages can't anchor a flip decision.
            "low_sample": n < 10,
            "top_displacement_examples": examples,
            "note": "SHADOW ONLY — the measured searches returned their normal fts \
                pages untouched. low_sample=true means too few measured pages to \
                anchor a default-flip decision; leave the gate on longer.",
        })))
    }
}

// ===========================================================================
//   retrieval_outcome_apply — behavior-changing reinforce/decay pass
// ===========================================================================

pub struct RetrievalOutcomeApplyTool {
    hub: Hub,
}
impl RetrievalOutcomeApplyTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for RetrievalOutcomeApplyTool {
    fn name(&self) -> &'static str {
        "retrieval_outcome_apply"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Behavior-changing counterpart of retrieval_outcome_shadow: \
                 run ONE reinforce/decay pass over the retrieval_surfacing telemetry \
                 (surfaced→used) against live importances. Memories with a used \
                 surfacing gain +reinforce_step (ceiling-capped); memories surfaced \
                 ≥min_surfaced_for_decay times with zero uses lose −decay_step \
                 (floor-capped). Each telemetry row is counted toward at most ONE \
                 action (v40 consumed_at marker) — immediate re-runs are no-ops, so \
                 pacing comes from evidence accrual, not call frequency. Only rows \
                 older than 6h are eligible (used_at attribution windows must close \
                 first); below-threshold evidence stays pending and accumulates. \
                 Default confirm_apply=false ⇒ dry-run preview of exactly the slice a \
                 confirmed pass would consume, no writes. With confirm_apply=true a \
                 full rollback map (old→new per key) is persisted as an audit memory \
                 BEFORE any importance moves. Importance-only op class (same as \
                 memory_decay_unused); never touches tags, content, or biocortex. \
                 Ambient bootstrap telemetry (mode=bootstrap, from session_bootstrap \
                 injections) is excluded from the aggregate and merely retired each \
                 confirmed pass (ambient_retired) — stage-1 telemetry-only, pending a \
                 calibrated ambient rule. Constraint-class rows (kind=feedback, \
                 continuity must_block/constraint/warning tags) are decay-exempt by \
                 default — their ambient consumption channel never stamps used_at, so \
                 never-used telemetry on them is attribution bias; they are reported \
                 as protected_skipped and their evidence is still consumed \
                 (AB_RETRIEVAL_OUTCOME_APPLY_PROTECT_DISABLE=1 disables). The daemon \
                 runs this automatically only when \
                 AGENT_BRIDGE_RETRIEVAL_OUTCOME_APPLY is enabled (default OFF)."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "reinforce_step": {
                        "type": "number", "minimum": 0.0, "maximum": 1.0, "default": 0.05,
                        "description": "Importance bump for memories with ≥1 used surfacing. \
                            0.0 disables this half. Default 0.05 (memory_decay_unused op-class step)."
                    },
                    "decay_step": {
                        "type": "number", "minimum": 0.0, "maximum": 1.0, "default": 0.05,
                        "description": "Importance shave for surfaced-never-used memories. \
                            0.0 disables this half. Default 0.05."
                    },
                    "min_surfaced_for_decay": {
                        "type": "integer", "minimum": 1, "default": 2,
                        "description": "Only decay memories with at least this many pending unused \
                            surfacings. Below-threshold rows stay pending (NOT consumed). Default 2."
                    },
                    "floor": {
                        "type": "number", "minimum": 0.0, "maximum": 1.0, "default": 0.1,
                        "description": "Decay never takes importance below this; rows already at/below \
                            are skipped (their telemetry is still consumed). Default 0.1."
                    },
                    "ceiling": {
                        "type": "number", "minimum": 0.0, "maximum": 1.0, "default": 0.9,
                        "description": "Reinforce never takes importance above this; rows already \
                            at/above are skipped (their telemetry is still consumed). Default 0.9."
                    },
                    "max_changes": {
                        "type": "integer", "minimum": 1, "maximum": 500, "default": 200,
                        "description": "Cap on importance writes this pass. Deferred rows keep their \
                            telemetry unconsumed and are reported in capped_out — never silently dropped."
                    },
                    "protect": {
                        "type": "boolean",
                        "description": "Exempt constraint-class rows (kind=feedback, continuity \
                            must_block/constraint/warning tags) from the decay half. Default: on \
                            unless AB_RETRIEVAL_OUTCOME_APPLY_PROTECT_DISABLE=1."
                    },
                    "confirm_apply": {
                        "type": "boolean", "default": false,
                        "description": "Final explicit write confirmation. Default false ⇒ preview only: \
                            no importance writes, no telemetry consumption."
                    },
                    "top_n": {
                        "type": "integer", "minimum": 1, "maximum": 200, "default": 15,
                        "description": "Max change rows listed in the result (counts always cover ALL rows)."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let f = |key: &str, default: f64| {
            args.get(key)
                .and_then(|v| v.as_f64())
                .unwrap_or(default)
                .clamp(0.0, 1.0)
        };
        let params = crate::retrieval_outcome::RuleParams {
            reinforce_step: f("reinforce_step", 0.05),
            decay_step: f("decay_step", 0.05),
            min_surfaced_for_decay: args
                .get("min_surfaced_for_decay")
                .and_then(|v| v.as_u64())
                .unwrap_or(2)
                .max(1),
            floor: f("floor", 0.1),
            ceiling: f("ceiling", 0.9),
            protect_classes: args
                .get("protect")
                .and_then(Value::as_bool)
                .unwrap_or_else(crate::retrieval_outcome::protect_classes_enabled),
        };
        let max_changes = args
            .get("max_changes")
            .and_then(|v| v.as_i64())
            .unwrap_or(200)
            .clamp(1, 500) as usize;
        let confirm = args
            .get("confirm_apply")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let top_n = args
            .get("top_n")
            .and_then(|v| v.as_i64())
            .unwrap_or(15)
            .clamp(1, 200) as usize;

        if let Err(e) = params.validate() {
            return Ok(ToolResult::error(e));
        }
        let report = crate::retrieval_outcome::run_apply_pass(
            &store,
            &params,
            max_changes,
            confirm,
            unix_now_secs(),
        )
        .await?;

        let round3 = |x: f64| (x * 1000.0).round() / 1000.0;
        let (mut n_reinforce, mut n_decay) = (0u64, 0u64);
        for ch in &report.changes {
            if ch.action == "reinforce" {
                n_reinforce += 1;
            } else {
                n_decay += 1;
            }
        }
        let truncated = report.changes.len() > top_n;
        let changes_json: Vec<Value> = report
            .changes
            .iter()
            .take(top_n)
            .map(|ch| {
                json!({
                    "key": ch.key,
                    "action": ch.action,
                    "surfaced_count": ch.surfaced_count,
                    "used_count": ch.used_count,
                    "avg_rank": (ch.avg_rank * 100.0).round() / 100.0,
                    "importance": round3(ch.importance),
                    "new_importance": round3(ch.would_be),
                    "delta": round3(ch.would_be - ch.importance),
                })
            })
            .collect();

        Ok(ToolResult::json_text(&json!({
            "schema": "agent_bridge.retrieval_outcome_apply.v0",
            "dry_run": report.dry_run,
            "params": {
                "reinforce_step": params.reinforce_step,
                "decay_step": params.decay_step,
                "min_surfaced_for_decay": params.min_surfaced_for_decay,
                "floor": params.floor,
                "ceiling": params.ceiling,
                "protect_classes": params.protect_classes,
                "max_changes": max_changes,
                "maturation_secs": crate::retrieval_outcome::APPLY_MATURATION_SECS,
            },
            "rows_considered": report.rows_considered,
            "reinforce": n_reinforce,
            "decay": n_decay,
            "at_ceiling": report.at_ceiling,
            "at_floor": report.at_floor,
            "zero_step": report.zero_step,
            "protected_skipped": report.protected_skipped,
            "pending_below_min": report.pending_below_min,
            "capped_out": report.capped_out,
            "applied": report.applied,
            "failed": report.failed,
            "skipped_raced": report.skipped_raced,
            "consumed_rows": report.consumed_rows,
            "consumed_noaction_keys": report.consumed_noaction_keys,
            "orphans_consumed": report.orphans_consumed,
            "ambient_retired": report.ambient_retired,
            "net_importance_delta": round3(report.net_importance_delta),
            "audit_memory_key": report.audit_memory_key,
            "changes": changes_json,
            "changes_truncated": truncated,
            "note": if report.dry_run {
                "DRY-RUN — nothing written, nothing consumed. This previews the exact \
                 unconsumed+mature slice a confirmed pass would act on (unlike \
                 retrieval_outcome_shadow, which windows over ALL telemetry). \
                 Rollback: restore old values from audit_memory_key via \
                 memory_set_importance."
            } else {
                "APPLIED — importance moved and telemetry consumed. Rollback: restore \
                 old values from the audit_memory_key record via \
                 memory_set_importance(key, old_importance)."
            },
        })))
    }
}

// ===========================================================================
//             memory_graph_topology — graph centrality readiness readout
// ===========================================================================

pub struct MemoryGraphTopologyTool {
    hub: Hub,
}
impl MemoryGraphTopologyTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for MemoryGraphTopologyTool {
    fn name(&self) -> &'static str {
        "memory_graph_topology"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Read-only memory graph topology snapshot for ranking experiments. \
                 Reports orphan rate, degree buckets, top hubs, and evolved-edge coverage. \
                 Use this before adding PageRank-like centrality into retrieval: it measures \
                 whether the graph is healthy enough for a bounded centrality prior without \
                 changing memory_search ranking."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "scope": {
                        "type": "string",
                        "description": "Optional memory scope, e.g. project:/abs/path or domain:rust. When set, reports an induced-subgraph topology for records selected by scope_mode."
                    },
                    "scope_mode": {
                        "type": "string",
                        "enum": ["local_only", "local_plus_global", "exploratory"],
                        "description": "Scope selection for scoped topology. local_only keeps matching project/domain rows; local_plus_global also includes global/unscoped rows; exploratory includes all source rows."
                    },
                    "skip_kinds": {
                        "type": "array",
                        "items": { "type": "string" },
                        "description": "Memory kinds to exclude from the topology denominator, e.g. work_memory/session_handoff/snapshot for durable-readiness checks."
                    },
                    "skip_tags": {
                        "type": "array",
                        "items": { "type": "string" },
                        "description": "Memory tags to exclude from the topology denominator, e.g. auto_curated/alert/ttl:7d."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };

        let requested_scope = args
            .get("scope")
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty());
        let scope_mode = MemorySearchScopeMode::parse(
            args.get("scope_mode")
                .and_then(|v| v.as_str())
                .map(str::trim)
                .filter(|s| !s.is_empty()),
            false,
        );
        let skip_tags = memory_string_array_arg(&args, "skip_tags", &[]);
        let skip_kinds = memory_string_array_arg(&args, "skip_kinds", &[]);
        let use_filtered_path =
            requested_scope.is_some() || !skip_tags.is_empty() || !skip_kinds.is_empty();

        let topo = if use_filtered_path {
            let records = store
                .list_memories(None, MemoryListSort::Newest, 10_000)
                .await?;
            let visible_records: Vec<MemoryRecord> = records
                .into_iter()
                .filter(|rec| {
                    memory_graph_topology_record_visible(
                        rec,
                        requested_scope,
                        scope_mode,
                        &skip_tags,
                        &skip_kinds,
                    )
                })
                .collect();
            let mut edges_by_key: HashMap<String, Vec<MemoryEdge>> = HashMap::new();
            for rec in &visible_records {
                edges_by_key.insert(rec.key.clone(), store.memory_neighbors(&rec.key).await?);
            }
            memory_graph_topology_from_records(&visible_records, &edges_by_key)
        } else {
            store.graph_topology().await?
        };
        let active_total = topo.non_skill_active_total.max(1);
        let orphan_fraction = topo.orphan_count as f64 / active_total as f64;
        let p4_evolved_fraction = topo.p4_evolved_coverage as f64 / active_total as f64;
        let top_hub_degree = topo.top_5_hubs.first().map(|(_, d)| *d).unwrap_or(0);
        let top_hub_fraction = top_hub_degree as f64 / active_total as f64;

        let pagerank_readiness = if topo.non_skill_active_total == 0 {
            "empty_graph"
        } else if orphan_fraction > 0.35 {
            "needs_graph_hygiene_before_rank_prior"
        } else if top_hub_fraction > 0.15 {
            "hub_risk_cap_centrality_boost"
        } else {
            "observe_then_bound_centrality_boost"
        };

        let degree_histogram: Vec<Value> = topo
            .degree_histogram
            .iter()
            .map(|(bucket, count)| json!({ "bucket": bucket, "count": count }))
            .collect();
        let top_5_hubs: Vec<Value> = topo
            .top_5_hubs
            .iter()
            .map(|(key, degree)| json!({ "key": key, "degree": degree }))
            .collect();

        Ok(ToolResult::json_text(&json!({
            "non_skill_active_total": topo.non_skill_active_total,
            "orphan_count": topo.orphan_count,
            "orphan_fraction": (orphan_fraction * 1000.0).round() / 1000.0,
            "degree_histogram": degree_histogram,
            "top_5_hubs": top_5_hubs,
            "top_hub_degree": top_hub_degree,
            "top_hub_fraction": (top_hub_fraction * 1000.0).round() / 1000.0,
            "p4_evolved_coverage": topo.p4_evolved_coverage,
            "p4_evolved_fraction": (p4_evolved_fraction * 1000.0).round() / 1000.0,
            "pagerank_readiness": pagerank_readiness,
            "scope": requested_scope,
            "scope_mode": requested_scope.map(|_| scope_mode.label()),
            "skip_tags": skip_tags,
            "skip_kinds": skip_kinds,
            "edge_scope": use_filtered_path.then_some("induced_subgraph"),
            "ranking_note": "This tool does not run PageRank and does not alter memory_search. \
                It is the cheap preflight for deciding whether a bounded centrality prior \
                is safe to test.",
        })))
    }
}

// ===========================================================================
//        memory_substrate_audit — P-ε substrate-readiness aggregate
// ===========================================================================

pub struct MemorySubstrateAuditTool {
    hub: Hub,
}
impl MemorySubstrateAuditTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for MemorySubstrateAuditTool {
    fn name(&self) -> &'static str {
        "memory_substrate_audit"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "P-ε — Substrate-Readiness Audit. Read-only aggregate of 7 metric \
                 families relevant to L1+L2 substrate state: M1 connected components of \
                 cofires/co_referenced edges (hairball detection), M2 edges per type, \
                 M3 coactivation table growth, M4 retire-state balance + 7d delta, \
                 M5 fraction of active memories with ≥1 L2 edge, M6 embedding backend \
                 distribution, M7 signal-fidelity Spearman + verdict, M8 query-side \
                 health. Pure composition over existing trait methods; no schema or \
                 write paths. See `docs/DESIGN-P-epsilon-substrate-readiness-audit.md`."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "window_secs": {
                        "type": "integer",
                        "minimum": 60,
                        "maximum": 31_536_000,
                        "default": 604_800,
                        "description": "Lookback window for M3 recent_active / M4 delta / M8 query stats. Default 7 days."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let window_secs = args
            .get("window_secs")
            .and_then(|v| v.as_i64())
            .unwrap_or(604_800)
            .clamp(60, 31_536_000) as u64;

        let r = store.memory_substrate_audit(window_secs).await?;

        let per_type_json: serde_json::Map<String, Value> = r
            .m2_edges
            .per_type
            .iter()
            .map(|(k, v)| (k.clone(), json!(v)))
            .collect();
        let by_kind_json: Vec<Value> = r
            .m8_query
            .by_kind
            .iter()
            .map(|(k, n)| json!({ "kind": k, "count": n }))
            .collect();

        Ok(ToolResult::json_text(&json!({
            "version": r.version,
            "generated_at_secs": r.generated_at_secs,
            "window_secs": r.window_secs,
            "m1_components": {
                "min_size": r.m1_components.min_size,
                "components": r.m1_components.components,
                "total_clustered_nodes": r.m1_components.total_clustered_nodes,
                "largest_size": r.m1_components.largest_size,
                "distribution": r.m1_components.distribution,
            },
            "m2_edges": {
                "total": r.m2_edges.total,
                "per_type": per_type_json,
                "density_per_active": (r.m2_edges.density_per_active * 1000.0).round() / 1000.0,
            },
            "m3_coactivation": {
                "total_pairs": r.m3_coactivation.total_pairs,
                "recent_active": r.m3_coactivation.recent_active,
                "avg_count": (r.m3_coactivation.avg_count * 100.0).round() / 100.0,
                "max_count": r.m3_coactivation.max_count,
                "est_daily_new_pairs":
                    (r.m3_coactivation.est_daily_new_pairs * 100.0).round() / 100.0,
            },
            "m4_retire": {
                "active": r.m4_retire.active,
                "archived": r.m4_retire.archived,
                "superseded": r.m4_retire.superseded,
                "tombstoned": r.m4_retire.tombstoned,
                "archived_fraction": (r.m4_retire.archived_fraction * 1000.0).round() / 1000.0,
                "delta": {
                    "active": r.m4_retire.delta.active,
                    "archived": r.m4_retire.delta.archived,
                    "superseded": r.m4_retire.delta.superseded,
                    "tombstoned": r.m4_retire.delta.tombstoned,
                    "is_approximate": r.m4_retire.delta.is_approximate,
                },
            },
            "m5_edge_coverage": {
                "active_with_l2_edge": r.m5_edge_coverage.active_with_l2_edge,
                "active_total": r.m5_edge_coverage.active_total,
                "fraction": (r.m5_edge_coverage.fraction * 1000.0).round() / 1000.0,
            },
            "m6_embedding": {
                "onnx": r.m6_embedding.onnx,
                "hash": r.m6_embedding.hash,
                "unknown": r.m6_embedding.unknown,
                "total": r.m6_embedding.total,
                "stale_fraction": (r.m6_embedding.stale_fraction * 1000.0).round() / 1000.0,
            },
            "m7_signal_fidelity": {
                "r_all": (r.m7_signal_fidelity.r_all * 1000.0).round() / 1000.0,
                "r_touched": (r.m7_signal_fidelity.r_touched * 1000.0).round() / 1000.0,
                "n_touched": r.m7_signal_fidelity.n_touched,
                "verdict": r.m7_signal_fidelity.verdict,
            },
            "m8_query": {
                "hit_rate": (r.m8_query.hit_rate * 1000.0).round() / 1000.0,
                "p50_us": r.m8_query.p50_duration_us,
                "p95_us": r.m8_query.p95_duration_us,
                "total_queries": r.m8_query.total_queries,
                "avg_top_hit_age_days":
                    (r.m8_query.avg_top_hit_age_secs / 86_400.0 * 100.0).round() / 100.0,
                "by_kind": by_kind_json,
            },
        })))
    }
}

// ===========================================================================
//             substrate_stats — v22 Phase 2.3 — runtime grid state read
// ===========================================================================

/// Phase 2.3 MCP wrapper around `ab_seed_bridge::current().stats()`. Complements
/// `memory_substrate_audit` (P-ε): audit reads L1/L2 SQL trace tables;
/// `substrate_stats` reads the in-process Seed grid runtime state.
///
/// Hub-less by design — substrate is a process-wide `OnceLock`, not Hub-mediated.
pub struct SubstrateStatsTool;

impl SubstrateStatsTool {
    pub fn new() -> Self {
        Self
    }
}

impl Default for SubstrateStatsTool {
    fn default() -> Self {
        Self::new()
    }
}

#[async_trait]
impl McpTool for SubstrateStatsTool {
    fn name(&self) -> &'static str {
        "substrate_stats"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "v22 Phase 2.3 — runtime state of the in-process Seed substrate (L2). \
                 Reports backend, N (neurons), D (substrate dim), step_count, last surprise \
                 mean/max, and connection mean-abs. Substrate is opt-in via `AB_SUBSTRATE=1` \
                 env var; when unset, returns `{installed: false}` + hint. Complements \
                 `memory_substrate_audit` (which reads SQL trace, not the live grid)."
                .into(),
            input_schema: json!({ "type": "object", "properties": {} }),
        }
    }
    async fn execute(&self, _args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let env_enabled = ab_seed_bridge::env_enabled();
        let stats = ab_seed_bridge::current().as_ref().map(|s| s.stats());
        let payload = match stats {
            Some(s) => json!({
                "env_var": ab_seed_bridge::SUBSTRATE_ENV_VAR,
                "env_enabled": env_enabled,
                "installed": true,
                "stats": {
                    "backend_inner": s.backend_name,
                    "n": s.n,
                    "d": s.d,
                    "outer_dim": s.outer_dim,
                    "step_count": s.step_count,
                    "last_surprise_mean": (s.last_surprise_mean as f64 * 10000.0).round() / 10000.0,
                    "last_surprise_max": (s.last_surprise_max as f64 * 10000.0).round() / 10000.0,
                    "connection_mean_abs": (s.connection_mean_abs as f64 * 1_000_000.0).round() / 1_000_000.0,
                },
            }),
            None => json!({
                "env_var": ab_seed_bridge::SUBSTRATE_ENV_VAR,
                "env_enabled": env_enabled,
                "installed": false,
                "hint": if env_enabled {
                    "env set but substrate not installed — process likely started before install_default() ran"
                } else {
                    "set AB_SUBSTRATE=1 in env and relaunch the long-lived MCP process to enable"
                },
            }),
        };
        Ok(ToolResult::json_text(&payload))
    }
}

// ===========================================================================
//             substrate_neighbors_of — v22 Phase 3 (A) topology query
// ===========================================================================

/// v22 §3.5 Phase 3 (A) — read-only topology query over the in-process
/// Seed substrate. Returns up to `k` other keys that the neuron(s) which
/// fired on `key` connect to most strongly (summed absolute connection
/// weight). Substrate must be installed (`AB_SUBSTRATE=1`); when not
/// installed, returns `{installed: false, neighbors: []}` — same
/// ablation contract as `SubstrateStatsTool`.
pub struct SubstrateNeighborsTool;

impl SubstrateNeighborsTool {
    pub fn new() -> Self {
        Self
    }
}

impl Default for SubstrateNeighborsTool {
    fn default() -> Self {
        Self::new()
    }
}

#[async_trait]
impl McpTool for SubstrateNeighborsTool {
    fn name(&self) -> &'static str {
        "substrate_neighbors_of"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "v22 Phase 3 (A) — substrate-topology neighbors. \
                 For `key`, return up to `k` other keys that the in-process Seed \
                 substrate's neuron(s) which most recently won on `key` connect \
                 to most strongly. Read-only over the live grid; no mutation, no \
                 access bump. Substrate is opt-in via `AB_SUBSTRATE=1`; when not \
                 installed, returns `{installed: false, neighbors: []}`. Use to \
                 measure v22 §4 P2 (Spearman vs α cofires ≥ 0.4); do NOT use as \
                 default retrieval bias yet — that's gated on P2 PASS."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "key": { "type": "string", "description": "Memory key to query." },
                    "k": { "type": "integer", "minimum": 0, "default": 20,
                           "description": "Max number of distinct neighbor keys to return." }
                },
                "required": ["key"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let key = args.get("key").and_then(|v| v.as_str()).unwrap_or("");
        let k = args
            .get("k")
            .and_then(|v| v.as_u64())
            .map(|n| n as usize)
            .unwrap_or(20);
        let env_enabled = ab_seed_bridge::env_enabled();
        let backend = ab_seed_bridge::current();
        let payload = match backend.as_ref() {
            Some(b) => {
                let pairs = b.neighbors_of(key, k);
                let neighbors: Vec<Value> = pairs
                    .into_iter()
                    .map(|(k_text, score)| {
                        let s = (score as f64 * 1_000_000.0).round() / 1_000_000.0;
                        json!({ "key": k_text, "score": s })
                    })
                    .collect();
                json!({
                    "env_var": ab_seed_bridge::SUBSTRATE_ENV_VAR,
                    "env_enabled": env_enabled,
                    "installed": true,
                    "key": key,
                    "k": k,
                    "neighbors": neighbors,
                })
            }
            None => json!({
                "env_var": ab_seed_bridge::SUBSTRATE_ENV_VAR,
                "env_enabled": env_enabled,
                "installed": false,
                "key": key,
                "k": k,
                "neighbors": [],
                "hint": if env_enabled {
                    "env set but substrate not installed — process likely started before install_default() ran"
                } else {
                    "set AB_SUBSTRATE=1 in env and relaunch the long-lived MCP process to enable"
                },
            }),
        };
        Ok(ToolResult::json_text(&payload))
    }
}

// BioCortex retrieval opt-in surface: shadow digest, replay compare, the opt-in gate/ceremony packet chain, gated trials/diagnostics, relevance-lift eval, runtime readiness/transition gate, and the retrieval shadow report. — extracted to mcp_tools/biocortex_retrieval.rs (2026-07 split step 2).
mod biocortex_retrieval;
pub use biocortex_retrieval::*;
// ===========================================================================
//   introspect_recall — L6 metacognition: novelty / hallucination signal
// ===========================================================================
//
// Maps to `docs/AGENT-BRIDGE-CAPABILITY-ROADMAP-2026-05-15.md` §3 L6 first
// ship. Returns the top-K pure-cosine matches for a query plus, when an
// LLM is configured, a Stage-2 semantic relevance probe ("Option E") that
// produces a continuous `probability_grounded` in [0, 1]. The v0 fields
// (`novelty_score`, `likely_unsupported`) remain in the response for
// backward compatibility; `likely_unsupported` now means
// `probability_grounded < threshold`.
//
// Option E design — `docs/L6-OPTION-E-DESIGN-2026-05-16.md` (commit `d7b112b`).
// Pre-conditions for the reframe are documented at thread 11 posts #160
// (proposal), #170 (sibling buy-in), #178 (owner claim), #180 (design memo).
//
// Implementation is Seed-independent: uses existing ONNX/hash embeddings +
// cosine for Stage 1. Stage 2 is one batched LLM call rating each top-K
// hit {0,1,2} with required verbatim quotes; quote presence is verified
// via substring match against the doc body. Aggregated score is
// `sum(verified_score) / (k * 2)`.

const OPTION_E_DEFAULT_THRESHOLD: f32 = 0.4;
const OPTION_E_DEFAULT_MAX_PER_HOUR: u32 = 30;
const OPTION_E_DEFAULT_MODEL: &str = "claude-haiku-4-5-20251001";
const OPTION_E_MAX_OUTPUT_TOKENS: u32 = 400;
const OPTION_E_DOC_BODY_TRUNCATE: usize = 1200;

#[derive(Debug, Clone)]
pub struct OptionEDocBreakdown {
    pub key: String,
    pub kind: String,
    pub cosine: f32,
    pub score_raw: u8,
    pub quote: Option<String>,
    pub quote_verified: bool,
    pub score_after_verify: u8,
}

#[derive(Debug, Clone)]
pub struct OptionEResult {
    pub probability_grounded: f32,
    pub per_doc: Vec<OptionEDocBreakdown>,
    pub llm_input_tokens: u32,
    pub llm_output_tokens: u32,
    pub llm_latency_ms: u128,
    pub model_used: String,
    pub provider_used: String,
}

#[derive(Debug, serde::Deserialize)]
struct OptionELlmDocsBlob {
    docs: Vec<OptionELlmDocScore>,
}

#[derive(Debug, serde::Deserialize)]
struct OptionELlmDocScore {
    #[allow(dead_code)]
    id: u32,
    score: u8,
    quote: Option<String>,
}

/// Build (system, user) prompts for the Stage-2 relevance probe.
/// Pure — no I/O; testable in isolation.
pub(crate) fn option_e_build_prompt(query: &str, hits: &[MemoryCosineHit]) -> (String, String) {
    let system = "You judge how directly each document addresses a query. \
You do NOT verify facts; you score topical and content relevance only.\n\n\
For each document, output:\n\
- score: 0 (unrelated), 1 (tangential), 2 (directly addresses)\n\
- quote: REQUIRED if score >= 1. Copy a verbatim span from that specific \
document that demonstrates the relevance. The span must be present in the \
document text exactly. If you cannot find a verbatim span that justifies \
score >= 1, set score to 0.\n\n\
Output strict JSON only, no prose: \
{\"docs\": [{\"id\": 1, \"score\": 0|1|2, \"quote\": \"...\"|null}, ...]}"
        .to_string();

    let mut user = format!("Query: {query}\n\nDocuments:\n");
    for (i, h) in hits.iter().enumerate() {
        let key_trunc: String = h.record.key.chars().take(32).collect();
        let body_trunc: String = h
            .record
            .content
            .chars()
            .take(OPTION_E_DOC_BODY_TRUNCATE)
            .collect();
        user.push_str(&format!(
            "\n[{}] (kind={}, key={})\n{}\n",
            i + 1,
            h.record.kind,
            key_trunc,
            body_trunc
        ));
    }
    user.push_str("\nReturn JSON now.");
    (system, user)
}

/// Parse the LLM relevance response. Strips ```json fences. Returns an
/// error if JSON is malformed, count doesn't match, or any score > 2.
/// Pure — testable in isolation.
pub(crate) fn option_e_parse_response(
    text: &str,
    expected_count: usize,
) -> std::result::Result<Vec<(u8, Option<String>)>, String> {
    let cleaned = text.trim();
    let cleaned = cleaned
        .strip_prefix("```json")
        .or_else(|| cleaned.strip_prefix("```"))
        .unwrap_or(cleaned);
    let cleaned = cleaned.strip_suffix("```").unwrap_or(cleaned).trim();

    let blob: OptionELlmDocsBlob =
        serde_json::from_str(cleaned).map_err(|e| format!("parse JSON: {e}"))?;
    if blob.docs.len() != expected_count {
        return Err(format!(
            "expected {expected_count} doc scores, got {}",
            blob.docs.len()
        ));
    }
    for d in &blob.docs {
        if d.score > 2 {
            return Err(format!("doc {} has invalid score {}", d.id, d.score));
        }
    }
    Ok(blob.docs.into_iter().map(|d| (d.score, d.quote)).collect())
}

/// Substring presence check (case-sensitive). Empty quote → not verified.
/// Pure — testable in isolation.
pub(crate) fn option_e_verify_quote(quote: &str, doc_body: &str) -> bool {
    let q = quote.trim();
    if q.is_empty() {
        return false;
    }
    doc_body.contains(q)
}

/// Aggregate `probability_grounded = sum(score_after_verify) / (k * 2)`.
/// Empty input → 0.0. Pure.
pub(crate) fn option_e_aggregate(per_doc: &[OptionEDocBreakdown]) -> f32 {
    if per_doc.is_empty() {
        return 0.0;
    }
    let sum: u32 = per_doc.iter().map(|d| d.score_after_verify as u32).sum();
    let max_possible = (per_doc.len() as u32) * 2;
    if max_possible == 0 {
        return 0.0;
    }
    sum as f32 / max_possible as f32
}

#[derive(Default, Debug)]
struct OptionERateState {
    bucket_start_unix: u64,
    bucket_count: u32,
}

static OPTION_E_RATE_LIMITER: std::sync::OnceLock<std::sync::Mutex<OptionERateState>> =
    std::sync::OnceLock::new();

/// Returns `true` if a call is allowed and the counter has been
/// incremented; `false` if the per-hour ceiling has been hit. Reads the
/// env var on each call so tests can override.
pub(crate) fn option_e_rate_check_and_bump() -> bool {
    let max_per_hour = std::env::var("AB_INTROSPECT_LLM_MAX_PER_HOUR")
        .ok()
        .and_then(|s| s.parse::<u32>().ok())
        .unwrap_or(OPTION_E_DEFAULT_MAX_PER_HOUR);
    let lock =
        OPTION_E_RATE_LIMITER.get_or_init(|| std::sync::Mutex::new(OptionERateState::default()));
    let mut state = lock.lock().expect("rate state mutex poisoned");
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    if now.saturating_sub(state.bucket_start_unix) >= 3600 {
        state.bucket_start_unix = now;
        state.bucket_count = 0;
    }
    if state.bucket_count >= max_per_hour {
        return false;
    }
    state.bucket_count += 1;
    true
}

/// Reset the rate limiter — test-only helper.
#[cfg(test)]
pub(crate) fn option_e_rate_reset() {
    let lock =
        OPTION_E_RATE_LIMITER.get_or_init(|| std::sync::Mutex::new(OptionERateState::default()));
    let mut state = lock.lock().expect("rate state mutex poisoned");
    *state = OptionERateState::default();
}

/// Run the Stage-2 relevance probe against an LLM. Returns
/// `OptionEResult` on success. Caller should treat any error as
/// "degraded — fall back to v0 novelty path".
pub async fn option_e_run(
    query: &str,
    hits: &[MemoryCosineHit],
    llm_client: &crate::llm_client::LlmClient,
) -> Result<OptionEResult> {
    // Model precedence: AB_INTROSPECT_LLM_MODEL (explicit) → provider default
    // from LlmClient (portable across protocols). The hardcoded
    // OPTION_E_DEFAULT_MODEL is documentation only — actual default is
    // whatever LlmClient picks for its primary provider.
    let _ = OPTION_E_DEFAULT_MODEL;
    let model_env = std::env::var("AB_INTROSPECT_LLM_MODEL").ok();
    let model_owned = model_env
        .filter(|s| !s.is_empty())
        .unwrap_or_else(|| llm_client.default_model());
    let model = model_owned.as_str();

    let (system, user) = option_e_build_prompt(query, hits);
    let messages = vec![crate::llm_client::Message {
        role: "user".to_string(),
        content: user,
    }];

    let t0 = std::time::Instant::now();
    let resp = llm_client
        .messages_create(model, Some(&system), &messages, OPTION_E_MAX_OUTPUT_TOKENS)
        .await
        .map_err(|e| ab_core::Error::Backend(format!("option_e LLM call: {e}")))?;
    let latency_ms = t0.elapsed().as_millis();

    let scores = option_e_parse_response(&resp.text, hits.len())
        .map_err(|e| ab_core::Error::Backend(format!("option_e parse: {e}")))?;

    let mut per_doc = Vec::with_capacity(hits.len());
    for (i, h) in hits.iter().enumerate() {
        let (score_raw, quote) = scores[i].clone();
        let (score_after_verify, quote_verified) = if score_raw == 0 {
            (0u8, false)
        } else {
            // claimed score >= 1: requires a verbatim, substring-verified quote
            let has_q = quote
                .as_ref()
                .map(|q| !q.trim().is_empty())
                .unwrap_or(false);
            if has_q && option_e_verify_quote(quote.as_ref().unwrap(), &h.record.content) {
                (score_raw, true)
            } else {
                (1, false) // cap to 1 if quote missing or substring miss
            }
        };
        per_doc.push(OptionEDocBreakdown {
            key: h.record.key.clone(),
            kind: h.record.kind.clone(),
            cosine: h.cosine,
            score_raw,
            quote,
            quote_verified,
            score_after_verify,
        });
    }

    let probability_grounded = option_e_aggregate(&per_doc);
    Ok(OptionEResult {
        probability_grounded,
        per_doc,
        llm_input_tokens: resp.input_tokens,
        llm_output_tokens: resp.output_tokens,
        llm_latency_ms: latency_ms,
        model_used: model.to_string(),
        provider_used: llm_client.provider().to_string(),
    })
}

pub struct IntrospectRecallTool {
    hub: Hub,
}

impl IntrospectRecallTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for IntrospectRecallTool {
    fn name(&self) -> &'static str {
        "introspect_recall"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "L6 metacognition probe — Stage-1 raw cosine recall + novelty score. \
                          **Use this before sediment when you suspect your conclusion may \
                          duplicate or contradict existing memory.** Returns top-K active \
                          memories ranked by pure cosine similarity (no importance/recency \
                          blending) plus `novelty_score = 1 - max(cosine)`. \
                          `likely_unsupported = (novelty_score >= threshold)` (default 0.4) \
                          flags queries whose closest indexed memory is far enough to suggest \
                          the claim is unsupported by current memory. Cheap and deterministic \
                          (no LLM call). Returns `{query, novelty_score, likely_unsupported, \
                          threshold, top_k_count, degraded, hits:[{key, kind, cosine, \
                          content_preview}]}`. Reads only; never writes. \
                          NOTE: A previous LLM-as-relevance Stage-2 layer (\"Option E\") was \
                          FALSIFIED + SHELVED 2026-05-16 (commit `0ced487`) per §6.5 rule 3; \
                          legacy `skip_llm_probe`, `probability_grounded`, `per_doc`, `llm` \
                          fields and the `AB_INTROSPECT_LLM_MAX_PER_HOUR` env are dead-code \
                          flags kept for API back-compat — do not rely on them. \
                          See docs/L6-OPTION-E-DESIGN-2026-05-16.md (history)."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "query": {
                        "type": "string",
                        "description": "Natural-language question or claim to probe. Required, non-empty."
                    },
                    "k": {
                        "type": "integer",
                        "default": 5,
                        "minimum": 1,
                        "maximum": 50,
                        "description": "Top-K cosine matches to inspect. Default 5."
                    },
                    "threshold": {
                        "type": "number",
                        "default": 0.4,
                        "minimum": 0.0,
                        "maximum": 1.0,
                        "description": "Novelty cutoff. likely_unsupported = (novelty_score >= threshold). Lower threshold (e.g. 0.3) → more sensitive flagging; higher (e.g. 0.6) → only flags truly novel claims. Default 0.4 is calibrated for typical aio2 memory density."
                    },
                    "content_preview_chars": {
                        "type": "integer",
                        "default": 160,
                        "minimum": 0,
                        "maximum": 2000,
                        "description": "Per-hit content preview length. 0 disables the preview field."
                    },
                    "skip_llm_probe": {
                        "type": "boolean",
                        "default": false,
                        "description": "DEPRECATED — no-op since Option E shelved 2026-05-16 (commit `0ced487`). Stage-1 cosine is now the only path; this flag is kept for API back-compat. Safe to omit."
                    }
                },
                "required": ["query"]
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let query = match args.get("query").and_then(|v| v.as_str()) {
            Some(s) if !s.trim().is_empty() => s.trim().to_string(),
            _ => return Ok(ToolResult::error("missing or empty 'query'")),
        };
        let k = args
            .get("k")
            .and_then(|v| v.as_u64())
            .unwrap_or(5)
            .clamp(1, 50) as u32;
        // Default threshold flipped from v0 (0.7 novelty cutoff) to 0.4
        // (Option E grounding cutoff). Caller can pass explicit value.
        let threshold = args
            .get("threshold")
            .and_then(|v| v.as_f64())
            .unwrap_or(OPTION_E_DEFAULT_THRESHOLD as f64)
            .clamp(0.0, 1.0) as f32;
        let preview_chars = args
            .get("content_preview_chars")
            .and_then(|v| v.as_u64())
            .unwrap_or(160)
            .min(2000) as usize;
        let skip_llm_probe = args
            .get("skip_llm_probe")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);

        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no memory store configured")),
        };

        let hits = store
            .memory_top_k_cosine(&query, k)
            .await
            .map_err(|e| ab_core::Error::Backend(format!("introspect_recall: {e}")))?;

        let max_cosine = hits
            .iter()
            .map(|h| h.cosine)
            .fold(f32::NEG_INFINITY, f32::max);
        // Treat "no hits at all" (empty store / no embeddings) as max-novelty.
        let novelty_score = if hits.is_empty() {
            1.0_f32
        } else {
            (1.0 - max_cosine).clamp(0.0, 1.0)
        };

        // Stage-2 Option E LLM relevance probe was FALSIFIED + SHELVED
        // 2026-05-16 (commit 0ced487, §6.5 rule 3). Stage-1 cosine novelty is
        // the only path. We intentionally do NOT invoke the LLM probe: leaving
        // it wired reintroduced a live degradation — `LlmClient::from_env()`
        // routed the introspect model id to an OpenAI-compatible endpoint that
        // rejected it (HTTP 400 "Invalid model id"), so every call returned
        // `degraded: true`. `skip_llm_probe` is accepted for API back-compat
        // but is a no-op (it never gated a real LLM call after this change).
        let option_e_result: Option<OptionEResult> = None;
        let _ = skip_llm_probe; // accepted for back-compat; never runs an LLM probe
                                // `no_hits` (empty store / no embeddings) is the only honest degradation
                                // signal left: novelty is forced to the 1.0 ceiling, so flag it so
                                // callers don't read max-novelty as a confident "unsupported" verdict.
        let degraded = hits.is_empty();
        let degraded_reason: Option<String> = if hits.is_empty() {
            Some("no_hits".to_string())
        } else {
            None
        };

        // Compose `likely_unsupported` from whichever signal is available.
        let (probability_grounded_v, likely_unsupported) = match &option_e_result {
            Some(r) => (
                Some(r.probability_grounded),
                r.probability_grounded < threshold,
            ),
            None => (
                None,
                // v0 fallback semantics: caller may have passed a v0-style
                // novelty threshold (0.7); treat threshold-as-novelty here.
                // For default 0.4, that fires more often → degraded callers
                // are urged to set explicit threshold for v0 semantics.
                novelty_score >= threshold,
            ),
        };

        let hits_json: Vec<Value> = hits
            .iter()
            .map(|h| {
                let preview = if preview_chars == 0 {
                    Value::Null
                } else {
                    let s: String = h.record.content.chars().take(preview_chars).collect();
                    Value::String(s)
                };
                json!({
                    "key": h.record.key,
                    "kind": h.record.kind,
                    "cosine": h.cosine,
                    "content_preview": preview,
                })
            })
            .collect();

        let mut out = json!({
            "query": query,
            "novelty_score": novelty_score,
            "likely_unsupported": likely_unsupported,
            "threshold": threshold,
            "top_k_count": hits.len(),
            "degraded": degraded,
            "hits": hits_json,
        });
        if let Some(prob) = probability_grounded_v {
            out["probability_grounded"] = json!(prob);
        }
        if let Some(reason) = degraded_reason {
            out["degraded_reason"] = json!(reason);
        }
        if let Some(r) = &option_e_result {
            let per_doc: Vec<Value> = r
                .per_doc
                .iter()
                .map(|d| {
                    json!({
                        "key": d.key,
                        "kind": d.kind,
                        "cosine": d.cosine,
                        "score": d.score_raw,
                        "quote": d.quote,
                        "quote_verified": d.quote_verified,
                        "score_after_verify": d.score_after_verify,
                    })
                })
                .collect();
            out["per_doc"] = json!(per_doc);
            out["llm"] = json!({
                "model": r.model_used,
                "provider": r.provider_used,
                "input_tokens": r.llm_input_tokens,
                "output_tokens": r.llm_output_tokens,
                "latency_ms": r.llm_latency_ms,
            });
        }

        Ok(ToolResult::json_text(&out))
    }
}

// ===========================================================================
//             memory_link_audit — Phase 0 dead-link probe over bodies
// ===========================================================================

/// Scan a memory body for path-like tokens. We look for tokens that begin
/// with one of the known prefixes (absolute roots and project-relative dirs)
/// and run through path-legal characters until a whitespace/punctuation
/// terminator. This is intentionally conservative: false negatives (a missed
/// reference) are safer than false positives (flagging real prose as a path).
fn scan_memory_paths(content: &str) -> Vec<String> {
    const PREFIXES: &[&str] = &[
        // Absolute roots that show up in our memories
        "/Data/",
        "/home/",
        "/tmp/",
        "/var/",
        "/opt/",
        "/etc/",
        "/run/",
        "/usr/",
        // Repo-relative dirs we frequently reference in memory bodies
        "crates/",
        "museum/",
        "docs/",
        "scripts/",
        "tests/",
        "examples/",
        "assets/",
        ".claude/",
        "target/",
        "warp-adapter/",
        "workflows/",
    ];
    let mut out: Vec<String> = Vec::new();
    let bytes = content.as_bytes();
    for prefix in PREFIXES {
        let mut start = 0usize;
        while let Some(pos) = content[start..].find(prefix) {
            let abs = start + pos;
            let mut end = abs + prefix.len();
            while end < bytes.len() {
                let b = bytes[end];
                let path_char =
                    b.is_ascii_alphanumeric() || b == b'_' || b == b'-' || b == b'.' || b == b'/';
                if path_char {
                    end += 1;
                } else {
                    break;
                }
            }
            // Trim trailing punctuation that isn't part of a real path.
            let candidate = &content[abs..end];
            let trimmed =
                candidate.trim_end_matches(|c: char| c == '.' || c == ',' || c == '/' || c == '-');
            if trimmed.len() > prefix.len() {
                out.push(trimmed.to_string());
            }
            start = end.max(abs + 1);
        }
    }
    out.sort();
    out.dedup();
    out
}

/// Resolve a candidate path: absolute → use as-is; relative → join with repo_root.
/// Single-root variant kept for tests + simple callers.
fn resolve_audit_path(candidate: &str, repo_root: &std::path::Path) -> std::path::PathBuf {
    if candidate.starts_with('/') {
        std::path::PathBuf::from(candidate)
    } else {
        repo_root.join(candidate)
    }
}

/// Multi-root existence probe. Absolute paths are checked once; relative
/// paths are tried against each root in order. Returns true on the first
/// hit. Used by the audit to handle `~/.claude/projects/...` references
/// that don't live under the agent-bridge repo.
fn path_exists_in_any_root(candidate: &str, roots: &[std::path::PathBuf]) -> bool {
    if candidate.starts_with('/') {
        return std::path::Path::new(candidate).exists();
    }
    roots.iter().any(|r| r.join(candidate).exists())
}

pub struct MemoryLinkAuditTool {
    hub: Hub,
}
impl MemoryLinkAuditTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for MemoryLinkAuditTool {
    fn name(&self) -> &'static str {
        "memory_link_audit"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Phase 0 dead-link probe. Scan memory bodies for path-like tokens \
                 (absolute paths and known repo-relative prefixes: crates/, museum/, docs/, \
                 scripts/, tests/, .claude/, etc.), check filesystem existence across one or \
                 more search roots, and report dead references. Surfaces stale memories whose \
                 code/file pointers no longer resolve — the input to per-memory STATUS banner \
                 work. Does NOT modify any memory; this is read-only diagnostics. \
                 Defaults exclude `kind=skill` records because skill manifests reference \
                 paths inside their own bundle, not the repo (overwhelms signal otherwise)."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "kind":       { "type": "string", "description": "Optional memory kind filter (e.g. 'lesson', 'todo'). When set, the include_skills default is overridden." },
                    "limit":      { "type": "integer", "minimum": 1, "maximum": 1000, "default": 200 },
                    "repo_root":  { "type": "string", "description": "Primary base for resolving relative paths. Default: current working dir." },
                    "extra_search_roots": {
                        "type": "array", "items": { "type": "string" }, "default": [],
                        "description": "Additional roots to try for relative paths (any-match wins). Useful for memory bodies that reference ~/.claude/projects/... or other out-of-repo locations."
                    },
                    "include_skills": {
                        "type": "boolean", "default": false,
                        "description": "Include kind=skill records (off by default; skills reference intra-bundle paths the repo audit can't resolve)."
                    },
                    "include_alive": { "type": "boolean", "default": false, "description": "If true, also include memories whose links all resolve (for coverage view)." }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };

        let kind = args
            .get("kind")
            .and_then(|v| v.as_str())
            .map(str::to_string);
        let limit = args
            .get("limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(200)
            .clamp(1, 1000) as u32;
        let repo_root_arg = args.get("repo_root").and_then(|v| v.as_str());
        let repo_root: std::path::PathBuf = match repo_root_arg {
            Some(s) => std::path::PathBuf::from(s),
            None => std::env::current_dir().unwrap_or_else(|_| std::path::PathBuf::from(".")),
        };
        let mut roots: Vec<std::path::PathBuf> = vec![repo_root.clone()];
        if let Some(extras) = args.get("extra_search_roots").and_then(|v| v.as_array()) {
            for v in extras {
                if let Some(s) = v.as_str() {
                    roots.push(std::path::PathBuf::from(s));
                }
            }
        }
        // Default-exclude skills unless the caller flips it explicitly OR
        // explicitly asks for kind=skill (their intent is then to audit skills).
        let include_skills = args
            .get("include_skills")
            .and_then(|v| v.as_bool())
            .unwrap_or(false)
            || kind.as_deref() == Some("skill");
        let include_alive = args
            .get("include_alive")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);

        let raw_memories = store
            .list_memories(kind.as_deref(), MemoryListSort::Newest, limit)
            .await?;
        let memories: Vec<_> = if include_skills {
            raw_memories
        } else {
            raw_memories
                .into_iter()
                .filter(|m| m.kind != "skill")
                .collect()
        };

        let mut audited = 0u64;
        let mut skipped_skills = 0u64;
        let mut with_links = 0u64;
        let mut dead_total = 0u64;
        let mut alive_total = 0u64;
        let mut per_memory: Vec<Value> = Vec::new();

        for rec in &memories {
            audited += 1;
            let candidates = scan_memory_paths(&rec.content);
            if candidates.is_empty() {
                continue;
            }
            with_links += 1;

            let mut dead: Vec<String> = Vec::new();
            let mut alive: Vec<String> = Vec::new();
            for cand in &candidates {
                if path_exists_in_any_root(cand, &roots) {
                    alive.push(cand.clone());
                } else {
                    dead.push(cand.clone());
                }
            }
            dead_total += dead.len() as u64;
            alive_total += alive.len() as u64;

            if !dead.is_empty() || include_alive {
                let mut row = json!({
                    "key": rec.key,
                    "kind": rec.kind,
                    "dead": dead,
                });
                if include_alive {
                    if let Some(obj) = row.as_object_mut() {
                        obj.insert("alive".to_string(), json!(alive));
                    }
                }
                per_memory.push(row);
            }
        }
        if !include_skills {
            // Estimate how many skill rows we suppressed for the user's coverage view.
            // (Cheap: just re-count from a kind="skill" pull capped to the same limit.)
            if let Ok(skill_only) = store
                .list_memories(Some("skill"), MemoryListSort::Newest, limit)
                .await
            {
                skipped_skills = skill_only.len() as u64;
            }
        }

        let roots_display: Vec<String> = roots.iter().map(|p| p.display().to_string()).collect();

        Ok(ToolResult::json_text(&json!({
            "audited": audited,
            "skipped_skill_rows": skipped_skills,
            "with_links": with_links,
            "dead_total": dead_total,
            "alive_total": alive_total,
            "per_memory": per_memory,
            "search_roots": roots_display,
            "kind_filter": kind,
            "include_skills": include_skills,
            "note": "Dead links don't auto-trigger banner edits — review and apply via memory_save \
                with a STATUS prefix. Pattern: see project_warp_drop_to_museum.md. \
                Pass `include_skills=true` to also audit skill records (their paths are usually \
                intra-bundle and produce false positives without that intent).",
        })))
    }
}

// ===========================================================================
//                             memory_suggest
// ===========================================================================

pub struct MemorySuggestTool {
    hub: Hub,
}
impl MemorySuggestTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for MemorySuggestTool {
    fn name(&self) -> &'static str {
        "memory_suggest"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Suggest related memory keys for a given key, based on tag overlap, \
                 key-prefix similarity, and content token overlap. \
                 Returns ranked candidates with reason + confidence. \
                 Use the suggestions to decide which memory_link calls to make."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "key": { "type": "string", "description": "The memory key to find suggestions for." },
                    "limit": { "type": "integer", "minimum": 1, "maximum": 20, "default": 8 }
                },
                "required": ["key"]
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let key = match args.get("key").and_then(|v| v.as_str()) {
            Some(s) if !s.is_empty() => s.to_string(),
            _ => return Ok(ToolResult::error("missing 'key'")),
        };
        let limit = args
            .get("limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(8)
            .min(20) as u32;

        // Fetch the source memory
        let source = match store.memory_get(&key).await? {
            Some(m) => m,
            None => return Ok(ToolResult::error(format!("key not found: '{key}'"))),
        };

        // Already-linked neighbors (to exclude from suggestions)
        let existing_edges = store.memory_neighbors(&key).await.unwrap_or_default();
        let already_linked: std::collections::HashSet<String> = existing_edges
            .iter()
            .map(|e| {
                if e.from_key == key {
                    e.to_key.clone()
                } else {
                    e.from_key.clone()
                }
            })
            .collect();

        // List all memories (up to 500 for scoring)
        let all = store
            .list_memories(None, MemoryListSort::Recent, 500)
            .await
            .unwrap_or_default();

        // ζ-7: scoring extracted into `compute_link_suggestions` helper so
        // batch tools (memory_link_orphans) can reuse it without N store
        // round-trips. JSON shape preserved by rebuilding from the helper's
        // (key, conf, reason) tuples + a snippet lookup against `all`.
        let by_key: std::collections::HashMap<&str, &MemoryRecord> =
            all.iter().map(|m| (m.key.as_str(), m)).collect();
        let suggestions =
            compute_link_suggestions(&source, &all, &already_linked, limit as usize, &[]);
        let candidates: Vec<Value> = suggestions
            .into_iter()
            .map(|(k, conf, reason)| {
                let kind = by_key
                    .get(k.as_str())
                    .map(|m| m.kind.clone())
                    .unwrap_or_default();
                let snippet = by_key
                    .get(k.as_str())
                    .map(|m| m.content.chars().take(80).collect::<String>())
                    .unwrap_or_default();
                json!({
                    "key": k,
                    "kind": kind,
                    "confidence": conf,
                    "reason": reason,
                    "snippet": snippet,
                })
            })
            .collect();

        Ok(ToolResult::json_text(&json!({
            "source_key": key,
            "suggestions": candidates,
            "already_linked": already_linked.into_iter().collect::<Vec<_>>()
        })))
    }
}

fn key_prefix(key: &str) -> &str {
    key.split(&['_', '-', '/', '.'][..]).next().unwrap_or("")
}

fn content_tokens(content: &str) -> std::collections::HashSet<String> {
    content
        .split_whitespace()
        .filter(|t| t.len() >= 4)
        .map(|t| t.to_lowercase())
        .collect()
}

/// ζ-7 (2026-05-11) — Suggestion-scoring core extracted from
/// `MemorySuggestTool`. Returns `(key, confidence, reason)` triples ranked
/// by confidence DESC. Same heuristic stack the MCP tool uses: tag
/// overlap (×0.4) + same-prefix (+0.3) + content-token Jaccard.
///
/// Caller supplies `source` + `candidates` + `already_linked` so this
/// function does ZERO store I/O — it can be called in a tight loop (e.g.
/// `memory_link_orphans` iterating over hundreds of orphans).
///
/// ζ-11 (2026-05-12) — added `skip_target_tags`: any candidate whose tag
/// set intersects `skip_target_tags` is dropped before scoring. This is
/// how `memory_link_orphans` excludes `auto_curated` stubs from becoming
/// link targets — the ζ-9 snapshot revealed that all 82 `curated_implicit_*`
/// stubs collapsed onto the lex-earliest sibling (degree=84 noise hub)
/// because tag+prefix overlap evaluated to a ~tie. Pass `&[]` to disable.
pub fn compute_link_suggestions(
    source: &MemoryRecord,
    candidates: &[MemoryRecord],
    already_linked: &std::collections::HashSet<String>,
    limit: usize,
    skip_target_tags: &[String],
) -> Vec<(String, f64, String)> {
    let source_prefix = key_prefix(&source.key);
    let source_tokens = content_tokens(&source.content);
    let mut scored: Vec<(String, f64, String)> = candidates
        .iter()
        .filter(|m| m.key != source.key && !already_linked.contains(&m.key))
        .filter(|m| {
            if skip_target_tags.is_empty() {
                return true;
            }
            !m.tags.iter().any(|t| skip_target_tags.contains(t))
        })
        .filter_map(|m| {
            let mut score = 0.0f64;
            let mut reasons: Vec<&str> = Vec::new();
            let tag_overlap = source.tags.iter().filter(|t| m.tags.contains(t)).count();
            if tag_overlap > 0 {
                score += 0.4 * tag_overlap as f64;
                reasons.push("tag_overlap");
            }
            let m_prefix = key_prefix(&m.key);
            if !source_prefix.is_empty() && source_prefix == m_prefix {
                score += 0.3;
                reasons.push("same_prefix");
            }
            let m_tokens = content_tokens(&m.content);
            let intersection = source_tokens
                .iter()
                .filter(|t| m_tokens.contains(*t))
                .count();
            let union = source_tokens.len() + m_tokens.len() - intersection;
            if union > 0 && intersection > 2 {
                let jaccard = intersection as f64 / union as f64;
                score += jaccard;
                reasons.push("content_overlap");
            }
            if score < 0.1 {
                return None;
            }
            let conf = (score * 100.0).min(100.0).round() / 100.0;
            Some((m.key.clone(), conf, reasons.join("+")))
        })
        .collect();
    scored.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
    scored.truncate(limit);
    scored
}

fn memory_string_array_arg(args: &Value, key: &str, default: &[&str]) -> Vec<String> {
    args.get(key)
        .and_then(|v| v.as_array())
        .map(|arr| {
            arr.iter()
                .filter_map(|v| v.as_str().map(|s| s.trim().to_string()))
                .filter(|s| !s.is_empty())
                .collect()
        })
        .unwrap_or_else(|| default.iter().map(|s| (*s).to_string()).collect())
}

fn memory_has_any_tag(rec: &MemoryRecord, tags: &[String]) -> bool {
    rec.tags
        .iter()
        .any(|tag| tags.iter().any(|skip| tag.eq_ignore_ascii_case(skip)))
}

fn memory_kind_is_any(rec: &MemoryRecord, kinds: &[String]) -> bool {
    kinds.iter().any(|kind| rec.kind.eq_ignore_ascii_case(kind))
}

fn memory_scope_value(rec: &MemoryRecord) -> Option<&str> {
    rec.scope
        .as_deref()
        .map(str::trim)
        .filter(|scope| !scope.is_empty())
}

const PROJECT_SCOPE_ALIASES_ENV: &str = "AGENT_BRIDGE_PROJECT_SCOPE_ALIASES";

fn project_scopes_read_time_compatible(a: &str, b: &str) -> bool {
    let aliases = std::env::var(PROJECT_SCOPE_ALIASES_ENV).ok();
    project_scopes_read_time_compatible_with_aliases(a, b, aliases.as_deref())
}

fn project_scopes_read_time_compatible_with_aliases(
    a: &str,
    b: &str,
    project_scope_aliases: Option<&str>,
) -> bool {
    let a = a.trim();
    let b = b.trim();
    !a.is_empty()
        && !b.is_empty()
        && (a == b
            || project_scope_paths_overlap(a, b)
            || crate::project_identity::project_scopes_canonical_match(a, b)
            || project_scope_aliases
                .map(str::trim)
                .filter(|aliases| !aliases.is_empty())
                .is_some_and(|aliases| {
                    crate::project_identity::project_scopes_alias_by_registry(a, b, aliases)
                }))
}

fn project_scope_paths_overlap(a: &str, b: &str) -> bool {
    let (Some(a), Some(b)) = (a.strip_prefix("project:"), b.strip_prefix("project:")) else {
        return false;
    };
    let a = a.trim_end_matches('/');
    let b = b.trim_end_matches('/');
    a == b
        || b.strip_prefix(a).is_some_and(|rest| rest.starts_with('/'))
        || a.strip_prefix(b).is_some_and(|rest| rest.starts_with('/'))
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum MemorySearchScopeMode {
    LocalOnly,
    LocalPlusGlobal,
    Exploratory,
}

impl MemorySearchScopeMode {
    fn parse(raw: Option<&str>, include_global: bool) -> Self {
        match raw {
            Some("local_plus_global") => Self::LocalPlusGlobal,
            Some("exploratory") => Self::Exploratory,
            Some("local_only") => Self::LocalOnly,
            // Backward compatibility for callers that adopted the first
            // scope-filter cut before scope_mode existed.
            None if include_global => Self::LocalPlusGlobal,
            _ => Self::LocalOnly,
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::LocalOnly => "local_only",
            Self::LocalPlusGlobal => "local_plus_global",
            Self::Exploratory => "exploratory",
        }
    }
}

fn memory_search_scope_mode(args: &Value, include_global: bool) -> MemorySearchScopeMode {
    MemorySearchScopeMode::parse(
        args.get("scope_mode")
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty()),
        include_global,
    )
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum MemorySearchScopeRelation {
    Local,
    Global,
    CrossScope,
}

fn memory_search_scope_relation(
    rec: &MemoryRecord,
    requested_scope: &str,
) -> MemorySearchScopeRelation {
    let aliases = std::env::var(PROJECT_SCOPE_ALIASES_ENV).ok();
    memory_search_scope_relation_with_aliases(rec, requested_scope, aliases.as_deref())
}

fn memory_search_scope_relation_with_aliases(
    rec: &MemoryRecord,
    requested_scope: &str,
    project_scope_aliases: Option<&str>,
) -> MemorySearchScopeRelation {
    let requested_scope = requested_scope.trim();
    match memory_scope_value(rec) {
        Some(scope)
            if !requested_scope.is_empty()
                && project_scopes_read_time_compatible_with_aliases(
                    scope,
                    requested_scope,
                    project_scope_aliases,
                ) =>
        {
            MemorySearchScopeRelation::Local
        }
        Some("global") | None => MemorySearchScopeRelation::Global,
        _ => MemorySearchScopeRelation::CrossScope,
    }
}

fn memory_search_scope_mode_matches(
    rec: &MemoryRecord,
    requested_scope: &str,
    mode: MemorySearchScopeMode,
) -> bool {
    match (mode, memory_search_scope_relation(rec, requested_scope)) {
        (MemorySearchScopeMode::LocalOnly, MemorySearchScopeRelation::Local) => true,
        (MemorySearchScopeMode::LocalPlusGlobal, MemorySearchScopeRelation::Local)
        | (MemorySearchScopeMode::LocalPlusGlobal, MemorySearchScopeRelation::Global) => true,
        (MemorySearchScopeMode::Exploratory, _) => true,
        _ => false,
    }
}

fn memory_search_scope_score_multiplier(
    rec: &MemoryRecord,
    requested_scope: &str,
    mode: MemorySearchScopeMode,
) -> f64 {
    match (mode, memory_search_scope_relation(rec, requested_scope)) {
        (_, MemorySearchScopeRelation::Local) => 1.0,
        (MemorySearchScopeMode::LocalPlusGlobal, MemorySearchScopeRelation::Global)
        | (MemorySearchScopeMode::Exploratory, MemorySearchScopeRelation::Global) => 0.85,
        (MemorySearchScopeMode::Exploratory, MemorySearchScopeRelation::CrossScope) => 0.65,
        _ => 1.0,
    }
}

fn memory_search_apply_scope_mode(
    hits: Vec<MemorySearchHit>,
    requested_scope: &str,
    mode: MemorySearchScopeMode,
) -> Vec<MemorySearchHit> {
    let mut scoped: Vec<MemorySearchHit> = hits
        .into_iter()
        .filter_map(|mut hit| {
            if !memory_search_scope_mode_matches(&hit.record, requested_scope, mode) {
                return None;
            }
            hit.score *= memory_search_scope_score_multiplier(&hit.record, requested_scope, mode);
            Some(hit)
        })
        .collect();
    scoped.sort_by(|a, b| {
        b.score
            .partial_cmp(&a.score)
            .unwrap_or(std::cmp::Ordering::Equal)
    });
    scoped
}

/// Apply scope-mode filtering with a recall-recovery fallback for *bare-default*
/// scoped searches (mirrors the FTS AND→OR fallback in the store layer).
///
/// A scoped search under the requested mode is tried first. The fallback widens
/// the scope (local_only → local_plus_global → exploratory) only when ALL of:
///   • the first pass returned nothing, AND
///   • the caller expressed no widening preference at all — no `scope_mode`, no
///     `include_global` (so the effective `mode` is the bare default local_only).
/// This surfaces global / cross-project knowledge for a scoped query that would
/// otherwise return empty, while:
///   • leaving scoped queries that already matched locally completely untouched
///     (precise default preserved — the fallback fires only on total emptiness);
///   • honoring an *expressed* preference as a ceiling — explicit local_only stays
///     strict, and include_global / explicit local_plus_global never widens into
///     cross-project rows the caller did not ask for;
///   • performing no extra SQL — the caller's `hits` were overfetched and already
///     contain the wider rows, so each stage only re-filters the in-memory set.
fn memory_search_apply_scope_mode_with_fallback(
    hits: Vec<MemorySearchHit>,
    requested_scope: &str,
    mode: MemorySearchScopeMode,
    scope_mode_explicit: bool,
) -> Vec<MemorySearchHit> {
    let prefilter = hits;
    let scoped = memory_search_apply_scope_mode(prefilter.clone(), requested_scope, mode);
    if !scoped.is_empty() || scope_mode_explicit || mode != MemorySearchScopeMode::LocalOnly {
        return scoped;
    }
    // Reaching here, `mode` is provably the bare default local_only; widen.
    for wider in [
        MemorySearchScopeMode::LocalPlusGlobal,
        MemorySearchScopeMode::Exploratory,
    ] {
        let widened = memory_search_apply_scope_mode(prefilter.clone(), requested_scope, wider);
        if !widened.is_empty() {
            return widened;
        }
    }
    scoped
}

fn memory_search_scope_trace_allowed(
    rec: &MemoryRecord,
    requested_scope: &str,
    mode: MemorySearchScopeMode,
) -> bool {
    match (mode, memory_search_scope_relation(rec, requested_scope)) {
        (_, MemorySearchScopeRelation::Local) => true,
        (MemorySearchScopeMode::LocalPlusGlobal, MemorySearchScopeRelation::Global) => true,
        // Exploratory cross-scope hits are read-time analogies. Do not
        // crystallize them into coactivation until a later explicit-feedback
        // path can distinguish useful transfer from noisy coincidence.
        _ => false,
    }
}

fn memory_graph_topology_record_visible(
    rec: &MemoryRecord,
    requested_scope: Option<&str>,
    scope_mode: MemorySearchScopeMode,
    skip_tags: &[String],
    skip_kinds: &[String],
) -> bool {
    // Coverage-denominator exclusion, symmetric with the SQL path
    // (store::graph_topology / M5). Edge-less-by-design cohorts (`skill`,
    // `present_outcome`) are excluded so they don't deflate orphan/coverage
    // fractions into a measurement artifact (thread 6 #1983 ruling 2026-06-04).
    if rec.status != "active"
        || ab_store::COVERAGE_EXCLUDED_KINDS
            .iter()
            .any(|k| rec.kind.eq_ignore_ascii_case(k))
    {
        return false;
    }
    if memory_has_any_tag(rec, skip_tags) || memory_kind_is_any(rec, skip_kinds) {
        return false;
    }
    match requested_scope {
        Some(scope) => memory_search_scope_mode_matches(rec, scope, scope_mode),
        None => true,
    }
}

fn memory_graph_topology_from_records(
    records: &[MemoryRecord],
    edges_by_key: &HashMap<String, Vec<MemoryEdge>>,
) -> GraphTopology {
    let visible_keys: HashSet<String> = records.iter().map(|rec| rec.key.clone()).collect();
    let mut degrees: HashMap<String, u64> = visible_keys
        .iter()
        .map(|key| (key.clone(), 0_u64))
        .collect();
    let mut evolved_keys: HashSet<String> = HashSet::new();

    for key in &visible_keys {
        let Some(edges) = edges_by_key.get(key) else {
            continue;
        };
        for edge in edges {
            let other = if edge.from_key == *key {
                &edge.to_key
            } else if edge.to_key == *key {
                &edge.from_key
            } else {
                continue;
            };
            if !visible_keys.contains(other) {
                continue;
            }
            if let Some(degree) = degrees.get_mut(key) {
                *degree += 1;
            }
            if edge.edge_type == "evolved" {
                evolved_keys.insert(key.clone());
            }
        }
    }

    let canonical = ["0", "1", "2-3", "4-5", "6-10", "11-20", "21+"];
    let mut bucket_counts: HashMap<String, u64> = canonical
        .iter()
        .map(|bucket| ((*bucket).to_string(), 0_u64))
        .collect();
    for degree in degrees.values() {
        let bucket = match *degree {
            0 => "0",
            1 => "1",
            2 | 3 => "2-3",
            4 | 5 => "4-5",
            6..=10 => "6-10",
            11..=20 => "11-20",
            _ => "21+",
        };
        *bucket_counts.entry(bucket.to_string()).or_default() += 1;
    }
    let degree_histogram = canonical
        .iter()
        .map(|bucket| {
            (
                (*bucket).to_string(),
                bucket_counts.get(*bucket).copied().unwrap_or(0),
            )
        })
        .collect();

    let mut hubs: Vec<(String, u64)> = degrees
        .into_iter()
        .filter(|(_, degree)| *degree > 0)
        .collect();
    hubs.sort_by(|(key_a, degree_a), (key_b, degree_b)| {
        degree_b.cmp(degree_a).then_with(|| key_a.cmp(key_b))
    });
    hubs.truncate(5);

    GraphTopology {
        non_skill_active_total: visible_keys.len() as u64,
        orphan_count: visible_keys
            .iter()
            .filter(|key| {
                edges_by_key
                    .get(*key)
                    .map(|edges| {
                        !edges.iter().any(|edge| {
                            let other = if edge.from_key == **key {
                                &edge.to_key
                            } else if edge.to_key == **key {
                                &edge.from_key
                            } else {
                                return false;
                            };
                            visible_keys.contains(other)
                        })
                    })
                    .unwrap_or(true)
            })
            .count() as u64,
        degree_histogram,
        top_5_hubs: hubs,
        p4_evolved_coverage: evolved_keys.len() as u64,
    }
}

fn memory_scopes_compatible(source: &MemoryRecord, target: &MemoryRecord, required: bool) -> bool {
    if !required {
        return true;
    }
    match (memory_scope_value(source), memory_scope_value(target)) {
        (Some(a), Some(b)) => {
            a == "global" || b == "global" || project_scopes_read_time_compatible(a, b)
        }
        _ => true,
    }
}

fn memory_link_orphan_candidate_allowed(
    source: &MemoryRecord,
    target: &MemoryRecord,
    skip_tags: &[String],
    skip_kinds: &[String],
    require_scope_compatible: bool,
) -> bool {
    source.key != target.key
        && !memory_has_any_tag(target, skip_tags)
        && !memory_kind_is_any(target, skip_kinds)
        && memory_scopes_compatible(source, target, require_scope_compatible)
}

fn undirected_memory_pair_key(a: &str, b: &str) -> (String, String) {
    if a <= b {
        (a.to_string(), b.to_string())
    } else {
        (b.to_string(), a.to_string())
    }
}

#[derive(Debug)]
struct MemoryOrphanCandidatePreviewRow {
    orphan: MemoryRecord,
    suggestions: Vec<(String, f64, String)>,
}

#[derive(Debug, Default)]
struct MemoryOrphanCandidatePreview {
    examined: u64,
    eligible_orphans: u64,
    would_link: u64,
    skipped_low_score: u64,
    skipped_no_candidates: u64,
    skipped_blacklisted_orphan: u64,
    skipped_blacklisted_kind: u64,
    rows: Vec<MemoryOrphanCandidatePreviewRow>,
}

#[derive(Debug)]
struct MemoryOrphanInventoryRow {
    record: MemoryRecord,
    created_age_days: i64,
    updated_age_days: i64,
    content_preview: String,
    content_truncated: bool,
    content_total_chars: usize,
}

#[derive(Debug, Default)]
struct MemoryOrphanInventory {
    examined: u64,
    orphan_total: u64,
    eligible_orphans: u64,
    skipped_blacklisted_orphan: u64,
    skipped_blacklisted_kind: u64,
    by_kind: Vec<(String, u64)>,
    top_tags: Vec<(String, u64)>,
    rows: Vec<MemoryOrphanInventoryRow>,
}

fn memory_age_days(now_secs: i64, ts: i64) -> i64 {
    if ts <= 0 || now_secs <= ts {
        0
    } else {
        (now_secs - ts) / 86_400
    }
}

fn memory_orphan_inventory_record_in_scope(
    rec: &MemoryRecord,
    min_content_len: usize,
    requested_scope: Option<&str>,
    scope_mode: MemorySearchScopeMode,
) -> bool {
    if rec.kind.eq_ignore_ascii_case("skill") {
        return false;
    }
    if rec.status != "active" && !rec.status.is_empty() {
        return false;
    }
    if rec.content.len() < min_content_len {
        return false;
    }
    if let Some(scope) = requested_scope {
        if !memory_search_scope_mode_matches(rec, scope, scope_mode) {
            return false;
        }
    }
    true
}

fn memory_orphan_inventory_record_eligible(
    rec: &MemoryRecord,
    min_content_len: usize,
    skip_tags: &[String],
    skip_kinds: &[String],
    requested_scope: Option<&str>,
    scope_mode: MemorySearchScopeMode,
) -> bool {
    memory_orphan_inventory_record_in_scope(rec, min_content_len, requested_scope, scope_mode)
        && !memory_has_any_tag(rec, skip_tags)
        && !memory_kind_is_any(rec, skip_kinds)
}

fn memory_record_has_induced_edge(
    key: &str,
    edges: &[MemoryEdge],
    visible_keys: &HashSet<String>,
) -> bool {
    edges.iter().any(|edge| {
        let other = if edge.from_key == key {
            &edge.to_key
        } else if edge.to_key == key {
            &edge.from_key
        } else {
            return false;
        };
        visible_keys.contains(other)
    })
}

#[allow(clippy::too_many_arguments)]
fn collect_memory_orphan_inventory(
    all: &[MemoryRecord],
    keys_with_edges: &HashSet<String>,
    min_content_len: usize,
    max_rows: usize,
    preview_chars: usize,
    sort: &str,
    skip_tags: &[String],
    skip_kinds: &[String],
    requested_scope: Option<&str>,
    scope_mode: MemorySearchScopeMode,
    now_secs: i64,
) -> MemoryOrphanInventory {
    let mut inventory = MemoryOrphanInventory::default();
    let mut rows = Vec::new();
    let mut kind_counts: HashMap<String, u64> = HashMap::new();
    let mut tag_counts: HashMap<String, u64> = HashMap::new();

    for rec in all {
        if !memory_orphan_inventory_record_in_scope(
            rec,
            min_content_len,
            requested_scope,
            scope_mode,
        ) {
            continue;
        }
        inventory.examined += 1;
        if keys_with_edges.contains(&rec.key) {
            continue;
        }

        inventory.orphan_total += 1;
        if memory_has_any_tag(rec, skip_tags) {
            inventory.skipped_blacklisted_orphan += 1;
            continue;
        }
        if memory_kind_is_any(rec, skip_kinds) {
            inventory.skipped_blacklisted_kind += 1;
            continue;
        }

        *kind_counts.entry(rec.kind.clone()).or_default() += 1;
        for tag in &rec.tags {
            *tag_counts.entry(tag.clone()).or_default() += 1;
        }
        let (content_preview, content_truncated, content_total_chars) =
            truncate_chars(&rec.content, preview_chars);
        rows.push(MemoryOrphanInventoryRow {
            record: rec.clone(),
            created_age_days: memory_age_days(now_secs, rec.created_at),
            updated_age_days: memory_age_days(now_secs, rec.updated_at),
            content_preview,
            content_truncated,
            content_total_chars,
        });
    }

    match sort {
        "newest" => rows.sort_by(|a, b| {
            b.record
                .updated_at
                .cmp(&a.record.updated_at)
                .then_with(|| a.record.key.cmp(&b.record.key))
        }),
        "kind" => rows.sort_by(|a, b| {
            a.record
                .kind
                .cmp(&b.record.kind)
                .then_with(|| b.updated_age_days.cmp(&a.updated_age_days))
                .then_with(|| a.record.key.cmp(&b.record.key))
        }),
        "importance" => rows.sort_by(|a, b| {
            b.record
                .importance
                .partial_cmp(&a.record.importance)
                .unwrap_or(std::cmp::Ordering::Equal)
                .then_with(|| b.updated_age_days.cmp(&a.updated_age_days))
                .then_with(|| a.record.key.cmp(&b.record.key))
        }),
        _ => rows.sort_by(|a, b| {
            b.updated_age_days
                .cmp(&a.updated_age_days)
                .then_with(|| a.record.key.cmp(&b.record.key))
        }),
    }

    inventory.eligible_orphans = rows.len() as u64;
    rows.truncate(max_rows);
    inventory.rows = rows;

    let mut by_kind: Vec<(String, u64)> = kind_counts.into_iter().collect();
    by_kind.sort_by(|(ka, ca), (kb, cb)| cb.cmp(ca).then_with(|| ka.cmp(kb)));
    inventory.by_kind = by_kind;

    let mut top_tags: Vec<(String, u64)> = tag_counts.into_iter().collect();
    top_tags.sort_by(|(ta, ca), (tb, cb)| cb.cmp(ca).then_with(|| ta.cmp(tb)));
    top_tags.truncate(10);
    inventory.top_tags = top_tags;

    inventory
}

#[allow(clippy::too_many_arguments)]
fn preview_memory_orphan_candidates(
    all: &[MemoryRecord],
    keys_with_edges: &HashSet<String>,
    threshold: f64,
    min_content_len: usize,
    max_orphans: usize,
    candidate_limit: usize,
    skip_tags: &[String],
    skip_kinds: &[String],
    require_scope_compatible: bool,
    requested_scope: Option<&str>,
    scope_mode: MemorySearchScopeMode,
) -> MemoryOrphanCandidatePreview {
    let mut preview = MemoryOrphanCandidatePreview::default();
    let mut orphans: Vec<MemoryRecord> = Vec::new();

    for rec in all {
        if rec.kind == "skill" {
            continue;
        }
        if rec.status != "active" && !rec.status.is_empty() {
            continue;
        }
        if rec.content.len() < min_content_len {
            continue;
        }
        if let Some(scope) = requested_scope {
            if !memory_search_scope_mode_matches(rec, scope, scope_mode) {
                continue;
            }
        }
        preview.examined += 1;
        if keys_with_edges.contains(&rec.key) {
            continue;
        }
        if memory_has_any_tag(rec, skip_tags) {
            preview.skipped_blacklisted_orphan += 1;
            continue;
        }
        if memory_kind_is_any(rec, skip_kinds) {
            preview.skipped_blacklisted_kind += 1;
            continue;
        }
        orphans.push(rec.clone());
        if orphans.len() >= max_orphans {
            break;
        }
    }

    preview.eligible_orphans = orphans.len() as u64;
    for orphan in &orphans {
        let already_linked: HashSet<String> = HashSet::new();
        let candidate_pool: Vec<MemoryRecord> = all
            .iter()
            .filter(|candidate| {
                memory_link_orphan_candidate_allowed(
                    orphan,
                    candidate,
                    skip_tags,
                    skip_kinds,
                    require_scope_compatible,
                )
            })
            .cloned()
            .collect();
        let suggestions = compute_link_suggestions(
            orphan,
            &candidate_pool,
            &already_linked,
            candidate_limit,
            skip_tags,
        );
        match suggestions.first() {
            Some((_, confidence, _)) if *confidence >= threshold => preview.would_link += 1,
            Some(_) => preview.skipped_low_score += 1,
            None => preview.skipped_no_candidates += 1,
        }
        preview.rows.push(MemoryOrphanCandidatePreviewRow {
            orphan: orphan.clone(),
            suggestions,
        });
    }

    preview
}

fn memory_pair_scope_relation(source: &MemoryRecord, target: &MemoryRecord) -> &'static str {
    match (memory_scope_value(source), memory_scope_value(target)) {
        (Some(a), Some(b)) if a == b => "same_scope",
        (Some(a), Some(b)) if project_scopes_read_time_compatible(a, b) => "same_project_scope",
        (Some("global"), _) | (_, Some("global")) | (None, _) | (_, None) => "global_or_unscoped",
        _ => "cross_scope",
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum MemoryRelatedKeysReviewScopeFilter {
    Compatible,
    Exact,
}

impl MemoryRelatedKeysReviewScopeFilter {
    fn parse(value: Option<&str>) -> Option<Self> {
        match value {
            Some("compatible") | None => Some(Self::Compatible),
            Some("exact") => Some(Self::Exact),
            _ => None,
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Compatible => "compatible",
            Self::Exact => "exact",
        }
    }

    fn matches_record(self, rec: &MemoryRecord, requested_scope: Option<&str>) -> bool {
        match self {
            Self::Compatible => true,
            Self::Exact => requested_scope
                .map(str::trim)
                .filter(|scope| !scope.is_empty())
                .and_then(|scope| memory_scope_value(rec).map(|rec_scope| rec_scope == scope))
                .unwrap_or(false),
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum MemoryRelatedKeysSelectionStrategy {
    PreserveOrder,
    OrphanReduction,
}

impl MemoryRelatedKeysSelectionStrategy {
    fn parse(value: Option<&str>) -> Option<Self> {
        match value {
            Some("preserve_order") | None => Some(Self::PreserveOrder),
            Some("orphan_reduction") => Some(Self::OrphanReduction),
            _ => None,
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::PreserveOrder => "preserve_order",
            Self::OrphanReduction => "orphan_reduction",
        }
    }
}

fn memory_related_key_excluded_reason(
    rec: &MemoryRecord,
    skip_tags: &[String],
    skip_kinds: &[String],
    requested_scope: Option<&str>,
    scope_mode: MemorySearchScopeMode,
) -> Option<&'static str> {
    memory_related_key_excluded_reason_with_scope_filter(
        rec,
        skip_tags,
        skip_kinds,
        requested_scope,
        scope_mode,
        MemoryRelatedKeysReviewScopeFilter::Compatible,
    )
}

fn memory_related_key_excluded_reason_with_scope_filter(
    rec: &MemoryRecord,
    skip_tags: &[String],
    skip_kinds: &[String],
    requested_scope: Option<&str>,
    scope_mode: MemorySearchScopeMode,
    scope_filter: MemoryRelatedKeysReviewScopeFilter,
) -> Option<&'static str> {
    if rec.status != "active" && !rec.status.is_empty() {
        return Some("target_not_active");
    }
    if ab_store::COVERAGE_EXCLUDED_KINDS
        .iter()
        .any(|kind| rec.kind.eq_ignore_ascii_case(kind))
        || memory_kind_is_any(rec, skip_kinds)
    {
        return Some("target_excluded_kind");
    }
    if memory_has_any_tag(rec, skip_tags) {
        return Some("target_excluded_tag");
    }
    if let Some(scope) = requested_scope {
        if !memory_search_scope_mode_matches(rec, scope, scope_mode) {
            return Some("target_scope_filtered");
        }
    }
    if !scope_filter.matches_record(rec, requested_scope) {
        return Some("target_scope_not_exact");
    }
    None
}

fn memory_related_key_preview(rec: &MemoryRecord, preview_chars: usize) -> String {
    let (preview, _, _) = truncate_chars(&rec.content, preview_chars);
    preview.replace('\n', " ").replace('\r', " ")
}

fn memory_related_add_bucket(
    pair_counts: &mut BTreeMap<String, u64>,
    source_counts: &mut BTreeMap<String, HashSet<String>>,
    bucket: &str,
    source_key: &str,
) {
    *pair_counts.entry(bucket.to_string()).or_default() += 1;
    source_counts
        .entry(bucket.to_string())
        .or_default()
        .insert(source_key.to_string());
}

fn memory_related_counter_rows(
    counts: &HashMap<String, u64>,
    field_name: &str,
    count_name: &str,
    limit: usize,
) -> Vec<Value> {
    let mut rows: Vec<(&String, &u64)> = counts.iter().collect();
    rows.sort_by(|(ka, ca), (kb, cb)| cb.cmp(ca).then_with(|| ka.cmp(kb)));
    rows.truncate(limit);
    rows.into_iter()
        .map(|(key, count)| json!({ field_name: key, count_name: count }))
        .collect()
}

fn memory_related_key_count_rows(
    counts: &HashMap<String, u64>,
    by_key: &HashMap<&str, &MemoryRecord>,
    count_name: &str,
    limit: usize,
) -> Vec<Value> {
    let mut rows: Vec<(&String, &u64)> = counts.iter().collect();
    rows.sort_by(|(ka, ca), (kb, cb)| cb.cmp(ca).then_with(|| ka.cmp(kb)));
    rows.truncate(limit);
    rows.into_iter()
        .map(|(key, count)| {
            let rec = by_key.get(key.as_str()).copied();
            json!({
                "key": key,
                "kind": rec.map(|r| r.kind.as_str()).unwrap_or(""),
                "scope": rec.and_then(|r| r.scope.as_deref()),
                count_name: count,
            })
        })
        .collect()
}

const MEMORY_RELATED_KEYS_REVIEW_PACKET_SCHEMA: &str =
    "agent_bridge.memory_related_keys_review_packet.v0";

fn memory_related_keys_review_skip_tags() -> Vec<String> {
    [
        "auto_curated",
        "implicit",
        "unverified_identifier",
        "alert",
        "ttl:7d",
        "ttl:14d",
    ]
    .iter()
    .map(|tag| (*tag).to_string())
    .collect()
}

fn memory_related_keys_review_skip_kinds() -> Vec<String> {
    ["alert", "work_memory", "snapshot"]
        .iter()
        .map(|kind| (*kind).to_string())
        .collect()
}

#[allow(clippy::too_many_arguments)]
fn memory_related_keys_preflight_from_records(
    all: &[MemoryRecord],
    edges_by_key: &HashMap<String, Vec<MemoryEdge>>,
    skip_tags: &[String],
    skip_kinds: &[String],
    require_scope_compatible: bool,
    dedupe_undirected_pairs: bool,
    requested_scope: Option<&str>,
    scope_mode: MemorySearchScopeMode,
    max_pairs: usize,
    preview_chars: usize,
) -> Value {
    let by_key: HashMap<&str, &MemoryRecord> =
        all.iter().map(|rec| (rec.key.as_str(), rec)).collect();
    let visible_records: Vec<&MemoryRecord> = all
        .iter()
        .filter(|rec| {
            memory_graph_topology_record_visible(
                rec,
                requested_scope,
                scope_mode,
                skip_tags,
                skip_kinds,
            )
        })
        .collect();
    let visible_keys: HashSet<String> = visible_records.iter().map(|rec| rec.key.clone()).collect();

    let mut existing_pairs: HashSet<(String, String)> = HashSet::new();
    let mut keys_with_edges: HashSet<String> = HashSet::new();
    for rec in &visible_records {
        let Some(edges) = edges_by_key.get(&rec.key) else {
            continue;
        };
        for edge in edges {
            let other = if edge.from_key == rec.key {
                &edge.to_key
            } else if edge.to_key == rec.key {
                &edge.from_key
            } else {
                continue;
            };
            if !visible_keys.contains(other) {
                continue;
            }
            existing_pairs.insert(undirected_memory_pair_key(&rec.key, other));
            keys_with_edges.insert(rec.key.clone());
            keys_with_edges.insert(other.clone());
        }
    }

    let current_orphans: HashSet<String> = visible_keys
        .iter()
        .filter(|key| !keys_with_edges.contains(*key))
        .cloned()
        .collect();
    let mut bucket_pair_counts: BTreeMap<String, u64> = BTreeMap::new();
    let mut bucket_source_counts: BTreeMap<String, HashSet<String>> = BTreeMap::new();
    let mut candidate_pairs_seen: HashSet<(String, String)> = HashSet::new();
    let mut candidate_sources: HashSet<String> = HashSet::new();
    let mut candidate_targets: HashSet<String> = HashSet::new();
    let mut candidate_touched_orphans: HashSet<String> = HashSet::new();
    let mut source_counts: HashMap<String, u64> = HashMap::new();
    let mut target_counts: HashMap<String, u64> = HashMap::new();
    let mut kind_pair_counts: HashMap<String, u64> = HashMap::new();
    let mut scope_pair_counts: HashMap<String, u64> = HashMap::new();
    let mut samples: Vec<Value> = Vec::new();

    for source in &visible_records {
        for raw_target in &source.related_keys {
            let target_key = raw_target.trim();
            if target_key.is_empty() {
                continue;
            }
            let Some(target) = by_key.get(target_key).copied() else {
                memory_related_add_bucket(
                    &mut bucket_pair_counts,
                    &mut bucket_source_counts,
                    "target_missing",
                    &source.key,
                );
                continue;
            };
            if let Some(reason) = memory_related_key_excluded_reason(
                target,
                skip_tags,
                skip_kinds,
                requested_scope,
                scope_mode,
            ) {
                memory_related_add_bucket(
                    &mut bucket_pair_counts,
                    &mut bucket_source_counts,
                    reason,
                    &source.key,
                );
                continue;
            }
            if !memory_scopes_compatible(source, target, require_scope_compatible) {
                memory_related_add_bucket(
                    &mut bucket_pair_counts,
                    &mut bucket_source_counts,
                    "cross_scope",
                    &source.key,
                );
                continue;
            }
            let undirected_pair = undirected_memory_pair_key(&source.key, &target.key);
            if existing_pairs.contains(&undirected_pair) {
                memory_related_add_bucket(
                    &mut bucket_pair_counts,
                    &mut bucket_source_counts,
                    "already_has_edge",
                    &source.key,
                );
                continue;
            }
            let candidate_pair = if dedupe_undirected_pairs {
                undirected_pair
            } else {
                (source.key.clone(), target.key.clone())
            };
            if !candidate_pairs_seen.insert(candidate_pair) {
                memory_related_add_bucket(
                    &mut bucket_pair_counts,
                    &mut bucket_source_counts,
                    "duplicate_candidate",
                    &source.key,
                );
                continue;
            }

            memory_related_add_bucket(
                &mut bucket_pair_counts,
                &mut bucket_source_counts,
                "safe_candidate",
                &source.key,
            );
            candidate_sources.insert(source.key.clone());
            candidate_targets.insert(target.key.clone());
            if current_orphans.contains(&source.key) {
                candidate_touched_orphans.insert(source.key.clone());
            }
            if current_orphans.contains(&target.key) {
                candidate_touched_orphans.insert(target.key.clone());
            }
            *source_counts.entry(source.key.clone()).or_default() += 1;
            *target_counts.entry(target.key.clone()).or_default() += 1;
            *kind_pair_counts
                .entry(format!("{} -> {}", source.kind, target.kind))
                .or_default() += 1;
            let from_scope = memory_scope_value(source).unwrap_or("<global>");
            let to_scope = memory_scope_value(target).unwrap_or("<global>");
            *scope_pair_counts
                .entry(format!("{from_scope} -> {to_scope}"))
                .or_default() += 1;

            if samples.len() < max_pairs {
                samples.push(json!({
                    "from_key": source.key,
                    "to_key": target.key,
                    "kind_pair": format!("{} -> {}", source.kind, target.kind),
                    "scope_relation": memory_pair_scope_relation(source, target),
                    "from_scope": source.scope,
                    "to_scope": target.scope,
                    "from_preview": memory_related_key_preview(source, preview_chars),
                    "to_preview": memory_related_key_preview(target, preview_chars),
                }));
            }
        }
    }

    let current_orphan_count = current_orphans.len() as u64;
    let projected_orphans =
        current_orphan_count.saturating_sub(candidate_touched_orphans.len() as u64);
    let bucket_counts: Vec<Value> = bucket_pair_counts
        .iter()
        .map(|(bucket, pairs)| {
            json!({
                "bucket": bucket,
                "pairs": pairs,
                "sources": bucket_source_counts
                    .get(bucket)
                    .map(|sources| sources.len())
                    .unwrap_or(0),
            })
        })
        .collect();

    json!({
        "read_only": true,
        "filters": {
            "skip_tags": skip_tags,
            "skip_kinds": skip_kinds,
            "require_scope_compatible": require_scope_compatible,
            "dedupe_undirected_pairs": dedupe_undirected_pairs,
            "scope": requested_scope,
            "scope_mode": scope_mode.label(),
        },
        "visible_total": visible_keys.len(),
        "current_edge_pairs": existing_pairs.len(),
        "current_orphans": current_orphan_count,
        "candidate_pairs": bucket_pair_counts.get("safe_candidate").copied().unwrap_or(0),
        "candidate_sources": candidate_sources.len(),
        "candidate_targets": candidate_targets.len(),
        "orphan_candidate_nodes": candidate_touched_orphans.len(),
        "projected_orphans_after_candidates": projected_orphans,
        "orphans_reduced": current_orphan_count.saturating_sub(projected_orphans),
        "bucket_counts": bucket_counts,
        "top_sources": memory_related_key_count_rows(&source_counts, &by_key, "outbound_candidates", 12),
        "top_targets": memory_related_key_count_rows(&target_counts, &by_key, "inbound_candidates", 12),
        "kind_pairs": memory_related_counter_rows(&kind_pair_counts, "kind_pair", "pairs", 12),
        "scope_pairs": memory_related_counter_rows(&scope_pair_counts, "scope_pair", "pairs", 12),
        "sample_pairs": samples,
        "next_step": "Review bucket_counts and sample_pairs. If quality is acceptable, add a separate write-capable materialization path with dry_run=true by default and capped batch size; do not write edges from this preflight tool.",
    })
}

#[derive(Debug, Clone)]
struct MemoryRelatedKeyEdgePlan {
    from_key: String,
    to_key: String,
    from_kind: String,
    to_kind: String,
    from_scope: Option<String>,
    to_scope: Option<String>,
    from_preview: String,
    to_preview: String,
}

impl MemoryRelatedKeyEdgePlan {
    fn value(&self) -> Value {
        json!({
            "from_key": self.from_key,
            "to_key": self.to_key,
            "kind_pair": format!("{} -> {}", self.from_kind, self.to_kind),
            "from_scope": self.from_scope,
            "to_scope": self.to_scope,
            "from_preview": self.from_preview,
            "to_preview": self.to_preview,
        })
    }
}

fn memory_related_keys_selected_edge_hash_v1(edges: &[MemoryRelatedKeyEdgePlan]) -> String {
    let canonical_edges: Vec<Value> = edges
        .iter()
        .map(|edge| {
            json!({
                "from_key": edge.from_key,
                "to_key": edge.to_key,
                "edge_type": "relates",
            })
        })
        .collect();
    let canonical = json!({
        "schema": "agent_bridge.memory_related_keys.selected_edges.v1",
        "edges": canonical_edges,
    });
    let encoded = serde_json::to_vec(&canonical).unwrap_or_default();
    let mut hasher = Sha256::new();
    ShaDigest::update(&mut hasher, encoded);
    format!("{:x}", ShaDigest::finalize(hasher))
}

#[derive(Debug, Default)]
struct MemoryRelatedKeysMaterializePlan {
    visible_total: usize,
    current_edge_pairs: usize,
    current_orphans: usize,
    safe_candidate_pairs_before_caps: u64,
    selected_edges: Vec<MemoryRelatedKeyEdgePlan>,
    selected_touched_orphans: HashSet<String>,
    bucket_pair_counts: BTreeMap<String, u64>,
    bucket_source_counts: BTreeMap<String, HashSet<String>>,
    selected_source_counts: HashMap<String, u64>,
    selected_target_counts: HashMap<String, u64>,
}

struct MemoryRelatedKeyCandidate<'a> {
    source: &'a MemoryRecord,
    target: &'a MemoryRecord,
    scan_index: usize,
}

impl MemoryRelatedKeyCandidate<'_> {
    fn orphan_touch_count(&self, current_orphans: &HashSet<String>) -> u8 {
        let source = current_orphans.contains(&self.source.key) as u8;
        let target = current_orphans.contains(&self.target.key) as u8;
        source + target
    }
}

impl MemoryRelatedKeysMaterializePlan {
    fn bucket_rows(&self) -> Vec<Value> {
        self.bucket_pair_counts
            .iter()
            .map(|(bucket, pairs)| {
                json!({
                    "bucket": bucket,
                    "pairs": pairs,
                    "sources": self.bucket_source_counts
                        .get(bucket)
                        .map(|sources| sources.len())
                        .unwrap_or(0),
                })
            })
            .collect()
    }

    fn projected_orphans_after_selected(&self) -> u64 {
        (self.current_orphans as u64).saturating_sub(self.selected_touched_orphans.len() as u64)
    }

    fn value(
        &self,
        by_key: &HashMap<&str, &MemoryRecord>,
        max_edges: usize,
        max_outbound_per_source: u32,
        max_inbound_per_target: u32,
    ) -> Value {
        let projected_orphans = self.projected_orphans_after_selected();
        let selected_edge_hash_v1 = memory_related_keys_selected_edge_hash_v1(&self.selected_edges);
        json!({
            "visible_total": self.visible_total,
            "current_edge_pairs": self.current_edge_pairs,
            "current_orphans": self.current_orphans,
            "safe_candidate_pairs_before_caps": self.safe_candidate_pairs_before_caps,
            "selected_edges_count": self.selected_edges.len(),
            "selected_edge_hash_v1": selected_edge_hash_v1,
            "max_edges": max_edges,
            "max_outbound_per_source": max_outbound_per_source,
            "max_inbound_per_target": max_inbound_per_target,
            "orphan_candidate_nodes_selected": self.selected_touched_orphans.len(),
            "projected_orphans_after_selected": projected_orphans,
            "orphans_reduced_by_selected": (self.current_orphans as u64).saturating_sub(projected_orphans),
            "bucket_counts": self.bucket_rows(),
            "top_selected_sources": memory_related_key_count_rows(
                &self.selected_source_counts,
                by_key,
                "outbound_selected",
                12,
            ),
            "top_selected_targets": memory_related_key_count_rows(
                &self.selected_target_counts,
                by_key,
                "inbound_selected",
                12,
            ),
            "selected_edges": self.selected_edges.iter().map(MemoryRelatedKeyEdgePlan::value).collect::<Vec<_>>(),
        })
    }
}

#[allow(clippy::too_many_arguments)]
fn memory_related_keys_materialize_plan_from_records(
    all: &[MemoryRecord],
    edges_by_key: &HashMap<String, Vec<MemoryEdge>>,
    skip_tags: &[String],
    skip_kinds: &[String],
    require_scope_compatible: bool,
    dedupe_undirected_pairs: bool,
    requested_scope: Option<&str>,
    scope_mode: MemorySearchScopeMode,
    max_edges: usize,
    max_outbound_per_source: u32,
    max_inbound_per_target: u32,
    preview_chars: usize,
) -> MemoryRelatedKeysMaterializePlan {
    memory_related_keys_materialize_plan_from_records_with_scope_filter(
        all,
        edges_by_key,
        skip_tags,
        skip_kinds,
        require_scope_compatible,
        dedupe_undirected_pairs,
        requested_scope,
        scope_mode,
        MemoryRelatedKeysReviewScopeFilter::Compatible,
        MemoryRelatedKeysSelectionStrategy::PreserveOrder,
        max_edges,
        max_outbound_per_source,
        max_inbound_per_target,
        preview_chars,
    )
}

#[allow(clippy::too_many_arguments)]
fn memory_related_keys_materialize_plan_from_records_with_scope_filter(
    all: &[MemoryRecord],
    edges_by_key: &HashMap<String, Vec<MemoryEdge>>,
    skip_tags: &[String],
    skip_kinds: &[String],
    require_scope_compatible: bool,
    dedupe_undirected_pairs: bool,
    requested_scope: Option<&str>,
    scope_mode: MemorySearchScopeMode,
    scope_filter: MemoryRelatedKeysReviewScopeFilter,
    selection_strategy: MemoryRelatedKeysSelectionStrategy,
    max_edges: usize,
    max_outbound_per_source: u32,
    max_inbound_per_target: u32,
    preview_chars: usize,
) -> MemoryRelatedKeysMaterializePlan {
    let by_key: HashMap<&str, &MemoryRecord> =
        all.iter().map(|rec| (rec.key.as_str(), rec)).collect();
    let visible_records: Vec<&MemoryRecord> = all
        .iter()
        .filter(|rec| {
            memory_graph_topology_record_visible(
                rec,
                requested_scope,
                scope_mode,
                skip_tags,
                skip_kinds,
            ) && scope_filter.matches_record(rec, requested_scope)
        })
        .collect();
    let visible_keys: HashSet<String> = visible_records.iter().map(|rec| rec.key.clone()).collect();

    let mut existing_pairs: HashSet<(String, String)> = HashSet::new();
    let mut keys_with_edges: HashSet<String> = HashSet::new();
    for rec in &visible_records {
        let Some(edges) = edges_by_key.get(&rec.key) else {
            continue;
        };
        for edge in edges {
            let other = if edge.from_key == rec.key {
                &edge.to_key
            } else if edge.to_key == rec.key {
                &edge.from_key
            } else {
                continue;
            };
            if !visible_keys.contains(other) {
                continue;
            }
            existing_pairs.insert(undirected_memory_pair_key(&rec.key, other));
            keys_with_edges.insert(rec.key.clone());
            keys_with_edges.insert(other.clone());
        }
    }

    let current_orphans: HashSet<String> = visible_keys
        .iter()
        .filter(|key| !keys_with_edges.contains(*key))
        .cloned()
        .collect();
    let mut plan = MemoryRelatedKeysMaterializePlan {
        visible_total: visible_keys.len(),
        current_edge_pairs: existing_pairs.len(),
        current_orphans: current_orphans.len(),
        ..Default::default()
    };
    let mut candidate_pairs_seen: HashSet<(String, String)> = HashSet::new();
    let mut candidates = Vec::new();
    let mut scan_index = 0_usize;

    for source in &visible_records {
        for raw_target in &source.related_keys {
            let target_key = raw_target.trim();
            if target_key.is_empty() {
                continue;
            }
            let Some(target) = by_key.get(target_key).copied() else {
                memory_related_add_bucket(
                    &mut plan.bucket_pair_counts,
                    &mut plan.bucket_source_counts,
                    "target_missing",
                    &source.key,
                );
                continue;
            };
            if let Some(reason) = memory_related_key_excluded_reason_with_scope_filter(
                target,
                skip_tags,
                skip_kinds,
                requested_scope,
                scope_mode,
                scope_filter,
            ) {
                memory_related_add_bucket(
                    &mut plan.bucket_pair_counts,
                    &mut plan.bucket_source_counts,
                    reason,
                    &source.key,
                );
                continue;
            }
            if !memory_scopes_compatible(source, target, require_scope_compatible) {
                memory_related_add_bucket(
                    &mut plan.bucket_pair_counts,
                    &mut plan.bucket_source_counts,
                    "cross_scope",
                    &source.key,
                );
                continue;
            }
            let undirected_pair = undirected_memory_pair_key(&source.key, &target.key);
            if existing_pairs.contains(&undirected_pair) {
                memory_related_add_bucket(
                    &mut plan.bucket_pair_counts,
                    &mut plan.bucket_source_counts,
                    "already_has_edge",
                    &source.key,
                );
                continue;
            }
            let candidate_pair = if dedupe_undirected_pairs {
                undirected_pair
            } else {
                (source.key.clone(), target.key.clone())
            };
            if !candidate_pairs_seen.insert(candidate_pair) {
                memory_related_add_bucket(
                    &mut plan.bucket_pair_counts,
                    &mut plan.bucket_source_counts,
                    "duplicate_candidate",
                    &source.key,
                );
                continue;
            }

            plan.safe_candidate_pairs_before_caps += 1;
            candidates.push(MemoryRelatedKeyCandidate {
                source,
                target,
                scan_index,
            });
            scan_index += 1;
        }
    }

    if selection_strategy == MemoryRelatedKeysSelectionStrategy::OrphanReduction {
        candidates.sort_by(|a, b| {
            b.orphan_touch_count(&current_orphans)
                .cmp(&a.orphan_touch_count(&current_orphans))
                .then_with(|| a.scan_index.cmp(&b.scan_index))
        });
    }

    let mut selected_outbound: HashMap<String, u32> = HashMap::new();
    let mut selected_inbound: HashMap<String, u32> = HashMap::new();

    for candidate in candidates {
        let source = candidate.source;
        let target = candidate.target;

        if plan.selected_edges.len() >= max_edges {
            memory_related_add_bucket(
                &mut plan.bucket_pair_counts,
                &mut plan.bucket_source_counts,
                "skipped_max_edges",
                &source.key,
            );
            continue;
        }
        let outbound = selected_outbound.get(&source.key).copied().unwrap_or(0);
        if outbound >= max_outbound_per_source {
            memory_related_add_bucket(
                &mut plan.bucket_pair_counts,
                &mut plan.bucket_source_counts,
                "skipped_outbound_cap",
                &source.key,
            );
            continue;
        }
        let inbound = selected_inbound.get(&target.key).copied().unwrap_or(0);
        if inbound >= max_inbound_per_target {
            memory_related_add_bucket(
                &mut plan.bucket_pair_counts,
                &mut plan.bucket_source_counts,
                "skipped_inbound_cap",
                &source.key,
            );
            continue;
        }

        memory_related_add_bucket(
            &mut plan.bucket_pair_counts,
            &mut plan.bucket_source_counts,
            "selected",
            &source.key,
        );
        *selected_outbound.entry(source.key.clone()).or_default() += 1;
        *selected_inbound.entry(target.key.clone()).or_default() += 1;
        *plan
            .selected_source_counts
            .entry(source.key.clone())
            .or_default() += 1;
        *plan
            .selected_target_counts
            .entry(target.key.clone())
            .or_default() += 1;
        if current_orphans.contains(&source.key) {
            plan.selected_touched_orphans.insert(source.key.clone());
        }
        if current_orphans.contains(&target.key) {
            plan.selected_touched_orphans.insert(target.key.clone());
        }
        plan.selected_edges.push(MemoryRelatedKeyEdgePlan {
            from_key: source.key.clone(),
            to_key: target.key.clone(),
            from_kind: source.kind.clone(),
            to_kind: target.kind.clone(),
            from_scope: source.scope.clone(),
            to_scope: target.scope.clone(),
            from_preview: memory_related_key_preview(source, preview_chars),
            to_preview: memory_related_key_preview(target, preview_chars),
        });
    }

    plan
}

fn memory_related_key_scope_relation_from_values(
    from_scope: Option<&str>,
    to_scope: Option<&str>,
) -> &'static str {
    match (from_scope, to_scope) {
        (Some(from), Some(to)) if from == to => "same_scope",
        (Some(from), Some(to)) if project_scopes_read_time_compatible(from, to) => {
            "same_project_scope"
        }
        (Some(_), Some(_)) => "cross_scope",
        (Some(_), None) => "target_global",
        (None, Some(_)) => "source_global",
        (None, None) => "global_pair",
    }
}

fn memory_related_key_review_edge_value(edge: &MemoryRelatedKeyEdgePlan) -> Value {
    let mut value = edge.value();
    if let Some(obj) = value.as_object_mut() {
        obj.insert("proposed_edge_type".into(), json!("relates"));
        obj.insert("reason".into(), json!("explicit_related_keys"));
        obj.insert("existing_edge_state".into(), json!("missing"));
        obj.insert(
            "scope_relation".into(),
            json!(memory_related_key_scope_relation_from_values(
                edge.from_scope.as_deref(),
                edge.to_scope.as_deref(),
            )),
        );
    }
    value
}

fn memory_related_keys_review_packet_from_records(
    all: &[MemoryRecord],
    edges_by_key: &HashMap<String, Vec<MemoryEdge>>,
    requested_scope: Option<&str>,
    scope_mode: MemorySearchScopeMode,
    scope_filter: MemoryRelatedKeysReviewScopeFilter,
    selection_strategy: MemoryRelatedKeysSelectionStrategy,
    max_pairs: usize,
    preview_chars: usize,
) -> Value {
    let skip_tags = memory_related_keys_review_skip_tags();
    let skip_kinds = memory_related_keys_review_skip_kinds();
    let max_edges = max_pairs.min(100);
    let max_outbound_per_source = 3_u32;
    let max_inbound_per_target = 3_u32;
    let by_key: HashMap<&str, &MemoryRecord> =
        all.iter().map(|rec| (rec.key.as_str(), rec)).collect();
    let plan = memory_related_keys_materialize_plan_from_records_with_scope_filter(
        all,
        edges_by_key,
        &skip_tags,
        &skip_kinds,
        true,
        true,
        requested_scope,
        scope_mode,
        scope_filter,
        selection_strategy,
        max_edges,
        max_outbound_per_source,
        max_inbound_per_target,
        preview_chars,
    );
    let selected_edges: Vec<Value> = plan
        .selected_edges
        .iter()
        .map(memory_related_key_review_edge_value)
        .collect();
    let ready = !selected_edges.is_empty();
    let block_reasons: Vec<&str> = if ready {
        Vec::new()
    } else if plan.safe_candidate_pairs_before_caps == 0 {
        vec!["no_safe_related_keys_candidates"]
    } else {
        vec!["no_selected_edges_after_caps"]
    };
    let projected_orphans = plan.projected_orphans_after_selected();

    json!({
        "schema": MEMORY_RELATED_KEYS_REVIEW_PACKET_SCHEMA,
        "read_only": true,
        "review_packet": {
            "ready": ready,
            "block_reasons": block_reasons,
            "implementation_stage": "ghp1_explicit_related_keys_dry_run_review_only",
            "selected_edges_count": selected_edges.len(),
            "safe_candidate_pairs_before_caps": plan.safe_candidate_pairs_before_caps,
            "visible_total": plan.visible_total,
            "current_edge_pairs": plan.current_edge_pairs,
            "current_orphans": plan.current_orphans,
            "orphan_candidate_nodes_selected": plan.selected_touched_orphans.len(),
            "projected_orphans_after_selected": projected_orphans,
            "orphans_reduced_by_selected": (plan.current_orphans as u64).saturating_sub(projected_orphans),
            "selected_edges": selected_edges,
        },
        "filters": {
            "skip_tags": skip_tags,
            "skip_kinds": skip_kinds,
            "require_scope_compatible": true,
            "dedupe_undirected_pairs": true,
            "scope": requested_scope,
            "scope_mode": scope_mode.label(),
            "scope_filter": scope_filter.label(),
            "selection_strategy": selection_strategy.label(),
            "max_pairs": max_edges,
            "max_outbound_per_source": max_outbound_per_source,
            "max_inbound_per_target": max_inbound_per_target,
            "preview_chars": preview_chars,
        },
        "bucket_counts": plan.bucket_rows(),
        "top_selected_sources": memory_related_key_count_rows(
            &plan.selected_source_counts,
            &by_key,
            "outbound_selected",
            12,
        ),
        "top_selected_targets": memory_related_key_count_rows(
            &plan.selected_target_counts,
            &by_key,
            "inbound_selected",
            12,
        ),
        "safety": {
            "read_only": true,
            "writes_memory": false,
            "writes_graph_edges": false,
            "writes_state": false,
            "changes_search_order": false,
            "changes_prod_retrieval_order": false,
            "changes_candidate_set_now": false,
            "approves_pagerank_prior": false,
            "approves_centrality_rank_prior": false,
            "runs_automatic_orphan_linking": false,
        },
        "write_contract": {
            "may_write_edges_now": false,
            "requires_separate_write_tool": true,
            "requires_sqlite_backup_before_write": true,
            "requires_pragma_quick_check_before_write": true,
            "requires_small_reviewed_batch": true,
            "requires_topology_rerun_after_write": true,
            "rollback": "delete reviewed edge batch or restore the pre-write SQLite backup",
        },
        "input_contract": {
            "raw_source_packet_included": false,
            "content_previews_included": true,
            "generated_noise_rows_filtered_by_default": true,
        },
        "next_step": "Review selected_edges only. A later write, if approved, must use a separate guarded writer with SQLite backup, quick_check, and topology re-run; this packet grants no write or ranking authority.",
    })
}

// ===========================================================================
//          memory_related_keys_review_packet (GHP-1 read-only review packet)
// ===========================================================================

/// GHP-1 review packet for explicit `related_keys` materialization.
///
/// This is stricter than the generic preflight surface: defaults exclude
/// generated-noise tags and the output is a human-review contract. It never
/// writes graph edges and never grants ranking or candidate-set authority.
pub struct MemoryRelatedKeysReviewPacketTool {
    hub: Hub,
}
impl MemoryRelatedKeysReviewPacketTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for MemoryRelatedKeysReviewPacketTool {
    fn name(&self) -> &'static str {
        "memory_related_keys_review_packet"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "GHP-1 read-only review packet for explicit memory related_keys graph \
                hygiene. Produces a capped, same-scope/scope-compatible packet with generated \
                noise filtered by default. Does not write memory_edges, change ranking, approve \
                PageRank/centrality, or run automatic orphan linking."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "scope": {
                        "type": "string",
                        "description": "Optional memory scope, e.g. project:/abs/path or domain:rust."
                    },
                    "scope_mode": {
                        "type": "string",
                        "enum": ["local_only", "local_plus_global", "exploratory"],
                        "default": "local_plus_global",
                        "description": "When scope is set: local_only keeps matching rows; local_plus_global also includes global/unscoped rows; exploratory scans all rows."
                    },
                    "scope_filter": {
                        "type": "string",
                        "enum": ["compatible", "exact"],
                        "default": "compatible",
                        "description": "compatible preserves scope-mode matching; exact requires source and target memory scope to exactly equal scope."
                    },
                    "selection_strategy": {
                        "type": "string",
                        "enum": ["preserve_order", "orphan_reduction"],
                        "default": "preserve_order",
                        "description": "preserve_order keeps the historical scan order; orphan_reduction selects candidates that touch current orphan nodes first while keeping all review caps and filters."
                    },
                    "max_records": {
                        "type": "integer",
                        "minimum": 100,
                        "maximum": 50000,
                        "default": 10000,
                        "description": "Maximum memory records loaded for analysis."
                    },
                    "max_pairs": {
                        "type": "integer",
                        "minimum": 0,
                        "maximum": 100,
                        "default": 20,
                        "description": "Maximum selected review-packet edge candidates returned."
                    },
                    "preview_chars": {
                        "type": "integer",
                        "minimum": 0,
                        "maximum": 1000,
                        "default": 160,
                        "description": "Content preview length for selected edge candidates."
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let requested_scope = args
            .get("scope")
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty());
        let scope_mode = MemorySearchScopeMode::parse(
            args.get("scope_mode")
                .and_then(|v| v.as_str())
                .map(str::trim)
                .filter(|s| !s.is_empty()),
            true,
        );
        let Some(scope_filter) = MemoryRelatedKeysReviewScopeFilter::parse(
            args.get("scope_filter")
                .and_then(|v| v.as_str())
                .map(str::trim)
                .filter(|s| !s.is_empty()),
        ) else {
            return Ok(ToolResult::error(
                "scope_filter must be one of: compatible, exact",
            ));
        };
        if scope_filter == MemoryRelatedKeysReviewScopeFilter::Exact && requested_scope.is_none() {
            return Ok(ToolResult::error(
                "scope_filter=exact requires a non-empty scope",
            ));
        }
        let Some(selection_strategy) = MemoryRelatedKeysSelectionStrategy::parse(
            args.get("selection_strategy")
                .and_then(|v| v.as_str())
                .map(str::trim)
                .filter(|s| !s.is_empty()),
        ) else {
            return Ok(ToolResult::error(
                "selection_strategy must be one of: preserve_order, orphan_reduction",
            ));
        };
        let max_records = args
            .get("max_records")
            .and_then(|v| v.as_u64())
            .unwrap_or(10_000)
            .clamp(100, 50_000) as usize;
        let max_pairs = args
            .get("max_pairs")
            .and_then(|v| v.as_u64())
            .unwrap_or(20)
            .min(100) as usize;
        let preview_chars = args
            .get("preview_chars")
            .and_then(|v| v.as_u64())
            .unwrap_or(160)
            .min(1000) as usize;

        let skip_tags = memory_related_keys_review_skip_tags();
        let skip_kinds = memory_related_keys_review_skip_kinds();
        let all = store
            .list_memories(None, MemoryListSort::Recent, max_records as u32)
            .await
            .unwrap_or_default();
        let mut edges_by_key: HashMap<String, Vec<MemoryEdge>> = HashMap::new();
        for rec in &all {
            let visible = memory_graph_topology_record_visible(
                rec,
                requested_scope,
                scope_mode,
                &skip_tags,
                &skip_kinds,
            );
            if !visible || !scope_filter.matches_record(rec, requested_scope) {
                continue;
            }
            if let Ok(edges) = store.memory_neighbors(&rec.key).await {
                edges_by_key.insert(rec.key.clone(), edges);
            }
        }

        let mut packet = memory_related_keys_review_packet_from_records(
            &all,
            &edges_by_key,
            requested_scope,
            scope_mode,
            scope_filter,
            selection_strategy,
            max_pairs,
            preview_chars,
        );
        if let Some(obj) = packet.as_object_mut() {
            obj.insert("loaded_records".into(), json!(all.len()));
            obj.insert("max_records".into(), json!(max_records));
        }
        Ok(ToolResult::json_text(&packet))
    }
}

