pub struct ContextBudgetTool;

impl ContextBudgetTool {
    pub fn new() -> Self {
        Self
    }
}

#[async_trait]
impl McpTool for ContextBudgetTool {
    fn name(&self) -> &'static str {
        "context_budget"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Estimate token usage from optional conversation text + turn count using offline heuristics; \
                 compare to an approximate model context limit and get a compaction recommendation. No API calls."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "model": {
                        "type": "string",
                        "description": "Model name hint for context window size (default: claude-sonnet-4).",
                        "default": "claude-sonnet-4"
                    },
                    "context_window": {
                        "type": "integer",
                        "minimum": 1,
                        "description": "Explicit context-window size in tokens — overrides the model→limit lookup. Pass 1000000 for long-context-beta (opus-4.x / sonnet-4.x @ 1M) sessions; the model name alone can't reveal the 200K-vs-1M SKU. Precedence: this arg > AGENT_BRIDGE_CONTEXT_WINDOW env > model default."
                    },
                    "conversation_turns": {
                        "type": "integer",
                        "minimum": 0,
                        "description": "When transcript is unavailable, each turn adds a coarse token guess.",
                        "default": 0
                    },
                    "text_sample": {
                        "type": "string",
                        "description": "Optional excerpt / transcript sample to token-estimate (mixed EN/CJK heuristic)."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let model = args
            .get("model")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty())
            .unwrap_or("claude-sonnet-4");
        let turns = args
            .get("conversation_turns")
            .and_then(|v| v.as_u64())
            .unwrap_or(0);
        let text = args
            .get("text_sample")
            .and_then(|v| v.as_str())
            .unwrap_or("");
        // Window precedence: explicit arg > AGENT_BRIDGE_CONTEXT_WINDOW env >
        // conservative model default (see context_pressure_estimate / #1758).
        let explicit_window = args
            .get("context_window")
            .or_else(|| args.get("model_limit"))
            .and_then(|v| v.as_u64());
        let (limit, limit_source) =
            resolve_context_window(explicit_window, env_context_window(), model);
        let estimated = estimated_usage_tokens(text, turns);
        let pct_raw = if limit == 0 {
            0.0
        } else {
            (estimated as f64 / limit as f64) * 100.0
        };
        let pct_used = (pct_raw * 10.0).round() / 10.0;
        let recommendation = budget_recommendation(pct_raw);
        Ok(ToolResult::json_text(&json!({
            "model_hint": model,
            "model_limit": limit,
            "model_limit_source": limit_source,
            "estimated_tokens_used": estimated,
            "pct_used": pct_used,
            "recommendation": recommendation,
            "heuristic_note": "Offline estimate only; actual tokenizer usage varies.",
        })))
    }
}

// ===========================================================================
//        context_pressure_estimate — L6 P3 metacognition probe
// ===========================================================================

/// L6 P3 — `context_pressure_estimate` MCP tool.
///
/// Companion to `context_budget` but framed for **introspection**: the
/// assistant reads its own context-window pressure as a categorical
/// fatigue tier (`fresh|engaged|strained|saturated`) plus distance to
/// compaction. Roadmap §3 L6 P3 (~0.3d).
///
/// Backed entirely by the existing offline `context_budget` heuristic —
/// no API calls, no LLM judge. Cheap enough to call at session
/// bootstrap + per-turn if desired.
pub struct ContextPressureEstimateTool;

impl ContextPressureEstimateTool {
    pub fn new() -> Self {
        Self
    }
}

impl Default for ContextPressureEstimateTool {
    fn default() -> Self {
        Self::new()
    }
}

#[async_trait]
impl McpTool for ContextPressureEstimateTool {
    fn name(&self) -> &'static str {
        "context_pressure_estimate"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "L6 P3 metacognition probe — read the assistant's own \
                 context-window pressure as a categorical fatigue tier (fresh / \
                 engaged / strained / saturated) plus distance-to-compaction. \
                 Backed by the same offline heuristic as `context_budget` but \
                 surfaced for introspective decisions (\"should I compact \
                 before starting another long task?\"). No API calls."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "model": {
                        "type": "string",
                        "description": "Model name hint for context window size (default: claude-sonnet-4).",
                        "default": "claude-sonnet-4"
                    },
                    "context_window": {
                        "type": "integer",
                        "minimum": 1,
                        "description": "Explicit context-window size in tokens — overrides the model→limit lookup. Use on long-context-beta sessions (e.g. opus-4.x / sonnet-4.x @ 1M): the model name alone cannot reveal the 200K-vs-1M SKU, so omitting this defaults to a conservative 200K and inflates pressure up to 5×. Pass 1000000 when on the 1M beta. Precedence: this arg > AGENT_BRIDGE_CONTEXT_WINDOW env > model default (set the env once machine-wide to avoid per-call args)."
                    },
                    "conversation_turns": {
                        "type": "integer",
                        "minimum": 0,
                        "description": "Turn count for coarse-overhead estimate when no transcript is available.",
                        "default": 0
                    },
                    "text_sample": {
                        "type": "string",
                        "description": "Optional transcript / excerpt sample for token-estimation (mixed EN/CJK heuristic)."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        use crate::context_budget::{
            budget_recommendation, env_context_window, estimated_usage_tokens, fatigue_tier,
            model_supports_1m_beta, resolve_context_window,
        };
        let model = args
            .get("model")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty())
            .unwrap_or("claude-sonnet-4");
        let turns = args
            .get("conversation_turns")
            .and_then(|v| v.as_u64())
            .unwrap_or(0);
        let text_raw = args
            .get("text_sample")
            .and_then(|v| v.as_str())
            .unwrap_or("");
        let text_sample_provided = !text_raw.is_empty();

        // Resolve the window: explicit caller arg > AGENT_BRIDGE_CONTEXT_WINDOW
        // env (machine-level truth, survives a client stripping the unknown
        // arg) > conservative model default. `model_limit` accepted as a
        // defensive alias for callers following the orchestrate_scan hint.
        let explicit_window = args
            .get("context_window")
            .or_else(|| args.get("model_limit"))
            .and_then(|v| v.as_u64());
        let (limit, limit_source) =
            resolve_context_window(explicit_window, env_context_window(), model);
        // Flag the 1M ambiguity only when we fell all the way back to the
        // model default AND the model is a long-context-beta family — tells
        // the caller to set the window (guards the #1758 5× inflation).
        let one_m_beta_possible = limit_source == "model_default" && model_supports_1m_beta(model);
        let estimated = estimated_usage_tokens(text_raw, turns);
        let pct_raw = if limit == 0 {
            0.0
        } else {
            (estimated as f64 / limit as f64) * 100.0
        };
        let pct_used = (pct_raw * 10.0).round() / 10.0;
        let tier = fatigue_tier(pct_raw);
        let recommendation = budget_recommendation(pct_raw);
        // Distance to soft compaction trigger (urgent_handoff at 80%).
        // Clamped at 0 — we never report "negative distance" since past
        // the threshold the model has already overrun the safe zone.
        let soft_trigger = (limit as f64 * 0.80) as u64;
        let distance_to_compaction = soft_trigger.saturating_sub(estimated);

        // L6 P3 dogfood 5/13 + 5/19: no-sample reading systematically
        // under-counted. Flag confidence so the caller can weight the
        // tier accordingly rather than treating heuristic-only as ground
        // truth.
        let confidence = if text_sample_provided { "high" } else { "low" };
        let mut note = String::from(if text_sample_provided {
            "Estimate uses turn × per-turn guess + actual sample tokens + system baseline."
        } else {
            "No text_sample passed — estimate is heuristic-only and may under-count tool-heavy turns. Pass `text_sample` (recent transcript excerpt) for higher confidence."
        });
        if one_m_beta_possible {
            note.push_str(
                " NOTE: limit defaulted to 200K but this is a long-context-beta family (opus-4.x / sonnet-4.x); if the session runs the 1M beta, pass context_window=1000000 (or set AGENT_BRIDGE_CONTEXT_WINDOW=1000000 once, machine-wide — survives clients that strip the arg) — otherwise pct_used / fatigue_tier are inflated up to 5×.",
            );
        }

        Ok(ToolResult::json_text(&json!({
            "model_hint": model,
            "model_limit": limit,
            "model_limit_source": limit_source,
            "long_context_beta_possible": one_m_beta_possible,
            "estimated_tokens_used": estimated,
            "pct_used": pct_used,
            "fatigue_tier": tier,
            "distance_to_compaction_tokens": distance_to_compaction,
            "recommendation": recommendation,
            "text_sample_provided": text_sample_provided,
            "confidence": confidence,
            "note": note,
            "heuristic_note": "Offline estimate; actual tokenizer usage varies. Tier bands per roadmap §3 L6 P3.",
        })))
    }
}

// ===========================================================================
//        research_cycle_plan - read-only/advisory research control packet
// ===========================================================================

pub struct ResearchCyclePlanTool;

impl ResearchCyclePlanTool {
    pub fn new() -> Self {
        Self
    }
}

impl Default for ResearchCyclePlanTool {
    fn default() -> Self {
        Self::new()
    }
}

fn research_cycle_text(args: &Value, key: &str) -> String {
    args.get(key)
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(str::to_string)
        .unwrap_or_default()
}

fn research_cycle_text_list(args: &Value, key: &str) -> Vec<String> {
    match args.get(key) {
        Some(Value::Array(values)) => values
            .iter()
            .filter_map(Value::as_str)
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(str::to_string)
            .take(20)
            .collect(),
        Some(Value::String(raw)) => {
            let trimmed = raw.trim();
            if trimmed.is_empty() {
                Vec::new()
            } else {
                vec![trimmed.to_string()]
            }
        }
        _ => Vec::new(),
    }
}

fn research_cycle_requested_actions(args: &Value) -> BTreeSet<String> {
    research_cycle_text_list(args, "requested_actions")
        .into_iter()
        .map(|action| {
            action
                .chars()
                .map(|c| {
                    if c.is_ascii_alphanumeric() {
                        c.to_ascii_lowercase()
                    } else {
                        '_'
                    }
                })
                .collect::<String>()
        })
        .collect()
}

fn research_cycle_action(rank: u32, action: &str, reason: &str, mutation: bool) -> Value {
    json!({
        "rank": rank,
        "action": action,
        "reason": reason,
        "requires_separate_tool_call": mutation,
        "this_tool_mutates_state": false,
    })
}

fn build_research_cycle_plan(args: &Value) -> Value {
    let research_question = research_cycle_text(args, "research_question");
    let hypothesis = research_cycle_text(args, "hypothesis");
    let source_anchors = research_cycle_text_list(args, "source_anchors");
    let proposed_experiment = research_cycle_text(args, "proposed_experiment");
    let experiment_command = research_cycle_text(args, "experiment_command");
    let evidence_summary = research_cycle_text(args, "evidence_summary");
    let reproducibility_handle = research_cycle_text(args, "reproducibility_handle");
    let expected_artifact = research_cycle_text(args, "expected_artifact");
    let falsifier = research_cycle_text(args, "falsifier");
    let owner = research_cycle_text(args, "owner");
    let reviewer = research_cycle_text(args, "reviewer");
    let forum_thread_id = args.get("forum_thread_id").and_then(Value::as_u64);
    let memory_key = research_cycle_text(args, "memory_key");
    let requested_actions = research_cycle_requested_actions(args);

    let mut blockers = Vec::<Value>::new();
    if hypothesis.is_empty() {
        blockers.push(json!("hypothesis_missing"));
    }
    if source_anchors.is_empty() {
        blockers.push(json!("source_anchors_missing"));
    }
    if proposed_experiment.is_empty() {
        blockers.push(json!("proposed_experiment_missing"));
    }
    if experiment_command.is_empty() {
        blockers.push(json!("experiment_command_missing"));
    }
    if evidence_summary.is_empty() {
        blockers.push(json!("evidence_summary_missing"));
    }
    if reproducibility_handle.is_empty() {
        blockers.push(json!("reproducibility_handle_missing"));
    }
    if falsifier.is_empty() {
        blockers.push(json!("falsifier_missing"));
    }
    if requested_actions
        .iter()
        .any(|a| a.contains("execute") || a.contains("run_code") || a.contains("spawn"))
    {
        blockers.push(json!("execution_not_authorized"));
    }
    if requested_actions
        .iter()
        .any(|a| a.contains("write_memory") || a.contains("memory_save") || a.contains("ingest"))
    {
        blockers.push(json!("memory_write_not_authorized"));
    }
    if requested_actions
        .iter()
        .any(|a| a.contains("manuscript") || a.contains("paper_generation"))
    {
        blockers.push(json!("manuscript_generation_not_authorized"));
    }

    let status = if blockers.is_empty() {
        "ready_for_human_review"
    } else {
        "planned_needs_evidence"
    };
    let mut actions = Vec::new();
    let mut rank = 1u32;
    if blockers.is_empty() {
        actions.push(research_cycle_action(
            rank,
            "publish_review_packet_to_forum",
            "Evidence handles are present; the next step is human-readable review, not automatic ingestion.",
            true,
        ));
        rank += 1;
        actions.push(research_cycle_action(
            rank,
            "await_owner_memory_ingest_decision",
            "Durable AB memory should only receive accepted conclusions after owner/reviewer approval.",
            false,
        ));
    } else {
        actions.push(research_cycle_action(
            rank,
            "capture_missing_evidence",
            "The plan is advisory until source, command, evidence, reproducibility, and falsifier handles are complete.",
            false,
        ));
        rank += 1;
        actions.push(research_cycle_action(
            rank,
            "post_blockers_for_review",
            "Visible blockers keep speculative research branches from becoming durable claims.",
            true,
        ));
    }
    actions.push(research_cycle_action(
        actions.len() as u32 + 1,
        "keep_execution_in_separate_authorized_lane",
        "This v0 packet borrows research-loop structure without executing LLM-written code or generating manuscripts.",
        false,
    ));

    json!({
        "schema": "agent_bridge.research_cycle.plan.v0",
        "source_pattern": "ai_scientist_v2_research_loop",
        "inspired_by": {
            "paper": "Towards end-to-end automation of AI research",
            "doi": "10.1038/s41586-026-10265-5",
            "repo": "https://github.com/SakanaAI/AI-Scientist-v2",
            "borrowed_pattern": "staged research lifecycle with experiment journal and advisory review",
            "code_reuse": false,
            "license_review_required_for_code_reuse": true,
        },
        "inputs": {
            "research_question": research_question,
            "hypothesis": hypothesis,
            "source_anchors": source_anchors,
            "source_anchor_count": source_anchors.len(),
            "proposed_experiment": proposed_experiment,
            "experiment_command": experiment_command,
            "evidence_summary": evidence_summary,
            "reproducibility_handle": reproducibility_handle,
            "expected_artifact": expected_artifact,
            "falsifier": falsifier,
            "owner": owner,
            "reviewer": reviewer,
            "forum_thread_id": forum_thread_id,
            "memory_key": memory_key,
        },
        "research_tree": {
            "mode": "single_root_first_branch_v0",
            "autonomous_branching": false,
            "root": {
                "id": "root",
                "kind": "hypothesis",
                "status": status,
                "question_present": !research_question.is_empty(),
                "hypothesis_present": !hypothesis.is_empty(),
                "source_anchor_count": source_anchors.len(),
            },
            "candidate_branches": [
                {
                    "id": "branch_001",
                    "kind": "proposed_experiment",
                    "status": status,
                    "requires_human_review": true,
                    "may_execute_from_this_packet": false,
                }
            ],
        },
        "evidence_contract": {
            "requires_source_anchors": true,
            "requires_experiment_command": true,
            "requires_evidence_summary": true,
            "requires_reproducibility_handle": true,
            "requires_falsifier": true,
            "negative_results_policy": "negative_results_are_evidence_and_may_close_or_reframe_the_branch",
            "claims_without_evidence_allowed": false,
        },
        "review_contract": {
            "review_is_advisory": true,
            "critic_dimensions": [
                "novelty",
                "method",
                "implementation_correctness",
                "evidence_strength",
                "safety_and_license",
                "memory_ingest_readiness"
            ],
            "human_review_required": true,
        },
        "gates": {
            "may_execute": false,
            "may_spawn_agents": false,
            "may_write_memory": false,
            "may_write_forum": false,
            "may_generate_manuscript": false,
            "may_change_runtime_policy": false,
            "requires_owner_review_before_ingest": true,
        },
        "tool_activity": {
            "calls_memory_search": false,
            "writes_memory": false,
            "writes_forum": false,
            "spawns_agents": false,
            "executes_commands": false,
            "imports_external_code": false,
        },
        "guardrails": {
            "read_only_packet": true,
            "does_not_call_memory_search": true,
            "does_not_write_memory": true,
            "does_not_spawn_agents": true,
            "does_not_execute_commands": true,
            "does_not_generate_manuscripts": true,
            "does_not_reopen_parked_embedding_runtime": true,
        },
        "blockers": blockers,
        "recommended_next_actions": actions,
    })
}

#[async_trait]
impl McpTool for ResearchCyclePlanTool {
    fn name(&self) -> &'static str {
        "research_cycle_plan"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Read-only/advisory research-cycle planning packet inspired by AI \
                 Scientist-v2's staged research loop. It structures a hypothesis, source \
                 anchors, experiment evidence handles, review contract, blockers, and \
                 owner-gated memory-ingest posture. It never searches memory, writes memory \
                 or forum posts, spawns agents, executes commands, imports external code, \
                 generates manuscripts, or changes runtime policy."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "research_question": { "type": "string" },
                    "hypothesis": { "type": "string" },
                    "source_anchors": {
                        "oneOf": [
                            { "type": "array", "items": { "type": "string" } },
                            { "type": "string" }
                        ],
                        "description": "URLs, memory keys, forum posts, commits, or file paths that anchor the claim."
                    },
                    "proposed_experiment": { "type": "string" },
                    "experiment_command": {
                        "type": "string",
                        "description": "Command that would verify the experiment in a separate authorized lane. This tool does not run it."
                    },
                    "evidence_summary": { "type": "string" },
                    "reproducibility_handle": { "type": "string" },
                    "expected_artifact": { "type": "string" },
                    "falsifier": { "type": "string" },
                    "owner": { "type": "string" },
                    "reviewer": { "type": "string" },
                    "forum_thread_id": { "type": "integer" },
                    "memory_key": { "type": "string" },
                    "requested_actions": {
                        "type": "array",
                        "items": { "type": "string" },
                        "description": "Optional requested actions; execution/write/manuscript requests are reported as blockers, never performed."
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        Ok(ToolResult::json_text(&build_research_cycle_plan(&args)))
    }
}

// ===========================================================================
//        context_governor_snapshot - read-only lifecycle decision packet
// ===========================================================================

pub struct ContextGovernorSnapshotTool;

impl ContextGovernorSnapshotTool {
    pub fn new() -> Self {
        Self
    }
}

impl Default for ContextGovernorSnapshotTool {
    fn default() -> Self {
        Self::new()
    }
}

fn context_governor_action(
    rank: u32,
    action: &str,
    reason: &str,
    effect: &str,
    mutation: bool,
) -> Value {
    json!({
        "rank": rank,
        "action": action,
        "reason": reason,
        "effect": effect,
        "requires_separate_tool_call": mutation,
        "snapshot_mutates_state": false,
    })
}

fn context_governor_suggested_actions(tier: &str, confidence: &str) -> Vec<Value> {
    let mut actions = Vec::new();
    let mut rank = 1u32;

    if confidence == "low" {
        actions.push(context_governor_action(
            rank,
            "provide_text_sample_before_aggressive_pruning",
            "No text_sample was provided, so the pressure estimate is turn-count based.",
            "Improves confidence before deciding to handoff, compact, or reduce context.",
            false,
        ));
        rank += 1;
    }

    match tier {
        "fresh" => {
            actions.push(context_governor_action(
                rank,
                "continue_current_flow",
                "Context pressure is below the first fatigue band.",
                "No lifecycle intervention is needed yet.",
                false,
            ));
            rank += 1;
            actions.push(context_governor_action(
                rank,
                "use_semantic_bootstrap_on_scope_shift",
                "If the task changes topic, retrieve by task query instead of carrying broad prior context.",
                "Keeps down-slide injection relevant.",
                true,
            ));
        }
        "engaged" => {
            actions.push(context_governor_action(
                rank,
                "save_active_work_memory_before_long_branch",
                "The session has meaningful pressure but is not near the urgent band.",
                "Preserves active state outside the model window before expanding scope.",
                true,
            ));
            rank += 1;
            actions.push(context_governor_action(
                rank,
                "prefer_targeted_retrieval",
                "Avoid reloading broad transcripts or large file dumps when scoped lookup will do.",
                "Reduces avoidable context growth.",
                false,
            ));
        }
        "strained" => {
            actions.push(context_governor_action(
                rank,
                "save_work_memory_now",
                "Context pressure is in the strained band.",
                "Captures active files, hypothesis, evidence, and next step before compaction risk.",
                true,
            ));
            rank += 1;
            actions.push(context_governor_action(
                rank,
                "prepare_handoff_or_compaction_point",
                "Further broad exploration risks losing relevant state to lossy compaction.",
                "Creates a deliberate boundary before continuing.",
                true,
            ));
            rank += 1;
            actions.push(context_governor_action(
                rank,
                "avoid_broad_context_injection",
                "Large unfiltered snippets are the main controllable growth source.",
                "Use semantic memory_search/session_bootstrap query and short snippets.",
                false,
            ));
        }
        "saturated" => {
            actions.push(context_governor_action(
                rank,
                "stop_expanding_current_thread",
                "Context pressure is at or past the saturation band.",
                "Prevents more work from entering a low-reliability window.",
                false,
            ));
            rank += 1;
            actions.push(context_governor_action(
                rank,
                "save_work_memory_and_handoff",
                "The active task state should be externalized before more tool output is added.",
                "Preserves recoverable state for a fresh window.",
                true,
            ));
            rank += 1;
            actions.push(context_governor_action(
                rank,
                "run_precompact_or_session_finalize",
                "A lifecycle boundary is safer than continuing with an overloaded transcript.",
                "Lets existing curate/finalize paths extract durable lessons and decisions.",
                true,
            ));
        }
        _ => {
            actions.push(context_governor_action(
                rank,
                "inspect_context_pressure",
                "Unknown fatigue tier returned by the estimator.",
                "Treat this as diagnostic-only and avoid automatic pruning.",
                false,
            ));
        }
    }

    actions.push(context_governor_action(
        actions.len() as u32 + 1,
        "keep_or_verify_lean_tool_surface",
        "Eager clients pay for exposed tool schemas every request.",
        "Keep codex-lean or run a measured A/B before widening the toolset.",
        false,
    ));

    actions
}

fn build_context_governor_snapshot(args: &Value) -> Value {
    let cwd = args
        .get("cwd")
        .and_then(|v| v.as_str())
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(str::to_string)
        .or_else(|| {
            std::env::current_dir()
                .ok()
                .map(|p| p.display().to_string())
        })
        .unwrap_or_else(|| "/".to_string());
    let model_default = std::env::var("AGENT_BRIDGE_MODEL").unwrap_or_else(|_| "gpt-5.5".into());
    let model = args
        .get("model")
        .and_then(|v| v.as_str())
        .filter(|s| !s.trim().is_empty())
        .unwrap_or(&model_default);
    let turns = args
        .get("conversation_turns")
        .and_then(|v| v.as_u64())
        .unwrap_or(0);
    let text_raw = args
        .get("text_sample")
        .and_then(|v| v.as_str())
        .unwrap_or("");
    let text_sample_provided = !text_raw.is_empty();
    let explicit_window = args
        .get("context_window")
        .or_else(|| args.get("model_limit"))
        .and_then(|v| v.as_u64());
    let (limit, limit_source) =
        resolve_context_window(explicit_window, env_context_window(), model);
    let estimated = estimated_usage_tokens(text_raw, turns);
    let pct_raw = if limit == 0 {
        0.0
    } else {
        (estimated as f64 / limit as f64) * 100.0
    };
    let pct_used = (pct_raw * 10.0).round() / 10.0;
    let tier = fatigue_tier(pct_raw);
    let recommendation = budget_recommendation(pct_raw);
    let soft_trigger = (limit as f64 * 0.80) as u64;
    let distance_to_compaction = soft_trigger.saturating_sub(estimated);
    let confidence = if text_sample_provided { "high" } else { "low" };
    let long_context_beta_possible =
        limit_source == "model_default" && model_supports_1m_beta(model);

    let toolset_env = std::env::var("AGENT_BRIDGE_TOOLSET").ok();
    let client_env = std::env::var("AGENT_BRIDGE_CLIENT").ok();
    let source_env = std::env::var("AGENT_BRIDGE_MCP_SOURCE").ok();
    let profile_env = std::env::var("AGENT_BRIDGE_TOOL_PROFILE").ok();
    let policy = ToolPolicy::from_values(
        toolset_env.as_deref(),
        client_env.as_deref(),
        source_env.as_deref(),
        profile_env.as_deref(),
    );
    // Reality view: the governor sizes the surface this process actually serves.
    let exposed_tool_count = exposed_tool_count_current(
        toolset_env.as_deref(),
        client_env.as_deref(),
        profile_env.as_deref(),
    );

    json!({
        "schema": "agent_bridge.context_governor.snapshot.v0",
        "cwd": cwd,
        "direct_model_context_pruning": {
            "supported": false,
            "reason": "Agent-Bridge cannot delete or reorder content already admitted to the host model window. It governs lifecycle inputs, saved scratch state, bootstrap recall, and tool-surface size around the host."
        },
        "pressure": {
            "model_hint": model,
            "model_limit": limit,
            "model_limit_source": limit_source,
            "long_context_beta_possible": long_context_beta_possible,
            "estimated_tokens_used": estimated,
            "pct_used": pct_used,
            "fatigue_tier": tier,
            "recommendation": recommendation,
            "distance_to_compaction_tokens": distance_to_compaction,
            "soft_trigger_pct": 80,
            "text_sample_provided": text_sample_provided,
            "text_sample_chars": text_raw.chars().count(),
            "text_sample_tokens_estimate": estimate_tokens_from_text(text_raw),
            "confidence": confidence,
            "heuristic_note": "Offline estimate only; pass text_sample for higher confidence on tool-heavy sessions."
        },
        "controls": {
            "toolset": policy.label(),
            "tool_profile": policy.profile().label(),
            "toolset_env": toolset_env,
            "tool_profile_env": profile_env,
            "client_env": client_env,
            "source_env": source_env,
            "exposed_tool_count": exposed_tool_count,
            "surfaces": [
                {
                    "name": "work_memory",
                    "role": "short-lived active task scratchpad outside model context",
                    "mutation_requires_separate_tool": true
                },
                {
                    "name": "session_bootstrap",
                    "role": "bounded down-slide recall with per-block budgets and optional semantic query",
                    "mutation_requires_separate_tool": false
                },
                {
                    "name": "session_lifecycle_step(precompact)",
                    "role": "pre-compaction capture plus curate/finalize path",
                    "mutation_requires_separate_tool": true
                },
                {
                    "name": "codex-lean",
                    "role": "eager tool-schema surface reduction for Codex-like clients",
                    "mutation_requires_separate_tool": false
                }
            ]
        },
        "suggested_actions": context_governor_suggested_actions(tier, confidence),
        "guardrails": {
            "snapshot_is_read_only": true,
            "does_not_write_memory": true,
            "does_not_compact_session": true,
            "does_not_change_tool_profile": true,
            "does_not_execute_remote_code": true
        }
    })
}

#[async_trait]
impl McpTool for ContextGovernorSnapshotTool {
    fn name(&self) -> &'static str {
        "context_governor_snapshot"
    }
    fn annotations(&self) -> Option<ToolAnnotations> {
        Some(ToolAnnotations::read_only())
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Read-only context lifecycle governor snapshot. Estimates context \
                 pressure, reports what Agent-Bridge can and cannot govern, and returns \
                 ranked lifecycle actions such as saving work_memory, using targeted \
                 bootstrap recall, or preparing handoff/compaction. It never mutates memory, \
                 compacts a session, changes tool exposure, or claims to prune live model \
                 context."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "cwd": { "type": "string", "description": "Project path for scoping. Defaults to current directory." },
                    "model": {
                        "type": "string",
                        "description": "Model name hint for context window size. Defaults to AGENT_BRIDGE_MODEL, then gpt-5.5."
                    },
                    "context_window": {
                        "type": "integer",
                        "minimum": 1,
                        "description": "Explicit context-window size in tokens; overrides AGENT_BRIDGE_CONTEXT_WINDOW and model default."
                    },
                    "conversation_turns": {
                        "type": "integer",
                        "minimum": 0,
                        "default": 0,
                        "description": "Coarse turn count when transcript text is unavailable."
                    },
                    "text_sample": {
                        "type": "string",
                        "description": "Optional recent transcript or excerpt for higher-confidence token estimation."
                    },
                    "compact": {
                        "type": "boolean",
                        "description": "Reserved for future compact projection; v0 always returns the full JSON packet."
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        Ok(ToolResult::json_text(&build_context_governor_snapshot(
            &args,
        )))
    }
}

// ===========================================================================
//        tool_call_attention_report — L6 P2 metacognition probe
// ===========================================================================

/// L6 P2 — Result of `tool_call_attention_report`. Pure data; the
/// MCP tool wraps this in a JSON response. Exposed `pub` (not just
/// crate-local) so cron jobs and integration tests can use the same
/// aggregator from outside this module.
#[derive(Debug, serde::Serialize)]
pub struct AttentionReport {
    pub window_secs: i64,
    pub high_yield_threshold_bytes: u32,
    pub followup_window_secs: i64,
    pub total_calls: usize,
    pub high_yield_calls: usize,
    pub followed_up_calls: usize,
    pub ignored_calls: usize,
    pub followed_up_ratio: f64,
    pub ignored: Vec<AttentionIgnoredRow>,
    pub top_yield: Vec<AttentionYieldRow>,
}

#[derive(Debug, serde::Serialize)]
pub struct AttentionIgnoredRow {
    pub ts: i64,
    pub tool_name: String,
    pub result_size: u32,
}

#[derive(Debug, serde::Serialize)]
pub struct AttentionYieldRow {
    pub ts: i64,
    pub tool_name: String,
    pub result_size: u32,
    pub followed_up: bool,
}

/// **L6 P2** — pure aggregator for the attention report.
///
/// Given a chronologically-sorted `calls` vector + thresholds, returns
/// a structured report. Pure for testability; the MCP tool wires this
/// to live store data.
///
/// Heuristic for "follow-up": after a high-yield call at time `t`, did
/// ANY other tool call appear in the same call list within
/// `followup_window_secs`? This is a structural proxy for "the agent
/// did something after seeing the result"; it doesn't prove the result
/// was *used*, but a missing follow-up strongly suggests the result
/// was ignored.
pub fn compute_attention_report(
    calls: &[ab_store::McpToolCallRow],
    window_secs: i64,
    high_yield_threshold_bytes: u32,
    followup_window_secs: i64,
) -> AttentionReport {
    // Filter to high-yield successful calls (errors are pre-filtered out
    // by spec: ignored-but-failed is a different signal).
    let high_yield: Vec<&ab_store::McpToolCallRow> = calls
        .iter()
        .filter(|c| c.ok)
        .filter(|c| {
            c.result_size
                .map(|s| s >= high_yield_threshold_bytes)
                .unwrap_or(false)
        })
        .collect();

    let mut followed_up_count = 0usize;
    let mut ignored: Vec<AttentionIgnoredRow> = Vec::new();
    let mut top_yield_rows: Vec<AttentionYieldRow> = Vec::new();

    for hy in &high_yield {
        // Did any DIFFERENT call (different ts OR different tool name)
        // appear in (hy.ts, hy.ts + followup_window_secs]? "Different"
        // protects against the same call counting itself when ts ties.
        let cutoff_end = hy.ts + followup_window_secs;
        let has_followup = calls.iter().any(|c| {
            c.ts > hy.ts && c.ts <= cutoff_end && (c.ts != hy.ts || c.tool_name != hy.tool_name)
        });
        let result_size = hy.result_size.unwrap_or(0);
        if has_followup {
            followed_up_count += 1;
        } else {
            ignored.push(AttentionIgnoredRow {
                ts: hy.ts,
                tool_name: hy.tool_name.clone(),
                result_size,
            });
        }
        top_yield_rows.push(AttentionYieldRow {
            ts: hy.ts,
            tool_name: hy.tool_name.clone(),
            result_size,
            followed_up: has_followup,
        });
    }

    // Sort top_yield by result_size DESC (most ROI-bearing first); take
    // top 20 for the report payload.
    top_yield_rows.sort_by(|a, b| b.result_size.cmp(&a.result_size));
    top_yield_rows.truncate(20);
    // Sort ignored by result_size DESC — biggest unused payload first.
    ignored.sort_by(|a, b| b.result_size.cmp(&a.result_size));
    ignored.truncate(20);

    let total = high_yield.len();
    let followed_up_ratio = if total == 0 {
        0.0
    } else {
        followed_up_count as f64 / total as f64
    };

    AttentionReport {
        window_secs,
        high_yield_threshold_bytes,
        followup_window_secs,
        total_calls: calls.len(),
        high_yield_calls: total,
        followed_up_calls: followed_up_count,
        ignored_calls: total - followed_up_count,
        followed_up_ratio,
        ignored,
        top_yield: top_yield_rows,
    }
}

/// L6 P2 — MCP tool that surfaces the attention report.
pub struct ToolCallAttentionReportTool {
    hub: Hub,
}

impl ToolCallAttentionReportTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for ToolCallAttentionReportTool {
    fn name(&self) -> &'static str {
        "tool_call_attention_report"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "L6 P2 metacognition probe — for the recent window, \
                 summarize which high-yield (≥N bytes result) tool calls had \
                 follow-up activity within K seconds (proxy for 'I used the \
                 answer') vs which had none (proxy for 'I asked for X then \
                 ignored the answer'). Backed by mcp_tool_calls telemetry; \
                 no LLM, no transcript access. Tuning targets: \
                 `high_yield_threshold_bytes` (default 2500 ≈ 10KB) + \
                 `followup_window_secs` (default 600 = 10min)."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "window_secs": {
                        "type": "integer",
                        "minimum": 60,
                        "maximum": 86400,
                        "default": 7200,
                        "description": "Lookback for tool-call telemetry. Default 7200s (2h ≈ recent session)."
                    },
                    "high_yield_threshold_bytes": {
                        "type": "integer",
                        "minimum": 100,
                        "default": 2500,
                        "description": "result_size >= this is considered high-yield (worth following up on)."
                    },
                    "followup_window_secs": {
                        "type": "integer",
                        "minimum": 30,
                        "maximum": 3600,
                        "default": 600,
                        "description": "After a high-yield call, look for ANY other call within this window. None → 'ignored'."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let window_secs = args
            .get("window_secs")
            .and_then(|v| v.as_i64())
            .unwrap_or(7200)
            .clamp(60, 86_400);
        let threshold = args
            .get("high_yield_threshold_bytes")
            .and_then(|v| v.as_u64())
            .unwrap_or(2500)
            .min(u32::MAX as u64) as u32;
        let followup = args
            .get("followup_window_secs")
            .and_then(|v| v.as_i64())
            .unwrap_or(600)
            .clamp(30, 3600);

        // Fetch row-level telemetry. Cap at 2000 to bound report cost
        // even on noisy sessions; matches the trait's hard cap.
        let calls = match store.recent_mcp_tool_calls(window_secs, 2000).await {
            Ok(c) => c,
            Err(e) => {
                return Ok(ToolResult::error(format!(
                    "recent_mcp_tool_calls failed: {e}"
                )));
            }
        };

        let report = compute_attention_report(&calls, window_secs, threshold, followup);
        let payload = serde_json::to_value(&report).unwrap_or_else(|_| json!({}));
        Ok(ToolResult::json_text(&payload))
    }
}

// ===========================================================================
//        practical_workflow_scorecard — product continuity outcomes
// ===========================================================================

#[derive(Debug, serde::Serialize, PartialEq)]
pub struct PracticalWorkflowScorecard {
    pub schema_version: u32,
    pub read_only: bool,
    pub window_secs: i64,
    pub total_calls: usize,
    pub successful_calls: usize,
    pub failed_calls: usize,
    pub continuation: PracticalContinuationMetrics,
    pub completion: PracticalCompletionMetrics,
    pub recovery: PracticalRecoveryMetrics,
    pub coordination: PracticalCoordinationMetrics,
    pub operator_burden: PracticalOperatorBurdenMetrics,
    pub recommendations: Vec<String>,
}

#[derive(Debug, serde::Serialize, PartialEq)]
pub struct PracticalContinuationMetrics {
    /// All successful `session_bootstrap` calls, including lifecycle hooks.
    pub bootstrap_calls: usize,
    /// Non-interactive hook bootstraps retained in telemetry but excluded from
    /// continuation metrics.
    pub excluded_hook_bootstraps: usize,
    /// Bootstrap calls whose source can represent an interactive workflow.
    pub continuation_candidate_bootstraps: usize,
    pub attributed_bootstrap_calls: usize,
    pub legacy_unattributed_bootstraps: usize,
    pub eligible_bootstrap_calls: usize,
    pub right_censored_bootstraps: usize,
    pub bootstraps_with_followup: usize,
    pub eligible_bootstraps_without_followup: usize,
    pub followup_rate: Option<f64>,
    pub median_followup_secs: Option<i64>,
    pub interpretation: &'static str,
}

#[derive(Debug, serde::Serialize, PartialEq)]
pub struct PracticalCompletionMetrics {
    pub finalize_signals: usize,
    pub plan_update_signals: usize,
    pub interpretation: &'static str,
}

#[derive(Debug, serde::Serialize, PartialEq)]
pub struct PracticalRecoveryMetrics {
    pub failed_calls: usize,
    pub failures_followed_by_success: usize,
    pub repeated_failure_loops: usize,
    pub repeated_failure_tools: std::collections::BTreeMap<String, usize>,
    pub interpretation: &'static str,
}

#[derive(Debug, serde::Serialize, PartialEq)]
pub struct PracticalCoordinationMetrics {
    pub calls: usize,
    pub ratio: Option<f64>,
    pub forum_reads: usize,
    pub forum_posts: usize,
    pub memory_saves: usize,
    pub capability_checks: usize,
    pub context_snapshots: usize,
    pub interpretation: &'static str,
}

#[derive(Debug, serde::Serialize, PartialEq)]
pub struct PracticalOperatorBurdenMetrics {
    pub repeated_authorization_prompts: Option<usize>,
    pub manual_interventions: Option<usize>,
    pub instrumentation_status: &'static str,
    pub interpretation: &'static str,
}

pub fn compute_practical_workflow_scorecard(
    calls: &[ab_store::McpToolCallRow],
    window_secs: i64,
    followup_window_secs: i64,
    as_of_ts: i64,
) -> PracticalWorkflowScorecard {
    let successful_calls = calls.iter().filter(|call| call.ok).count();
    let failed_calls = calls.len().saturating_sub(successful_calls);
    let all_bootstraps: Vec<_> = calls
        .iter()
        .filter(|call| call.ok && call.tool_name == "session_bootstrap")
        .collect();
    let excluded_hook_bootstraps = all_bootstraps
        .iter()
        .filter(|bootstrap| bootstrap.source.as_deref() == Some("hook"))
        .count();
    let bootstraps: Vec<_> = all_bootstraps
        .iter()
        .copied()
        .filter(|bootstrap| bootstrap.source.as_deref() != Some("hook"))
        .collect();
    let attributed_bootstraps: Vec<_> = bootstraps
        .iter()
        .copied()
        .filter(|bootstrap| bootstrap.mcp_session_id.is_some())
        .collect();
    let legacy_unattributed_bootstraps = bootstraps
        .len()
        .saturating_sub(attributed_bootstraps.len());
    let eligibility_cutoff = as_of_ts.saturating_sub(followup_window_secs);
    let eligible_bootstraps: Vec<_> = attributed_bootstraps
        .iter()
        .copied()
        .filter(|bootstrap| bootstrap.ts <= eligibility_cutoff)
        .collect();
    let right_censored_bootstraps = attributed_bootstraps
        .len()
        .saturating_sub(eligible_bootstraps.len());
    let mut followup_latencies = Vec::new();
    for bootstrap in &eligible_bootstraps {
        if let Some(next) = calls.iter().find(|call| {
            call.ok
                && call.id > bootstrap.id
                && call.ts <= bootstrap.ts.saturating_add(followup_window_secs)
                && call.mcp_session_id == bootstrap.mcp_session_id
                && !matches!(
                    call.tool_name.as_str(),
                    "session_bootstrap" | "practical_workflow_scorecard"
                )
        }) {
            followup_latencies.push(next.ts.saturating_sub(bootstrap.ts));
        }
    }
    followup_latencies.sort_unstable();
    let median_followup_secs = if followup_latencies.is_empty() {
        None
    } else {
        Some(followup_latencies[followup_latencies.len() / 2])
    };
    let followup_rate = if eligible_bootstraps.is_empty() {
        None
    } else {
        Some(followup_latencies.len() as f64 / eligible_bootstraps.len() as f64)
    };
    let eligible_bootstraps_without_followup = eligible_bootstraps
        .len()
        .saturating_sub(followup_latencies.len());

    let failures: Vec<_> = calls
        .iter()
        .enumerate()
        .filter(|(_, call)| !call.ok)
        .collect();
    let failures_followed_by_success = failures
        .iter()
        .filter(|(index, failure)| {
            calls[index.saturating_add(1)..].iter().any(|call| {
                call.ok && call.ts <= failure.ts.saturating_add(followup_window_secs)
            })
        })
        .count();
    let mut repeated_failure_tools = std::collections::BTreeMap::new();
    for pair in failures.windows(2) {
        if pair[0].1.tool_name == pair[1].1.tool_name
            && pair[1].1.ts.saturating_sub(pair[0].1.ts) <= 300
        {
            *repeated_failure_tools
                .entry(pair[1].1.tool_name.clone())
                .or_insert(0) += 1;
        }
    }
    let repeated_failure_loops = repeated_failure_tools.values().sum();

    let count_tool = |name: &str| calls.iter().filter(|call| call.tool_name == name).count();
    let forum_reads = count_tool("forum_read");
    let forum_posts = count_tool("forum_post");
    let memory_saves = count_tool("memory_save");
    let capability_checks = count_tool("capabilities");
    let context_snapshots = count_tool("context_governor_snapshot");
    let coordination_calls = forum_reads
        .saturating_add(forum_posts)
        .saturating_add(memory_saves)
        .saturating_add(capability_checks)
        .saturating_add(context_snapshots);
    let coordination_ratio = if calls.is_empty() {
        None
    } else {
        Some(coordination_calls as f64 / calls.len() as f64)
    };

    let mut recommendations = Vec::new();
    if bootstraps.is_empty() && excluded_hook_bootstraps > 0 {
        recommendations.push("Only non-interactive hook bootstraps were observed in this window; wait for an interactive MCP bootstrap before judging continuation.".into());
    } else if bootstraps.is_empty() {
        recommendations.push("No bootstrap signal in this window; widen the window before judging continuation.".into());
    } else if attributed_bootstraps.is_empty() {
        recommendations.push("No attributed bootstrap is available yet; reconnect or start a current MCP process before judging same-session continuation.".into());
    } else if eligible_bootstraps_without_followup > 0 {
        recommendations.push("Inspect eligible MCP sessions without a successful same-session follow-up inside the selected recovery window.".into());
    }
    if right_censored_bootstraps > 0 {
        recommendations.push("Re-run after the follow-up window closes before judging right-censored recent bootstraps.".into());
    }
    if legacy_unattributed_bootstraps > 0 {
        recommendations.push("Historical pre-attribution bootstraps are reported as legacy and excluded from the same-session rate.".into());
    }
    if repeated_failure_loops > 0 {
        recommendations.push("Inspect repeated same-tool failures before retrying or requesting authorization again.".into());
    }
    if calls.len() >= 20 && coordination_calls.saturating_mul(5) >= calls.len().saturating_mul(2)
    {
        recommendations.push("At least two in five observed calls are workflow coordination (forum read/post, memory save, capability checks, or context snapshots); inspect repeated gates and keep only milestone coordination.".into());
    }
    recommendations.push("Authorization prompts and manual interventions are not present in MCP telemetry; keep them explicitly unavailable instead of estimating them.".into());

    PracticalWorkflowScorecard {
        schema_version: 5,
        read_only: true,
        window_secs,
        total_calls: calls.len(),
        successful_calls,
        failed_calls,
        continuation: PracticalContinuationMetrics {
            bootstrap_calls: all_bootstraps.len(),
            excluded_hook_bootstraps,
            continuation_candidate_bootstraps: bootstraps.len(),
            attributed_bootstrap_calls: attributed_bootstraps.len(),
            legacy_unattributed_bootstraps,
            eligible_bootstrap_calls: eligible_bootstraps.len(),
            right_censored_bootstraps,
            bootstraps_with_followup: followup_latencies.len(),
            eligible_bootstraps_without_followup,
            followup_rate,
            median_followup_secs,
            interpretation: "A successful call from the same random MCP-process session after a non-hook bootstrap is a continuation proxy, not proof that recalled context was correct. Non-interactive hook bootstraps, legacy unattributed candidates, and recent right-censored candidates are excluded from the rate.",
        },
        completion: PracticalCompletionMetrics {
            finalize_signals: calls
                .iter()
                .filter(|call| call.ok && call.tool_name == "session_finalize")
                .count(),
            plan_update_signals: calls
                .iter()
                .filter(|call| call.ok && call.tool_name == "plan_update")
                .count(),
            interpretation: "Finalize and plan-update calls are completion signals; MCP telemetry cannot prove the user goal was achieved.",
        },
        recovery: PracticalRecoveryMetrics {
            failed_calls,
            failures_followed_by_success,
            repeated_failure_loops,
            repeated_failure_tools,
            interpretation: "A later successful call is a recovery proxy; repeated same-tool failures within five minutes flag a retry loop. Tool counts identify where to inspect without exposing arguments or error text.",
        },
        coordination: PracticalCoordinationMetrics {
            calls: coordination_calls,
            ratio: coordination_ratio,
            forum_reads,
            forum_posts,
            memory_saves,
            capability_checks,
            context_snapshots,
            interpretation: "Coordination calls keep work aligned, but a sustained majority suggests process overhead is crowding out task execution. The ratio is descriptive and does not judge individual call value.",
        },
        operator_burden: PracticalOperatorBurdenMetrics {
            repeated_authorization_prompts: None,
            manual_interventions: None,
            instrumentation_status: "unavailable",
            interpretation: "Codex-native approval prompts and out-of-band operator actions are outside Agent-Bridge MCP telemetry.",
        },
        recommendations,
    }
}

pub struct PracticalWorkflowScorecardTool {
    hub: Hub,
}

impl PracticalWorkflowScorecardTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for PracticalWorkflowScorecardTool {
    fn name(&self) -> &'static str {
        "practical_workflow_scorecard"
    }

    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Read-only practical continuity scorecard over existing MCP telemetry. Reports anonymous same-MCP-session bootstrap follow-up, right-censoring, legacy attribution coverage, completion signals, failure recovery and retry loops. Authorization prompts and manual interventions stay explicitly unavailable because Codex-native UI events are not in this telemetry.".into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "window_secs": {
                        "type": "integer", "minimum": 60, "maximum": 2592000,
                        "default": 604800,
                        "description": "Telemetry lookback. Default 7 days."
                    },
                    "followup_window_secs": {
                        "type": "integer", "minimum": 30, "maximum": 3600,
                        "default": 600,
                        "description": "Window for bootstrap continuation and failure recovery proxies."
                    }
                }
            }),
        }
    }

    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(store) => store.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let window_secs = args
            .get("window_secs")
            .and_then(Value::as_i64)
            .unwrap_or(604_800)
            .clamp(60, 2_592_000);
        let followup_window_secs = args
            .get("followup_window_secs")
            .and_then(Value::as_i64)
            .unwrap_or(600)
            .clamp(30, 3_600);
        let calls = match store.recent_mcp_tool_calls(window_secs, 2_000).await {
            Ok(calls) => calls,
            Err(error) => return Ok(ToolResult::error(format!("recent_mcp_tool_calls: {error}"))),
        };
        let report = compute_practical_workflow_scorecard(
            &calls,
            window_secs,
            followup_window_secs,
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|duration| duration.as_secs().min(i64::MAX as u64) as i64)
                .unwrap_or(0),
        );
        let payload = serde_json::to_value(&report).unwrap_or_else(|_| json!({}));
        Ok(ToolResult::json_text(&payload))
    }
}

// ===========================================================================
//        embed_text — Phase 2.1 raw encoder exposure for external apps
// ===========================================================================

/// Pure helper — pick raw inner encoder per Phase 2.1 precedence,
/// independent of `ab_store::default_backend()` (which may be wrapped
/// by `SeedBackend` when v22 substrate is installed; here we want raw
/// encoder output — gte-multilingual-base 768-d by default since the
/// 2026-06-26 default flip — with no substrate perception side effect).
///
/// Mirrors `seed_bridge::select_inner_kind()` so wrap and raw paths
/// agree on which encoder produces the vectors.
fn select_raw_encoder_kind() -> String {
    std::env::var("AGENT_BRIDGE_EMBED_BACKEND")
        .ok()
        .map(|s| s.to_lowercase())
        .filter(|s| s == "hash" || s == "onnx")
        .unwrap_or_else(|| "onnx".to_string())
}

fn build_raw_encoder() -> Arc<dyn ab_store::EmbeddingBackend> {
    // If embedding delegation is active in THIS process, the raw encoder
    // delegates too — the shared /embed service is itself a raw encoder (no
    // substrate wrapping), so `embed_text` doesn't load a local ~2.8GB model in
    // a delegating MCP. Role-safe: `active_remote_url()` is set only by the MCP
    // startup path, never in daemon / daemon-http, so this can't self-loop into
    // the daemon's own /embed. Falls back to a local load if the daemon is down.
    if let Some(url) = crate::remote_embed::active_remote_url() {
        return Arc::new(crate::remote_embed::RemoteEmbedBackend::new(url));
    }
    match select_raw_encoder_kind().as_str() {
        "hash" => Arc::new(ab_store::HashBackend),
        // "onnx" or fallthrough — OnnxBackend carries its own hash
        // fallback on model-load failure, so unknown values are
        // safe-by-default.
        _ => Arc::new(ab_store::OnnxBackend),
    }
}

/// **Phase 2.1 / onsen-hd integration** — `embed_text` MCP tool.
///
/// Exposes the raw inner sentence encoder (`gte-multilingual-base` 768-d
/// via `fastembed` by default, hash fallback on model-load failure) so
/// external apps can build their own grids / indexes without touching v22
/// substrate state. Companion HTTP route `POST /embed` ships on daemon-http
/// for non-MCP clients (Unity / Unreal / Godot / Web).
///
/// Returns raw inner output — does NOT feed substrate perception. Use
/// `memory_save` for substrate-aware embedding flow.
pub struct EmbedTextTool;

impl EmbedTextTool {
    pub fn new() -> Self {
        Self
    }
}

impl Default for EmbedTextTool {
    fn default() -> Self {
        Self::new()
    }
}

#[async_trait]
impl McpTool for EmbedTextTool {
    fn name(&self) -> &'static str {
        "embed_text"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Raw sentence-encoder pass-through — returns the active \
                inner encoder's embedding (gte-multilingual-base, 768-d by default; \
                dimension follows the configured model, hash fallback on model-load \
                failure). Exposes Phase 2.1 inner encoder for external apps (e.g. \
                game NPC AI, custom indexers) that need encoder semantics WITHOUT \
                feeding v22 substrate perception. Companion HTTP route POST /embed \
                on daemon-http for non-MCP clients."
                .into(),
            input_schema: json!({
                "type": "object",
                "required": ["text"],
                "properties": {
                    "text": {
                        "type": "string",
                        "description": "Text to encode. Empty input returns zero/default vector of dim()."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let text = args.get("text").and_then(|v| v.as_str()).unwrap_or("");
        let backend = build_raw_encoder();
        let vec = backend.embed(text);
        Ok(ToolResult::json_text(&json!({
            "embedding": vec,
            "backend": backend.name(),
            "dim": backend.dim(),
        })))
    }
}

// ===========================================================================
//                  Warp URI tools (W4 — DESIGN-warp-first-agent-shell)
// ===========================================================================

fn warp_resolve_tab_window_path(raw: Option<&str>) -> Result<String> {
    match raw.filter(|s| !s.is_empty()) {
        Some(p) => Ok(resolve_cwd(Some(p))?.display().to_string()),
        None => Ok(resolve_cwd(None)?.display().to_string()),
    }
}

pub struct WarpOpenTabTool {
    hub: Hub,
}

impl WarpOpenTabTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}

#[async_trait]
impl McpTool for WarpOpenTabTool {
    fn name(&self) -> &'static str {
        "warp_open_tab"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: "Open a new Warp tab via URI scheme and return the new session's UUID. \
                 Polls terminal_list for up to 3 s to detect the newly registered session. \
                 Optional `path` sets initial cwd (defaults to bridge process cwd). \
                 Returns `session_id` (string) when detected, null otherwise."
                .into(),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "path": {
                        "type": "string",
                        "description": "Directory for ?path= (absolute or relative); omit for current cwd."
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let raw = args.get("path").and_then(|v| v.as_str());
        let cwd = warp_resolve_tab_window_path(raw)?;
        let uri = warp_scheme_new_tab(Some(&cwd));

        // Snapshot existing sessions so we can detect the new one.
        let before: std::collections::HashSet<String> = if let Some(term) = &self.hub.terminal {
            term.list_panes()
                .await
                .unwrap_or_default()
                .into_iter()
                .map(|p| p.id.to_string())
                .collect()
        } else {
            std::collections::HashSet::new()
        };

        dispatch_warp_scheme_uri(&uri)
            .await
            .map_err(|e| ab_core::Error::Backend(format!("warp_open_tab: {e}")))?;

        // Poll up to 3 s (20 × 150 ms) for a session UUID that was not in `before`.
        let new_session_id: Option<String> = if let Some(term) = &self.hub.terminal {
            let mut found = None;
            for _ in 0..20 {
                tokio::time::sleep(Duration::from_millis(150)).await;
                if let Ok(panes) = term.list_panes().await {
                    if let Some(p) = panes
                        .into_iter()
                        .find(|p| !before.contains(&p.id.to_string()))
                    {
                        found = Some(p.id.to_string());
                        break;
                    }
                }
            }
            found
        } else {
            None
        };

        Ok(ToolResult::json_text(&json!({
            "status": "ok",
            "uri": uri,
            "session_id": new_session_id,
            "detected": new_session_id.is_some()
        })))
    }
}

