pub struct CodebaseCallsTool {
    hub: Hub,
}
impl CodebaseCallsTool {
    pub fn new(hub: Hub) -> Self {
        Self { hub }
    }
}
#[async_trait]
impl McpTool for CodebaseCallsTool {
    fn name(&self) -> &'static str {
        "codebase_calls"
    }
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: self.name().into(),
            description: mcp_schema_description(
                "Query the codebase call-graph table built by \
                 codebase_index. Returns one row per call expression matching \
                 the given `callee` and/or `caller` substring (LIKE). Use to \
                 answer 'who calls X' (set `callee`) or 'what does Y call' \
                 (set `caller`) without re-walking source. At least one of \
                 `callee` / `caller` is required. Method calls appear with \
                 a leading dot (e.g. `.collect`). Supports Rust, Python, \
                 TypeScript/JavaScript, and Go. Run codebase_index first if \
                 no results appear.",
                "Prefer Codex native file/search tools for simple grep-style questions; use \
                 this when the indexed call graph provides better structured answers than \
                 live text search.",
            ),
            input_schema: json!({
                "type": "object",
                "properties": {
                    "callee": {
                        "type": "string",
                        "description": "Substring matched against the called name (e.g. 'SqliteStore::new' or '.collect')."
                    },
                    "caller": {
                        "type": "string",
                        "description": "Substring matched against the enclosing function (e.g. 'Foo::bar' or '<Foo as Bar>::baz')."
                    },
                    "file_filter": {
                        "type": "string",
                        "description": "Optional substring matched against file_path."
                    },
                    "root_path": {
                        "type": "string",
                        "description": "Optional root directory to restrict results to a specific index."
                    },
                    "limit": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": 500,
                        "default": 50
                    }
                }
            }),
        }
    }
    async fn execute(&self, args: Value, _ctx: &ToolContext) -> Result<ToolResult> {
        let store = match &self.hub.store {
            Some(s) => s.clone(),
            None => return Ok(ToolResult::error("no store configured")),
        };
        let callee = args
            .get("callee")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty())
            .map(|s| s.to_string());
        let caller = args
            .get("caller")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty())
            .map(|s| s.to_string());
        if callee.is_none() && caller.is_none() {
            return Ok(ToolResult::error(
                "at least one of 'callee' or 'caller' is required",
            ));
        }
        let file_filter = args
            .get("file_filter")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty())
            .map(|s| s.to_string());
        let root_path = args
            .get("root_path")
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty())
            .map(|s| s.to_string());
        let limit = args
            .get("limit")
            .and_then(|v| v.as_u64())
            .unwrap_or(50)
            .min(500) as u32;

        match store
            .codebase_calls_for(
                callee.as_deref(),
                caller.as_deref(),
                file_filter.as_deref(),
                root_path.as_deref(),
                limit,
            )
            .await
        {
            Ok(hits) => Ok(ToolResult::json_text(
                &serde_json::to_value(hits).unwrap_or(Value::Null),
            )),
            Err(e) => Ok(ToolResult::error(&format!("codebase_calls failed: {e}"))),
        }
    }
}

